import { describe, expect, test } from "bun:test"
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from "node:fs"
import os from "node:os"
import path from "node:path"

import { resolveCodeIntelRootFrom } from "./code-intel-root"

describe("resolveCodeIntelRootFrom", () => {
  test("returns cwd when argus-search.json exists in cwd", () => {
    const tmp = mkdtempSync(path.join(os.tmpdir(), "argus-root-cwd-"))
    try {
      writeFileSync(path.join(tmp, "argus-search.json"), "{}", "utf8")
      expect(resolveCodeIntelRootFrom(tmp)).toBe(tmp)
    } finally {
      rmSync(tmp, { recursive: true, force: true })
    }
  })

  test("walks up to parent when config is not in cwd", () => {
    const tmp = mkdtempSync(path.join(os.tmpdir(), "argus-root-parent-"))
    const nested = path.join(tmp, "apps", "web")
    try {
      mkdirSync(nested, { recursive: true })
      writeFileSync(path.join(tmp, "argus-search.json"), "{}", "utf8")
      expect(resolveCodeIntelRootFrom(nested)).toBe(tmp)
    } finally {
      rmSync(tmp, { recursive: true, force: true })
    }
  })

  test("throws when config cannot be found", () => {
    const tmp = mkdtempSync(path.join(os.tmpdir(), "argus-root-missing-"))
    try {
      expect(() => resolveCodeIntelRootFrom(tmp)).toThrow(
        "Could not locate argus-search.json",
      )
    } finally {
      rmSync(tmp, { recursive: true, force: true })
    }
  })
})

import { describe, expect, mock, test } from "bun:test"

type ApiLogHandlerArgs = {
  logger: {
    set: (context: Record<string, unknown>) => void
  }
  requestId: string
}

type ApiLogHandlerResult = {
  response: Response
  status: number
  outcome?: string
}

type RunWithApiRequestLogArgs = {
  request: Request
  path: string
  event: string
  handler: (args: ApiLogHandlerArgs) => Promise<ApiLogHandlerResult>
}

const loadRouteModule = async (options?: { userId?: string | null }) => {
  const runWithApiRequestLog = mock(async ({ handler }: RunWithApiRequestLogArgs) => {
    const logger = {
      set: (context: Record<string, unknown>) => {
        void context
      },
    }
    const result = await handler({ logger, requestId: "req_1" })
    return result.response
  })

  const getSessionUserId = mock(async () =>
    options?.userId === undefined ? "user-1" : options.userId,
  )

  const values = mock(async () => undefined)
  const insert = mock(() => ({ values }))

  mock.module("@/lib/utils/logger", () => ({
    runWithApiRequestLog,
  }))
  mock.module("@/lib/session", () => ({
    getSessionUserId,
    getSession: async () => ({ user: { id: await getSessionUserId() } }),
    getSessionAccess: async () => ({
      session: { user: { id: await getSessionUserId() } },
      isAlphaDenied: false,
    }),
  }))
  mock.module("@/lib/db", () => ({ db: { insert } }))
  mock.module("@/lib/db/schema", () => ({
    analyticsUserActivityEvents: { __table: "analytics_user_activity_events" },
    analyticsCodeMetricSnapshots: { __table: "analytics_code_metric_snapshots" },
  }))

  const routeModule = await import(`./route?cacheBust=${Math.random().toString(36).slice(2)}`)
  return {
    POST: routeModule.POST as (request: Request) => Promise<Response>,
    values,
  }
}

describe("analytics track route", () => {

test("returns 401 when unauthenticated", async () => {
  const { POST, values } = await loadRouteModule({ userId: null })

  const response = await POST(new Request("http://localhost/api/analytics/track", { method: "POST" }))
  const body = await response.json()

  expect(response.status).toBe(401)
  expect(body).toEqual({ error: "Unauthorized" })
  expect(values).toHaveBeenCalledTimes(0)
})

test("validates command_used command field", async () => {
  const { POST, values } = await loadRouteModule()

  const response = await POST(
    new Request("http://localhost/api/analytics/track", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ event: "command_used" }),
    }),
  )
  const body = await response.json()

  expect(response.status).toBe(400)
  expect(body).toEqual({ error: "command is required for command_used." })
  expect(values).toHaveBeenCalledTimes(0)
})

  test("persists a feature_opened event", async () => {
    const { POST, values } = await loadRouteModule()

    const response = await POST(
      new Request("http://localhost/api/analytics/track", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          event: "feature_opened",
          feature: "/analytics",
          sessionId: "session-1",
        }),
      }),
    )
    const body = await response.json()

    expect(response.status).toBe(200)
    expect(body).toEqual({ ok: true })
    expect(values).toHaveBeenCalledWith({
      userId: "user-1",
      event: "feature_opened",
      feature: "/analytics",
      command: undefined,
      sessionId: "session-1",
      durationMs: undefined,
      metadata: undefined,
    })
  })
})

"use client"

import { useTheme } from "next-themes"
import { useMemo } from "react"

import type { MergeRequestDiffPanelProps } from "../merge-request-diff-panel"
import {
  DEFAULT_WORKER_COUNT,
  DIFF_CACHE_SIZE,
  DIFF_THEME,
  type DiffStyle,
  type DiffThemeMode,
} from "../merge-request-diff-viewer.utils"

type MergeRequestDiffRenderingOptions = {
  diffThemeMode: DiffThemeMode
  diffStyle: DiffStyle
  wrapLines: boolean
  showLineNumbers: boolean
}

type MergeRequestDiffRenderingState = Pick<
  MergeRequestDiffPanelProps,
  "effectiveDiffThemeType" | "diffOptions" | "poolOptions" | "highlighterOptions"
>

export function useMergeRequestDiffRendering({
  diffThemeMode,
  diffStyle,
  wrapLines,
  showLineNumbers,
}: MergeRequestDiffRenderingOptions): MergeRequestDiffRenderingState {
  const { resolvedTheme } = useTheme()
  const effectiveDiffThemeType: "system" | "light" | "dark" = useMemo(() => {
    if (diffThemeMode !== "system") {
      return diffThemeMode
    }

    if (resolvedTheme === "dark" || resolvedTheme === "argus-dark") {
      return "dark"
    }
    if (resolvedTheme === "light" || resolvedTheme === "argus-light") {
      return "light"
    }

    return "system"
  }, [diffThemeMode, resolvedTheme])

  const workerPoolSize = useMemo(() => {
    if (typeof navigator === "undefined") {
      return DEFAULT_WORKER_COUNT
    }

    const cores = navigator.hardwareConcurrency || DEFAULT_WORKER_COUNT
    return Math.max(2, Math.min(8, cores - 1))
  }, [])

  const diffOptions = useMemo(
    () => ({
      diffStyle,
      disableFileHeader: true,
      overflow: (wrapLines ? "wrap" : "scroll") as "wrap" | "scroll",
      disableLineNumbers: !showLineNumbers,
      lineDiffType: "word" as const,
      diffIndicators: "bars" as const,
      hunkSeparators: "line-info" as const,
      expansionLineCount: 20,
      tokenizeMaxLineLength: 1500,
      theme: DIFF_THEME,
      themeType: effectiveDiffThemeType,
    }),
    [diffStyle, showLineNumbers, wrapLines, effectiveDiffThemeType],
  )

  const poolOptions = useMemo(
    () => ({
      workerFactory: () =>
        new Worker(
          new URL("@pierre/diffs/worker/worker.js", import.meta.url),
        ),
      poolSize: workerPoolSize,
      totalASTLRUCacheSize: DIFF_CACHE_SIZE,
    }),
    [workerPoolSize],
  )

  const highlighterOptions = useMemo(
    () => ({
      theme: DIFF_THEME,
      lineDiffType: "word" as const,
      tokenizeMaxLineLength: 1500,
    }),
    [],
  )

  return {
    effectiveDiffThemeType,
    diffOptions,
    poolOptions,
    highlighterOptions,
  }
}

]

