const formatShortcutLabel = (shortcut?: PaletteShortcut) => {
  if (!shortcut) {
    return undefined
  }

  const tokens: string[] = []
  if (shortcut.mod) {
    tokens.push("⌘")
  }
  if (shortcut.shift) {
    tokens.push("⇧")
  }
  if (shortcut.alt) {
    tokens.push("⌥")
  }
  tokens.push(shortcut.key.toUpperCase())

  return tokens.join("+")
}

const doesShortcutMatch = (
  event: globalThis.KeyboardEvent,
  shortcut: PaletteShortcut,
) => {
  if (event.key.toLowerCase() !== shortcut.key.toLowerCase()) {
    return false
  }
  if (shortcut.mod) {
    if (!event.metaKey && !event.ctrlKey) {
      return false
    }
  } else if (event.metaKey || event.ctrlKey) {
    return false
  }
  if (Boolean(shortcut.shift) !== event.shiftKey) {
    return false
  }
  if (Boolean(shortcut.alt) !== event.altKey) {
    return false
  }
  return true
}

const createChatMessageId = () =>
  typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
    ? crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(36).slice(2)}`

const getChatErrorMessage = (payload: PaletteChatResponsePayload | null, fallback: string) => {
  if (typeof payload?.error === "string" && payload.error.trim().length > 0) {
    return payload.error.trim()
  }
  return fallback
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value)

const normalizeInstanceKey = (instanceUrl: string) => {
  const trimmed = instanceUrl.trim()
  if (!trimmed) {
    return ""
  }

  try {
    const parsed = new URL(trimmed)
    return parsed.origin.toLowerCase()
  } catch {
    return trimmed.toLowerCase().replace(/\/+$/, "")
  }
}

const getFreshDynamicCommandsCache = () => {
  if (!dynamicCommandsCacheEntry) {
    return null
  }

  if (dynamicCommandsCacheEntry.expiresAt <= Date.now()) {
    dynamicCommandsCacheEntry = null
    return null
  }

  return dynamicCommandsCacheEntry.commands
}

const setDynamicCommandsCache = (commands: PaletteCommand[]) => {
  dynamicCommandsCacheEntry = {
    expiresAt: Date.now() + DYNAMIC_COMMAND_CACHE_TTL_MS,
    commands,
  }
}

const toPaletteIntegrations = (payload: unknown): PaletteIntegration[] => {
  if (!isRecord(payload) || !Array.isArray(payload.data)) {
    return []
  }

  return payload.data.flatMap((row) => {
    if (!isRecord(row)) {
      return []
    }

    const id = typeof row.id === "string" ? row.id.trim() : ""
    const instanceUrl = typeof row.instanceUrl === "string" ? row.instanceUrl.trim() : ""
    const projectId = typeof row.projectId === "string" ? row.projectId.trim() : ""
    const projectPath = typeof row.projectPath === "string" ? row.projectPath.trim() : ""
    const projectName = typeof row.projectName === "string" ? row.projectName.trim() : ""
    if (!id || !instanceUrl || !projectId || !projectPath) {
      return []
    }

    return [{
      id,
      instanceUrl,
      projectId,
      projectPath,
      projectName: projectName || projectPath,
    }]
  })
}

const toPaletteMergeRequests = (payload: unknown): PaletteMergeRequest[] => {
  if (!isRecord(payload) || !Array.isArray(payload.data)) {
    return []
  }

  return payload.data.flatMap((row) => {
    if (!isRecord(row)) {
      return []
    }

    const iid = typeof row.iid === "string" ? row.iid.trim() : ""
    const title = typeof row.title === "string" ? row.title.trim() : ""
    const projectId = typeof row.projectId === "string" ? row.projectId.trim() : ""
    if (!iid || !title || !projectId) {
      return []
    }

    return [{
      iid,
      title,
      projectId,
    }]
  })
}

const buildInstanceSeeds = (integrations: PaletteIntegration[]): PaletteInstanceSeed[] => {
  const seedsByKey = new Map<string, PaletteInstanceSeed>()

  for (const integration of integrations) {
    const instanceKey = normalizeInstanceKey(integration.instanceUrl)
    if (!instanceKey || seedsByKey.has(instanceKey)) {
      continue
    }

    seedsByKey.set(instanceKey, {
      instanceUrl: integration.instanceUrl,
      integrationId: integration.id,
    })
  }

  return [...seedsByKey.values()]
}

const buildProjectCommands = (integrations: PaletteIntegration[]) =>
  integrations
    .slice(0, PROJECT_COMMAND_LIMIT)
    .map((integration) => ({
      id: `project-${integration.id}`,
      label: integration.projectName,
      description: integration.projectPath,
      href: buildRepoPath(integration),
      group: "Projects",
      icon: () => <FolderGit2 className="size-4" />,
    }) satisfies PaletteCommand)

const buildMergeRequestCommands = (
  integrations: PaletteIntegration[],
  mergeRequestsByInstance: Map<string, PaletteMergeRequest[]>,
) => {
  const integrationByScope = new Map<string, PaletteIntegration>()
  for (const integration of integrations) {
    integrationByScope.set(
      `${normalizeInstanceKey(integration.instanceUrl)}::${integration.projectId}`,
      integration,
    )
  }

  const commands: PaletteCommand[] = []
  const seen = new Set<string>()

  for (const [instanceKey, mergeRequests] of mergeRequestsByInstance.entries()) {
    for (const mergeRequest of mergeRequests) {
      const integration = integrationByScope.get(`${instanceKey}::${mergeRequest.projectId}`)
      if (!integration) {
        continue
      }

      const href = buildRepoMergeRequestPath(integration, mergeRequest.iid)
      if (seen.has(href)) {
        continue
      }

      seen.add(href)
      commands.push({
        id: `mr-${integration.id}-${mergeRequest.iid}`,
        label: `!${mergeRequest.iid} ${mergeRequest.title}`,
        description: integration.projectPath,
        href,
        group: "Merge Requests",
        icon: () => <GitPullRequest className="size-4" />,
      })

      if (commands.length >= MERGE_REQUEST_COMMAND_LIMIT) {
        return commands
      }
    }
  }

  return commands
}

export { prefetchRouteOnce } from "@/lib/navigation/perf-navigation"

export function CommandPalette() {
  const router = useRouter()
  const pathname = usePathname()
  const [isOpen, setIsOpen] = useState(false)
  const [query, setQuery] = useState("")

const [chatMessages, setChatMessages] = useState<PaletteChatMessage[]>([])
const [isChatPending, setIsChatPending] = useState(false)
const [chatError, setChatError] = useState("")
const [dynamicCommands, setDynamicCommands] = useState<PaletteCommand[]>([])
const [isDynamicCommandsPending, setIsDynamicCommandsPending] = useState(false)
const chatViewportRef = useRef<HTMLDivElement | null>(null)
const prefetchedCommandHrefsRef = useRef<Set<string>>(new Set())

const loadDynamicCommands = useCallback(async () => {
  const cached = getFreshDynamicCommandsCache()
  if (cached) {
    setDynamicCommands(cached)
    return
  }

  setIsDynamicCommandsPending(true)

  try {
    const integrationsResponse = await fetch("/api/gitlab/integrations")
    const integrationsPayload = await integrationsResponse.json().catch(() => null)
    if (!integrationsResponse.ok) {
      throw new Error("Could not load connected repositories.")
    }

    const integrations = toPaletteIntegrations(integrationsPayload)
    if (integrations.length === 0) {
      setDynamicCommands([])
      setDynamicCommandsCache([])
      return
    }

    const projectCommands = buildProjectCommands(integrations)
    const instanceSeeds = buildInstanceSeeds(integrations)

const mergeRequestResponses = await Promise.allSettled(
  instanceSeeds.map(async (seed) => {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "recent-merge-requests",
        instanceUrl: seed.instanceUrl,
        integrationId: seed.integrationId,
        perPage: MERGE_REQUESTS_PER_INSTANCE_LIMIT,
      }),
    })

    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      return {
        instanceKey: normalizeInstanceKey(seed.instanceUrl),
        mergeRequests: [],
      }
    }

    return {
      instanceKey: normalizeInstanceKey(seed.instanceUrl),
      mergeRequests: toPaletteMergeRequests(payload),
    }
  }),
)

const mergeRequestsByInstance = new Map<string, PaletteMergeRequest[]>()
for (const result of mergeRequestResponses) {
  if (result.status === "rejected") {
    continue
  }
  if (!result.value.instanceKey) {
    continue
  }

  mergeRequestsByInstance.set(result.value.instanceKey, result.value.mergeRequests)
}

const mergeRequestCommands = buildMergeRequestCommands(integrations, mergeRequestsByInstance)
const nextDynamicCommands = [...projectCommands, ...mergeRequestCommands]
setDynamicCommands(nextDynamicCommands)

    setDynamicCommandsCache(nextDynamicCommands)
  } catch {
    setDynamicCommands([])
  } finally {
    setIsDynamicCommandsPending(false)
  }
}, [])

const commands = useMemo(
  () => [...BASE_COMMANDS, ...SETTINGS_COMMANDS, ...dynamicCommands]
    .filter((command) => !command.href || command.href !== pathname),
  [dynamicCommands, pathname],
)

const groupedCommands = useMemo(() => {
  const grouped = new Map<PaletteCommandGroup, PaletteCommand[]>()
  for (const group of COMMAND_GROUP_ORDER) {
    grouped.set(group, [])
  }

  for (const command of commands) {
    grouped.get(command.group)?.push(command)
  }

  return grouped
}, [commands])

const visibleGroups = useMemo(
  () =>
    COMMAND_GROUP_ORDER.filter((group) => (groupedCommands.get(group)?.length ?? 0) > 0),
  [groupedCommands],
)

const hasCommandMatchForQuery = useMemo(() => {
  const normalizedQuery = query.trim().toLowerCase()
  if (!normalizedQuery) {
    return true
  }

  return commands.some((command) =>
    `${command.id} ${command.label} ${command.description}`
      .toLowerCase()
      .includes(normalizedQuery),
  )
}, [commands, query])

const prefetchCommandHref = useCallback((href?: string) => {
  prefetchRouteOnce({
    href,
    prefetchedHrefs: prefetchedCommandHrefsRef.current,
    prefetch: router.prefetch,
  })
}, [router])

const runCommand = useCallback(
  (command: PaletteCommand) => {
    trackAnalyticsEvent({
      event: "command_used",
      command: command.id,
      feature: pathname,
      metadata: {
        group: command.group,
        hasHref: Boolean(command.href),
      },
    })

    if (command.href) {
      prefetchCommandHref(command.href)
      markRouteNavigationStart({
        href: command.href,
        source: "command_palette",
      })
      router.push(command.href)
    } else {
      command.action?.()
    }
    setIsOpen(false)
  },
  [pathname, prefetchCommandHref, router],
)

const submitPaletteChat = useCallback(
  async (questionText: string) => {
    const question = questionText.trim()
    if (!question || isChatPending) {
      return
    }

    const userMessage: PaletteChatMessage = {
      id: createChatMessageId(),
      role: "user",
      content: question,
    }
    const priorMessages = chatMessages.slice(-MAX_CHAT_HISTORY_MESSAGES)

    setChatMessages((current) => [...current, userMessage].slice(-24))
    setIsChatPending(true)
    setChatError("")
    setQuery("")

    trackAnalyticsEvent({
      event: "command_used",
      command: "palette_chat_message",
      feature: pathname,
      metadata: {
        historyLength: priorMessages.length,
      },
    })

try {
  const aiSettings = readAiClientSettingsFromStorage()
  const response = await fetch("/api/command-palette/chat", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      question,
      pathname,
      history: priorMessages.map((message) => ({
        role: message.role,
        content: message.content,
      })),
      apiUrl: aiSettings.apiUrl,
      model: aiSettings.model,
      token: aiSettings.token,
    }),
  })

  const payload = (await response.json().catch(() => null)) as PaletteChatResponsePayload | null
  if (!response.ok) {
    throw new Error(
      getChatErrorMessage(payload, "Could not get an answer from Argus AI."),
    )
  }

  if (!payload || typeof payload.answer !== "string" || payload.answer.trim().length === 0) {
    throw new Error("Argus AI returned an empty response.")
  }

  const assistantMessage: PaletteChatMessage = {
    id: createChatMessageId(),
    role: "assistant",
    content: payload.answer.trim(),
  }
  setChatMessages((current) => [...current, assistantMessage].slice(-24))
} catch (error) {
  const message =
    error instanceof Error && error.message.trim().length > 0
      ? error.message
      : "Could not get an answer from Argus AI."
  setChatError(message)
} finally {
  setIsChatPending(false)
}

  },
  [chatMessages, isChatPending, pathname],
)

const renderCommandGroup = React.useCallback(
  (group: PaletteCommandGroup) => {
    const items = groupedCommands.get(group) ?? []
    if (items.length === 0) {
      return null
    }

    return (
      <CommandGroup key={group} heading={group}>
        {items.map((command) => (
          <CommandItem
            key={command.id}
            value={`${command.id} ${command.label} ${command.description}`}
            onSelect={() => runCommand(command)}
            onPointerMove={() => prefetchCommandHref(command.href)}
            onFocus={() => prefetchCommandHref(command.href)}
            className="gap-2"
          >
            <command.icon />
            <span>{command.label}</span>
            {command.shortcut ? (
              <CommandShortcut>{formatShortcutLabel(command.shortcut)}</CommandShortcut>
            ) : null}
          </CommandItem>
        ))}
      </CommandGroup>
    )
  },
  [groupedCommands, prefetchCommandHref, runCommand],
)

useEffect(() => {
  if (!isOpen) {
    setQuery("")
  }
}, [isOpen])

useEffect(() => {
  if (!isOpen) {
    return
  }

  void loadDynamicCommands()
}, [isOpen, loadDynamicCommands])

useEffect(() => {
  if (!isOpen) {
    return
  }

  for (const command of commands) {
    prefetchCommandHref(command.href)
  }
}, [commands, isOpen, prefetchCommandHref])

useEffect(() => {
  if (!isOpen) {
    return
  }

  const viewport = chatViewportRef.current
  if (!viewport) {
    return
  }
  viewport.scrollTop = viewport.scrollHeight
}, [chatError, chatMessages, isChatPending, isOpen])

const handleCommandKeyDown = React.useCallback(
  (event: React.KeyboardEvent) => {
    if (!isOpen) {
      return
    }

    if (!(event.key.length === 1) && !["Escape", "ArrowDown", "ArrowUp", "Enter"].includes(event.key)) {
      return
    }

    const target = event.target as EventTarget | null
    if (!(target instanceof Element)) {
      return
    }

    const command = commands.find(
      (candidate) =>
        candidate.shortcut ? doesShortcutMatch(event.nativeEvent, candidate.shortcut) : false,
    )

    if (!command) {
      return
    }

    event.preventDefault()
    runCommand(command)
  },
  [commands, isOpen, runCommand],
)

const handleCommandKeyDownCapture = React.useCallback(
  (event: React.KeyboardEvent) => {
    if (!isOpen) {
      return
    }

    if (event.key !== "Enter") {
      return
    }
    if (event.nativeEvent.isComposing) {
      return
    }
    if (!query.trim()) {
      return
    }

    const shouldSubmit =
      event.shiftKey || (!event.shiftKey && !hasCommandMatchForQuery)
    if (!shouldSubmit) {
      return
    }

    event.preventDefault()
    event.stopPropagation()
    void submitPaletteChat(query)
  },
  [hasCommandMatchForQuery, isOpen, query, submitPaletteChat],
)

