const formatDuration = (durationMs: number | null) => {
  if (durationMs === null || durationMs < 0) {
    return "n/a"
  }

  const seconds = Math.floor(durationMs / 1000)
  if (seconds < 60) {
    return `${seconds}s`
  }

  const minutes = Math.floor(seconds / 60)
  const remainderSeconds = seconds % 60
  return `${minutes}m ${remainderSeconds}s`
}

const joinParts = (parts: Array<string | null | undefined>) =>
  parts.filter((part) => typeof part === "string" && part.trim().length > 0).join(" · ")

const describeIndexingMetrics = (value: unknown) => {
  const metrics = asRecord(value)
  if (!metrics) {
    return null
  }

  const filesProcessed = asInteger(metrics.filesProcessed)
  const failures = asInteger(metrics.failures)
  const embeddingApiCalls = asInteger(metrics.embeddingApiCalls)
  const embeddingTotalTokens = asInteger(metrics.embeddingTotalTokens)
  const embeddingCostUsd = asUsd(metrics.embeddingCostUsd)
  const durationMs = asInteger(metrics.durationMs)

  const summary = joinParts([
    filesProcessed !== null ? `${filesProcessed} file(s)` : null,
    embeddingApiCalls !== null ? `${embeddingApiCalls} embedding call(s)` : null,
    embeddingTotalTokens !== null ? `${embeddingTotalTokens} tok` : null,
    failures !== null ? `${failures} failure(s)` : null,
    embeddingCostUsd !== null ? `$${embeddingCostUsd.toFixed(4)}` : null,
    durationMs !== null ? `${formatDuration(durationMs)}` : null,
  ])

  return summary.length > 0 ? summary : null
}

const readRunStats = (run: IndexRun | null) => {
  const stats = run?.stats ?? null
  return {
    filesProcessed: asInteger(stats?.filesProcessed),
    filesScanned: asInteger(stats?.filesScanned),
    filesFetched: asInteger(stats?.filesFetched),
    chunksUpserted: asInteger(stats?.chunksUpserted),
    embeddingApiCalls: asInteger(stats?.embeddingApiCalls),
    embeddingPromptTokens: asInteger(stats?.embeddingPromptTokens),
    embeddingTotalTokens: asInteger(stats?.embeddingTotalTokens),
    embeddingCostUsd: asUsd(stats?.embeddingCostUsd),
    modeFallback: asString(stats?.modeFallback),
    modeFallbackReason: asString(stats?.modeFallbackReason),
  }
}

const liveLogContext = (entry: LiveIndexerLog) => {
  const payload = asRecord(entry.payload)
  if (!payload) {
    return "—"
  }

  const context = joinParts([
    toShortId(payload.runId) ? `run ${toShortId(payload.runId)}` : null,
    toShortId(payload.jobId) ? `job ${toShortId(payload.jobId)}` : null,
    toShortId(payload.batchId) ? `batch ${toShortId(payload.batchId)}` : null,
    asString(payload.stage) ? `stage=${asString(payload.stage)}` : null,
    asString(payload.branch),
    asString(payload.filePath),
  ])
  return context || "—"
}

const liveLogMessage = (entry: LiveIndexerLog) => {
  const payload = asRecord(entry.payload)
  if (!payload) {
    return ""
  }

  if (typeof payload.errorMessage === "string" && payload.errorMessage.trim().length > 0) {
    return payload.errorMessage
  }

if (entry.event === "indexer.job.processing") {
  return joinParts([
    asString(payload.jobType) ? `${asString(payload.jobType)} job` : "job",
    asString(payload.outcome) ? `outcome=${asString(payload.outcome)}` : null,
    asString(payload.runMode) ? `mode=${asString(payload.runMode)}` : null,
    asInteger(payload.attempts) !== null ? `attempt=${asInteger(payload.attempts)}` : null,
    asString(payload.duration),
  ])
}

if (entry.event === "indexer.run.processing") {
  const outcome = asString(payload.outcome)
  if (outcome === "progress") {
    const progressStats = describeIndexingMetrics(payload.progressStats)
    return joinParts([
      asString(payload.stepMessage),
      asString(payload.step) ? `step=${asString(payload.step)}` : null,
      progressStats,
    ])
  }

  return joinParts([
    outcome ? `outcome=${outcome}` : null,
    asString(payload.statusTransitionFrom) && asString(payload.statusTransitionTo)
      ? `transition=${asString(payload.statusTransitionFrom)}→${asString(payload.statusTransitionTo)}`
      : null,
    asString(payload.ingestMode) ? `mode=${asString(payload.ingestMode)}` : null,
    asString(payload.modeFallback)
      ? `fallback=${asString(payload.modeFallback)}${asString(payload.modeFallbackReason) ? `(${asString(payload.modeFallbackReason)})` : ""}`
      : null,
    asString(payload.gcStatus) ? `gc=${asString(payload.gcStatus)}` : null,
    describeIndexingMetrics(payload.indexingMetrics),
  ])
}

  if (entry.event === "indexer.batch.processing") {
    const summary = asRecord(payload.summary)
    const queueDepthAfter = asRecord(summary?.queueDepthAfter)
    return joinParts([
      asString(payload.outcome) ? `outcome=${asString(payload.outcome)}` : null,
      asInteger(summary?.claimed) !== null ? `runsClaimed=${asInteger(summary?.claimed)}` : null,
      asInteger(summary?.ready) !== null ? `ready=${asInteger(summary?.ready)}` : null,
      asInteger(summary?.failed) !== null ? `failed=${asInteger(summary?.failed)}` : null,
      asInteger(summary?.filesProcessed) !== null ? `files=${asInteger(summary?.filesProcessed)}` : null,
      asInteger(queueDepthAfter?.jobsPending) !== null
        ? `queuePending=${asInteger(queueDepthAfter?.jobsPending)}`
        : null,
      asInteger(queueDepthAfter?.jobsProcessing) !== null
        ? `queueProcessing=${asInteger(queueDepthAfter?.jobsProcessing)}`
        : null,
    ])
  }

  if (typeof payload.outcome === "string" && payload.outcome.trim().length > 0) {
    return `outcome=${payload.outcome}`
  }

  if (typeof payload.errorCode === "string" && payload.errorCode.trim().length > 0) {
    return `errorCode=${payload.errorCode}`
  }

  return ""
}

const branchNeedsReconcile = (branch: IndexBranch) => {
  if (branch.reconcile?.wasEnqueued) {
    return true
  }
  if (branch.reconcile?.headSha) {
    return branch.reconcile.headSha !== (branch.lastReadySha ?? null)
  }
  return false
}

export function IndexingConsole({
  initialIntegrationId = null,
  fixedIntegration = null,
}: IndexingConsoleProps) {

const router = useRouter()
const pathname = usePathname()
const searchParams = useSearchParams()
const integrationIdFromQuery = searchParams.get("integrationId") ?? ""
const [integrations, setIntegrations] = useState<GitLabIntegration[]>(
  fixedIntegration ? [fixedIntegration] : [],
)
const [selectedIntegrationId, setSelectedIntegrationId] = useState<string>(
  fixedIntegration?.id ?? initialIntegrationId ?? "",
)
const [runs, setRuns] = useState<IndexRun[]>([])
const [runsPagination, setRunsPagination] = useState<IndexRunsPayload["pagination"] | null>(null)
const [queueSummary, setQueueSummary] = useState<IndexRunsPayload["queue"]>(null)
const [workerTelemetry, setWorkerTelemetry] = useState<IndexRunsPayload["worker"]>(null)
const [branches, setBranches] = useState<IndexBranch[]>([])
const [latestReconcile, setLatestReconcile] = useState<ReconcileSummary | null>(null)
const [isLoadingIntegrations, setIsLoadingIntegrations] = useState(!fixedIntegration)
const [isLoadingIndexing, setIsLoadingIndexing] = useState(false)
const [errorMessage, setErrorMessage] = useState("")
const [actionMessage, setActionMessage] = useState("")
const [lastRefreshedAt, setLastRefreshedAt] = useState<Date | null>(null)
const [reindexingKey, setReindexingKey] = useState<string | null>(null)
const [cancelingRunId, setCancelingRunId] = useState<string | null>(null)
const [startRunDialogOpen, setStartRunDialogOpen] = useState(false)
const [startRunBranch, setStartRunBranch] = useState("")

const [startRunConfigHash, setStartRunConfigHash] = useState("")
const [startRunError, setStartRunError] = useState("")
const [isStartingRun, setIsStartingRun] = useState(false)
const [recentlyQueuedKey, setRecentlyQueuedKey] = useState<string | null>(null)
const [progressTarget, setProgressTarget] = useState<ProgressTarget | null>(null)
const [progressDialogOpen, setProgressDialogOpen] = useState(false)
const [streamStatus, setStreamStatus] = useState<"idle" | "connecting" | "live" | "disconnected">("idle")
const [liveLogs, setLiveLogs] = useState<LiveIndexerLog[]>([])
const [liveLogStreamStatus, setLiveLogStreamStatus] = useState<"idle" | "connecting" | "live" | "disconnected">("idle")

const selectedIntegration = useMemo(() => {
  if (fixedIntegration) {
    return fixedIntegration
  }
  return integrations.find((integration) => integration.id === selectedIntegrationId) ?? null
}, [fixedIntegration, integrations, selectedIntegrationId])

const staleBranchCount = useMemo(
  () => branches.filter(branchNeedsReconcile).length,
  [branches],
)

const suggestedRunTarget = useMemo(() => {
  const preferredMain = branches.find((branch) => branch.branch === "main")
  if (preferredMain) {
    return {
      branch: preferredMain.branch,
      configHash: preferredMain.configHash,
    }
  }

  const firstBranch = branches[0]
  if (firstBranch) {
    return {
      branch: firstBranch.branch,
      configHash: firstBranch.configHash,
    }
  }

  const firstRun = runs[0]
  if (firstRun) {
    return {
      branch: firstRun.branch,
      configHash: firstRun.configHash,
    }
  }

  return {
    branch: "main",
    configHash: "",
  }
}, [branches, runs])

const progressBranch = useMemo(() => {
  if (!progressTarget) {
    return null
  }
  return (
    branches.find(
      (branch) =>
        branch.branch === progressTarget.branch &&
        branch.configHash === progressTarget.configHash,
    ) ?? null
  )
}, [branches, progressTarget])

const progressRun = useMemo(() => {
  if (!progressTarget) {
    return null
  }

  const branchLastRunId = progressBranch?.lastRun?.id
  if (branchLastRunId) {
    const byId = runs.find((run) => run.id === branchLastRunId)
    if (byId) {
      return byId
    }
  }

  return (
    runs.find(
      (run) =>
        run.branch === progressTarget.branch &&
        run.configHash === progressTarget.configHash,
    ) ?? null
  )
}, [progressBranch?.lastRun?.id, progressTarget, runs])

const progressRowKey = progressTarget
  ? buildBranchKey(progressTarget.branch, progressTarget.configHash)
  : null

const progressStatus = progressRun?.status ??
  progressBranch?.lastRun?.status ??
  (progressRowKey && progressRowKey === recentlyQueuedKey ? "planned" : null)
const progressErrorRaw = progressRun?.error ?? null
const progressError = useMemo(
  () => (progressErrorRaw ? describeRunError(progressErrorRaw) : null),
  [progressErrorRaw],
)
const progressIsQueueing = progressRowKey !== null && reindexingKey === progressRowKey
const progressRunId = progressRun?.id ?? null
const progressCanCancel = Boolean(progressRunId && progressStatus && RUN_ACTIVE_STATUSES.has(progressStatus))
const progressIsCancelling = progressRunId !== null && cancelingRunId === progressRunId

const pipelineStages = useMemo(
  () => buildPipelineStages(progressStatus),
  [progressStatus],
)

const progressRunStats = useMemo(
  () => readRunStats(progressRun),
  [progressRun],
)

const progressElapsedMs = useMemo(() => {
  if (!progressRun) {
    return null
  }
  const startedAt = parseTimestampMs(progressRun.createdAt)
  const updatedAt = parseTimestampMs(progressRun.updatedAt)
  if (startedAt === null || updatedAt === null) {
    return null
  }

  const endMs = RUN_ACTIVE_STATUSES.has(progressRun.status)
    ? Date.now()
    : updatedAt
  return Math.max(0, endMs - startedAt)
}, [progressRun])

const progressFilesFromRun = progressRunStats.filesProcessed ??
  progressRunStats.filesScanned ??
  progressRunStats.filesFetched

const progressLogs = useMemo(() => {
  if (!progressTarget) {
    return []
  }

  const runId = progressRun?.id ?? null
  const filtered = liveLogs.filter((entry) => {
    const payload = asRecord(entry.payload)
    if (!payload) {
      return false
    }

    const payloadRunId = asString(payload.runId)
    if (runId && payloadRunId === runId) {
      return true
    }

    const payloadBranch = asString(payload.branch)
    if (payloadBranch !== progressTarget.branch) {
      return false
    }

    const payloadConfigHash = asString(payload.configHash)
    if (payloadConfigHash && payloadConfigHash !== progressTarget.configHash) {
      return false
    }

    return true
  })

  return filtered.slice(-PROGRESS_LOG_VIEW_LIMIT).reverse()
}, [liveLogs, progressRun?.id, progressTarget])

const latestProgressSnapshot = useMemo(() => {
  for (const entry of progressLogs) {
    const payload = asRecord(entry.payload)
    if (!payload) {
      continue
    }

    if (asString(payload.outcome) !== "progress") {
      continue
    }

    return {
      timestamp: entry.timestamp,
      stage: asString(payload.stage),
      step: asString(payload.step),
      message: asString(payload.stepMessage),
      filePath: asString(payload.filePath),
      stats: asRecord(payload.progressStats),
    }
  }

  return null
}, [progressLogs])

const progressFilesProcessed = useMemo(() => {
  if (progressFilesFromRun !== null) {
    return progressFilesFromRun
  }
  return (
    asInteger(latestProgressSnapshot?.stats?.filesProcessed) ??
    asInteger(latestProgressSnapshot?.stats?.filesScanned) ??
    asInteger(latestProgressSnapshot?.stats?.filesFetched)
  )
}, [latestProgressSnapshot?.stats, progressFilesFromRun])

const progressChunksUpserted = useMemo(() => {
  if (progressRunStats.chunksUpserted !== null) {
    return progressRunStats.chunksUpserted
  }
  return asInteger(latestProgressSnapshot?.stats?.chunksUpserted)
}, [latestProgressSnapshot?.stats, progressRunStats.chunksUpserted])

const progressElapsedDisplayMs = useMemo(() => {
  if (!progressStatus || !RUN_ACTIVE_STATUSES.has(progressStatus)) {
    return progressElapsedMs
  }

  for (const entry of progressLogs) {
    const payload = asRecord(entry.payload)
    if (!payload || asString(payload.outcome) !== "progress") {
      continue
    }

    const eventMs = parseTimestampMs(entry.timestamp) ?? parseTimestampMs(entry.createdAt)
    if (eventMs !== null) {
      return Math.max(0, Date.now() - eventMs)
    }
  }

  return progressElapsedMs
}, [progressElapsedMs, progressLogs, progressStatus])

const workerHealth = useMemo(() => {

if (workerTelemetry) {
  const heartbeatAgeMs = workerTelemetry.heartbeatAgeMs
  if (workerTelemetry.lastHeartbeatAt === null) {
    return {
      level: "offline" as const,
      label: "offline",
      message: "No worker heartbeat has been recorded yet.",
    }
  }

  if (!workerTelemetry.isOnline) {
    return {
      level: "offline" as const,
      label: "offline",
      message: `Last heartbeat ${formatAge(heartbeatAgeMs)} ago.`,
    }
  }

  return {
    level: "healthy" as const,
    label: "online",
    message: `Last heartbeat ${formatAge(heartbeatAgeMs)} ago.`,
  }
}

if (!queueSummary) {
  return {
    level: "unknown" as const,
    label: "unknown",
    message: "No queue telemetry yet.",
  }
}

const nowMs = Date.now()
const pending = queueSummary.pending
const processing = queueSummary.processing
const hasBacklog = pending + processing > 0
const oldestPendingAgeMs = (() => {
  const ts = parseTimestampMs(queueSummary.oldestPendingAt)
  return ts === null ? null : nowMs - ts
})()
const lastProcessedAgeMs = (() => {
  const ts = parseTimestampMs(queueSummary.lastProcessedAt)
  return ts === null ? null : nowMs - ts
})()
const hasRecentActivity = (
  lastProcessedAgeMs !== null &&
  lastProcessedAgeMs <= WORKER_RECENT_ACTIVITY_MS
)

  if (
    pending > 0 &&
    oldestPendingAgeMs !== null &&
    oldestPendingAgeMs >= WORKER_PENDING_STALE_MS &&
    !hasRecentActivity
  ) {
    return {
      level: "offline" as const,
      label: "likely offline",
      message: `Pending jobs oldest age: ${formatAge(oldestPendingAgeMs)}.`,
    }
  }

  if (hasBacklog) {
    return {
      level: "busy" as const,
      label: "active",
      message: `Queue backlog: pending ${pending}, processing ${processing}.`,
    }
  }

  if (hasRecentActivity) {
    return {
      level: "healthy" as const,
      label: "healthy",
      message: `Last processed ${formatAge(lastProcessedAgeMs)} ago.`,
    }
  }

  return {
    level: "unknown" as const,
    label: "unknown",
    message: "No recent processed jobs and no backlog.",
  }
}, [queueSummary, workerTelemetry])

const loadIntegrations = useCallback(async () => {
  if (fixedIntegration) {
    setIntegrations([fixedIntegration])
    setIsLoadingIntegrations(false)
    return
  }

  setIsLoadingIntegrations(true)
  try {
    const response = await fetch("/api/gitlab/integrations", {
      method: "GET",
      headers: { "content-type": "application/json" },
    })
    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, "Failed to load integrations."))
    }

    const records =
      payload &&
        typeof payload === "object" &&
        "data" in payload &&
        Array.isArray((payload as { data?: unknown }).data)
        ? (payload as { data: GitLabIntegration[] }).data
        : []

    setIntegrations(records)
  } catch (error) {
    setErrorMessage(error instanceof Error ? error.message : "Failed to load integrations.")
  } finally {
    setIsLoadingIntegrations(false)
  }
}, [fixedIntegration])

const loadIndexingData = useCallback(async (integrationId: string, quiet?: boolean) => {
  if (!quiet) {
    setIsLoadingIndexing(true)
  }

try {
  const [runsResponse, branchesResponse] = await Promise.all([
    fetch(`/api/gitlab/integrations/${integrationId}/index/runs?page=1&limit=20`, {
      method: "GET",
      headers: { "content-type": "application/json" },
    }),
    fetch(`/api/gitlab/integrations/${integrationId}/index/branches`, {
      method: "GET",
      headers: { "content-type": "application/json" },
    }),
  ])

  const [runsPayload, branchesPayload] = await Promise.all([
    runsResponse.json().catch(() => null),
    branchesResponse.json().catch(() => null),
  ])

  if (!runsResponse.ok) {
    throw new Error(extractErrorMessage(runsPayload, "Failed to load indexing runs."))
  }

  if (!branchesResponse.ok) {
    throw new Error(extractErrorMessage(branchesPayload, "Failed to load branch states."))
  }

  const typedRunsPayload = runsPayload as IndexRunsPayload
  const typedBranchesPayload = branchesPayload as IndexBranchesPayload

  setRuns(
    Array.isArray(typedRunsPayload.data)
      ? typedRunsPayload.data.flatMap((entry) => {
        const run = normalizeIndexRun(entry)
        return run ? [run] : []
      })
      : [],
  )
  setRunsPagination(typedRunsPayload.pagination ?? null)
  setQueueSummary(typedRunsPayload.queue ?? null)
  setWorkerTelemetry(typedRunsPayload.worker ?? null)
  setBranches(Array.isArray(typedBranchesPayload.data) ? typedBranchesPayload.data : [])

    setLatestReconcile(typedBranchesPayload.reconcile ?? typedRunsPayload.reconcile ?? null)
    setLastRefreshedAt(new Date())
    setErrorMessage("")
  } catch (error) {
    setErrorMessage(error instanceof Error ? error.message : "Failed to load indexing data.")
  } finally {
    if (!quiet) {
      setIsLoadingIndexing(false)
    }
  }
}, [])

const handleRefresh = useCallback(() => {
  if (!selectedIntegrationId) {
    return
  }
  setActionMessage("")
  void loadIndexingData(selectedIntegrationId)
}, [loadIndexingData, selectedIntegrationId])

const openProgressDialog = useCallback((branch: string, configHash: string) => {
  setProgressTarget({ branch, configHash })
  setProgressDialogOpen(true)
}, [])

const resolveConfigHashForBranch = useCallback((branch: string, configHash?: string) => {
  const explicit = configHash?.trim()
  if (explicit) {
    return explicit
  }

  const branchState = branches.find((entry) => entry.branch === branch)
  if (branchState) {
    return branchState.configHash
  }

  const latestRun = runs.find((entry) => entry.branch === branch)
  if (latestRun) {
    return latestRun.configHash
  }

  return "default-v1"
}, [branches, runs])

const handleReindex = useCallback(async (branch: string, configHash?: string) => {
  if (!selectedIntegrationId) {
    return false
  }
  const normalizedConfigHash = configHash?.trim() || undefined
  const resolvedConfigHash = resolveConfigHashForBranch(branch, normalizedConfigHash)
  const rowKey = buildBranchKey(branch, resolvedConfigHash)
  setReindexingKey(rowKey)
  setActionMessage("")
  try {
    const response = await fetch(
      `/api/gitlab/integrations/${selectedIntegrationId}/index/reindex`,
      {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(
          normalizedConfigHash
            ? {
              branch,
              configHash: normalizedConfigHash,
            }
            : {
              branch,
            },
        ),
      },
    )
    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, `Failed to enqueue reindex for ${branch}.`))
    }
    setActionMessage(`Reindex queued for ${branch}.`)
    setRecentlyQueuedKey(rowKey)
    openProgressDialog(branch, resolvedConfigHash)
    await loadIndexingData(selectedIntegrationId, true)
    return true
  } catch (error) {
    setErrorMessage(error instanceof Error ? error.message : "Failed to enqueue reindex job.")
    return false
  } finally {
    setReindexingKey(null)
  }
}, [loadIndexingData, openProgressDialog, resolveConfigHashForBranch, selectedIntegrationId])

const handleCancelRun = useCallback(async (runId: string) => {
  if (!selectedIntegrationId) {
    return false
  }

  setCancelingRunId(runId)
  setActionMessage("")
  try {
    const response = await fetch(
      `/api/gitlab/integrations/${selectedIntegrationId}/index/runs/${runId}/cancel`,
      {
        method: "POST",
        headers: { "content-type": "application/json" },
      },
    )
    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, "Failed to cancel indexing run."))
    }

    setActionMessage("Cancellation requested for indexing run.")
    await loadIndexingData(selectedIntegrationId, true)
    return true
  } catch (error) {
    setErrorMessage(error instanceof Error ? error.message : "Failed to cancel indexing run.")
    return false
  } finally {
    setCancelingRunId(null)
  }
}, [loadIndexingData, selectedIntegrationId])

const openStartRunDialog = useCallback(() => {
  setStartRunError("")
  setStartRunBranch(suggestedRunTarget.branch)
  setStartRunConfigHash(suggestedRunTarget.configHash)
  setStartRunDialogOpen(true)
}, [suggestedRunTarget])

const handleStartRun = useCallback(async () => {
  const branch = startRunBranch.trim()
  if (!branch) {
    setStartRunError("Branch is required.")
    return
  }

  setIsStartingRun(true)
  setStartRunError("")
  const queued = await handleReindex(branch, startRunConfigHash)
  if (queued) {
    setStartRunDialogOpen(false)
  } else {
    setStartRunError("Failed to queue run. Check error banner above and retry.")
  }
  setIsStartingRun(false)
}, [handleReindex, startRunBranch, startRunConfigHash])

useEffect(() => {
  void loadIntegrations()
}, [loadIntegrations])

useEffect(() => {
  const hasQueryMatch = integrationIdFromQuery.length > 0 &&
    integrations.some((integration) => integration.id === integrationIdFromQuery)

  if (fixedIntegration) {
    if (selectedIntegrationId !== fixedIntegration.id) {
      setSelectedIntegrationId(fixedIntegration.id)
    }
    return
  }

  if (hasQueryMatch && selectedIntegrationId !== integrationIdFromQuery) {
    setSelectedIntegrationId(integrationIdFromQuery)
    return
  }

  const hasSelectedMatch = selectedIntegrationId.length > 0 &&
    integrations.some((integration) => integration.id === selectedIntegrationId)

  if (hasSelectedMatch) {
    return
  }

  setSelectedIntegrationId(integrations[0]?.id ?? "")
}, [fixedIntegration, integrationIdFromQuery, integrations, selectedIntegrationId])

useEffect(() => {
  if (fixedIntegration) {
    return
  }

  const currentQueryId = searchParams.get("integrationId") ?? ""

  if (!selectedIntegrationId) {
    if (!currentQueryId) {
      return
    }

    const nextParams = new URLSearchParams(searchParams.toString())
    nextParams.delete("integrationId")
    const nextQuery = nextParams.toString()
    router.replace(nextQuery.length > 0 ? `${pathname}?${nextQuery}` : pathname, { scroll: false })
    return
  }

  if (currentQueryId === selectedIntegrationId) {
    return
  }

  const nextParams = new URLSearchParams(searchParams.toString())
  nextParams.set("integrationId", selectedIntegrationId)
  router.replace(`${pathname}?${nextParams.toString()}`, { scroll: false })
}, [fixedIntegration, pathname, router, searchParams, selectedIntegrationId])

useEffect(() => {
  if (!selectedIntegrationId) {
    setRuns([])
    setRunsPagination(null)
    setQueueSummary(null)
    setWorkerTelemetry(null)
