import type { GitLabIntegrationSummary } from "@/lib/gitlab/service"

type UserIntegrationsCacheEntry = {
  expiresAt: number
  value: Promise<GitLabIntegrationSummary[]>
}

const DEFAULT_CACHE_TTL_MS = 60_000
const DEFAULT_CACHE_MAX_ENTRIES = 256

const asPositiveInteger = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed < 1) {
    return fallback
  }

  return parsed
}

const USER_INTEGRATIONS_CACHE_TTL_MS = asPositiveInteger(
  process.env.ARGUS_INTEGRATIONS_CACHE_TTL_MS,
  DEFAULT_CACHE_TTL_MS,
)
const USER_INTEGRATIONS_CACHE_MAX_ENTRIES = asPositiveInteger(
  process.env.ARGUS_INTEGRATIONS_CACHE_MAX_ENTRIES,
  DEFAULT_CACHE_MAX_ENTRIES,
)

const userIntegrationsCache = new Map<string, UserIntegrationsCacheEntry>()

const trimUserIntegrationsCache = () => {
  const now = Date.now()
  for (const [key, entry] of userIntegrationsCache.entries()) {
    if (entry.expiresAt <= now) {
      userIntegrationsCache.delete(key)
    }
  }

  while (userIntegrationsCache.size > USER_INTEGRATIONS_CACHE_MAX_ENTRIES) {
    const oldestKey = userIntegrationsCache.keys().next().value
    if (!oldestKey) {
      break
    }
    userIntegrationsCache.delete(oldestKey)
  }
}

const defaultLoadUserIntegrations = async (userId: string) => {
  const { listUserIntegrations } = await import("@/lib/gitlab/service")
  return listUserIntegrations(userId)
}

export const getCachedUserIntegrations = (
  userId: string,
  options?: {
    load?: (userId: string) => Promise<GitLabIntegrationSummary[]>
  },
) => {
  const normalizedUserId = userId.trim()
  if (!normalizedUserId) {
    return Promise.resolve([] as GitLabIntegrationSummary[])
  }

  const now = Date.now()
  const cachedEntry = userIntegrationsCache.get(normalizedUserId)
  if (cachedEntry && cachedEntry.expiresAt > now) {
    return cachedEntry.value
  }
  if (cachedEntry) {
    userIntegrationsCache.delete(normalizedUserId)
  }

  const load = options?.load ?? defaultLoadUserIntegrations
  const value = load(normalizedUserId)
  userIntegrationsCache.set(normalizedUserId, {
    expiresAt: now + USER_INTEGRATIONS_CACHE_TTL_MS,
    value,
  })
  trimUserIntegrationsCache()

  value.catch(() => {
    const current = userIntegrationsCache.get(normalizedUserId)
    if (current?.value === value) {
      userIntegrationsCache.delete(normalizedUserId)
    }
  })

  return value
}

export const invalidateUserIntegrations = (userId?: string) => {
  if (typeof userId === "string") {
    const normalizedUserId = userId.trim()
    if (!normalizedUserId) {
      return 0
    }
    return userIntegrationsCache.delete(normalizedUserId) ? 1 : 0
  }

  const size = userIntegrationsCache.size
  userIntegrationsCache.clear()
  return size
}

export const getUserIntegrationsCacheConfig = () => ({
  ttlMs: USER_INTEGRATIONS_CACHE_TTL_MS,
  maxEntries: USER_INTEGRATIONS_CACHE_MAX_ENTRIES,
})

const ALLOWED_MERGE_REQUEST_ACTIONS = new Set([
  "open",
  "reopen",
  "update",
  "merge",
]);

type NormalizedWebhookEvent = {
  eventType: "push" | "merge_request" | "ignored";
  jobType?: "push" | "merge_request";
  ref: string | null;
  normalizedPayload?: Record<string, unknown>;
};

const asObject = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null;
  }
  return value as Record<string, unknown>;
};

const asString = (value: unknown) =>
  typeof value === "string" && value.trim().length > 0 ? value : null;

const asNumberString = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return String(value);
  }
  if (typeof value === "string" && value.trim()) {
    return value.trim();
  }
  return null;
};

export const classifyWebhookEvent = (
  eventName: string,
  payload: Record<string, unknown>,
): NormalizedWebhookEvent => {

  const ref = asString(payload.ref);

  if (eventName === "Push Hook") {
    if (!ref || !ref.startsWith("refs/heads/")) {
      return {
        eventType: "ignored",
        ref,
      };
    }

    const after = asString(payload.after);
    if (!after) {
      return {
        eventType: "ignored",
        ref,
      };
    }

    return {
      eventType: "push",
      jobType: "push",
      ref,
      normalizedPayload: {
        ref,
        before: asString(payload.before),
        after,
        checkoutSha: asString(payload.checkout_sha),
      },
    };
  }

  if (eventName === "Merge Request Hook") {
    const objectAttributes = asObject(payload.object_attributes);
    const action = asString(objectAttributes?.action);

    if (!action || !ALLOWED_MERGE_REQUEST_ACTIONS.has(action)) {
      return {
        eventType: "ignored",
        ref,
      };
    }

    const mergeRequestIid = asNumberString(objectAttributes?.iid);
    if (!mergeRequestIid) {
      return {
        eventType: "ignored",
        ref,
      };
    }

    const lastCommit = asObject(objectAttributes?.last_commit);

    return {
      eventType: "merge_request",
      jobType: "merge_request",
      ref,
      normalizedPayload: {
        mergeRequestIid,
        action,
        sourceBranch: asString(objectAttributes?.source_branch),
        targetBranch: asString(objectAttributes?.target_branch),
        state: asString(objectAttributes?.state),
        lastCommitSha: asString(lastCommit?.id),
      },
    };
  }

  return {
    eventType: "ignored",
    ref,
  };
};

