import { createLogDrainBuffer } from "@argus/shared-observability"

describe("shared observability drain buffer", () => {
  test("flushes immediately when batch size threshold is reached", async () => {
    const written: number[][] = []
    const drain = createLogDrainBuffer<number>({
      maxBufferSize: 10,
      batchSize: 2,
      flushIntervalMs: 10_000,
      enabled: true,
      writeBatch: async (batch) => {
        written.push(batch)
      },
    })

    drain.push(1)
    drain.push(2)
    await drain.flush()

    expect(written).toEqual([[1, 2]])
  })

  test("drops oldest items when max buffer is exceeded", async () => {
    const written: number[][] = []
    const drain = createLogDrainBuffer<number>({
      maxBufferSize: 2,
      batchSize: 10,
      flushIntervalMs: 10_000,
      enabled: true,
      writeBatch: async (batch) => {
        written.push(batch)
      },
    })

    drain.push(1)
    drain.push(2)
    drain.push(3)
    await drain.flush()

    expect(written).toEqual([[2, 3]])
    expect(drain.getState().dropCount).toBe(1)
  })
})

