const claimPlannedRuns = async (batchSize: number): Promise<ClaimedRun[]> => {
  const query = sql<ClaimedRun>`
    with due_runs as (
      select
        ${indexRuns.id} as id,
        ${indexRuns.headSha} as head_sha,
        ${indexBranchStates.integrationId} as integration_id,
        ${indexBranchStates.branch} as branch,
        ${indexBranchStates.configHash} as config_hash
      from ${indexRuns}
      inner join ${indexBranchStates}
        on ${indexBranchStates.id} = ${indexRuns.branchStateId}
      where ${indexRuns.status} = 'planned'
      order by ${indexRuns.createdAt} asc
      for update skip locked
      limit ${batchSize}
    ),
    claimed as (
      update ${indexRuns}
        set
          "status" = 'ingesting',
          "updated_at" = now()
      from due_runs
      where ${indexRuns.id} = due_runs.id
      returning ${indexRuns.id} as id
    )
    select
      claimed.id as "id",
      due_runs.head_sha as "headSha",
      due_runs.integration_id as "integrationId",
      due_runs.branch as "branch",
      due_runs.config_hash as "configHash"
    from claimed
    inner join due_runs
      on due_runs.id = claimed.id
  `

  const result = await db.execute(query)
  return result.rows.map((raw) => {
    const row = raw as Record<string, unknown>
    return {
      id: String(row.id),
      headSha: String(row.headSha),
      integrationId: String(row.integrationId),
      branch: String(row.branch),
      configHash: String(row.configHash),
    }
  })
}

export const runIndexingWorkerBatch = async (

