    summary.appLogCleanupTriggered = appLogCleanupSummary.lock === 'acquired'
    summary.appLogCleanupDeletedByAge = appLogCleanupSummary.deletedByAge
    summary.appLogCleanupDeletedByCap = appLogCleanupSummary.deletedByCap
    if (appLogCleanupSummary.lock === 'acquired') {
