  })
} catch (error) {
  const errorToLog = toError(error, 'Unexpected queue depth snapshot processing error.')
  logRunnerScopedError(batchLog, errorToLog, {
    code: 'INDEXER_QUEUE_DEPTH_AFTER_FAILED',
    why: 'Failed to read queue depth snapshot after batch processing.',
    fix: 'Inspect index_jobs/index_runs queries and database connectivity.',
  })
}
batchLog.set({
  outcome: hasFailures ? 'partial_failure' : 'success',
})
if (hasFailures) {
  batchStatus = 207
}

return summary

  } finally {
    const durationMs = Date.now() - startedAt
    const indexingFailures =
      summary.failed + summary.jobsFailed + summary.jobsDead + summary.embeddingFailures
    batchLog.set({
      durationMs,
      summary,
      indexingMetrics: {
        durationMs,
        filesProcessed: summary.filesProcessed,
        failures: indexingFailures,
        embeddingApiCalls: summary.embeddingApiCalls,
        pendingJobs: summary.queueDepthAfter?.jobsPending ?? null,
        processingJobs: summary.queueDepthAfter?.jobsProcessing ?? null,
      },
      llmMetrics: {
        provider: resolveEmbeddingProviderLabel(),
        model: resolveEmbeddingModelLabel(),
        promptTokens: summary.embeddingPromptTokens,
        completionTokens: 0,
        totalTokens: summary.embeddingTotalTokens,
        latencyMs: null,
        costUsd: Number(summary.embeddingCostUsd.toFixed(8)),
        requestCount: summary.embeddingApiCalls,
      },
    })
    batchLog.emit({
      status: batchStatus,
      durationMs,
    })
  }
}

import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { performance } from 'node:perf_hooks'
import { spawn, spawnSync } from 'node:child_process'
import type { ChildProcess } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { parseArgs } from 'node:util'

type RunResult = {
  indexMs: number
  searchMs: number
  queryMs: number[]
  queryHitCounts: number[]
  impactMs: number
  impactQueryMs: number[]
  impactHitCounts: number[]
}

type EngineSummary = {
  name: 'argus-ci' | 'grepai'
  warmup: RunResult[]
  measured: RunResult[]
}

type ArgusPhases = {
  parse: boolean
  graph: boolean
  vector: boolean
  scip: boolean
  indexPack: boolean
}

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')

const EXCLUDED_BASENAMES = new Set([
  '.git',
  '.argus-search',
  '.grepai',
  'node_modules',
  'target',
  'dist',
  'build',
  '.venv',
  '__pycache__',
])

const DEFAULT_MOCK_EMBEDDINGS_PORT = 18765

function sleepMs(ms: number) {
  const sleeper = new Int32Array(new SharedArrayBuffer(4))
  Atomics.wait(sleeper, 0, 0, ms)
}

function parsePositiveInt(name: string, value: string | undefined, fallback: number): number {
  if (!value) return fallback
  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(`${name} must be a positive integer`)
  }
  return parsed
}

function parseBoolean(value: boolean | undefined, fallback = false): boolean {
  if (value == null) return fallback
  return Boolean(value)
}

function splitCsv(value: string | undefined, fallback: string[]): string[] {
  if (!value) return [...fallback]
  const out = value
    .split(',')
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0)
  return out.length ? out : [...fallback]
}

function parseChoice(name: string, value: string | undefined, allowed: string[], fallback: string): string {
  const selected = (value ?? fallback).toLowerCase()
  if (!allowed.includes(selected)) {
    throw new Error(`${name} must be one of: ${allowed.join(', ')}`)
  }
  return selected
}

function avg(values: number[]): number {
  if (!values.length) return 0
  return values.reduce((sum, current) => sum + current, 0) / values.length
}

function min(values: number[]): number {
  if (!values.length) return 0
  return Math.min(...values)
}

function max(values: number[]): number {
  if (!values.length) return 0
  return Math.max(...values)
}

function percentile(values: number[], p: number): number {
  if (!values.length) return 0
  const sorted = [...values].sort((a, b) => a - b)
  const index = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1))
  return sorted[index]
}

function summarize(values: number[]) {
  return {
    avg: Number(avg(values).toFixed(2)),
    min: Number(min(values).toFixed(2)),
    p50: Number(percentile(values, 50).toFixed(2)),
    p95: Number(percentile(values, 95).toFixed(2)),
    max: Number(max(values).toFixed(2)),
  }
}

function commandLine(cmd: string, args: string[]): string {
  const quoted = args.map((arg) => (arg.includes(' ') ? JSON.stringify(arg) : arg))
  return [cmd, ...quoted].join(' ')
}

function runCommand(
  cmd: string,
  args: string[],
  options: { cwd: string; timeoutMs: number; allowFailure?: boolean; dryRun?: boolean },
): { stdout: string; stderr: string; status: number; durationMs: number } {
  if (options.dryRun) {
    console.log(`[dry-run] ${commandLine(cmd, args)} (cwd=${options.cwd})`)
    return { stdout: '', stderr: '', status: 0, durationMs: 0 }
  }

  const started = performance.now()
  const result = spawnSync(cmd, args, {
    cwd: options.cwd,
    env: process.env,
    encoding: 'utf8',
    timeout: options.timeoutMs,
    maxBuffer: 64 * 1024 * 1024,
  })
  const durationMs = Number((performance.now() - started).toFixed(2))

  if (result.error) {
    const cause = result.error.message || String(result.error)
    throw new Error(`command failed: ${commandLine(cmd, args)} (${cause})`)
  }

  const status = typeof result.status === 'number' ? result.status : 1
  const stdout = result.stdout ?? ''
  const stderr = result.stderr ?? ''

  if (status !== 0 && !options.allowFailure) {
    throw new Error(
      [
        `command failed with exit code ${status}: ${commandLine(cmd, args)}`,
        stdout ? `stdout:\n${stdout}` : '',
        stderr ? `stderr:\n${stderr}` : '',
      ]
        .filter(Boolean)
        .join('\n'),
    )
  }

  return { stdout, stderr, status, durationMs }
}

function runCommandWithRetries(
  cmd: string,
  args: string[],
  options: { cwd: string; timeoutMs: number; allowFailure?: boolean; dryRun?: boolean },
  retries: number,
  label?: string,
  onRetry?: (attempt: number) => void,
): { stdout: string; stderr: string; status: number; durationMs: number } {
  let lastError: unknown
  for (let attempt = 1; attempt <= retries + 1; attempt += 1) {
    try {
      return runCommand(cmd, args, options)
    } catch (error) {
      lastError = error
      if (attempt > retries) break
      const target = label ?? commandLine(cmd, args)
      console.warn(`[retry ${attempt}/${retries}] ${target}`)
      onRetry?.(attempt)
    }
  }
  throw lastError instanceof Error ? lastError : new Error(String(lastError))
}

function maybeParseHitCount(raw: string): number {
  const text = raw.trim()
  if (!text) return 0

  try {
    const parsed = JSON.parse(text) as unknown
    if (Array.isArray(parsed)) return parsed.length
    if (parsed && typeof parsed === 'object') {
      const obj = parsed as Record<string, unknown>
      if (Array.isArray(obj.results)) return obj.results.length
      if (Array.isArray(obj.hits)) return obj.hits.length
      if (Array.isArray(obj.items)) return obj.items.length
    }
  } catch {
    return 0
  }
  return 0
}

function maybeParseImpactCount(raw: string): number {
  const text = raw.trim()
  if (!text) return 0
  try {
    const parsed = JSON.parse(text) as unknown
    if (Array.isArray(parsed)) {
      let impactNodes = 0
      for (const item of parsed) {
        if (item && typeof item === 'object') {
          const obj = item as Record<string, unknown>
          if (Array.isArray(obj.impact)) {
            impactNodes += obj.impact.length
          }
        }
      }
      if (impactNodes > 0) return impactNodes
      return parsed.length
    }
    if (parsed && typeof parsed === 'object') {
      const obj = parsed as Record<string, unknown>
      const keys = ['nodes', 'callers', 'callees', 'results', 'hits', 'items', 'edges']
      for (const key of keys) {
        if (Array.isArray(obj[key])) {
          return obj[key].length
        }
      }
    }
  } catch {
    return 0
  }
  return 0
}

function cleanArgusStore(storePath: string) {
  fs.rmSync(storePath, { force: true })
  fs.rmSync(`${storePath}.manifest.json`, { force: true })
}

function argusQueryCachePath(storePath: string): string {
  const base = path.basename(storePath)
  const dir = path.dirname(storePath)
  return path.join(dir, `${base}.query-cache.json`)
}

function replaceYamlScalar(content: string, key: string, value: string | number): string {
  const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  const pattern = new RegExp(`^(\\s*${escaped}:\\s*).*$`, 'm')
  if (pattern.test(content)) {
    return content.replace(pattern, `$1${value}`)
  }
  return content
}

function normalizeArgusPhase(value: string): keyof ArgusPhases | null {
  const lowered = value.trim().toLowerCase()
  if (lowered === 'parse') return 'parse'
  if (lowered === 'graph') return 'graph'
  if (lowered === 'vector') return 'vector'
  if (lowered === 'scip') return 'scip'
  if (lowered === 'indexpack' || lowered === 'index-pack' || lowered === 'index_pack') return 'indexPack'
  return null
}

function parseArgusPhases(csv: string): ArgusPhases {
  const parsed: ArgusPhases = { parse: false, graph: false, vector: false, scip: false, indexPack: false }
  const unknown: string[] = []
  for (const entry of csv
    .split(',')
    .map((item) => item.trim())
    .filter(Boolean)) {
    const phase = normalizeArgusPhase(entry)
    if (phase) parsed[phase] = true
    else unknown.push(entry)
  }
  if (unknown.length) {
    throw new Error(`Unknown argus phases: ${unknown.join(', ')}`)
  }
  return parsed
}

function applyPhasesToArgusConfig(configPath: string, phases: ArgusPhases) {
  const raw = fs.readFileSync(configPath, 'utf8')
  const config = JSON.parse(raw) as Record<string, unknown>
  config.phases = phases
  fs.writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`, 'utf8')
}

function applyVectorToArgusConfig(configPath: string, vector: { baseUrl: string; model: string; dimension: number }) {
  const raw = fs.readFileSync(configPath, 'utf8')
  const config = JSON.parse(raw) as Record<string, unknown>
  const currentVector =
    config.vector && typeof config.vector === 'object' ? (config.vector as Record<string, unknown>) : {}
  const currentProvider =
    currentVector.provider && typeof currentVector.provider === 'object'
      ? (currentVector.provider as Record<string, unknown>)
      : {}

  config.vector = {
    ...currentVector,
    provider: {
      ...currentProvider,
      kind: 'http',
      baseUrl: vector.baseUrl,
      model: vector.model,
      dimension: vector.dimension,
    },
  }
  fs.writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`, 'utf8')
}

function copyProject(source: string, destination: string) {
  fs.mkdirSync(path.dirname(destination), { recursive: true })
  fs.cpSync(source, destination, {
    recursive: true,
    force: true,
    filter: (entry) => !EXCLUDED_BASENAMES.has(path.basename(entry)),
  })
}

function detectArgusBin(defaultRoot: string, overrideBin: string | undefined): string {
  if (overrideBin?.trim()) return overrideBin.trim()
  const releaseBin = path.join(defaultRoot, 'target', 'release', process.platform === 'win32' ? 'ci.exe' : 'ci')
  return fs.existsSync(releaseBin) ? releaseBin : 'ci'
}

function normalizeGrepaiConfig(
  grepaiRoot: string,
  options: { provider: string; model?: string; endpoint?: string; dimensions?: number },
) {
  const configPath = path.join(grepaiRoot, '.grepai', 'config.yaml')
  if (!fs.existsSync(configPath)) return

  let content = fs.readFileSync(configPath, 'utf8')
  content = replaceYamlScalar(content, 'provider', options.provider)
  if (options.model) content = replaceYamlScalar(content, 'model', options.model)
  if (options.endpoint) content = replaceYamlScalar(content, 'endpoint', options.endpoint)
  if (options.dimensions) content = replaceYamlScalar(content, 'dimensions', options.dimensions)
  fs.writeFileSync(configPath, content, 'utf8')
}

function startMockEmbeddingsServer(port: number): ChildProcess {
  const script = `
const http = require('http');
const port = Number(process.env.MOCK_EMBEDDINGS_PORT || ${DEFAULT_MOCK_EMBEDDINGS_PORT});

function respondJson(res, status, payload) {
  const body = JSON.stringify(payload);
  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body) });
  res.end(body);
}

const server = http.createServer((req, res) => {
  if (req.method !== 'POST') return respondJson(res, 404, { error: 'not found' });
  if (req.url !== '/embeddings' && req.url !== '/v1/embeddings') return respondJson(res, 404, { error: 'not found' });
  let raw = '';
  req.on('data', (chunk) => (raw += chunk));
  req.on('end', () => {
    let input = [];
    try {
      const parsed = JSON.parse(raw || '{}');
      if (Array.isArray(parsed.input)) input = parsed.input;
    } catch {}
    const data = input.map(() => ({ embedding: [0.1, 0.2, 0.3] }));
    respondJson(res, 200, { data });
  });
});

server.listen(port, '127.0.0.1');
`
  const child = spawn(process.execPath, ['-e', script], {
    stdio: 'ignore',
    env: {
      ...process.env,
      MOCK_EMBEDDINGS_PORT: String(port),
    },
  })
  sleepMs(300)
  if (child.exitCode !== null) {
    throw new Error(`failed to start mock embeddings server on port ${port}`)
  }
  return child
}

function stopMockEmbeddingsServer(proc: ChildProcess | null) {
  if (!proc || proc.exitCode !== null) return
  proc.kill('SIGTERM')
}

