const argusSummary: EngineSummary = { name: 'argus-ci', warmup: [], measured: [] }
const grepaiSummary: EngineSummary = { name: 'grepai', warmup: [], measured: [] }

function runArgusPass(passIndex: number): RunResult {
  cleanArgusStore(argusStorePath)
  if (argusQueryCacheMode === 'cold') {
    fs.rmSync(argusQueryCachePath(argusStorePath), { force: true })
  }
  if (!dryRun) {
    applyPhasesToArgusConfig(argusConfigPath, argusPhaseConfig)
  }

  const watchArgs = ['--config', argusConfigPath, '--store', argusStorePath, 'watch', '--once']
  if (argusWatchSupportsPhases) {
    watchArgs.push('--phases', argusPhases)
  }
  if (argusCheckpointWarmup === 'off') {
    watchArgs.push('--no-checkpoint-warmup')
  }
  const indexRun = runCommand(argusBin, watchArgs, { cwd: argusRoot, timeoutMs, dryRun })

  const queryMs: number[] = []
  const queryHitCounts: number[] = []
  for (const query of queries) {
    const searchRun = runCommand(
      argusBin,
      ['--config', argusConfigPath, '--store', argusStorePath, 'search', query, '--top-k', String(topK), '--json'],
      { cwd: argusRoot, timeoutMs, dryRun },
    )
    queryMs.push(searchRun.durationMs)
    queryHitCounts.push(maybeParseHitCount(searchRun.stdout))
  }
  const impactQueryMs: number[] = []
  const impactHitCounts: number[] = []

}

function resetGrepaiProject() {
  fs.rmSync(path.join(grepaiRoot, '.grepai'), { recursive: true, force: true })
  runCommand(grepaiBin, ['init', '--yes', '--provider', grepaiProvider, '--backend', grepaiBackend], {
    cwd: grepaiRoot,
    timeoutMs,
    dryRun,
  })
  if (!dryRun) {
    normalizeGrepaiConfig(grepaiRoot, {
      provider: grepaiProvider,
      model: grepaiModel,
      endpoint: grepaiEndpoint,
      dimensions: grepaiDimensions,
    })
  }
}

function runGrepaiPass(passIndex: number): RunResult {
  runCommand(grepaiBin, ['watch', '--stop'], { cwd: grepaiRoot, timeoutMs, allowFailure: true, dryRun })
  resetGrepaiProject()

  const indexRun = runCommandWithRetries(
    grepaiBin,
    ['watch', '--background'],
    { cwd: grepaiRoot, timeoutMs, dryRun },
    2,
    'grepai watch --background failed, retrying startup',
    () => {
      runCommand(grepaiBin, ['watch', '--stop'], { cwd: grepaiRoot, timeoutMs, allowFailure: true, dryRun })
      resetGrepaiProject()
    },
  )

  const queryMs: number[] = []
  const queryHitCounts: number[] = []
  for (const query of queries) {
    const searchRun = runCommand(grepaiBin, ['search', query, '--json', '--compact', '--limit', String(topK)], {
      cwd: grepaiRoot,
      timeoutMs,
      dryRun,
    })
    queryMs.push(searchRun.durationMs)
    queryHitCounts.push(maybeParseHitCount(searchRun.stdout))
  }
  const impactQueryMs: number[] = []
  const impactHitCounts: number[] = []

if (includeImpact) {
  for (const query of impactQueries) {
    const traceArgs = ['trace', grepaiTraceKind, query, '--json', '--mode', grepaiTraceMode]
    if (grepaiTraceKind === 'graph') {
      traceArgs.push('--depth', String(traceDepth))
    }
    const impactRun = runCommand(grepaiBin, traceArgs, {
      cwd: grepaiRoot,
      timeoutMs,
      dryRun,
    })
    impactQueryMs.push(impactRun.durationMs)
    impactHitCounts.push(maybeParseImpactCount(impactRun.stdout))
  }
}

runCommand(grepaiBin, ['watch', '--stop'], { cwd: grepaiRoot, timeoutMs, allowFailure: true, dryRun })

const searchMs = Number(queryMs.reduce((sum, value) => sum + value, 0).toFixed(2))
const impactMs = Number(impactQueryMs.reduce((sum, value) => sum + value, 0).toFixed(2))
const run: RunResult = {
  indexMs: indexRun.durationMs,
  searchMs,
  queryMs,
  queryHitCounts,
  impactMs,
  impactQueryMs,
  impactHitCounts,
}
const label = passIndex <= warmup ? `warmup ${passIndex}` : `run ${passIndex - warmup}`
const impactText = includeImpact ? ` impact=${run.impactMs.toFixed(2)}ms` : ''
console.log(
  `[grepai] ${label.padEnd(10)} index=${run.indexMs.toFixed(2)}ms search=${run.searchMs.toFixed(2)}ms${impactText}`,
)
return run

}

try {
