  | "GITLAB_RATE_LIMITED"
  | "GITLAB_UPSTREAM_TRANSIENT"
  | "GITLAB_UPSTREAM_ERROR";

type GitLabRouteErrorOptions = {
  status: number;
  code: GitLabRouteErrorCode;
  retryable?: boolean;
  reconnectRequired?: boolean;
