      apiPath: "/api/v4/user",
    }).catch(() => ({})),
  ]);

  const currentUser = normalizeGitLabUser(currentUserData);
  const mergeRequests: MergeRequest[] = responseData
    .filter((item) => item && typeof item === "object")
    .map((item) => mapMergeRequest(item, currentUser));

  logger.set({
    projectId: payload.projectId,
    count: mergeRequests.length,
  });
  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ data: mergeRequests }),
  };
}

if (!isNonEmptyString(payload.mergeRequestIid)) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "Merge request selection is required." },
      { status: 400 },
    ),
  };
}

if (payload.action === "merge-request") {
  const forceRefresh = payload.forceRefresh === true;
  const encodedProjectId = encodeURIComponent(payload.projectId);
  const encodedMergeRequestIid = encodeURIComponent(payload.mergeRequestIid);
  const mergeRequestApiPath = `/api/v4/projects/${encodedProjectId}/merge_requests/${encodedMergeRequestIid}`;
  const mergeRequestPayload = await getCachedGitLabJson<Record<string, unknown>>({
    instanceUrl: normalizedInstanceUrl,
    token: resolvedToken.token,
    action: payload.action,
    forceRefresh,
