  });

  const mergeRequest = {
    id: String(mergeRequestPayload.id ?? "").trim(),
    iid: String(mergeRequestPayload.iid ?? payload.mergeRequestIid),
    title: String(mergeRequestPayload.title ?? "").trim(),
    description:
      typeof mergeRequestPayload.description === "string"
        ? mergeRequestPayload.description
        : "",
    webUrl: String(mergeRequestPayload.web_url ?? "").trim(),
  };

  logger.set({
    projectId: payload.projectId,
    mergeRequestIid: payload.mergeRequestIid,
    mergeRequestId: mergeRequest.id || null,
    descriptionLength: mergeRequest.description.length,
  });

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ data: mergeRequest }),
