}

if (payload.action === "create-merge-request-discussion") {
  const commentBody = normalizeDiscussionBody(payload.commentBody);
  const commentLine = normalizeDiscussionLine(payload.commentLine);
  const commentSide = normalizeDiscussionSide(payload.commentSide);
  const commentFilePath = normalizeDiscussionPath(payload.commentFilePath);
  const commentOldPath = normalizeDiscussionPath(payload.commentOldPath);
  const commentNewPath = normalizeDiscussionPath(payload.commentNewPath);

  if (!commentBody) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: "commentBody is required." },
        { status: 400 },
      ),
    };
  }
  if (!commentSide) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: "commentSide must be one of: additions or deletions." },
        { status: 400 },
      ),
    };
  }
  if (!commentLine) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: "commentLine must be a positive integer." },
        { status: 400 },
      ),
    };
  }

  let oldPath = commentOldPath || commentFilePath || commentNewPath;

let newPath = commentNewPath || commentFilePath || commentOldPath;
if (!oldPath && newPath) {
  oldPath = newPath;
}
if (!newPath && oldPath) {
  newPath = oldPath;
}

if (commentSide === "additions" && !newPath) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "A new path is required for additions-side comments." },
      { status: 400 },
    ),
  };
}
if (commentSide === "deletions" && !oldPath) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "An old path is required for deletions-side comments." },
      { status: 400 },
    ),
  };
}

let discussionData: Awaited<
  ReturnType<typeof createMergeRequestDiscussion>
>;

try {
  discussionData = await createMergeRequestDiscussion({
