  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        mergeRequestId,
        updated: true,
        previousDescription,
      },
    }),
  };
}

if (payload.streamDiff === true) {
  const streamResponse = await getMergeRequestPatchStreamResponse({
