use std::collections::HashMap;
use std::fs::{self, File, OpenOptions};
use std::io::Write;
use std::path::{Path, PathBuf};
use std::thread::sleep;
use std::time::Duration;

#[derive(Debug, Clone, Default)]
pub struct CacheOptions {
  pub enabled: bool,
  pub force: bool,
  pub path: Option<PathBuf>,
}

impl CacheOptions {
  pub fn resolve_path(&self, data_dir: &Path) -> PathBuf {
    self
      .path
      .clone()
      .unwrap_or_else(|| data_dir.join("cache/index-cache.json"))
  }
}

#[derive(Debug)]
pub enum CacheError {
  Io(std::io::Error),
  Json(serde_json::Error),
  LockTimeout(String),
}

impl std::fmt::Display for CacheError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      CacheError::Io(err) => write!(f, "cache io error: {err}"),
      CacheError::Json(err) => write!(f, "cache json error: {err}"),
      CacheError::LockTimeout(msg) => write!(f, "{msg}"),
    }
  }
}

impl std::error::Error for CacheError {}

impl From<std::io::Error> for CacheError {
  fn from(value: std::io::Error) -> Self {
    CacheError::Io(value)
  }
}

impl From<serde_json::Error> for CacheError {
  fn from(value: serde_json::Error) -> Self {
    CacheError::Json(value)
  }
}

#[derive(Debug, Clone)]
pub struct CacheState {
  path: PathBuf,
  data: HashMap<String, String>,
  dirty: bool,
}

impl CacheState {
  pub fn load(path: PathBuf) -> Self {
    let data = fs::read_to_string(&path)
      .ok()
      .and_then(|raw| serde_json::from_str::<HashMap<String, String>>(&raw).ok())
      .unwrap_or_default();

    Self {
      path,
      data,
      dirty: false,
    }
  }

  pub fn get(&self, key: &str) -> Option<&str> {
    self.data.get(key).map(|value| value.as_str())
  }

  pub fn set(&mut self, key: impl Into<String>, value: impl Into<String>) {
    self.data.insert(key.into(), value.into());
    self.dirty = true;
  }

  pub fn save(&mut self) -> Result<(), CacheError> {
    if !self.dirty {
      return Ok(());
    }

    if let Some(parent) = self.path.parent() {
      fs::create_dir_all(parent)?;
    }

    let lock_path = self.path.with_extension("lock");
    let lock = acquire_lock(&lock_path)?;

    let temp_path = self
      .path
      .with_extension(format!("tmp-{}", std::process::id()));

    let payload = serde_json::to_vec_pretty(&self.data)?;
    let result = (|| -> Result<(), CacheError> {
      let mut file = File::create(&temp_path)?;
      file.write_all(&payload)?;
      file.flush()?;
      fs::rename(&temp_path, &self.path)?;
      Ok(())
    })();

    release_lock(&lock_path, lock);
    result?;
    self.dirty = false;
    Ok(())
  }
}

fn acquire_lock(lock_path: &Path) -> Result<File, CacheError> {
  let attempts = 10;
  let delay = Duration::from_millis(50);
  let mut last_error = None;

  for _ in 0..attempts {
    match OpenOptions::new()
      .write(true)
      .create_new(true)
      .open(lock_path)
    {
      Ok(file) => return Ok(file),
      Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {
        last_error = Some(err);
        sleep(delay);
      }
      Err(err) => return Err(CacheError::Io(err)),
    }
  }

  let message = format!(
    "Failed to acquire cache lock at {}",
    lock_path.to_string_lossy()
  );
  if let Some(err) = last_error {
    return Err(CacheError::LockTimeout(format!("{message}: {err}")));
  }
  Err(CacheError::LockTimeout(message))
}

fn release_lock(lock_path: &Path, file: File) {
  drop(file);
  let _ = fs::remove_file(lock_path);
}

