    let temp = tempfile::tempdir()?;
    let path = temp.path().join("cache.json");
    let mut cache = CacheState::load(path.clone());
    cache.set("foo", "bar");
    cache.save()?;

    let cache = CacheState::load(path);
    assert_eq!(cache.get("foo"), Some("bar"));
    Ok(())
  }
