mod tests {
  use super::*;
  use crate::core::cancel::CancelToken;
  use crate::core::kitedb_store::{KiteCodeStore, KiteDbIndexSink};
  use crate::core::parse::types::CodeChunk;
  use crate::core::vector::provider::{EmbeddingError, EmbeddingsProvider};
  use std::fs;

  struct TestSink {
    parse_batches: usize,
    graph_batches: usize,
  }

  impl ParseSink for TestSink {
    fn on_parse_batch_ref(&mut self, batch: &[CodeChunk]) {
      if !batch.is_empty() {
        self.parse_batches += 1;
      }
    }
  }

  impl GraphSink for TestSink {
    fn on_graph_batch(&mut self, batch: crate::core::graph::types::GraphBatch) {
      if !batch.nodes.is_empty() || !batch.edges.is_empty() {
        self.graph_batches += 1;
      }
    }
  }

  impl VectorSink for TestSink {}
  impl ScipSink for TestSink {}
  impl IndexSink for TestSink {}

  struct VectorEventSink {
    vector_progress_events: usize,
  }

  impl ParseSink for VectorEventSink {}
  impl GraphSink for VectorEventSink {}
  impl VectorSink for VectorEventSink {}
  impl ScipSink for VectorEventSink {}

impl IndexSink for VectorEventSink {
  fn on_event(&mut self, event: IndexEvent) {
    if matches!(
      event,
      IndexEvent::PhaseProgress {
        phase: IndexPhase::Vector,
        ..
      }
    ) {
      self.vector_progress_events += 1;
    }
  }
}

