#[test]
fn kitedb_sink_removes_stale_nodes_on_rename_and_delete() -> Result<(), Box<dyn std::error::Error>>
{
  let temp = tempfile::tempdir()?;
  let file_path = temp.path().join("sample.js");
  fs::write(&file_path, "function foo() {}\n")?;
  let store_path = temp.path().join("index.kite");

  let mut options = IndexOptions::new(temp.path());
  options.inputs.paths = vec![temp.path().to_path_buf()];
  options.inputs.include = vec!["*.js".to_string()];
  options.phases = IndexPhases {
    parse: true,
    graph: true,
    vector: false,
    scip: false,
    index_pack: false,
  };
  options.cache.enabled = true;

  options.output.incremental = true;

  let run_once = |options: &IndexOptions,
                  store_path: &std::path::Path|
   -> Result<(), Box<dyn std::error::Error>> {
    let engine = IndexEngine::new(options.clone());
    let mut sink = KiteDbIndexSink::new(store_path.to_path_buf(), false);
    engine.run(&mut sink, &CancelToken::new())?;
    sink.finish()?;
    Ok(())
  };

  run_once(&options, &store_path)?;
  let store = KiteCodeStore::open_readonly(store_path.clone())?;
  assert!(store.has_ci_id("ts:function:sample.js:foo:0"));

  fs::write(&file_path, "function bar() {}\n")?;
  run_once(&options, &store_path)?;
  let store = KiteCodeStore::open_readonly(store_path.clone())?;
  assert!(!store.has_ci_id("ts:function:sample.js:foo:0"));
  assert!(store.has_ci_id("ts:function:sample.js:bar:0"));

  fs::remove_file(&file_path)?;
  run_once(&options, &store_path)?;
  let store = KiteCodeStore::open_readonly(store_path)?;
  assert!(!store.has_ci_id("ts:function:sample.js:bar:0"));
  assert!(!store.has_ci_id("ts:file:sample.js"));

  Ok(())
}

#[test]

fn kitedb_sink_bootstraps_without_manifest_and_preserves_unchanged_files(
) -> Result<(), Box<dyn std::error::Error>> {
  let temp = tempfile::tempdir()?;
  let file_a = temp.path().join("a.js");
  let file_b = temp.path().join("b.js");
  fs::write(&file_a, "function alpha() {}\n")?;
  fs::write(&file_b, "function beta() {}\n")?;
  let store_path = temp.path().join("index.kite");
  let manifest_path = temp.path().join("index.kite.manifest.json");

  let mut options = IndexOptions::new(temp.path());
  options.inputs.paths = vec![temp.path().to_path_buf()];
  options.inputs.include = vec!["*.js".to_string()];
  options.phases = IndexPhases {
    parse: true,
    graph: true,
    vector: false,
    scip: false,
    index_pack: false,
  };
  options.cache.enabled = true;
  options.output.incremental = true;

  let run_once = |options: &IndexOptions,
                  store_path: &std::path::Path|
   -> Result<(), Box<dyn std::error::Error>> {
    let engine = IndexEngine::new(options.clone());
    let mut sink = KiteDbIndexSink::new(store_path.to_path_buf(), false);
    engine.run(&mut sink, &CancelToken::new())?;
    sink.finish()?;
    Ok(())
  };

  run_once(&options, &store_path)?;
  assert!(manifest_path.exists());

  fs::remove_file(&manifest_path)?;
  fs::remove_file(&file_a)?;
  run_once(&options, &store_path)?;

  let store = KiteCodeStore::open_readonly(store_path)?;
  assert!(!store.has_ci_id("ts:function:a.js:alpha:0"));
  assert!(store.has_ci_id("ts:function:b.js:beta:0"));

  Ok(())
}

