export const parseBooleanWithFallback = (value: string | undefined, fallback: boolean) => {
  if (!value) {
    return fallback
  }

  const normalized = value.trim().toLowerCase()
  if (normalized === "1" || normalized === "true" || normalized === "yes") {
    return true
  }
  if (normalized === "0" || normalized === "false" || normalized === "no") {
    return false
  }

  return fallback
}

export const parsePositiveIntWithFallback = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }

  return parsed
}

export const parseRate = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed)) {
    return fallback
  }

  return Math.max(0, Math.min(100, parsed))
}

export const parseDurationMs = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.floor(value))
  }
  if (typeof value !== "string" || !value.trim()) {
    return null
  }

  const normalized = value.trim().toLowerCase()
  if (normalized.endsWith("ms")) {
    const parsed = Number.parseFloat(normalized.slice(0, -2))
    return Number.isFinite(parsed) ? Math.max(0, Math.round(parsed)) : null
  }
  if (normalized.endsWith("s")) {
    const parsed = Number.parseFloat(normalized.slice(0, -1))
    return Number.isFinite(parsed) ? Math.max(0, Math.round(parsed * 1_000)) : null
  }

  return null
}

export const createCorrelationId = () => {
  const cryptoApi = (globalThis as { crypto?: { randomUUID?: () => string } }).crypto
  if (typeof cryptoApi?.randomUUID === "function") {
    return cryptoApi.randomUUID()
  }

  return `${Date.now()}-${Math.random().toString(16).slice(2)}`
}

const resolveConfigPath = () => resolveCodeIntelConfigPath()
const resolveIndexPackDir = () => resolveCodeIntelIndexPackDir()
const resolveManifestPath = () => path.join(resolveIndexPackDir(), "manifest.json")

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const parseManifest = (raw: string): CodeGraphSummary => {
  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    throw new CodeGraphError("invalid_output", "Failed to parse graph index-pack manifest JSON.", null)
  }

  const validated = indexPackManifestSchema.safeParse(parsed)
  if (!validated.success) {
    throw new CodeGraphError("invalid_output", "Graph index-pack manifest did not match expected schema.", {
      issues: validated.error.issues.map((issue) => issue.message),
    })
  }

  const stats = validated.data.stats
  return {
    indexRunId: validated.data.indexRunId,
    generatedAt: validated.data.generatedAt,
    schemaVersion: validated.data.schemaVersion,
    stats: {
      filesParsed: stats?.filesParsed ?? 0,
      chunksEmitted: stats?.chunksEmitted ?? 0,
      nodesEmitted: stats?.nodesEmitted ?? 0,
      edgesEmitted: stats?.edgesEmitted ?? 0,
    },
  }
}

export const getCodeGraphSummary = async (): Promise<CodeGraphSummary | null> => {
  try {
    const raw = await readFile(resolveManifestPath(), "utf8")
    return parseManifest(raw)
  } catch (error) {
    if (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code?: string }).code === "ENOENT"
    ) {
      return null
    }

    if (error instanceof CodeGraphError) {
      throw error
    }

    throw new CodeGraphError("invalid_output", "Failed to read graph index-pack manifest.", {
      message: errorMessage(error),
    })
  }
}

export const refreshCodeGraphSummary = async (): Promise<CodeGraphSummary> => {
  const rootDir = resolveCodeIntelRoot()
  const configPath = resolveConfigPath()
  const configRaw = await readFile(configPath, "utf8").catch((error) => {
    throw new CodeGraphError("command_failed", "Failed to read argus-search config.", {
      configPath,
      message: errorMessage(error),
    })
  })

  let parsedConfig: unknown
  try {
    parsedConfig = JSON.parse(configRaw)
  } catch {
    throw new CodeGraphError("invalid_output", "Failed to parse argus-search config JSON.", {
      configPath,
    })
  }

  const baseConfig = asRecord(parsedConfig)
  if (!baseConfig) {
    throw new CodeGraphError("invalid_output", "Argus Search config must be a JSON object.", {
      configPath,
    })
  }

  const phases = asRecord(baseConfig.phases)
  const cache = asRecord(baseConfig.cache)
  const output = asRecord(baseConfig.output)

const fullGraphConfig = {
  ...baseConfig,
  phases: {
    ...phases,
    parse: true,
    graph: true,
    vector: false,
    indexPack: true,
  },
  cache: {
    ...cache,
    enabled: false,
    force: true,
  },
  output: {
    ...output,
    incremental: false,
  },
}

const tempDir = await mkdtemp(path.join(os.tmpdir(), "argus-code-graph-")).catch((error) => {
  throw new CodeGraphError("command_failed", "Failed to prepare temporary graph config directory.", {
    message: errorMessage(error),
  })
})
const tempConfigPath = path.join(tempDir, "argus-search.graph.json")
try {
  await writeFile(tempConfigPath, JSON.stringify(fullGraphConfig, null, 2), "utf8")
} catch (error) {
  await rm(tempDir, { recursive: true, force: true }).catch(() => {})
  throw new CodeGraphError("command_failed", "Failed to write temporary graph config.", {
    tempConfigPath,
    message: errorMessage(error),
  })
}

  try {
    await runWatchOnce({
      projectRoot: rootDir,
      configPath: tempConfigPath,
      storePath: undefined,
      phases: ["parse", "graph", "indexPack"],
      noVector: true,
      timeoutMs: 120_000,
    })
  } catch (error) {
    if (error instanceof CodeIntelSdkError) {
      if (error.code === "sdk_missing" || error.code === "operation_missing") {
        throw new CodeGraphError("binary_missing", "The Argus Search SDK is not available in this runtime.", {
          details: error.details,
        })
      }

      throw new CodeGraphError("command_failed", "Failed to refresh code graph index-pack.", {
        message: error.message,
        details: error.details,
      })
    }

    throw new CodeGraphError("command_failed", "Failed to refresh code graph index-pack.", {
      message: errorMessage(error),
    })
  } finally {
    await rm(tempDir, { recursive: true, force: true }).catch(() => {})
  }

  const summary = await getCodeGraphSummary()
  if (!summary) {
    throw new CodeGraphError(
      "missing_index_pack",
      "Code graph index-pack was not created at expected path.",
      {
        indexPackDir: resolveIndexPackDir(),
      },
    )
  }

  return summary
}

