import { existsSync } from 'node:fs'

import { Indexer, KiteDB, formatSearchHits } from '../../sdk.js'

const root = 'fixtures/sample-repo'
const query = process.env.CODE_INTEL_QUERY ?? 'Where is add defined?'
const color = process.env.CODE_INTEL_COLOR ?? 'auto'

const ix = new Indexer({ root })
ix.paths('src').include('*.ts')
ix.useVectors({ model: 'text-embedding-3-small' })

const db = new KiteDB({ root, path: '.argus-search/examples-main.kite' })
const t0 = performance.now()
const forceReindex = process.env.CODE_INTEL_REINDEX === '1'
const shouldIndex = forceReindex || !existsSync(db.path)
const ti0 = performance.now()
if (shouldIndex) await ix.persist({ db, clear: forceReindex, vector: true, graph: true })
const indexMs = shouldIndex ? performance.now() - ti0 : 0

const ts0 = performance.now()
const hits = await ix.search(query, { db, topK: 5, includeContent: true, contentContext: 1, contentMaxChars: 180 })
const searchMs = performance.now() - ts0
const totalMs = performance.now() - t0

console.log(`query ${query}`)
console.log(
  `index ${shouldIndex ? `${indexMs.toFixed(1)}ms` : 'cached'} | search ${searchMs.toFixed(1)}ms | total ${totalMs.toFixed(1)}ms\n`,
)
process.stdout.write(
  `${formatSearchHits(hits, { projectRoot: ix.root, context: 1, color, includeContentFallback: true })}\n`,
)

