const execFileAsync = promisify(execFile)

const DEFAULT_GRAPH_BUILD_TIMEOUT_MS = 240_000

const resolveGraphBuildTimeoutMs = () =>
  parsePositiveInt(process.env.INDEXER_GRAPH_BUILD_TIMEOUT_MS, DEFAULT_GRAPH_BUILD_TIMEOUT_MS)

const resolveGraphArtifactsRoot = () =>
  path.resolve(
    process.env.INDEXER_GRAPH_DIR?.trim() ||
      path.join(process.cwd(), ".indexer-artifacts", "graphs"),
  )

const ensureWithinRoot = (root: string, value: string) => {
  const resolvedRoot = path.resolve(root)
  const candidate = path.resolve(value)
  const rootWithSep = `${resolvedRoot}${path.sep}`
  if (candidate !== resolvedRoot && !candidate.startsWith(rootWithSep)) {
    throw new Error("Graph artifact path escapes root.")
  }
  return candidate
}

const resolveRunGraphDir = (artifactsPrefix: string) => {
  const root = resolveGraphArtifactsRoot()
  const runDir = ensureWithinRoot(root, path.join(root, artifactsPrefix))
  return { root, runDir }
}

const findExtractedRoot = async (extractDir: string): Promise<string> => {
  const entries = await readdir(extractDir, { withFileTypes: true })
  const directories = entries.filter((entry) => entry.isDirectory())
  if (directories.length === 1) {
    return path.join(extractDir, directories[0].name)
  }
  return extractDir
}

const extractArchive = async (
  archivePath: string,
): Promise<{ extractDir: string; repoRoot: string }> => {
  const extractDir = await mkdtemp(path.join(os.tmpdir(), "argus-indexer-graph-extract-"))
  await execFileAsync("tar", ["-xzf", archivePath, "-C", extractDir])
  const repoRoot = await findExtractedRoot(extractDir)
  return { extractDir, repoRoot }
}

type GraphManifest = {
  indexRunId: string
  generatedAt: string
  stats: {
    filesParsed: number
    chunksEmitted: number
    nodesEmitted: number
    edgesEmitted: number
  }
}

const parseManifest = (raw: string): GraphManifest => {
  const parsed = JSON.parse(raw) as Record<string, unknown>
  const stats = (parsed.stats ?? {}) as Record<string, unknown>
  const asCount = (value: unknown) =>
    typeof value === "number" && Number.isFinite(value) ? Math.max(0, Math.floor(value)) : 0
  return {
    indexRunId: String(parsed.indexRunId ?? "").trim(),
    generatedAt: String(parsed.generatedAt ?? "").trim(),
    stats: {
      filesParsed: asCount(stats.filesParsed),
      chunksEmitted: asCount(stats.chunksEmitted),
      nodesEmitted: asCount(stats.nodesEmitted),
      edgesEmitted: asCount(stats.edgesEmitted),
    },
  }
}

const assertFileExists = async (filePath: string) => {
  const details = await stat(filePath)
  if (!details.isFile()) {
    throw new Error(`Expected file at ${filePath}`)
  }
}

const resolveSourceIndexPackDir = async (repoRoot: string): Promise<string> => {
  const candidateDirs = [
    path.join(repoRoot, ".argus-search", "index-pack"),
    path.join(repoRoot, ".code-intelligence", "index-pack"),
  ]

  for (const candidateDir of candidateDirs) {
    try {
      await assertFileExists(path.join(candidateDir, "manifest.json"))
      return candidateDir
    } catch {
      // Try next known legacy/current location.
    }
  }

  throw new Error("Graph index-pack artifacts were not produced.")
}

