export type BuildRunGraphArtifactsResult = {
  backend: "kitedb_fs"
  graphStorePath: string
  indexPackDir: string
  indexRunId: string
  generatedAt: string
  stats: {
    filesParsed: number
    chunksEmitted: number
    nodesEmitted: number
    edgesEmitted: number
  }
  durationMs: number
}

export const buildRunGraphArtifacts = async (args: {
  source: GitLabSource
  integrationId: string
  headSha: string
  artifactsPrefix: string
  workspace?: RepoWorkspace
}): Promise<BuildRunGraphArtifactsResult> => {
  const startedAt = Date.now()
  const { runDir } = resolveRunGraphDir(args.artifactsPrefix)
  await mkdir(runDir, { recursive: true })

  const outputStorePath = path.join(runDir, "index.kite")
  const outputStoreManifestPath = `${outputStorePath}.manifest.json`
  const outputNodesPath = path.join(runDir, "graph.nodes.jsonl")
  const outputEdgesPath = path.join(runDir, "graph.edges.jsonl")
  const outputIndexPackManifestPath = path.join(runDir, "index-pack.manifest.json")
  const outputIndexPackDir = runDir

  let archiveRootDir: string | null = null
  let extractDir: string | null = null

  try {
    const repoRoot = await (async () => {
      if (args.workspace) {
        return args.workspace.rootDir
      }

      const { archivePath } = await args.source.downloadArchive({
        integrationId: args.integrationId,
        sha: args.headSha,
      })
      archiveRootDir = path.dirname(archivePath)
      const extracted = await extractArchive(archivePath)
      extractDir = extracted.extractDir
      return extracted.repoRoot
    })()

const sdkProjectRoot = await realpath(repoRoot).catch(() => repoRoot)
const sourceStorePath = path.join(sdkProjectRoot, ".argus-search", "index.kite")
const sourceStoreManifestPath = `${sourceStorePath}.manifest.json`
const tempConfigPath = path.join(sdkProjectRoot, ".argus-search.graph.json")
await Promise.all([
  mkdir(path.dirname(sourceStorePath), { recursive: true }),
  writeFile(tempConfigPath, JSON.stringify(graphConfig, null, 2), "utf8"),
])

try {
  await runWatchOnce({
    projectRoot: sdkProjectRoot,
    configPath: tempConfigPath,
    storePath: ".argus-search/index.kite",
    phases: ["parse", "graph", "indexPack"],
    noVector: true,
    timeoutMs: resolveGraphBuildTimeoutMs(),
  })
} catch (error) {
  if (error instanceof CodeIntelSdkError) {
    if (error.code === "sdk_missing") {
      throw new Error("The Argus Search SDK is not available in this runtime.")
    }

    const wrapped = new Error("Failed to build graph artifacts.")
    ;(wrapped as Error & { details?: Record<string, unknown> }).details = {
      message: error.message,
      details: error.details,
    }
    throw wrapped
  }

  const wrapped = new Error("Failed to build graph artifacts.")
  ;(wrapped as Error & { details?: Record<string, unknown> }).details = {
    message: error instanceof Error ? error.message : "Unknown command failure.",
  }
  throw wrapped
} finally {
  await rm(tempConfigPath, { force: true }).catch(() => {})
}

const sourceIndexPackDir = await resolveSourceIndexPackDir(sdkProjectRoot)
const sourceIndexPackManifestPath = path.join(sourceIndexPackDir, "manifest.json")
const sourceNodesPath = path.join(sourceIndexPackDir, "graph.nodes.jsonl")
const sourceEdgesPath = path.join(sourceIndexPackDir, "graph.edges.jsonl")

await Promise.all([
  assertFileExists(sourceStorePath),
  assertFileExists(sourceStoreManifestPath),
  assertFileExists(sourceIndexPackManifestPath),
  assertFileExists(sourceNodesPath),
  assertFileExists(sourceEdgesPath),
])

await Promise.all([
  copyFile(sourceStorePath, outputStorePath),
  copyFile(sourceStoreManifestPath, outputStoreManifestPath),
  copyFile(sourceNodesPath, outputNodesPath),
  copyFile(sourceEdgesPath, outputEdgesPath),
  copyFile(sourceIndexPackManifestPath, outputIndexPackManifestPath),
])

const manifest = parseManifest(await readFile(outputIndexPackManifestPath, "utf8"))
return {
  backend: "kitedb_fs",
  graphStorePath: outputStorePath,
  indexPackDir: outputIndexPackDir,
  indexRunId: manifest.indexRunId,
  generatedAt: manifest.generatedAt,
  stats: manifest.stats,
  durationMs: Date.now() - startedAt,
}

  } catch (error) {
    const wrapped = new Error(error instanceof Error ? error.message : "Failed to build graph artifacts.")
    ;(wrapped as Error & { details?: Record<string, unknown> }).details = {
      integrationId: args.integrationId,
      headSha: args.headSha,
      artifactsPrefix: args.artifactsPrefix,
      message: errorMessage(error),
      details:
        error instanceof Error
          ? ((error as Error & { details?: Record<string, unknown> }).details ?? null)
          : null,
    }
    throw wrapped
  } finally {
    if (extractDir) {
      await rm(extractDir, { recursive: true, force: true }).catch(() => {})
    }
    if (archiveRootDir) {
      await rm(archiveRootDir, { recursive: true, force: true }).catch(() => {})
    }
  }
}

import { useMemo } from "react"

import {
  getInstanceByKey,
  hashTokenForCache,
  RECENT_PROJECTS_LIMIT,
  resolveGitLabInstance,
} from "@/components/onboarding/onboarding-flow.utils"
import type { MergeRequest, Project } from "@/components/onboarding/onboarding-types"

type UseOnboardingDerivedStateOptions = {
  token: string
  gitlabInstance: string
  customInstance: string
  projects: Project[]
  selectedProjectId: string
  mergeRequests: MergeRequest[]
  selectedMergeRequestId: string
  projectSearchQuery: string
}

export function useOnboardingDerivedState({
  token,
  gitlabInstance,
  customInstance,
  projects,
  selectedProjectId,
  mergeRequests,
  selectedMergeRequestId,
  projectSearchQuery,
}: UseOnboardingDerivedStateOptions) {
  const selectedProject = projects.find((project) => project.id === selectedProjectId)
  const selectedMergeRequest = mergeRequests.find((mr) => mr.id === selectedMergeRequestId)

  const canLoadProjects = useMemo(
    () =>
      token.trim().length > 0 &&
      (getInstanceByKey(gitlabInstance).isCustom
        ? customInstance.trim().length > 0
        : getInstanceByKey(gitlabInstance).key.trim().length > 0),
    [token, gitlabInstance, customInstance],
  )

  const normalizedProjectSearchQuery = useMemo(
    () => projectSearchQuery.trim().toLowerCase(),
    [projectSearchQuery],
  )

  const filteredProjects = useMemo(() => {
    if (!normalizedProjectSearchQuery) {
      return projects
    }

    return projects.filter((project) => {
      const name = project.name.toLowerCase()
      const path = project.path.toLowerCase()
      return (
        name.includes(normalizedProjectSearchQuery) ||
        path.includes(normalizedProjectSearchQuery)
      )
    })
  }, [projects, normalizedProjectSearchQuery])

  const recentProjects = useMemo(
    () => filteredProjects.slice(0, RECENT_PROJECTS_LIMIT),
    [filteredProjects],
  )

  const resolvedGitLabInstance = useMemo(() => {
    if (!token.trim()) {
      return ""
    }

    try {
      return resolveGitLabInstance(gitlabInstance, customInstance)
    } catch {
      return ""
    }
  }, [token, gitlabInstance, customInstance])

  const tokenCacheHash = useMemo(() => {
    const trimmed = token.trim()
    if (!trimmed) {
      return ""
    }
    return hashTokenForCache(trimmed)
  }, [token])

  const projectsCacheKey = useMemo(() => {
    if (!tokenCacheHash) {
      return ""
    }

    try {
      const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
      return `${normalizedInstance}::${tokenCacheHash}`
    } catch {
      return ""
    }
  }, [tokenCacheHash, gitlabInstance, customInstance])

  return {
    selectedProject,
    selectedMergeRequest,
    canLoadProjects,
    normalizedProjectSearchQuery,
    recentProjects,
    resolvedGitLabInstance,
    tokenCacheHash,
    projectsCacheKey,
  }
}

#!/usr/bin/env node
const fs = require('node:fs')
const fsp = require('node:fs/promises')
const path = require('node:path')
