const { version: packageVersion } = require('./package.json')
const { normalizeSearchHits } = require('./search-contract.js')
const { formatSearchHits, resolveColorMode } = require('./search-format.js')
const { getColors, fmt, formatStatus, formatEvent, formatBox, formatKeyValue, stripAnsi } = require('./cli-format.js')

const COMMANDS = new Set([
  'index',
  'serve',
  'mcp',
  'init',
  'watch',
  'search',
  'trace',
  'doctor',
  'completions',
  'man',
  'help',
])

const DEFAULT_COMMAND = 'index'
const ALLOWED_PHASES = new Set(['parse', 'graph', 'vector', 'scip', 'indexPack'])
const TRACE_SUBCOMMANDS = new Set(['callers', 'impact'])
const DEFAULT_VECTOR_BASE_URL = 'https://api.openai.com/v1'
const DEFAULT_VECTOR_MODEL = 'text-embedding-3-small'
const DEFAULT_INIT_PATHS = ['.']
const DEFAULT_INIT_INCLUDE = ['*.ts', '*.tsx', '*.js', '*.jsx', '*.py', '*.cpp', '*.cc', '*.c', '*.hpp', '*.h', '*.ada']
const DEFAULT_INIT_EXCLUDE = [
  'node_modules',
  'dist',
  'build',
  'target',
  '.git',
  '.venv',
  '__pycache__',
  '.argus-search',
]

// Common options text (used in multiple places)

function formatCommonOptions(c) {
  const f = fmt(c)
  const lines = []
  for (const opt of COMMON_OPTIONS_DATA) {
    const flags = opt.short
      ? `${f.option(`-${opt.short}`)}, ${f.option(`--${opt.name}`)}`
      : `    ${f.option(`--${opt.name}`)}`
    const padded = stripAnsi(flags).length < 22 ? flags + ' '.repeat(22 - stripAnsi(flags).length) : flags
    lines.push(`  ${padded} ${c.dim}${opt.description}${c.reset}`)
  }
  return lines.join('\n')
}

function buildColorfulUsage(c) {
  const f = fmt(c)
  const lines = []

  // Header
  lines.push('')
  lines.push(`  ${c.cyan}${c.bold}argus-search${c.reset} ${c.dim}v${packageVersion}${c.reset}`)
  lines.push(`  ${c.dim}Rust-powered Argus Search CLI${c.reset}`)
  lines.push('')

  // Usage
  lines.push(`${c.bold}${c.underline}USAGE${c.reset}`)
  lines.push(`  ${f.command('argus-search')} ${c.yellow}<command>${c.reset} ${c.dim}[options]${c.reset}`)
  lines.push('')

  // Commands
  lines.push(`${c.bold}${c.underline}COMMANDS${c.reset}`)
  for (const cmd of COMMANDS_DATA) {
    const name = f.command(cmd.name.padEnd(14))
    lines.push(`  ${name} ${c.dim}${cmd.description}${c.reset}`)
  }
  lines.push('')

  // Common options
  lines.push(`${c.bold}${c.underline}OPTIONS${c.reset}`)
  lines.push(formatCommonOptions(c))
  lines.push('')

  // Footer
  lines.push(`${c.dim}Run ${f.command('argus-search help <command>')} for command-specific help${c.reset}`)
  lines.push('')

  return lines.join('\n')
}

// Plain text COMMON_OPTIONS used by COMMAND_USAGE for command help

}

function printUsage(command) {
  const c = getColors()

  if (command && COMMAND_USAGE[command]) {
    // Format command-specific help with colors
    const usage = COMMAND_USAGE[command]
    const formatted = usage
      // Color the "Usage:" header
      .replace(/^Usage:/m, `${c.bold}${c.underline}USAGE${c.reset}`)
      // Color the "Options:" header
      .replace(/^Options:/m, `${c.bold}${c.underline}OPTIONS${c.reset}`)
      // Color the "Supported shells:" header
      .replace(/^Supported shells:/m, `${c.bold}${c.underline}SUPPORTED SHELLS${c.reset}`)
      // Color command names in usage examples
      .replace(/argus-search/g, `${c.cyan}${c.bold}argus-search${c.reset}`)
      // Color option flags
      .replace(/(--[\w-]+)/g, `${c.yellow}$1${c.reset}`)
      .replace(/(-[a-z]),/g, `${c.yellow}$1${c.reset},`)
    process.stdout.write(`${formatted.trim()}\n`)
    return
  }

  // Use colorful main usage
  process.stdout.write(buildColorfulUsage(c))
}

function normalizePhase(phase) {
  const trimmed = phase.trim()
  if (trimmed === 'index-pack' || trimmed === 'indexpack') {
    return 'indexPack'
  }
  return trimmed
}

function parseArgs(argv) {
  const args = [...argv]
  let command = DEFAULT_COMMAND
  const flags = new Map()
  const positionals = []
  const errors = []

  if (args[0] && !args[0].startsWith('-')) {
    command = args.shift()
  }

if (command === 'help') {
  const target = args[0] && !args[0].startsWith('-') ? args[0] : undefined
  flags.set('help', true)
  if (target) {
    flags.set('help-target', target)
  }
  return { command, flags, positionals, errors }
}

if (!COMMANDS.has(command)) {
  return {
    command,
    flags,
    positionals,
    errors: [`unknown command: ${command}`],
  }
}

const optionDefs = OPTION_DEFS[command] ?? {}

  for (let i = 0; i < args.length; i += 1) {
    const arg = args[i]
    if (arg === '--') {
      positionals.push(...args.slice(i + 1))
      break
    }

    if (!arg.startsWith('-')) {
      positionals.push(arg)
      continue
    }

    if (arg === '-h' || arg === '--help') {
      flags.set('help', true)
      continue
    }
    if (arg === '-v' || arg === '--version') {
      flags.set('version', true)
      continue
    }

    let key = arg.replace(/^-+/, '')
    let value
    if (key.includes('=')) {
      const [k, v] = key.split('=')
      key = k
      value = v
    }

    const kind = optionDefs[key]
    if (!kind) {
      errors.push(`unknown option: --${key}`)
      continue
    }

    if (kind === 'boolean') {
      flags.set(key, true)
      continue
    }

    if (value === undefined) {
      const next = args[i + 1]
      if (!next || next.startsWith('-')) {
        errors.push(`missing value for --${key}`)
        continue
      }
      value = next
      i += 1
    }

    if (kind === 'list') {
      const existing = flags.get(key) ?? []
      const list = Array.isArray(existing) ? existing : [existing]
      list.push(value)
      flags.set(key, list)
    } else {
      flags.set(key, value)
    }
  }

  return { command, flags, positionals, errors }
}

function splitList(value) {
  if (!value) return []
  const values = Array.isArray(value) ? value : [value]
  return values
    .flatMap((entry) => entry.split(','))
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0)
}

function parseNumber(raw, label, { min, max } = {}) {
  if (raw === undefined || raw === null) return undefined
  const value = Number(raw)
  if (!Number.isFinite(value)) {
    throw new Error(`invalid ${label}: ${raw}`)
  }
  if (min !== undefined && value < min) {
    throw new Error(`invalid ${label}: ${raw}`)
  }
  if (max !== undefined && value > max) {
    throw new Error(`invalid ${label}: ${raw}`)
  }
  return value
}

async function loadConfig(configPath) {
  const raw = await fsp.readFile(configPath, 'utf8')
  return JSON.parse(raw)
}

async function pathExists(filePath) {
  if (!filePath) return false
  try {
    await fsp.access(filePath)
    return true
  } catch {
    return false
  }
}

async function resolveConfigPath(explicitPath) {
  if (explicitPath) {
    return path.resolve(String(explicitPath))
  }

  const candidates = ['argus-search.json', '.argus-search.json']
  let dir = process.cwd()
  while (true) {
    for (const candidate of candidates) {
      const candidatePath = path.resolve(dir, candidate)
      try {
        await fsp.access(candidatePath)
        return candidatePath
      } catch {
        // ignore missing file
      }
    }

    const parent = path.dirname(dir)
    if (parent === dir) break
    dir = parent
  }

  return null
}

function resolveBootstrapProjectRoot(flags, fallbackConfigPath) {
  const projectRootFlag = flags.get('project-root')
  if (projectRootFlag) {
    return path.resolve(String(projectRootFlag))
  }
  if (fallbackConfigPath) {
    return path.dirname(fallbackConfigPath)
  }
  const envRoot = process.env.CODE_INTELLIGENCE_PROJECT_ROOT || process.env.CODE_INTEL_PROJECT_ROOT
  if (envRoot) {
    return path.resolve(String(envRoot))
  }
  return process.cwd()
}

async function createAutoConfig(configPath, projectRoot, reason) {
  const resolvedConfigPath = path.resolve(configPath)
  const resolvedProjectRoot = path.resolve(projectRoot)
  await ensureProjectRoot(resolvedProjectRoot)

  const configDir = path.dirname(resolvedConfigPath)
  const relRoot = path.relative(configDir, resolvedProjectRoot)
  const configProjectRoot = normalizePath(relRoot || '.')
  const payload = buildInitConfig({
    paths: [...DEFAULT_INIT_PATHS],
    include: [...DEFAULT_INIT_INCLUDE],
    exclude: [...DEFAULT_INIT_EXCLUDE],
    vectorBaseUrl: DEFAULT_VECTOR_BASE_URL,
    vectorModel: DEFAULT_VECTOR_MODEL,
    incremental: true,
  })
  payload.projectRoot = configProjectRoot

  process.stderr.write(`[argus-search] ${reason}\n`)
  process.stderr.write(`[argus-search] Creating default config at ${resolvedConfigPath}\n`)

  await fsp.mkdir(configDir, { recursive: true })
  await fsp.writeFile(resolvedConfigPath, JSON.stringify(payload, null, 2))
  await fsp.mkdir(path.join(resolvedProjectRoot, '.argus-search'), { recursive: true })
  ensureGitignore(resolvedProjectRoot)

  process.stderr.write(
    `[argus-search] Created config (projectRoot=${configProjectRoot}, vector.model=${DEFAULT_VECTOR_MODEL})\n`,
  )
}

function resolveProjectRoot(configPath, options, overrideRoot) {
  if (overrideRoot) return overrideRoot
  if (configPath && options.projectRoot && !path.isAbsolute(options.projectRoot)) {
    return path.resolve(path.dirname(configPath), String(options.projectRoot))
  }
  if (options.projectRoot) return String(options.projectRoot)
  const envRoot = process.env.CODE_INTELLIGENCE_PROJECT_ROOT || process.env.CODE_INTEL_PROJECT_ROOT
  if (envRoot) return String(envRoot)
  if (configPath) return path.dirname(configPath)
  return process.cwd()
}

function applyInputOverrides(options, flags) {
  const paths = splitList(flags.get('paths'))
  const include = splitList(flags.get('include'))
  const exclude = splitList(flags.get('exclude'))
  const noGitignore = Boolean(flags.get('no-gitignore'))

  if (paths.length || include.length || exclude.length || noGitignore) {
    options.inputs = {
      ...options.inputs,
      ...(paths.length ? { paths } : {}),
      ...(include.length ? { include } : {}),
      ...(exclude.length ? { exclude } : {}),
      ...(noGitignore ? { respectGitignore: false } : {}),
    }
  }
}

function applyPhaseOverrides(options, flags) {
  const phases = splitList(flags.get('phases'))
  if (!phases.length) return
  const normalized = phases.map((phase) => normalizePhase(phase))
  const unknown = normalized.filter((phase) => !ALLOWED_PHASES.has(phase))
  if (unknown.length) {
    throw new Error(`unknown phase(s): ${unknown.join(', ')} (allowed: ${Array.from(ALLOWED_PHASES).join(', ')})`)
  }
  const enabled = new Set(normalized)
  options.phases = {
    ...options.phases,
    parse: enabled.has('parse'),
    graph: enabled.has('graph'),
    vector: enabled.has('vector'),
    scip: enabled.has('scip'),
    indexPack: enabled.has('indexPack'),
  }
}

async function loadOptions(flags, { requireConfig } = { requireConfig: false }) {
  const explicitConfig = flags.get('config')
  let configPath = await resolveConfigPath(explicitConfig)
  let configExists = await pathExists(configPath)
  if (!configExists) {
    const bootstrapRoot = resolveBootstrapProjectRoot(flags, configPath)
    const nextConfigPath = configPath || path.join(bootstrapRoot, 'argus-search.json')
    const reason = explicitConfig
      ? `Config not found at ${nextConfigPath}; bootstrapping with defaults.`
      : `No config found via find-up from ${process.cwd()}; bootstrapping with defaults.`
    await createAutoConfig(nextConfigPath, bootstrapRoot, reason)
    configPath = nextConfigPath
    configExists = true
  }
  if (requireConfig && !configExists) {
    throw new Error('config not found (run: argus-search init)')
  }
  const options = configPath ? await loadConfig(configPath) : {}
  const projectRootFlag = flags.get('project-root')
  const projectRoot = resolveProjectRoot(configPath, options, projectRootFlag && String(projectRootFlag))
  options.projectRoot = projectRoot

  applyInputOverrides(options, flags)
  applyPhaseOverrides(options, flags)

  return { options, configPath }
}

async function ensureProjectRoot(projectRoot) {
  try {
    const stat = await fsp.stat(projectRoot)
    if (!stat.isDirectory()) {
      throw new Error('project root is not a directory')
    }
  } catch (error) {
    throw new Error(
      `project root not found: ${projectRoot} (${error instanceof Error ? error.message : String(error)})`,
    )
  }
}

function resolveStorePath(projectRoot, storeFlag) {
  const storePath = storeFlag ? String(storeFlag) : '.argus-search/index.kite'
  return path.isAbsolute(storePath) ? storePath : path.join(projectRoot, storePath)
}

function resolveVectorProvider(options, flags, { preferDefaults = false } = {}) {
  let provider = options?.vector?.provider ? { ...options.vector.provider } : null
  if (provider?.kind && provider.kind !== 'http') {
    throw new Error(`unsupported vector provider kind: ${provider.kind}`)
  }

  const baseUrl = flags.get('vector-base-url')
  const model = flags.get('vector-model')
  const apiKey = flags.get('vector-api-key')
  const dimension = flags.get('vector-dimension')
  const timeoutMs = flags.get('vector-timeout-ms')
  const envKey = process.env.OPENAI_API_KEY

  const hasOverride =
    baseUrl !== undefined ||
    model !== undefined ||
    apiKey !== undefined ||
    dimension !== undefined ||
    timeoutMs !== undefined ||
    Boolean(envKey)

  if (!provider && (hasOverride || preferDefaults)) {
    provider = {
      kind: 'http',
      baseUrl: baseUrl ?? DEFAULT_VECTOR_BASE_URL,
      model: model ?? DEFAULT_VECTOR_MODEL,
    }
  }

  if (provider) {
    if (!provider.kind) provider.kind = 'http'
    if (provider.kind !== 'http') {
      throw new Error(`unsupported vector provider kind: ${provider.kind}`)
    }
    if (!provider.baseUrl) provider.baseUrl = DEFAULT_VECTOR_BASE_URL
    if (!provider.model) provider.model = DEFAULT_VECTOR_MODEL
    if (baseUrl) provider.baseUrl = String(baseUrl)
    if (model) provider.model = String(model)
    if (apiKey) provider.apiKey = String(apiKey)
    if (!provider.apiKey && envKey) provider.apiKey = envKey
    if (dimension !== undefined) {
      provider.dimension = parseNumber(dimension, 'vector-dimension', { min: 1 })
    }
    if (timeoutMs !== undefined) {
      provider.timeoutMs = parseNumber(timeoutMs, 'vector-timeout-ms', { min: 1 })
    }
  }

  if (provider && (!provider.baseUrl || !provider.model)) {
    throw new Error('vector provider requires baseUrl and model')
  }

  return provider
}

function ensureGitignore(projectRoot) {
  const gitignorePath = path.join(projectRoot, '.gitignore')
  const entry = '.argus-search/'
  let existing = ''
  try {
    existing = fs.readFileSync(gitignorePath, 'utf8')
  } catch {
    existing = ''
  }
  if (existing.includes(entry)) {
    return
  }
  let updated = existing
  if (updated.length > 0 && !updated.endsWith('\n')) {
    updated += '\n'
  }
  updated += '\n# argus-search\n'
  updated += `${entry}\n`
  fs.writeFileSync(gitignorePath, updated)
}

function buildInitConfig({ paths, include, exclude, vectorBaseUrl, vectorModel, incremental }) {
  return {
    projectRoot: '.',
    inputs: {
      paths,
      include,
      exclude,
      respectGitignore: true,
    },
    phases: { parse: true, graph: true, vector: true, scip: false, indexPack: false },
    vector: {
      provider: {
        kind: 'http',
        baseUrl: vectorBaseUrl,
        model: vectorModel,
      },
    },
    cache: { enabled: incremental, force: false },
    output: { incremental },
  }
}

function getBinding() {
  const mod = require('./index.js')
  return mod?.default ?? mod
}

function normalizePath(value) {
  return String(value).replace(/\\/g, '/')
}

function emitWatchEvent(json, event, storePath, message) {
  if (json) {
    const payload = {
      event,
      storePath,
      message,
      timestampMs: Date.now(),
    }
    process.stdout.write(`${JSON.stringify(payload)}\n`)
  } else {
    const c = getColors()
    process.stderr.write(`${formatEvent(c, event, message)}\n`)
  }
}

function installSignalFlag(onSignal) {
  const signals = ['SIGINT', 'SIGTERM']
  const handlers = signals.map((signal) => {
    const handler = () => onSignal(signal)
    process.once(signal, handler)
    return { signal, handler }
  })
  return () => {
    for (const { signal, handler } of handlers) {
      process.off(signal, handler)
    }
  }
}

function waitForTermination(onTerminate) {
  return new Promise((resolve, reject) => {
    let done = false
    const cleanup = installSignalFlag(async () => {
      if (done) return
      done = true
      cleanup()
      try {
        await onTerminate()
        resolve(null)
      } catch (error) {
        reject(error)
      }
    })
  })
}

function compileGlob(pattern) {
  const esc = (value) => value.replace(/[.+^${}()|[\]\\]/g, '\\$&')
  let re = ''
  let i = 0
  while (i < pattern.length) {
    const ch = pattern[i]
    if (ch === '*') {
      if (pattern[i + 1] === '*') {
        re += '.*'
        i += 2
      } else {
        re += '[^/]*'
        i += 1
      }
      continue
    }
    if (ch === '?') {
      re += '[^/]'
      i += 1
      continue
    }
    re += esc(ch)
    i += 1
  }
  return new RegExp(`^${re}$`)
}

function compilePatterns(patterns) {
  const globPatterns = []
  const namePatterns = new Set()
  const substringPatterns = []

  for (const raw of patterns) {
    if (!raw) continue
    const value = normalizePath(raw)
    if (/[*?]/.test(value)) {
      globPatterns.push({ raw: value, regex: compileGlob(value) })
    } else if (value.includes('/')) {
      substringPatterns.push(value)
    } else {
      namePatterns.add(value)
    }
  }

  return { globPatterns, namePatterns, substringPatterns }
}

function loadGitignorePatterns(projectRoot) {
  const gitignorePath = path.join(projectRoot, '.gitignore')
  let raw = ''
  try {
    raw = fs.readFileSync(gitignorePath, 'utf8')
  } catch {
    return []
  }

  return raw
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0 && !line.startsWith('#'))
    .filter((line) => !line.startsWith('!'))
    .map((line) => (line.startsWith('/') ? line.slice(1) : line))
}

function matchPatterns(relativePath, name, compiled) {
  if (compiled.namePatterns.has(name)) return true
  if (compiled.substringPatterns.some((value) => relativePath.includes(value))) return true
  return compiled.globPatterns.some(({ regex, raw }) => {
    if (raw.includes('/')) return regex.test(relativePath)
    return regex.test(name)
  })
}

async function discoverFiles(projectRoot, inputs) {
  const paths = (inputs?.paths ?? []).map((entry) => (path.isAbsolute(entry) ? entry : path.join(projectRoot, entry)))
  const includePatterns = compilePatterns(inputs?.include ?? [])
  const excludePatterns = compilePatterns(inputs?.exclude ?? [])
  const gitignorePatterns = inputs?.respectGitignore ? compilePatterns(loadGitignorePatterns(projectRoot)) : null

  const files = []
  const seen = new Set()

const visit = async (target) => {
  let stat
  try {
    stat = await fsp.lstat(target)
  } catch {
    return
  }
  if (stat.isSymbolicLink()) return
  if (stat.isDirectory()) {
    let rel = normalizePath(path.relative(projectRoot, target))
    if (rel === '') rel = '.'
    const name = path.basename(target)
    if (matchPatterns(rel, name, excludePatterns)) {
      return
    }
    let entries
    try {
      entries = await fsp.readdir(target)
    } catch {
      return
    }
    for (const entry of entries) {
      await visit(path.join(target, entry))
    }
    return
  }

  const relPath = normalizePath(path.relative(projectRoot, target))
  const name = path.basename(target)
  if (gitignorePatterns && matchPatterns(relPath, name, gitignorePatterns)) {
    return
  }
  if (matchPatterns(relPath, name, excludePatterns)) {
    return
  }
  if (inputs?.include?.length) {
    if (!matchPatterns(relPath, name, includePatterns)) {
      return
    }
  }
  if (!seen.has(target)) {
    seen.add(target)
    files.push(target)
  }
}

if (!paths.length) {
  await visit(projectRoot)
} else {
  for (const entry of paths) {
    await visit(entry)
  }
}

return files

}

async function snapshotFiles(projectRoot, inputs) {
  const files = await discoverFiles(projectRoot, inputs)
  const snapshot = new Map()
  for (const file of files) {
    try {
      const stat = await fsp.stat(file)
      snapshot.set(file, `${stat.mtimeMs}:${stat.size}`)
    } catch {
      // ignore
    }
  }
  return snapshot
}

async function runInit(flags) {
  const c = getColors()
  const f = fmt(c)
  const projectRoot = flags.get('project-root') ? String(flags.get('project-root')) : process.cwd()
  const outPath = flags.get('out') ? String(flags.get('out')) : path.join(projectRoot, 'argus-search.json')
  const force = Boolean(flags.get('force'))

  if (fs.existsSync(outPath) && !force) {
    throw new Error(`config already exists at ${outPath}; pass --force to overwrite`)
  }

  const paths = splitList(flags.get('paths'))
  const include = splitList(flags.get('include'))
  const exclude = splitList(flags.get('exclude'))

  const finalPaths = paths.length ? paths : [...DEFAULT_INIT_PATHS]
  const finalInclude = include.length ? include : [...DEFAULT_INIT_INCLUDE]
  const finalExclude = exclude.length ? exclude : [...DEFAULT_INIT_EXCLUDE]

  const incremental = !flags.get('no-incremental')
  const vectorBaseUrl = flags.get('vector-base-url') ? String(flags.get('vector-base-url')) : DEFAULT_VECTOR_BASE_URL
  const vectorModel = flags.get('vector-model') ? String(flags.get('vector-model')) : DEFAULT_VECTOR_MODEL

const { options } = await loadOptions(flags, { requireConfig: true })
await ensureProjectRoot(options.projectRoot)

const storePath = resolveStorePath(options.projectRoot, flags.get('store'))
const pollMs = parseNumber(flags.get('poll-ms'), 'poll-ms', { min: 50 }) ?? 1000
const debounceMs = parseNumber(flags.get('debounce-ms'), 'debounce-ms', { min: 0 }) ?? 750
const once = Boolean(flags.get('once'))
const json = Boolean(flags.get('json'))

if (flags.get('no-vector')) {
  options.phases = { ...options.phases, vector: false }
}

if (options.phases?.vector !== false && !options.vector?.provider) {
  throw new Error('vector.provider is required for semantic search; pass --no-vector or run: argus-search init')
}

const binding = getBinding()
const indexToKiteDb = binding.indexToKiteDb
if (typeof indexToKiteDb !== 'function') {
  throw new Error('indexToKiteDb not available in native binding')
}

let lastSeen = new Map()
let lastIndexAt = 0
let stopping = false
const cleanupSignals = installSignalFlag((signal) => {
  stopping = true
  emitWatchEvent(json, 'stopping', storePath, `Received ${signal}; shutting down watch...`)
})

try {
  while (!stopping) {
    let current
    try {
      current = await snapshotFiles(options.projectRoot, options.inputs)
    } catch (error) {
      emitWatchEvent(json, 'error', storePath, `Failed to discover files: ${error}`)
      await new Promise((resolve) => setTimeout(resolve, pollMs))
      continue
    }

    let changed = false
    if (lastSeen.size === 0) {
      changed = true
    } else if (current.size !== lastSeen.size) {
      changed = true
    } else {
      for (const [file, sig] of current.entries()) {
        if (lastSeen.get(file) !== sig) {
          changed = true
          break
        }
      }
    }

    if (changed) {
      const now = Date.now()
      if (lastIndexAt && now - lastIndexAt < debounceMs) {
        await new Promise((resolve) => setTimeout(resolve, pollMs))
        continue
      }
      emitWatchEvent(json, 'index_start', storePath, `Indexing into ${storePath} ...`)
      try {
        await indexToKiteDb(options, { path: storePath, clear: false })
        lastIndexAt = Date.now()
        emitWatchEvent(json, 'index_complete', storePath, 'Index complete.')
      } catch (error) {
        emitWatchEvent(json, 'error', storePath, `Index failed: ${error}`)
        if (once) throw error
        await new Promise((resolve) => setTimeout(resolve, pollMs))
        continue
      }
      if (once) break
    }

    lastSeen = current
    await new Promise((resolve) => setTimeout(resolve, pollMs))
  }
} finally {
  cleanupSignals()
}

}

async function runSearch(flags, query) {
  const { options } = await loadOptions(flags, { requireConfig: false })
  await ensureProjectRoot(options.projectRoot)
  const text = String(query ?? '').trim()
  if (!text) {
    throw new Error('query cannot be empty')
  }

  const storePath = resolveStorePath(options.projectRoot, flags.get('store'))
  if (!fs.existsSync(storePath)) {
    throw new Error(`index not found at ${storePath}; run: argus-search watch --once`)
  }

  const provider = resolveVectorProvider(options, flags)
  if (!provider) {
    throw new Error(
      'vector provider missing; run: argus-search init (or pass --vector-base-url/--vector-model and set OPENAI_API_KEY)',
    )
  }

  if (options.phases?.vector === false) {
    throw new Error('phases.vector is false; enable it to use search')
  }

  const binding = getBinding()
  const searchKiteDb = binding.searchKiteDb
  if (typeof searchKiteDb !== 'function') {
    throw new Error('searchKiteDb not available in native binding')
  }

  const topK = parseNumber(flags.get('top-k'), 'top-k', { min: 1, max: 50 }) ?? 5
  const context = parseNumber(flags.get('context'), 'context', { min: 0, max: 100 }) ?? 2
  const includeContent = Boolean(flags.get('include-content'))
  const includeImpact = Boolean(flags.get('impact'))
  const contentMaxChars =
    parseNumber(flags.get('content-max-chars'), 'content-max-chars', { min: 256, max: 200000 }) ?? 4000
  const colorMode = flags.get('color') == null ? 'auto' : String(flags.get('color'))
  resolveColorMode(colorMode)

const hits = normalizeSearchHits(
  await searchKiteDb({
    projectRoot: options.projectRoot,
    store: { path: storePath },
    query: text,
    topK,
    includeContent,
    contentContext: context,
    contentMaxChars,
    vectorProvider: provider,
  }),
  'searchKiteDb',
)

let impactByChunkId = new Map()
if (includeImpact && hits.length > 0) {
  const traceCallersKiteDb = binding.traceCallersKiteDb
  if (typeof traceCallersKiteDb !== 'function') {
    throw new Error('traceCallersKiteDb not available in native binding')
  }

  const callersCache = new Map()
  const impactPromises = hits.map(async (hit) => {
    const impact = await collectTransitiveCallImpact(traceCallersKiteDb, {
      projectRoot: options.projectRoot,
      storePath,
      nodeId: hit.chunkId,
      callersCache,
    })
    return [hit.chunkId, impact]
  })
  const resolved = await Promise.all(impactPromises)
  impactByChunkId = new Map(resolved)
}

if (flags.get('json')) {
  if (!includeImpact) {
    process.stdout.write(`${JSON.stringify(hits, null, 2)}\n`)
    return
  }
  const payload = hits.map((hit) => ({ ...hit, impact: impactByChunkId.get(hit.chunkId) ?? [] }))
  process.stdout.write(`${JSON.stringify(payload, null, 2)}\n`)
  return
}

const sections = []
const formattedHits = formatSearchHits(hits, {
  projectRoot: options.projectRoot,
  context,
  color: colorMode,
  includeContentFallback: includeContent,
})
if (formattedHits) {
  sections.push(formattedHits)
}

  if (includeImpact && hits.length > 0) {
    sections.push(formatImpactSections(hits, impactByChunkId))
  }

  process.stdout.write(`${sections.join('\n\n')}\n`)
}

async function loadCallers(traceCallersKiteDb, projectRoot, storePath, nodeId, callersCache) {
  if (callersCache.has(nodeId)) {
    return callersCache.get(nodeId)
  }
  const callers = await traceCallersKiteDb({
    projectRoot,
    store: { path: storePath },
    nodeId,
    limit: 200,
  })
  const normalized = Array.isArray(callers) ? callers : []
  callersCache.set(nodeId, normalized)
  return normalized
}

async function collectTransitiveCallImpact(
  traceCallersKiteDb,
  { projectRoot, storePath, nodeId, name, callersCache },
  { maxDepth = 3, limit = 200 } = {},
) {
  const visited = new Set()
  const queue = []
  const out = []

if (nodeId) {
  visited.add(nodeId)
  queue.push({ nodeId, depth: 0 })
} else if (name) {
  const seedCallersRaw = await traceCallersKiteDb({
    projectRoot,
    store: { path: storePath },
    name,
    limit: Math.min(limit, 200),
  })
  const seedCallers = Array.isArray(seedCallersRaw) ? seedCallersRaw : []
  for (const caller of seedCallers) {
    const callerId = caller?.id ? String(caller.id) : ''
    if (!callerId || visited.has(callerId)) {
      continue
    }
    visited.add(callerId)
    out.push({
      depth: 1,
      node: {
        id: callerId,
        kind: caller?.kind ?? null,
        name: caller?.name ?? null,
        filePath: caller?.filePath ?? null,
        rangeJson: caller?.rangeJson ?? null,
      },
    })
    if (out.length >= limit || maxDepth <= 1) {
      return out
    }
    queue.push({ nodeId: callerId, depth: 1 })
  }
} else {
  throw new Error('impact traversal requires nodeId or name')
}

while (queue.length > 0) {
  const current = queue.shift()
  if (!current || current.depth >= maxDepth) {
    continue
  }

  const callers = await loadCallers(traceCallersKiteDb, projectRoot, storePath, current.nodeId, callersCache)
  for (const caller of callers) {
    const callerId = caller?.id ? String(caller.id) : ''
    if (!callerId || visited.has(callerId)) {
      continue
    }
    const nextDepth = current.depth + 1
    visited.add(callerId)
    out.push({
      depth: nextDepth,
      node: {
        id: callerId,
        kind: caller?.kind ?? null,
        name: caller?.name ?? null,
        filePath: caller?.filePath ?? null,
        rangeJson: caller?.rangeJson ?? null,
      },
    })
    if (out.length >= limit) {
      return out
    }
    queue.push({ nodeId: callerId, depth: nextDepth })
  }
}

return out

}

function formatImpactSections(hits, impactByChunkId) {
  const c = getColors()
  const lines = [`\n${c.bold}${c.underline}IMPACT${c.reset} ${c.dim}(transitive callers, max depth 3)${c.reset}`]

  for (const hit of hits) {
    lines.push(`\n${c.cyan}${c.bold}${hit.chunkId}${c.reset}`)
    const impact = impactByChunkId.get(hit.chunkId) ?? []
    if (!impact.length) {
      lines.push(`  ${c.dim}(no callers found)${c.reset}`)
      continue
    }
    for (const entry of impact) {
      const depth = `${c.yellow}d${entry.depth}${c.reset}`
      const id = `${c.magenta}${entry.node.id}${c.reset}`
      const name = entry.node.name ? `  ${c.green}${entry.node.name}${c.reset}` : ''
      const filePath = entry.node.filePath ? `  ${c.blue}${entry.node.filePath}${c.reset}` : ''
      lines.push(`  ${depth}  ${id}${name}${filePath}`)
    }
  }

  return lines.join('\n')
}

async function runTrace(flags, subcommand, name) {
  if (!TRACE_SUBCOMMANDS.has(subcommand)) {
    throw new Error(`unknown trace subcommand: ${subcommand}`)
  }

  const { options } = await loadOptions(flags, { requireConfig: false })
  await ensureProjectRoot(options.projectRoot)

  const storePath = resolveStorePath(options.projectRoot, flags.get('store'))
  if (!fs.existsSync(storePath)) {
    throw new Error(`index not found at ${storePath}; run: argus-search watch --once`)
  }

  const binding = getBinding()
  const traceCallersKiteDb = binding.traceCallersKiteDb
  if (typeof traceCallersKiteDb !== 'function') {
    throw new Error('traceCallersKiteDb not available in native binding')
  }

const defaultLimit = subcommand === 'impact' ? 200 : 50
const limit = parseNumber(flags.get('limit'), 'limit', { min: 1, max: 500 }) ?? defaultLimit
const depth = subcommand === 'impact' ? parseNumber(flags.get('depth'), 'depth', { min: 1, max: 64 }) ?? 3 : 1
const nodeId = flags.get('node-id') ? String(flags.get('node-id')) : undefined

if (!nodeId && !name) {
  throw new Error(`trace ${subcommand} requires a name or --node-id`)
}

const c = getColors()

if (subcommand === 'callers') {
  const neighbors = await traceCallersKiteDb({
    projectRoot: options.projectRoot,
    store: { path: storePath },
    name,
    nodeId,
    limit,
  })

  if (flags.get('json')) {
    process.stdout.write(`${JSON.stringify(neighbors, null, 2)}\n`)
    return
  }

  if (!neighbors.length) {
    process.stdout.write(`${c.yellow}No callers found${c.reset}\n`)
    return
  }

  process.stdout.write(`\n${c.bold}${c.underline}CALLERS${c.reset} ${c.dim}(${neighbors.length} found)${c.reset}\n\n`)

  for (const [idx, neighbor] of neighbors.entries()) {
    const num = `${c.dim}${String(idx + 1).padStart(3)}${c.reset}`
    const id = `${c.cyan}${neighbor.id}${c.reset}`
    const name = neighbor.name ? `  ${c.yellow}${neighbor.name}${c.reset}` : ''
    const filePath = neighbor.filePath ? `  ${c.blue}${neighbor.filePath}${c.reset}` : ''
    process.stdout.write(`${num}  ${id}${name}${filePath}\n`)
  }
  process.stdout.write('\n')
  return
}

  const impact = await collectTransitiveCallImpact(
    traceCallersKiteDb,
    {
      projectRoot: options.projectRoot,
      storePath,
      nodeId,
      name,
      callersCache: new Map(),
    },
    { maxDepth: depth, limit },
  )

  if (flags.get('json')) {
    process.stdout.write(`${JSON.stringify(impact, null, 2)}\n`)
    return
  }

  if (!impact.length) {
    process.stdout.write(`${c.yellow}No impact callers found${c.reset}\n`)
    return
  }

  process.stdout.write(
    `\n${c.bold}${c.underline}IMPACT${c.reset} ${c.dim}(transitive callers, max depth ${depth}, ${impact.length} found)${c.reset}\n\n`,
  )
  for (const entry of impact) {
    const depthLabel = `${c.yellow}d${entry.depth}${c.reset}`
    const id = `${c.magenta}${entry.node.id}${c.reset}`
    const impactName = entry.node.name ? `  ${c.green}${entry.node.name}${c.reset}` : ''
    const filePath = entry.node.filePath ? `  ${c.blue}${entry.node.filePath}${c.reset}` : ''
    process.stdout.write(`  ${depthLabel}  ${id}${impactName}${filePath}\n`)
  }
  process.stdout.write('\n')
}

async function runDoctor(flags) {
  const { options, configPath } = await loadOptions(flags, { requireConfig: false })
  const projectRoot = options.projectRoot
  const storePath = resolveStorePath(projectRoot, flags.get('store'))
  const results = []
  const fixes = []

  if (configPath) {
    results.push({ status: 'ok', name: 'config', message: `loaded ${configPath}` })
  } else {
    results.push({ status: 'warn', name: 'config', message: 'not found (run: argus-search init)' })
  }

if (fs.existsSync(projectRoot)) {
  const stat = fs.statSync(projectRoot)
  if (stat.isDirectory()) {
    results.push({ status: 'ok', name: 'projectRoot', message: projectRoot })
  } else {
    results.push({ status: 'error', name: 'projectRoot', message: `not a directory: ${projectRoot}` })
  }
} else {
  results.push({ status: 'error', name: 'projectRoot', message: `not found: ${projectRoot}` })
}

if (flags.get('fix') && fs.existsSync(projectRoot) && fs.statSync(projectRoot).isDirectory()) {
  const ciDir = path.join(projectRoot, '.argus-search')
  if (!fs.existsSync(ciDir)) {
    try {
      fs.mkdirSync(ciDir, { recursive: true })
      fixes.push(`created ${ciDir}`)
    } catch (error) {
      results.push({ status: 'warn', name: 'fix', message: `failed to create ${ciDir}: ${error}` })
    }
  }

  try {
    ensureGitignore(projectRoot)
    fixes.push('ensured .gitignore includes .argus-search/')
  } catch (error) {
    results.push({ status: 'warn', name: 'fix', message: `failed to update .gitignore: ${error}` })
  }

  const storeDir = path.dirname(storePath)
  if (!fs.existsSync(storeDir)) {
    try {
      fs.mkdirSync(storeDir, { recursive: true })
      fixes.push(`created store dir ${storeDir}`)
    } catch (error) {
      results.push({ status: 'warn', name: 'fix', message: `failed to create store dir ${storeDir}: ${error}` })
    }
  }
}

const storeDir = path.dirname(storePath)

if (fs.existsSync(storeDir)) {
  if (!fs.statSync(storeDir).isDirectory()) {
    results.push({ status: 'error', name: 'storePath', message: `store parent is not a directory: ${storeDir}` })
  } else if (fs.existsSync(storePath)) {
    results.push({ status: 'ok', name: 'storePath', message: `found ${storePath}` })
  } else {
    results.push({
      status: 'warn',
      name: 'storePath',
      message: `not found (run: argus-search watch --once) at ${storePath}`,
    })
  }
} else {
  results.push({
    status: 'warn',
    name: 'storePath',
    message: `parent does not exist (will be created on watch): ${storeDir}`,
  })
}

if (options.inputs?.paths?.length) {
  const missing = []
  for (const raw of options.inputs.paths) {
    const resolved = path.isAbsolute(raw) ? raw : path.join(projectRoot, raw)
    if (!fs.existsSync(resolved)) missing.push(raw)
  }
  if (missing.length) {
    results.push({ status: 'warn', name: 'inputs', message: `missing paths: ${missing.join(', ')}` })
  } else {
    results.push({ status: 'ok', name: 'inputs', message: 'all input paths exist' })
  }
} else {
  results.push({ status: 'warn', name: 'inputs', message: 'inputs.paths not set (defaults apply)' })
}

const vectorEnabled = options.phases?.vector !== false

if (!vectorEnabled) {
  results.push({ status: 'ok', name: 'vector', message: 'disabled (phases.vector=false)' })
} else {
  const provider = options?.vector?.provider ? { ...options.vector.provider } : null
  if (!provider) {
    results.push({ status: 'error', name: 'vector', message: 'vector.provider is required for semantic search' })
  } else {
    if (provider.kind && provider.kind !== 'http') {
      results.push({ status: 'error', name: 'vector', message: `unsupported provider kind: ${provider.kind}` })
    }
    if (!provider.baseUrl) {
      results.push({ status: 'error', name: 'vector', message: 'provider.baseUrl is empty' })
    }
    if (!provider.model) {
      results.push({ status: 'error', name: 'vector', message: 'provider.model is empty' })
    }
    if (!provider.apiKey) {
      const envKey = process.env.OPENAI_API_KEY
      if (envKey) {
        provider.apiKey = envKey
      } else {
        results.push({
          status: 'warn',
          name: 'vector',
          message: 'no API key found (set OPENAI_API_KEY if provider requires auth)',
        })
      }
    }

    if (flags.get('network')) {
      try {
        await checkVectorNetwork(provider)
        results.push({ status: 'ok', name: 'vector.network', message: 'embeddings request succeeded' })
      } catch (error) {
        results.push({ status: 'error', name: 'vector.network', message: String(error) })
      }
    }
  }
}

const hasError = results.some((item) => item.status === 'error')

if (flags.get('json')) {
  process.stdout.write(
    `${JSON.stringify(
      {
        ok: !hasError,
        fixes,
        checks: results.map((item) => ({
          name: item.name,
          status: item.status,
          message: item.message,
        })),
      },
      null,
      2,
    )}\n`,
  )
} else {
  const c = getColors()
  const f = fmt(c)

  // Header
  process.stdout.write('\n')
  process.stdout.write(`  ${c.cyan}${c.bold}argus-search doctor${c.reset}\n`)
  process.stdout.write(`  ${c.dim}Diagnosing configuration and environment${c.reset}\n`)
  process.stdout.write('\n')

  // Fixes section (if --fix was used)
  if (flags.get('fix')) {
    if (!fixes.length) {
      process.stdout.write(`${f.symbols.check} ${c.green}No fixes needed${c.reset}\n\n`)
    } else {
      process.stdout.write(`${c.bold}${c.underline}FIXES APPLIED${c.reset}\n`)
      for (const fix of fixes) {
        process.stdout.write(`  ${f.symbols.check} ${c.green}${fix}${c.reset}\n`)
      }
      process.stdout.write('\n')
    }
  }

  // Results section
  process.stdout.write(`${c.bold}${c.underline}CHECKS${c.reset}\n`)
  for (const item of results) {
    process.stdout.write(`${formatStatus(c, item.status, item.name, item.message)}\n`)
  }
  process.stdout.write('\n')

  // Summary
  const okCount = results.filter((r) => r.status === 'ok').length
  const warnCount = results.filter((r) => r.status === 'warn').length
  const errorCount = results.filter((r) => r.status === 'error').length

    if (hasError) {
      process.stdout.write(`${c.red}${c.bold}✗ ${errorCount} error(s)${c.reset}`)
    } else if (warnCount > 0) {
      process.stdout.write(`${c.yellow}${c.bold}⚠ ${warnCount} warning(s)${c.reset}`)
    } else {
      process.stdout.write(`${c.green}${c.bold}✓ All checks passed${c.reset}`)
    }
    process.stdout.write(` ${c.dim}(${okCount} ok, ${warnCount} warn, ${errorCount} error)${c.reset}\n\n`)
  }

  if (hasError) {
    process.exitCode = 1
  }
}

async function checkVectorNetwork(provider) {
  const baseUrl = provider.baseUrl.replace(/\/$/, '')
  const url = `${baseUrl}/embeddings`
  const controller = new AbortController()
  const timeoutMs = provider.timeoutMs ?? 10000
  const timer = setTimeout(() => controller.abort(), timeoutMs)
  const headers = { 'content-type': 'application/json' }
  if (provider.apiKey) {
    headers.authorization = `Bearer ${provider.apiKey}`
  }
  const body = JSON.stringify({ model: provider.model, input: ['ping'] })
  const res = await fetch(url, {
    method: 'POST',
    headers,
    body,
    signal: controller.signal,
  })
  clearTimeout(timer)
  if (!res.ok) {
    const text = await res.text().catch(() => '')
    throw new Error(`embeddings request failed (${res.status}): ${text || res.statusText}`)
  }
}

  if (shell === 'bash') {
