  throw new Error(`unsupported shell: ${shell}`)

}

function validatePositionals(command, positionals, flags) {
  if (command === 'search') {
    if (positionals.length < 1) {
      return 'search requires a query'
    }
    if (positionals.length > 1) {
      return `unexpected arguments: ${positionals.slice(1).join(' ')}`
    }
  }

  if (command === 'trace') {
    if (positionals.length < 1) {
      return 'trace requires a subcommand (callers|impact)'
    }
    if (!TRACE_SUBCOMMANDS.has(positionals[0])) {
      return `unknown trace subcommand: ${positionals[0]}`
    }
    if (!flags.get('node-id') && !positionals[1]) {
      return `trace ${positionals[0]} requires a name or --node-id`
    }
  }

  if (command === 'completions') {
    if (positionals.length !== 1) {
      return 'completions requires a shell name'
    }
  }

  if (['index', 'serve', 'mcp', 'init', 'watch', 'doctor', 'man'].includes(command)) {
    if (positionals.length) {
      return `unexpected arguments: ${positionals.join(' ')}`
    }
  }

  return null
}

async function main() {
  const { command, flags, positionals, errors } = parseArgs(process.argv.slice(2))

  if (flags.get('version')) {
    const c = getColors()
    process.stdout.write(
      `${c.cyan}${c.bold}argus-search${c.reset} ${c.dim}v${c.reset}${c.green}${packageVersion}${c.reset}\n`,
    )
    return
  }

  if (flags.get('help') || command === 'help') {
    const target = flags.get('help-target')
    printUsage(target && COMMANDS.has(target) ? target : undefined)
    return
  }

if (errors.length) {
  throw new Error(`${errors.join('\n')}\nRun "argus-search --help" for usage.`)
}

const positionalError = validatePositionals(command, positionals, flags)
if (positionalError) {
  throw new Error(`${positionalError}\nRun "argus-search help ${command}" for usage.`)
}

if (!COMMANDS.has(command)) {
  throw new Error(`unknown command: ${command}\nRun "argus-search --help" for usage.`)
}

if (command === 'index') {
  const { options } = await loadOptions(flags, { requireConfig: false })
  await ensureProjectRoot(options.projectRoot)
  const { index } = getBinding()
  await index(options)
  return
}

if (command === 'serve') {
  const { options } = await loadOptions(flags, { requireConfig: false })
  await ensureProjectRoot(options.projectRoot)
  const portRaw = flags.get('port')
  const port = portRaw ? Number(portRaw) : Number(options?.server?.port) || 17890
  if (!Number.isFinite(port) || port <= 0 || port > 65535) {
    throw new Error(`invalid port: ${portRaw}`)
  }
  const vectorProvider = resolveVectorProvider(options, flags, { preferDefaults: true })
  if (!vectorProvider) throw new Error('serve requires vector.provider (HTTP embeddings) in config/options')

  const { createMcpServer } = require('./mcp.js')
  const server = createMcpServer({
    port,
    projectRoot: options.projectRoot,
    inputs: options.inputs,
    vectorProvider,
    streamOptions: options?.server?.streamOptions,
    indexOnStart: options?.server?.indexOnStart ?? true,
  })

}

if (command === 'mcp') {
  const { options } = await loadOptions(flags, { requireConfig: false })
  await ensureProjectRoot(options.projectRoot)
  const vectorProvider = resolveVectorProvider(options, flags, { preferDefaults: true })
  if (!vectorProvider) throw new Error('mcp requires vector.provider (HTTP embeddings) in config/options')

  const storeFlag = flags.get('store')
  const storePath = storeFlag ? String(storeFlag) : options?.server?.store?.path
  const resolvedStorePath = storePath ? storePath : '.argus-search/index.kite'

  const indexOnStartFlag = flags.get('no-index-on-start') ? false : undefined
  const indexOnStart = indexOnStartFlag ?? options?.server?.indexOnStart ?? true

  const { createStdioMcpServer } = require('./mcp-stdio.js')
  const server = createStdioMcpServer({
    projectRoot: options.projectRoot,
    storePath: path.isAbsolute(resolvedStorePath)
      ? resolvedStorePath
      : path.join(options.projectRoot, resolvedStorePath),
    indexOptions: {
      projectRoot: options.projectRoot,
      inputs: options.inputs,
      phases: { parse: true, graph: true, vector: true, scip: false, indexPack: false, ...options.phases },
      vector: options.vector,
    },
    vectorProvider,
    indexOnStart,
  })

  await server.start()
  return
}

if (command === 'init') {
  await runInit(flags)
  return
}

if (command === 'watch') {
  await runWatch(flags)
  return
}

if (command === 'search') {
  await runSearch(flags, positionals[0])
  return
}

  if (command === 'trace') {
    await runTrace(flags, positionals[0], positionals[1])
    return
  }

  if (command === 'doctor') {
    await runDoctor(flags)
    return
  }

  if (command === 'completions') {
    const shell = positionals[0]
    process.stdout.write(renderCompletions(shell))
    return
  }

  if (command === 'man') {
    process.stdout.write(renderManPage())
    return
  }
}

main().catch((error) => {
  const c = getColors()
  const f = fmt(c)
  const message = error instanceof Error ? error.message : String(error)
  process.stderr.write(`\n${f.symbols.cross} ${c.red}${c.bold}Error:${c.reset} ${message}\n\n`)
  process.exitCode = 1
})

