	if (reviewCommentTargets.length === 0) {
		return 0;
	}
	if (!activeCommentKey) {
		return 0;
	}
	const foundIndex = reviewCommentTargets.findIndex(
		(target) => target.feedbackKey === activeCommentKey,
	);
	return foundIndex >= 0 ? foundIndex : 0;
}, [activeCommentKey, reviewCommentTargets]);
const navigateReviewComments = useCallback(
	(direction: -1 | 1) => {
		if (reviewCommentTargets.length === 0) {
			return;
		}
		const total = reviewCommentTargets.length;
		const currentIndex = activeCommentKey
			? reviewCommentTargets.findIndex(
					(target) => target.feedbackKey === activeCommentKey,
				)
			: activeCommentIndex;
		const nextIndex =
			direction > 0
				? ((currentIndex >= 0 ? currentIndex : 0) + 1) % total
				: ((currentIndex >= 0 ? currentIndex : 0) - 1 + total) % total;
		const target = reviewCommentTargets[nextIndex];

		setActiveCommentKey(target.feedbackKey);
		if (collapsedFileKeys.has(target.fileKey)) {
			onToggleFileCollapsed(target.file);
		}
		scheduleScrollToCommentByKey(target.feedbackKey);
	},
	[
		activeCommentKey,
		activeCommentIndex,
		collapsedFileKeys,
		onToggleFileCollapsed,
		reviewCommentTargets,
		scheduleScrollToCommentByKey,
	],
);

const resolveFileReviewStatus = (
	file: FileDiffMetadata,
	fileKey: string,
): FileReviewStatus => {
	const candidatePaths = [file.name, file.prevName]
		.filter(
			(path): path is string =>
				typeof path === "string" && path.trim().length > 0,
		)
		.map((path) => normalizePatchPath(path));

	const isFailed = candidatePaths.some((path) => failedFilePaths.has(path));
	if (isFailed) {
		return "failed";
	}
	if (
		reviewRun.stage === "failed" &&
		failedFilePaths.size === 0 &&
		reviewRun.completedBatches === 0 &&
		reviewError.trim().length > 0
	) {
		return "failed";
	}

	const isReviewingFile = candidatePaths.some((path) =>
		reviewingFilePaths.has(path),
	);
	if (isReviewingFile) {
		return "reviewing";
	}

	const isReviewedFile = candidatePaths.some((path) =>
		reviewedFilePaths.has(path),
	);
	if (isReviewedFile) {
		if (reviewCoverageByFileKey[fileKey]) {
			return "issues";
		}
		return "clean";
	}

	if (!hasReviewAttempt) {
		return "pending";
	}

	return "pending";
};

return (
	<div className="relative flex min-h-0 flex-1 flex-col overflow-hidden">
		{/* ── header: fixed above scroll ── */}

					{visibleFiles.length > 0 ? (
						<WorkerPoolContextProvider
							poolOptions={poolOptions}
							highlighterOptions={highlighterOptions}
						>
							<div className="space-y-3">
								{visibleFiles.map((file) => {
									const fileKey = getFileKey(file);
									return (
										<div key={fileKey}>
											<MergeRequestDiffFileHeader
												file={file}
												isCollapsed={collapsedFileKeys.has(fileKey)}
												reviewCoverage={reviewCoverageByFileKey[fileKey]}
												reviewStatus={resolveFileReviewStatus(file, fileKey)}
												isDarkMode={isDarkMode}
												onToggleCollapsed={() => onToggleFileCollapsed(file)}
											/>
											{!collapsedFileKeys.has(fileKey) ? (
												<div className="overflow-hidden rounded-b-lg border border-t-0 border-border">
													<FileDiff
														fileDiff={file}
														options={diffOptions}
														lineAnnotations={reviewAnnotationsByFileKey[fileKey]}
														renderAnnotation={renderReviewAnnotation}
													/>
												</div>
											) : null}
										</div>
									);
								})}
							</div>
						</WorkerPoolContextProvider>
					) : null}

					{canLoadMore ? (
						<div className="pt-2 pb-4">
							<Button
								type="button"
								variant="outline"
								onClick={onLoadMore}
								className="text-xs"
							>
								Load more files ({remainingFileCount} remaining)
							</Button>
						</div>
					) : null}
				</div>

			</div>
		</div>
	);
}

function resolveColorEnabled(mode = 'auto', { isTTY = Boolean(process.stderr?.isTTY), env = process.env } = {}) {
  const value = String(mode ?? 'auto')
    .trim()
    .toLowerCase()
  if (value === 'always') return true
  if (value === 'never') return false
  if (value !== 'auto') return isTTY
  if (env.NO_COLOR != null && String(env.NO_COLOR) !== '') return false
  return isTTY
}

/**
 * Create a colorizer object based on the color mode
 * @param {string} mode
 * @returns {object}
 */
function createColors(mode = 'auto') {
  return resolveColorEnabled(mode) ? ANSI : NO_COLOR
}

// Global colors instance (auto-detect)
let globalColors = null

function getColors() {
  if (!globalColors) {
    globalColors = createColors('auto')
  }
  return globalColors
}

function setColorMode(mode) {
  globalColors = createColors(mode)
}

// ============================================================================
// Semantic styling helpers
// ============================================================================

function fmt(c) {

  return {
    // Status indicators
    success: (text) => `${c.green}${c.bold}${text}${c.reset}`,
    error: (text) => `${c.red}${c.bold}${text}${c.reset}`,
    warning: (text) => `${c.yellow}${text}${c.reset}`,
    info: (text) => `${c.cyan}${text}${c.reset}`,

    // UI elements
    command: (text) => `${c.cyan}${c.bold}${text}${c.reset}`,
    option: (text) => `${c.yellow}${text}${c.reset}`,
    value: (text) => `${c.green}${text}${c.reset}`,
    path: (text) => `${c.blue}${c.underline}${text}${c.reset}`,
    dim: (text) => `${c.dim}${text}${c.reset}`,
    bold: (text) => `${c.bold}${text}${c.reset}`,

    // Semantic elements
    label: (text) => `${c.brightBlack}${text}${c.reset}`,
    highlight: (text) => `${c.magenta}${text}${c.reset}`,
    number: (text) => `${c.yellow}${text}${c.reset}`,

    // Status badges
    badge: {
      ok: () => `${c.bgGreen}${c.black}${c.bold} OK ${c.reset}`,
      warn: () => `${c.bgYellow}${c.black}${c.bold} WARN ${c.reset}`,
      error: () => `${c.bgRed}${c.white}${c.bold} ERR ${c.reset}`,
      info: () => `${c.bgBlue}${c.white}${c.bold} INFO ${c.reset}`,
    },

    // Symbols
    symbols: {
      check: c.green ? `${c.green}✓${c.reset}` : '[OK]',
      cross: c.red ? `${c.red}✗${c.reset}` : '[FAIL]',
      warning: c.yellow ? `${c.yellow}⚠${c.reset}` : '[WARN]',
      info: c.cyan ? `${c.cyan}ℹ${c.reset}` : '[INFO]',
      arrow: c.cyan ? `${c.cyan}→${c.reset}` : '->',
      bullet: c.dim ? `${c.dim}•${c.reset}` : '*',
      spinner: ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'],
    },
  }
}

// ============================================================================
// Pre-built formatters
// ============================================================================

/**
 * Format the CLI banner/logo
 */
function formatBanner(c) {
  return `${c.cyan}${c.bold}
   ___          _        ___       _       _ _ _                          
  / __|___   __| | ___  |_ _|_ __ | |_ ___| | (_) __ _  ___ _ __   ___ ___ 
 | |  / _ \\ / _\` |/ _ \\  | || '_ \\| __/ _ \\ | | |/ _\` |/ _ \\ '_ \\ / __/ _ \\
 | |_| (_) | (_| |  __/  | || | | | ||  __/ | | | (_| |  __/ | | | (_|  __/
  \\___\\___/ \\__,_|\\___| |___|_| |_|\\__\\___|_|_|_|\\__, |\\___|_| |_|\\___\\___|
                                                 |___/                     
${c.reset}`
}

/**
 * Format a mini logo for compact output
 */
function formatMiniLogo(c) {
  return `${c.cyan}${c.bold}argus-search${c.reset}`
}

/**
 * Format a section header
 */
function formatSection(c, title) {
  return `\n${c.bold}${c.underline}${title}${c.reset}\n`
}

/**
 * Format a key-value pair
 */
function formatKeyValue(c, key, value, { indent = 0, keyWidth = 16 } = {}) {
  const padding = ' '.repeat(indent)
  const paddedKey = String(key).padEnd(keyWidth)
  return `${padding}${c.dim}${paddedKey}${c.reset} ${value}`
}

/**
 * Format a list item
 */
function formatListItem(c, text, { indent = 2, bullet = true } = {}) {
  const f = fmt(c)
  const padding = ' '.repeat(indent)
  const prefix = bullet ? `${f.symbols.bullet} ` : ''
  return `${padding}${prefix}${text}`
}

/**
 * Format a status line (for doctor, etc.)
 */

function formatBox(c, lines, { title = '', padding = 1, borderColor = c.dim } = {}) {
  const linesArray = Array.isArray(lines) ? lines : lines.split('\n')
  const maxLen = Math.max(...linesArray.map((l) => stripAnsi(l).length), stripAnsi(title).length + 2)
  const width = maxLen + padding * 2

  const top = title
    ? `${borderColor}┌─${c.reset}${c.bold} ${title} ${c.reset}${borderColor}${'─'.repeat(width - stripAnsi(title).length - 3)}┐${c.reset}`
    : `${borderColor}┌${'─'.repeat(width)}┐${c.reset}`
  const bottom = `${borderColor}└${'─'.repeat(width)}┘${c.reset}`
  const pad = ' '.repeat(padding)

  const content = linesArray.map((line) => {
    const stripped = stripAnsi(line)
    const rightPad = ' '.repeat(Math.max(0, maxLen - stripped.length))
    return `${borderColor}│${c.reset}${pad}${line}${rightPad}${pad}${borderColor}│${c.reset}`
  })

  return [top, ...content, bottom].join('\n')
}

/**
 * Strip ANSI escape codes from a string
 * Removes sequences like ESC[...m used for colors/styles
 */

function stripAnsi(str) {
  // ESC character (0x1B = 27) followed by [ then optional numbers/semicolons then m
  const esc = String.fromCharCode(27)
  const escBracket = `${esc}[`
  let result = String(str)
  let i = result.indexOf(escBracket)
  while (i !== -1) {
    let j = i + 2
    while (j < result.length && ((result[j] >= '0' && result[j] <= '9') || result[j] === ';')) {
      j++
    }
    if (j < result.length && result[j] === 'm') {
      result = result.slice(0, i) + result.slice(j + 1)
    } else {
      i++
    }
    i = result.indexOf(escBracket, i)
  }
  return result
}

/**
 * Format a table
 */

function formatTable(c, rows, { headers = [], columnWidths = [] } = {}) {
  if (!rows.length) return ''

  // Calculate column widths if not provided
  const allRows = headers.length ? [headers, ...rows] : rows
  const widths =
    columnWidths.length > 0
      ? columnWidths
      : allRows[0].map((_, colIdx) => Math.max(...allRows.map((row) => stripAnsi(String(row[colIdx] ?? '')).length)))

  const formatRow = (row, isHeader = false) => {
    return row
      .map((cell, idx) => {
        const text = String(cell ?? '')
        const stripped = stripAnsi(text)
        const pad = ' '.repeat(Math.max(0, widths[idx] - stripped.length))
        return isHeader ? `${c.bold}${text}${c.reset}${pad}` : `${text}${pad}`
      })
      .join('  ')
  }

  const output = []
  if (headers.length) {
    output.push(formatRow(headers, true))
    output.push(c.dim + widths.map((w) => '─'.repeat(w)).join('──') + c.reset)
  }
  for (const row of rows) {
    output.push(formatRow(row))
  }
  return output.join('\n')
}

// ============================================================================
// Help text formatting
// ============================================================================

/**
 * Format the main usage text with colors
 */

function formatUsage(c, { version = '', commands = [], options = [] } = {}) {
  const f = fmt(c)
  const lines = []

  lines.push(`${formatMiniLogo(c)} ${c.dim}v${version}${c.reset}`)
  lines.push('')
  lines.push(`${c.bold}USAGE${c.reset}`)
  lines.push(`  ${f.command('argus-search')} ${c.dim}<command>${c.reset} ${c.dim}[options]${c.reset}`)
  lines.push('')

  if (commands.length) {
    lines.push(`${c.bold}COMMANDS${c.reset}`)
    for (const cmd of commands) {
      lines.push(`  ${f.command(cmd.name.padEnd(16))} ${c.dim}${cmd.description}${c.reset}`)
    }
    lines.push('')
  }

  if (options.length) {
    lines.push(`${c.bold}OPTIONS${c.reset}`)
    for (const opt of options) {
      const flags = opt.short
        ? `${f.option(`-${opt.short}`)}, ${f.option(`--${opt.name}`)}`
        : `    ${f.option(`--${opt.name}`)}`
      lines.push(`  ${flags.padEnd(30)} ${c.dim}${opt.description}${c.reset}`)
    }
    lines.push('')
  }

  lines.push(`${c.dim}Run ${f.command('argus-search help <command>')} for command-specific help${c.reset}`)
  return lines.join('\n')
}

/**
 * Format command-specific help
 */

function formatCommandHelp(c, { command = '', usage = '', options = [], examples = [] } = {}) {
  const f = fmt(c)
  const lines = []

  lines.push(`${c.bold}${command.toUpperCase()}${c.reset}`)
  lines.push('')
  lines.push(`${c.bold}USAGE${c.reset}`)
  lines.push(`  ${usage}`)
  lines.push('')

  if (options.length) {
    lines.push(`${c.bold}OPTIONS${c.reset}`)
    for (const opt of options) {
      const name = opt.name.padEnd(24)
      lines.push(`  ${f.option(`--${name}`)} ${c.dim}${opt.description}${c.reset}`)
    }
    lines.push('')
  }

  if (examples.length) {
    lines.push(`${c.bold}EXAMPLES${c.reset}`)
    for (const ex of examples) {
      lines.push(`  ${c.dim}$${c.reset} ${f.command(ex)}`)
    }
    lines.push('')
  }

  return lines.join('\n')
}

// ============================================================================
// Exports
// ============================================================================

module.exports = {
  ANSI,
  NO_COLOR,
  resolveColorEnabled,
  createColors,
  getColors,
  setColorMode,
  fmt,
  formatBanner,
  formatMiniLogo,
  formatSection,
  formatKeyValue,
  formatListItem,
  formatStatus,
  formatEvent,
  formatBox,
  formatTable,
  formatUsage,
  formatCommandHelp,
  stripAnsi,
}

