export { WelcomeHeader } from "./welcome-header";
export { HeroSection } from "./hero-section";
export { ComparisonSection } from "./comparison-section";
export { StatisticsSection } from "./statistics-section";
export { PopoverRow } from "./popover-row";
export { SavingsStat } from "./savings-stat";
export { comparisonData } from "./comparison-data";
export type { ComparisonRow } from "./comparison-data";

const defaultRuntimeDeps: DeltaRuntimeDeps = {
  clearStagedChanges,
  loadExistingStates,
  stageDelete,
  stageUpsert,
  buildVectorChunks,
  embedVectorChunks,
}

const resolveMaxFileSizeBytes = () =>
  parsePositiveInt(process.env.INDEXER_MAX_FILE_SIZE_BYTES, DEFAULT_MAX_FILE_SIZE_BYTES)

const resolveDeltaFallbackThreshold = () =>
  parsePositiveInt(process.env.INDEXER_DELTA_FALLBACK_THRESHOLD, DEFAULT_DELTA_FALLBACK_THRESHOLD)

const toErrorMessage = (error: unknown) =>
  error instanceof Error ? error.message : 'Unexpected embedding failure.'

const wrapEmbeddingError = (args: {
  path: string
  chunks: Array<Omit<VectorChunkRecord, 'embedding'>>
  error: unknown
}) => {
  const maxChunk = args.chunks.reduce<{ chunkIndex: number; size: number } | null>(
    (largest, chunk) => {
      const size = chunk.content.length
      if (!largest || size > largest.size) {
        return {
          chunkIndex: chunk.chunkIndex,
          size,
        }
      }

      return largest
    },
    null,
  )

  const wrapped = new Error(
    `Embedding failed for ${args.path} (chunks=${args.chunks.length}, maxChunkChars=${maxChunk?.size ?? 0}): ${toErrorMessage(args.error)}`,
  )
  ;(wrapped as Error & { details?: Record<string, unknown> }).details = {
    stage: 'embedding',
    path: args.path,
    chunkCount: args.chunks.length,
    maxChunkChars: maxChunk?.size ?? 0,
    maxChunkIndex: maxChunk?.chunkIndex ?? null,
  }

  return wrapped
}

export class DeltaSnapshotFallbackError extends Error {
  readonly reason: DeltaFallbackReason

  constructor(reason: DeltaFallbackReason) {
    super(`Delta ingest fallback required: ${reason}`)
    this.reason = reason
    this.name = 'DeltaSnapshotFallbackError'
  }
}

export const runDeltaIngest = async (args: {
  run: DeltaRunContext
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
  shouldAbort?: () => Promise<void>
  onProgress?: (event: DeltaProgressEvent) => void
  workspace?: RepoWorkspace
  runtimeDeps?: Partial<DeltaRuntimeDeps>
}): Promise<DeltaResult> => {
  const runtime: DeltaRuntimeDeps = {
    ...defaultRuntimeDeps,
    ...args.runtimeDeps,
  }
  const maxFileSizeBytes = resolveMaxFileSizeBytes()

  const stats = {
    compareChanges: 0,
    filesProcessed: 0,
    filesFetched: 0,
    filesUnchanged: 0,
    filesIndexed: 0,
    filesSkipped: 0,
    filesDeleted: 0,
    chunksUpserted: 0,
    embeddingApiCalls: 0,
    embeddingFailures: 0,
    embeddingPromptTokens: 0,
    embeddingTotalTokens: 0,
    embeddingCostUsd: 0,
  }

  const manifestLines: string[] = []
  const changedFileLines: string[] = []
  const existingByPath = await runtime.loadExistingStates(args.run.branchStateId)

  const emitProgress = (event: Omit<DeltaProgressEvent, 'stage' | 'stats'>) => {
    if (!args.onProgress) {
      return
    }

    args.onProgress({
      stage: 'ingest',
      ...event,
      stats: { ...stats },
    })
  }

  await runtime.clearStagedChanges(args.run.runId)
  await args.shouldAbort?.()

if (!args.run.baseSha) {
  throw new DeltaSnapshotFallbackError('missing_base_sha')
}

const compare = await args.source.compare({
  integrationId: args.run.integrationId,
  fromSha: args.run.baseSha,
  toSha: args.run.headSha,
})
stats.compareChanges = compare.changes.length

await args.shouldAbort?.()

const fallbackReason = resolveDeltaFallbackReason({
  baseSha: args.run.baseSha,
  compare,
  maxChanges: resolveDeltaFallbackThreshold(),
})

if (fallbackReason) {
  throw new DeltaSnapshotFallbackError(fallbackReason)
}

const deltaPlan = buildDeltaIngestPlan(compare.changes)
emitProgress({
  step: 'delta_plan_ready',
  message: `Delta plan ready (${deltaPlan.upserts.length} upsert(s), ${deltaPlan.deletes.length} delete(s)).`,
  details: {
    compareChanges: compare.changes.length,
    upserts: deltaPlan.upserts.length,
    deletes: deltaPlan.deletes.length,
  },
})

for (const deletion of deltaPlan.deletes) {
  await args.shouldAbort?.()
  stats.filesProcessed += 1
  await runtime.stageDelete({
    runId: args.run.runId,
    path: deletion.path,
    skipReason: deletion.reason,
  })
  stats.filesDeleted += 1
  emitProgress({
    step: 'file_deleted',
    message: `Deleted ${deletion.path} from index state (${deletion.reason}).`,
    path: deletion.path,
    details: {
      reason: deletion.reason,
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: deletion.path,
      status: 'deleted',
      reason: deletion.reason,
    }),
  )
  changedFileLines.push(
    JSON.stringify({
      path: deletion.path,
      changeType: 'deleted',
      reason: deletion.reason,
    }),
  )
}

for (const upsert of deltaPlan.upserts) {
  await args.shouldAbort?.()
  stats.filesProcessed += 1
  const file = args.workspace
    ? {
        path: upsert.path,
        content: await args.workspace.readFile(upsert.path),
      }
    : await args.source.fetchFile({
        integrationId: args.run.integrationId,
        path: upsert.path,
        ref: args.run.headSha,
      })
  stats.filesFetched += 1

  const skipReason = classifySkipReason({
    relativePath: upsert.path,
    content: file.content,
    maxFileSizeBytes,
  })

  const existing = existingByPath.get(upsert.path)

if (skipReason) {
  stats.filesSkipped += 1
  emitProgress({
    step: 'file_skipped',
    message: `Skipped ${upsert.path} (${skipReason}).`,
    path: upsert.path,
    details: {
      skipReason,
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: 'skipped',
      skipReason,
    }),
  )

  if (existing) {
    await runtime.stageDelete({
      runId: args.run.runId,
      path: upsert.path,
      skipReason,
    })
    stats.filesDeleted += 1
    changedFileLines.push(
      JSON.stringify({
        path: upsert.path,
        changeType: 'deleted',
        reason: skipReason,
      }),
    )
  }

  continue
}

const fileId = sha256Hex(file.content)
if (existing?.fileId === fileId) {
  stats.filesUnchanged += 1
  emitProgress({
    step: 'file_unchanged',
    message: `Unchanged ${upsert.path}; reuse existing vectors.`,
    path: upsert.path,
  })
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: 'unchanged',
    }),
  )
  continue
}

const chunks = await runtime.buildVectorChunks({
  path: upsert.path,
  content: file.content.toString('utf8'),
  configHash: args.run.configHash,
})

if (chunks.length === 0) {
  stats.filesSkipped += 1
  emitProgress({
    step: 'file_skipped',
    message: `Skipped ${upsert.path} (no chunks).`,
    path: upsert.path,
    details: {
      skipReason: 'no_chunks',
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: 'skipped',
      skipReason: 'no_chunks',
    }),
  )

  if (existing) {
    await runtime.stageDelete({
      runId: args.run.runId,
      path: upsert.path,
      skipReason: 'no_chunks',
    })
    stats.filesDeleted += 1
    changedFileLines.push(
      JSON.stringify({
        path: upsert.path,
        changeType: 'deleted',
        reason: 'no_chunks',
      }),
    )
  }
  continue
}

let embeddedChunks: VectorChunkRecord[]
try {
  embeddedChunks = await runtime.embedVectorChunks(chunks, {
    onTelemetry: (telemetry) => {
      stats.embeddingApiCalls += telemetry.requestCount
      stats.embeddingFailures += telemetry.failureCount
      stats.embeddingPromptTokens += telemetry.promptTokens
      stats.embeddingTotalTokens += telemetry.totalTokens
      stats.embeddingCostUsd += telemetry.costUsd ?? 0
    },
  })
} catch (error) {
  throw wrapEmbeddingError({
    path: upsert.path,
    chunks,
    error,
  })
}

  await args.vectorStore.upsertChunks({
    branchStateId: args.run.branchStateId,
    runId: args.run.runId,
    path: upsert.path,
    fileId,
    chunks: embeddedChunks,
  })

  await runtime.stageUpsert({
    runId: args.run.runId,
    path: upsert.path,
    fileId,
    sizeBytes: file.content.length,
  })

  stats.filesIndexed += 1
  stats.chunksUpserted += embeddedChunks.length
  emitProgress({
    step: 'file_indexed',
    message: `Indexed ${upsert.path} (${embeddedChunks.length} chunk(s)).`,
    path: upsert.path,
    details: {
      chunks: embeddedChunks.length,
      changeType: upsert.changeType,
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: upsert.path,
      status: existing ? 'changed' : 'new',
      chunks: embeddedChunks.length,
    }),
  )
  changedFileLines.push(
    JSON.stringify({
      path: upsert.path,
      changeType: upsert.changeType,
      oldPath: upsert.oldPath,
      fileId,
    }),
  )
}

await args.shouldAbort?.()
await args.artifactStore.writeManifest({
  artifactsPrefix: args.run.artifactsPrefix,
  lines: manifestLines,
})

await args.artifactStore.writeChangedFiles({
  artifactsPrefix: args.run.artifactsPrefix,
  lines: changedFileLines,
})

await args.artifactStore.writeRunJson({
  artifactsPrefix: args.run.artifactsPrefix,
  run: {
    runId: args.run.runId,
    mode: 'delta',
    baseSha: args.run.baseSha,
    headSha: args.run.headSha,
    stats,
  },
})

  emitProgress({
    step: 'delta_artifacts_written',
    message: 'Delta artifacts written.',
    details: {
      manifestLines: manifestLines.length,
      changedFiles: changedFileLines.length,
    },
  })

  return {
    stats,
  }
}

import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

import { TreeSitterChunker } from "../../../argus/src/parser/tree-sitter/chunker.ts";
import { buildGraphArtifacts } from "../../../argus/src/db/indexing/file_processor.ts";
import { normalizeFileResults } from "../../../argus/src/db/indexing/index-pack.ts";
import { generateFileNodeId, mapEdgeType } from "../../../argus/src/db/graph/ray/mapper.ts";

type GraphNodeRecord = {
  id: string;
  kind: string;
  name?: string;
  filePath?: string;
  range?: unknown;
  language?: string;
  sources: string[];
  metadata?: Record<string, unknown>;
  metadataBySource?: Record<string, Record<string, unknown>>;
};

type GraphEdgeRecord = {
  sourceId: string;
  targetId: string;
  type: string;
  sources: string[];
  metadata?: Record<string, unknown>;
  metadataBySource?: Record<string, Record<string, unknown>>;
};

type GraphOutput = {
  layer: "syntax";
  nodes: GraphNodeRecord[];
  edges: GraphEdgeRecord[];
};

type ParsedChunk = {
  id: string;
  kind: string;
  language: string;
  filePath: string;
  name?: string;
  range: unknown;
  content?: string;
  metadata?: Record<string, unknown>;
};

type ParsedFileOutput = {
  filePath: string;
  chunks: ParsedChunk[];
};

const fixtureRoot = resolve(import.meta.dir);
const projectRoot = fixtureRoot;
const srcDir = resolve(fixtureRoot, "src");

const rawResults = ["foo.ts", "bar.ts", "index.ts"].map((name) => {
  const filePath = resolve(srcDir, name);
  const fullPath = resolve(srcDir, name);
  const content = readFileSync(fullPath, "utf8");
  const chunks = TreeSitterChunker.chunkFile(filePath, content);
  return { filePath, chunks };
});

const config = {
  lancedb: {
    graph: {
      extensions: [".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs"],
      aliases: {},
    },
  },
} as const;

const { results: normalizedResults, idMap } = normalizeFileResults(
  rawResults as any,
  projectRoot,
);
const artifacts = buildGraphArtifacts(rawResults as any, projectRoot, config);
const knownFiles = new Set(normalizedResults.map((entry) => entry.filePath));
const extensionCandidates = config.lancedb.graph.extensions;

const nodes: GraphNodeRecord[] = [];
const edges: GraphEdgeRecord[] = [];

const fileNodes = new Map<string, GraphNodeRecord>();
for (const result of normalizedResults) {
  const fileNodeId = generateFileNodeId(result.filePath);
  const fileNode: GraphNodeRecord = {
    id: fileNodeId,
    kind: "file",
    name: result.filePath.split("/").pop(),
    filePath: result.filePath,
    language: inferLanguageFromPath(result.filePath),
    sources: ["tree-sitter"],
    metadata: { filePath: result.filePath },
    metadataBySource: { "tree-sitter": { filePath: result.filePath } },
  };
  fileNodes.set(fileNodeId, fileNode);
}

for (const [rawFilePath, artifact] of artifacts.entries()) {
  const normalized = normalizedResults.find((entry) => entry.filePath === normalizeFilePath(rawFilePath, projectRoot));

const fileChunks = normalized?.chunks ?? [];
for (const chunk of fileChunks) {
  nodes.push({
    id: chunk.id,
    kind: chunk.kind ?? "chunk",
    name: chunk.name,
    filePath: chunk.filePath,
    range: chunk.range,
    language: chunk.language,
    sources: ["tree-sitter"],
    metadata: chunk.metadata,
    metadataBySource: { "tree-sitter": chunk.metadata ?? {} },
  });
}

for (const edge of artifact.edges) {
  const metadata = normalizeEdgeMetadata(
    edge.metadata ?? {},
    projectRoot,
    knownFiles,
    extensionCandidates,
  );
  edges.push({
    sourceId: normalizeGraphId(
      edge.sourceId,
      idMap,
      projectRoot,
      knownFiles,
      extensionCandidates,
    ),
    targetId: normalizeGraphId(
      edge.targetId,
      idMap,
      projectRoot,
      knownFiles,
      extensionCandidates,
    ),
    type: mapEdgeType(edge.edgeType),
    sources: ["tree-sitter"],
    metadata,
    metadataBySource: { "tree-sitter": metadata },
  });
}

const normalizedFilePath = normalizeFilePath(rawFilePath, projectRoot);
const fileNodeId = generateFileNodeId(normalizedFilePath);
let order = 0;
for (const chunk of fileChunks) {
  if (chunk.kind === "file") continue;
  order += 1;
  edges.push({
    sourceId: fileNodeId,
    targetId: chunk.id,
    type: "CONTAINS",
    sources: ["tree-sitter"],
    metadata: { order },
    metadataBySource: { "tree-sitter": { order } },
  });
}

}

for (const fileNode of fileNodes.values()) {
  nodes.push(fileNode);
}

nodes.sort((a, b) => a.id.localeCompare(b.id));
edges.sort((a, b) => {
  if (a.sourceId !== b.sourceId) return a.sourceId.localeCompare(b.sourceId);
  if (a.type !== b.type) return a.type.localeCompare(b.type);
  return a.targetId.localeCompare(b.targetId);
});

const output: GraphOutput = { layer: "syntax", nodes, edges };
const outPath = resolve(fixtureRoot, "expected", "graph.json");
writeFileSync(outPath, JSON.stringify(output, null, 2));

const parseFiles: ParsedFileOutput[] = normalizedResults.map((result) => ({
  filePath: result.filePath,
  chunks: result.chunks.map((chunk) => ({ ...chunk })),
}));

parseFiles.sort((a, b) => a.filePath.localeCompare(b.filePath));
for (const file of parseFiles) {
  file.chunks.sort((a, b) => a.id.localeCompare(b.id));
}

const parseOutPath = resolve(fixtureRoot, "expected", "chunks.json");
writeFileSync(parseOutPath, JSON.stringify(parseFiles, null, 2));

function normalizeEdgeMetadata(
  metadata: Record<string, unknown>,
  root: string,
  knownFiles: Set<string>,
  extensions: string[],
) {
  const normalized = { ...metadata } as Record<string, unknown>;
  if (typeof normalized.targetFile === "string") {
    normalized.targetFile = normalizeMaybePath(normalized.targetFile, root);
  }
  if (typeof normalized.resolvedPath === "string") {
    const maybePath = normalizeMaybePath(normalized.resolvedPath, root);
    normalized.resolvedPath =
      resolveKnownFilePath(maybePath, knownFiles, extensions) ?? maybePath;
  }
  return normalized;
}

function normalizeMaybePath(value: string, root: string) {
  const resolved = resolve(value);
  const resolvedRoot = resolve(root);
  if (resolved.startsWith(resolvedRoot)) {
    const rel = resolved.slice(resolvedRoot.length).replace(/^\//, "");
    return rel.replace(/\\/g, "/");
  }
  return value;
}

function normalizeFilePath(filePath: string, root: string) {
  const resolved = resolve(filePath);
  const resolvedRoot = resolve(root);
  if (resolved.startsWith(resolvedRoot)) {
    const rel = resolved.slice(resolvedRoot.length).replace(/^\//, "");
    return rel.replace(/\\/g, "/");
  }
  return filePath;
}

function normalizeGraphId(
  id: string,
  idMap: Map<string, string>,
  root: string,
  knownFiles: Set<string>,
  extensions: string[],
) {
  const mapped = idMap.get(id);
  if (mapped) return mapped;

  if (id.startsWith("ts:file:")) {
    const rawPath = id.slice("ts:file:".length);
    const normalizedPath = normalizeMaybePath(rawPath, root);
    const resolvedPath =
      resolveKnownFilePath(normalizedPath, knownFiles, extensions) ??
      normalizedPath;
    return generateFileNodeId(resolvedPath);
  }

  return id;
}

function inferLanguageFromPath(filePath: string) {
  const ext = filePath.split(".").pop()?.toLowerCase();
  switch (ext) {
    case "ts":
    case "tsx":
      return "typescript";
    case "js":
    case "jsx":
      return "javascript";
    case "py":
      return "python";
    case "c":
    case "cc":
    case "cpp":
    case "cxx":
    case "h":
    case "hpp":
      return "cpp";
    default:
      return "unknown";
  }
}

function resolveKnownFilePath(
  filePath: string,
  knownFiles: Set<string>,
  extensions: string[],
) {
  if (knownFiles.has(filePath)) {
    return filePath;
  }

  const lastSegment = filePath.split("/").pop() ?? "";
  if (lastSegment.includes(".")) {
    return undefined;
  }

  for (const extension of extensions) {
    const candidate = `${filePath}${extension}`;
    if (knownFiles.has(candidate)) {
      return candidate;
    }
  }

  return undefined;
}

