import type {
  ObservabilityHealthStatus,
  ObservabilityLogLevel,
} from "@/lib/observability"

type BadgeVariant = "default" | "secondary" | "destructive" | "outline"

export const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

export const extractErrorMessage = (payload: unknown, fallback: string) => {
  const record = asRecord(payload)
  const rawError = record?.error
  return typeof rawError === "string" && rawError.trim() ? rawError : fallback
}

export const formatDateTime = (value: string | null | undefined) => {
  if (!value) {
    return "n/a"
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "invalid"
  }
  return parsed.toLocaleString()
}

export const formatDuration = (value: number | null) => {
  if (value === null || value < 0) {
    return "n/a"
  }
  return `${value}ms`
}

export const formatPercent = (value: number | null) => {
  if (value === null || !Number.isFinite(value) || value < 0) {
    return "n/a"
  }
  return `${value.toFixed(2)}%`
}

export const formatCurrencyUsd = (value: number | null) => {
  if (value === null || !Number.isFinite(value) || value < 0) {
    return "n/a"
  }
  return `$${value.toFixed(6)}`
}

export const formatCount = (value: number | null | undefined) => {
  if (value === null || value === undefined || !Number.isFinite(value) || value < 0) {
    return "n/a"
  }
  return Math.floor(value).toLocaleString()
}

export const asNumber = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number.parseFloat(value)
    return Number.isFinite(parsed) ? parsed : null
  }
  return null
}

export const formatAge = (value: number | null) => {
  if (value === null || value < 0) {
    return "n/a"
  }
  const seconds = Math.floor(value / 1000)
  if (seconds < 60) {
    return `${seconds}s`
  }
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) {
    return `${minutes}m`
  }
  const hours = Math.floor(minutes / 60)
  return `${hours}h`
}

export const toIsoQuery = (value: string) => {
  if (!value.trim()) {
    return ""
  }
  const parsed = new Date(value)
  return Number.isNaN(parsed.getTime()) ? "" : parsed.toISOString()
}

export const toLocalDateTimeInput = (value: string | null | undefined) => {
  if (!value) {
    return ""
  }
  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return ""
  }
  const pad = (segment: number) => String(segment).padStart(2, "0")
  return [
    parsed.getFullYear(),
    "-",
    pad(parsed.getMonth() + 1),
    "-",
    pad(parsed.getDate()),
    "T",
    pad(parsed.getHours()),
    ":",
    pad(parsed.getMinutes()),
  ].join("")
}

export const levelBadgeVariant = (level: ObservabilityLogLevel): BadgeVariant => {
  if (level === "error") {
    return "destructive"
  }
  if (level === "warn") {
    return "secondary"
  }
  if (level === "debug") {
    return "outline"
  }
  return "default"
}

export const healthBadgeVariant = (status: ObservabilityHealthStatus): BadgeVariant => {
  if (status === "critical") {
    return "destructive"
  }
  if (status === "degraded") {
    return "secondary"
  }
  return "default"
}

export const payloadPreview = (payload: Record<string, unknown>) => {
  try {
    const serialized = JSON.stringify(payload, null, 2)
    if (serialized.length <= 280) {
      return serialized
    }
    return `${serialized.slice(0, 280)}...`
  } catch {
    return "[payload serialization failed]"
  }
}

use std::collections::{HashMap, HashSet};
use std::fs;
use std::path::{Path, PathBuf};

use protobuf::Message;
use scip::types::symbol_information::Kind;
use scip::types::{Document, Index, Occurrence, Relationship, SymbolInformation, SyntaxKind};
use serde_json::json;

use super::engine::ScipError;
use super::engine::{
  ScipArtifacts, ScipEdgeInsert, ScipIndexOptions, ScipNodeInsert, ScipProvider,
};

pub const SYMBOL_ROLE_DEFINITION: i32 = 1 << 0;
pub const SYMBOL_ROLE_IMPORT: i32 = 1 << 1;
const MAX_SCIP_FILE_BYTES: u64 = 64 * 1024 * 1024;

#[derive(Debug, Clone)]
pub struct ScipBinaryProvider {
  pub paths: Vec<PathBuf>,
}

impl ScipBinaryProvider {
  pub fn new(paths: Vec<PathBuf>) -> Self {
    Self { paths }
  }

  pub fn parse_file(path: &Path, project_root: &Path) -> Result<ScipArtifacts, ScipError> {
    Self::parse_file_with_limit(path, project_root, MAX_SCIP_FILE_BYTES)
  }

  fn parse_file_with_limit(
    path: &Path,
    project_root: &Path,
    max_bytes: u64,
  ) -> Result<ScipArtifacts, ScipError> {
    let size = fs::metadata(path)?.len();
    if size > max_bytes {
      return Err(ScipError::Provider(format!(
        "scip file too large: {} bytes (max {}) at {}",
        size,
        max_bytes,
        path.display()
      )));
    }
    let bytes = fs::read(path)?;
    let index: Index = Index::parse_from_bytes(&bytes)
      .map_err(|err| ScipError::Provider(format!("failed to parse scip: {err}")))?;
    Ok(parse_index(&index, project_root))
  }
}

impl ScipProvider for ScipBinaryProvider {
  fn index(&self, options: &ScipIndexOptions) -> Result<ScipArtifacts, ScipError> {
    let mut combined = ScipArtifacts::default();
    let mut seen_nodes = HashSet::new();
    let mut seen_edges = HashSet::new();

    for path in &self.paths {
      let artifacts = Self::parse_file(path, &options.project_root)?;
      for node in artifacts.nodes {
        if seen_nodes.insert(node.id.clone()) {
          combined.nodes.push(node);
        }
      }
      for edge in artifacts.edges {
        let edge_key = format!("{}::{}::{}", edge.source_id, edge.edge_type, edge.target_id);
        if seen_edges.insert(edge_key) {
          combined.edges.push(edge);
        }
      }
    }

    Ok(combined)
  }
}

#[derive(Debug, Clone)]
struct DefinitionInfo {
  symbol: String,
  start_line: u32,
  start_col: i32,
  end_line: u32,
  end_col: i32,
}

#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct OccurrenceRecord {
  line: u32,
  column: i32,
  end_line: u32,
  end_column: i32,
  role: String,
}

#[derive(Debug, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
struct RelationshipRecord {
  source_symbol: String,
  target_symbol: String,
  is_reference: bool,
  is_implementation: bool,
  is_type_definition: bool,
  is_definition: bool,
}

#[derive(Debug, Clone, Default)]
struct EdgeAggregate {
  occurrences: Vec<OccurrenceRecord>,
  relationships: Vec<RelationshipRecord>,
}

fn parse_index(index: &Index, project_root: &Path) -> ScipArtifacts {
  let mut artifacts = ScipArtifacts::default();

let mut seen_nodes = HashSet::new();
let symbol_kinds = build_symbol_kind_index(index);

for document in &index.documents {
  let file_path = normalize_path(&document.relative_path, project_root);
  let file_node_id = format!("ts:file:{file_path}");
  if seen_nodes.insert(file_node_id.clone()) {
    artifacts.nodes.push(ScipNodeInsert {
      id: file_node_id,
      node_type: "file".to_string(),
      name: Some(file_path.split('/').next_back().unwrap_or("").to_string()),
      start_line: Some(1),
      end_line: Some(1),
      metadata: Some(json!({
        "filePath": file_path.as_str(),
        "language": document.language.as_str(),
        "source": "scip"
      })),
    });
  }

  let mut definitions = Vec::new();

for symbol_info in &document.symbols {
  if let Some(def_occ) = find_definition_occurrence(document, symbol_info) {
    let (start_line, start_col, end_line, end_col) = parse_range(&def_occ.range);
    let kind = map_symbol_kind(
      symbol_info
        .kind
        .enum_value()
        .unwrap_or(Kind::UnspecifiedKind),
    );
    let node = ScipNodeInsert {
      id: symbol_info.symbol.clone(),
      node_type: kind.to_string(),
      name: display_name(symbol_info),
      start_line: Some(start_line),
      end_line: Some(end_line),
      metadata: Some(json!({
        "filePath": file_path.as_str(),
        "language": document.language.as_str(),
        "scipSymbol": symbol_info.symbol.as_str(),
        "symbolKind": kind,
        "displayName": symbol_info.display_name.as_str(),
        "documentation": symbol_info.documentation.join("\n"),
        "source": "scip"
      })),
    };

    if seen_nodes.insert(node.id.clone()) {
      artifacts.nodes.push(node);
    }

    let (def_end_line, def_end_col) =
      extend_definition_range(symbol_info, start_line, end_line, end_col);
    definitions.push(DefinitionInfo {
      symbol: symbol_info.symbol.clone(),
      start_line,
      start_col,
      end_line: def_end_line,
      end_col: def_end_col,
    });
  }
}

let mut edge_map: HashMap<(String, String, String), EdgeAggregate> = HashMap::new();

for occ in &document.occurrences {
  if is_definition(occ) {
    continue;
  }
  if occ.symbol.is_empty() {
    continue;
  }

  let enclosing = find_enclosing_symbol(occ, &definitions);
  let source_id = enclosing
    .map(|def| def.symbol.clone())
    .unwrap_or_else(|| format!("ts:file:{file_path}"));
  let target_id = occ.symbol.clone();
  if source_id == target_id {
    continue;
  }

  let role = determine_role(occ.symbol_roles);
  let target_kind = symbol_kinds.get(&target_id).copied();
  let edge_type = determine_edge_type(occ, target_kind);

  let (line, column, end_line, end_column) = parse_range(&occ.range);
  let record = OccurrenceRecord {
    line,
    column,
    end_line,
    end_column,
    role,
  };

  edge_map
    .entry((source_id, target_id, edge_type.to_string()))
    .or_default()
    .occurrences
    .push(record);
}

for symbol_info in &document.symbols {
  if symbol_info.symbol.is_empty() {
    continue;
  }
  let source_id = symbol_info.symbol.clone();
  for relationship in &symbol_info.relationships {
    if relationship.symbol.is_empty() {
      continue;
    }
    let target_id = relationship.symbol.clone();
    if source_id == target_id {
      continue;
    }

    let target_kind = symbol_kinds.get(&target_id).copied();
    for edge_type in relationship_edge_types(relationship, target_kind) {
      let record = RelationshipRecord {
        source_symbol: source_id.clone(),
        target_symbol: target_id.clone(),
        is_reference: relationship.is_reference,
        is_implementation: relationship.is_implementation,
        is_type_definition: relationship.is_type_definition,
        is_definition: relationship.is_definition,
      };
      edge_map
        .entry((source_id.clone(), target_id.clone(), edge_type.to_string()))
        .or_default()
        .relationships
        .push(record);
    }
  }
}

    for ((source_id, target_id, edge_type), aggregate) in edge_map {
      let mut metadata = serde_json::Map::new();
      if !aggregate.occurrences.is_empty() {
        metadata.insert("occurrences".to_string(), json!(aggregate.occurrences));
        metadata.insert("totalCount".to_string(), json!(aggregate.occurrences.len()));
      }
      if !aggregate.relationships.is_empty() {
        metadata.insert("relationships".to_string(), json!(aggregate.relationships));
        metadata.insert(
          "relationshipCount".to_string(),
          json!(aggregate.relationships.len()),
        );
      }
      artifacts.edges.push(ScipEdgeInsert {
        source_id: source_id.clone(),
        target_id: target_id.clone(),
        edge_type: edge_type.clone(),
        metadata: (!metadata.is_empty()).then_some(serde_json::Value::Object(metadata.clone())),
      });

      if edge_type == "CALLS" {
        let mut reverse = metadata;
        reverse.insert("derivedFrom".to_string(), json!("CALLS"));
        artifacts.edges.push(ScipEdgeInsert {
          source_id: target_id,
          target_id: source_id,
          edge_type: "CALLED_BY".to_string(),
          metadata: Some(serde_json::Value::Object(reverse)),
        });
      }
    }
  }

  artifacts
}

fn find_definition_occurrence<'a>(
  document: &'a Document,
  symbol_info: &SymbolInformation,
) -> Option<&'a Occurrence> {
  document.occurrences.iter().find(|occ| {
    occ.symbol == symbol_info.symbol && (occ.symbol_roles & SYMBOL_ROLE_DEFINITION) != 0
  })
}

fn is_definition(occ: &Occurrence) -> bool {
  (occ.symbol_roles & SYMBOL_ROLE_DEFINITION) != 0
}

fn parse_range(range: &[i32]) -> (u32, i32, u32, i32) {
  if range.len() == 4 {
    return (
      (range[0].max(0) as u32) + 1,
      range[1],
      (range[2].max(0) as u32) + 1,
      range[3],
    );
  }
  if range.len() == 3 {
    return (
      (range[0].max(0) as u32) + 1,
      range[1],
      (range[0].max(0) as u32) + 1,
      range[2],
    );
  }
  (1, 0, 1, 0)
}

fn determine_role(symbol_roles: i32) -> String {
  if (symbol_roles & SYMBOL_ROLE_IMPORT) != 0 {
    return "import".to_string();
  }
  "reference".to_string()
}

fn determine_edge_type(occ: &Occurrence, target_kind: Option<Kind>) -> &'static str {
  if (occ.symbol_roles & SYMBOL_ROLE_IMPORT) != 0 {
    return "IMPORTS";
  }
  if is_call_occurrence(occ, target_kind) {
    return "CALLS";
  }
  "REFERENCES"
}

fn is_call_occurrence(occ: &Occurrence, target_kind: Option<Kind>) -> bool {
  if !is_callable_kind(target_kind) {
    return false;
  }
  let syntax = occ
    .syntax_kind
    .enum_value()
    .unwrap_or(SyntaxKind::UnspecifiedSyntaxKind);
  matches!(
    syntax,
    SyntaxKind::IdentifierFunction | SyntaxKind::IdentifierOperator
  )
}

fn is_callable_kind(kind: Option<Kind>) -> bool {
  matches!(
    kind.unwrap_or(Kind::UnspecifiedKind),
    Kind::Function
      | Kind::Method
      | Kind::AbstractMethod
      | Kind::StaticMethod
      | Kind::ProtocolMethod
      | Kind::PureVirtualMethod
      | Kind::TraitMethod
      | Kind::TypeClassMethod
      | Kind::MethodSpecification
      | Kind::Constructor
      | Kind::Accessor
      | Kind::Getter
      | Kind::Setter
      | Kind::Operator
      | Kind::MethodAlias
      | Kind::SingletonMethod
  )
}

fn is_interface_like_kind(kind: Option<Kind>) -> bool {
  matches!(
    kind.unwrap_or(Kind::UnspecifiedKind),
    Kind::Interface | Kind::Protocol | Kind::Trait | Kind::TypeClass
  )
}

fn relationship_edge_types(
  relationship: &Relationship,
  target_kind: Option<Kind>,
) -> Vec<&'static str> {
  let mut out = Vec::new();
  if relationship.is_implementation {
    if is_interface_like_kind(target_kind) {
      out.push("IMPLEMENTS");
    } else {
      out.push("EXTENDS");
    }
  }
  if relationship.is_type_definition {
    out.push("HAS_TYPE");
  }
  if relationship.is_definition {
    out.push("OVERRIDES");
  }
  if relationship.is_reference {
    out.push("REFERENCES");
  }
  out
}

fn build_symbol_kind_index(index: &Index) -> HashMap<String, Kind> {
  let mut kinds = HashMap::new();
  for document in &index.documents {
    for symbol in &document.symbols {
      if symbol.symbol.is_empty() {
        continue;
      }
      let kind = symbol.kind.enum_value().unwrap_or(Kind::UnspecifiedKind);
      kinds.entry(symbol.symbol.clone()).or_insert(kind);
    }
  }
  kinds
}

fn find_enclosing_symbol<'a>(
  occ: &Occurrence,
  definitions: &'a [DefinitionInfo],
) -> Option<&'a DefinitionInfo> {
  if !occ.enclosing_range.is_empty() {
    let (line, column, _, _) = parse_range(&occ.enclosing_range);
    if let Some(found) = definitions
      .iter()
      .find(|def| def.start_line == line && def.start_col == column)
    {
      return Some(found);
    }
  }

  let (line, column, _, _) = parse_range(&occ.range);
  definitions
    .iter()
    .filter(|def| {
      if line < def.start_line || line > def.end_line {
        return false;
      }
      if line == def.start_line && column < def.start_col {
        return false;
      }
      if line == def.end_line && column > def.end_col {
        return false;
      }
      true
    })
    .min_by_key(|def| {
      let span = def.end_line.saturating_sub(def.start_line);
      (span, def.start_line, def.start_col)
    })
}

fn extend_definition_range(
  symbol_info: &SymbolInformation,
  start_line: u32,
  end_line: u32,
  end_col: i32,
) -> (u32, i32) {
  let kind = map_symbol_kind(
    symbol_info
      .kind
      .enum_value()
      .unwrap_or(Kind::UnspecifiedKind),
  );
  let symbol = symbol_info.symbol.as_str();
  let looks_like_function = symbol.ends_with("().")
    || symbol.ends_with("()")
    || symbol.contains("()")
    || symbol.contains("#");
  let is_block =
    matches!(kind, "function" | "method" | "class" | "interface") || looks_like_function;
  if is_block {
    return (start_line.saturating_add(1000), 0);
  }
  (end_line, end_col)
}

fn normalize_path(file_path: &str, project_root: &Path) -> String {
  let resolved = Path::new(file_path);
  let resolved = if resolved.is_absolute() {
    resolved.to_path_buf()
  } else {
    project_root.join(resolved)
  };
  if let Ok(rel) = resolved.strip_prefix(project_root) {
    return rel.to_string_lossy().replace('\\', "/");
  }
  file_path.replace('\\', "/")
}

#[cfg(test)]
mod tests {
  use super::*;
  use scip::types::symbol_information::Kind as ScipKind;
  use scip::types::{Occurrence, SymbolInformation};

  #[test]
  fn parses_binary_index() -> Result<(), Box<dyn std::error::Error>> {
    let temp = tempfile::tempdir()?;
    let path = temp.path().join("index.scip");

    let mut doc = Document::new();
    doc.relative_path = "src/foo.ts".to_string();
    doc.language = "typescript".to_string();

    let mut sym = SymbolInformation::new();
    sym.symbol = "scip:foo".to_string();
    sym.display_name = "foo".to_string();

  sym.kind = ScipKind::Function.into();
  doc.symbols.push(sym);

  let mut bar = SymbolInformation::new();
  bar.symbol = "scip:bar".to_string();
  bar.display_name = "bar".to_string();
  bar.kind = ScipKind::Function.into();
  doc.symbols.push(bar);

  let mut def_occ = Occurrence::new();
  def_occ.symbol = "scip:foo".to_string();
  def_occ.range = vec![0, 0, 0, 3];
  def_occ.symbol_roles = SYMBOL_ROLE_DEFINITION;
  doc.occurrences.push(def_occ);

  let mut ref_occ = Occurrence::new();
  ref_occ.symbol = "scip:bar".to_string();
  ref_occ.range = vec![1, 0, 1, 3];
  ref_occ.syntax_kind = SyntaxKind::IdentifierFunction.into();
  ref_occ.enclosing_range = vec![0, 0, 0, 3];
  doc.occurrences.push(ref_occ);

  let mut bar_def = Occurrence::new();
  bar_def.symbol = "scip:bar".to_string();
  bar_def.range = vec![2, 0, 2, 3];
  bar_def.symbol_roles = SYMBOL_ROLE_DEFINITION;
  doc.occurrences.push(bar_def);

  let mut index = Index::new();
  index.documents.push(doc);
  let bytes = index.write_to_bytes()?;
  fs::write(&path, bytes)?;

  let artifacts = ScipBinaryProvider::parse_file(&path, temp.path())?;
  assert_eq!(artifacts.nodes.len(), 3);
  assert_eq!(artifacts.edges.len(), 2);
  assert!(artifacts.edges.iter().any(|edge| edge.edge_type == "CALLS"));
  assert!(artifacts
    .edges
    .iter()
    .any(|edge| edge.edge_type == "CALLED_BY"));
  Ok(())
}

#[test]

fn write_like_occurrence_on_variable_is_reference() -> Result<(), Box<dyn std::error::Error>> {
  let temp = tempfile::tempdir()?;
  let path = temp.path().join("index.scip");

  let mut doc = Document::new();
  doc.relative_path = "src/value.ts".to_string();
