  var.display_name = "value".to_string();
  var.kind = ScipKind::Variable.into();
  doc.symbols.push(var);

  let mut def_occ = Occurrence::new();
  def_occ.symbol = "scip:value".to_string();
  def_occ.range = vec![0, 0, 0, 5];
  def_occ.symbol_roles = SYMBOL_ROLE_DEFINITION;
  doc.occurrences.push(def_occ);

  let mut ref_occ = Occurrence::new();
  ref_occ.symbol = "scip:value".to_string();
