type MetricRow = {
  timestamp: Date
  event: string
  service: string
  environment: string
  region: string | null
  requestId: string | null
  method: string | null
  path: string | null
  status: number | null
  durationMs: number | null
  payload: AppLogPayload
}

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const asSafePayload = (value: AppLogPayload): Record<string, unknown> => asRecord(value) ?? {}

const asDate = (value: unknown): Date | null => {
  if (!value) {
    return null
  }
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = new Date(value)
    return Number.isNaN(parsed.getTime()) ? null : parsed
  }
  return null
}

const asNumber = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }
  if (typeof value === "bigint") {
    return Number(value)
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number.parseFloat(value)
    return Number.isFinite(parsed) ? parsed : null
  }
  return null
}

const asInt = (value: unknown, fallback = 0): number => {
  const parsed = asNumber(value)
  return parsed === null ? fallback : Math.max(0, Math.floor(parsed))
}

const asNullableInt = (value: unknown): number | null => {
  const parsed = asNumber(value)
  return parsed === null ? null : Math.max(0, Math.floor(parsed))
}

const asString = (value: unknown): string | null =>
  typeof value === "string" && value.trim().length > 0 ? value.trim() : null

const lower = (value: string | null | undefined) => (value ?? "").trim().toLowerCase()

const sameIgnoreCase = (left: string | null, right: string | null) =>
  left !== null && right !== null && lower(left) === lower(right)

const percentile = (values: number[], p: number): number | null => {
  if (values.length === 0) {
    return null
  }
  const sorted = [...values].sort((a, b) => a - b)
  const rank = Math.max(0, Math.min(sorted.length - 1, Math.ceil(p * sorted.length) - 1))
  const value = sorted[rank]
  return Number.isFinite(value) ? Math.max(0, Math.round(value)) : null
}

const readThreshold = (key: string, fallback: number): number => {
  const raw = process.env[key]
  if (!raw || raw.trim().length === 0) {
    return fallback
  }
  const parsed = Number.parseFloat(raw)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return fallback
  }
  return parsed
}

const resolveAlertingThresholds = (): ObservabilityAlertingThresholds => ({
  apiMetrics: {
    p95LatencyMsWarning: readThreshold("OBS_ALERT_API_P95_LATENCY_MS_WARNING", 1_000),
    p95LatencyMsCritical: readThreshold("OBS_ALERT_API_P95_LATENCY_MS_CRITICAL", 2_500),
    errorRatePctWarning: readThreshold("OBS_ALERT_API_ERROR_RATE_PCT_WARNING", 2),
    errorRatePctCritical: readThreshold("OBS_ALERT_API_ERROR_RATE_PCT_CRITICAL", 5),
  },
  indexingMetrics: {
    durationMsWarning: readThreshold("OBS_ALERT_INDEXING_DURATION_MS_WARNING", 120_000),
    durationMsCritical: readThreshold("OBS_ALERT_INDEXING_DURATION_MS_CRITICAL", 300_000),
    failuresWarning: readThreshold("OBS_ALERT_INDEXING_FAILURES_WARNING", 5),
    failuresCritical: readThreshold("OBS_ALERT_INDEXING_FAILURES_CRITICAL", 10),
    embeddingApiCallsWarning: readThreshold("OBS_ALERT_INDEXING_EMBEDDING_CALLS_WARNING", 200),
    embeddingApiCallsCritical: readThreshold("OBS_ALERT_INDEXING_EMBEDDING_CALLS_CRITICAL", 1_000),
  },
  llmMetrics: {
    latencyMsWarning: readThreshold("OBS_ALERT_LLM_LATENCY_MS_WARNING", 8_000),
    latencyMsCritical: readThreshold("OBS_ALERT_LLM_LATENCY_MS_CRITICAL", 20_000),
    costUsdWarning: readThreshold("OBS_ALERT_LLM_COST_USD_WARNING", 2),
    costUsdCritical: readThreshold("OBS_ALERT_LLM_COST_USD_CRITICAL", 10),
    totalTokensWarning: readThreshold("OBS_ALERT_LLM_TOTAL_TOKENS_WARNING", 200_000),
    totalTokensCritical: readThreshold("OBS_ALERT_LLM_TOTAL_TOKENS_CRITICAL", 1_000_000),
  },
})

const readProviderAndModel = (payload: Record<string, unknown>) => {
  const labels = asRecord(payload.labels)
  const llmMetrics = asRecord(payload.llmMetrics)
  const provider =
    asString(labels?.provider) ??
    asString(llmMetrics?.provider) ??
    null
  const model =
    asString(labels?.model) ??
    asString(llmMetrics?.model) ??
    asString(payload.model) ??
    null
  return { provider, model }
}

const resolveWindow = (args: {
  sinceRaw?: string
  untilRaw?: string
  windowHours: number
}) => {
  const now = new Date()
  const until = args.untilRaw ? asDate(args.untilRaw) : now
  if (!until) {
    return { error: "Invalid until date." as const, since: null, until: null }
  }
  const since = args.sinceRaw
    ? asDate(args.sinceRaw)
    : new Date(until.getTime() - args.windowHours * 60 * 60 * 1_000)
  if (!since) {
    return { error: "Invalid since date." as const, since: null, until: null }
  }
  if (until.getTime() < since.getTime()) {
    return { error: "until cannot be before since." as const, since: null, until: null }
  }
  return { error: null, since, until }
}

const matchedRows = args.rows.filter((row) => {
  const payload = asSafePayload(row.payload)
  const { provider, model } = readProviderAndModel(payload)
  if (args.providerFilter && !sameIgnoreCase(provider, args.providerFilter)) {
    return false
  }
  if (args.modelFilter && !sameIgnoreCase(model, args.modelFilter)) {
    return false
  }
  return true
})

const apiLatencies: number[] = []
let apiRequestCount = 0
let apiErrorCount = 0
let latestApi: MetricRow | null = null

const indexingDurations: number[] = []
let indexingFilesProcessed = 0
let indexingFailures = 0
let indexingEmbeddingApiCalls = 0
let latestIndexingPendingJobs: number | null = null
let latestIndexingProcessingJobs: number | null = null

const llmLatencies: number[] = []
let llmPromptTokens = 0
let llmCompletionTokens = 0
let llmTotalTokens = 0
let llmRequestCount = 0
let llmCostKnown = false
let llmCostUsd = 0
let llmProvider: string | null = args.providerFilter ?? null
let llmModel: string | null = args.modelFilter ?? null

for (const row of matchedRows) {
  const payload = asSafePayload(row.payload)
  const apiMetrics = asRecord(payload.apiMetrics)
  const indexingMetrics = asRecord(payload.indexingMetrics)
  const llmMetrics = asRecord(payload.llmMetrics)
  const { provider, model } = readProviderAndModel(payload)

  const isApi = row.event.startsWith("api.") || apiMetrics !== null

if (isApi) {
  apiRequestCount += asInt(apiMetrics?.requestCount, 1)
  apiErrorCount += asInt(apiMetrics?.errorCount, row.status !== null && row.status >= 400 ? 1 : 0)
  const latency = asNullableInt(apiMetrics?.requestLatencyMs) ?? asNullableInt(row.durationMs)
  if (latency !== null) {
    apiLatencies.push(latency)
  }
  if (!latestApi) {
    latestApi = row
  }
}

const isIndexing = row.event.startsWith("indexer.") || indexingMetrics !== null
if (isIndexing) {
  const duration = asNullableInt(indexingMetrics?.durationMs) ?? asNullableInt(row.durationMs)
  if (duration !== null) {
    indexingDurations.push(duration)
  }
  indexingFilesProcessed += asInt(indexingMetrics?.filesProcessed, 0)
  indexingFailures += asInt(
    indexingMetrics?.failures,
    row.event.startsWith("indexer.") && row.status !== null && row.status >= 400 ? 1 : 0,
  )
  indexingEmbeddingApiCalls += asInt(indexingMetrics?.embeddingApiCalls, 0)
  const maybePendingJobs = asNullableInt(indexingMetrics?.pendingJobs)
  const maybeProcessingJobs = asNullableInt(indexingMetrics?.processingJobs)
  if (maybePendingJobs !== null && latestIndexingPendingJobs === null) {
    latestIndexingPendingJobs = maybePendingJobs
  }
  if (maybeProcessingJobs !== null && latestIndexingProcessingJobs === null) {
    latestIndexingProcessingJobs = maybeProcessingJobs
  }
}

const isLlm = llmMetrics !== null || row.event.startsWith("api.ai.") || row.event.startsWith("api.review.")

  if (isLlm) {
    llmPromptTokens += asInt(llmMetrics?.promptTokens, 0)
    llmCompletionTokens += asInt(llmMetrics?.completionTokens, 0)
    llmTotalTokens += asInt(llmMetrics?.totalTokens, 0)
    llmRequestCount += asInt(llmMetrics?.requestCount, 1)
    const llmLatency = asNullableInt(llmMetrics?.latencyMs) ?? asNullableInt(payload.latencyMs)
    if (llmLatency !== null) {
      llmLatencies.push(llmLatency)
    }
    const maybeCost = asNumber(llmMetrics?.costUsd)
    if (maybeCost !== null) {
      llmCostKnown = true
      llmCostUsd += Math.max(0, maybeCost)
    }
    if (llmProvider === null && provider) {
      llmProvider = provider
    }
    if (llmModel === null && model) {
      llmModel = model
    }
  }
}

const labels: ObservabilityFilterLabels = {
  service: args.requestedLabels.service ?? latestApi?.service,
  environment: args.requestedLabels.environment ?? latestApi?.environment,
  region: args.requestedLabels.region ?? latestApi?.region ?? undefined,
  event: args.requestedLabels.event ?? latestApi?.event,
  path: args.requestedLabels.path ?? latestApi?.path ?? undefined,
  method: args.requestedLabels.method ?? latestApi?.method ?? undefined,
  status: args.requestedLabels.status ?? latestApi?.status ?? undefined,
  requestId: args.requestedLabels.requestId ?? latestApi?.requestId ?? undefined,
  provider: args.providerFilter ?? llmProvider ?? undefined,
  model: args.modelFilter ?? llmModel ?? undefined,
}

  return {
    labels,
    dimensions,
    apiMetrics: {
      requestLatencyMs: percentile(apiLatencies, 0.95),
      requestCount: apiRequestCount,
      errorCount: apiErrorCount,
      errorRatePct: apiErrorRatePct,
      status: labels.status ?? null,
      method: labels.method ?? null,
      path: labels.path ?? null,
      service: labels.service ?? "argus-app",
      event: labels.event ?? null,
    },
    indexingMetrics: {
      durationMs: percentile(indexingDurations, 0.95),
      filesProcessed: indexingFilesProcessed,
      failures: indexingFailures,
      embeddingApiCalls: indexingEmbeddingApiCalls,
      pendingJobs: latestIndexingPendingJobs ?? args.pendingJobs,
      processingJobs: latestIndexingProcessingJobs ?? args.processingJobs,
    },
    llmMetrics: {
      provider: labels.provider ?? null,
      model: labels.model ?? null,
      promptTokens: llmPromptTokens,
      completionTokens: llmCompletionTokens,
      totalTokens: llmTotalTokens,
      latencyMs: percentile(llmLatencies, 0.95),
      costUsd: llmCostKnown ? Number(llmCostUsd.toFixed(8)) : null,
      requestCount: llmRequestCount,
    },
    alertingThresholds: resolveAlertingThresholds(),
  }
}

