import { describe, expect, mock, test } from "bun:test"

const loadServiceModule = async (dbMock: {
  select: () => {
    from: () => {
      where: () => {
        orderBy: () => {
          limit: () => Promise<Array<{ createdAt: Date }>>
        }
      }
    }
  }
  insert: () => {
    values: (value: unknown) => Promise<unknown>
  }
}) => {
  mock.module("@/lib/db", () => ({ db: dbMock }))
  return import(`@/lib/onboarding/service.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
}

const createDbMock = (limitResponses: Array<Array<{ createdAt: Date }>>) => {
  const insertValues: unknown[] = []
  const queued = [...limitResponses]

  const dbMock = {
    select: () => ({
      from: () => ({
        where: () => ({
          orderBy: () => ({
            limit: () => Promise.resolve(queued.shift() ?? []),
          }),
        }),
      }),
    }),
    insert: () => ({
      values: (value: unknown) => {
        insertValues.push(value)
        return Promise.resolve([])
      },
    }),
  }

  return { dbMock, insertValues }
}

describe("onboarding service", () => {

test("records onboarding completion once and computes duration", async () => {
  const startedAt = new Date(Date.now() - 12_000)
  const { dbMock, insertValues } = createDbMock([[], [{ createdAt: startedAt }]])
  const mod = await loadServiceModule(dbMock)

  const result = await mod.recordOnboardingCompletedIfMissing({
    userId: "user-1",
    metadata: {
      completionSource: "first_ai_review",
      findingsCount: 3,
    },
  })

  expect(result.alreadyCompleted).toBe(false)
  expect(result.onboardingDurationMs).toBeTypeOf("number")
  expect((result.onboardingDurationMs ?? 0) >= 10_000).toBe(true)
  expect(insertValues).toHaveLength(1)
  expect(insertValues[0]).toMatchObject({
    userId: "user-1",
    event: "onboarding_completed",
    metadata: expect.objectContaining({
      completionSource: "first_ai_review",
      findingsCount: 3,
    }),
  })
})

test("skips insert when onboarding is already completed", async () => {
  const completedAt = new Date(Date.now() - 5_000)
  const { dbMock, insertValues } = createDbMock([[{ createdAt: completedAt }]])
  const mod = await loadServiceModule(dbMock)

  const result = await mod.recordOnboardingCompletedIfMissing({
    userId: "user-1",
    metadata: { completionSource: "manual" },
  })

  expect(result.alreadyCompleted).toBe(true)
  expect(result.onboardingCompletedAt).toBe(completedAt)
  expect(insertValues).toHaveLength(0)
})

  test("reports completion state", async () => {
    const completedAt = new Date()
    const completedMock = createDbMock([[{ createdAt: completedAt }]])
    const incompleteMock = createDbMock([[]])

    const completedMod = await loadServiceModule(completedMock.dbMock)
    expect(await completedMod.isOnboardingCompleted("user-1")).toBe(true)

    const incompleteMod = await loadServiceModule(incompleteMock.dbMock)
    expect(await incompleteMod.isOnboardingCompleted("user-1")).toBe(false)
  })
})

import { and, eq } from "drizzle-orm"
import { NextResponse } from "next/server"

import { db } from "@/lib/db"
import { aiReviewCommentFeedback, aiReviewRuns, type AiReviewFinding } from "@/lib/db/schema"
import { buildReviewCommentFeedbackKey, isReviewFeedbackValue, normalizeReviewCommentFeedbackKey } from "@/lib/review/comment-feedback"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

type FeedbackPayload = {
  reviewId?: unknown
  commentKey?: unknown
  feedback?: unknown
}

const normalizeReviewId = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

const normalizeFeedback = (value: unknown): "up" | "down" | null | undefined => {
  if (value === null) {
    return null
  }
  if (typeof value !== "string") {
    return undefined
  }
  const normalized = value.trim().toLowerCase()
  if (!normalized) {
    return null
  }
  if (isReviewFeedbackValue(normalized)) {
    return normalized
  }
  return undefined
}

const hasCommentKeyInFindings = ({
  findings,
  commentKey,
}: {
  findings: AiReviewFinding[]
  commentKey: string
}) => {
  return findings.some((finding) =>
    buildReviewCommentFeedbackKey({
      file: finding.file,
      side: finding.side,
      line: finding.line,
      title: finding.title,
    }) === commentKey,
  )
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/feedback",
    event: "api.review.feedback",
    handler: async ({ logger }) => {

const [userId, payload] = await Promise.all([
  getSessionUserId(),
  request.json().catch(() => null) as Promise<FeedbackPayload | null>,
])
if (!userId) {
  return {
    status: 401,
    outcome: "unauthorized",
    response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
  }
}
const reviewId = normalizeReviewId(payload?.reviewId)
const commentKey = normalizeReviewCommentFeedbackKey(payload?.commentKey)
const feedback = normalizeFeedback(payload?.feedback)

if (!reviewId) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "reviewId is required." }, { status: 400 }),
  }
}
if (feedback === undefined) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "feedback must be one of: up, down, or null." },
      { status: 400 },
    ),
  }
}

if (commentKey) {
  const reviewRows = await db
    .select({
      id: aiReviewRuns.id,
      findings: aiReviewRuns.findings,
    })
    .from(aiReviewRuns)
    .where(and(eq(aiReviewRuns.id, reviewId), eq(aiReviewRuns.userId, userId)))
    .limit(1)

  const review = reviewRows[0]

if (!review) {
  return {
    status: 404,
    outcome: "not_found",
    response: NextResponse.json({ error: "Review not found." }, { status: 404 }),
  }
}

const findings = review.findings as AiReviewFinding[]
if (!hasCommentKeyInFindings({ findings, commentKey })) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "commentKey is not associated with this review." },
      { status: 400 },
    ),
  }
}

if (feedback === null) {
  await db
    .delete(aiReviewCommentFeedback)
    .where(
      and(
        eq(aiReviewCommentFeedback.reviewId, reviewId),
        eq(aiReviewCommentFeedback.userId, userId),
        eq(aiReviewCommentFeedback.commentKey, commentKey),
      ),
    )

  logger.set({
    reviewId,
    commentKey,
    feedback,
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        commentFeedback: {
          reviewId,
          commentKey,
          feedback: null,
          submittedAt: null,
        },
      },
    }),
  }
}

const now = new Date()

  const rows = await db
    .insert(aiReviewCommentFeedback)
    .values({
      reviewId,
      userId,
      commentKey,
      feedback,
      submittedAt: now,
    })
    .onConflictDoUpdate({
      target: [aiReviewCommentFeedback.reviewId, aiReviewCommentFeedback.commentKey],
      set: {
        feedback,
        submittedAt: now,
      },
    })
    .returning({
      reviewId: aiReviewCommentFeedback.reviewId,
      commentKey: aiReviewCommentFeedback.commentKey,
      feedback: aiReviewCommentFeedback.feedback,
      submittedAt: aiReviewCommentFeedback.submittedAt,
    })

  const row = rows[0]
  logger.set({
    reviewId,
    commentKey,
    feedback,
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        commentFeedback: {
          reviewId: row?.reviewId ?? reviewId,
          commentKey: row?.commentKey ?? commentKey,
          feedback: row?.feedback ?? feedback,
          submittedAt: row?.submittedAt?.toISOString() ?? now.toISOString(),
        },
      },
    }),
  }
}

const now = new Date()

      const rows = await db
        .update(aiReviewRuns)
        .set({
          feedback,
          feedbackSubmittedAt: feedback === null ? null : now,
        })
        .where(and(eq(aiReviewRuns.id, reviewId), eq(aiReviewRuns.userId, userId)))
        .returning({
          id: aiReviewRuns.id,
          feedback: aiReviewRuns.feedback,
          feedbackSubmittedAt: aiReviewRuns.feedbackSubmittedAt,
        })

      if (!rows[0]) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Review not found." }, { status: 404 }),
        }
      }

      logger.set({
        reviewId,
        feedback,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            review: {
              id: rows[0].id,
              feedback: rows[0].feedback,
              feedbackSubmittedAt: rows[0].feedbackSubmittedAt?.toISOString() ?? null,
            },
          },
        }),
      }
    },
  })
}

