import { normalizeJiraInstanceUrl } from "@/lib/jira/instance"

type JiraRequestConfig = {
  baseUrl: string
  email: string
  token: string
}

type JiraUser = {
  accountId: string
  emailAddress?: string
  displayName?: string
}

type JiraBoard = {
  id: number
  name: string
  type: string
  location?: {
    projectKey?: string
    projectName?: string
  }
}

type JiraSprint = {
  id: number
  state: string
  name: string
  startDate?: string
  endDate?: string
  goal?: string
}

type JiraIssue = {
  id: string
  key: string
  fields: {
    summary?: string
    status?: {
      name?: string
      statusCategory?: {
        name?: string
      }
    }
    assignee?: {
      displayName?: string
    } | null
    reporter?: {
