  }
}

type JiraAgilePagedResponse<T> = {
  maxResults: number
  startAt: number
  total?: number
  isLast: boolean
  values: T[]
}

type JiraSearchResponse = {
  total: number
  issues: JiraIssue[]
}

export type JiraValidationResult = {
  isValid: boolean
  user?: {
    displayName: string
    emailAddress: string
