use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::time::UNIX_EPOCH;

use sha2::Digest;

use super::chunker::TreeSitterChunker;
use super::file_discovery::{find_files, FileDiscoveryOptions};
use super::types::{CodeChunk, ParsedFile};
use crate::core::cache::CacheState;
use crate::core::cancel::CancelToken;
use crate::core::index_pack::writer::IndexPackWriter;

#[derive(Debug, Clone)]
pub struct ParseInputs {
  pub paths: Vec<PathBuf>,
  pub include: Vec<String>,
  pub exclude: Vec<String>,
  pub respect_gitignore: bool,
}

impl Default for ParseInputs {
  fn default() -> Self {
    Self {
      paths: Vec::new(),
      include: Vec::new(),
      exclude: Vec::new(),
      respect_gitignore: true,
    }
  }
}

#[derive(Debug, Clone)]
pub struct ParseOptions {
  pub project_root: PathBuf,
  pub inputs: ParseInputs,
  pub batch_size: usize,
}

impl ParseOptions {
  pub fn new(project_root: impl Into<PathBuf>) -> Self {
    Self {
      project_root: project_root.into(),
      inputs: ParseInputs::default(),
      batch_size: 256,
    }
  }
}

#[derive(Debug, Default, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ParseStats {
  pub files_parsed: u64,
  pub files_skipped: u64,
  pub chunks_emitted: u64,
}

#[derive(Debug)]
pub enum ParseError {
  Io(std::io::Error),
  Cancelled,
}

impl std::fmt::Display for ParseError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      ParseError::Io(err) => write!(f, "parse io error: {err}"),
      ParseError::Cancelled => write!(f, "cancelled"),
    }
  }
}

impl std::error::Error for ParseError {}

impl From<std::io::Error> for ParseError {
  fn from(value: std::io::Error) -> Self {
    ParseError::Io(value)
  }
}

pub trait ParseSink {
  fn on_parse_batch_ref(&mut self, _batch: &[CodeChunk]) {}
}

#[derive(Debug, Clone, Copy, Default)]
pub struct ParseCachePolicy {
  // When true, unchanged files may return `skipped: true` with empty chunks.
  pub allow_skip: bool,
  // When true, bypass skip checks even if allow_skip is enabled.
  pub force: bool,
}

pub fn run_parse(
  options: &ParseOptions,
  cancel: &CancelToken,
  cache: Option<&mut CacheState>,
  cache_policy: ParseCachePolicy,
  sink: &mut dyn ParseSink,
  mut index_pack: Option<&mut IndexPackWriter>,
) -> Result<(Vec<ParsedFile>, ParseStats), ParseError> {
  // Parse first so sinks can consume stable, ordered batch slices per file.
  let (files, stats) = collect_parsed_files(options, cancel, cache, cache_policy)?;
  let batch_size = if options.batch_size == 0 {
    1
  } else {
    options.batch_size
  };

  for file in &files {
    cancel.check().map_err(|_| ParseError::Cancelled)?;
    for chunk_batch in file.chunks.chunks(batch_size) {
      cancel.check().map_err(|_| ParseError::Cancelled)?;
      if let Some(writer) = index_pack.as_deref_mut() {
        for chunk in chunk_batch {
          writer.write_chunk(chunk)?;
        }
      }
      sink.on_parse_batch_ref(chunk_batch);
    }
  }

  Ok((files, stats))
}

pub fn collect_parsed_files(
  options: &ParseOptions,
  cancel: &CancelToken,
  mut cache: Option<&mut CacheState>,
  cache_policy: ParseCachePolicy,
) -> Result<(Vec<ParsedFile>, ParseStats), ParseError> {
  let mut stats = ParseStats::default();
  let mut parsed_files = Vec::new();

  let files = discover_files(&options.project_root, &options.inputs, cancel)?;
  for path in files {
    cancel.check().map_err(|_| ParseError::Cancelled)?;
    let parsed = if let Some(cache) = cache.as_deref_mut() {
      parse_file(&path, options, Some(cache), cache_policy)?
    } else {
      parse_file(&path, options, None, cache_policy)?
    };
    if parsed.skipped {
      stats.files_skipped += 1;
    } else {
      stats.files_parsed += 1;
      stats.chunks_emitted += parsed.chunks.len() as u64;
    }
    parsed_files.push(parsed);
  }

  Ok((parsed_files, stats))
}

fn parse_file(
  path: &Path,
  options: &ParseOptions,
  mut cache: Option<&mut CacheState>,
  cache_policy: ParseCachePolicy,
) -> Result<ParsedFile, ParseError> {
  // Canonical paths keep cache keys stable across different path spellings.
  let absolute = canonical_path(path);
  let cache_key = absolute.to_string_lossy().to_string();
  let file_rel = relative_path(&options.project_root, path);
  let allow_skip = cache_policy.allow_skip && !cache_policy.force;

if let Some(cache) = cache.as_mut() {
  if allow_skip {
    // Fast path: compare mtime/size signature before reading file contents.
    let mtime_key = format!("mtime:{cache_key}");
    if let Some(current_mtime) = file_mtime_signature(&absolute) {
      if let Some(cached_mtime) = cache.get(&mtime_key) {
        if cached_mtime == current_mtime && cache.get(&cache_key).is_some() {
          return Ok(ParsedFile {
            file_path: file_rel,
            chunks: Vec::new(),
            skipped: true,
          });
        }
      }
    }
  }
}

let content = std::fs::read_to_string(path)?;
let hash = hash_content(&content);

if let Some(cache) = cache.as_mut() {
  if allow_skip {
    // Hash fallback handles filesystems with coarse mtime precision.
    if let Some(cached_hash) = cache.get(&cache_key) {
      if cached_hash == hash {
        if let Some(current_mtime) = file_mtime_signature(&absolute) {
          cache.set(format!("mtime:{cache_key}"), current_mtime);
        }
        return Ok(ParsedFile {
          file_path: file_rel,
          chunks: Vec::new(),
          skipped: true,
        });
      }
    }
  }
}

let chunks = TreeSitterChunker::chunk_file(&file_rel, &content, None);

  if let Some(cache) = cache.as_mut() {
    // Persist both content hash and mtime signature to optimize future skip checks.
    cache.set(cache_key.clone(), hash.clone());
    if let Some(current_mtime) = file_mtime_signature(&absolute) {
      cache.set(format!("mtime:{cache_key}"), current_mtime);
    }
  }

  Ok(ParsedFile {
    file_path: file_rel,
    chunks,
    skipped: false,
  })
}

fn canonical_path(path: &Path) -> PathBuf {
  path.canonicalize().unwrap_or_else(|_| path.to_path_buf())
}

fn file_mtime_signature(path: &Path) -> Option<String> {
  let metadata = std::fs::metadata(path).ok()?;
  let modified = metadata.modified().ok()?;
  let duration = modified.duration_since(UNIX_EPOCH).ok()?;
  Some(format!("{}:{}", duration.as_millis(), metadata.len()))
}

fn hash_content(content: &str) -> String {
  let mut hasher = sha2::Sha256::new();
  hasher.update(content.as_bytes());
  let digest = hasher.finalize();
  format!("{digest:x}")
}

pub fn discover_files(
  project_root: &Path,
  inputs: &ParseInputs,
  cancel: &CancelToken,
) -> Result<Vec<PathBuf>, ParseError> {
  cancel.check().map_err(|_| ParseError::Cancelled)?;
  let mut targets = Vec::new();
  if inputs.paths.is_empty() {
    targets.push(project_root.to_path_buf());
  } else {
    targets.extend(inputs.paths.clone());
  }

  let mut files = Vec::new();
  let mut seen = HashSet::new();

  for target in targets {
    cancel.check().map_err(|_| ParseError::Cancelled)?;
    if target.is_file() {
      // De-duplicate explicit files and discovered files from overlapping roots.
      if seen.insert(target.clone()) {
        files.push(target);
      }
      continue;
    }

    let options = FileDiscoveryOptions {
      base_path: target,
      include_patterns: inputs.include.clone(),
      exclude_patterns: inputs.exclude.clone(),
      respect_gitignore: inputs.respect_gitignore,
    };

    let discovered = find_files(&options).map_err(|err| {
      ParseError::Io(std::io::Error::new(
        std::io::ErrorKind::InvalidInput,
        err.to_string(),
      ))
    })?;

    for file in discovered {
      cancel.check().map_err(|_| ParseError::Cancelled)?;
      if seen.insert(file.clone()) {
        files.push(file);
      }
    }
  }

  Ok(files)
}

fn relative_path(project_root: &Path, path: &Path) -> String {
  path
    .strip_prefix(project_root)
    .unwrap_or(path)
    .to_string_lossy()
    .replace('\\', "/")
}

