  )
  .expect("parse files");
  let mut actual: Vec<ExpectedParsedFile> = parsed_files
    .into_iter()
    .map(|file| ExpectedParsedFile {
      file_path: file.file_path,
      chunks: file.chunks,
    })
    .collect();

  sort_parsed_files(&mut expected);
  sort_parsed_files(&mut actual);

  let actual_value = serde_json::to_value(actual).expect("serialize actual");
  let expected_value = serde_json::to_value(expected).expect("serialize expected");
  assert_eq!(actual_value, expected_value);
}

  fn sort_parsed_files(files: &mut [ExpectedParsedFile]) {
    for file in files.iter_mut() {
      file
        .chunks
        .sort_by(|a, b| a.id.cmp(&b.id).then(a.kind.cmp(&b.kind)));
    }
    files.sort_by(|a, b| a.file_path.cmp(&b.file_path));
  }
}

