const createInitialReviewRunState = (): ReviewRunState => ({
  stage: "idle",
  totalBatches: 0,
  completedBatches: 0,
  currentBatchIndex: 0,
  currentBatchFiles: [],
  reviewedFiles: [],
  failedFiles: [],
  startedAt: null,
  finishedAt: null,
  events: [],
})

const extractFilePathsFromPatch = (patchText: string) => {
  const matches = Array.from(patchText.matchAll(/^diff --git a\/(.+?) b\/(.+)$/gm))
  const paths = matches
    .map((match) => normalizePatchPath(match[2] ?? match[1] ?? ""))
    .filter((path) => path.length > 0)
  return Array.from(new Set(paths))
}

const dedupeFindings = (findings: ReviewFinding[]) => {
  const deduped = new Map<string, ReviewFinding>()
  for (const finding of findings) {
    const normalizedFile = normalizePatchPath(finding.file)
    const key = buildReviewCommentFeedbackKey({
      file: normalizedFile,
      side: finding.side,
      line: finding.line,
      title: finding.title,
    })
    const normalizedFinding = {
      ...finding,
      file: normalizedFile,
    }
    const current = deduped.get(key)
    if (!current) {
      deduped.set(key, normalizedFinding)
      continue
    }

    if (normalizedFinding.confidence > current.confidence) {
      deduped.set(key, normalizedFinding)
      continue
    }

    if (normalizedFinding.confidence === current.confidence) {
      const currentEvidenceLength = (current.evidence ?? "").trim().length
      const nextEvidenceLength = (normalizedFinding.evidence ?? "").trim().length
      if (nextEvidenceLength > currentEvidenceLength) {
        deduped.set(key, normalizedFinding)
      }
    }
  }
  return Array.from(deduped.values())
}

const buildReviewSummary = (findings: ReviewFinding[]) => {
  if (findings.length === 0) {
    return "AI review complete. No findings."
  }

  const highCount = findings.filter((finding) => finding.severity === "high").length
  const medCount = findings.filter((finding) => finding.severity === "med").length
  const lowCount = findings.length - highCount - medCount
  return `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`
}

const getCommentPublishErrorMessage = (value: unknown) => {
  if (
    value instanceof Error &&
    (value.name === "AbortError" || value.name === "TimeoutError")
  ) {
    return COMMENT_PUBLISH_TIMEOUT_ERROR
  }
  const message = getErrorMessage(value)
  return message === DIFF_LOAD_ERROR_MESSAGE ? COMMENT_PUBLISH_FALLBACK_ERROR : message
}

const getCommentRemoveErrorMessage = (value: unknown) => {
  if (
    value instanceof Error &&
    (value.name === "AbortError" || value.name === "TimeoutError")
  ) {
    return COMMENT_REMOVE_TIMEOUT_ERROR
  }
  const message = getErrorMessage(value)
  return message === DIFF_LOAD_ERROR_MESSAGE ? COMMENT_REMOVE_FALLBACK_ERROR : message
}

type ReviewBatch = {
  patch: string
  files: string[]
}

const buildReviewBatches = (patchText: string): ReviewBatch[] => {
  const patchChunks = splitPatchIntoFileChunks(patchText)
  if (patchChunks.length === 0) {
    return [
      {
        patch: patchText,
        files: extractFilePathsFromPatch(patchText),
      },
    ]
  }

  const groupedChunks: string[][] = []
  let currentBatch: string[] = []
  let currentBatchCharLength = 0

  for (const chunk of patchChunks) {
    const separatorCharLength = currentBatch.length > 0 ? 2 : 0
    const candidateLength = currentBatchCharLength + separatorCharLength + chunk.length
    const exceedsFileLimit = currentBatch.length >= REVIEW_BATCH_FILE_COUNT
    const exceedsCharLimit = candidateLength > REVIEW_BATCH_MAX_PATCH_CHARS

    if (currentBatch.length > 0 && (exceedsFileLimit || exceedsCharLimit)) {
      groupedChunks.push(currentBatch)
      currentBatch = [chunk]
      currentBatchCharLength = chunk.length
      continue
    }

    currentBatch.push(chunk)
    currentBatchCharLength = candidateLength
  }

  if (currentBatch.length > 0) {
    groupedChunks.push(currentBatch)
  }

  return groupedChunks.map((chunks) => {
    const joinedPatch = chunks.join("\n\n")
    return {
      patch: joinedPatch,
      files: extractFilePathsFromPatch(joinedPatch),
    }
  })
}

const normalizeFeedback = (value: unknown): ReviewFeedback | null => {
  if (value === "up" || value === "down") {
    return value
  }
  return null
}

const toSuppressedFindingsCount = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0) {
    return 0
  }
  return Math.floor(value)
}

export function useMergeRequestAiReview({
  instanceUrl,
  token: _token,
  integrationId,
  projectId,
  mergeRequestIid,
