  const [isReviewing, setIsReviewing] = useState(false)
  const [reviewError, setReviewError] = useState("")
  const [reviewSummary, setReviewSummary] = useState("")
  const [reviewFindings, setReviewFindings] = useState<ReviewFinding[]>([])
  const [suppressedReviewFindingsCount, setSuppressedReviewFindingsCount] = useState(0)
  const [reviewRun, setReviewRun] = useState<ReviewRunState>(() => createInitialReviewRunState())
  const [reviewId, setReviewId] = useState<string | null>(null)
  const [reviewFeedback, setReviewFeedback] = useState<ReviewFeedback | null>(null)
  const [isSubmittingReviewFeedback, setIsSubmittingReviewFeedback] = useState(false)
  const [reviewFeedbackError, setReviewFeedbackError] = useState("")
  const [reviewCommentFeedbackByKey, setReviewCommentFeedbackByKey] = useState<
    Record<string, ReviewFeedback>
  >({})
  const [reviewCommentFeedbackErrorByKey, setReviewCommentFeedbackErrorByKey] = useState<
    Record<string, string>
  >({})
  const [submittingReviewCommentFeedbackKeys, setSubmittingReviewCommentFeedbackKeys] = useState<
    Set<string>
  >(() => new Set())
  const [reviewCommentPostedToGitLabKeys, setReviewCommentPostedToGitLabKeys] = useState<
    Set<string>
  >(() => new Set())

const applyPersistedCommentPublishByKey = useCallback(
  (commentPublishByKey: Record<string, ReviewCommentPublishState>) => {
    const postedKeys = new Set<string>()
    const postingKeys = new Set<string>()
    const errorsByKey: Record<string, string> = {}

    for (const [commentKey, state] of Object.entries(commentPublishByKey)) {
      if (state.status === "succeeded") {
        postedKeys.add(commentKey)
        continue
      }
      if (state.status === "pending" || state.status === "processing") {
        postingKeys.add(commentKey)
      }
      if ((state.status === "failed" || state.status === "dead") && state.lastError.trim()) {
        errorsByKey[commentKey] = state.lastError.trim()
      }
    }

    setReviewCommentPostedToGitLabKeys(postedKeys)
    setSubmittingReviewCommentGitLabKeys(postingKeys)
    setRemovingReviewCommentGitLabKeys(new Set())
    setReviewCommentGitLabErrorByKey(errorsByKey)
  },
  [],
)

const applyReviewImpactPayload = useCallback((value: unknown) => {
  const normalized = normalizeReviewImpact(value)
  if (!normalized) {
    return null
  }
  setReviewImpactByKey(normalized.impactByKey)
  setReviewImpactStatus(normalized.status)
  return normalized
}, [])

const requestReviewImpact = useCallback(
  async ({
    reviewId: targetReviewId,
    method,
    force,
  }: {
    reviewId: string
    method: "GET" | "POST"
    force?: boolean
  }) => {
    const normalizedReviewId = targetReviewId.trim()
    if (!normalizedReviewId) {
      return null
    }

    const response =
      method === "GET"
        ? await fetch(
            `/api/review/impact?${new URLSearchParams({ reviewId: normalizedReviewId }).toString()}`,
            {
              method: "GET",
            },
          )
        : await fetch("/api/review/impact", {
            method: "POST",
            headers: {
              "content-type": "application/json",
            },
            body: JSON.stringify({
              reviewId: normalizedReviewId,
              force: force === true,
            }),
          })

    const payload = (await response.json().catch(() => null)) as
      | {
          data?: unknown
          error?: unknown
        }
      | null
    if (!response.ok) {
      throw new Error(getReviewErrorMessage(payload))
    }

    return applyReviewImpactPayload(payload?.data)
  },
  [applyReviewImpactPayload],
)

const loadReviewImpact = useCallback(
  async (targetReviewId: string) => {
    setIsLoadingReviewImpact(true)
    try {
      const loaded = await requestReviewImpact({
        reviewId: targetReviewId,
        method: "GET",
      })
      if (
        loaded &&
        (loaded.status === "not_started" || loaded.status === "in_progress")
      ) {
        await requestReviewImpact({
          reviewId: targetReviewId,
          method: "POST",
          force: false,
        }).catch(() => null)
      }
    } catch {
      setReviewImpactByKey({})
      setReviewImpactStatus("not_started")
    } finally {
      setIsLoadingReviewImpact(false)
    }
  },
  [requestReviewImpact],
)

const computeReviewImpact = useCallback(
  async (targetReviewId: string, force = false) => {
    setIsLoadingReviewImpact(true)
    try {
      await requestReviewImpact({
        reviewId: targetReviewId,
        method: "POST",
        force,
      })
    } catch {
      setReviewImpactByKey({})
      setReviewImpactStatus("not_started")
    } finally {
      setIsLoadingReviewImpact(false)
    }
  },
  [requestReviewImpact],
)

const appendReviewRunEvent = useCallback(
