import { beforeEach, describe, expect, mock, test } from 'bun:test'

const loadChunkerModule = async (chunkWithArgusSearch: ReturnType<typeof mock>) => {
  mock.module('@/lib/indexing/engines/argus-search', () => ({
    chunkWithArgusSearch,
  }))

  return import(`@/lib/indexing/chunker.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
}

beforeEach(() => {
  delete process.env.INDEXER_EMBEDDING_MAX_INPUT_TOKENS
  delete process.env.INDEXER_EMBEDDING_CHUNK_OVERLAP_TOKENS
})

describe('buildVectorChunks', () => {
  test('keeps single chunk when input is within budget', async () => {
    process.env.INDEXER_EMBEDDING_MAX_INPUT_TOKENS = '64'
    process.env.INDEXER_EMBEDDING_CHUNK_OVERLAP_TOKENS = '8'

    const chunkWithArgusSearch = mock(async () => [
      {
        chunkId: 'chunk-1',
        chunkIndex: 0,
        content: 'const ok = true',
        metadata: { kind: 'code' },
      },
    ])

    const { buildVectorChunks } = await loadChunkerModule(chunkWithArgusSearch)
    const result = await buildVectorChunks({
      path: 'src/a.ts',
      content: 'const ok = true',
      configHash: 'default-v1',
    })

    expect(result).toHaveLength(1)
    expect(result[0]?.chunkIndex).toBe(0)
    expect(result[0]?.content).toBe('const ok = true')
    expect(result[0]?.metadata).toMatchObject({
      kind: 'code',
      embeddingChunking: {
        sourceChunkId: 'chunk-1',
        sourceChunkIndex: 0,
        split: false,
        segmentIndex: 0,
        segmentCount: 1,
        maxInputTokens: 64,
        overlapTokens: 8,
      },
    })
  })

test('splits oversized chunk with overlap', async () => {
  process.env.INDEXER_EMBEDDING_MAX_INPUT_TOKENS = '12'
  process.env.INDEXER_EMBEDDING_CHUNK_OVERLAP_TOKENS = '4'

  const chunkWithArgusSearch = mock(async () => [
    {
      chunkId: 'chunk-oversized',
      chunkIndex: 0,
      content: '0123456789ABCDEFGHIJ',
      metadata: { language: 'txt' },
    },
  ])

  const { buildVectorChunks } = await loadChunkerModule(chunkWithArgusSearch)
  const result = await buildVectorChunks({
    path: 'docs/large.txt',
    content: '0123456789ABCDEFGHIJ',
    configHash: 'default-v1',
  })

  expect(result).toHaveLength(2)
  expect(result[0]?.chunkIndex).toBe(0)
  expect(result[1]?.chunkIndex).toBe(1)
  expect(result[0]?.content).toBe('0123456789AB')
  expect(result[1]?.content).toBe('89ABCDEFGHIJ')
  expect(result[1]?.content.slice(0, 4)).toBe(result[0]?.content.slice(-4))
  expect(result[0]?.metadata).toMatchObject({
    embeddingChunking: {
      split: true,
      segmentIndex: 0,
      segmentCount: 2,
      maxInputTokens: 12,
      overlapTokens: 4,
    },
  })
  expect(result[1]?.metadata).toMatchObject({
    embeddingChunking: {
      split: true,
      segmentIndex: 1,
      segmentCount: 2,
    },
  })
})

  test('keeps chunk indexes contiguous after filtering empty chunks', async () => {
    process.env.INDEXER_EMBEDDING_MAX_INPUT_TOKENS = '32'
    process.env.INDEXER_EMBEDDING_CHUNK_OVERLAP_TOKENS = '4'

    const chunkWithArgusSearch = mock(async () => [
      {
        chunkId: 'blank',
        chunkIndex: 0,
        content: '   \n\t ',
        metadata: {},
      },
      {
        chunkId: 'real',
        chunkIndex: 1,
        content: 'hello',
        metadata: {},
      },
    ])

    const { buildVectorChunks } = await loadChunkerModule(chunkWithArgusSearch)
    const result = await buildVectorChunks({
      path: 'docs/mixed.txt',
      content: 'hello',
      configHash: 'default-v1',
    })

    expect(result).toHaveLength(1)
    expect(result[0]?.chunkIndex).toBe(0)
    expect(result[0]?.content).toBe('hello')
  })
})

