import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

import test from 'ava'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')

function loadSdkWithMocks(mockNative: any, mockStream: any) {
  const sdkPath = path.join(packageRoot, 'sdk.js')
  const requireFromSdk = createRequire(sdkPath)

  const nativeResolved = requireFromSdk.resolve('./index.js')
  const streamResolved = requireFromSdk.resolve('./stream.js')
  const sdkResolved = requireFromSdk.resolve('./sdk.js')

  const prevNative = requireFromSdk.cache[nativeResolved]
  const prevStream = requireFromSdk.cache[streamResolved]
  const prevSdk = requireFromSdk.cache[sdkResolved]

  requireFromSdk.cache[nativeResolved] = {
    id: nativeResolved,
    filename: nativeResolved,
    loaded: true,
    exports: mockNative,
  } as any
  requireFromSdk.cache[streamResolved] = {
    id: streamResolved,
    filename: streamResolved,
    loaded: true,
    exports: mockStream,
  } as any
  delete requireFromSdk.cache[sdkResolved]

  const mod = requireFromSdk('./sdk.js') as any
  const restore = () => {
    if (prevNative) requireFromSdk.cache[nativeResolved] = prevNative
    else delete requireFromSdk.cache[nativeResolved]
    if (prevStream) requireFromSdk.cache[streamResolved] = prevStream
    else delete requireFromSdk.cache[streamResolved]
    if (prevSdk) requireFromSdk.cache[sdkResolved] = prevSdk
    else delete requireFromSdk.cache[sdkResolved]
  }

  return { mod, restore }
}

