      },
    },
  )
  t.teardown(restore)

  const oldKey = process.env.OPENAI_API_KEY
  process.env.OPENAI_API_KEY = 'env-token'
  t.teardown(() => {
    if (oldKey == null) delete process.env.OPENAI_API_KEY
    else process.env.OPENAI_API_KEY = oldKey
  })

  const ix = new mod.Indexer({ root: '/repo' }).useVectors({ model: 'text-embedding-3-small' })
