              },
            }
          },
        }
      },
    },
  )
  t.teardown(restore)

  const ix = new mod.Indexer({ root: '/repo' })
    .paths('src', ['packages'])
    .include('*.ts', '*.tsx')
    .exclude('node_modules')
    .useGitignore(false)

  ix.stream({ batchSize: 32, highWaterMark: 8, graph: true })

  t.deepEqual(calls.stream.options.inputs.paths, [path.join('/repo', 'src'), path.join('/repo', 'packages')])
  t.deepEqual(calls.stream.options.inputs.include, ['*.ts', '*.tsx'])
  t.deepEqual(calls.stream.options.inputs.exclude, ['node_modules'])
  t.false(calls.stream.options.inputs.respectGitignore)
  t.is(calls.stream.options.hooks.parseBatch, 32)
  t.is(calls.stream.options.hooks.graphBatch, 32)
  t.is(calls.stream.options.hooks.vectorBatch, 32)
  t.is(calls.stream.options.hooks.scipBatch, 32)
  t.is(calls.stream.stream.highWaterMark, 8)
})

