import { notFound, redirect } from "next/navigation";

import {
	buildRepoMergeRequestDescriptionPath,
	buildRepoMergeRequestPath,
	buildRepoPath,
	buildRepoRouteId,
	findIntegrationByRepoRouteId,
} from "@/lib/gitlab/repo-route";
import { MergeRequestDiffViewerClient } from "@/components/merge-request-diff/merge-request-diff-viewer-client";
import { getCachedUserIntegrations } from "@/lib/gitlab/user-integrations-cache";
import { getSession } from "@/lib/session";

type MergeRequestReviewPageProps = {
	params: Promise<{
		integrationId: string;
		mergeRequestIid: string;
	}>;
};

export default async function MergeRequestReviewPage({
	params,
}: MergeRequestReviewPageProps) {
	const [session, { integrationId: repoRouteId, mergeRequestIid }] =
		await Promise.all([getSession(), params]);

	if (!session?.user?.id) {
		redirect("/");
	}

	const integrations = await getCachedUserIntegrations(session.user.id);
	const integration = findIntegrationByRepoRouteId(integrations, repoRouteId);
	if (!integration) {
		notFound();
	}
	const canonicalRepoRouteId = buildRepoRouteId(integration);
	if (repoRouteId !== canonicalRepoRouteId) {
		redirect(buildRepoMergeRequestPath(integration, mergeRequestIid));
	}

	return (
		<MergeRequestDiffViewerClient
			instanceUrl={integration.instanceUrl}
			token=""
			integrationId={integration.id}
			projectId={integration.projectId}
			mergeRequestIid={mergeRequestIid}
			nav={{
				projectPath: integration.projectPath,
				mergeRequestIid,
				integrationStatus: integration.status,
				mrDescriptionHref: buildRepoMergeRequestDescriptionPath(
					integration,
					mergeRequestIid,
				),
