class DescriptionUpstreamError extends Error {
  readonly info: DescriptionErrorInfo

  constructor(info: DescriptionErrorInfo) {
    super(info.message)
    this.name = "DescriptionUpstreamError"
    this.info = info
  }
}

export type ReviewDescriptionRequestPayload = {
  patch?: unknown
  apiUrl?: unknown
  model?: unknown
  token?: unknown
  stream?: unknown
  instanceUrl?: unknown
  projectId?: unknown
  mergeRequestIid?: unknown
}

type ResolvedDescriptionRequest = {
  patch: string
  apiUrl: string
  model: string
  token: string
  stream: boolean
  usesServerToken: boolean
}

type ChatCompletionsResponse = {
  choices?: Array<{
    message?: {
      content?: unknown
    }
  }>
  usage?: {
    prompt_tokens?: unknown
    completion_tokens?: unknown
    total_tokens?: unknown
  }
}

type ChatCompletionsStreamChunk = {
  choices?: Array<{
    delta?: {
      content?: unknown
    }
    message?: {
      content?: unknown
    }
  }>
}

type DescriptionScope = {
  instanceUrl: string
  projectId: string
  mergeRequestIid: string
}

type PersistedDescription = {
  id: string
  markdown: string
  createdAt: string
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const pickFirstNonEmpty = (...values: Array<string | undefined>) => {
  for (const value of values) {
    if (isNonEmptyString(value)) {
      return value.trim()
    }
  }
  return ""
}

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const isPrivateOrLocalHost = (hostname: string) => {
  const normalized = hostname.trim().toLowerCase()
  if (!normalized) {
    return true
  }

  if (
    normalized === "localhost" ||
    normalized.endsWith(".localhost") ||
    normalized === "0.0.0.0" ||
    normalized === "::1" ||
    normalized.endsWith(".local") ||
    normalized.endsWith(".internal")
  ) {
    return true
  }

  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(normalized)) {
    const octets = normalized.split(".").map((part) => Number.parseInt(part, 10))
    if (octets.some((value) => !Number.isFinite(value) || value < 0 || value > 255)) {
      return true
    }

    const [a, b] = octets
    if (
      a === 10 ||
      a === 127 ||
      (a === 169 && b === 254) ||
      (a === 172 && b >= 16 && b <= 31) ||
      (a === 192 && b === 168) ||
      (a === 100 && b >= 64 && b <= 127)
    ) {
      return true
    }
  }

  if (
    normalized.includes(":") &&
    (normalized.startsWith("fc") || normalized.startsWith("fd") || normalized.startsWith("fe80:"))
  ) {
    return true
  }

  return false
}

const getEnvApiUrl = () =>
  pickFirstNonEmpty(
    process.env.AI_API_URL,
    process.env.OPENAI_BASE_URL,
  ) || DEFAULT_AI_API_URL

const getEnvModel = () =>
  pickFirstNonEmpty(
    process.env.AI_MODEL,
    process.env.OPENAI_MODEL,
  ) || DEFAULT_AI_MODEL

const getEnvToken = () =>
  pickFirstNonEmpty(
    process.env.AI_API_TOKEN,
    process.env.OPENAI_API_KEY,
  )

const resolveApiUrl = (raw: string) => {
  let parsed: URL
  try {
    parsed = new URL(raw)
  } catch {
    throw new Error("AI_API_URL (or OPENAI_BASE_URL) must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("AI provider URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("AI provider URL must not include credentials.")
  }
  if (isPrivateOrLocalHost(parsed.hostname)) {
    throw new Error("AI provider URL must not target localhost or private network hosts.")
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  const normalized = pathname ? `${parsed.origin}${pathname}` : parsed.origin
  return normalizeApiUrl(normalized)
}

export const resolveServerApiUrl = () => resolveApiUrl(getEnvApiUrl())

export const resolveDescriptionRequestInput = (
  payload: ReviewDescriptionRequestPayload | null,
): ResolvedDescriptionRequest => {
  const serverApiUrl = resolveServerApiUrl()
  const clientApiUrl = isNonEmptyString(payload?.apiUrl)
    ? resolveApiUrl(payload.apiUrl)
    : null
  const apiUrl = clientApiUrl ?? serverApiUrl
  const hasCustomApiUrl = Boolean(clientApiUrl && normalizeApiUrl(clientApiUrl) !== serverApiUrl)

  const clientToken = isNonEmptyString(payload?.token) ? payload.token.trim() : ""
  if (hasCustomApiUrl && !clientToken) {
    throw new Error("Custom AI provider URL requires an explicit token.")
  }

  return {
    patch: isNonEmptyString(payload?.patch) ? payload.patch : "",
    apiUrl,
    model: isNonEmptyString(payload?.model) ? payload.model.trim() : getEnvModel(),
    token: clientToken || getEnvToken(),
    stream: payload?.stream === true,
    usesServerToken: clientToken.length === 0,
  }
}

const resolveDescriptionScope = (
  payload: ReviewDescriptionRequestPayload | null,
): DescriptionScope | null => {
  const instanceUrl = isNonEmptyString(payload?.instanceUrl)
    ? normalizeApiUrl(payload.instanceUrl)
    : ""
  const projectId = isNonEmptyString(payload?.projectId) ? payload.projectId.trim() : ""
  const mergeRequestIid = isNonEmptyString(payload?.mergeRequestIid)
    ? payload.mergeRequestIid.trim()
    : ""

  if (!instanceUrl || !projectId || !mergeRequestIid) {
    return null
  }

  return {
    instanceUrl,
    projectId,
    mergeRequestIid,
  }
}

const resolveDescriptionScopeFromSearchParams = (params: URLSearchParams): DescriptionScope | null => {
  const instanceUrl = normalizeApiUrl(params.get("instanceUrl") ?? "")
  const projectId = (params.get("projectId") ?? "").trim()
  const mergeRequestIid = (params.get("mergeRequestIid") ?? "").trim()
  if (!instanceUrl || !projectId || !mergeRequestIid) {
    return null
  }
  return {
    instanceUrl,
    projectId,
    mergeRequestIid,
  }
}

const getChatCompletionsUrl = (apiUrl: string) => {
  const normalized = normalizeApiUrl(apiUrl)
  if (/\/chat\/completions$/i.test(normalized)) {
    return normalized
  }
  return `${normalized}/chat/completions`
}

const readProviderError = async (response: Response) => {
  const bodyText = await response.text().catch(() => "")
  return bodyText.slice(0, 400)
}

const sanitizeErrorMessage = (message: string) => {
  const normalized = message.trim().replace(/\s+/g, " ")
  if (!normalized) {
    return GENERIC_AI_DESCRIPTION_ERROR
  }

  const looksLikeSensitiveLeak =
    /failed query:/i.test(normalized) ||
    /\bparams:\b/i.test(normalized) ||
    /\binsert into\b/i.test(normalized) ||
    /\bon conflict\b/i.test(normalized)

  if (looksLikeSensitiveLeak) {
    return GENERIC_AI_DESCRIPTION_ERROR
  }

  if (normalized.length > MAX_ERROR_LENGTH) {
    return `${normalized.slice(0, MAX_ERROR_LENGTH - 1)}…`
  }

  return normalized
}

const getDescriptionErrorMessage = (error: unknown) => {
  if (error instanceof Error) {
    return sanitizeErrorMessage(error.message)
  }
  if (typeof error === "string") {
    return sanitizeErrorMessage(error)
  }
  return GENERIC_AI_DESCRIPTION_ERROR
}

const toDescriptionUpstreamError = (info: DescriptionErrorInfo) =>
  new DescriptionUpstreamError({
    ...info,
    message: sanitizeErrorMessage(info.message),
  })

const extractMessageFromUnknown = (value: unknown): string => {
  if (typeof value === "string") {
    return value
  }
  if (!value || typeof value !== "object") {
    return ""
  }

  const candidate = value as Record<string, unknown>
  return (
    pickFirstNonEmpty(
      typeof candidate.message === "string" ? candidate.message : undefined,
      typeof candidate.error === "string" ? candidate.error : undefined,
      typeof candidate.detail === "string" ? candidate.detail : undefined,
    ) || extractMessageFromUnknown(candidate.error)
  )
}

const getProviderErrorMessage = (providerError: string) => {
  const trimmed = providerError.trim()
  if (!trimmed) {
    return ""
  }

  try {
    const parsed = JSON.parse(trimmed) as unknown
    const extracted = extractMessageFromUnknown(parsed)
    return extracted ? sanitizeErrorMessage(extracted) : sanitizeErrorMessage(trimmed)
  } catch {
    return sanitizeErrorMessage(trimmed)
  }
}

const withProviderMessage = (message: string, providerError: string) => {
  const providerMessage = getProviderErrorMessage(providerError)
  if (!providerMessage || providerMessage === GENERIC_AI_DESCRIPTION_ERROR) {
    return sanitizeErrorMessage(message)
  }
  return sanitizeErrorMessage(`${message} Provider response: ${providerMessage}`)
}

const classifyProviderError = (status: number, providerError: string): DescriptionUpstreamError => {
  if (status === 401 || status === 403) {
    return toDescriptionUpstreamError({
      code: "AI_UPSTREAM_AUTH",
      category: "auth",
      providerStatus: status,
      retryable: false,
      message: withProviderMessage(
        `AI provider rejected authentication (${status}). Check AI_API_TOKEN/OPENAI_API_KEY (or client token) and provider access.`,
        providerError,
      ),
    })
  }

  if (status === 404) {
    return toDescriptionUpstreamError({
      code: "AI_UPSTREAM_ENDPOINT",
      category: "url",
      providerStatus: status,
      retryable: false,
      message: withProviderMessage(
        "AI provider endpoint was not found (404). Check AI_API_URL/OPENAI_BASE_URL points to a valid API base (for OpenAI, https://api.openai.com/v1).",
        providerError,
      ),
    })
  }

  if (status === 429) {
    return toDescriptionUpstreamError({
      code: "AI_UPSTREAM_RATE_LIMIT",
      category: "rate_limit",
      providerStatus: status,
      retryable: true,
      message: withProviderMessage("AI provider rate limited this request (429). Wait briefly and retry.", providerError),
    })
  }

if (status >= 500) {
  return toDescriptionUpstreamError({
    code: "AI_UPSTREAM_PROVIDER",
    category: "provider",
    providerStatus: status,
    retryable: true,
    message: withProviderMessage(`AI provider failed the request (${status}). Retry in a moment.`, providerError),
  })
}

if (status === 400 || status === 422) {
  return toDescriptionUpstreamError({
    code: "AI_UPSTREAM_BAD_REQUEST",
    category: "request",
    providerStatus: status,
    retryable: false,
    message: withProviderMessage(
      `AI provider rejected the request (${status}). Check AI model/config values and retry.`,
      providerError,
    ),
  })
}

return toDescriptionUpstreamError({
  code: "AI_UPSTREAM_PROVIDER",
  category: "provider",
  providerStatus: status,
  retryable: status >= 500,
  message: withProviderMessage(`AI provider request failed (${status}).`, providerError),
})

}

const getNestedErrorCode = (value: unknown, seen = new Set<unknown>()): string => {
  if (!value || typeof value !== "object" || seen.has(value)) {
    return ""
  }

  seen.add(value)
  const candidate = value as {
    code?: unknown
    cause?: unknown
    errors?: unknown
  }

  if (typeof candidate.code === "string" && candidate.code.trim()) {
    return candidate.code.trim().toUpperCase()
  }

  if (Array.isArray(candidate.errors)) {
    for (const nested of candidate.errors) {
      const nestedCode = getNestedErrorCode(nested, seen)
      if (nestedCode) {
        return nestedCode
      }
    }
  }

  return getNestedErrorCode(candidate.cause, seen)
}

const classifyDescriptionError = (error: unknown): DescriptionErrorInfo => {
  if (error instanceof DescriptionUpstreamError) {
    return error.info
  }

  if (error instanceof Error && error.name === "AbortError") {
    return toDescriptionUpstreamError({
      code: "AI_UPSTREAM_TIMEOUT",
      category: "timeout",
      providerStatus: null,
      retryable: true,
      message: `AI MR description timed out after ${Math.round(CHAT_TIMEOUT_MS / 1000)} seconds.`,
    }).info
  }

  const nestedErrorCode = getNestedErrorCode(error)
  if (DNS_ERROR_CODES.has(nestedErrorCode)) {
    return toDescriptionUpstreamError({
      code: "AI_UPSTREAM_NETWORK",
      category: "network",
      providerStatus: null,
      retryable: true,
      message: "Unable to resolve AI provider host. Check AI_API_URL/OPENAI_BASE_URL DNS and network access.",
    }).info
  }

if (NETWORK_ERROR_CODES.has(nestedErrorCode)) {
  return toDescriptionUpstreamError({
    code: "AI_UPSTREAM_NETWORK",
    category: "network",
    providerStatus: null,
    retryable: true,
    message: `Unable to reach AI provider (${nestedErrorCode}). Check provider URL and network connectivity.`,
  }).info
}

if (error instanceof Error && /fetch failed/i.test(error.message)) {
  return toDescriptionUpstreamError({
    code: "AI_UPSTREAM_NETWORK",
    category: "network",
    providerStatus: null,
    retryable: true,
    message: "AI provider request failed before receiving a response. Check provider URL and network connectivity.",
  }).info
}

if (
  error instanceof Error &&
  (/stream missing response body/i.test(error.message) ||
    /did not return an mr description/i.test(error.message))
) {
  return toDescriptionUpstreamError({
    code: "AI_UPSTREAM_RESPONSE",
    category: "response",
    providerStatus: null,
    retryable: true,
    message: error.message,
  }).info
}

return toDescriptionUpstreamError({
  code: "AI_UPSTREAM_UNKNOWN",
  category: "unknown",
  providerStatus: null,
  retryable: false,
  message: getDescriptionErrorMessage(error),
}).info

const extractAssistantContent = (content: unknown) => {
  if (typeof content === "string") {
    return content
  }

  if (Array.isArray(content)) {
    const text = content
      .map((part) => {
        if (!part || typeof part !== "object") {
          return ""
        }

        const candidate = part as { text?: unknown }
        return typeof candidate.text === "string" ? candidate.text : ""
      })
      .join("\n")
      .trim()

    return text
  }

  return ""
}

const sanitizeAssistantMarkdown = (content: string) => {
  const trimmed = content.trim()
  if (!trimmed) {
    return ""
  }

  const fenced = trimmed.match(/^```(?:markdown|md)?\s*([\s\S]*?)```$/i)
  return (fenced?.[1] ?? trimmed).trim()
}

const requestDescription = async ({
  patch,
  apiUrl,
  model,
  token,
}: {
  patch: string
  apiUrl: string
  model: string
  token: string
}) => {
  const controller = new AbortController()
  const timeout = setTimeout(() => {
    controller.abort()
  }, CHAT_TIMEOUT_MS)
  const startedAt = Date.now()

try {
  const response = await fetch(getChatCompletionsUrl(apiUrl), {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      model,
      temperature: 0.2,
      messages: [
        { role: "system", content: buildSystemPrompt() },
        { role: "user", content: `Build a merge request description for this patch:\n\n${patch}` },
      ],
    }),
    signal: controller.signal,
  })

  if (!response.ok) {
    const providerError = await readProviderError(response)
    throw classifyProviderError(response.status, providerError)
  }

  const payload = (await response.json()) as ChatCompletionsResponse
  const content = extractAssistantContent(payload.choices?.[0]?.message?.content)
  const usage = extractUsageFromOpenAiCompatiblePayload(payload)
  const latencyMs = Math.max(1, Date.now() - startedAt)
  return {
    markdown: sanitizeAssistantMarkdown(content),
    llmMetrics: buildLlmMetrics({
      provider: resolveLlmProviderLabel(apiUrl),
      model,
      promptTokens: usage.promptTokens,
      completionTokens: usage.completionTokens,
      totalTokens: usage.totalTokens,
      latencyMs,
      requestCount: 1,
    }),
  }
} catch (error) {

    if (error instanceof Error && error.name === "AbortError") {
      throw toDescriptionUpstreamError({
        code: "AI_UPSTREAM_TIMEOUT",
        category: "timeout",
        providerStatus: null,
        retryable: true,
        message: `AI MR description timed out after ${Math.round(CHAT_TIMEOUT_MS / 1000)} seconds.`,
      })
    }
    throw error
  } finally {
    clearTimeout(timeout)
  }
}

const extractStreamChunkText = (value: unknown) => {
  if (!value || typeof value !== "object") {
    return ""
  }

  const chunk = value as ChatCompletionsStreamChunk
  const choice = chunk.choices?.[0]
  if (!choice) {
    return ""
  }

  return extractAssistantContent(choice.delta?.content ?? choice.message?.content)
}

const parseSseDataChunk = (line: string) => {
  const trimmedLine = line.trim()
  if (!trimmedLine.startsWith("data:")) {
    return ""
  }

  const payloadText = trimmedLine.slice(5).trim()
  if (!payloadText || payloadText === "[DONE]") {
    return ""
  }

  try {
    return extractStreamChunkText(JSON.parse(payloadText))
  } catch {
    return ""
  }
}

const requestDescriptionStream = async ({
  patch,
  apiUrl,
  model,
  token,
}: {
  patch: string
  apiUrl: string
  model: string
  token: string
}) => {
  const controller = new AbortController()
  const timeout = setTimeout(() => {
    controller.abort()
  }, CHAT_TIMEOUT_MS)

try {
  const response = await fetch(getChatCompletionsUrl(apiUrl), {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      model,
      temperature: 0.2,
      stream: true,
      messages: [
        { role: "system", content: buildSystemPrompt() },
        { role: "user", content: `Build a merge request description for this patch:\n\n${patch}` },
      ],
    }),
    signal: controller.signal,
  })

  if (!response.ok) {
    const providerError = await readProviderError(response)
    throw classifyProviderError(response.status, providerError)
  }

  if (!response.body) {
    throw toDescriptionUpstreamError({
      code: "AI_UPSTREAM_RESPONSE",
      category: "response",
      providerStatus: null,
      retryable: true,
      message: "AI provider stream missing response body.",
    })
  }

  const upstreamReader = response.body.getReader()
  const decoder = new TextDecoder()
  const encoder = new TextEncoder()

const stream = new ReadableStream<Uint8Array>({
  start(controller) {
    void (async () => {
      let pending = ""

      try {
        while (true) {
          const { done, value } = await upstreamReader.read()
          if (done) {
            break
          }

          pending += decoder.decode(value, { stream: true })
          const lines = pending.split("\n")
          pending = lines.pop() ?? ""

          for (const line of lines) {
            const textChunk = parseSseDataChunk(line)
            if (textChunk) {
              controller.enqueue(encoder.encode(textChunk))
            }
          }
        }

        pending += decoder.decode()
        if (pending.trim()) {
          const textChunk = parseSseDataChunk(pending)
          if (textChunk) {
            controller.enqueue(encoder.encode(textChunk))
          }
        }

        controller.close()
      } catch (error) {
        controller.error(error)
      } finally {
        clearTimeout(timeout)
        upstreamReader.releaseLock()
      }
    })()
  },
  cancel() {
    controller.abort()
    return upstreamReader.cancel()
  },
})

return stream

  } catch (error) {
    clearTimeout(timeout)
    if (error instanceof Error && error.name === "AbortError") {
      throw toDescriptionUpstreamError({
        code: "AI_UPSTREAM_TIMEOUT",
        category: "timeout",
        providerStatus: null,
        retryable: true,
        message: `AI MR description timed out after ${Math.round(CHAT_TIMEOUT_MS / 1000)} seconds.`,
      })
    }
    throw error
  }
}

const persistDescription = async ({
  userId,
  scope,
  model,
  patch,
  markdown,
}: {
  userId: string
  scope: DescriptionScope | null
  model: string
  patch: string
  markdown: string
}) => {
  if (!scope) {
    return null
  }

  if (!markdown.trim()) {
    throw new Error("AI did not return an MR description.")
  }

  const [{ db }, { aiReviewDescriptions }] = await Promise.all([
    import("@/lib/db"),
    import("@/lib/db/schema"),
  ])

  const inserted = await db
    .insert(aiReviewDescriptions)
    .values({
      userId,
      instanceUrl: scope.instanceUrl,
      projectId: scope.projectId,
      mergeRequestIid: scope.mergeRequestIid,
      model,
      patchLength: patch.length,
      patchHash: sha256Hex(patch),
      markdown,
    })
    .returning({
      id: aiReviewDescriptions.id,
    })

  return inserted[0]?.id ?? null
}

const toPersistedDescription = (row: {
  id: string
  markdown: string
  createdAt: Date
}): PersistedDescription => ({
  id: row.id,
  markdown: row.markdown,
  createdAt: row.createdAt.toISOString(),
})

const streamWithPersistence = ({
  stream,
  onComplete,
}: {
  stream: ReadableStream<Uint8Array>
  onComplete: (markdown: string) => Promise<void>
}) => {
  const decoder = new TextDecoder()
  const encodedChunks: Uint8Array[] = []

  return new ReadableStream<Uint8Array>({
    start(controller) {
      const reader = stream.getReader()

      void (async () => {
        try {
          while (true) {
            const { done, value } = await reader.read()
            if (done) {
              break
            }

            if (value) {
              encodedChunks.push(value)
              controller.enqueue(value)
            }
          }

          const markdown = encodedChunks
            .map((chunk) => decoder.decode(chunk, { stream: true }))
            .join("") + decoder.decode()

          await onComplete(sanitizeAssistantMarkdown(markdown))
          controller.close()
        } catch (error) {
          controller.error(error)
        } finally {
          reader.releaseLock()
        }
      })()
    },
    cancel(reason) {
      return stream.cancel(reason)
    },
  })
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/description",
    event: "api.review.description",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => null) as Promise<ReviewDescriptionRequestPayload | null>,
      ])

if (!userId) {
  return {
    status: 401,
    outcome: "unauthorized",
    response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
  }
}

let resolved: ResolvedDescriptionRequest
try {
  resolved = resolveDescriptionRequestInput(payload)
} catch (error) {
  const message =
    error instanceof Error ? error.message : "AI provider URL is invalid."
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: message }, { status: 400 }),
  }
}

const { patch, apiUrl, model, token, stream, usesServerToken } = resolved
const provider = resolveLlmProviderLabel(apiUrl)
const scope = resolveDescriptionScope(payload)

if (!patch) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Patch is required." }, { status: 400 }),
  }
}
if (!apiUrl || !model || !token) {
  return {
    status: 400,
    outcome: "missing_config",
    response: NextResponse.json(
      { error: "AI token missing. Set AI_API_TOKEN or OPENAI_API_KEY on the server." },
      { status: 400 },
    ),
  }
}

if (patch.length > MAX_PATCH_CHARS) {
  return {
    status: 413,
    outcome: "payload_too_large",
    response: NextResponse.json(
      {
        error: `Diff too large for AI MR description. Limit is ${MAX_PATCH_CHARS.toLocaleString()} characters.`,
      },
      { status: 413 },
    ),
  }
}

const trialAvailability = await ensureDefaultTokenUsageAvailable({
  userId,
  usesServerToken,
})
if (trialAvailability.limited) {
  logger.set({
    defaultTokenUsageLimit: trialAvailability.summary.limit,
    defaultTokenUsageCount: trialAvailability.summary.used,
    defaultTokenUsageRemaining: trialAvailability.summary.remaining,
  })
  return {
    status: 403,
    outcome: "trial_limit_reached",
    response: NextResponse.json(
      { error: buildDefaultTokenUsageLimitMessage(trialAvailability.summary.limit) },
      { status: 403 },
    ),
  }
}

try {
  if (stream) {
    const trialConsumption = await consumeDefaultTokenUsage({
      userId,
      usesServerToken,
      requestType: "description",
    })

if (trialConsumption.limited && trialConsumption.summary) {
  return {
    status: 403,
    outcome: "trial_limit_reached",
    response: NextResponse.json(
      { error: buildDefaultTokenUsageLimitMessage(trialConsumption.summary.limit) },
      { status: 403 },
    ),
  }
}

const markdownStream = await requestDescriptionStream({
