  apiUrl,
  model,
  token,
})
const persistedStream = streamWithPersistence({
  stream: markdownStream,
  onComplete: async (markdown) => {
    await persistDescription({
      userId,
      scope,
      model,
      patch,
      markdown,
    })
  },
})

  logger.set({
    model,
    patchLength: patch.length,
    stream: true,
    labels: {
      provider,
      model,
    },
    llmMetrics: buildLlmMetrics({
      provider,
      model,
      promptTokens: 0,
      completionTokens: 0,
      totalTokens: 0,
      latencyMs: null,
      requestCount: 1,
    }),
    persisted: scope !== null,
    instanceUrl: scope?.instanceUrl ?? null,
    projectId: scope?.projectId ?? null,
    mergeRequestIid: scope?.mergeRequestIid ?? null,
    defaultTokenUsageLimit: trialConsumption.summary?.limit ?? null,
    defaultTokenUsageCount: trialConsumption.summary?.used ?? null,
    defaultTokenUsageRemaining: trialConsumption.summary?.remaining ?? null,
  })

  return {
    status: 200,
    outcome: "success",
    response: new Response(persistedStream, {
      headers: {
        "content-type": "text/plain; charset=utf-8",
        "cache-control": "no-store",
        "x-accel-buffering": "no",
      },
    }),
  }
}

const trialConsumption = await consumeDefaultTokenUsage({
  userId,
  usesServerToken,
  requestType: "description",
})

if (trialConsumption.limited && trialConsumption.summary) {
  return {
    status: 403,
    outcome: "trial_limit_reached",
    response: NextResponse.json(
      { error: buildDefaultTokenUsageLimitMessage(trialConsumption.summary.limit) },
      { status: 403 },
    ),
  }
}

const descriptionResult = await requestDescription({
  patch,
  apiUrl,
  model,
  token,
})
const markdown = descriptionResult.markdown

if (!markdown) {
  throw new Error("AI did not return an MR description.")
}
const descriptionId = await persistDescription({
  userId,
  scope,
  model,
  patch,
  markdown,
})

logger.set({
  model,
  patchLength: patch.length,
  markdownLength: markdown.length,
  stream: false,
  labels: {
    provider,
    model,
  },
  llmMetrics: descriptionResult.llmMetrics,
  descriptionId,
  persisted: scope !== null,
  instanceUrl: scope?.instanceUrl ?? null,
  projectId: scope?.projectId ?? null,
  mergeRequestIid: scope?.mergeRequestIid ?? null,
  defaultTokenUsageLimit: trialConsumption.summary?.limit ?? null,
  defaultTokenUsageCount: trialConsumption.summary?.used ?? null,
  defaultTokenUsageRemaining: trialConsumption.summary?.remaining ?? null,
})

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: { markdown } }),
        }
      } catch (error) {
        const failure = classifyDescriptionError(error)
        logger.set({
          errorCode: failure.code,
          errorCategory: failure.category,
          providerStatus: failure.providerStatus,
          retryable: failure.retryable,
        })
        return {
          status: 502,
          outcome: "upstream_error",
          response: NextResponse.json(
            {
              error: failure.message,
              code: failure.code,
              category: failure.category,
              providerStatus: failure.providerStatus,
              retryable: failure.retryable,
            },
            { status: 502 },
          ),
        }
      }
    },
  })
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/description",
    event: "api.review.description.latest",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const scope = resolveDescriptionScopeFromSearchParams(new URL(request.url).searchParams)

      if (!scope) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json(
            { error: "instanceUrl, projectId, and mergeRequestIid are required." },
            { status: 400 },
          ),
        }
      }

      const [{ db }, { aiReviewDescriptions }] = await Promise.all([
        import("@/lib/db"),
        import("@/lib/db/schema"),
      ])

      const rows = await db
        .select({
          id: aiReviewDescriptions.id,
          markdown: aiReviewDescriptions.markdown,
          createdAt: aiReviewDescriptions.createdAt,
        })
        .from(aiReviewDescriptions)
        .where(
          and(
            eq(aiReviewDescriptions.userId, userId),
            eq(aiReviewDescriptions.instanceUrl, scope.instanceUrl),
            eq(aiReviewDescriptions.projectId, scope.projectId),
            eq(aiReviewDescriptions.mergeRequestIid, scope.mergeRequestIid),
          ),
        )
        .orderBy(desc(aiReviewDescriptions.createdAt))
        .limit(1)

      const description = rows[0] ? toPersistedDescription(rows[0]) : null
      logger.set({
        descriptionFound: Boolean(description),
        descriptionId: description?.id ?? null,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: { description } }),
      }
    },
  })
}

