import type {
  OnboardingSessionState,
  TokenTestFeedback,
} from "@/components/onboarding/onboarding-types"
import {
  INSTANCE_PRESETS,
  ONBOARDING_STORAGE_KEY,
  ONBOARDING_TOKEN_TEST_CACHE_KEY,
  TOKEN_TEST_CACHE_TTL_MS,
} from "@/components/onboarding/onboarding.constants"
import type { GitLabInstancePreset } from "@/components/onboarding/onboarding.constants"

export {
  AUTOTEST_TOKEN_DEBOUNCE_MS,
  INSTANCE_PRESETS,
  MERGE_REQUESTS_FULL_LIMIT,
  MERGE_REQUESTS_PRELOAD_CONCURRENCY,
  MERGE_REQUESTS_PRELOAD_LIMIT,
  MERGE_REQUESTS_PRELOAD_PROJECTS_LIMIT,
  ONBOARDING_PREFETCH_STALE_TIME,
  ONBOARDING_QUERY_GC_TIME,
  ONBOARDING_QUERY_KEY_PREFIX,
  ONBOARDING_QUERY_STALE_TIME,
  ONBOARDING_STORAGE_KEY,
  RECENT_PROJECTS_LIMIT,
  routeStepPosition,
  SERVER_PROJECT_SEARCH_LIMIT,
  SERVER_PROJECT_SEARCH_MIN_CHARS,
  TOKEN_TEST_CACHE_TTL_MS,
  type GitLabInstancePreset,
} from "@/components/onboarding/onboarding.constants"

export const getInstanceByKey = (instance: string) =>
  INSTANCE_PRESETS.find((item) => item.key === instance) ?? INSTANCE_PRESETS[0]

export const isInstanceKey = (
  instance: string,
): instance is GitLabInstancePreset["key"] =>
  INSTANCE_PRESETS.some((item) => item.key === instance)

export const resolveGitLabInstance = (
  instance: string,
  customValue: string,
) => {
  const selectedInstance = getInstanceByKey(instance)
  const value = (
    selectedInstance.isCustom ? customValue : selectedInstance.key
  ).trim()
  if (!value) {
    throw new Error("Please select or enter a GitLab instance.")
  }
  return value.replace(/\/+$/, "")
}

export const buildEmptyInstanceTokens = () => {
  const values: Record<string, string> = {}
  for (const instance of INSTANCE_PRESETS) {
    values[instance.key] = ""
  }
  return values
}

export const isStringRecord = (
  value: unknown,
): value is Record<string, string> =>
  Boolean(value) &&
  typeof value === "object" &&
  !Array.isArray(value) &&
  Object.values(value as Record<string, unknown>).every(
    (item) => typeof item === "string",
  )

export const readPersistedState = (): Partial<OnboardingSessionState> => {
  const raw = window.sessionStorage.getItem(ONBOARDING_STORAGE_KEY)
  if (!raw) {
    return {}
  }

  try {
    const parsed = JSON.parse(raw) as Partial<OnboardingSessionState>
    return parsed && typeof parsed === "object" ? parsed : {}
  } catch {
    return {}
  }
}

export const persistOnboardingStatePatch = (
  patch: Partial<OnboardingSessionState>,
) => {
  if (typeof window === "undefined") {
    return
  }

  try {
    const current = readPersistedState()
    window.sessionStorage.setItem(
      ONBOARDING_STORAGE_KEY,
      JSON.stringify({
        ...current,
        ...patch,
      }),
    )
  } catch {
    // best-effort
  }
}

export const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

export const hashTokenForCache = (value: string) => {
  let hash = 0x811c9dc5
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(16).padStart(8, "0")
}

const GENERIC_ONBOARDING_ERROR =
  "Could not complete that action. Please verify your GitLab settings and try again."

const sanitizeOnboardingErrorMessage = (message: string) => {
  const normalized = message.trim().replace(/\s+/g, " ")
  if (!normalized) {
    return GENERIC_ONBOARDING_ERROR
  }

  const looksLikeRawSqlLeak =
    /failed query:/i.test(normalized) ||
    /\bparams:\b/i.test(normalized) ||
    /\binsert into\b/i.test(normalized) ||
    /\bon conflict\b/i.test(normalized) ||
    /\btoken_ciphertext\b|\btoken_iv\b|\btoken_auth_tag\b/i.test(normalized)

  if (looksLikeRawSqlLeak) {
    return GENERIC_ONBOARDING_ERROR
  }

  const MAX_ERROR_LENGTH = 220
  if (normalized.length > MAX_ERROR_LENGTH) {
    return `${normalized.slice(0, MAX_ERROR_LENGTH - 1)}…`
  }

  return normalized
}

export const getErrorMessage = (value: unknown) => {
  let rawMessage: string | null = null

  if (typeof value === "string") {
    rawMessage = value
  } else if (value instanceof Error) {
    rawMessage = value.message
  } else if (value && typeof value === "object") {
    if ("error" in value) {
      rawMessage = String((value as { error?: string }).error)
    } else if ("message" in value) {
      rawMessage = String((value as { message?: string }).message)
    }
  }

  if (rawMessage) {
    return sanitizeOnboardingErrorMessage(rawMessage)
  }

  return "Something went wrong."
}

export type TokenTestResultCache = Map<
  string,
  { checkedAt: number; feedback: TokenTestFeedback }
>

export const loadTokenTestCache = () => {
  const raw = window.sessionStorage.getItem(ONBOARDING_TOKEN_TEST_CACHE_KEY)
  if (!raw) {
    return new Map<
      string,
      { checkedAt: number; feedback: TokenTestFeedback }
    >()
  }

  try {
    const parsed = JSON.parse(raw) as Record<
      string,
      { checkedAt: number; feedback: TokenTestFeedback } | undefined
    >
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return new Map()
    }

    const entries = Object.entries(parsed).filter(([, item]) => {
      if (!item || typeof item !== "object") {
        return false
      }
      if (
        typeof item.checkedAt !== "number" ||
        !Number.isFinite(item.checkedAt)
      ) {
        return false
      }
      if (!item.feedback || typeof item.feedback !== "object") {
        return false
      }
      if (item.feedback.kind !== "success" && item.feedback.kind !== "error") {
        return false
      }
      if (typeof item.feedback.message !== "string") {
        return false
      }
      return true
    })

    return new Map(entries)
  } catch {
    return new Map()
  }
}

export const pruneTokenTestCache = (
  cache: TokenTestResultCache,
  now: number,
) => {
  for (const [signature, entry] of cache) {
    if (now - entry.checkedAt >= TOKEN_TEST_CACHE_TTL_MS) {
      cache.delete(signature)
    }
  }
}

export const persistTokenTestCache = (cache: TokenTestResultCache) => {
  try {
    const now = Date.now()
    pruneTokenTestCache(cache, now)
    const payload = Object.fromEntries(cache.entries())
    window.sessionStorage.setItem(
      ONBOARDING_TOKEN_TEST_CACHE_KEY,
      JSON.stringify(payload),
    )
  } catch {
    // best-effort
  }
}

