    run: () => {
      const source = readSource("src/app/(app)/repos/[integrationId]/mrs/[mergeRequestIid]/page.tsx");
      return source.includes("<Skeleton");
    },
  },
];

let warnings = 0;

console.log("Performance report (warn-only):");
for (const check of checks) {
  try {
    const passed = check.run();
    if (passed) {
      console.log(`  [ok]   ${check.id} - ${check.description}`);
    } else {
      warnings += 1;
      console.log(`  [warn] ${check.id} - ${check.description}`);
    }
  } catch (error) {
    warnings += 1;
    console.log(
      `  [warn] ${check.id} - check failed to run: ${
        error instanceof Error ? error.message : "unknown error"
      }`,
    );
  }
}

console.log(
  `Summary: ${checks.length - warnings} passing, ${warnings} warnings (non-blocking).`,
);
process.exit(0);

import type { FileDiffMetadata } from "@pierre/diffs"
import { useMemo } from "react"

import {
  getFileLabel,
  INITIAL_FILE_BATCH_SIZE,
  type DiffDataSource,
  type DiffLoadProfile,
} from "../merge-request-diff-viewer.utils"

type UseMergeRequestDiffDerivedOptions = {
  parsedFiles: FileDiffMetadata[]
  filenameFilter: string
  patchText: string
  visibleResetToken: number
  visibleWindow: { key: string; count: number }
  dataSource: DiffDataSource | null
  loadProfile: DiffLoadProfile
}

export function useMergeRequestDiffDerived({
  parsedFiles,
  filenameFilter,
  patchText,
  visibleResetToken,
  visibleWindow,
  dataSource,
  loadProfile,
}: UseMergeRequestDiffDerivedOptions) {
  const normalizedFilter = filenameFilter.trim().toLowerCase()

  const filteredFiles = useMemo(() => {
    if (!normalizedFilter) {
      return parsedFiles
    }

    return parsedFiles.filter((file) => {
      const label = getFileLabel(file).toLowerCase()
      return label.includes(normalizedFilter)
    })
  }, [normalizedFilter, parsedFiles])

  const totals = useMemo(
    () =>
      filteredFiles.reduce(
        (accumulator, file) => {
          for (const hunk of file.hunks) {
            accumulator.additions += hunk.additionLines
            accumulator.deletions += hunk.deletionLines
          }
          return accumulator
        },
        { additions: 0, deletions: 0 },
      ),
    [filteredFiles],
  )

  const visibleWindowKey = `${visibleResetToken}:${normalizedFilter}:${patchText}`

  const visibleFileCount =
    visibleWindow.key === visibleWindowKey
      ? visibleWindow.count
      : INITIAL_FILE_BATCH_SIZE

  const visibleFiles = filteredFiles.slice(0, visibleFileCount)
  const canLoadMore = visibleFileCount < filteredFiles.length

  const loadProfileSummary = useMemo(() => {
    if (!dataSource || loadProfile.fetchMs == null) {
      return ""
    }

    const parts = [
      `Source: ${dataSource === "changes" ? "changes" : "raw_diffs"}`,
      `fetch ${loadProfile.fetchMs}ms`,
    ]
    if (loadProfile.firstParseMs != null) {
      parts.push(`first parse ${loadProfile.firstParseMs}ms`)
    }
    if (loadProfile.fullParseMs != null) {
      parts.push(`full parse ${loadProfile.fullParseMs}ms`)
    }
    return parts.join(" · ")
  }, [dataSource, loadProfile.fetchMs, loadProfile.firstParseMs, loadProfile.fullParseMs])

  return {
    filteredFiles,
    totals,
    visibleWindowKey,
    visibleFileCount,
    visibleFiles,
    canLoadMore,
    loadProfileSummary,
  }
}

const toReviewSide = (value: unknown): AiReviewFinding["side"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (
    normalized === "deletions" ||
    normalized === "deletion" ||
    normalized === "removed" ||
    normalized === "left"
  ) {
    return "deletions"
  }
  return "additions"
}

const toReviewSeverity = (value: unknown): AiReviewFinding["severity"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (normalized === "high") {
    return "high"
  }
  if (normalized === "medium" || normalized === "med") {
    return "med"
  }
  return "low"
}

const toConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0.7
  }
  return Math.max(0, Math.min(1, value))
}

const toEvidence = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

const parseFindings = (value: unknown): AiReviewFinding[] => {
  if (!Array.isArray(value)) {
    return []
  }

  const normalizedFindings: AiReviewFinding[] = []
  for (const item of value) {
    if (!item || typeof item !== "object") {
      continue
    }
    const finding = item as Record<string, unknown>
    const line = Number(finding.line)
    const file = String(finding.file ?? "").trim()
    const title = String(finding.title ?? "").trim()
    const body = String(finding.body ?? finding.explanation ?? "").trim()
    if (!file || !title || !body || !Number.isFinite(line) || line < 1) {
      continue
    }

    const normalizedFinding: AiReviewFinding = {
      file,
      line: Math.floor(line),
      side: toReviewSide(finding.side),
      severity: toReviewSeverity(finding.severity),
      title,
      body,
      confidence: toConfidence(finding.confidence),
      evidence: toEvidence(finding.evidence),
    }
    normalizedFindings.push(normalizedFinding)
  }

  return normalizedFindings.slice(0, MAX_FINDINGS)
}

const buildReviewSummary = (findings: AiReviewFinding[]) => {
  if (findings.length === 0) {
    return "AI review complete. No findings."
  }
  const highCount = findings.filter((finding) => finding.severity === "high").length
  const medCount = findings.filter((finding) => finding.severity === "med").length
  const lowCount = findings.length - highCount - medCount
  return `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`
}

const getEnvModel = () => {
  if (isNonEmptyString(process.env.AI_MODEL)) {
    return process.env.AI_MODEL.trim()
  }
  if (isNonEmptyString(process.env.OPENAI_MODEL)) {
    return process.env.OPENAI_MODEL.trim()
  }
  return DEFAULT_AI_MODEL
}

const toOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const toMergeRequestGraphScope = (value: unknown) => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {
      sourceBranch: null,
      sourceHeadSha: null,
    }
  }

  const record = value as Record<string, unknown>
  const diffRefs =
    record.diff_refs && typeof record.diff_refs === "object" && !Array.isArray(record.diff_refs)
      ? (record.diff_refs as Record<string, unknown>)
      : null

  return {
    sourceBranch: toOptionalString(record.source_branch),
    sourceHeadSha: toOptionalString(diffRefs?.head_sha),
  }
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/save",
    event: "api.review.save",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => null) as Promise<SaveReviewPayload | null>,
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
