const patch = isNonEmptyString(payload?.patch) ? payload.patch : ""
const instanceUrl = normalizeApiUrl(String(payload?.instanceUrl ?? "").trim())
const projectId = String(payload?.projectId ?? "").trim()
const mergeRequestIid = String(payload?.mergeRequestIid ?? "").trim()
const integrationId = String(payload?.integrationId ?? "").trim()
const scope = normalizeReviewGateScope({
  instanceUrl,
  projectId,
})
const findings = reconcileFindingLinesWithPatch({
  patch,
  findings: parseFindings(payload?.findings),
})
