  userId,
  usesServerToken: usedServerToken,
  requestType: "review",
})

if (trialConsumption.limited && trialConsumption.summary) {
  return {
    status: 403,
    outcome: "trial_limit_reached",
    response: NextResponse.json(
      { error: buildDefaultTokenUsageLimitMessage(trialConsumption.summary.limit) },
      { status: 403 },
    ),
  }
}

const gatePreferences = await resolveReviewGatePreferences({
  userId,
  scope,
})
const gateResult = applyReviewGate({
  findings,
  settings: gatePreferences.effectiveSettings,
})
const filteredFindings = gateResult.filteredFindings
const summary = isNonEmptyString(payload?.summary)
  ? payload.summary.trim()
  : buildReviewSummary(filteredFindings)
const model = getEnvModel()
const integration = await commentPublish.resolveManagedIntegrationForScope({
  userId,
  instanceUrl,
  projectId,
  integrationId: integrationId || null,
})
let sourceBranch: string | null = null
let sourceHeadSha: string | null = null

if (integration) {
  try {
    const token = decryptIntegrationToken(integration)
    const mergeRequestDetails = await getMergeRequestDetails(
      instanceUrl,
      token,
      projectId,
      mergeRequestIid,
    )
    const graphScope = toMergeRequestGraphScope(mergeRequestDetails)
    sourceBranch = graphScope.sourceBranch
    sourceHeadSha = graphScope.sourceHeadSha
  } catch (error) {
    logScopedError(logger, error, {
      code: "REVIEW_GRAPH_SCOPE_LOOKUP_FAILED",
      why: "Failed to resolve merge request graph scope.",
      details: {
        scope: "review.save.graph_scope_lookup",
        integrationId: integration.id,
        instanceUrl,
        projectId,
        mergeRequestIid,
      },
    })
  }
}

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            review: row
                ? {
                  id: row.id,
                  summary: row.summary,
                  findings: row.findings,
                  feedback: row.feedback,
                  commentFeedbackByKey: {},
                  commentPublishByKey,
                  createdAt: row.createdAt.toISOString(),
                }
              : null,
            suppressedFindingsCount: gateResult.suppressedFindingsCount,
            suppressedByReason: gateResult.suppressedByReason,
            gateProfile: gatePreferences.effectiveSettings,
          },
        }),
      }
    },
  })
}

