export type WorkerRunner = () => Promise<void>

export type ModuleImporter = (moduleId: string) => Promise<unknown>

type WorkerModule = {
  runIndexerWorker?: WorkerRunner
}

export const DEFAULT_INDEXER_RUNTIME_MODULE = "@argus/service-web/indexer-runtime"

export const loadWorkerRunner = async ({
  moduleId = DEFAULT_INDEXER_RUNTIME_MODULE,
  importModule = (importId: string) => import(importId),
}: {
  moduleId?: string
  importModule?: ModuleImporter
} = {}): Promise<WorkerRunner> => {
  const workerModule = (await importModule(moduleId)) as WorkerModule
  const runIndexerWorker = workerModule.runIndexerWorker
  if (typeof runIndexerWorker !== "function") {
    throw new Error(
      `[service-indexer] worker module did not export runIndexerWorker: ${moduleId}`,
    )
  }
  return runIndexerWorker
}

export const runIndexerService = async ({
  loadRunner = () => loadWorkerRunner(),
}: {
  loadRunner?: () => Promise<WorkerRunner>
} = {}) => {
  const runWorker = await loadRunner()
  await runWorker()
}

export const runIndexerServiceCli = async ({
  runService = () => runIndexerService(),
  logError = (...args: unknown[]) => {
    console.error(...args)
  },
  exit = (code: number) => {
    process.exit(code)
  },
}: {
  runService?: () => Promise<void>
  logError?: (...args: unknown[]) => void
  exit?: (code: number) => void
} = {}) => {
  try {
    await runService()
  } catch (error) {
    logError("[service-indexer] worker execution failed:", error)
    exit(1)
  }
}

import { NextResponse } from "next/server"
import { z } from "zod"

import { CodeGraphError } from "@/lib/argus-search/graph-index-pack"
import { samplePersistedGraphForVisualization } from "@/lib/argus-search/persisted-graph-query"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const payloadSchema = z.object({
  maxNodes: z.number().int().positive().max(2_000).optional(),
  maxEdges: z.number().int().positive().max(10_000).optional(),
  edgeTypes: z.array(z.string().trim().min(1).max(100)).max(20).optional(),
})

const mapGraphErrorStatus = (code: CodeGraphError["code"]) => {
  if (code === "binary_missing") {
    return 503
  }
  if (code === "missing_index_pack") {
    return 404
  }
  return 502
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/graph/visualization",
    event: "api.code.graph.visualization",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => ({})),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }
      const parsed = payloadSchema.safeParse(payload)

      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid graph visualization payload." }, { status: 400 }),
        }
      }

      try {
        const graph = await samplePersistedGraphForVisualization(parsed.data)
        logger.set({
          nodeCount: graph.nodes.length,
          edgeCount: graph.edges.length,
          appliedEdgeTypes: graph.appliedEdgeTypes,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: graph }),
        }
      } catch (error) {
        if (error instanceof CodeGraphError) {
          logger.set({
            graphErrorCode: error.code,
            graphErrorDetails: error.details,
          })
          return {
            status: mapGraphErrorStatus(error.code),
            outcome: "graph_failed",
            response: NextResponse.json({ error: error.message }, { status: mapGraphErrorStatus(error.code) }),
          }
        }

        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to generate graph visualization payload." }, { status: 500 }),
        }
      }
    },
  })
}

const formatRelative = (value: Date | null) => {
  if (!value) return "never"
  const diffMs = Date.now() - value.getTime()
  const diffMin = Math.floor(diffMs / 60_000)
  if (diffMin < 1) return "just now"
  if (diffMin < 60) return `${diffMin}m ago`
  const diffHr = Math.floor(diffMin / 60)
  if (diffHr < 24) return `${diffHr}h ago`
  const diffDay = Math.floor(diffHr / 24)
  return `${diffDay}d ago`
}

const extractErrorMessage = (payload: unknown, fallback: string) => {
  if (
    payload &&
    typeof payload === "object" &&
    "error" in payload &&
    typeof (payload as { error?: unknown }).error === "string"
  ) {
    return (payload as { error: string }).error
  }
  return fallback
}

