      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const url = new URL(request.url)
      const parsed = querySchema.safeParse({
        windowDays: url.searchParams.get("windowDays") ?? undefined,
        trendDays: url.searchParams.get("trendDays") ?? undefined,
      })
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid query params." }, { status: 400 }),
        }
      }

      const overview = await buildAnalyticsOverview(userId, {
        windowDays: parsed.data.windowDays,
        trendDays: parsed.data.trendDays,
      })

      logger.set({
        windowDays: overview.windowDays,
        trendDays: overview.trendDays,
        commandKinds: overview.userActivity.commandsUsed.length,
        featureKinds: overview.userActivity.featureAdoption.length,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json(overview),
      }
    },
  })
}

