export const upsertJiraCredentials = async (
  userId: string,
  input: JiraStoredCredentials,
) => {
  const normalizedBaseUrl = normalizeJiraInstanceUrl(input.baseUrl)
  const normalizedEmail = normalizeEmail(input.email)
  const normalizedToken = input.token.trim()

  if (!normalizedEmail) {
    throw new Error("Jira email is required.")
  }

  if (!normalizedToken) {
    throw new Error("Jira API token is required.")
  }

  const encryptedToken = encryptGitLabToken(normalizedToken)

  await db
    .insert(jiraCredentials)
    .values({
      userId,
      baseUrl: normalizedBaseUrl,
      email: normalizedEmail,
      tokenCiphertext: encryptedToken.ciphertext,
      tokenIv: encryptedToken.iv,
      tokenAuthTag: encryptedToken.authTag,
    })
    .onConflictDoUpdate({
      target: jiraCredentials.userId,
      set: {
        baseUrl: normalizedBaseUrl,
        email: normalizedEmail,
        tokenCiphertext: encryptedToken.ciphertext,
        tokenIv: encryptedToken.iv,
        tokenAuthTag: encryptedToken.authTag,
        updatedAt: new Date(),
      },
    })

  return {
    baseUrl: normalizedBaseUrl,
