const createTestDeps = () => {
  const infoLogs: Record<string, unknown>[] = []
  const initCalls: Record<string, unknown>[] = []
  const logScopedErrorCalls: Array<{
    error: unknown
    metadata: Record<string, unknown> | undefined
  }> = []
  const createdLoggerPaths: string[] = []
  const cycleEmits: Record<string, unknown>[] = []
  let flushCalls = 0
  let batchCalls = 0

  const createScopedLogger = (args: { path: string }) => {
    createdLoggerPaths.push(args.path)
    return {
      set: (_fields: Record<string, unknown>) => {},
      emit: (fields: Record<string, unknown>) => {
        cycleEmits.push(fields)
      },
    }
  }

return {
  infoLogs,
  initCalls,
  logScopedErrorCalls,
  createdLoggerPaths,
  cycleEmits,
  getFlushCalls: () => flushCalls,
  getBatchCalls: () => batchCalls,
  deps: {
    initAppLogger: (args: Record<string, unknown>) => {
      initCalls.push(args)
    },
    appLogInfo: (fields: Record<string, unknown>) => {
      infoLogs.push(fields)
    },
    createScopedLogger,
    logScopedError: (
      _logger: { set: (fields: Record<string, unknown>) => void; emit: (fields: Record<string, unknown>) => void },
      error: unknown,
      metadata?: Record<string, unknown>,
    ) => {
      logScopedErrorCalls.push({ error, metadata })
    },
    flushAppLogger: async () => {
      flushCalls += 1
    },
    runIndexingWorkerBatch: async (_batchSize: number) => {
      batchCalls += 1
      return { jobsFailed: 0, jobsDead: 0, failed: 0 }
    },
    createCorrelationId: () => `cid-${batchCalls + 1}`,
    env: {
      INDEXER_CONTINUOUS: "0",
      INDEXER_BATCH_SIZE: "42",
      INDEXER_POLL_MS: "100",
    },
    processLike: {
      once: (_signal: "SIGINT" | "SIGTERM", _listener: () => void) => {},
      exit: (_code: number) => {},
    },
    sleep: async (_ms: number) => {},
    now: (() => {
      let ts = 1000
      return () => {
        ts += 25
        return ts
      }
    })(),
  },
}

}

describe("shared indexer worker runtime", () => {
  test("runs one batch and flushes when continuous mode is disabled", async () => {
    const runtime = createTestDeps()
    await runIndexerWorkerRuntime(runtime.deps)

    expect(runtime.getBatchCalls()).toBe(1)
    expect(runtime.getFlushCalls()).toBe(1)
    expect(runtime.initCalls.length).toBe(1)
    expect(runtime.infoLogs.some((entry) => entry.event === "indexer.worker.started")).toBe(true)
    expect(runtime.createdLoggerPaths).toContain("/workers/indexer/cycle")
    expect(runtime.cycleEmits.some((entry) => entry.status === 200)).toBe(true)
  })

  test("logs fatal details and rethrows when worker batch fails", async () => {
    const runtime = createTestDeps()
