      throw new Error("batch failed")
    }

    await expect(runIndexerWorkerRuntime(runtime.deps)).rejects.toThrow("batch failed")
    expect(runtime.getBatchCalls()).toBe(0)
    expect(runtime.getFlushCalls()).toBe(1)
    expect(runtime.createdLoggerPaths).toContain("/workers/indexer")
    expect(runtime.logScopedErrorCalls.length).toBe(1)
