const formatDateTime = (value: string | null) => {
  if (!value) {
    return "Never"
  }

  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "Unknown"
  }

  return parsed.toLocaleString()
}

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const extractErrorMessage = (payload: unknown, fallback: string) => {
  const root = asRecord(payload)
  const rawError = root?.error
  return typeof rawError === "string" && rawError.trim().length > 0 ? rawError : fallback
}

const readThemeModeFromStorage = (): ThemeMode => {
  if (typeof window === "undefined") {
    return "system"
  }

  const themeRaw = window.localStorage.getItem(THEME_SETTINGS_STORAGE_KEY)
  return isThemeMode(themeRaw) ? themeRaw : "system"
}

const useDebouncedAutosave = <T,>(
  value: T,
  onSave: (value: T) => void,
  delayMs: number,
) => {
  const hasInitialized = useRef(false)
  const timerRef = useRef<number | null>(null)

  useEffect(() => {
    if (!hasInitialized.current) {
      hasInitialized.current = true
      return
    }

    if (timerRef.current) {
      window.clearTimeout(timerRef.current)
      timerRef.current = null
    }

    timerRef.current = window.setTimeout(() => {
      onSave(value)
      timerRef.current = null
    }, delayMs)

    return () => {
      if (timerRef.current) {
        window.clearTimeout(timerRef.current)
        timerRef.current = null
      }
    }
  }, [delayMs, onSave, value])
}

