const [isConnectingProject, setIsConnectingProject] = useState(false)
const [showConnectToken, setShowConnectToken] = useState(false)
const [connectStatus, setConnectStatus] = useState("")
const [aiSettings, setAiSettings] = useState<AiClientSettings>(() => readAiClientSettingsFromStorage())
const [hasStoredAiToken, setHasStoredAiToken] = useState(false)
const [showAiToken, setShowAiToken] = useState(false)
const [aiStatus, setAiStatus] = useState("")
const [aiTestStatus, setAiTestStatus] = useState("")
