const selectedConnectProject = useMemo(
  () => connectProjects.find((project) => project.id === connectProjectId) ?? null,
  [connectProjectId, connectProjects],
)
const connectedReviewProjects = useMemo(() => {
  const deduped = new Map<string, { key: string; label: string; instanceUrl: string; projectId: string }>()
  for (const integration of integrations) {
    const key = encodeProjectScopeKey(integration.instanceUrl, integration.projectId)
    if (!deduped.has(key)) {
      deduped.set(key, {
        key,
        label: integration.projectPath,
        instanceUrl: integration.instanceUrl,
        projectId: integration.projectId,
      })
    }
  }
  return Array.from(deduped.values()).sort((a, b) => a.label.localeCompare(b.label))
}, [integrations])

const selectedReviewProjectScope = useMemo(() => {
  const { instanceUrl, projectId } = decodeProjectScopeKey(selectedReviewProjectScopeKey)
  if (!instanceUrl || !projectId) {
    return null
  }
  return {
    instanceUrl,
    projectId,
  }
}, [selectedReviewProjectScopeKey])

useEffect(() => {
  setTheme(getActualThemeMode(themeMode))
}, [setTheme, themeMode])

const handleTabChange = useCallback((nextTab: SettingsTab) => {
  if (activeTab === nextTab) {
    return
  }

  const nextQuery = new URLSearchParams(searchParams.toString())
  nextQuery.set("tab", nextTab)
  router.push(`${pathname}?${nextQuery.toString()}`, { scroll: false })
}, [activeTab, pathname, router, searchParams])

const buildSettingsTabHref = useCallback((nextTab: SettingsTab) => {
  const nextQuery = new URLSearchParams(searchParams.toString())
  nextQuery.set("tab", nextTab)
  return `${pathname}?${nextQuery.toString()}`
}, [pathname, searchParams])

