  }

  try {
    const payload = await fetchReviewPreferences({
      instanceUrl: selectedReviewProjectScope.instanceUrl,
      projectId: selectedReviewProjectScope.projectId,
    })
    setHasReviewProjectOverride(Boolean(payload.projectOverride))
    setReviewGateProjectSettings(payload.projectOverride ?? payload.global ?? reviewGateGlobalSettings)
  } catch (error) {
    setReviewGateStatus(error instanceof Error ? error.message : "Failed to load project override.")
    setHasReviewProjectOverride(false)
    setReviewGateProjectSettings(reviewGateGlobalSettings)
  }
}, [reviewGateGlobalSettings, selectedReviewProjectScope])

useEffect(() => {
  void loadGlobalReviewPreferences()
}, [loadGlobalReviewPreferences])

useEffect(() => {
  if (connectedReviewProjects.length === 0) {
    setSelectedReviewProjectScopeKey("")
    return
  }

  setSelectedReviewProjectScopeKey((current) => {
    if (current && connectedReviewProjects.some((project) => project.key === current)) {
      return current
    }
    return connectedReviewProjects[0]?.key ?? ""
  })
}, [connectedReviewProjects])

useEffect(() => {
