}

const handleThemeModeChange = (value: ThemeMode) => {
  setThemeMode(value)
}

const saveAiSettings = useCallback((value: AiClientSettings) => {
  const normalizedValue = normalizeAiClientSettings(value, defaultAiSettings)
  if (typeof window !== "undefined") {
    window.localStorage.setItem(AI_CLIENT_SETTINGS_STORAGE_KEY, JSON.stringify(normalizedValue))
  }

  void (async () => {
    const response = await fetch("/api/ai/settings", {
      method: "PUT",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify(normalizedValue),
    })
    const payload = await response.json().catch(() => null)
    if (!response.ok) {
      throw new Error(extractErrorMessage(payload, "Failed to save AI settings."))
    }

    const root = asRecord(payload)
    const data = asRecord(root?.data)
    if (data && typeof data.hasStoredToken === "boolean") {
      setHasStoredAiToken(data.hasStoredToken)
    } else {
      setHasStoredAiToken(normalizedValue.token.trim().length > 0)
    }

    setAiStatus("AI settings auto-saved.")
    clearStatusLater(setAiStatus)
  })().catch((error) => {
    setAiStatus(error instanceof Error ? error.message : "Failed to save AI settings.")
    clearStatusLater(setAiStatus)
    setHasStoredAiToken(normalizedValue.token.trim().length > 0)
  })
}, [clearStatusLater, defaultAiSettings])

const saveThemeMode = useCallback((value: ThemeMode) => {
  if (typeof window !== "undefined") {
    window.localStorage.setItem(THEME_SETTINGS_STORAGE_KEY, value)
    setThemeStatus("Theme preference auto-saved.")
    clearStatusLater(setThemeStatus)
  }
}, [clearStatusLater])

useDebouncedAutosave(aiSettings, saveAiSettings, SETTINGS_AUTOSAVE_DEBOUNCE_MS)
useDebouncedAutosave(themeMode, saveThemeMode, SETTINGS_AUTOSAVE_DEBOUNCE_MS)

useEffect(() => {
  if (themeMode !== "argus") {
    return
  }

  const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)")
  const handleSystemThemeChange = () => {
    setTheme(getActualThemeMode("argus"))
  }
  mediaQuery.addEventListener("change", handleSystemThemeChange)

  return () => {
    mediaQuery.removeEventListener("change", handleSystemThemeChange)
  }
}, [themeMode, setTheme])

return (
  <div className="min-h-full">
    <div className="grid min-h-0 gap-8 lg:grid-cols-[280px_minmax(0,1fr)]">
