import path from 'node:path'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'

import test from 'ava'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')

function loadAgentWithMockStream(mockIndexStream: any) {
  const agentPath = path.join(packageRoot, 'agent.js')
  const requireFromAgent = createRequire(agentPath)

  const streamResolved = requireFromAgent.resolve('./stream.js')
  const agentResolved = requireFromAgent.resolve('./agent.js')

  const prevStream = requireFromAgent.cache[streamResolved]
  const prevAgent = requireFromAgent.cache[agentResolved]

  requireFromAgent.cache[streamResolved] = {
    id: streamResolved,
    filename: streamResolved,
    loaded: true,
    exports: { indexStream: mockIndexStream },
  } as any
  delete requireFromAgent.cache[agentResolved]

  const mod = requireFromAgent('./agent.js') as any
  const restore = () => {
    if (prevStream) requireFromAgent.cache[streamResolved] = prevStream
    else delete requireFromAgent.cache[streamResolved]
    if (prevAgent) requireFromAgent.cache[agentResolved] = prevAgent
    else delete requireFromAgent.cache[agentResolved]
  }

  return { mod, restore }
}

