import { buildReviewCommentFeedbackKey } from "@/lib/review/comment-feedback"

export type ReviewGateStrictness = "quiet" | "balanced" | "thorough"

export type ReviewGateSettings = {
  strictness: ReviewGateStrictness
  requireEvidence: boolean
  securityBoost: boolean
}

export type ReviewGateScopeSource = "global_default" | "global" | "project"

export type ReviewGateEffectiveSettings = ReviewGateSettings & {
  scopeSource: ReviewGateScopeSource
}

export type ReviewFindingLike = {
  file: string
  line: number
  side: "additions" | "deletions"
  severity: "high" | "med" | "low"
  title: string
  body: string
  confidence: number
  evidence?: string
}

export type ReviewGateSuppressedByReason = {
  lowConfidence: number
  missingEvidence: number
}

export type ApplyReviewGateResult<T extends ReviewFindingLike> = {
  filteredFindings: T[]
  suppressedFindingsCount: number
  suppressedByReason: ReviewGateSuppressedByReason
}

export const REVIEW_GATE_DEFAULTS: ReviewGateSettings = {
  strictness: "balanced",
  requireEvidence: false,
  securityBoost: false,
}

export const REVIEW_GATE_THRESHOLDS: Record<
  ReviewGateStrictness,
  Record<ReviewFindingLike["severity"], number>
> = {
  quiet: {
    high: 0.88,
    med: 0.92,
    low: 0.96,
  },
  balanced: {
    high: 0.8,
    med: 0.88,
    low: 0.93,
  },
  thorough: {
    high: 0.72,
    med: 0.82,
    low: 0.89,
  },
}

const INVALID_EVIDENCE_VALUES = new Set(["n/a", "none", "unknown"])

export const normalizeReviewGateStrictness = (value: unknown): ReviewGateStrictness => {
  if (value === "quiet" || value === "balanced" || value === "thorough") {
    return value
  }
  return REVIEW_GATE_DEFAULTS.strictness
}

export const normalizeReviewGateSettings = (value: unknown): ReviewGateSettings => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return { ...REVIEW_GATE_DEFAULTS }
  }

  const candidate = value as Record<string, unknown>
  return {
    strictness: normalizeReviewGateStrictness(candidate.strictness),
    requireEvidence: candidate.requireEvidence === true,
    securityBoost: candidate.securityBoost === true,
  }
}

export const normalizeEvidence = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

export const hasStructuredEvidence = (value: unknown) => {
  const normalized = normalizeEvidence(value).toLowerCase()
  if (!normalized) {
    return false
  }
  return !INVALID_EVIDENCE_VALUES.has(normalized)
}

const getConfidenceThreshold = ({
  severity,
  settings,
}: {
  severity: ReviewFindingLike["severity"]
  settings: ReviewGateSettings
}) => {
  const baseThreshold = REVIEW_GATE_THRESHOLDS[settings.strictness][severity]
  if (settings.securityBoost && severity === "high") {
    return Math.max(0, baseThreshold - 0.05)
  }
  return baseThreshold
}

const normalizeConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0
  }
  return Math.max(0, Math.min(1, value))
}

export const dedupeReviewFindingsByConfidence = <T extends ReviewFindingLike>(findings: T[]) => {
  const deduped = new Map<string, T>()

  for (const finding of findings) {
    const key = buildReviewCommentFeedbackKey({
      file: finding.file,
      side: finding.side,
      line: finding.line,
      title: finding.title,
    })

    const current = deduped.get(key)
    if (!current) {
      deduped.set(key, finding)
      continue
    }

    const currentConfidence = normalizeConfidence(current.confidence)
    const nextConfidence = normalizeConfidence(finding.confidence)
    if (nextConfidence > currentConfidence) {
      deduped.set(key, finding)
      continue
    }

    if (nextConfidence === currentConfidence) {
      const currentEvidenceLength = normalizeEvidence(current.evidence).length
      const nextEvidenceLength = normalizeEvidence(finding.evidence).length
      if (nextEvidenceLength > currentEvidenceLength) {
        deduped.set(key, finding)
      }
    }
  }

  return Array.from(deduped.values())
}

export const applyReviewGate = <T extends ReviewFindingLike>({
  findings,
  settings,
}: {
  findings: T[]
  settings: ReviewGateSettings
}): ApplyReviewGateResult<T> => {
  const suppressedByReason: ReviewGateSuppressedByReason = {
    lowConfidence: 0,
    missingEvidence: 0,
  }

  const kept: T[] = []
  let suppressedFindingsCount = 0

  for (const finding of findings) {
    const threshold = getConfidenceThreshold({
      severity: finding.severity,
      settings,
    })

    const hasConfidence = normalizeConfidence(finding.confidence) >= threshold
    if (!hasConfidence) {
      suppressedByReason.lowConfidence += 1
    }

    const hasEvidence = !settings.requireEvidence || hasStructuredEvidence(finding.evidence)
    if (!hasEvidence) {
      suppressedByReason.missingEvidence += 1
    }

    if (hasConfidence && hasEvidence) {
      kept.push(finding)
    } else {
      suppressedFindingsCount += 1
    }
  }

  const filteredFindings = dedupeReviewFindingsByConfidence(kept)

  return {
    filteredFindings,
    suppressedFindingsCount,
    suppressedByReason,
  }
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import { Check, Copy, LoaderCircle, RefreshCw, Send, Sparkles, Square, Undo2 } from "lucide-react"
import { toast } from "sonner"
import dynamic from "next/dynamic"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { useCopyableErrorToast } from "@/components/ui/use-copyable-error-toast"
import { readAiClientSettingsFromStorage } from "@/lib/ai/client-settings"
import {
  getErrorMessage,
  getReviewErrorMessage,
  type DiffPayload,
} from "./merge-request-diff-viewer.utils"

const MergeRequestMarkdownRenderer = dynamic(
  () => import("./merge-request-markdown-renderer").then((module) => module.MergeRequestMarkdownRenderer),
  {
    ssr: false,
    loading: () => (
      <div className="rounded-lg border border-dashed p-4 text-sm text-muted-foreground">
        Rendering markdown preview...
      </div>
    ),
  },
