type MergeRequestDescriptionStreamPageProps = {
  instanceUrl: string
  token: string
  integrationId?: string
  projectId: string
  mergeRequestIid: string
}

type UpdateMergeRequestDescriptionPayload = {
  data?: {
    mergeRequestId?: unknown
    updated?: unknown
    previousDescription?: unknown
  }
  error?: unknown
}

type MergeRequestDetailsPayload = {
  data?: {
    title?: unknown
    description?: unknown
  }
  error?: unknown
}

type LatestAiDescriptionPayload = {
  data?: {
    description?: {
      markdown?: unknown
    } | null
  }
  error?: unknown
}

type DescriptionSource = "ai" | "gitlab"

const sanitizeMarkdown = (value: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    return ""
  }

  const fenced = trimmed.match(/^```(?:markdown|md)?\s*([\s\S]*?)```$/i)
  return (fenced?.[1] ?? trimmed).trim()
}

const copyToClipboard = async (value: string) => {
  if (
    typeof navigator === "undefined" ||
    !navigator.clipboard ||
    typeof navigator.clipboard.writeText !== "function"
  ) {
    throw new Error("Clipboard is unavailable in this browser.")
  }

  await navigator.clipboard.writeText(value)
}

const readDescriptionError = async (response: Response) => {
  const contentType = response.headers.get("content-type") ?? ""
  if (contentType.includes("application/json")) {
    const payload = await response.json().catch(() => null)
    return getReviewErrorMessage(payload)
  }

  const bodyText = await response.text().catch(() => "")
  const fallback = bodyText.trim()
  return fallback || "Unable to generate AI MR description."
}

const normalizeMarkdownForComparison = (value: string) =>
  sanitizeMarkdown(value).replace(/\r\n/g, "\n")

export function MergeRequestDescriptionStreamPage({
  instanceUrl,
  token,
  integrationId,
  projectId,
  mergeRequestIid,
}: MergeRequestDescriptionStreamPageProps) {
  const [patchText, setPatchText] = useState("")
  const [isLoadingPatch, setIsLoadingPatch] = useState(false)
  const [patchLoadError, setPatchLoadError] = useState("")

const [gitLabMarkdown, setGitLabMarkdown] = useState("")
const [aiMarkdown, setAiMarkdown] = useState("")
const [mergeRequestTitle, setMergeRequestTitle] = useState("")
const [activeSource, setActiveSource] = useState<DescriptionSource>("ai")
const [isGenerating, setIsGenerating] = useState(false)
const [descriptionError, setDescriptionError] = useState("")
const [hasLoadedSavedDescription, setHasLoadedSavedDescription] = useState(false)
const [hasCopied, setHasCopied] = useState(false)
const [isCopying, setIsCopying] = useState(false)
const [isPostingToGitLab, setIsPostingToGitLab] = useState(false)
const [isUndoingPostToGitLab, setIsUndoingPostToGitLab] = useState(false)
const [undoDescription, setUndoDescription] = useState<string | null>(null)
const [postToGitLabError, setPostToGitLabError] = useState("")

const generationAbortRef = useRef<AbortController | null>(null)
const hasAttemptedInitialGenerationRef = useRef(false)
const hasGitLabDescription = gitLabMarkdown.trim().length > 0
const hasAiDescription = aiMarkdown.trim().length > 0
const descriptionsDiffer =
  hasGitLabDescription &&
  hasAiDescription &&
  normalizeMarkdownForComparison(gitLabMarkdown) !== normalizeMarkdownForComparison(aiMarkdown)
const selectedSource = descriptionsDiffer
  ? activeSource
  : hasAiDescription
    ? "ai"
    : "gitlab"
const selectedMarkdown = selectedSource === "gitlab" ? gitLabMarkdown : aiMarkdown
const selectedTrimmedMarkdown = selectedMarkdown.trim()

useCopyableErrorToast(patchLoadError, { title: "Failed to load merge request diff" })
useCopyableErrorToast(descriptionError, { title: "AI MR description failed" })
useCopyableErrorToast(postToGitLabError, { title: "Failed to publish MR description" })

const loadPatch = useCallback(async () => {
  setIsLoadingPatch(true)
  setPatchLoadError("")

  try {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "merge-request-diff",
        instanceUrl,
        token,
        ...(integrationId ? { integrationId } : {}),
        projectId,
        mergeRequestIid,
      }),
    })

    const payload = (await response.json().catch(() => null)) as DiffPayload | null
    if (!response.ok) {
      throw new Error(getErrorMessage(payload))
    }

    if (!payload?.data || typeof payload.data.patch !== "string") {
      throw new Error("Unexpected diff response from server.")
    }

    setPatchText(payload.data.patch)
  } catch (error) {
    setPatchText("")
    setPatchLoadError(getErrorMessage(error))
  } finally {
    setIsLoadingPatch(false)
  }
}, [instanceUrl, integrationId, mergeRequestIid, projectId, token])

const loadInitialDescription = useCallback(async () => {
  setHasLoadedSavedDescription(false)
  setDescriptionError("")
  setGitLabMarkdown("")
  setAiMarkdown("")
  setMergeRequestTitle("")
  setUndoDescription(null)

hasAttemptedInitialGenerationRef.current = false

const normalizedInstanceUrl = instanceUrl.trim().replace(/\/+$/, "")
const normalizedProjectId = projectId.trim()
const normalizedMergeRequestIid = mergeRequestIid.trim()
if (!normalizedInstanceUrl || !normalizedProjectId || !normalizedMergeRequestIid) {
  setHasLoadedSavedDescription(true)
  return
}

try {
  const [gitLabResponse, aiResponse] = await Promise.all([
    fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "merge-request",
        instanceUrl: normalizedInstanceUrl,
        token,
        ...(integrationId ? { integrationId } : {}),
        projectId: normalizedProjectId,
        mergeRequestIid: normalizedMergeRequestIid,
      }),
    }),
    fetch(
      `/api/review/description?${new URLSearchParams({
        instanceUrl: normalizedInstanceUrl,
        projectId: normalizedProjectId,
        mergeRequestIid: normalizedMergeRequestIid,
      }).toString()}`,
    ),
  ])

  const errors: string[] = []

  const mergeRequestPayload = (await gitLabResponse.json().catch(() => null)) as MergeRequestDetailsPayload | null

  if (!gitLabResponse.ok) {
    errors.push(getErrorMessage(mergeRequestPayload))
  } else {
    const mergeRequestTitle =
      typeof mergeRequestPayload?.data?.title === "string" ? mergeRequestPayload.data.title.trim() : ""
    setMergeRequestTitle(mergeRequestTitle)

    const mergeRequestDescription =
      typeof mergeRequestPayload?.data?.description === "string"
        ? mergeRequestPayload.data.description.trim()
        : ""
    setGitLabMarkdown(mergeRequestDescription)
  }

  const aiPayload = (await aiResponse.json().catch(() => null)) as LatestAiDescriptionPayload | null
  if (!aiResponse.ok) {
    errors.push(getErrorMessage(aiPayload))
  } else {
    const latestAiDescription =
      typeof aiPayload?.data?.description?.markdown === "string"
        ? aiPayload.data.description.markdown.trim()
        : ""
    setAiMarkdown(latestAiDescription)
  }

  const hasInitialDescription =
    (typeof mergeRequestPayload?.data?.description === "string" &&
      mergeRequestPayload.data.description.trim().length > 0) ||
    (typeof aiPayload?.data?.description?.markdown === "string" &&
      aiPayload.data.description.markdown.trim().length > 0)
  if (hasInitialDescription) {
    hasAttemptedInitialGenerationRef.current = true
  }

  if (errors[0]) {
    setDescriptionError(errors[0])
  }
} catch (error) {
  setDescriptionError(getErrorMessage(error))
} finally {
  setHasLoadedSavedDescription(true)
}

}, [instanceUrl, integrationId, mergeRequestIid, projectId, token])

const streamDescription = useCallback(async () => {
  if (!patchText.trim()) {
    setDescriptionError("Load a diff before generating an AI MR description.")
    return
  }

  generationAbortRef.current?.abort()
  const abortController = new AbortController()
  generationAbortRef.current = abortController

  setIsGenerating(true)
  setDescriptionError("")
  setAiMarkdown("")
  setActiveSource("ai")

try {
  const aiSettings = readAiClientSettingsFromStorage()
  const response = await fetch("/api/review/description", {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      patch: patchText,
      instanceUrl,
      projectId,
      mergeRequestIid,
      apiUrl: aiSettings.apiUrl,
      model: aiSettings.model,
      token: aiSettings.token,
      stream: true,
    }),
    signal: abortController.signal,
  })

  if (!response.ok) {
    throw new Error(await readDescriptionError(response))
  }
  if (!response.body) {
    throw new Error("AI provider stream missing response body.")
  }

  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let nextMarkdown = ""

  while (true) {
    const { done, value } = await reader.read()
    if (done) {
      break
    }

    nextMarkdown += decoder.decode(value, { stream: true })
    setAiMarkdown(sanitizeMarkdown(nextMarkdown))
  }

  nextMarkdown += decoder.decode()
  setAiMarkdown(sanitizeMarkdown(nextMarkdown))
} catch (error) {
  if (abortController.signal.aborted) {
    return
  }
  setAiMarkdown("")
  setDescriptionError(getReviewErrorMessage(error))
} finally {
  if (generationAbortRef.current === abortController) {
    generationAbortRef.current = null
  }
  setIsGenerating(false)
}

}, [instanceUrl, mergeRequestIid, patchText, projectId])

useEffect(() => {
  void loadPatch()
}, [loadPatch])

useEffect(() => {
  void loadInitialDescription()
}, [loadInitialDescription])

useEffect(() => {
  if (!hasLoadedSavedDescription || !patchText || hasAttemptedInitialGenerationRef.current || isGenerating) {
    return
  }
  hasAttemptedInitialGenerationRef.current = true
  void streamDescription()
}, [hasLoadedSavedDescription, isGenerating, patchText, streamDescription])

useEffect(() => {
  return () => {
    generationAbortRef.current?.abort()
  }
}, [])

const handleStopGeneration = useCallback(() => {
  generationAbortRef.current?.abort()
}, [])

const handleCopyMarkdown = useCallback(async () => {
  const nextMarkdown = selectedTrimmedMarkdown
  if (!nextMarkdown || isCopying) {
    return
  }

  setIsCopying(true)
  try {
    await copyToClipboard(nextMarkdown)
    setHasCopied(true)
    toast.success("MR description copied")
    setTimeout(() => {
      setHasCopied(false)
    }, 1_800)
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unable to copy MR description."
    toast.error(message)
  } finally {
    setIsCopying(false)
  }
}, [isCopying, selectedTrimmedMarkdown])

const handlePostToGitLab = useCallback(async () => {
  const nextMarkdown = selectedTrimmedMarkdown
  if (!nextMarkdown || isPostingToGitLab || isUndoingPostToGitLab) {
    return
  }

  setIsPostingToGitLab(true)
  setPostToGitLabError("")

  try {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "update-merge-request-description",
        instanceUrl,
        token,
        ...(integrationId ? { integrationId } : {}),
        projectId,
        mergeRequestIid,
        description: nextMarkdown,
      }),
    })

    const payload = (await response.json().catch(() => null)) as UpdateMergeRequestDescriptionPayload | null
    if (!response.ok) {
      throw new Error(getErrorMessage(payload))
    }
    const previousDescription = payload?.data?.previousDescription
    setUndoDescription(typeof previousDescription === "string" ? previousDescription : null)
    setGitLabMarkdown(nextMarkdown)

    toast.success("MR description posted to GitLab")
  } catch (error) {
    const message = getErrorMessage(error)
    setPostToGitLabError(message)
    toast.error(message)
  } finally {
    setIsPostingToGitLab(false)
  }
}, [
  instanceUrl,
  integrationId,
  isPostingToGitLab,
  isUndoingPostToGitLab,
  mergeRequestIid,
  projectId,
  selectedTrimmedMarkdown,
  token,
])

const handleUndoPostToGitLab = useCallback(async () => {
  if (undoDescription === null || isPostingToGitLab || isUndoingPostToGitLab) {
    return
  }

  setIsUndoingPostToGitLab(true)
  setPostToGitLabError("")

  try {
    const response = await fetch("/api/gitlab", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        action: "update-merge-request-description",
        instanceUrl,
        token,
        ...(integrationId ? { integrationId } : {}),
        projectId,
        mergeRequestIid,
        description: undoDescription,
        allowEmptyDescription: true,
      }),
    })

    const payload = (await response.json().catch(() => null)) as UpdateMergeRequestDescriptionPayload | null
    if (!response.ok) {
      throw new Error(getErrorMessage(payload))
    }

    setGitLabMarkdown(undoDescription)
    setUndoDescription(null)
    toast.success("MR description reverted on GitLab")
  } catch (error) {
    const message = getErrorMessage(error)
    setPostToGitLabError(message)
    toast.error(message)
  } finally {
    setIsUndoingPostToGitLab(false)
  }
}, [
  instanceUrl,
  integrationId,
  isPostingToGitLab,
  isUndoingPostToGitLab,
  mergeRequestIid,
  projectId,
  token,
  undoDescription,
])

return (
  <Card className="border-border/60">
    <CardHeader className="pb-3">
      <div className="flex flex-wrap items-center justify-between gap-2">

{isGenerating ? (
  <Button type="button" size="sm" variant="outline" onClick={handleStopGeneration}>
    <Square className="size-4" aria-hidden="true" />
    Stop
  </Button>
) : null}
<Button
  type="button"
  size="sm"
  variant="outline"
  disabled={!selectedTrimmedMarkdown || isCopying}
  onClick={() => void handleCopyMarkdown()}
>
  {hasCopied ? (
    <Check className="size-4" aria-hidden="true" />
  ) : (
    <Copy className="size-4" aria-hidden="true" />
  )}
  {hasCopied ? "Copied" : "Copy markdown"}
</Button>
<Button
  type="button"
  size="sm"
  variant="outline"
  disabled={undoDescription === null || isPostingToGitLab || isUndoingPostToGitLab}
  onClick={() => void handleUndoPostToGitLab()}
>
  {isUndoingPostToGitLab ? (
    <LoaderCircle className="size-4 animate-spin" aria-hidden="true" />
  ) : (
    <Undo2 className="size-4" aria-hidden="true" />
  )}
  {isUndoingPostToGitLab ? "Undoing..." : "Undo post"}
</Button>

