type GraphStore = {
  nodesById: Map<string, GraphNode>
  nodesByFilePath: Map<string, GraphNode[]>
  outgoing: Map<string, GraphEdge[]>
  incoming: Map<string, GraphEdge[]>
}

type GraphArtifactsManifest = {
  indexRunId: string
  generatedAt: string
}

type DbClient = typeof db

type KiteDbFsBackendDeps = {
  dbClient: DbClient
  graphArtifactsRoot: string
  readTextFile: (filePath: string) => Promise<string>
  statPath: (filePath: string) => Promise<Awaited<ReturnType<typeof stat>>>
}

const DEFAULT_GRAPH_ARTIFACTS_ROOT = path.resolve(
  process.env.INDEXER_GRAPH_DIR?.trim() ||
    path.join(process.cwd(), ".indexer-artifacts", "graphs"),
)

const normalizeBackend = (value: string | undefined): ImpactGraphBackendKind => {
  const normalized = value?.trim().toLowerCase()
  if (normalized === "legacy_index_pack") {
    return "legacy_index_pack"
  }
  return "kitedb_fs"
}

const normalizePath = (value: string) =>
  value
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")

const toPositiveInt = (value: unknown) =>
  typeof value === "number" && Number.isFinite(value) && value >= 0
    ? Math.floor(value)
    : null

const toOptionalString = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }
  const normalized = value.trim()
  return normalized.length > 0 ? normalized : null
}

const isGraphRange = (
  value: unknown,
): value is {
  start: { row: number; column: number }
  end: { row: number; column: number }
} => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return false
  }
  const record = value as Record<string, unknown>
  const start = record.start
  const end = record.end
  if (!start || typeof start !== "object" || Array.isArray(start)) {
    return false
  }
  if (!end || typeof end !== "object" || Array.isArray(end)) {
    return false
  }
  const startRecord = start as Record<string, unknown>
  const endRecord = end as Record<string, unknown>
  const startRow = toPositiveInt(startRecord.row)
  const startColumn = toPositiveInt(startRecord.column)
  const endRow = toPositiveInt(endRecord.row)
  const endColumn = toPositiveInt(endRecord.column)
  return startRow !== null && startColumn !== null && endRow !== null && endColumn !== null
}

const parseNodeLine = (value: unknown): GraphNode | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  const record = value as Record<string, unknown>
  const id = toOptionalString(record.id)
  const kind = toOptionalString(record.kind)
  if (!id || !kind) {
    return null
  }

  return {
    id,
    kind,
    name: toOptionalString(record.name),
    filePath: toOptionalString(record.filePath),
    range: isGraphRange(record.range)
      ? {
          start: {
            row: Math.floor(record.range.start.row),
            column: Math.floor(record.range.start.column),
          },
          end: {
            row: Math.floor(record.range.end.row),
            column: Math.floor(record.range.end.column),
          },
        }
      : null,
  }
}

const parseEdgeLine = (value: unknown): GraphEdge | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }

  const record = value as Record<string, unknown>
  const sourceId = toOptionalString(record.sourceId)
  const targetId = toOptionalString(record.targetId)
  const type = toOptionalString(record.type)
  if (!sourceId || !targetId || !type) {
    return null
  }

  return {
    sourceId,
    targetId,
    type,
  }
}

const parseJsonLine = (line: string): unknown => {
  try {
    return JSON.parse(line)
  } catch {
    return null
  }
}

const readJsonl = async <T>(filePath: string, parse: (value: unknown) => T | null) => {
  const records: T[] = []
  const stream = createReadStream(filePath, { encoding: "utf8" })
  const rl = createInterface({ input: stream, crlfDelay: Infinity })

  try {
    for await (const line of rl) {
      const trimmed = line.trim()
      if (!trimmed) {
        continue
      }
      const parsed = parse(parseJsonLine(trimmed))
      if (parsed) {
        records.push(parsed)
      }
    }
  } finally {
    rl.close()
    stream.destroy()
  }

  return records
}

const includesLine = (node: GraphNode, lineNumber: number) => {
  if (!node.range) {
    return false
  }
  const safeLine = Math.max(1, Math.floor(lineNumber))
  const zeroBasedLine = safeLine - 1
  return zeroBasedLine >= node.range.start.row && zeroBasedLine <= node.range.end.row
}

const nodeSpanRows = (node: GraphNode) => {
  if (!node.range) {
    return Number.POSITIVE_INFINITY
  }
  return Math.max(0, node.range.end.row - node.range.start.row)
}

const nodeKindRank = (kind: string) => {
  switch (kind.toLowerCase()) {
    case "function":
    case "method":
      return 0
    case "class":
    case "interface":
    case "type":
      return 1
    case "variable":
    case "constant":
      return 2
    case "file":
      return 9
    default:
      return 4
  }
}

const pickBestNode = (nodes: GraphNode[]) => {
  if (nodes.length === 0) {
    return null
  }

  return [...nodes].sort((left, right) => {
    const spanDelta = nodeSpanRows(left) - nodeSpanRows(right)
    if (spanDelta !== 0) {
      return spanDelta
    }

    const rankDelta = nodeKindRank(left.kind) - nodeKindRank(right.kind)
    if (rankDelta !== 0) {
      return rankDelta
    }

    return (left.name ?? "").localeCompare(right.name ?? "")
  })[0] ?? null
}

const collectReachableNodeIds = ({
  store,
  startNodeId,
  direction,
  edgeTypes,
  depth,
  maxNodes,
}: {
  store: GraphStore
  startNodeId: string
  direction: "incoming" | "outgoing" | "both"
  edgeTypes: Set<string>
  depth: number
  maxNodes: number
}) => {

  const queue: Array<{ id: string; depth: number }> = [{ id: startNodeId, depth: 0 }]
  const visited = new Set<string>([startNodeId])
  const reached = new Set<string>()

  while (queue.length > 0 && reached.size < maxNodes) {
    const current = queue.shift()
    if (!current) {
      break
    }
    if (current.depth >= depth) {
      continue
    }

    if (direction !== "incoming") {
      const outgoing = store.outgoing.get(current.id) ?? []
      for (const edge of outgoing) {
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        const nextId = edge.targetId
        if (nextId !== startNodeId) {
          reached.add(nextId)
        }
        if (!visited.has(nextId) && visited.size < maxNodes) {
          visited.add(nextId)
          queue.push({ id: nextId, depth: current.depth + 1 })
        }
      }
    }

    if (direction !== "outgoing") {
      const incoming = store.incoming.get(current.id) ?? []
      for (const edge of incoming) {
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        const nextId = edge.sourceId
        if (nextId !== startNodeId) {
          reached.add(nextId)
        }
        if (!visited.has(nextId) && visited.size < maxNodes) {
          visited.add(nextId)
          queue.push({ id: nextId, depth: current.depth + 1 })
        }
      }
    }
  }

  return reached
}

const parseManifest = (raw: string): GraphArtifactsManifest => {
  const parsed = JSON.parse(raw) as Record<string, unknown>
  const indexRunId = toOptionalString(parsed.indexRunId)
  const generatedAt = toOptionalString(parsed.generatedAt)
  if (!indexRunId || !generatedAt) {
    throw new Error("Graph index-pack manifest is missing indexRunId/generatedAt.")
  }

  return {
    indexRunId,
    generatedAt,
  }
}

const ensureWithinRoot = (root: string, targetPath: string) => {
  const resolvedRoot = path.resolve(root)
  const resolvedPath = path.resolve(targetPath)
  const rootWithSeparator = `${resolvedRoot}${path.sep}`
  if (resolvedPath !== resolvedRoot && !resolvedPath.startsWith(rootWithSeparator)) {
    throw new Error("Graph artifact path escapes configured root.")
  }
  return resolvedPath
}

const resolveRunGraphPaths = (graphRoot: string, artifactsPrefix: string) => {
  const runDir = ensureWithinRoot(graphRoot, path.join(graphRoot, artifactsPrefix))
  return {
    runDir,
    indexStorePath: path.join(runDir, "index.kite"),
    indexStoreManifestPath: path.join(runDir, "index.kite.manifest.json"),
    nodesPath: path.join(runDir, "graph.nodes.jsonl"),
    edgesPath: path.join(runDir, "graph.edges.jsonl"),
    indexPackManifestPath: path.join(runDir, "index-pack.manifest.json"),
  }
}

const basePendingSnapshot = ({
  backend,
  integrationId,
  branch,
  reason,
  message,
}: {
  backend: ImpactGraphBackendKind
  integrationId: string | null
  branch: string | null
  reason: GraphSnapshotPendingReason
  message: string
}): GraphImpactSnapshotPending => ({
  status: "pending_graph",
  backend,
  integrationId,
  branch,
  reason,
  message,
})

const toMillis = (value: Date | null) => value?.getTime() ?? 0

class KiteDbFsGraphImpactBackend implements GraphImpactBackend {
  readonly kind: ImpactGraphBackendKind = "kitedb_fs"
  private readonly deps: KiteDbFsBackendDeps
  private readonly storeCache = new Map<string, Promise<GraphStore>>()

  constructor(deps: KiteDbFsBackendDeps) {
    this.deps = deps
  }

  async resolveSnapshot(args: {
    integrationId: string | null
    sourceBranch: string | null
  }): Promise<GraphImpactSnapshotResolution> {
    const integrationId = toOptionalString(args.integrationId)
    if (!integrationId) {
      return basePendingSnapshot({
        backend: this.kind,
        integrationId: null,
        branch: toOptionalString(args.sourceBranch),
        reason: "missing_integration_id",
        message: "Review is missing integration scope.",
      })
    }

    const branch = toOptionalString(args.sourceBranch)
    if (!branch) {
      return basePendingSnapshot({
        backend: this.kind,
        integrationId,
        branch: null,
        reason: "missing_source_branch",
        message: "Review is missing source branch metadata.",
      })
    }

try {
  const branchStates = await this.deps.dbClient.query.indexBranchStates.findMany({
    where: and(
      eq(indexBranchStates.integrationId, integrationId),
      eq(indexBranchStates.branch, branch),
    ),
    columns: {
      id: true,
      lastReadyRunId: true,
      servingUpdatedAt: true,
      updatedAt: true,
    },
  })

  if (branchStates.length === 0) {
    return basePendingSnapshot({
      backend: this.kind,
      integrationId,
      branch,
      reason: "branch_state_not_found",
      message: "Branch has not been indexed yet.",
    })
  }

  const selectedState = [...branchStates]
    .sort(
      (left, right) =>
        toMillis(right.servingUpdatedAt ?? right.updatedAt) -
        toMillis(left.servingUpdatedAt ?? left.updatedAt),
    )
    .find((state) => typeof state.lastReadyRunId === "string" && state.lastReadyRunId.length > 0)

  if (!selectedState?.lastReadyRunId) {
    return basePendingSnapshot({
      backend: this.kind,
      integrationId,
      branch,
      reason: "no_ready_run",
      message: "Branch indexing is still in progress.",
    })
  }

  const run = await this.deps.dbClient.query.indexRuns.findFirst({
    where: eq(indexRuns.id, selectedState.lastReadyRunId),
    columns: {
      id: true,
      status: true,
      artifactsPrefix: true,
    },
  })

if (!run || run.status !== "ready") {
  return basePendingSnapshot({
    backend: this.kind,
    integrationId,
    branch,
    reason: "ready_run_not_found",
    message: "No ready graph snapshot is available for this branch.",
  })
}

const artifactsPrefix = toOptionalString(run.artifactsPrefix)
if (!artifactsPrefix) {
  return basePendingSnapshot({
    backend: this.kind,
    integrationId,
    branch,
    reason: "missing_artifacts",
    message: "Graph artifacts are missing for the latest ready run.",
  })
}

const paths = resolveRunGraphPaths(this.deps.graphArtifactsRoot, artifactsPrefix)
const requiredPaths = [
  paths.indexStorePath,
  paths.indexStoreManifestPath,
  paths.indexPackManifestPath,
  paths.nodesPath,
  paths.edgesPath,
]

try {
  await Promise.all(requiredPaths.map((filePath) => this.deps.statPath(filePath)))
} catch {
  return basePendingSnapshot({
    backend: this.kind,
    integrationId,
    branch,
    reason: "missing_artifacts",
    message: "Branch graph artifacts are not ready yet.",
  })
}

const manifestRaw = await this.deps.readTextFile(paths.indexPackManifestPath)
const manifest = parseManifest(manifestRaw)

    return {
      status: "ready",
      backend: this.kind,
      integrationId,
      branch,
      indexRunId: manifest.indexRunId,
      generatedAt: manifest.generatedAt,
      graphStorePath: paths.indexStorePath,
      nodesPath: paths.nodesPath,
      edgesPath: paths.edgesPath,
    }
  } catch (error) {
    return {
      status: "error",
      backend: this.kind,
      integrationId,
      branch,
      error: errorMessage(error),
    }
  }
}

private async loadStore(snapshot: GraphImpactSnapshotReady): Promise<GraphStore> {
  if (!snapshot.nodesPath || !snapshot.edgesPath) {
    throw new Error("Snapshot does not include graph nodes/edges paths.")
  }

  const cacheKey = `${snapshot.indexRunId}:${snapshot.nodesPath}:${snapshot.edgesPath}`
  const cached = this.storeCache.get(cacheKey)
  if (cached) {
    return cached
  }

const loading = (async () => {
  const [nodes, edges] = await Promise.all([
    readJsonl(snapshot.nodesPath!, parseNodeLine),
    readJsonl(snapshot.edgesPath!, parseEdgeLine),
  ])

  const nodesById = new Map<string, GraphNode>()
  const nodesByFilePath = new Map<string, GraphNode[]>()
  for (const node of nodes) {
    nodesById.set(node.id, node)
    if (!node.filePath) {
      continue
    }
    const normalizedPath = normalizePath(node.filePath)
    const current = nodesByFilePath.get(normalizedPath) ?? []
    current.push(node)
    nodesByFilePath.set(normalizedPath, current)
  }

  const outgoing = new Map<string, GraphEdge[]>()
  const incoming = new Map<string, GraphEdge[]>()
  for (const edge of edges) {
    const currentOutgoing = outgoing.get(edge.sourceId) ?? []
    currentOutgoing.push(edge)
    outgoing.set(edge.sourceId, currentOutgoing)

    const currentIncoming = incoming.get(edge.targetId) ?? []
    currentIncoming.push(edge)
    incoming.set(edge.targetId, currentIncoming)
  }

  return {
    nodesById,
    nodesByFilePath,
    outgoing,
    incoming,
  }
})()

this.storeCache.set(cacheKey, loading)
return loading

}

async matchFindingLocation(args: {
  snapshot: GraphImpactSnapshotReady
  filePath: string
  line: number
  title?: string
}): Promise<GraphImpactNodeMatch | null> {
  const store = await this.loadStore(args.snapshot)
  const normalizedFilePath = normalizePath(args.filePath)
  if (!normalizedFilePath) {
    return null
  }

  const nodesInFile = store.nodesByFilePath.get(normalizedFilePath) ?? []
  if (nodesInFile.length === 0) {
    return null
  }

  const symbolNodes = nodesInFile.filter((node) => node.kind !== "file" && includesLine(node, args.line))
  const normalizedTitle = (args.title ?? "").trim().toLowerCase()
  const symbolTitleMatches = normalizedTitle
    ? symbolNodes.filter((node) => {
        const name = (node.name ?? "").trim().toLowerCase()
        return name.length > 0 && normalizedTitle.includes(name)
      })
    : []

  const symbolNode = pickBestNode(symbolTitleMatches) ?? pickBestNode(symbolNodes)
  if (symbolNode) {
    return {
      nodeId: symbolNode.id,
      scope: "symbol",
      sourceFile: symbolNode.filePath ?? normalizedFilePath,
      sourceLine: args.line,
    }
  }

  const fileNode = nodesInFile.find((node) => node.kind === "file") ?? nodesInFile[0]
  if (!fileNode) {
    return null
  }

  return {
    nodeId: fileNode.id,
    scope: "file",
    sourceFile: fileNode.filePath ?? normalizedFilePath,
    sourceLine: args.line,
  }
}

async summarizeImpact(args: {

  snapshot: GraphImpactSnapshotReady
  nodeId: string
}): Promise<GraphImpactSummary> {
  const store = await this.loadStore(args.snapshot)
  const nodeId = args.nodeId.trim()
  if (!nodeId) {
    throw new Error("Impact summary requires a non-empty nodeId.")
  }

  const callers = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "incoming",
    edgeTypes: new Set(["CALLS"]),
    depth: 2,
    maxNodes: 4_000,
  })
  const callees = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "outgoing",
    edgeTypes: new Set(["CALLS"]),
    depth: 2,
    maxNodes: 4_000,
  })
  const dependents = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "incoming",
    edgeTypes: new Set(["IMPORTS"]),
    depth: 2,
    maxNodes: 4_000,
  })
  const dependencies = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "outgoing",
    edgeTypes: new Set(["IMPORTS"]),
    depth: 2,
    maxNodes: 4_000,
  })
  const impacted = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "both",
    edgeTypes: new Set(["CALLS", "IMPORTS", "REFERENCES"]),
    depth: 2,
    maxNodes: 4_000,
  })

  const fileCounts = new Map<string, number>()
  let affectedSymbolsCount = 0

    for (const impactedNodeId of impacted) {
      const node = store.nodesById.get(impactedNodeId)
      if (!node) {
        continue
      }
      if (node.kind !== "file") {
        affectedSymbolsCount += 1
      }
      if (!node.filePath) {
        continue
      }
      const normalizedFilePath = normalizePath(node.filePath)
      fileCounts.set(normalizedFilePath, (fileCounts.get(normalizedFilePath) ?? 0) + 1)
    }

    const topImpactedFiles = [...fileCounts.entries()]
      .sort((left, right) => {
        if (right[1] !== left[1]) {
          return right[1] - left[1]
        }
        return left[0].localeCompare(right[0])
      })
      .slice(0, 5)
      .map(([filePath, count]) => ({ filePath, count }))

    return {
      callersCount: callers.size,
      calleesCount: callees.size,
      dependentsCount: dependents.size,
      dependenciesCount: dependencies.size,
      affectedFilesCount: fileCounts.size,
      affectedSymbolsCount,
      topImpactedFiles,
    }
  }
}

