const loadNormalizer = async (allowPrivateHosts?: string) => {
  const previous = process.env.GITLAB_ALLOW_PRIVATE_HOSTS
  if (allowPrivateHosts === undefined) {
    delete process.env.GITLAB_ALLOW_PRIVATE_HOSTS
  } else {
    process.env.GITLAB_ALLOW_PRIVATE_HOSTS = allowPrivateHosts
  }

  try {
    const mod = await import(`./instance.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
    return mod.normalizeGitLabInstanceUrl as (input: string) => string
  } finally {
    if (previous === undefined) {
      delete process.env.GITLAB_ALLOW_PRIVATE_HOSTS
    } else {
      process.env.GITLAB_ALLOW_PRIVATE_HOSTS = previous
    }
  }
}

describe("normalizeGitLabInstanceUrl", () => {
  test("normalizes valid public URLs", async () => {
    const normalize = await loadNormalizer()

    expect(normalize("gitlab.com/")).toBe("https://gitlab.com")
    expect(normalize("https://gitlab.com/group/project/?foo=bar#frag")).toBe(
      "https://gitlab.com/group/project",
    )
  })

  test("rejects credentials and private hosts by default", async () => {
    const normalize = await loadNormalizer()

    expect(() => normalize("https://user:pass@gitlab.com")).toThrow(
      "GitLab instance URL must not include credentials.",
    )
    expect(() => normalize("http://localhost:3000")).toThrow(
      "GitLab instance URL must use a public host.",
    )
    expect(() => normalize("http://127.0.0.1:3000")).toThrow(
      "GitLab instance URL must use a public host.",
    )
    expect(() => normalize("http://192.168.1.10")).toThrow(
      "GitLab instance URL must use a public host.",
    )
  })

  test("allows private hosts when explicitly enabled", async () => {
    const normalize = await loadNormalizer("1")
    expect(normalize("http://localhost:3000")).toBe("http://localhost:3000")
  })
})

const fs = require('node:fs/promises')
const path = require('node:path')
const readline = require('node:readline')

const binding = require('./index.js')
const { clampTopK } = require('./search-contract.js')

function jsonRpcResult(id, result) {
  return { jsonrpc: '2.0', id: id ?? null, result }
}

function jsonRpcError(id, code, message, data) {
  return { jsonrpc: '2.0', id: id ?? null, error: { code, message, ...(data ? { data } : {}) } }
}

async function safeResolveWithinRoot(rootDir, unsafePath) {
  const rootInput = path.resolve(String(rootDir))
  const root = await fs.realpath(rootInput).catch(() => rootInput)
  const resolvedInput = path.resolve(root, String(unsafePath))
  const resolved = await fs.realpath(resolvedInput).catch(() => resolvedInput)
  const rel = path.relative(root, resolved)
  if (rel === '..' || rel.startsWith('..' + path.sep) || path.isAbsolute(rel)) {
    throw new Error('path escapes project root')
  }
  return { root, resolved }
}

function toolDefs() {
  return [
    {
      name: 'code_search',
      title: 'Code search',
      description: 'Search over indexed code chunks (KiteDB-backed).',
      inputSchema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          query: { type: 'string' },
          topK: { type: 'integer', minimum: 1, maximum: 50, default: 5 },
        },
        required: ['query'],
      },
    },
    {
      name: 'code_open',
      title: 'Open file',
      description: 'Open a file (optionally line-ranged) within the configured project root.',
      inputSchema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          filePath: { type: 'string', description: 'Path relative to project root (or absolute within it)' },
          startLine: { type: 'integer', minimum: 1, default: 1 },
          endLine: { type: 'integer', minimum: 1, default: 200 },
          maxChars: { type: 'integer', minimum: 256, maximum: 200000, default: 20000 },
        },
        required: ['filePath'],
      },
    },
    {
      name: 'code_reindex',
      title: 'Reindex',
      description: 'Rebuild the KiteDB index.',
      inputSchema: { type: 'object', additionalProperties: false, properties: {} },
    },
  ]
}

function createStdioMcpServer(options) {
  const {
    projectRoot,
    storePath,
    indexOptions,
    vectorProvider,
    indexOnStart = true,
    quiet = false,
  } = options ?? {}

  if (!projectRoot) throw new Error('projectRoot is required')
  if (!storePath) throw new Error('storePath is required')

if (!vectorProvider) throw new Error('vectorProvider is required')

let indexed = false
let indexing = null
let shuttingDown = false
let rl = null
let exitCode = 0

const ensureIndexed = async ({ clear = false } = {}) => {
  if (indexed && !clear) return
  if (indexing) return indexing
  indexing = (async () => {
    await binding.indexToKiteDb(
      {
        ...indexOptions,
        projectRoot,
        vector: { ...indexOptions?.vector, provider: vectorProvider },
      },
      { path: storePath, clear: Boolean(clear) },
    )
    indexed = true
  })().finally(() => {
    indexing = null
  })
  return indexing
}

const callTool = async (name, args) => {
  if (name === 'code_search') {
    await ensureIndexed()
    const query = String(args?.query ?? '')
    const topK = clampTopK(args?.topK)
    const hits = await binding.searchKiteDb({
      projectRoot,
      store: { path: storePath },
      query,
      topK,
      vectorProvider,
    })
    return { content: [{ type: 'text', text: JSON.stringify(hits, null, 2) }] }
  }

  if (name === 'code_open') {
    const filePath = String(args?.filePath ?? '')
    const startLine = Math.max(1, Number(args?.startLine) || 1)
    const endLine = Math.max(startLine, Number(args?.endLine) || startLine + 199)
    const maxChars = Math.max(256, Math.min(200000, Number(args?.maxChars) || 20000))

    const { root, resolved: absPath } = await safeResolveWithinRoot(projectRoot, filePath)
    const content = await fs.readFile(absPath, 'utf8')
    const lines = content.split('\n')
    const slice = lines.slice(startLine - 1, endLine)
    let text = slice.join('\n')
    if (text.length > maxChars) text = text.slice(0, maxChars)

    return {
      content: [
        {
          type: 'text',
          text: `file: ${path.relative(root, absPath)}\nlines: ${startLine}-${endLine}\n\n${text}`,
        },
      ],
    }
  }

  if (name === 'code_reindex') {
    await ensureIndexed({ clear: true })
    return { content: [{ type: 'text', text: 'reindexed' }] }
  }

  throw new Error(`unknown tool: ${name}`)
}

const write = (message) => {
  // MCP stdio transport is newline-delimited JSON. Keep it single-line.
  process.stdout.write(`${JSON.stringify(message)}\n`)
}

const log = (msg) => {
  if (quiet) return
  process.stderr.write(`${msg}\n`)
}

const requestStop = (code = 0) => {
  exitCode = Number(code) || 0
  if (rl) {
    rl.close()
    return
  }
  process.exitCode = exitCode
}

const onRequest = async (request) => {
  const id = request?.id ?? null
  const method = String(request?.method ?? '')

  if (!method) return write(jsonRpcError(id, -32600, 'invalid request'))

  if (method === 'initialize') {
    return write(
      jsonRpcResult(id, {
        protocolVersion: request?.params?.protocolVersion ?? '2025-11-25',
        serverInfo: { name: '@argus/argus-search', version: '0.1.0' },
        capabilities: { tools: { listChanged: false } },
      }),
    )
  }

  if (method === 'tools/list') {
    return write(jsonRpcResult(id, { tools: toolDefs() }))
  }

  if (method === 'tools/call') {
    const name = String(request?.params?.name ?? '')
    const args = request?.params?.arguments ?? {}
    try {
      const result = await callTool(name, args)
      return write(jsonRpcResult(id, result))
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error)
      return write(jsonRpcError(id, -32000, message))
    }
  }

  if (method === 'shutdown') {
    shuttingDown = true
    return write(jsonRpcResult(id, null))
  }

  if (method === 'exit') {
    requestStop(shuttingDown ? 0 : 1)
    return
  }

  write(jsonRpcError(id, -32601, `method not found: ${method}`))
}

  const start = async () => {
    if (indexOnStart) {
      log(`indexing to ${storePath}...`)
      await ensureIndexed()
      log('ready')
    } else {
      log('ready (indexOnStart=false)')
    }

    rl = readline.createInterface({ input: process.stdin, crlfDelay: Infinity })
    const onSignal = () => requestStop(0)
    process.once('SIGINT', onSignal)
    process.once('SIGTERM', onSignal)
    rl.on('line', async (line) => {
      const trimmed = String(line ?? '').trim()
      if (!trimmed) return
      let request = null
      try {
        request = JSON.parse(trimmed)
      } catch {
        write(jsonRpcError(null, -32700, 'parse error'))
        return
      }
      try {
        await onRequest(request)
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error)
        write(jsonRpcError(request?.id ?? null, -32000, message))
      }
    })

    rl.on('close', () => {
      process.off('SIGINT', onSignal)
      process.off('SIGTERM', onSignal)
      process.exit(exitCode)
    })
  }

  return { start }
}

module.exports = { createStdioMcpServer }

