import { and, eq } from "drizzle-orm"

import { db } from "@/lib/db"
import { gitlabUserInstanceTokens } from "@/lib/db/schema"
import { decryptGitLabToken, encryptGitLabToken } from "@/lib/gitlab/crypto"
import { normalizeGitLabInstanceUrl } from "@/lib/gitlab/instance"

export type GitLabUserInstanceToken = {
  token: string
  staleAt: Date | null
  staleReason: string | null
  lastValidatedAt: Date | null
}

export const getGitLabUserInstanceToken = async (
  userId: string,
  instanceUrl: string,
): Promise<GitLabUserInstanceToken | null> => {
  const normalizedInstanceUrl = normalizeGitLabInstanceUrl(instanceUrl)

  let row:
    | typeof gitlabUserInstanceTokens.$inferSelect
    | undefined
  try {
    row = await db.query.gitlabUserInstanceTokens.findFirst({
      where: and(
        eq(gitlabUserInstanceTokens.userId, userId),
        eq(gitlabUserInstanceTokens.instanceUrl, normalizedInstanceUrl),
      ),
    })
  } catch {
    // Token cache storage is optional; if unavailable/misaligned, fall back to
    // request token or integration token resolution paths.
    return null
  }

  if (!row) {
    return null
  }

  return {
    token: decryptGitLabToken({
      ciphertext: row.tokenCiphertext,
      iv: row.tokenIv,
      authTag: row.tokenAuthTag,
    }),
    staleAt: row.staleAt,
    staleReason: row.staleReason,
    lastValidatedAt: row.lastValidatedAt,
  }
}

export const upsertGitLabUserInstanceToken = async ({
  userId,
  instanceUrl,
  token,
}: {
  userId: string
  instanceUrl: string
  token: string
}) => {
  const normalizedInstanceUrl = normalizeGitLabInstanceUrl(instanceUrl)
  const normalizedToken = token.trim()

  if (!normalizedToken) {
    throw new Error("Personal access token is required.")
  }

  const encryptedToken = encryptGitLabToken(normalizedToken)

  await db
    .insert(gitlabUserInstanceTokens)
    .values({
      userId,
      instanceUrl: normalizedInstanceUrl,
      tokenCiphertext: encryptedToken.ciphertext,
      tokenIv: encryptedToken.iv,
      tokenAuthTag: encryptedToken.authTag,
      staleAt: null,
      staleReason: null,
      lastValidatedAt: new Date(),
    })
    .onConflictDoUpdate({
      target: [
        gitlabUserInstanceTokens.userId,
        gitlabUserInstanceTokens.instanceUrl,
      ],
      set: {
        tokenCiphertext: encryptedToken.ciphertext,
        tokenIv: encryptedToken.iv,
        tokenAuthTag: encryptedToken.authTag,
        staleAt: null,
        staleReason: null,
        lastValidatedAt: new Date(),
        updatedAt: new Date(),
      },
    })
}

export const markGitLabUserInstanceTokenStale = async ({
  userId,
  instanceUrl,
  reason,
}: {
  userId: string
  instanceUrl: string
  reason: string
}) => {
  const normalizedInstanceUrl = normalizeGitLabInstanceUrl(instanceUrl)

  await db
    .update(gitlabUserInstanceTokens)
    .set({
      staleAt: new Date(),
      staleReason: reason,
      updatedAt: new Date(),
    })
    .where(
      and(
        eq(gitlabUserInstanceTokens.userId, userId),
        eq(gitlabUserInstanceTokens.instanceUrl, normalizedInstanceUrl),
      ),
    )
}

