const http = require('node:http')
const path = require('node:path')
const fs = require('node:fs/promises')

const { createArgusSearch } = require('./agent.js')
const { clampTopK } = require('./search-contract.js')

function toSse(res, payload) {
  res.statusCode = 200
  res.setHeader('content-type', 'text/event-stream')
  res.setHeader('cache-control', 'no-cache')
  res.setHeader('connection', 'keep-alive')
  res.end(`data: ${JSON.stringify(payload)}\n\n`)
}

function jsonRpcResult({ id, result }) {
  return { jsonrpc: '2.0', id: id ?? null, result }
}

function jsonRpcError({ id, code, message, data }) {
  return {
    jsonrpc: '2.0',
    id: id ?? null,
    error: {
      code,
      message,
      ...(data ? { data } : {}),
    },
  }
}

async function safeResolveWithinRoot(rootDir, unsafePath) {
  const rootInput = path.resolve(String(rootDir))
  const root = await fs.realpath(rootInput).catch(() => rootInput)
  const resolvedInput = path.resolve(root, String(unsafePath))
  const resolved = await fs.realpath(resolvedInput).catch(() => resolvedInput)
  const rel = path.relative(root, resolved)
  if (rel === '..' || rel.startsWith('..' + path.sep) || path.isAbsolute(rel)) {
    throw new Error('path escapes project root')
  }
  return { root, resolved }
}

function toolDefs() {
  return [
    {
      name: 'code_search',
      description: 'Search over indexed code chunks.',
      inputSchema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          query: { type: 'string' },
          topK: { type: 'integer', minimum: 1, maximum: 50, default: 5 },
        },
        required: ['query'],
      },
    },
    {
      name: 'code_open',
      description: 'Open a file (optionally line-ranged) within the indexed project root.',
      inputSchema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          filePath: { type: 'string', description: 'Path relative to project root (or absolute within it)' },
          startLine: { type: 'integer', minimum: 1, default: 1 },
          endLine: { type: 'integer', minimum: 1, default: 200 },
          maxChars: { type: 'integer', minimum: 256, maximum: 200000, default: 20000 },
        },
        required: ['filePath'],
      },
    },
    {
      name: 'code_reindex',
      description: 'Rebuild the in-memory index for the configured project root.',
      inputSchema: {
        type: 'object',
        additionalProperties: false,
        properties: {},
      },
    },
  ]
}

async function readRequestBody(req, { maxBytes = 1024 * 1024 } = {}) {
  return new Promise((resolve, reject) => {
    let raw = ''
    let size = 0
    let rejected = false
    req.on('data', (chunk) => {
      if (rejected) return
      size += chunk.length
      if (size > maxBytes) {
        rejected = true
        const error = new Error(`request body too large (${maxBytes} bytes max)`)
        error.code = 'BODY_TOO_LARGE'
        reject(error)
        return
      }
      raw += String(chunk)
    })
    req.on('end', () => resolve(raw))
    req.on('error', (error) => {
      if (rejected) return
      reject(error)
    })
  })
}

function createMcpServer(options) {
  const {
    host = '127.0.0.1',
    port = 17890,
    mcpPath = '/mcp',
    projectRoot,
    inputs,
    vectorProvider,
    streamOptions,
    indexOnStart = true,
  } = options ?? {}

  if (!projectRoot) throw new Error('createMcpServer: projectRoot is required')
  if (!vectorProvider) throw new Error('createMcpServer: vectorProvider is required (HTTP embeddings)')

  const argusSearch = createArgusSearch({ projectRoot, inputs, vectorProvider, streamOptions })

  let indexing = null
  let indexed = false

const ensureIndexed = async () => {
  if (indexed) return null
  if (indexing) return indexing
  indexing = (async () => {
    try {
      await argusSearch.index()
      indexed = true
      return null
    } catch (error) {
      if (typeof argusSearch?.store?.clear === 'function') {
        argusSearch.store.clear()
      }
      if (typeof argusSearch?.graphStore?.clear === 'function') {
        argusSearch.graphStore.clear()
      }
      throw error
    }
  })().finally(() => {
    indexing = null
  })
  return indexing
}

const callTool = async (name, args) => {
  if (name === 'code_search') {
    await ensureIndexed()
    const results = await argusSearch.search(String(args?.query ?? ''), { topK: clampTopK(args?.topK) })
    return {
      content: [
        {
          type: 'text',
          text: JSON.stringify(results, null, 2),
        },
      ],
    }
  }

  if (name === 'code_open') {
    const filePath = String(args?.filePath ?? '')
    const startLine = Math.max(1, Number(args?.startLine) || 1)
    const endLine = Math.max(startLine, Number(args?.endLine) || startLine + 199)
    const maxChars = Math.max(256, Math.min(200000, Number(args?.maxChars) || 20000))

    const { root, resolved: absPath } = await safeResolveWithinRoot(projectRoot, filePath)
    const content = await fs.readFile(absPath, 'utf8')
    const lines = content.split('\n')
    const slice = lines.slice(startLine - 1, endLine)
    let text = slice.join('\n')
    if (text.length > maxChars) text = text.slice(0, maxChars)

    return {
      content: [
        {
          type: 'text',
          text: `file: ${path.relative(root, absPath)}\nlines: ${startLine}-${endLine}\n\n${text}`,
        },
      ],
    }
  }

  if (name === 'code_reindex') {
    argusSearch.store.clear()
    indexed = false
    await ensureIndexed()
    return { content: [{ type: 'text', text: `reindexed: ${argusSearch.store.size()} vectors` }] }
  }

  throw new Error(`unknown tool: ${name}`)
}

const server = http.createServer(async (req, res) => {

let id = null
try {
  if (req.method === 'GET' && req.url === '/healthz') {
    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ ok: true }))
    return
  }

  if (req.method !== 'POST' || req.url !== mcpPath) {
    res.statusCode = 404
    res.end('not found')
    return
  }

  const raw = await readRequestBody(req)
  const request = raw ? JSON.parse(raw) : null
  id = request?.id ?? null
  const method = String(request?.method ?? '')

  if (!method) {
    toSse(res, jsonRpcError({ id, code: -32600, message: 'invalid request' }))
    return
  }

  if (method === 'initialize') {
    toSse(
      res,
      jsonRpcResult({
        id,
        result: {
          protocolVersion: '2024-11-05',
          serverInfo: { name: '@argus/argus-search', version: '0.1.0' },
          capabilities: { tools: { listChanged: false } },
        },
      }),
    )
    return
  }

  if (method === 'tools/list') {
    toSse(res, jsonRpcResult({ id, result: { tools: toolDefs() } }))
    return
  }

  if (method === 'tools/call') {
    const name = String(request?.params?.name ?? '')
    const args = request?.params?.arguments ?? {}
    const result = await callTool(name, args)
    toSse(res, jsonRpcResult({ id, result }))
    return
  }

  toSse(res, jsonRpcError({ id, code: -32601, message: `method not found: ${method}` }))
} catch (error) {

      const message = error instanceof Error ? error.message : String(error)
      toSse(res, jsonRpcError({ id, code: -32000, message }))
    }
  })

  const start = async () => {
    if (indexOnStart) await ensureIndexed()
    const listenPort = port == null ? 17890 : Number(port)
    await new Promise((resolve) => server.listen(listenPort, host, () => resolve(null)))
    const address = server.address()
    const actualPort = typeof address === 'object' && address ? address.port : port
    return {
      url: `http://${host}:${actualPort}${mcpPath}`,
      close: () => new Promise((resolve) => server.close(() => resolve(null))),
      argusSearch,
    }
  }

  return { start, server, argusSearch }
}

module.exports = { createMcpServer }

