import { type GitLabIntegrationSummary } from "@/lib/gitlab/service";
import { getCachedUserIntegrations } from "@/lib/gitlab/user-integrations-cache";

export type AnalyticsIntegrationScope = GitLabIntegrationSummary[];

export const loadAnalyticsIntegrationScope = async (
  userId: string,
): Promise<AnalyticsIntegrationScope> => getCachedUserIntegrations(userId);

import { execFile } from "node:child_process"
import { mkdtemp, readdir, readFile, rm, stat } from "node:fs/promises"
import os from "node:os"
import path from "node:path"
import { promisify } from "node:util"

import type { GitLabSource } from "@/lib/indexing/contracts"

const execFileAsync = promisify(execFile)

export type RepoWorkspaceMetrics = {
  downloadMs: number
  extractMs: number
  archiveBytes: number
}

export type RepoWorkspace = {
  rootDir: string
  archivePath: string
  metrics: RepoWorkspaceMetrics
  readFile: (relativePath: string) => Promise<Buffer>
  listFiles: () => Promise<string[]>
  cleanup: () => Promise<void>
}

const normalizeRelativePath = (relativePath: string) =>
  relativePath.split(path.sep).join("/")

const ensureWithinRoot = (root: string, value: string) => {
  const resolvedRoot = path.resolve(root)
  const candidate = path.resolve(value)
  const rootWithSep = `${resolvedRoot}${path.sep}`
  if (candidate !== resolvedRoot && !candidate.startsWith(rootWithSep)) {
    throw new Error("Workspace path escapes repository root.")
  }

  return candidate
}

const findExtractedRoot = async (extractDir: string): Promise<string> => {
  const entries = await readdir(extractDir, { withFileTypes: true })
  const directories = entries.filter((entry) => entry.isDirectory())

  if (directories.length === 1) {
    return path.join(extractDir, directories[0].name)
  }

  return extractDir
}

const listRepoFiles = async (root: string): Promise<string[]> => {
  const files: string[] = []

  const walk = async (currentDir: string) => {
    const entries = await readdir(currentDir, { withFileTypes: true })
    for (const entry of entries) {
      const absolutePath = path.join(currentDir, entry.name)
      if (entry.isDirectory()) {
        await walk(absolutePath)
        continue
      }

      if (entry.isFile()) {
        files.push(normalizeRelativePath(path.relative(root, absolutePath)))
      }
    }
  }

  await walk(root)
  return files
}

export const prepareRepoWorkspace = async (args: {
  source: Pick<GitLabSource, "downloadArchive">
  integrationId: string
  sha: string
}): Promise<RepoWorkspace> => {
  const downloadStartedAt = Date.now()
  const { archivePath } = await args.source.downloadArchive({
    integrationId: args.integrationId,
    sha: args.sha,
  })
  const downloadMs = Date.now() - downloadStartedAt

  const archiveStats = await stat(archivePath)
  const extractStartedAt = Date.now()
  const extractDir = await mkdtemp(path.join(os.tmpdir(), "argus-indexer-workspace-"))
  await execFileAsync("tar", ["-xzf", archivePath, "-C", extractDir])
  const repoRoot = await findExtractedRoot(extractDir)
  const extractMs = Date.now() - extractStartedAt

  let cleanedUp = false
  const cleanup = async () => {
    if (cleanedUp) {
      return
    }
    cleanedUp = true

    await rm(extractDir, { recursive: true, force: true }).catch(() => {})
    await rm(path.dirname(archivePath), { recursive: true, force: true }).catch(() => {})
  }

  return {
    rootDir: repoRoot,
    archivePath,
    metrics: {
      downloadMs,
      extractMs,
      archiveBytes: archiveStats.size,
    },
    listFiles: async () => listRepoFiles(repoRoot),
    readFile: async (relativePath: string) => {
      const normalized = relativePath.trim()
      if (!normalized || path.isAbsolute(normalized)) {
        throw new Error("Workspace path escapes repository root.")
      }

      const absolutePath = ensureWithinRoot(repoRoot, path.join(repoRoot, normalized))
      return readFile(absolutePath)
    },
    cleanup,
  }
}

import { describe, expect, test } from "bun:test"

import { parseBoolean, parsePositiveInt, resolveIndexerWorkerConfig } from "@argus/shared-config"

describe("shared config env parsing", () => {
  test("parsePositiveInt keeps fallback for empty/invalid values", () => {
    expect(parsePositiveInt(undefined, 25)).toBe(25)
    expect(parsePositiveInt("", 25)).toBe(25)
    expect(parsePositiveInt("0", 25)).toBe(25)
    expect(parsePositiveInt("-1", 25)).toBe(25)
    expect(parsePositiveInt("nope", 25)).toBe(25)
  })

  test("parsePositiveInt returns parsed positive integers", () => {
    expect(parsePositiveInt("1", 25)).toBe(1)
    expect(parsePositiveInt("300", 25)).toBe(300)
  })

  test("parseBoolean parses known true/false values", () => {
    expect(parseBoolean("1")).toBe(true)
    expect(parseBoolean("true")).toBe(true)
    expect(parseBoolean("yes")).toBe(true)
    expect(parseBoolean("0")).toBe(false)
    expect(parseBoolean("false")).toBe(false)
    expect(parseBoolean("no")).toBe(false)
  })

  test("parseBoolean returns undefined for unknown values", () => {
    expect(parseBoolean(undefined)).toBeUndefined()
    expect(parseBoolean("")).toBeUndefined()
    expect(parseBoolean("on")).toBeUndefined()
    expect(parseBoolean("off")).toBeUndefined()
  })

  test("resolveIndexerWorkerConfig returns parsed worker settings", () => {
    expect(
      resolveIndexerWorkerConfig({
        INDEXER_SERVICE_NAME: " indexer-a ",
        INDEXER_ENVIRONMENT: "production",
        INDEXER_SERVICE_VERSION: "1.2.3",
        INDEXER_LOG_PRETTY: "true",
        INDEXER_BATCH_SIZE: "40",
        INDEXER_POLL_MS: "5000",
        INDEXER_CONTINUOUS: "1",
      }),
    ).toEqual({
      service: "indexer-a",
      environment: "production",
      version: "1.2.3",
      pretty: true,
      batchSize: 40,
      pollIntervalMs: 5000,
      continuous: true,
    })
  })

  test("resolveIndexerWorkerConfig falls back to defaults", () => {
    expect(resolveIndexerWorkerConfig({})).toEqual({
      service: "argus-indexer-worker",
      environment: "development",
      version: undefined,
      pretty: undefined,
      batchSize: 25,
      pollIntervalMs: 30_000,
      continuous: false,
    })
  })
})

import { count, eq } from "drizzle-orm"

import { db } from "@/lib/db"
import { aiDefaultTokenUsage } from "@/lib/db/schema"

const DEFAULT_USAGE_LIMIT = 3

export type DefaultTokenUsageType = "review" | "description"

export type DefaultTokenUsageSummary = {
  limit: number
  used: number
  remaining: number
}

const toSafeInteger = (value: unknown) => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return Math.max(0, Math.floor(value))
  }

  const parsed = Number.parseInt(String(value ?? ""), 10)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return 0
  }
  return parsed
}

export const getDefaultTokenUsageLimit = () => {
  const parsed = Number.parseInt(process.env.AI_DEFAULT_TOKEN_USAGE_LIMIT ?? "", 10)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return DEFAULT_USAGE_LIMIT
  }
  return parsed
}

export const buildDefaultTokenUsageLimitMessage = (limit: number) =>
  `Default AI key limit reached (${limit} review/description runs). Add your own API token in Settings > AI to continue.`

export const getDefaultTokenUsageSummary = async (
  userId: string,
): Promise<DefaultTokenUsageSummary> => {
  const limit = getDefaultTokenUsageLimit()
  if (limit <= 0) {
    return { limit, used: 0, remaining: Number.MAX_SAFE_INTEGER }
  }

  const rows = await db
    .select({ value: count() })
    .from(aiDefaultTokenUsage)
    .where(eq(aiDefaultTokenUsage.userId, userId))

  const used = toSafeInteger(rows[0]?.value)
  return {
    limit,
    used,
    remaining: Math.max(0, limit - used),
  }
}

export const ensureDefaultTokenUsageAvailable = async ({
  userId,
  usesServerToken,
}: {
  userId: string
  usesServerToken: boolean
}) => {
  if (!usesServerToken) {
    return { limited: false as const, summary: null as DefaultTokenUsageSummary | null }
  }

  const summary = await getDefaultTokenUsageSummary(userId)
  if (summary.limit <= 0 || summary.remaining > 0) {
    return { limited: false as const, summary }
  }

  return { limited: true as const, summary }
}

export const consumeDefaultTokenUsage = async ({
  userId,
  usesServerToken,
  requestType,
}: {
  userId: string
  usesServerToken: boolean
  requestType: DefaultTokenUsageType
}) => {
  const availability = await ensureDefaultTokenUsageAvailable({ userId, usesServerToken })
  if (availability.limited || !availability.summary) {
    return availability
  }

  await db.insert(aiDefaultTokenUsage).values({
    userId,
    requestType,
  })

  return {
    limited: false as const,
    summary: {
      ...availability.summary,
      used: availability.summary.used + 1,
      remaining: Math.max(0, availability.summary.remaining - 1),
    },
  }
}

import type { ObservabilityLlmMetrics } from "@/lib/observability/types"

type UsageRecord = {
  promptTokens: number
  completionTokens: number
  totalTokens: number
}

type UsageLikePayload = {
  usage?: {
    prompt_tokens?: unknown
    completion_tokens?: unknown
    total_tokens?: unknown
    promptTokens?: unknown
    completionTokens?: unknown
    totalTokens?: unknown
  } | null
}

const asNonNegativeInt = (value: unknown): number | null => {
  if (typeof value === "number" && Number.isFinite(value) && value >= 0) {
    return Math.floor(value)
  }

  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number.parseInt(value, 10)
    if (Number.isFinite(parsed) && parsed >= 0) {
      return parsed
    }
  }

  return null
}

const toUsd = (value: number) => Number(value.toFixed(8))

const normalizeModelEnvKey = (model: string) =>
  model
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")

const resolveUsdPer1kFromEnv = (args: {
  prefix: string
  model: string | null
}): number | null => {
  const modelKey = args.model ? normalizeModelEnvKey(args.model) : ""
  const modelEnvKey = modelKey ? `${args.prefix}_${modelKey}` : ""
  const rawModelRate = modelEnvKey ? process.env[modelEnvKey] : undefined
  const rawGlobalRate = process.env[args.prefix]
  const rawRate = rawModelRate ?? rawGlobalRate
  if (!rawRate || rawRate.trim().length === 0) {
    return null
  }

  const parsed = Number.parseFloat(rawRate)
  if (!Number.isFinite(parsed) || parsed < 0) {
    return null
  }

  return parsed
}

export const resolveLlmProviderLabel = (apiUrl: string): string => {
  try {
    const hostname = new URL(apiUrl).hostname.trim().toLowerCase()
    if (!hostname) {
      return "openai-compatible"
    }
    if (hostname.includes("openai.com")) {
      return "openai"
    }
    return `openai-compatible:${hostname}`
  } catch {
    return "openai-compatible"
  }
}

export const extractUsageFromOpenAiCompatiblePayload = (payload: unknown): UsageRecord => {
  const usage = (payload as UsageLikePayload | null)?.usage ?? null
  if (!usage || typeof usage !== "object" || Array.isArray(usage)) {
    return {
      promptTokens: 0,
      completionTokens: 0,
      totalTokens: 0,
    }
  }

  const promptTokens =
    asNonNegativeInt(usage.prompt_tokens) ??
    asNonNegativeInt(usage.promptTokens) ??
    0
  const completionTokens =
    asNonNegativeInt(usage.completion_tokens) ??
    asNonNegativeInt(usage.completionTokens) ??
    0
  const totalTokens =
    asNonNegativeInt(usage.total_tokens) ??
    asNonNegativeInt(usage.totalTokens) ??
    promptTokens + completionTokens

  return {
    promptTokens,
    completionTokens,
    totalTokens,
  }
}

export const estimateLlmCostUsd = (args: {
  model: string | null
  promptTokens: number
  completionTokens: number
}): number | null => {
  const promptUsdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_LLM_COST_PROMPT_USD_PER_1K",
    model: args.model,
  })
  const completionUsdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_LLM_COST_COMPLETION_USD_PER_1K",
    model: args.model,
  })

  if (promptUsdPer1k === null && completionUsdPer1k === null) {
    return null
  }

  const promptCost = ((promptUsdPer1k ?? 0) * Math.max(0, args.promptTokens)) / 1_000
  const completionCost = ((completionUsdPer1k ?? 0) * Math.max(0, args.completionTokens)) / 1_000
  return toUsd(promptCost + completionCost)
}

export const estimateEmbeddingCostUsd = (args: {
  model: string | null
  totalTokens: number
}): number | null => {
  const usdPer1k = resolveUsdPer1kFromEnv({
    prefix: "OBS_EMBEDDING_COST_USD_PER_1K",
    model: args.model,
  })
  if (usdPer1k === null) {
    return null
  }

  const totalCost = (usdPer1k * Math.max(0, args.totalTokens)) / 1_000
  return toUsd(totalCost)
}

