const readSource = (relativePath: string) =>
  readFileSync(join(process.cwd(), relativePath), "utf8")

describe("merge request diff lazy loading", () => {
  test("loads merge request diff viewer through dynamic import at route boundary", () => {
    const pageSource = readSource("src/app/(app)/repos/[integrationId]/mrs/[mergeRequestIid]/page.tsx")

    expect(pageSource.includes('import { MergeRequestDiffViewer } from "@/components/merge-request-diff/merge-request-diff-viewer"')).toBe(false)
    expect(pageSource.includes("dynamic(")).toBe(true)
  })

  test("loads markdown renderer lazily in description stream page", () => {
    const streamPageSource = readSource("src/components/merge-request-diff/merge-request-description-stream-page.tsx")

    expect(streamPageSource.includes('import { MergeRequestMarkdownRenderer } from "./merge-request-markdown-renderer"')).toBe(false)
    expect(streamPageSource.includes("dynamic(")).toBe(true)
  })
})

