  token: state.token,
  gitlabInstance: state.gitlabInstance,
  customInstance: state.customInstance,
  projects: state.projects,
  selectedProjectId: state.selectedProjectId,
  mergeRequests: state.mergeRequests,
  selectedMergeRequestId: state.selectedMergeRequestId,
  projectSearchQuery: state.projectSearchQuery,
})
const { trackEvent } = useOnboardingTracking()
const { connectIntegration, getProjectReviewContext, getProjectIntegrationId } = useOnboardingIntegrationConnect({
  gitlabInstance: state.gitlabInstance,
  customInstance: state.customInstance,
  token: state.token,
  setWebhookSetupFeedback: state.setWebhookSetupFeedback,
  trackEvent,
})

const { reviewMode, indexingStatusLabel } = getProjectReviewContext(
  state.selectedProjectId || null,
)

const { handleProjectSelection, handleMergeRequestSelection } =
  useOnboardingSelectionHandlers({
    projects: state.projects,
    mergeRequests: state.mergeRequests,
    selectedProjectId: state.selectedProjectId,
    resolvedGitLabInstance,
    reviewMode,
    queryClient,
    setSelectedProjectId: state.setSelectedProjectId,
    setSelectedMergeRequestId: state.setSelectedMergeRequestId,
    setMergeRequestsError: state.setMergeRequestsError,
    setMergeRequests: state.setMergeRequests,
    mergeRequestsQueryKey,
    loadMergeRequests,
    connectIntegration,
    routePushMrs: () => navigate("/onboarding/mrs", "onboarding_flow"),
    routePrefetchReview: (repoRouteId, mergeRequestIid) => {
      prefetch(
        `/repos/${encodeURIComponent(repoRouteId)}/mrs/${encodeURIComponent(mergeRequestIid)}`,
      )
    },
