const RETRY_BASE_DELAY_MS = 30_000
const RETRY_MAX_DELAY_MS = 60 * 60_000

const normalizeScopeValue = (value: unknown) => String(value ?? "").trim().replace(/\/+$/, "")

const nowDate = () => new Date()

const toCommentBody = (finding: AiReviewFinding) =>
  `${finding.title.trim()}\n\n${finding.body.trim()}`.trim()

export const buildCommentKey = (finding: AiReviewFinding) =>
  buildReviewCommentFeedbackKey({
    file: finding.file,
    side: finding.side,
    line: finding.line,
    title: finding.title,
  })

const getRetryDelayMs = (attempt: number) => {
  const exponent = Math.max(0, attempt - 1)
  return Math.min(RETRY_MAX_DELAY_MS, RETRY_BASE_DELAY_MS * 2 ** exponent)
}

const toCommentPublishState = (
  row: Pick<
    PublicationRow,
    "status" | "attempts" | "lastError" | "gitlabDiscussionId" | "gitlabNoteId" | "updatedAt"
  >,
): CommentPublishState => ({
  status: row.status,
  attempts: row.attempts,
  lastError: row.lastError ?? "",
  discussionId: row.gitlabDiscussionId ?? null,
  noteId: row.gitlabNoteId ?? null,
  updatedAt: row.updatedAt.toISOString(),
})

export const mapCommentPublishByKey = (
  rows: Array<
    Pick<
      PublicationRow,
      | "commentKey"
      | "status"
      | "attempts"
      | "lastError"
      | "gitlabDiscussionId"
      | "gitlabNoteId"
      | "updatedAt"
    >
  >,
): Record<string, CommentPublishState> =>
  Object.fromEntries(rows.map((row) => [row.commentKey, toCommentPublishState(row)]))

export const resolveManagedIntegrationForScope = async ({

  userId,
  instanceUrl,
  projectId,
  integrationId,
}: {
  userId: string
  instanceUrl: string
  projectId: string
  integrationId?: string | null
}) => {

  const normalizedInstanceUrl = normalizeScopeValue(instanceUrl)
  const normalizedProjectId = String(projectId).trim()
  const normalizedIntegrationId = String(integrationId ?? "").trim()
  if (!normalizedInstanceUrl || !normalizedProjectId) {
    return null
  }

  if (normalizedIntegrationId) {
    const rows = await db
      .select({ integration: gitlabIntegrations })
      .from(gitlabIntegrations)
      .innerJoin(
        gitlabIntegrationMemberships,
        and(
          eq(gitlabIntegrationMemberships.integrationId, gitlabIntegrations.id),
          eqGitLabMembershipUserId(userId),
        ),
      )
      .where(
        and(
          eq(gitlabIntegrations.id, normalizedIntegrationId),
          eq(gitlabIntegrations.instanceUrl, normalizedInstanceUrl),
          eq(gitlabIntegrations.projectId, normalizedProjectId),
        ),
      )
      .limit(1)
    return rows[0]?.integration ?? null
  }

  const rows = await db
    .select({ integration: gitlabIntegrations })
    .from(gitlabIntegrations)
    .innerJoin(
      gitlabIntegrationMemberships,
      and(
        eq(gitlabIntegrationMemberships.integrationId, gitlabIntegrations.id),
        eqGitLabMembershipUserId(userId),
      ),
    )
    .where(
      and(
        eq(gitlabIntegrations.instanceUrl, normalizedInstanceUrl),
        eq(gitlabIntegrations.projectId, normalizedProjectId),
      ),
    )
    .limit(1)

  return rows[0]?.integration ?? null
}

