export const processDuePublications = async (
  batchSize: number,
): Promise<PublishSummary> => {
  const claimedRows = await claimDuePublications(Math.max(1, Math.min(batchSize, 200)))
  const summary: PublishSummary = {
    claimed: claimedRows.length,
    succeeded: 0,
    failed: 0,
    dead: 0,
  }

  for (const row of claimedRows) {
    const result = await processClaimedPublication(row)
    if (result.status === "succeeded") {
      summary.succeeded += 1
    } else if (result.status === "failed") {
      summary.failed += 1
    } else {
      summary.dead += 1
    }
  }
  return summary
}

export const processPublicationNow = async ({
  integrationId,
  mergeRequestIid,
  commentKey,
}: {
  integrationId: string
  mergeRequestIid: string
  commentKey: string
}) => {
  const claimed = await claimPendingPublication({
    integrationId,
    mergeRequestIid,
    commentKey,
  })

  if (claimed) {
    await processClaimedPublication(claimed)
  }

  const rows = await findPublicationRowsByKeys({
    integrationId,
    mergeRequestIid,
    commentKeys: [commentKey],
  })
  return mapCommentPublishByKey(rows)[commentKey] ?? null
}

export const removePublicationNow = async ({
  integrationId,
  mergeRequestIid,
  commentKey,
  userId,
}: {
  integrationId: string
  mergeRequestIid: string
  commentKey: string
  userId: string
}) => {
  const rows = await findPublicationRowsByKeys({
    integrationId,
    mergeRequestIid,
    commentKeys: [commentKey],
  })
  const publication = rows[0]
  if (!publication || publication.userId !== userId) {
    return null
  }

  const discussionId = String(publication.gitlabDiscussionId ?? "").trim()
  const noteId = String(publication.gitlabNoteId ?? "").trim()
  if (discussionId && noteId) {
    const resolved = await resolvePostingToken({
      userId,
      instanceUrl: publication.instanceUrl,
      integrationId: publication.integrationId,
    })
    try {
      await deleteMergeRequestDiscussionNote(
        publication.instanceUrl,
        resolved.token,
        publication.projectId,
        publication.mergeRequestIid,
        discussionId,
        noteId,
      )
    } catch (error) {
      if (!(error instanceof GitLabApiError && error.status === 404)) {
        throw error
      }
    }
  }

  await clearPublicationPostedState({
    id: publication.id,
  })

  const refreshedRows = await findPublicationRowsByKeys({
    integrationId,
    mergeRequestIid,
    commentKeys: [commentKey],
  })
  return mapCommentPublishByKey(refreshedRows)[commentKey] ?? null
}

