import { spawn } from "node:child_process"
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs"
import { createServer, Socket } from "node:net"
import { tmpdir } from "node:os"
import { join, resolve } from "node:path"
import { setTimeout as delay } from "node:timers/promises"

const bunExecutable = process.platform === "win32" ? "bun.exe" : "bun"
const cloudflaredExecutable = process.platform === "win32" ? "cloudflared.exe" : "cloudflared"
const rootDir = resolve(process.cwd())

const parseEnvFile = (filePath) => {
  const parsed = {}
  const content = readFileSync(filePath, "utf8")

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim()
    if (!line || line.startsWith("#")) {
      continue
    }

    const normalized = line.startsWith("export ") ? line.slice(7).trim() : line
    const separatorIndex = normalized.indexOf("=")
    if (separatorIndex <= 0) {
      continue
    }

    const key = normalized.slice(0, separatorIndex).trim()
    if (!key) {
      continue
    }

    let value = normalized.slice(separatorIndex + 1).trim()
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1)
    }

    parsed[key] = value
  }

  return parsed
}

const loadMergedEnv = () => {
  const env = { ...process.env }
  const rootEnvPath = resolve(rootDir, ".env")
  const tunnelEnvPath = resolve(rootDir, ".env.tunnel")

  if (existsSync(rootEnvPath)) {
    Object.assign(env, parseEnvFile(rootEnvPath))
  }

  if (existsSync(tunnelEnvPath)) {
    Object.assign(env, parseEnvFile(tunnelEnvPath))
  }

  return env
}

const env = loadMergedEnv()
const tunnelToken = env.CF_TUNNEL_TOKEN_DEV?.trim()

if (!tunnelToken) {
  console.error(
    [
      "[dev:tunnel] missing CF_TUNNEL_TOKEN_DEV.",
      "Create .env.tunnel from .env.tunnel.example and set CF_TUNNEL_TOKEN_DEV.",
    ].join("\n"),
  )
  process.exit(1)
}

const devTunnelUrl = env.DEV_TUNNEL_URL?.trim() || "http://127.0.0.1:3000"
const appUrl = env.BETTER_AUTH_URL?.trim()

if (!appUrl) {
  console.error("[dev:tunnel] missing BETTER_AUTH_URL. Set it in .env.tunnel.")
  process.exit(1)
}

let parsedTunnelUrl
try {
  parsedTunnelUrl = new URL(devTunnelUrl)
} catch {
  console.error(`[dev:tunnel] DEV_TUNNEL_URL must be a valid URL. Received: ${devTunnelUrl}`)
  process.exit(1)
}

if (!/^https?:$/i.test(parsedTunnelUrl.protocol)) {
  console.error(`[dev:tunnel] DEV_TUNNEL_URL must use http or https. Received: ${devTunnelUrl}`)
  process.exit(1)
}

const originHost = parsedTunnelUrl.hostname || "127.0.0.1"
const originPort =
  parsedTunnelUrl.port
    ? Number.parseInt(parsedTunnelUrl.port, 10)
    : parsedTunnelUrl.protocol === "https:"
      ? 443
      : 80

if (!Number.isFinite(originPort) || originPort <= 0) {
  console.error(`[dev:tunnel] DEV_TUNNEL_URL port is invalid. Received: ${devTunnelUrl}`)
  process.exit(1)
}

const children = []
let shuttingDown = false
let tokenFileDir = null

const stopAll = (signal = "SIGTERM") => {
  if (shuttingDown) {
    return
  }
  shuttingDown = true

  if (tokenFileDir) {
    rmSync(tokenFileDir, { recursive: true, force: true })
    tokenFileDir = null
  }

  for (const child of children) {
    if (!child.killed) {
      child.kill(signal)
    }
  }
}

const spawnManaged = ({ name, executable, args, childEnv }) => {
  const child = spawn(executable, args, {
    cwd: rootDir,
    stdio: "inherit",
    env: childEnv,
  })

  child.on("exit", (code, signal) => {
    if (shuttingDown) {
      return
    }

    console.error(
      `[dev:tunnel] ${name} exited ${signal ? `with signal ${signal}` : `with code ${code}`}`,
    )
    stopAll(signal ?? "SIGTERM")
    process.exit(code ?? 1)
  })

  child.on("error", (error) => {
    console.error(`[dev:tunnel] failed to start ${name}:`, error)
    stopAll()
    process.exit(1)
  })

  children.push(child)
  return child
}

const ensurePortAvailable = (port) =>
  new Promise((resolveAvailable, rejectUnavailable) => {
    const server = createServer()

    server.once("error", (error) => {
      if (error && typeof error === "object" && "code" in error && error.code === "EADDRINUSE") {
        rejectUnavailable(
          new Error(`[dev:tunnel] port ${port} is already in use. Stop the existing process and retry.`),
        )
        return
      }

      rejectUnavailable(error)
    })

    server.listen(port, () => {
      server.close(() => resolveAvailable())
    })
  })

const waitForOriginReady = async (host, port, timeoutMs = 60_000) => {
  const startedAt = Date.now()

  while (Date.now() - startedAt < timeoutMs) {
    const opened = await new Promise((resolveOpen) => {
      const socket = new Socket()
      let settled = false

      const finalize = (value) => {
        if (!settled) {
          settled = true
          resolveOpen(value)
        }
      }

      socket.setTimeout(500)
      socket.once("connect", () => {
        socket.destroy()
        finalize(true)
      })
      socket.once("timeout", () => {
        socket.destroy()
        finalize(false)
      })
      socket.once("error", () => finalize(false))
      socket.connect(port, host)
    })

    if (opened) {
      return
    }

    await delay(250)
  }

  throw new Error(`[dev:tunnel] timed out waiting for web origin at ${host}:${port}.`)
}

const run = async () => {
  await ensurePortAvailable(originPort)

  const webEnv = { ...env }
  delete webEnv.CF_TUNNEL_TOKEN_DEV

  const tunnelEnv = { ...env }
  delete tunnelEnv.CF_TUNNEL_TOKEN_DEV

  tokenFileDir = mkdtempSync(join(tmpdir(), "argus-tunnel-"))
  const tokenFilePath = join(tokenFileDir, "token")
  writeFileSync(tokenFilePath, `${tunnelToken}\n`, {
    encoding: "utf8",
    mode: 0o600,
  })

  spawnManaged({
    name: "web",
    executable: bunExecutable,
    args: [
      "run",
      "--cwd",
      "apps/web",
      "dev",
      "--",
      "--webpack",
      "--hostname",
      originHost,
      "--port",
      String(originPort),
    ],
    childEnv: webEnv,
  })

  await waitForOriginReady(originHost, originPort)

  spawnManaged({
    name: "cloudflared",
    executable: cloudflaredExecutable,
    args: ["tunnel", "run", "--token-file", tokenFilePath, "--url", devTunnelUrl],
    childEnv: tunnelEnv,
  })

  console.log(`[dev:tunnel] BETTER_AUTH_URL=${appUrl}`)
  console.log(`[dev:tunnel] DEV_TUNNEL_URL=${devTunnelUrl}`)
}

run().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error))
  stopAll()
  process.exit(1)
})

process.once("SIGINT", () => {
  stopAll("SIGINT")
  process.exit(0)
})

process.once("SIGTERM", () => {
  stopAll("SIGTERM")
  process.exit(0)
})

#![allow(dead_code)]

use std::thread;

use napi::bindgen_prelude::Object;
use napi::{Error, Result};
use napi_derive::napi;

use crate::core::index_engine::{IndexEngine, IndexSink};
use crate::core::stream::{StreamError, StreamQueue};

use super::parse_index_options_core;

#[derive(Debug, Clone)]
struct StreamEmitOptions {
  parse_batches: bool,
  graph_batches: bool,
  vector_batches: bool,
  scip_batches: bool,
  phase_events: bool,
}

#[derive(Debug, Clone)]
struct ParsedStreamOptions {
  high_water_mark: usize,
  emit: StreamEmitOptions,
}

fn apply_hook_batch_overrides(
  index_options: &mut crate::core::index_engine::IndexOptions,
  options: &Object<'_>,
) -> Result<()> {
  let hooks = options.get::<Object<'_>>("hooks")?;
  if let Some(hooks) = hooks.as_ref() {
    if let Some(value) = hooks.get::<u32>("parseBatch")? {
      index_options.parse_batch = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("graphBatch")? {
      index_options.graph_batch = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("vectorBatch")? {
      index_options.vector.batch_size = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("scipBatch")? {
      index_options.scip_batch = value as usize;
    }
  }
  Ok(())
}

fn parse_stream_options(
  options: &crate::core::index_engine::IndexOptions,
  stream: Option<Object<'_>>,
) -> Result<ParsedStreamOptions> {
  let mut high_water_mark = 16usize;
  let mut emit_parse_batches = false;
  let mut emit_graph_batches = options.phases.graph;
  let mut emit_vector_batches = options.phases.vector;
  let mut emit_scip_batches = options.phases.scip;
  let mut emit_phase_events = true;

  if let Some(stream) = stream {
    if let Some(value) = stream.get::<u32>("highWaterMark")? {
      high_water_mark = value.max(1) as usize;
    }
    if let Some(emit) = stream.get::<Object<'_>>("emit")? {
      if let Some(value) = emit.get::<bool>("parseBatches")? {
        emit_parse_batches = value;
      }
      if let Some(value) = emit.get::<bool>("graphBatches")? {
        emit_graph_batches = value;
      }
      if let Some(value) = emit.get::<bool>("vectorBatches")? {
        emit_vector_batches = value;
      }
      if let Some(value) = emit.get::<bool>("scipBatches")? {
        emit_scip_batches = value;
      }
      if let Some(value) = emit.get::<bool>("phaseEvents")? {
        emit_phase_events = value;
      }
    }
  }

  Ok(ParsedStreamOptions {
    high_water_mark,
    emit: StreamEmitOptions {
      parse_batches: emit_parse_batches,
      graph_batches: emit_graph_batches,
      vector_batches: emit_vector_batches,
      scip_batches: emit_scip_batches,
      phase_events: emit_phase_events,
    },
  })
}

struct StreamSink {
  queue: StreamQueue,
  emit: StreamEmitOptions,
}

impl StreamSink {
  fn push_json(&self, value: serde_json::Value) {
    let _ = self.queue.push_blocking(value);
  }
}

impl crate::core::parse::engine::ParseSink for StreamSink {
  fn on_parse_batch_ref(&mut self, batch: &[crate::core::parse::types::CodeChunk]) {
    if !self.emit.parse_batches {
      return;
    }
    match serde_json::to_value(batch) {
      Ok(chunks) => self.push_json(serde_json::json!({ "type": "parse:batch", "chunks": chunks })),
      Err(err) => self.queue.close(Some(err.to_string())),
    }
  }
}

impl crate::core::graph::engine::GraphSink for StreamSink {
  fn on_graph_batch(&mut self, batch: crate::core::graph::types::GraphBatch) {
    if !self.emit.graph_batches {
      return;
    }
    match serde_json::to_value(batch) {
      Ok(value) => self.push_json(serde_json::json!({ "type": "graph:batch", "batch": value })),
      Err(err) => self.queue.close(Some(err.to_string())),
    }
  }
}

impl crate::core::vector::engine::VectorSink for StreamSink {
  fn on_vector_batch(&mut self, batch: crate::core::vector::types::VectorBatch) {
    if !self.emit.vector_batches {
      return;
    }
    match serde_json::to_value(batch) {
      Ok(value) => self.push_json(serde_json::json!({ "type": "vector:batch", "batch": value })),
      Err(err) => self.queue.close(Some(err.to_string())),
    }
  }
}

impl crate::core::scip::engine::ScipSink for StreamSink {
  fn on_scip_batch(&mut self, batch: crate::core::graph::types::GraphBatch) {
    if !self.emit.scip_batches {
      return;
    }
    match serde_json::to_value(batch) {
      Ok(value) => self.push_json(serde_json::json!({ "type": "scip:batch", "batch": value })),
      Err(err) => self.queue.close(Some(err.to_string())),
    }
  }
}

impl IndexSink for StreamSink {
  fn on_event(&mut self, event: crate::core::index_engine::IndexEvent) {
    if !self.emit.phase_events {
      return;
    }
    self.push_json(event.to_json());
  }
}

#[napi]
pub struct IndexStreamHandle {
  queue: StreamQueue,
}

#[napi]
impl IndexStreamHandle {
  #[napi]
  pub fn cancel(&self) {
    self.queue.cancel();
  }

  #[napi]
  pub async fn next(&self) -> Result<Option<serde_json::Value>> {
    let queue = self.queue.clone();
    let next = napi::tokio::task::spawn_blocking(move || queue.next_blocking())
      .await
      .map_err(|err| Error::from_reason(format!("stream next task failed: {err}")))??;
    Ok(next)
  }
}

impl Drop for IndexStreamHandle {
  fn drop(&mut self) {
    self.queue.cancel();
  }
}

#[napi(js_name = "createIndexStream")]

pub fn create_index_stream(
  options: Object<'_>,
  stream: Option<Object<'_>>,
) -> Result<IndexStreamHandle> {
  let mut index_options = parse_index_options_core(&options)?;
  apply_hook_batch_overrides(&mut index_options, &options)?;
  let stream_options = parse_stream_options(&index_options, stream)?;

  if stream_options.emit.vector_batches {
    index_options.vector.include_chunk = true;
  }

  let queue = StreamQueue::new(stream_options.high_water_mark);
  let cancel = queue.cancel_token();
  let mut sink = StreamSink {
    queue: queue.clone(),
    emit: stream_options.emit,
  };
  let close_queue = queue.clone();

  thread::spawn(move || {
    let engine = IndexEngine::new(index_options);
    let result = engine.run(&mut sink, &cancel);
    match result {
      Ok(_) => close_queue.close(None),
      Err(err) => close_queue.close(Some(err.to_string())),
    }
  });

  Ok(IndexStreamHandle { queue })
}

impl From<StreamError> for Error {
  fn from(value: StreamError) -> Self {
    match value {
      StreamError::Cancelled => Error::from_reason("cancelled"),
      StreamError::Closed => Error::from_reason("closed"),
      StreamError::Fatal(message) => Error::from_reason(message),
    }
  }
}

