use std::path::{Path, PathBuf};

use super::cli_provider::ScipIndexerCommand;
const DEFAULT_CLANG_DOCKER_IMAGE: &str = "sourcegraph/scip-clang:latest";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ScipLanguage {
  Typescript,
  Python,
  Cpp,
  Java,
  CSharp,
}

impl ScipLanguage {
  // Intentionally no `as_str()` for now; the CLI commands already carry a `language` label.
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum WorkspaceMode {
  #[default]
  Auto,
  Yarn,
  Pnpm,
  Npm,
}

#[derive(Debug, Clone, Default)]
pub struct ScipTypescriptConfig {
  pub workspaces: WorkspaceMode,
  pub infer_tsconfig: Option<bool>,
}

#[derive(Debug, Clone, Default)]
pub struct ScipPythonConfig {
  pub project_name: Option<String>,
  pub virtual_env: Option<String>,
}

#[derive(Debug, Clone, Default)]
pub struct ScipClangConfig {
  pub compile_commands_path: Option<PathBuf>,
  pub use_docker: Option<bool>,
  pub docker_image: Option<String>,
}

#[derive(Debug, Clone, Default)]
pub struct ScipJavaConfig {
  pub enabled: bool,
  pub command: Option<String>,
  pub args: Vec<String>,
}

#[derive(Debug, Clone, Default)]
pub struct ScipCSharpConfig {
  pub enabled: bool,
  pub command: Option<String>,
  pub args: Vec<String>,
}

#[derive(Debug, Clone, Default)]
pub struct ScipIndexerConfig {
  pub typescript: ScipTypescriptConfig,
  pub python: ScipPythonConfig,
  pub clang: ScipClangConfig,
  pub java: ScipJavaConfig,
  pub csharp: ScipCSharpConfig,
}

pub fn detect_languages(files: &[String]) -> Vec<ScipLanguage> {
  let mut has_typescript = false;
  let mut has_python = false;
  let mut has_cpp = false;
  let mut has_java = false;
  let mut has_csharp = false;

  for file in files {
    let Some(ext) = Path::new(file).extension().and_then(|value| value.to_str()) else {
      continue;
    };
    match ext.to_ascii_lowercase().as_str() {
      "ts" | "tsx" | "js" | "jsx" => has_typescript = true,
      "py" => has_python = true,
      "cpp" | "hpp" | "c" | "h" | "cc" | "cxx" => has_cpp = true,
      "java" => has_java = true,
      "cs" | "csx" => has_csharp = true,
      _ => {}
    }
  }

  let mut languages = Vec::new();
  if has_typescript {
    languages.push(ScipLanguage::Typescript);
  }
  if has_python {
    languages.push(ScipLanguage::Python);
  }
  if has_cpp {
    languages.push(ScipLanguage::Cpp);
  }
  if has_java {
    languages.push(ScipLanguage::Java);
  }
  if has_csharp {
    languages.push(ScipLanguage::CSharp);
  }

  languages
}

pub fn default_indexer_commands_with_config(
  project_root: &Path,
  files: &[String],
  config: &ScipIndexerConfig,
) -> Vec<ScipIndexerCommand> {
  let mut commands = Vec::new();
  let languages = detect_languages(files);

  for language in languages {
    match language {
      ScipLanguage::Typescript => {
        commands.push(build_typescript_indexer(project_root, &config.typescript));
      }
      ScipLanguage::Python => {
        commands.push(build_python_indexer(project_root, &config.python));
      }
      ScipLanguage::Cpp => {
        if let Some(compile_commands) = resolve_compile_commands(project_root, &config.clang) {
          commands.push(build_clang_indexer(
            project_root,
            &compile_commands,
            &config.clang,
          ));
        }
      }
      ScipLanguage::Java => {
        if config.java.enabled {
          commands.push(build_java_indexer(project_root, &config.java));
        }
      }
      ScipLanguage::CSharp => {
        if config.csharp.enabled {
          commands.push(build_csharp_indexer(project_root, &config.csharp));
        }
      }
    }
  }

  commands
}

fn build_typescript_indexer(
  project_root: &Path,
  config: &ScipTypescriptConfig,
) -> ScipIndexerCommand {
  let mut command = ScipIndexerCommand::new("typescript", "npx");
  command.args = vec![
    "@sourcegraph/scip-typescript".to_string(),
    "index".to_string(),
    "--output".to_string(),
    "{output}".to_string(),
    "--cwd".to_string(),
    "{project_root}".to_string(),
  ];

  let infer_tsconfig = config
    .infer_tsconfig
    .unwrap_or_else(|| find_tsconfig(project_root).is_none());
  if infer_tsconfig {
    command.args.push("--infer-tsconfig".to_string());
  }

  if let Some(workspaces) = resolve_workspace_arg(project_root, config.workspaces) {
    command.args.push(workspaces.to_string());
  }

  command
}

fn build_python_indexer(project_root: &Path, config: &ScipPythonConfig) -> ScipIndexerCommand {
  let mut command = ScipIndexerCommand::new("python", "npx");
  let project_name = config
    .project_name
    .clone()
    .or_else(|| {
      project_root
        .file_name()
        .and_then(|value| value.to_str())
        .map(|value| value.to_string())
    })
    .unwrap_or_else(|| "project".to_string());

  command.args = vec![
    "@sourcegraph/scip-python".to_string(),
    "index".to_string(),
    "{project_root}".to_string(),
    "--project-name".to_string(),
    project_name.to_string(),
    "--output".to_string(),
    "{output}".to_string(),
  ];

  if let Some(virtual_env) = resolve_virtual_env(config) {
    command.args.push("--environment".to_string());
    command.args.push(virtual_env);
  }

  command
}

fn build_clang_indexer(
  project_root: &Path,
  compile_commands: &Path,
  config: &ScipClangConfig,
) -> ScipIndexerCommand {
  let use_docker = config.use_docker.unwrap_or(false);
  if use_docker {
    return build_clang_docker_indexer(project_root, compile_commands, config);
  }

  let mut command = ScipIndexerCommand::new("cpp", "scip-clang");
  command.args = vec![
    "--compdb-path".to_string(),
    compile_commands.to_string_lossy().to_string(),
    "--output".to_string(),
    "{output}".to_string(),
  ];
  command
}

fn find_tsconfig(project_root: &Path) -> Option<PathBuf> {
  let candidates = [
    project_root.join("tsconfig.json"),
    project_root.join("tsconfig.build.json"),
    project_root.join("jsconfig.json"),
  ];

  candidates.into_iter().find(|candidate| candidate.exists())
}

fn resolve_workspace_arg(project_root: &Path, mode: WorkspaceMode) -> Option<&'static str> {
  match mode {
    WorkspaceMode::Yarn => Some("--yarn-workspaces"),
    WorkspaceMode::Pnpm => Some("--pnpm-workspaces"),
    WorkspaceMode::Npm => None,
    WorkspaceMode::Auto => {
      if project_root.join("yarn.lock").exists() {
        return Some("--yarn-workspaces");
      }
      if project_root.join("pnpm-lock.yaml").exists() {
        return Some("--pnpm-workspaces");
      }
      None
    }
  }
}

fn resolve_virtual_env(config: &ScipPythonConfig) -> Option<String> {
  if let Some(value) = config.virtual_env.clone() {
    if !value.is_empty() {
      return Some(value);
    }
  }
  if let Ok(value) = std::env::var("VIRTUAL_ENV") {
    if !value.is_empty() {
      return Some(value);
    }
  }
  None
}

fn resolve_compile_commands(project_root: &Path, config: &ScipClangConfig) -> Option<PathBuf> {
  if let Some(path) = config.compile_commands_path.clone() {
    return Some(path);
  }
  let candidates = [
    project_root.join("compile_commands.json"),
    project_root.join("build").join("compile_commands.json"),
  ];

  candidates.into_iter().find(|candidate| candidate.exists())
}

fn build_clang_docker_indexer(
  project_root: &Path,
  compile_commands: &Path,
  config: &ScipClangConfig,
) -> ScipIndexerCommand {
  let docker_image = normalize_docker_image(config.docker_image.as_deref());
  let relative_compdb = compile_commands
    .strip_prefix(project_root)
    .unwrap_or(compile_commands)
    .to_string_lossy()
    .replace('\\', "/");

  let mut command = ScipIndexerCommand::new("cpp", "docker");
  command.args = vec![
    "run".to_string(),
    "--rm".to_string(),
    "-v".to_string(),
    "{project_root}:/workspace".to_string(),
    "-v".to_string(),
    "{output}:/output/index.scip".to_string(),
    "-w".to_string(),
    "/workspace".to_string(),
    docker_image,
    "--compdb-path".to_string(),
    format!("/workspace/{relative_compdb}"),
    "--output".to_string(),
    "/output/index.scip".to_string(),
  ];
  command
}

fn build_java_indexer(_project_root: &Path, config: &ScipJavaConfig) -> ScipIndexerCommand {
  let command_bin = config.command.clone().unwrap_or_else(|| "npx".to_string());
  let mut command = ScipIndexerCommand::new("java", command_bin);
  command.args = vec![
    "@sourcegraph/scip-java".to_string(),
    "index".to_string(),
    "--output".to_string(),
    "{output}".to_string(),
    "--cwd".to_string(),
    "{project_root}".to_string(),
  ];
  if !config.args.is_empty() {
    command.args.extend(config.args.clone());
  }
  command
}

fn build_csharp_indexer(_project_root: &Path, config: &ScipCSharpConfig) -> ScipIndexerCommand {
  let command_bin = config
    .command
    .clone()
    .unwrap_or_else(|| "scip-dotnet".to_string());
  let mut command = ScipIndexerCommand::new("csharp", command_bin);
  command.args = vec![
    "index".to_string(),
    "--output".to_string(),
    "{output}".to_string(),
  ];
  if !config.args.is_empty() {
    command.args.extend(config.args.clone());
  }
  command
}

fn normalize_docker_image(image: Option<&str>) -> String {
  let Some(raw) = image.map(str::trim).filter(|value| !value.is_empty()) else {
    return DEFAULT_CLANG_DOCKER_IMAGE.to_string();
  };
  if is_valid_docker_image(raw) {
    raw.to_string()
  } else {
    DEFAULT_CLANG_DOCKER_IMAGE.to_string()
  }
}

fn is_valid_docker_image(value: &str) -> bool {
  if value.len() > 255 {
    return false;
  }
  if value.starts_with('-')
    || value.starts_with('/')
    || value.ends_with('/')
    || value.contains("//")
    || value.contains("..")
  {
    return false;
  }
  value
    .chars()
    .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-' | '/' | ':' | '@'))
}

