        ..ScipCSharpConfig::default()
      },
      ..ScipIndexerConfig::default()
    };
    let commands = default_indexer_commands_with_config(temp.path(), &files, &config);
    assert!(commands.iter().any(|cmd| cmd.language == "java"));
    assert!(commands.iter().any(|cmd| cmd.language == "csharp"));
    Ok(())
  }
}

