pub struct KiteCodeStore {
  db: SingleFileDB,
  checkpoint_on_finish: bool,
  checkpoint_threshold: f64,
  prop_id: PropKeyId,
  prop_kind: PropKeyId,
  prop_name: PropKeyId,
  prop_file_path: PropKeyId,
  prop_language: PropKeyId,
  prop_range: PropKeyId,
  prop_sources: PropKeyId,
  prop_metadata: PropKeyId,
  prop_chunk: PropKeyId,
  prop_embedding: PropKeyId,
}

impl KiteCodeStore {
  fn open_db_with_wal_fallback(
    path: &Path,
    read_only: bool,
    create_if_missing: bool,
    checkpoint_threshold: f64,
  ) -> Result<SingleFileDB, KiteStoreError> {
    let open_with = |wal_size: usize| {
      let mut options = SingleFileOpenOptions::new()
        .read_only(read_only)
        .create_if_missing(create_if_missing)
        .wal_size(wal_size);
      if !read_only {
        // `ci` performs a deterministic blocking checkpoint at the end of each
        // indexing pass when enabled by policy; keep DB-level auto-checkpoint
        // disabled here to avoid redundant checkpointing behavior.
        options = options
          .auto_checkpoint(false)
          .checkpoint_threshold(checkpoint_threshold)
          .background_checkpoint(false);
      }
      if read_only {
        options = options.create_if_missing(false);
      }
      open_single_file(path, options)
    };

    match open_with(KITEDB_WAL_SIZE_BYTES) {
      Ok(db) => Ok(db),
      Err(primary) => match open_with(KITEDB_LEGACY_WAL_SIZE_BYTES) {
        Ok(db) => Ok(db),
        Err(_) => Err(primary.into()),
      },
    }
  }

pub fn open(options: KiteStoreOptions) -> Result<Self, KiteStoreError> {
  if options.clear {
    let _ = fs::remove_file(&options.path);
  }

  if let Some(parent) = options.path.parent() {
    fs::create_dir_all(parent)?;
  }

  let checkpoint_threshold = options.checkpoint_threshold.clamp(0.0, 1.0);
  let db = Self::open_db_with_wal_fallback(&options.path, false, true, checkpoint_threshold)?;
  db.begin_bulk()?;

  let prop_id = db.define_propkey("ci_id")?;
  let prop_kind = db.define_propkey("ci_kind")?;
  let prop_name = db.define_propkey("ci_name")?;
  let prop_file_path = db.define_propkey("ci_file_path")?;
  let prop_language = db.define_propkey("ci_language")?;
  let prop_range = db.define_propkey("ci_range_json")?;
  let prop_sources = db.define_propkey("ci_sources_json")?;
  let prop_metadata = db.define_propkey("ci_metadata_json")?;
  let prop_chunk = db.define_propkey("ci_chunk_json")?;
  let prop_embedding = db.define_propkey("embedding")?;

  Ok(Self {
    db,
    checkpoint_on_finish: options.checkpoint_on_finish,
    checkpoint_threshold,
    prop_id,
    prop_kind,
    prop_name,
    prop_file_path,
    prop_language,
    prop_range,
    prop_sources,
    prop_metadata,
    prop_chunk,
    prop_embedding,
  })
}

pub fn open_readonly(path: PathBuf) -> Result<Self, KiteStoreError> {
  let db = Self::open_db_with_wal_fallback(&path, true, false, 0.5)?;

  fn require_prop(db: &SingleFileDB, name: &str) -> Result<PropKeyId, KiteStoreError> {
    db.propkey_id(name).ok_or_else(|| {
      KiteStoreError::Kite(KiteError::InvalidSchema(
        format!("missing required propkey: {name}").into(),
      ))
    })
  }

  let prop_id = require_prop(&db, "ci_id")?;
  let prop_kind = require_prop(&db, "ci_kind")?;
  let prop_name = require_prop(&db, "ci_name")?;
  let prop_file_path = require_prop(&db, "ci_file_path")?;
  let prop_language = require_prop(&db, "ci_language")?;
  let prop_range = require_prop(&db, "ci_range_json")?;
  let prop_sources = require_prop(&db, "ci_sources_json")?;
  let prop_metadata = require_prop(&db, "ci_metadata_json")?;
  let prop_chunk = require_prop(&db, "ci_chunk_json")?;
  let prop_embedding = require_prop(&db, "embedding")?;

  Ok(Self {
    db,
    checkpoint_on_finish: false,
    checkpoint_threshold: 0.5,
    prop_id,
    prop_kind,
    prop_name,
    prop_file_path,
    prop_language,
    prop_range,
    prop_sources,
    prop_metadata,
    prop_chunk,
    prop_embedding,
  })
}

pub fn commit(self) -> Result<(), KiteStoreError> {
  let mut committed = false;
  if self.db.has_transaction() {
    self.db.commit()?;
    committed = true;
  }
  if committed
    && self.checkpoint_on_finish
    && self.db.should_checkpoint(self.checkpoint_threshold)
  {
    self.db.checkpoint()?;
  }
  Ok(())
}

pub fn rollback(&self) -> Result<(), KiteStoreError> {
  if self.db.has_transaction() {
    self.db.rollback()?;
  }
  Ok(())
}

fn key_for(id: &str) -> String {
  format!("{KEY_PREFIX}{id}")
}

fn node_id_for_ci_id(&self, ci_id: &str) -> Option<NodeId> {
  self.db.node_by_key(&Self::key_for(ci_id))
}

#[cfg(test)]
pub fn has_ci_id(&self, ci_id: &str) -> bool {
  self.node_id_for_ci_id(ci_id).is_some()
}

pub fn delete_ci_ids<I, S>(&self, ids: I) -> Result<usize, KiteStoreError>
where
  I: IntoIterator<Item = S>,
  S: AsRef<str>,
{
  let mut removed = 0usize;
  for id in ids {
    let Some(node_id) = self.node_id_for_ci_id(id.as_ref()) else {
      continue;
    };
    self.db.delete_node(node_id)?;
    removed = removed.saturating_add(1);
  }
  Ok(removed)
}

fn tracked_ids_by_file(&self) -> HashMap<String, HashSet<String>> {
  let mut out: HashMap<String, HashSet<String>> = HashMap::new();
  for node_id in self.db.iter_nodes() {
    let Some(PropValue::String(file_path)) = self.db.node_prop(node_id, self.prop_file_path)
    else {
      continue;
    };
    let Some(PropValue::String(ci_id)) = self.db.node_prop(node_id, self.prop_id) else {
      continue;
    };
    out.entry(file_path).or_default().insert(ci_id);
  }
  out
}

fn etype_id(&self, edge_type: &str) -> Option<ETypeId> {
