}

fn upsert_node_by_key(&self, key: &str) -> Result<NodeId, KiteStoreError> {
  if let Some(node_id) = self.db.node_by_key(key) {
    return Ok(node_id);
  }
  Ok(self.db.create_node(Some(key))?)
}

fn set_opt_string_prop(
  &self,
  node_id: NodeId,
  prop_key_id: PropKeyId,
  value: Option<&str>,
) -> Result<(), KiteStoreError> {
  if let Some(value) = value {
    self
      .db
      .set_node_prop(node_id, prop_key_id, PropValue::String(value.to_string()))?;
  }
  Ok(())
}

fn set_json_prop<T: serde::Serialize>(
  &self,
  node_id: NodeId,
  prop_key_id: PropKeyId,
  value: &T,
) -> Result<(), KiteStoreError> {
  let json = serde_json::to_string(value)?;
  self
    .db
    .set_node_prop(node_id, prop_key_id, PropValue::String(json))?;
  Ok(())
}

fn upsert_graph_node(&self, node: &GraphNodeRecord) -> Result<NodeId, KiteStoreError> {
  let key = Self::key_for(&node.id);
  let node_id = self.upsert_node_by_key(&key)?;

  self
    .db
    .set_node_prop(node_id, self.prop_id, PropValue::String(node.id.clone()))?;
  self.db.set_node_prop(
    node_id,
    self.prop_kind,
    PropValue::String(node.kind.clone()),
  )?;

  self.set_opt_string_prop(node_id, self.prop_name, node.name.as_deref())?;
  self.set_opt_string_prop(node_id, self.prop_file_path, node.file_path.as_deref())?;
  self.set_opt_string_prop(node_id, self.prop_language, node.language.as_deref())?;

  if let Some(range) = node.range {
    self.set_json_prop(node_id, self.prop_range, &range)?;
  }

  self.set_json_prop(node_id, self.prop_sources, &node.sources)?;

  if let Some(meta) = &node.metadata {
    self.db.set_node_prop(
      node_id,
      self.prop_metadata,
      PropValue::String(serde_json::to_string(meta)?),
    )?;
  }

  Ok(node_id)
}

fn upsert_chunk_node(&self, chunk: &CodeChunk) -> Result<NodeId, KiteStoreError> {
  let key = Self::key_for(&chunk.id);
  let node_id = self.upsert_node_by_key(&key)?;

  self
    .db
    .set_node_prop(node_id, self.prop_id, PropValue::String(chunk.id.clone()))?;
  self.db.set_node_prop(
    node_id,
    self.prop_kind,
    PropValue::String(chunk.kind.clone()),
  )?;

  self.set_opt_string_prop(node_id, self.prop_name, chunk.name.as_deref())?;
  self.set_opt_string_prop(node_id, self.prop_file_path, Some(&chunk.file_path))?;
  self.set_opt_string_prop(node_id, self.prop_language, Some(&chunk.language))?;
  self.set_json_prop(node_id, self.prop_range, &chunk.range)?;

  if let Some(meta) = &chunk.metadata {
    self.db.set_node_prop(
      node_id,
      self.prop_metadata,
      PropValue::String(serde_json::to_string(meta)?),
    )?;
  }

  Ok(node_id)
}

pub fn upsert_graph_batch(&self, batch: GraphBatch) -> Result<(), KiteStoreError> {
  for node in &batch.nodes {
    let _ = self.upsert_graph_node(node)?;
  }

  for edge in &batch.edges {
    let src_key = Self::key_for(&edge.source_id);
    let dst_key = Self::key_for(&edge.target_id);
    let src_id = self.upsert_node_by_key(&src_key)?;
    let dst_id = self.upsert_node_by_key(&dst_key)?;

    let etype = self.db.define_etype(&edge.edge_type)?;
    self.db.add_edge(src_id, etype, dst_id)?;
  }

  Ok(())
}

pub fn upsert_vector_batch(&self, batch: VectorBatch) -> Result<(), KiteStoreError> {
  for record in &batch {
    let node_id = if let Some(chunk) = &record.chunk {
      self.upsert_chunk_node(chunk)?
    } else {
      let key = Self::key_for(&record.chunk_id);
      let node_id = self.upsert_node_by_key(&key)?;
      self.db.set_node_prop(
        node_id,
        self.prop_id,
        PropValue::String(record.chunk_id.clone()),
      )?;
      self.set_opt_string_prop(node_id, self.prop_file_path, Some(&record.file_path))?;
      node_id
    };

    if let Some(meta) = &record.metadata {
      self.db.set_node_prop(
        node_id,
        self.prop_metadata,
        PropValue::String(serde_json::to_string(meta)?),
      )?;
    }

    if let Some(chunk) = &record.chunk {
      // Optional, can be large; still useful for preview without file IO.
      self.set_json_prop(node_id, self.prop_chunk, chunk)?;
    }

    let sanitized = sanitize_embedding_vector(&record.embedding);
    if sanitized.is_empty() {
      continue;
    }
    self
      .db
      .set_node_vector(node_id, self.prop_embedding, &sanitized)?;
  }
  Ok(())
}

fn normalize(v: &[f32]) -> Vec<f32> {
  let mut out = v.to_vec();
  let mut sum_sq = 0.0_f32;
  for x in &out {
    sum_sq += x * x;
  }
  let norm = sum_sq.sqrt().max(1e-12);
  for x in &mut out {
    *x /= norm;
  }
  out
}

pub fn search_by_embedding(

  &self,
  query_embedding: &[f32],
  top_k: usize,
) -> Result<Vec<KiteSearchHit>, KiteStoreError> {
  let query = Self::normalize(query_embedding);
  if query.is_empty() {
    return Ok(Vec::new());
  }
  let k = top_k.clamp(1, 50);

  #[derive(Debug)]
  struct ScoredNode {
    score: f32,
    node_id: NodeId,
  }

  impl PartialEq for ScoredNode {
    fn eq(&self, other: &Self) -> bool {
      self.cmp(other) == Ordering::Equal
    }
  }
  impl Eq for ScoredNode {}
  impl PartialOrd for ScoredNode {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
      Some(self.cmp(other))
    }
  }
  impl Ord for ScoredNode {
    fn cmp(&self, other: &Self) -> Ordering {
      // max-heap by score
      self
        .score
        .total_cmp(&other.score)
        .then_with(|| self.node_id.cmp(&other.node_id))
    }
  }

  let mut heap = BinaryHeap::<ScoredNode>::new();

  for node_id in self.db.iter_nodes() {
    let Some(vector) = self.db.node_vector(node_id, self.prop_embedding) else {
      continue;
    };
    if vector.is_empty() {
      continue;
    }
    let vector = Self::normalize(&vector);
    if vector.len() != query.len() {
      continue;
    }
    let mut score = 0.0_f32;
    for idx in 0..query.len() {
      score += query[idx] * vector[idx];
    }
    heap.push(ScoredNode { score, node_id });
  }

  let mut out = Vec::with_capacity(k);

  for _ in 0..k {
    let Some(item) = heap.pop() else { break };
    let chunk_id = match self.db.node_prop(item.node_id, self.prop_id) {
      Some(PropValue::String(value)) => value,
      _ => continue,
    };
    let file_path = match self.db.node_prop(item.node_id, self.prop_file_path) {
      Some(PropValue::String(value)) => Some(value),
      _ => None,
    };
    let range_json = match self.db.node_prop(item.node_id, self.prop_range) {
      Some(PropValue::String(value)) => Some(value),
      _ => None,
    };
    out.push(KiteSearchHit {
      score: item.score,
      chunk_id,
      file_path,
      range_json,
      content: None,
    });
  }

  Ok(out)
}

