pub fn graph_neighbors(
  &self,
  node_id: &str,
  edge_type: &str,
  direction: &str,
  limit: usize,
) -> Result<Vec<KiteGraphNeighbor>, KiteStoreError> {
  let Some(node) = self.node_id_for_ci_id(node_id) else {
    return Ok(Vec::new());
  };
  let Some(etype) = self.etype_id(edge_type) else {
    return Ok(Vec::new());
  };

  let mut neighbors = match direction.to_lowercase().as_str() {
    "in" | "incoming" => self.db.in_neighbors(node, etype),
    "out" | "outgoing" => self.db.out_neighbors(node, etype),
    _ => return Ok(Vec::new()),
  };

  if neighbors.is_empty() {
    return Ok(Vec::new());
  }

  let cap = limit.clamp(1, 200);
  if neighbors.len() > cap {
    neighbors.truncate(cap);
  }

  let mut out = Vec::with_capacity(neighbors.len());
  for neighbor_id in neighbors {
    let id = match self.db.node_prop(neighbor_id, self.prop_id) {
      Some(PropValue::String(value)) => value,
      _ => continue,
    };
    let kind = match self.db.node_prop(neighbor_id, self.prop_kind) {
      Some(PropValue::String(value)) => Some(value),
      _ => None,
    };
    let name = match self.db.node_prop(neighbor_id, self.prop_name) {
      Some(PropValue::String(value)) => Some(value),
      _ => None,
    };
    let file_path = match self.db.node_prop(neighbor_id, self.prop_file_path) {
      Some(PropValue::String(value)) => Some(value),
      _ => None,
    };
    let range_json = match self.db.node_prop(neighbor_id, self.prop_range) {
      Some(PropValue::String(value)) => Some(value),
      _ => None,
    };
    out.push(KiteGraphNeighbor {
      id,
      kind,
      name,
      file_path,
      range_json,
    });
  }

  Ok(out)
}

pub fn find_nodes_by_name(
  &self,
  name: &str,
  limit: usize,
) -> Result<Vec<KiteGraphNeighbor>, KiteStoreError> {
  let query = name.trim();

if query.is_empty() {
  return Ok(Vec::new());
}

fn build_neighbor(store: &KiteCodeStore, node_id: NodeId) -> Option<KiteGraphNeighbor> {
  let id = match store.db.node_prop(node_id, store.prop_id) {
    Some(PropValue::String(value)) => value,
    _ => return None,
  };
  let kind = match store.db.node_prop(node_id, store.prop_kind) {
    Some(PropValue::String(value)) => Some(value),
    _ => None,
  };
  let name = match store.db.node_prop(node_id, store.prop_name) {
    Some(PropValue::String(value)) => Some(value),
    _ => None,
  };
  let file_path = match store.db.node_prop(node_id, store.prop_file_path) {
    Some(PropValue::String(value)) => Some(value),
    _ => None,
  };
  let range_json = match store.db.node_prop(node_id, store.prop_range) {
    Some(PropValue::String(value)) => Some(value),
    _ => None,
  };

  Some(KiteGraphNeighbor {
    id,
    kind,
    name,
    file_path,
    range_json,
  })
}

let cap = limit.clamp(1, 200);

// Pass 1: exact match (case-sensitive).
let mut out = Vec::new();
for node_id in self.db.iter_nodes() {
  if out.len() >= cap {
    break;
  }
  let stored_name = match self.db.node_prop(node_id, self.prop_name) {
    Some(PropValue::String(value)) => value,
    _ => continue,
  };
  if stored_name != query {
    continue;
  }
  if let Some(neighbor) = build_neighbor(self, node_id) {
    out.push(neighbor);
  }
}

  if !out.is_empty() {
    return Ok(out);
  }

  // Pass 2: exact match (case-insensitive).
  let query_lower = query.to_lowercase();
  for node_id in self.db.iter_nodes() {
    if out.len() >= cap {
      break;
    }
    let stored_name = match self.db.node_prop(node_id, self.prop_name) {
      Some(PropValue::String(value)) => value,
      _ => continue,
    };
    if stored_name.to_lowercase() != query_lower {
      continue;
    }
    if let Some(neighbor) = build_neighbor(self, node_id) {
      out.push(neighbor);
    }
  }

  Ok(out)
}

pub fn locate_by_position(
  &self,
  file_path: &str,
  position: Position,
  options: KiteLocateOptions,
) -> Result<Vec<KiteLocateHit>, KiteStoreError> {
  fn contains(range: Range, position: Position) -> bool {
    if position.row < range.start.row {
      return false;
    }
    if position.row > range.end.row {
      return false;
    }
    if position.row == range.start.row && position.column < range.start.column {
      return false;
    }
    // Treat end as exclusive (tree-sitter end_position semantics).
    if position.row == range.end.row && position.column >= range.end.column {
      return false;
    }
    true
  }

  fn span_size(range: Range) -> u64 {
    let rows = range.end.row.saturating_sub(range.start.row) as u64;
    let cols = range.end.column.saturating_sub(range.start.column) as u64;
    rows.saturating_mul(1_000_000).saturating_add(cols)
  }

  let cap = options.limit.clamp(1, 50);

let include = options.include_kinds;
let exclude = options.exclude_kinds;
let prefer = options.prefer_kinds;

let mut matches: Vec<(u64, KiteLocateHit)> = Vec::new();

for node_id in self.db.iter_nodes() {
  let Some(PropValue::String(node_file_path)) = self.db.node_prop(node_id, self.prop_file_path)
  else {
    continue;
  };
  if node_file_path != file_path {
    continue;
  }

  let kind = match self.db.node_prop(node_id, self.prop_kind) {
    Some(PropValue::String(value)) => Some(value),
    _ => None,
  };
  if !include.is_empty() {
    let Some(kind_value) = kind.as_deref() else {
      continue;
    };
    if !include.iter().any(|k| k == kind_value) {
      continue;
    }
  }
  if !exclude.is_empty() {
    if let Some(kind_value) = kind.as_deref() {
      if exclude.iter().any(|k| k == kind_value) {
        continue;
      }
    }
  }

  let Some(PropValue::String(range_json)) = self.db.node_prop(node_id, self.prop_range) else {
    continue;
  };
  let range: Range = serde_json::from_str(&range_json)?;
  if !contains(range, position) {
    continue;
  }

  let id = match self.db.node_prop(node_id, self.prop_id) {
    Some(PropValue::String(value)) => value,
    _ => continue,
  };
  let name = match self.db.node_prop(node_id, self.prop_name) {
    Some(PropValue::String(value)) => Some(value),
    _ => None,
  };

  matches.push((
    span_size(range),
    KiteLocateHit {
      id,
      kind,
      name,
      file_path: Some(node_file_path),
      range,
      range_json,
    },
  ));
}

    let prefer_index = |kind: Option<&str>| -> Option<usize> {
      let kind = kind?;
      prefer.iter().position(|k| k == kind)
    };

    matches.sort_by(|a, b| {
      let a_hit = &a.1;
      let b_hit = &b.1;

      let a_kind = a_hit.kind.as_deref();
      let b_kind = b_hit.kind.as_deref();

      let strategy_cmp = match options.strategy {
        KiteLocateStrategy::MostSpecific => std::cmp::Ordering::Equal,
        KiteLocateStrategy::PreferDefinitions => {
          let cat = |kind: Option<&str>, name: &Option<String>| -> u8 {
            match kind {
              Some("file") => 3,
              Some(_) if name.is_some() => 0,
              Some(_) => 1,
              None => 2,
            }
          };
          cat(a_kind, &a_hit.name).cmp(&cat(b_kind, &b_hit.name))
        }
        KiteLocateStrategy::PreferKinds => {
          let ai = prefer_index(a_kind).unwrap_or(usize::MAX);
          let bi = prefer_index(b_kind).unwrap_or(usize::MAX);
          ai.cmp(&bi)
        }
      };

      strategy_cmp
        .then_with(|| a.0.cmp(&b.0))
        .then_with(|| a_hit.id.cmp(&b_hit.id))
    });

    Ok(matches.into_iter().take(cap).map(|(_, hit)| hit).collect())
  }
}

fn load_incremental_manifest(path: &Path) -> Option<KiteIncrementalManifest> {
  let content = fs::read_to_string(path).ok()?;
  let manifest: KiteIncrementalManifest = serde_json::from_str(&content).ok()?;
  if manifest.version != INCREMENTAL_MANIFEST_VERSION {
    return None;
  }
  Some(manifest)
}

fn save_incremental_manifest(
  path: &Path,
  manifest: &KiteIncrementalManifest,
) -> Result<(), KiteStoreError> {
  if let Some(parent) = path.parent() {
    fs::create_dir_all(parent)?;
  }
  let payload = serde_json::to_string_pretty(manifest)?;
  let tmp_name = format!(
    ".{}.tmp.{}",
    path
      .file_name()
      .and_then(|name| name.to_str())
      .unwrap_or("manifest"),
    std::process::id()
  );
  let tmp_path = path
    .parent()
    .map(|parent| parent.join(&tmp_name))
    .unwrap_or_else(|| PathBuf::from(&tmp_name));
  fs::write(&tmp_path, payload)?;
  if fs::rename(&tmp_path, path).is_err() {
    if path.exists() {
      let _ = fs::remove_file(path);
    }
    fs::rename(&tmp_path, path)?;
  }
  Ok(())
}

fn collect_chunk_ids_by_file(
  files: &[ParsedFile],
  include_graph_file_nodes: bool,
) -> HashMap<String, HashSet<String>> {
  let mut out: HashMap<String, HashSet<String>> = HashMap::new();
  for file in files {
    let mut ids = HashSet::new();
    for chunk in &file.chunks {
      ids.insert(chunk.id.clone());
    }
    if include_graph_file_nodes {
      ids.insert(format!("ts:file:{}", file.file_path));
    }
    out.insert(file.file_path.clone(), ids);
  }
  out
}

fn to_sorted_ids(ids: &HashSet<String>) -> Vec<String> {
  let mut out: Vec<String> = ids.iter().cloned().collect();
  out.sort();
  out
}

fn sanitize_embedding_vector(embedding: &[f32]) -> Vec<f32> {
  if embedding.is_empty() {
    return Vec::new();
  }
  let mut out = Vec::with_capacity(embedding.len());
  let mut has_non_zero = false;
  for value in embedding {
    let cleaned = if value.is_finite() { *value } else { 0.0 };
    if cleaned != 0.0 {
      has_non_zero = true;
    }
    out.push(cleaned);
  }
  if !has_non_zero {
    return Vec::new();
  }
  out
}

pub struct KiteDbIndexSink {
  store: Option<KiteCodeStore>,
  store_path: PathBuf,
  manifest_path: PathBuf,
  pending_manifest: Option<KiteIncrementalManifest>,
  clear: bool,
  checkpoint_on_finish: bool,
  checkpoint_threshold: f64,
  error: Option<KiteStoreError>,
}

impl KiteDbIndexSink {
  pub fn new(store_path: PathBuf, clear: bool) -> Self {
    Self::new_with_checkpoint_policy(store_path, clear, true, 0.0)
  }

  pub fn new_with_checkpoint_policy(
    store_path: PathBuf,
    clear: bool,
    checkpoint_on_finish: bool,
    checkpoint_threshold: f64,
  ) -> Self {
    let manifest_path = manifest_path_for_store(&store_path);
    Self {
      store: None,
      store_path,
      manifest_path,
      pending_manifest: None,
      clear,
      checkpoint_on_finish,
      checkpoint_threshold: checkpoint_threshold.clamp(0.0, 1.0),
      error: None,
    }
  }

  fn incremental_enabled(phases: crate::core::index_engine::IndexPhases) -> bool {
    phases.graph || phases.vector
  }

  fn plan_incremental_tombstones(
    &mut self,
    files: &[ParsedFile],
    phases: crate::core::index_engine::IndexPhases,
  ) -> Result<(), KiteStoreError> {

if !Self::incremental_enabled(phases) {
  return Ok(());
}

if self.clear {
  let _ = fs::remove_file(&self.manifest_path);
}

let current_ids_by_file = collect_chunk_ids_by_file(files, phases.graph);
let current_files: HashSet<&str> = files.iter().map(|file| file.file_path.as_str()).collect();
let mut ids_to_remove = HashSet::new();
let mut next_files = BTreeMap::new();

if let Some(previous) = if self.clear {
  None
} else {
  load_incremental_manifest(&self.manifest_path)
} {

  for (file, old_ids) in &previous.files {
    if !current_files.contains(file.as_str()) {
      ids_to_remove.extend(old_ids.iter().cloned());
    }
  }

  for file in files {
    if file.skipped {
      if let Some(old_ids) = previous.files.get(&file.file_path) {
        let mut persisted_ids = old_ids.iter().cloned().collect::<HashSet<_>>();
        if phases.graph {
          persisted_ids.insert(format!("ts:file:{}", file.file_path));
        }
        next_files.insert(file.file_path.clone(), to_sorted_ids(&persisted_ids));
        continue;
      }
    }

    let new_ids = current_ids_by_file
      .get(&file.file_path)
      .cloned()
      .unwrap_or_default();
    if let Some(old_ids) = previous.files.get(&file.file_path) {
      for old_id in old_ids {
        if !new_ids.contains(old_id) {
          ids_to_remove.insert(old_id.clone());
        }
      }
    }
    next_files.insert(file.file_path.clone(), to_sorted_ids(&new_ids));
  }
} else {

    // Bootstrap reconciliation when no manifest exists yet.
    let existing = self.open_if_needed()?.tracked_ids_by_file();
    for (file, existing_ids) in existing {
      if let Some(current_ids) = current_ids_by_file.get(&file) {
        for existing_id in existing_ids {
          if !current_ids.contains(&existing_id) {
            ids_to_remove.insert(existing_id);
          }
        }
      } else {
        ids_to_remove.extend(existing_ids);
      }
    }

    for (file, ids) in &current_ids_by_file {
      next_files.insert(file.clone(), to_sorted_ids(ids));
    }
  }

  if !ids_to_remove.is_empty() {
    self
      .open_if_needed()?
      .delete_ci_ids(ids_to_remove.iter().map(String::as_str))?;
  }

  self.pending_manifest = Some(KiteIncrementalManifest {
    version: INCREMENTAL_MANIFEST_VERSION,
    files: next_files,
  });
  Ok(())
}

pub fn open_if_needed(&mut self) -> Result<&KiteCodeStore, KiteStoreError> {
  if self.store.is_none() {
    self.store = Some(KiteCodeStore::open(KiteStoreOptions {
      path: self.store_path.clone(),
      clear: self.clear,
      checkpoint_on_finish: self.checkpoint_on_finish,
      checkpoint_threshold: self.checkpoint_threshold,
    })?);
    self.clear = false;
  }
  Ok(self.store.as_ref().expect("store initialized"))
}

  pub fn finish(mut self) -> Result<(), KiteStoreError> {
    if let Some(err) = self.error.take() {
      if let Some(store) = &self.store {
        let _ = store.rollback();
      }
      return Err(err);
    }
    if let Some(store) = self.store.take() {
      store.commit()?;
    }
    if let Some(manifest) = self.pending_manifest.take() {
      save_incremental_manifest(&self.manifest_path, &manifest)?;
    }
    Ok(())
  }

  pub fn abort(mut self) -> Result<(), KiteStoreError> {
    if let Some(store) = self.store.take() {
      store.rollback()?;
    }
    self.pending_manifest = None;
    Ok(())
  }
}

