impl IndexSink for KiteDbIndexSink {
  fn disable_parse_skip(&self, phases: crate::core::index_engine::IndexPhases) -> bool {
    Self::incremental_enabled(phases) && (self.clear || !self.manifest_path.exists())
  }

  fn on_parsed_files(
    &mut self,
    files: &[ParsedFile],
    phases: crate::core::index_engine::IndexPhases,
  ) -> Result<(), String> {
    if self.error.is_some() {
      return Ok(());
    }
    self
      .plan_incremental_tombstones(files, phases)
      .map_err(|err| err.to_string())
  }

  fn on_event(&mut self, event: IndexEvent) {
    if self.error.is_some() {
      return;
    }
    if matches!(event, IndexEvent::PipelineCompleted { .. }) {
      // Commit is handled in `finish()` to surface errors.
    }
  }
}

