import { spawn } from "node:child_process"

const commands = [
  {
    name: "web",
    cwd: "apps/web",
    args: ["run", "--env-file=../../.env", "dev"],
  },
  {
    name: "indexer",
    cwd: "apps/indexer",
    args: ["run", "--env-file=../../.env", "dev"],
  },
]

const bunExecutable = process.platform === "win32" ? "bun.exe" : "bun"
const children = []
let shuttingDown = false

const stopAll = (signal = "SIGTERM") => {
  if (shuttingDown) {
    return
  }
  shuttingDown = true

  for (const child of children) {
    if (!child.killed) {
      child.kill(signal)
    }
  }
}

for (const command of commands) {
  const child = spawn(bunExecutable, command.args, {
    cwd: command.cwd,
    stdio: "inherit",
    env: process.env,
  })

  child.on("exit", (code, signal) => {
    if (!shuttingDown) {
      console.error(
        `[dev:all] ${command.name} exited ${signal ? `with signal ${signal}` : `with code ${code}`}`,
      )
      stopAll(signal ?? "SIGTERM")
      process.exit(code ?? 1)
    }
  })

  child.on("error", (error) => {
    console.error(`[dev:all] failed to start ${command.name}:`, error)
    stopAll()
    process.exit(1)
  })

  children.push(child)
}

process.once("SIGINT", () => {
  stopAll("SIGINT")
  process.exit(0)
})

process.once("SIGTERM", () => {
  stopAll("SIGTERM")
  process.exit(0)
})

import { describe, expect, mock, test } from "bun:test"

type LoggerContext = Record<string, unknown>

type ApiLogHandlerArgs = {
  logger: {
    set: (context: LoggerContext) => void
  }
  requestId: string
}

type ApiLogHandlerResult = {
  response: Response
  status: number
  outcome?: string
}

type RunWithApiRequestLogArgs = {
  request: Request
  path: string
  event: string
  handler: (args: ApiLogHandlerArgs) => Promise<ApiLogHandlerResult>
}

type ModelRouteRow = {
  timestamp: Date
  event: string
  service: string
  environment: string
  region: string | null
  requestId: string | null
  method: string | null
  path: string | null
  status: number | null
  durationMs: number | null
  payload: Record<string, unknown> | null
}

const loadRouteModule = async (options?: {
  userId?: string | null
  rows?: ModelRouteRow[]
  total?: number
  pendingJobs?: number
  processingJobs?: number
}) => {
  const loggerContext: LoggerContext = {}
  const runWithApiRequestLog = mock(async ({ handler }: RunWithApiRequestLogArgs) => {
    const logger = {
      set: (context: LoggerContext) => {
        Object.assign(loggerContext, context)
      },
    }
    const result = await handler({ logger, requestId: "req_model_1" })
    return result.response
  })

  const getSessionUserId = mock(async () =>
    options?.userId === undefined ? "user-1" : options.userId,
  )

const appLogEvents = {
  timestamp: "timestamp",
  createdAt: "created_at",
  event: "event",
  service: "service",
  environment: "environment",
  region: "region",
  requestId: "request_id",
  method: "method",
  path: "path",
  status: "status",
  durationMs: "duration_ms",
  payload: "payload",
}

const indexJobs = {
  status: "status",
}

const select = mock((selection: Record<string, unknown>) => ({
  from: (table: unknown) => {
    if (table === appLogEvents) {
      if ("total" in selection) {
        return {
          where: async () => [{ total: options?.total ?? options?.rows?.length ?? 0 }],
        }
      }

      return {
        where: () => ({
          orderBy: () => ({
            limit: async (limit: number) => (options?.rows ?? []).slice(0, Math.max(0, limit)),
          }),
        }),
      }
    }

    if (table === indexJobs) {
      return {
        where: async (predicate: { __eq?: [unknown, unknown] } | undefined) => {
          const status = predicate?.__eq?.[1]
          if (status === "pending") {
            return [{ value: options?.pendingJobs ?? 0 }]
          }
          if (status === "processing") {
            return [{ value: options?.processingJobs ?? 0 }]
          }
          return [{ value: 0 }]
        },
      }
    }

    throw new Error("Unexpected table in model route test.")
  },
}))

  mock.module("drizzle-orm", () => ({
    and: (...args: unknown[]) => ({ __and: args }),
    count: () => ({ __count: true }),
    desc: (value: unknown) => ({ __desc: value }),
    eq: (left: unknown, right: unknown) => ({ __eq: [left, right] }),
    gte: (left: unknown, right: unknown) => ({ __gte: [left, right] }),
    lte: (left: unknown, right: unknown) => ({ __lte: [left, right] }),
    sql: Object.assign(
      (strings: TemplateStringsArray, ...values: unknown[]) => ({
        __sql: [strings, values],
      }),
      { raw: (value: string) => ({ __sqlRaw: value }) },
    ),
  }))
  mock.module("@/lib/db", () => ({ db: { select } }))
  mock.module("@/lib/db/schema", () => ({
    appLogEvents,
    indexJobs,
  }))
  mock.module("@/lib/session", () => ({
    getSessionUserId,
    getSession: async () => {
      const userId = await getSessionUserId()
      return userId ? { user: { id: userId } } : null
    },
    getSessionAccess: async () => {
      const userId = await getSessionUserId()
      return {
        session: userId ? { user: { id: userId } } : null,
        isAlphaDenied: false,
      }
    },
  }))
  mock.module("@/lib/utils/logger", () => ({
    runWithApiRequestLog,
    logScopedError: mock(() => {}),
  }))

  const routeModule = await import(`./route?cacheBust=${Math.random().toString(36).slice(2)}`)

  return {
    GET: routeModule.GET as (request: Request) => Promise<Response>,
    loggerContext,
    select,
  }
}

