import { and, count, desc, eq, gte, inArray, isNotNull, or, sql } from "drizzle-orm";

import { db } from "@/lib/db";
import {
  aiReviewRuns,
  analyticsCodeMetricSnapshots,
  analyticsUserActivityEvents,
} from "@/lib/db/schema";
import {
  loadAnalyticsIntegrationScope,
  type AnalyticsIntegrationScope,
} from "@/lib/analytics/integration-scope";

type MetricPoint = {
  date: string;
  complexityScore: number | null;
  testCoverageRate: number | null;
  technicalDebtMinutes: number | null;
  antiPatternCount: number | null;
  acCoverageRate: number | null;
};

type MetricSnapshot = Omit<MetricPoint, "date">;

export type AnalyticsOverview = {
  generatedAt: string;
  windowDays: number;
  trendDays: number;
  codeMetrics: {
    latest: MetricSnapshot;
    previous: MetricSnapshot;
    deltas: MetricSnapshot;
    trend: MetricPoint[];
  };
  reviewAnalytics: {
    reviewsByDay: Array<{ date: string; count: number }>;
    reviewsByWeek: Array<{ week: string; count: number }>;
    issuesPerReview: number;
    reviewAcceptanceRate: number | null;
    acCoverageRate: number | null;
    reviewsInWindow: number;
    findingsInWindow: number;
  };
  userActivity: {
    commandsUsed: Array<{ command: string; count: number }>;
    featureAdoption: Array<{ feature: string; count: number }>;
    averageSessionDurationMs: number | null;
    medianSessionDurationMs: number | null;
    sessionsMeasured: number;
  };
};

const DAY_MS = 24 * 60 * 60 * 1000;

const toNumber = (value: unknown): number => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }
  if (typeof value === "bigint") {
    return Number(value);
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : 0;
  }
  return 0;
};

const asOptionalNumber = (value: unknown): number | null => {
  if (value === null || value === undefined) {
    return null;
  }
  const normalized = toNumber(value);
  return Number.isFinite(normalized) ? normalized : null;
};

const average = (values: number[]) =>
  values.length === 0
    ? null
    : Math.round((values.reduce((sum, value) => sum + value, 0) / values.length) * 100) / 100;

const percentile = (values: number[], p: number) => {
  if (values.length === 0) {
    return null;
  }

  const sorted = [...values].sort((a, b) => a - b);
  const index = (sorted.length - 1) * p;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);

  if (lower === upper) {
    return sorted[lower];
  }

  const weight = index - lower;
  return sorted[lower] * (1 - weight) + sorted[upper] * weight;
};

const toUtcDateKey = (value: Date) => value.toISOString().slice(0, 10);

const emptyMetricSnapshot = (): MetricSnapshot => ({
  complexityScore: null,
  testCoverageRate: null,
  technicalDebtMinutes: null,
  antiPatternCount: null,
  acCoverageRate: null,
});

const metricDelta = (latest: number | null, previous: number | null) => {
  if (latest === null || previous === null) {
    return null;
  }
  return Math.round((latest - previous) * 100) / 100;
};

const toMetricSnapshot = (row: {
  complexityScore: unknown;
  testCoverageRate: unknown;
  technicalDebtMinutes: unknown;
  antiPatternCount: unknown;
  acCoverageRate: unknown;
}): MetricSnapshot => ({
  complexityScore: asOptionalNumber(row.complexityScore),
  testCoverageRate: asOptionalNumber(row.testCoverageRate),
  technicalDebtMinutes: asOptionalNumber(row.technicalDebtMinutes),
  antiPatternCount: asOptionalNumber(row.antiPatternCount),
  acCoverageRate: asOptionalNumber(row.acCoverageRate),
});

const buildTrend = (
  rows: Array<{
    measuredAt: Date;
    complexityScore: unknown;
    testCoverageRate: unknown;
    technicalDebtMinutes: unknown;
    antiPatternCount: unknown;
    acCoverageRate: unknown;
  }>,
  trendDays: number,
) => {
  const perDay = new Map<
    string,
    {
      complexityScore: number[];
      testCoverageRate: number[];
      technicalDebtMinutes: number[];
      antiPatternCount: number[];
      acCoverageRate: number[];
    }
  >();

for (const row of rows) {
  const date = toUtcDateKey(row.measuredAt);
  const current = perDay.get(date) ?? {
    complexityScore: [],
    testCoverageRate: [],
    technicalDebtMinutes: [],
    antiPatternCount: [],
    acCoverageRate: [],
  };

  const complexityScore = asOptionalNumber(row.complexityScore);
  const testCoverageRate = asOptionalNumber(row.testCoverageRate);
  const technicalDebtMinutes = asOptionalNumber(row.technicalDebtMinutes);
  const antiPatternCount = asOptionalNumber(row.antiPatternCount);
  const acCoverageRate = asOptionalNumber(row.acCoverageRate);

  if (complexityScore !== null) {
    current.complexityScore.push(complexityScore);
  }
  if (testCoverageRate !== null) {
    current.testCoverageRate.push(testCoverageRate);
  }
  if (technicalDebtMinutes !== null) {
    current.technicalDebtMinutes.push(technicalDebtMinutes);
  }
  if (antiPatternCount !== null) {
    current.antiPatternCount.push(antiPatternCount);
  }
  if (acCoverageRate !== null) {
    current.acCoverageRate.push(acCoverageRate);
  }

  perDay.set(date, current);
}

const now = new Date();
const trend: MetricPoint[] = [];

  for (let offset = trendDays - 1; offset >= 0; offset -= 1) {
    const cursor = new Date(now.getTime() - offset * DAY_MS);
    const date = toUtcDateKey(cursor);
    const bucket = perDay.get(date);

    trend.push({
      date,
      complexityScore: average(bucket?.complexityScore ?? []),
      testCoverageRate: average(bucket?.testCoverageRate ?? []),
      technicalDebtMinutes: average(bucket?.technicalDebtMinutes ?? []),
      antiPatternCount: average(bucket?.antiPatternCount ?? []),
      acCoverageRate: average(bucket?.acCoverageRate ?? []),
    });
  }

  return trend;
};

export const buildAnalyticsOverview = async (
  userId: string,
  options: {
    windowDays?: number;
    trendDays?: number;
    integrations?: AnalyticsIntegrationScope;
  } = {},
): Promise<AnalyticsOverview> => {
  const windowDays = Math.max(1, Math.min(365, options.windowDays ?? 30));
  const trendDays = Math.max(7, Math.min(365, options.trendDays ?? 90));
  const now = new Date();
  const sinceWindow = new Date(now.getTime() - windowDays * DAY_MS);
  const sinceTrend = new Date(now.getTime() - trendDays * DAY_MS);

  const integrations = options.integrations ?? (await loadAnalyticsIntegrationScope(userId));
  const integrationIds = integrations.map((integration) => integration.id);

const codeMetricRows =
  integrationIds.length > 0
    ? await db
        .select({
          measuredAt: analyticsCodeMetricSnapshots.measuredAt,
          complexityScore: analyticsCodeMetricSnapshots.complexityScore,
          testCoverageRate: analyticsCodeMetricSnapshots.testCoverageRate,
          technicalDebtMinutes: analyticsCodeMetricSnapshots.technicalDebtMinutes,
          antiPatternCount: analyticsCodeMetricSnapshots.antiPatternCount,
          acCoverageRate: analyticsCodeMetricSnapshots.acCoverageRate,
        })
        .from(analyticsCodeMetricSnapshots)
        .where(
          and(
            eq(analyticsCodeMetricSnapshots.userId, userId),
            inArray(analyticsCodeMetricSnapshots.integrationId, integrationIds),
            gte(analyticsCodeMetricSnapshots.measuredAt, sinceTrend),
          ),
        )
        .orderBy(analyticsCodeMetricSnapshots.measuredAt)
    : [];

const latestCodeRow = codeMetricRows[codeMetricRows.length - 1];
const previousCodeRow = codeMetricRows[codeMetricRows.length - 2];
const latestMetrics = latestCodeRow
  ? toMetricSnapshot(latestCodeRow)
  : emptyMetricSnapshot();
const previousMetrics = previousCodeRow
  ? toMetricSnapshot(previousCodeRow)
  : emptyMetricSnapshot();

const codeMetrics = {
  latest: latestMetrics,
  previous: previousMetrics,
  deltas: {
    complexityScore: metricDelta(
      latestMetrics.complexityScore,
      previousMetrics.complexityScore,
    ),
    testCoverageRate: metricDelta(
      latestMetrics.testCoverageRate,
      previousMetrics.testCoverageRate,
    ),
    technicalDebtMinutes: metricDelta(
      latestMetrics.technicalDebtMinutes,
      previousMetrics.technicalDebtMinutes,
    ),
    antiPatternCount: metricDelta(
      latestMetrics.antiPatternCount,
      previousMetrics.antiPatternCount,
    ),
    acCoverageRate: metricDelta(
      latestMetrics.acCoverageRate,
      previousMetrics.acCoverageRate,
    ),
  },
  trend: buildTrend(codeMetricRows, trendDays),
};

const reviewScopeConditions = integrations.map((integration) =>
  and(
    eq(aiReviewRuns.instanceUrl, integration.instanceUrl),
    eq(aiReviewRuns.projectId, integration.projectId),
  ),
);
const reviewScopeWhere =
  reviewScopeConditions.length === 0
    ? null
    : reviewScopeConditions.length === 1
