      : 0,
  reviewAcceptanceRate,
  acCoverageRate: codeMetrics.latest.acCoverageRate,
  reviewsInWindow,
  findingsInWindow,
};

const [commandsRows, featureRows, sessionDurationRows] = await Promise.all([

  const durations = sessionDurationRows
    .map((row) => asOptionalNumber(row.durationMs))
    .filter((value): value is number => value !== null && value >= 0);
  const averageSessionDurationMs =
    durations.length === 0
      ? null
      : Math.round(
          durations.reduce((sum, value) => sum + value, 0) / durations.length,
        );
  const medianSessionDurationMsRaw = percentile(durations, 0.5);
  const medianSessionDurationMs =
    medianSessionDurationMsRaw === null
      ? null
      : Math.round(medianSessionDurationMsRaw);

  return {
    generatedAt: now.toISOString(),
    windowDays,
    trendDays,
    codeMetrics,
    reviewAnalytics,
    userActivity: {
      commandsUsed: commandsRows.flatMap((row) => {
        if (!row.command) {
          return [];
        }
        return [{ command: row.command, count: toNumber(row.count) }];
      }),
      featureAdoption: featureRows.flatMap((row) => {
        if (!row.feature) {
          return [];
        }
        return [{ feature: row.feature, count: toNumber(row.count) }];
      }),
      averageSessionDurationMs,
      medianSessionDurationMs,
      sessionsMeasured: durations.length,
    },
  };
};

import { type ReviewGateSettings, type ReviewGateStrictness } from "@/lib/review/gate"

const isStrictness = (value: unknown): value is ReviewGateStrictness =>
  value === "quiet" || value === "balanced" || value === "thorough"

export const parseReviewGateSettings = (
  payload: unknown,
): { settings: ReviewGateSettings | null; error: string | null } => {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return {
      settings: null,
      error: "Request body must be an object.",
    }
  }

  const record = payload as Record<string, unknown>

  if (!isStrictness(record.strictness)) {
    return {
      settings: null,
      error: "strictness must be one of: quiet, balanced, thorough.",
    }
  }

  if (typeof record.requireEvidence !== "boolean") {
    return {
      settings: null,
      error: "requireEvidence must be a boolean.",
    }
  }

  if (typeof record.securityBoost !== "boolean") {
    return {
      settings: null,
      error: "securityBoost must be a boolean.",
    }
  }

  return {
    settings: {
      strictness: record.strictness,
      requireEvidence: record.requireEvidence,
      securityBoost: record.securityBoost,
    },
    error: null,
  }
}

import { NextResponse } from "next/server"
import { z } from "zod"

import {
  buildLlmMetrics,
  extractUsageFromOpenAiCompatiblePayload,
  resolveLlmProviderLabel,
} from "@/lib/observability"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const TEST_TIMEOUT_MS = 15_000
const DEFAULT_AI_TOKEN = ""
const DEFAULT_AI_API_URL = "https://api.openai.com/v1"
const MAX_PROVIDER_ERROR_LENGTH = 240

const testConnectionPayloadSchema = z.object({
  apiUrl: z.string().trim().min(1),
  model: z.string().trim().min(1),
  token: z.string().optional(),
})

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const pickFirstNonEmpty = (...values: Array<string | undefined>) => {
  for (const value of values) {
    if (isNonEmptyString(value)) {
      return value.trim()
    }
  }
  return ""
}

const getEnvToken = () =>
  pickFirstNonEmpty(
    process.env.AI_API_TOKEN,
    process.env.OPENAI_API_KEY,
  ) || DEFAULT_AI_TOKEN

const getEnvApiUrl = () =>
  pickFirstNonEmpty(
    process.env.AI_API_URL,
    process.env.OPENAI_BASE_URL,
  ) || DEFAULT_AI_API_URL

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

const isPrivateOrLocalHost = (hostname: string) => {
  const normalized = hostname.trim().toLowerCase()
  if (!normalized) {
    return true
  }

  if (
    normalized === "localhost" ||
    normalized.endsWith(".localhost") ||
    normalized === "0.0.0.0" ||
    normalized === "::1" ||
    normalized.endsWith(".local") ||
    normalized.endsWith(".internal")
  ) {
    return true
  }

  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(normalized)) {
    const octets = normalized.split(".").map((part) => Number.parseInt(part, 10))
    if (octets.some((value) => !Number.isFinite(value) || value < 0 || value > 255)) {
      return true
    }

    const [a, b] = octets
    if (
      a === 10 ||
      a === 127 ||
      (a === 169 && b === 254) ||
      (a === 172 && b >= 16 && b <= 31) ||
      (a === 192 && b === 168) ||
      (a === 100 && b >= 64 && b <= 127)
    ) {
      return true
    }
  }

  if (
    normalized.includes(":") &&
    (normalized.startsWith("fc") || normalized.startsWith("fd") || normalized.startsWith("fe80:"))
  ) {
    return true
  }

  return false
}

const resolveApiUrl = (rawApiUrl: string) => {
  let parsed: URL
  try {
    parsed = new URL(rawApiUrl)
  } catch {
    throw new Error("API URL must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("API URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("API URL must not include credentials.")
  }
  if (isPrivateOrLocalHost(parsed.hostname)) {
    throw new Error("API URL must not target localhost or private network hosts.")
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  const normalized = pathname ? `${parsed.origin}${pathname}` : parsed.origin
  return normalizeApiUrl(normalized)
}

const resolveServerApiUrl = () => resolveApiUrl(getEnvApiUrl())

const getChatCompletionsUrl = (apiUrl: string) => {
  const normalized = normalizeApiUrl(apiUrl)
  if (/\/chat\/completions$/i.test(normalized)) {
    return normalized
  }
  return `${normalized}/chat/completions`
}

const readProviderErrorMessage = async (response: Response) => {
  const bodyText = await response.text().catch(() => "")
  const trimmed = bodyText.trim()
  if (!trimmed) {
    return ""
  }

  try {
    const parsed = JSON.parse(trimmed) as unknown
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    const root = parsed as Record<string, unknown>
    if (typeof root.error === "string" && root.error.trim().length > 0) {
      return root.error.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    if (root.error && typeof root.error === "object" && !Array.isArray(root.error)) {
      const nested = root.error as Record<string, unknown>
      if (typeof nested.message === "string" && nested.message.trim().length > 0) {
        return nested.message.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
      }
    }

    if (typeof root.message === "string" && root.message.trim().length > 0) {
      return root.message.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
  } catch {
    return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
  }
}

const buildNetworkErrorMessage = (error: unknown) => {
  if (error instanceof Error && error.name === "AbortError") {
    return `Connection timed out after ${Math.round(TEST_TIMEOUT_MS / 1000)} seconds.`
  }

  if (error instanceof Error && error.message.trim().length > 0) {
    return `Connection failed before response: ${error.message}`
  }

  return "Connection failed before response."
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/ai/test",
    event: "api.ai.test",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => null) as Promise<unknown>,
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }
      const parsed = testConnectionPayloadSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json(
            { error: "apiUrl and model are required." },
            { status: 400 },
          ),
        }
      }

      let apiUrl: string
      try {
        apiUrl = resolveApiUrl(parsed.data.apiUrl)
      } catch (error) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json(
            { error: error instanceof Error ? error.message : "API URL is invalid." },
            { status: 400 },
          ),
        }
      }

      const model = parsed.data.model.trim()
      const clientToken = parsed.data.token?.trim() ?? ""
      const serverApiUrl = (() => {
        try {
          return resolveServerApiUrl()
        } catch {
          return ""
        }
      })()
      const hasCustomApiUrl = !serverApiUrl || normalizeApiUrl(apiUrl) !== serverApiUrl

const token = (clientToken || (hasCustomApiUrl ? "" : getEnvToken())).trim()
if (!token) {
  return {
    status: 400,
    outcome: hasCustomApiUrl ? "invalid_request" : "missing_config",
    response: NextResponse.json(
      {
        error: hasCustomApiUrl
          ? "Custom API URL requires an explicit token."
          : "AI token missing. Set API token in settings or server env.",
      },
      { status: 400 },
    ),
  }
}

const controller = new AbortController()
const timeout = setTimeout(() => {
  controller.abort()
}, TEST_TIMEOUT_MS)
const startedAt = Date.now()

try {
  const response = await fetch(getChatCompletionsUrl(apiUrl), {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      model,
      temperature: 0,
      max_tokens: 1,
      messages: [
        {
          role: "user",
          content: "Reply with OK.",
        },
      ],
    }),
    signal: controller.signal,
  })

if (!response.ok) {
  const providerError = await readProviderErrorMessage(response)
  const suffix = providerError ? ` ${providerError}` : ""

  logger.set({
    model,
    providerStatus: response.status,
  })

  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      {
        error: `Connection failed (${response.status}).${suffix}`,
        providerStatus: response.status,
      },
      { status: 502 },
    ),
  }
}

const latencyMs = Math.max(1, Date.now() - startedAt)
const providerPayload = (await response.json().catch(() => null)) as unknown
const usage = extractUsageFromOpenAiCompatiblePayload(providerPayload)
const provider = resolveLlmProviderLabel(apiUrl)
logger.set({
  model,
  latencyMs,
  labels: {
    provider,
    model,
  },
  llmMetrics: buildLlmMetrics({
    provider,
    model,
    promptTokens: usage.promptTokens,
    completionTokens: usage.completionTokens,
    totalTokens: usage.totalTokens,
    latencyMs,
    requestCount: 1,
  }),
})

return {
  status: 200,
  outcome: "success",
  response: NextResponse.json({
    ok: true,
    data: {
      latencyMs,
    },
  }),
}

      } catch (error) {
        const message = buildNetworkErrorMessage(error)
        logger.set({
          model,
          networkError: message,
        })

        return {
          status: 502,
          outcome: "upstream_error",
          response: NextResponse.json({ error: message }, { status: 502 }),
        }
      } finally {
        clearTimeout(timeout)
      }
    },
  })
}

