import {
  loadWorkerRunner,
  runIndexerService,
  runIndexerServiceCli,
  workerModuleId,
} from "./main"

describe("service indexer main", () => {

  test("runIndexerService executes loaded worker", async () => {
    let loaded = 0
    let ran = 0

    await runIndexerService({
      loadRunner: async () => {
        loaded += 1
        return async () => {
          ran += 1
        }
      },
    })

    expect(loaded).toBe(1)
    expect(ran).toBe(1)
  })

  test("loadWorkerRunner rejects when worker export is missing", async () => {
    await expect(
      loadWorkerRunner({
        moduleId: "mock-worker",
        importModule: async () => ({}),
      }),
    ).rejects.toThrow("worker module did not export runIndexerWorker")
  })

  test("default worker module id uses service-web exported runtime", () => {
    expect(workerModuleId).toBe("@argus/service-web/indexer-runtime")
  })

  test("runIndexerServiceCli logs and exits on failure", async () => {
    const logged: unknown[][] = []
    const exits: number[] = []

    await runIndexerServiceCli({
      runService: async () => {
        throw new Error("boom")
      },
      logError: (...args) => {
        logged.push(args)
      },
      exit: (code) => {
        exits.push(code)
      },
    })

    expect(logged.length).toBe(1)
    expect(String(logged[0]?.[0])).toContain("[service-indexer] worker execution failed:")
    expect(exits).toEqual([1])
  })

  test("runIndexerServiceCli does not exit on success", async () => {
    const exits: number[] = []

    await runIndexerServiceCli({
      runService: async () => {
        // no-op success path
      },
      exit: (code) => {
        exits.push(code)
      },
    })

    expect(exits).toEqual([])
  })
})

