type ClaimedJob = {
  id: string
  integrationId: string
  deliveryId: string | null
  jobType: "push" | "merge_request" | "hook_sync"
  attempts: number
  normalizedPayload: Record<string, unknown> | null
}

const parseNormalizedPayload = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

const parseJobType = (value: unknown): ClaimedJob["jobType"] => {
  if (value === "push" || value === "merge_request" || value === "hook_sync") {
    return value
  }
  throw new Error("Invalid claimed job type.")
}

const claimDueJobs = async (batchSize: number): Promise<ClaimedJob[]> => {
  const query = sql<ClaimedJob>`
    with due_jobs as (
      select ${gitlabJobs.id}
      from ${gitlabJobs}
      where ${gitlabJobs.status} in ('pending', 'failed')
        and ${gitlabJobs.nextAttemptAt} <= now()
      order by ${gitlabJobs.nextAttemptAt} asc
      for update skip locked
      limit ${batchSize}
    )
    update ${gitlabJobs}
      set
        ${gitlabJobs.status} = 'processing',
        ${gitlabJobs.startedAt} = now(),
        ${gitlabJobs.updatedAt} = now(),
        ${gitlabJobs.attempts} = ${gitlabJobs.attempts} + 1
    from due_jobs
    where ${gitlabJobs.id} = due_jobs.id
    returning
      ${gitlabJobs.id} as "id",
      ${gitlabJobs.integrationId} as "integrationId",
      ${gitlabJobs.deliveryId} as "deliveryId",
      ${gitlabJobs.jobType} as "jobType",
      ${gitlabJobs.attempts} as "attempts",
      ${gitlabJobs.normalizedPayload} as "normalizedPayload"
  `

  const result = await db.execute(query)
  return result.rows.map((rawRow) => {
    const row = rawRow as Record<string, unknown>
    return {
      id: String(row.id),
      integrationId: String(row.integrationId),
      deliveryId: typeof row.deliveryId === "string" ? row.deliveryId : null,
      jobType: parseJobType(row.jobType),
      attempts: Number(row.attempts),
      normalizedPayload: parseNormalizedPayload(row.normalizedPayload),
    }
  })
}

const getRetryDelayMs = (attempt: number) => {
  const exponent = Math.max(0, attempt - 1)
  const baseDelayMs = 30_000
  return Math.min(60 * 60 * 1_000, baseDelayMs * 2 ** exponent)
}

const markJobSucceeded = async (jobId: string, result: Record<string, unknown>) => {
  await db
    .update(gitlabJobs)
    .set({
      status: "succeeded",
      finishedAt: new Date(),
      lastError: null,
      result,
      updatedAt: new Date(),
    })
    .where(eq(gitlabJobs.id, jobId))
}

const markJobFailed = async ({
  job,
  error,
}: {
  job: ClaimedJob
  error: unknown
}) => {
  const message =
    error instanceof Error ? error.message.slice(0, 500) : "Unexpected job processing error."

  const exceededAttempts = job.attempts >= GITLAB_MAX_JOB_ATTEMPTS
  await db
    .update(gitlabJobs)
    .set({
      status: exceededAttempts ? "dead" : "failed",
      finishedAt: exceededAttempts ? new Date() : null,
      nextAttemptAt: exceededAttempts
        ? new Date()
        : new Date(Date.now() + getRetryDelayMs(job.attempts)),
      lastError: message,
      updatedAt: new Date(),
    })
    .where(eq(gitlabJobs.id, job.id))

  return exceededAttempts
}

const readString = (
  payload: Record<string, unknown> | null,
  key: string,
  fieldName: string,
) => {
  const value = payload?.[key]
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`Missing ${fieldName} in job payload.`)
  }
  return value
}

const branchFromRef = (value: unknown) => {
  if (typeof value !== "string") {
    return null
  }

  const normalized = value.trim()
  const prefix = "refs/heads/"
  if (!normalized.startsWith(prefix)) {
    return null
  }

  const branch = normalized.slice(prefix.length).trim()
  return branch.length > 0 ? branch : null
}

const processPushJob = async (job: ClaimedJob) => {
  const integration = await getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for push job.")
  }

  const afterSha = readString(job.normalizedPayload, "after", "after")
  const token = decryptIntegrationToken(integration)
  const commit = await getCommitDetails(
    integration.instanceUrl,
    token,
    integration.projectId,
    afterSha,
  )
  const branch = branchFromRef(job.normalizedPayload?.ref)
  const queuedPlanJob = branch
    ? await enqueuePlanJob({
        integrationId: job.integrationId,
        branch,
        hintedHeadSha: afterSha,
      })
    : null
  const queuedReconcileJob = await enqueueReconcileJob({
    integrationId: job.integrationId,
  })

  return {
    type: "push",
    ref: typeof job.normalizedPayload?.ref === "string" ? job.normalizedPayload.ref : null,
    after: afterSha,
    branch,
    indexing:
      queuedPlanJob === null
        ? {
            queued: false,
            reason: "non_branch_ref",
          }
        : {
            queued: true,
            jobId: queuedPlanJob.id,
            debounceKey: queuedPlanJob.debounceKey,
            status: queuedPlanJob.status,
          },
    reconcile: {
      queued: true,
      jobId: queuedReconcileJob.id,
      debounceKey: queuedReconcileJob.debounceKey,
      status: queuedReconcileJob.status,
    },
    commit,
  }
}

const processMergeRequestJob = async (job: ClaimedJob) => {
  const integration = await getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for merge request job.")
  }

  const mergeRequestIid = readString(
    job.normalizedPayload,
    "mergeRequestIid",
    "mergeRequestIid",
  )

  const token = decryptIntegrationToken(integration)
  const mergeRequest = await getMergeRequestDetails(
    integration.instanceUrl,
    token,
    integration.projectId,
    mergeRequestIid,
  )

  let changes: Record<string, unknown> | null = null
  try {
    changes = await getMergeRequestChanges(
      integration.instanceUrl,
      token,
      integration.projectId,
      mergeRequestIid,
    )
  } catch {
    changes = null
  }

  return {
    type: "merge_request",
    mergeRequestIid,
    mergeRequest,
    ...(changes ? { changes } : {}),
  }
}

const processHookSyncJob = async (job: ClaimedJob) => {
  const integration = await getIntegrationById(job.integrationId)
  if (!integration) {
    throw new Error("Integration not found for hook sync job.")
  }

  const token = decryptIntegrationToken(integration)
  const syncResult = await syncIntegrationWebhook({
    integration,
    token,
  })

  if (!syncResult.ok) {
    throw new Error(syncResult.error ?? "Hook sync failed.")
  }

  return {
    type: "hook_sync",
    reason:
      typeof job.normalizedPayload?.reason === "string"
        ? job.normalizedPayload.reason
        : "scheduled",
  }
}

const processClaimedJob = async (job: ClaimedJob): Promise<Record<string, unknown>> => {
  if (job.jobType === "push") {
    return processPushJob(job)
  }

  if (job.jobType === "merge_request") {
    return processMergeRequestJob(job)
  }

  return processHookSyncJob(job)
}

export const runGitLabJobRunner = async (batchSize = gitlabEnv.jobBatchSize) => {
  const normalizedBatchSize = Math.min(200, Math.max(1, Math.floor(batchSize)))
  const jobs = await claimDueJobs(normalizedBatchSize)

  const summary = {
    claimed: jobs.length,
    succeeded: 0,
    failed: 0,
    dead: 0,
  }

  for (const job of jobs) {
    try {
      const result = await processClaimedJob(job)
      await markJobSucceeded(job.id, result)
      summary.succeeded += 1
    } catch (error) {
      const isDead = await markJobFailed({ job, error })
      if (isDead) {
        summary.dead += 1
      } else {
        summary.failed += 1
      }
    }
  }

  return summary
}

export const cleanupOldWebhookDeliveries = async (
  retentionDays = GITLAB_WEBHOOK_RETENTION_DAYS,
) => {
  const normalizedDays = Math.max(1, Math.floor(retentionDays))
  const cutoff = new Date(Date.now() - normalizedDays * 24 * 60 * 60 * 1_000)

  const deleted = await db
    .delete(gitlabWebhookDeliveries)
    .where(lt(gitlabWebhookDeliveries.receivedAt, cutoff))
    .returning({ id: gitlabWebhookDeliveries.id })

  return {
    deletedDeliveries: deleted.length,
    retentionDays: normalizedDays,
  }
}

import { and, eq, ne, sql } from 'drizzle-orm'

import { db } from '@/lib/db'
import { indexFileStates, indexVectors } from '@/lib/db/schema'
import { INDEX_VECTOR_DIMENSION } from '@/lib/indexing/constants'
import type { VectorQueryCandidate, VectorStore } from '@/lib/indexing/contracts'

const normalizeEmbedding = (embedding: number[]) => {
  if (embedding.length !== INDEX_VECTOR_DIMENSION) {
    throw new Error(
      `Embedding dimension mismatch. Expected ${INDEX_VECTOR_DIMENSION}, received ${embedding.length}.`,
    )
  }

  const values = embedding.map((value) => {
    if (!Number.isFinite(value)) {
      throw new Error('Embedding contains non-finite values.')
    }
    return Number(value.toFixed(8))
  })

  return `[${values.join(',')}]`
}

const parseCandidate = (row: Record<string, unknown>): VectorQueryCandidate => ({
  path: String(row.path),
  fileId: String(row.fileId),
  runId: String(row.runId),
  chunkIndex: Number(row.chunkIndex),
  score: Number(row.score),
  content: typeof row.content === 'string' ? row.content : '',
})

const computeHnswEfSearch = (effectiveLimit: number) =>
  Math.max(40, Math.min(1_000, effectiveLimit * 4))

export class PostgresVectorStore implements VectorStore {

async upsertChunks(args: {
  branchStateId: string
  runId: string
  path: string
  fileId: string
  chunks: Array<{
    chunkIndex: number
    chunkId: string
    content: string
    embedding: number[]
    metadata: Record<string, unknown>
  }>
}): Promise<void> {
  if (args.chunks.length === 0) {
    return
  }

  const now = new Date()

  await db
    .insert(indexVectors)
    .values(
      args.chunks.map((chunk) => ({
        branchStateId: args.branchStateId,
        runId: args.runId,
        path: args.path,
        fileId: args.fileId,
        chunkIndex: chunk.chunkIndex,
        chunkId: chunk.chunkId,
        content: chunk.content,
        embedding: chunk.embedding,
        metadata: chunk.metadata,
        createdAt: now,
        updatedAt: now,
      })),
    )
    .onConflictDoUpdate({
      target: [
        indexVectors.branchStateId,
        indexVectors.path,
        indexVectors.fileId,
        indexVectors.chunkIndex,
      ],
      set: {
        runId: args.runId,
        chunkId: sql`excluded.chunk_id`,
        content: sql`excluded.content`,
        embedding: sql`excluded.embedding`,
        metadata: sql`excluded.metadata`,
        updatedAt: now,
      },
    })
}

async queryCandidates(args: {
  branchStateId: string
  embedding: number[]
  limit: number
  oversample?: number
}): Promise<VectorQueryCandidate[]> {
  const oversample = Math.max(1, Math.floor(args.oversample ?? 5))
  const limit = Math.max(1, Math.floor(args.limit))
  const effectiveLimit = Math.min(1_000, limit * oversample)
  const queryVector = normalizeEmbedding(args.embedding)
  const efSearch = computeHnswEfSearch(effectiveLimit)

  return db.transaction(async (tx) => {
    await tx.execute(sql`set local hnsw.ef_search = ${efSearch}`)

    const result = await tx.execute(sql`
      select
        ${indexVectors.path} as "path",
        ${indexVectors.fileId} as "fileId",
        ${indexVectors.runId} as "runId",
        ${indexVectors.chunkIndex} as "chunkIndex",
        (1 - (${indexVectors.embedding} <=> ${queryVector}::vector)) as "score",
        ${indexVectors.content} as "content"
      from ${indexVectors}
      inner join ${indexFileStates}
        on ${indexFileStates.branchStateId} = ${indexVectors.branchStateId}
       and ${indexFileStates.path} = ${indexVectors.path}
       and ${indexFileStates.fileId} = ${indexVectors.fileId}
      where ${indexVectors.branchStateId} = ${args.branchStateId}
      order by ${indexVectors.embedding} <=> ${queryVector}::vector asc
      limit ${effectiveLimit}
    `)

    return result.rows.map((raw) => parseCandidate(raw as Record<string, unknown>))
  })
}

  async deleteStaleByPath(args: {
    branchStateId: string
    path: string
    keepFileId: string | null
  }): Promise<void> {
    if (args.keepFileId === null) {
      await db
        .delete(indexVectors)
        .where(
          and(
            eq(indexVectors.branchStateId, args.branchStateId),
            eq(indexVectors.path, args.path),
          ),
        )
      return
    }

    await db
      .delete(indexVectors)
      .where(
        and(
          eq(indexVectors.branchStateId, args.branchStateId),
          eq(indexVectors.path, args.path),
          ne(indexVectors.fileId, args.keepFileId),
        ),
      )
  }
}

export const createPostgresVectorStore = () => new PostgresVectorStore()

