const toSafePayload = (value: unknown): Record<string, unknown> => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {}
  }

  return value as Record<string, unknown>
}

const serializeRow = (row: StreamLogRow) => ({
  id: row.id,
  timestamp: toIso(row.timestamp),
  createdAt: toIso(row.createdAt),
  level: row.level,
  event: row.event,
  service: row.service,
  requestId: row.requestId,
  path: row.path,
  status: row.status,
  durationMs: row.durationMs,
  payload: toSafePayload(row.payload),
})

const listIndexerLogs = async (args: {
  integrationId: string
  limit: number
  sinceCreatedAt?: Date
}) => {
  const where = and(
    inArray(appLogEvents.event, [...INDEXER_STREAM_EVENTS]),
    or(
      inArray(appLogEvents.event, [...WORKER_EVENTS]),
      sql`${appLogEvents.payload} ->> 'integrationId' = ${args.integrationId}`,
    ),
    ...(args.sinceCreatedAt ? [gte(appLogEvents.createdAt, args.sinceCreatedAt)] : []),
  )

  const rows = await db
    .select({
      id: appLogEvents.id,
      timestamp: appLogEvents.timestamp,
      createdAt: appLogEvents.createdAt,
      level: appLogEvents.level,
      event: appLogEvents.event,
      service: appLogEvents.service,
      requestId: appLogEvents.requestId,
      path: appLogEvents.path,
      status: appLogEvents.status,
      durationMs: appLogEvents.durationMs,
      payload: appLogEvents.payload,
    })
    .from(appLogEvents)
    .where(where)
    .orderBy(desc(appLogEvents.createdAt), desc(appLogEvents.timestamp))
    .limit(args.limit)

  return rows.reverse() as StreamLogRow[]
}

