const encoder = new TextEncoder()
let closed = false
let inFlight = false
let pollTimer: ReturnType<typeof setInterval> | null = null
let keepAliveTimer: ReturnType<typeof setInterval> | null = null
let cursorCreatedAt: Date | undefined
const sentIds = new Set<string>()
const sentOrder: string[] = []

const rememberSent = (id: string) => {
  if (sentIds.has(id)) {
    return
  }
  sentIds.add(id)
  sentOrder.push(id)
  if (sentOrder.length > MAX_SENT_IDS) {
    const dropped = sentOrder.shift()
    if (dropped) {
      sentIds.delete(dropped)
    }
  }
}

const close = (controller: ReadableStreamDefaultController<Uint8Array>) => {
  if (closed) {
    return
  }
  closed = true
  if (pollTimer) {
    clearInterval(pollTimer)
    pollTimer = null
  }
  if (keepAliveTimer) {
    clearInterval(keepAliveTimer)
    keepAliveTimer = null
  }

  try {
    controller.close()
  } catch {
    // no-op
  }
}

const sendEvent = (
  controller: ReadableStreamDefaultController<Uint8Array>,
  event: string,
  data: Record<string, unknown>,
) => {
  if (closed) {
    return
  }

  controller.enqueue(
    encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`),
  )
}

const stream = new ReadableStream<Uint8Array>({
  start(controller) {
    const sync = async (initial: boolean) => {
      if (closed || inFlight) {
        return
      }

      inFlight = true

try {
  const rows = await listIndexerLogs({
    integrationId: integration.id,
    limit: initial ? parsed.data.limit : Math.min(parsed.data.limit, 200),
    sinceCreatedAt: initial ? undefined : cursorCreatedAt,
  })

  const unsent = rows.filter((row) => !sentIds.has(row.id))
  if (unsent.length === 0) {
    return
  }

  for (const row of unsent) {
    rememberSent(row.id)
  }

  const lastCreatedAt = unsent[unsent.length - 1]?.createdAt
  if (lastCreatedAt) {
    const parsedCreatedAt = new Date(lastCreatedAt)
    if (!Number.isNaN(parsedCreatedAt.getTime())) {
      cursorCreatedAt = parsedCreatedAt
    }
  }

  if (initial) {
    sendEvent(controller, "ready", {
      at: new Date().toISOString(),
      logs: unsent.map(serializeRow),
    })
    return
  }

  for (const row of unsent) {
    sendEvent(controller, "log", {
      at: new Date().toISOString(),
      log: serializeRow(row),
    })
  }
} catch {
  sendEvent(controller, "error", {
    code: "LOG_STREAM_SYNC_FAILED",
    at: new Date().toISOString(),
  })
} finally {
  inFlight = false
}

          }

          request.signal.addEventListener("abort", () => {
            close(controller)
          })

          void sync(true)
          pollTimer = setInterval(() => {
            void sync(false)
          }, STREAM_POLL_INTERVAL_MS)
          keepAliveTimer = setInterval(() => {
            if (closed) {
              return
            }
            controller.enqueue(encoder.encode(": ping\n\n"))
          }, STREAM_KEEPALIVE_INTERVAL_MS)
        },
        cancel() {
          closed = true
          if (pollTimer) {
            clearInterval(pollTimer)
            pollTimer = null
          }
          if (keepAliveTimer) {
            clearInterval(keepAliveTimer)
            keepAliveTimer = null
          }
        },
      })

      return {
        status: 200,
        outcome: "success",
        response: new Response(stream, {
          headers: {
            "content-type": "text/event-stream; charset=utf-8",
            "cache-control":
              "private, max-age=0, must-revalidate, no-transform",
            connection: "keep-alive",
            "x-accel-buffering": "no",
          },
        }),
      }
    },
  })
}

  review: {
    mergeRequest: (
      integrationId: string,
      projectId: string,
      mergeRequestIid: string,
    ) =>
      [
        "review",
