const path = require('node:path')

const native = require('./index.js')
const { indexStream } = require('./stream.js')
const { clampTopK, normalizeSearchHits } = require('./search-contract.js')
const { formatSearchHits, resolveColorMode } = require('./search-format.js')

const DEFAULT_EMBEDDING_BASE_URL = 'https://api.openai.com/v1'
const DEFAULT_EMBEDDING_MODEL = 'text-embedding-3-small'
const DEFAULT_EMBEDDING_DIMENSION = 1536
const DEFAULT_EMBEDDING_TIMEOUT_MS = 30_000
const DEFAULT_VECTOR_BATCH_SIZE = 256
const DEFAULT_VECTOR_CONCURRENCY = 4
const DEFAULT_TOP_K = 5
const DEFAULT_STORE_RELATIVE_PATH = '.argus-search/index.kite'

const StreamEventType = Object.freeze({
  ParseBatch: 'parse:batch',
  GraphBatch: 'graph:batch',
  VectorBatch: 'vector:batch',
  ScipBatch: 'scip:batch',
  PhaseStart: 'phase:start',
  PhaseProgress: 'phase:progress',
  PhaseComplete: 'phase:complete',
  PhaseError: 'phase:error',
  PipelineComplete: 'pipeline:complete',
})

function resolveRoot(root) {
  if (root == null) return process.cwd()
  const value = String(root).trim()
  if (!value) throw new Error('root cannot be empty')
  return path.resolve(value)
}

function resolveProjectPath(root, candidate) {
  const value = String(candidate ?? '').trim()
  if (!value) return root
  return path.isAbsolute(value) ? value : path.join(root, value)
}

function defaultStorePath(root) {
  return path.join(root, DEFAULT_STORE_RELATIVE_PATH)
}

function withDefaultOpenAiKey(apiKey) {
  if (typeof apiKey === 'string' && apiKey.trim()) return apiKey
  const fromEnv = process.env.OPENAI_API_KEY
  return typeof fromEnv === 'string' && fromEnv.trim() ? fromEnv : undefined
}

function normalizeStringList(input, fallback = []) {
  const values = Array.isArray(input) ? input : [input]
  const unique = []
  for (const raw of values) {
    if (raw == null) continue
    const value = String(raw).trim()
    if (!value) continue
    if (!unique.includes(value)) unique.push(value)
  }
  return unique.length > 0 ? unique : [...fallback]
}

function appendUnique(target, values) {
  for (const value of values) {
    if (!target.includes(value)) target.push(value)
  }
}

function flattenStringArgs(args) {
  if (!args || args.length === 0) return []
  if (args.length === 1 && Array.isArray(args[0])) return normalizeStringList(args[0], [])
  return normalizeStringList(args, [])
}

function toIndexRun(stats, durationMs, storePath) {
  const parse = stats?.parse ?? null
  const graph = stats?.graph ?? null
  const vector = stats?.vector ?? null
  return {
    duration: durationMs / 1000,
    durationMs,
    fileCount: Number(parse?.filesParsed ?? 0) + Number(parse?.filesSkipped ?? 0),
    vectorCount: Number(vector?.vectorsEmitted ?? 0),
    graphNodes: Number(graph?.nodesEmitted ?? 0),
    graphEdges: Number(graph?.edgesEmitted ?? 0),
    storePath: storePath ?? null,
    stats: stats ?? null,
  }
}

class VectorConfig {

  constructor(options = {}) {
    const {
      model = DEFAULT_EMBEDDING_MODEL,
      apiKey,
      baseUrl = DEFAULT_EMBEDDING_BASE_URL,
      dimension = DEFAULT_EMBEDDING_DIMENSION,
      timeoutMs = DEFAULT_EMBEDDING_TIMEOUT_MS,
      batchSize = DEFAULT_VECTOR_BATCH_SIZE,
      concurrency = DEFAULT_VECTOR_CONCURRENCY,
    } = options

    if (!String(model).trim()) throw new Error('model cannot be empty')
    if (!String(baseUrl).trim()) throw new Error('baseUrl cannot be empty')
    if (!Number.isFinite(Number(dimension)) || Number(dimension) <= 0) {
      throw new Error('dimension must be greater than 0')
    }
    if (!Number.isFinite(Number(timeoutMs)) || Number(timeoutMs) <= 0) {
      throw new Error('timeoutMs must be greater than 0')
    }
    if (!Number.isFinite(Number(batchSize)) || Number(batchSize) <= 0) {
      throw new Error('batchSize must be greater than 0')
    }
    if (!Number.isFinite(Number(concurrency)) || Number(concurrency) <= 0) {
      throw new Error('concurrency must be greater than 0')
    }

    this.model = String(model)
    this.apiKey = withDefaultOpenAiKey(apiKey)
    this.baseUrl = String(baseUrl)
    this.dimension = Math.floor(Number(dimension))
    this.timeoutMs = Math.floor(Number(timeoutMs))
    this.batchSize = Math.floor(Number(batchSize))
    this.concurrency = Math.floor(Number(concurrency))
  }

  toProvider() {
    return {
      kind: 'http',
      baseUrl: this.baseUrl,
      model: this.model,
      apiKey: this.apiKey,
      dimension: this.dimension,
      timeoutMs: this.timeoutMs,
    }
  }
}

class KiteDB {
  constructor(options = {}) {
    const normalized = typeof options === 'string' ? { path: options } : options
    const root = resolveRoot(normalized?.root)
    this.path = normalized?.path ? resolveProjectPath(root, normalized.path) : defaultStorePath(root)
  }
}

class Indexer {
  constructor(options = {}) {
    const normalized = typeof options === 'string' ? { root: options } : options
    this.root = resolveRoot(normalized.root)
    this._paths = normalizeStringList(normalized.paths ?? ['.'], ['.'])
    this._include = normalizeStringList(normalized.include ?? [], [])
    this._exclude = normalizeStringList(normalized.exclude ?? [], [])
    this._respectGitignore = normalized.respectGitignore ?? true
    this._vector = null
  }

  paths(...pathsInput) {
    this._paths = normalizeStringList(flattenStringArgs(pathsInput), ['.'])
    return this
  }

  include(...patterns) {
    appendUnique(this._include, flattenStringArgs(patterns))
    return this
  }

  exclude(...patterns) {
    appendUnique(this._exclude, flattenStringArgs(patterns))
    return this
  }

  useGitignore(enabled = true) {
    this._respectGitignore = Boolean(enabled)
    return this
  }

  useVectors(options = {}) {
    this._vector = options instanceof VectorConfig ? options : new VectorConfig(options)
    return this
  }

createStore(pathOrOptions) {
  if (pathOrOptions instanceof KiteDB) return pathOrOptions
  if (pathOrOptions == null) return new KiteDB({ root: this.root })
  if (typeof pathOrOptions === 'string') return new KiteDB({ root: this.root, path: pathOrOptions })
  return new KiteDB({ root: this.root, ...pathOrOptions })
}

stream(options = {}) {
  const {
    batchSize,
    highWaterMark = 16,
    signal,
    emit,
    graph = false,
    vector,
    scip = false,
    indexPack = false,
  } = options
  const indexOptions = this._buildIndexOptions({ graph, vector, scip, indexPack, batchSize })
  const streamOptions = { highWaterMark, signal }
  if (emit) streamOptions.emit = emit
  return indexStream(indexOptions, streamOptions)
}

async index(options = {}) {
  const { graph = true, vector, scip = false, indexPack = false, batchSize } = options
  const indexOptions = this._buildIndexOptions({ graph, vector, scip, indexPack, batchSize })
  const started = Date.now()
  const stats = await native.index(indexOptions)
  return toIndexRun(stats, Date.now() - started, null)
}

async persist(options = {}) {
  const { db, clear = false, graph = true, vector, scip = false, indexPack = false, batchSize } = options
  const store = this.createStore(db)
  const indexOptions = this._buildIndexOptions({ graph, vector, scip, indexPack, batchSize })
  const started = Date.now()
  const stats = await native.indexToKiteDb(indexOptions, { path: store.path, clear: Boolean(clear) })
  return toIndexRun(stats, Date.now() - started, store.path)
}

async search(query, options = {}) {
  const text = String(query ?? '').trim()
  if (!text) throw new Error('query cannot be empty')
  if (!this._vector) throw new Error('search requires useVectors(...)')

  const {
    db,
    topK = DEFAULT_TOP_K,
    includeContent = false,
    contentContext = 2,
    contentMaxChars = 4000,
  } = options
  const store = this.createStore(db)
  const hits = await native.searchKiteDb({
    projectRoot: this.root,
    store: { path: store.path },
    query: text,
    topK: clampTopK(topK),
    includeContent: Boolean(includeContent),
    contentContext: Number.isFinite(Number(contentContext)) ? Number(contentContext) : 2,
    contentMaxChars: Number.isFinite(Number(contentMaxChars)) ? Number(contentMaxChars) : 4000,
    vectorProvider: this._vector.toProvider(),
  })
  return normalizeSearchHits(hits, 'searchKiteDb')
}

  _buildIndexOptions({ graph = true, vector, scip = false, indexPack = false, batchSize } = {}) {
    const vectorEnabled = vector ?? Boolean(this._vector)
    if (vectorEnabled && !this._vector) {
      throw new Error('vector phase requires useVectors(...)')
    }

    const options = {
      projectRoot: this.root,
      inputs: {
        paths: this._paths.map((entry) => resolveProjectPath(this.root, entry)),
        include: [...this._include],
        exclude: [...this._exclude],
        respectGitignore: this._respectGitignore,
      },
      phases: {
        parse: true,
        graph: Boolean(graph),
        vector: Boolean(vectorEnabled),
        scip: Boolean(scip),
        indexPack: Boolean(indexPack),
      },
    }

    const maybeBatchSize = Number(batchSize)
    if (Number.isFinite(maybeBatchSize) && maybeBatchSize > 0) {
      const size = Math.floor(maybeBatchSize)
      options.hooks = {
        parseBatch: size,
        graphBatch: size,
        vectorBatch: size,
        scipBatch: size,
      }
    }

    if (vectorEnabled && this._vector) {
      options.vector = {
        batchSize: this._vector.batchSize,
        concurrency: this._vector.concurrency,
        provider: this._vector.toProvider(),
      }
    }

    return options
  }
}

module.exports = {
  ...native,
  indexStream,
  StreamEventType,
  VectorConfig,
  KiteDB,
  Indexer,
  formatSearchHits,
  resolveColorMode,
}

