import { readFileSync } from "node:fs";
import { isAbsolute, join, relative } from "node:path";
import { globSync } from "node:fs";

const repoRoot = process.cwd();
const srcRoot = join(repoRoot, "src");
const loggerFile = join(srcRoot, "lib", "utils", "logger.ts");

const read = (path) => readFileSync(path, "utf8");
const toAbsolutePath = (path) => (isAbsolute(path) ? path : join(repoRoot, path));
const toRepoRelativePath = (path) => relative(repoRoot, path);
const sensitiveLogKeyRegex =
  /\b(token|password|secret|authorization|cookie|sessionToken|sessionId|apiKey|privateKey|accessKey)\b\s*:/i;

const loggingObjectLiteralRegexes = [
  /(logger\.(set|emit)|appLog\.(info|warn|error|debug))\s*\(\s*\{([\s\S]{0,700}?)\}\s*\)/g,
  /logScopedError\([\s\S]{0,200}?,\s*[\s\S]{0,200}?,\s*\{([\s\S]{0,700}?)\}\s*\)/g,
];

const fail = (label, items) => {
  if (items.length === 0) {
    return;
  }

  console.error(`\n[observability] ${label}`);
  for (const item of items) {
    console.error(`- ${item}`);
  }
};

const findDirectEvlogImports = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    if (absolutePath === loggerFile) {
      continue;
    }

    const source = read(absolutePath);
    if (/from\s+["']evlog["']|require\(\s*["']evlog["']\s*\)/.test(source)) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findConsoleUsage = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    if (absolutePath === loggerFile) {
      continue;
    }

    const source = read(absolutePath);
    if (/\bconsole\.(debug|log|info|warn|error)\b/.test(source)) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findUnwrappedApiRoutes = () => {
  const routes = globSync("src/app/api/**/route.ts", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const route of routes) {
    const absolutePath = toAbsolutePath(route);
    const source = read(absolutePath);
    if (!source.includes("runWithApiRequestLog(")) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findSensitiveLoggingKeys = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    const source = read(absolutePath);

    for (const pattern of loggingObjectLiteralRegexes) {
      pattern.lastIndex = 0;
      let match = pattern.exec(source);
      while (match) {
        const objectText = match[0];
        if (sensitiveLogKeyRegex.test(objectText)) {
          violations.push(toRepoRelativePath(absolutePath));
          break;
        }
        match = pattern.exec(source);
      }
      if (violations[violations.length - 1] === toRepoRelativePath(absolutePath)) {
        break;
      }
    }
  }

  return violations;
};

const directEvlogImports = findDirectEvlogImports();
const consoleUsage = findConsoleUsage();
const unwrappedRoutes = findUnwrappedApiRoutes();
const sensitiveLoggingKeys = findSensitiveLoggingKeys();

fail("Direct evlog imports outside logger entrypoint", directEvlogImports);
fail("console.* usage outside logger entrypoint", consoleUsage);
fail("API routes missing runWithApiRequestLog wrapper", unwrappedRoutes);
fail("Sensitive keys found in logging payloads", sensitiveLoggingKeys);

if (
  directEvlogImports.length > 0 ||
  consoleUsage.length > 0 ||
  unwrappedRoutes.length > 0 ||
  sensitiveLoggingKeys.length > 0
) {
  process.exit(1);
}

console.log("[observability] conventions check passed");

import { describe, expect, mock, test } from "bun:test"

type ApiLogHandlerArgs = {
  logger: {
    set: (context: Record<string, unknown>) => void
  }
  requestId: string
}

type ApiLogHandlerResult = {
  response: Response
  status: number
  outcome?: string
}

type RunWithApiRequestLogArgs = {
  request: Request
  path: string
  event: string
  handler: (args: ApiLogHandlerArgs) => Promise<ApiLogHandlerResult>
}

describe("review preferences global route", () => {
  test("updates global preferences", async () => {
    const runWithApiRequestLog = mock(async ({ handler }: RunWithApiRequestLogArgs) => {
      const result = await handler({ logger: { set: () => {} }, requestId: "req_1" })
      return result.response
    })
    const getSessionUserId = mock(async () => "user-1")
    const upsertReviewGateGlobalSettings = mock(async () => {})
    const normalizeReviewGateScope = mock(() => null)
    const upsertReviewGateProjectOverride = mock(async () => {})
    const deleteReviewGateProjectOverride = mock(async () => {})
    const canUserManageProjectScope = mock(async () => true)
    const resolveReviewGatePreferences = mock(async () => ({
      globalSettings: {
        strictness: "quiet",
        requireEvidence: true,
        securityBoost: true,
      },
      projectOverride: null,
      effectiveSettings: {
        strictness: "quiet",
        requireEvidence: true,
        securityBoost: true,
        scopeSource: "global",
      },
    }))

    mock.module("@/lib/session", () => ({
      getSessionUserId,
      getSession: async () => {
        const userId = await getSessionUserId()
        return userId ? { user: { id: userId } } : null
      },
      getSessionAccess: async () => ({
        session: { user: { id: "user-1" } },
        isAlphaDenied: false,
      }),
    }))
    mock.module("@/lib/review/preferences", () => ({
      normalizeReviewGateScope,
      upsertReviewGateGlobalSettings,
      upsertReviewGateProjectOverride,
      deleteReviewGateProjectOverride,
      canUserManageProjectScope,
      resolveReviewGatePreferences,
    }))
    mock.module("@/lib/utils/logger", () => ({
      runWithApiRequestLog,
      logScopedError: mock(() => {}),
    }))

    const routeModule = await import(`./route?cacheBust=${Math.random().toString(36).slice(2)}`)
    const response = await routeModule.PUT(
      new Request("http://localhost/api/review/preferences/global", {
        method: "PUT",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          strictness: "quiet",
          requireEvidence: true,
          securityBoost: true,
        }),
      }),
    )
    const body = await response.json()

    expect(response.status).toBe(200)
    expect(upsertReviewGateGlobalSettings).toHaveBeenCalledWith({
      userId: "user-1",
      settings: {
        strictness: "quiet",
        requireEvidence: true,
        securityBoost: true,
      },
    })
    expect(body.data.global.strictness).toBe("quiet")
  })
})

"use client"

import { ThemeProvider as NextThemesProvider } from "next-themes"
import { type ComponentProps } from "react"

export function ThemeProvider({
  children,
  ...props
}: ComponentProps<typeof NextThemesProvider>) {
  return (
    <NextThemesProvider
      themes={["light", "dark", "system", "argus-light", "argus-dark"]}
      {...props}
    >
      {children}
    </NextThemesProvider>
  )
}

import type {
  ReviewGateEffectiveSettings,
  ReviewGateSettings,
} from "@/lib/review/gate"

export type ReviewGatePreferencesPayload = {
  global?: ReviewGateSettings
  projectOverride?: ReviewGateSettings | null
  effective?: ReviewGateEffectiveSettings
}

const getErrorMessage = (payload: unknown, fallback: string) => {
  if (payload && typeof payload === "object" && "error" in payload) {
    const value = (payload as { error?: unknown }).error
    if (typeof value === "string" && value.trim().length > 0) {
      return value
    }
  }
  return fallback
}

const parsePreferencesPayload = (payload: unknown): ReviewGatePreferencesPayload => {
  if (!payload || typeof payload !== "object") {
    return {}
  }

  const root = payload as { data?: unknown }
  if (!root.data || typeof root.data !== "object") {
    return {}
  }

  const data = root.data as Record<string, unknown>
  return {
    global: data.global as ReviewGateSettings | undefined,
    projectOverride: (data.projectOverride as ReviewGateSettings | null | undefined) ?? null,
    effective: data.effective as ReviewGateEffectiveSettings | undefined,
  }
}

export const fetchReviewPreferences = async ({
  instanceUrl,
  projectId,
}: {
  instanceUrl?: string
  projectId?: string
}) => {
  const params = new URLSearchParams()
  if (instanceUrl?.trim()) {
    params.set("instanceUrl", instanceUrl.trim())
  }
  if (projectId?.trim()) {
    params.set("projectId", projectId.trim())
  }

  const response = await fetch(`/api/review/preferences${params.size > 0 ? `?${params.toString()}` : ""}`)
  const payload = (await response.json().catch(() => null)) as unknown
  if (!response.ok) {
    throw new Error(getErrorMessage(payload, "Failed to load review preferences."))
  }

  return parsePreferencesPayload(payload)
}

export const saveGlobalReviewPreferences = async (settings: ReviewGateSettings) => {
  const response = await fetch("/api/review/preferences/global", {
    method: "PUT",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify(settings),
  })
  const payload = (await response.json().catch(() => null)) as unknown
  if (!response.ok) {
    throw new Error(getErrorMessage(payload, "Failed to save global review preferences."))
  }

  return parsePreferencesPayload(payload)
}

export const saveProjectReviewPreferences = async ({
  instanceUrl,
  projectId,
  settings,
}: {
  instanceUrl: string
  projectId: string
  settings: ReviewGateSettings
}) => {
  const response = await fetch("/api/review/preferences/project", {
    method: "PUT",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      instanceUrl,
      projectId,
      ...settings,
    }),
  })
  const payload = (await response.json().catch(() => null)) as unknown
  if (!response.ok) {
    throw new Error(getErrorMessage(payload, "Failed to save project review preferences."))
  }

  return parsePreferencesPayload(payload)
}

export const deleteProjectReviewPreferences = async ({
  instanceUrl,
  projectId,
}: {
  instanceUrl: string
  projectId: string
}) => {
  const response = await fetch("/api/review/preferences/project", {
    method: "DELETE",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      instanceUrl,
      projectId,
    }),
  })
  const payload = (await response.json().catch(() => null)) as unknown
  if (!response.ok) {
    throw new Error(getErrorMessage(payload, "Failed to delete project review preferences."))
  }

  return parsePreferencesPayload(payload)
}

