use streaming_iterator::StreamingIterator;
use tree_sitter::{Parser, Query, QueryCursor, Tree};

use super::range::{node_text, to_range};
use super::types::Range;

#[derive(Debug, Clone)]
pub struct QueryCapture {
  pub name: String,
  pub node_id: u64,
  pub range: Range,
  pub text: String,
}

#[derive(Debug, Clone)]
pub struct QueryMatch {
  pub captures: Vec<QueryCapture>,
}

#[derive(Debug)]
pub struct QueryOutput {
  pub tree: Tree,
  pub matches: Vec<QueryMatch>,
}

pub fn run_combined_query_with_tree(
  language: &tree_sitter::Language,
  source_text: &str,
  query_texts: &[String],
) -> Option<QueryOutput> {
  let mut parser = Parser::new();
  parser.set_language(language).ok()?;
  let tree = parser.parse(source_text, None)?;

  let combined = query_texts.join("\n");
  let query = Query::new(language, &combined).ok()?;

  let mut cursor = QueryCursor::new();
  let mut matches = Vec::new();
  let capture_names = query.capture_names();

  let mut matches_iter = cursor.matches(&query, tree.root_node(), source_text.as_bytes());
  while let Some(m) = matches_iter.next() {
    let mut captures = Vec::with_capacity(m.captures.len());
    for capture in m.captures.iter() {
      let node = capture.node;
      let capture_name = capture_names
        .get(capture.index as usize)
        .copied()
        .unwrap_or_default()
        .to_string();
      let node_id = node.id() as u64;
      let text = node_text(source_text, node);
      captures.push(QueryCapture {
        name: capture_name,
        node_id,
        range: to_range(node),
        text,
      });
    }
    matches.push(QueryMatch { captures });
  }

  Some(QueryOutput { tree, matches })
}

import { spawnSync } from "node:child_process"
import { existsSync, readdirSync, readFileSync } from "node:fs"
import path from "node:path"

const [, , scriptName, ...args] = process.argv

if (!scriptName) {
  console.error("[workspace-runner] usage: bun run scripts/run-workspace-script.mjs <script> [--scope=all|apps|shared]")
  process.exit(1)
}

const scopeArg = args.find((arg) => arg.startsWith("--scope="))
const scope = scopeArg ? scopeArg.slice("--scope=".length) : "all"

if (!["all", "apps", "shared"].includes(scope)) {
  console.error(`[workspace-runner] unsupported scope: ${scope}`)
  process.exit(1)
}

const rootDir = process.cwd()

const collectWorkspaceDirs = (workspaceRoot) => {
  if (!existsSync(workspaceRoot)) {
    return []
  }

  return readdirSync(workspaceRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => path.join(workspaceRoot, entry.name))
    .filter((dir) => existsSync(path.join(dir, "package.json")))
}

const TEST_FILE_PATTERN = /(\.test\.|_test_|\.spec\.|_spec_)/
const TEST_SCAN_SKIP_DIRS = new Set(["node_modules", ".git", ".next", "dist", "build", "coverage"])

const hasTestFiles = (dirPath) => {
  const entries = readdirSync(dirPath, { withFileTypes: true })
  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (TEST_SCAN_SKIP_DIRS.has(entry.name)) {
        continue
      }
      if (hasTestFiles(path.join(dirPath, entry.name))) {
        return true
      }
      continue
    }

    if (TEST_FILE_PATTERN.test(entry.name)) {
      return true
    }
  }

  return false
}

const workspaceDirs = [
  ...(scope === "all" || scope === "apps" ? collectWorkspaceDirs(path.join(rootDir, "apps")) : []),
  ...(scope === "all" || scope === "shared"
    ? collectWorkspaceDirs(path.join(rootDir, "packages", "shared"))
    : []),
].sort((left, right) => left.localeCompare(right))

let runCount = 0

for (const packageDir of workspaceDirs) {
  const packageJson = JSON.parse(readFileSync(path.join(packageDir, "package.json"), "utf8"))
  const scripts = packageJson.scripts ?? {}
  if (!scripts[scriptName]) {
    continue
  }

  if (scriptName === "test" && !hasTestFiles(packageDir)) {
    const displayName = packageJson.name ?? path.relative(rootDir, packageDir)
    console.log(
      `\n[workspace-runner] skipping ${displayName} (${path.relative(rootDir, packageDir)}) - no test files found`,
    )
    continue
  }

  runCount += 1
  const displayName = packageJson.name ?? path.relative(rootDir, packageDir)
  console.log(`\n[workspace-runner] ${displayName} (${path.relative(rootDir, packageDir)})`)
  console.log(`[workspace-runner] bun run ${scriptName}`)

  const result = spawnSync("bun", ["run", scriptName], {
    cwd: packageDir,
    stdio: "inherit",
    env: process.env,
  })

  if ((result.status ?? 1) !== 0) {
    process.exit(result.status ?? 1)
  }
}

if (runCount === 0) {
  console.error(`[workspace-runner] no workspace packages expose script "${scriptName}" for scope "${scope}"`)
  process.exit(1)
}

console.log(`\n[workspace-runner] completed "${scriptName}" in ${runCount} package(s).`)

import { useCallback } from "react"

import type {
  OnboardingEventMetadata,
  OnboardingTrackedEvent,
} from "@/components/onboarding/onboarding-types"

export function useOnboardingTracking() {
  const trackEvent = useCallback((
    event: OnboardingTrackedEvent,
    metadata?: OnboardingEventMetadata,
  ) => {
    const body = JSON.stringify({ event, metadata })

    if (typeof navigator !== "undefined" && typeof navigator.sendBeacon === "function") {
      try {
        const sent = navigator.sendBeacon(
          "/api/onboarding/track",
          new Blob([body], { type: "application/json" }),
        )
        if (sent) {
          return
        }
      } catch {
      }
    }

    void fetch("/api/onboarding/track", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body,
      keepalive: true,
    }).catch(() => null)
  }, [])

  return { trackEvent }
}

