import { and, eq } from 'drizzle-orm'
import { parsePositiveInt } from '@argus/shared-config'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexConfigs,
  indexRuns,
} from '@/lib/db/schema'
import type { GitLabSource, PlanJob } from '@/lib/indexing/contracts'
import {
  DEFAULT_DELTA_FALLBACK_THRESHOLD,
  DEFAULT_INDEX_CONFIG_HASH,
} from '@/lib/indexing/constants'
import { createGitLabSource } from '@/lib/indexing/sources/gitlab-source'
import type { PlannedRun } from '@/lib/indexing/types'

const CONFIG_HASH_PATTERN = /^[A-Za-z0-9._-]{1,120}$/

type PlanProcessorDeps = {
  source: GitLabSource
}

const defaultDeps = (): PlanProcessorDeps => ({
  source: createGitLabSource(),
})

const resolveDeltaFallbackThreshold = () =>
  parsePositiveInt(process.env.INDEXER_DELTA_FALLBACK_THRESHOLD, DEFAULT_DELTA_FALLBACK_THRESHOLD)

const isEnvTruthy = (value: string | undefined): boolean => {
  if (!value) {
    return false
  }

  const normalized = value.trim().toLowerCase()
  return normalized === '1' || normalized === 'true' || normalized === 'yes' || normalized === 'on'
}

const isEnvFalsy = (value: string | undefined): boolean => {
  if (!value) {
    return false
  }

  const normalized = value.trim().toLowerCase()
  return normalized === '0' || normalized === 'false' || normalized === 'no' || normalized === 'off'
}

const resolveDeltaModeEnabled = (): boolean => {
  if (isEnvTruthy(process.env.INDEXER_FORCE_SNAPSHOT)) {
    return false
  }

  const configured = process.env.INDEXER_ENABLE_DELTA
  if (isEnvFalsy(configured)) {
    return false
  }

  if (isEnvTruthy(configured)) {
    return true
  }

  // Default-on for Phase 2 rollout; keep INDEXER_FORCE_SNAPSHOT as emergency override.
  return true
}

const artifactsPrefixForRun = (args: {
  integrationId: string
  configHash: string
  branch: string
  headSha: string
  runId: string
}) =>
  [
    'integrations',
    args.integrationId,
    'runs',
    args.configHash,
    args.branch,
    args.headSha,
    args.runId,
  ].join('/')

export const processPlanJob = async (
  job: PlanJob,
  deps: PlanProcessorDeps = defaultDeps(),
): Promise<PlannedRun> => {
  const now = new Date()
  const configHash = job.configHash?.trim() || DEFAULT_INDEX_CONFIG_HASH
  if (!CONFIG_HASH_PATTERN.test(configHash)) {
    throw new Error('Invalid config hash.')
  }
  const configJson = job.configJson ?? {}
  const headSha = await deps.source.resolveHeadSha({
    integrationId: job.integrationId,
    branch: job.branch,
    hintedHeadSha: job.hintedHeadSha,
  })

  await db
    .insert(indexConfigs)
    .values({
      integrationId: job.integrationId,
      configHash,
      configJson,
      active: true,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexConfigs.integrationId, indexConfigs.configHash],
      set: {
        active: true,
        updatedAt: now,
      },
    })

const [branchState] = await db
  .insert(indexBranchStates)
  .values({
    integrationId: job.integrationId,
    branch: job.branch,
    configHash,
    createdAt: now,
    updatedAt: now,
  })
  .onConflictDoUpdate({
    target: [
      indexBranchStates.integrationId,
      indexBranchStates.branch,
      indexBranchStates.configHash,
    ],
    set: {
      updatedAt: now,
    },
  })
  .returning({
    id: indexBranchStates.id,
    lastReadySha: indexBranchStates.lastReadySha,
  })

const mode = await (async () => {
  if (!resolveDeltaModeEnabled() || !branchState.lastReadySha) {
    return 'snapshot' as const
  }

  const compare = await deps.source.compare({
    integrationId: job.integrationId,
    fromSha: branchState.lastReadySha,
    toSha: headSha,
  })
  const tooManyChanges = compare.changes.length > resolveDeltaFallbackThreshold()
  if (!compare.valid || compare.incomplete || tooManyChanges) {
    return 'snapshot' as const
  }

  return 'delta' as const
})()

const [inserted] = await db
  .insert(indexRuns)
  .values({
    branchStateId: branchState.id,
    headSha,
    baseSha: branchState.lastReadySha,
    mode,
    status: 'planned',
    artifactsPrefix: 'pending',
    createdAt: now,
    updatedAt: now,
