    };

const ENDPOINT = "/api/analytics/track";

export const trackAnalyticsEvent = (payload: AnalyticsTrackEvent) => {
  const body = JSON.stringify(payload);

  if (typeof fetch === "function") {
    void fetch(ENDPOINT, {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body,
      keepalive: true,
    }).catch(() => {});
    return;
  }

  if (typeof navigator !== "undefined" && typeof navigator.sendBeacon === "function") {
    const blob = new Blob([body], { type: "application/json" });
    navigator.sendBeacon(ENDPOINT, blob);
  }
};

use std::collections::BTreeSet;
use std::path::PathBuf;

use argus_search::core::parse::chunker::TreeSitterChunker;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Manifest {
  cases: Vec<SymbolCase>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct SymbolCase {
  id: String,
  file_path: String,
  source_path: String,
  expected: ExpectedSymbols,
}

#[derive(Debug, Deserialize)]
struct ExpectedSymbols {
  function: Vec<String>,
  class: Vec<String>,
  #[serde(rename = "type")]
  ty: Vec<String>,
  variable: Vec<String>,
}

fn to_set(values: &[String]) -> BTreeSet<String> {
  values.iter().cloned().collect()
}

fn extract_names(
  chunks: &[argus_search::core::parse::types::CodeChunk],
  kind: &str,
) -> BTreeSet<String> {
  chunks
    .iter()
    .filter(|chunk| chunk.kind == kind)
    .filter_map(|chunk| chunk.name.clone())
    .collect()
}

#[test]

fn symbol_accuracy_fixtures_match_expected_sets() -> Result<(), Box<dyn std::error::Error>> {
  let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
  let manifest_path = root.join("fixtures/symbol-accuracy/cases.json");
  let manifest_raw = std::fs::read_to_string(manifest_path)?;
  let manifest: Manifest = serde_json::from_str(&manifest_raw)?;

  for case in &manifest.cases {
    let source_path = root.join(&case.source_path);
    let source = std::fs::read_to_string(&source_path)?;
    let chunks = TreeSitterChunker::chunk_file(&case.file_path, &source, None);

    let actual_function = extract_names(&chunks, "function");
    let actual_class = extract_names(&chunks, "class");
    let actual_type = extract_names(&chunks, "type");
    let actual_variable = extract_names(&chunks, "variable");

    assert_eq!(
      actual_function,
      to_set(&case.expected.function),
      "case={} function mismatch",
      case.id
    );
    assert_eq!(
      actual_class,
      to_set(&case.expected.class),
      "case={} class mismatch",
      case.id
    );
    assert_eq!(
      actual_type,
      to_set(&case.expected.ty),
      "case={} type mismatch",
      case.id
    );
    assert_eq!(
      actual_variable,
      to_set(&case.expected.variable),
      "case={} variable mismatch",
      case.id
    );
  }

  Ok(())
}

