use crate::core::cancel::CancelToken;
use crate::core::index_pack::writer::IndexPackWriter;
use crate::core::parse::types::ParsedFile;

use super::builder::{build_syntax_graph_batch, GraphConfig};
use super::types::{GraphBatch, GraphEdgeRecord, GraphNodeRecord};

#[derive(Debug, Clone)]
pub struct GraphOptions {
  pub project_root: PathBuf,
  pub config: GraphConfig,
  pub batch_size: usize,
}

impl GraphOptions {
  pub fn new(project_root: impl Into<PathBuf>) -> Self {
    Self {
      project_root: project_root.into(),
      config: GraphConfig::default(),
      batch_size: 512,
    }
  }
}

#[derive(Debug, Default, Clone, serde::Serialize)]
#[serde(rename_all = "camelCase")]
pub struct GraphStats {
  pub nodes_emitted: u64,
  pub edges_emitted: u64,
}

#[derive(Debug)]
pub enum GraphError {
  Io(std::io::Error),
  Cancelled,
}

impl std::fmt::Display for GraphError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      GraphError::Io(err) => write!(f, "graph io error: {err}"),
      GraphError::Cancelled => write!(f, "cancelled"),
    }
  }
}

impl std::error::Error for GraphError {}

impl From<std::io::Error> for GraphError {
  fn from(value: std::io::Error) -> Self {
    GraphError::Io(value)
  }
}

pub trait GraphSink {
  fn on_graph_batch(&mut self, _batch: GraphBatch) {}
}

pub fn run_graph(
  files: &[ParsedFile],
  options: &GraphOptions,
  cancel: &CancelToken,
  sink: &mut dyn GraphSink,
  index_pack: Option<&mut IndexPackWriter>,
) -> Result<GraphStats, GraphError> {
  let batch = build_syntax_graph_batch(files, &options.project_root, &options.config, cancel)?;
  emit_batches(batch, options.batch_size, sink, index_pack, cancel)
}

fn emit_batches(
  batch: GraphBatch,
  batch_size: usize,
  sink: &mut dyn GraphSink,
  mut index_pack: Option<&mut IndexPackWriter>,
  cancel: &CancelToken,
) -> Result<GraphStats, GraphError> {
  let mut stats = GraphStats::default();
  let GraphBatch {
    layer,
    mut nodes,
    mut edges,
  } = batch;

  let node_batches = chunk_vec(&mut nodes, batch_size);
  for node_batch in node_batches {
    cancel.check().map_err(|_| GraphError::Cancelled)?;
    write_nodes(&node_batch, index_pack.as_deref_mut())?;
    stats.nodes_emitted += node_batch.len() as u64;
    sink.on_graph_batch(GraphBatch {
      layer,
      nodes: node_batch,
      edges: Vec::new(),
    });
  }

  let edge_batches = chunk_vec(&mut edges, batch_size);
  for edge_batch in edge_batches {
    cancel.check().map_err(|_| GraphError::Cancelled)?;
    write_edges(&edge_batch, index_pack.as_deref_mut())?;
    stats.edges_emitted += edge_batch.len() as u64;
    sink.on_graph_batch(GraphBatch {
      layer,
      nodes: Vec::new(),
      edges: edge_batch,
    });
  }

  Ok(stats)
}

fn chunk_vec<T>(items: &mut Vec<T>, batch_size: usize) -> Vec<Vec<T>> {
  let mut batches = Vec::new();
  let size = if batch_size == 0 {
    items.len().max(1)
  } else {
    batch_size
  };
  while !items.is_empty() {
    let take = items.len().min(size);
    let batch: Vec<T> = items.drain(0..take).collect();
    batches.push(batch);
  }
  if batches.is_empty() {
    batches.push(Vec::new());
  }
  batches
}

fn write_nodes(
  nodes: &[GraphNodeRecord],
  writer: Option<&mut IndexPackWriter>,
) -> Result<(), GraphError> {
  let Some(writer) = writer else {
    return Ok(());
  };
  for node in nodes {
    writer.write_node(node)?;
  }
  Ok(())
}

fn write_edges(
  edges: &[GraphEdgeRecord],
  writer: Option<&mut IndexPackWriter>,
) -> Result<(), GraphError> {
  let Some(writer) = writer else {
    return Ok(());
  };
  for edge in edges {
    writer.write_edge(edge)?;
  }
  Ok(())
}

