  type ReviewGateEffectiveSettings,
  type ReviewGateSettings,
} from "@/lib/review/gate"

export type ReviewGateScope = {
  instanceUrl: string
  projectId: string
}

export type ResolvedReviewGatePreferences = {
  globalSettings: ReviewGateSettings
  projectOverride: ReviewGateSettings | null
  effectiveSettings: ReviewGateEffectiveSettings
}

const normalizeScopeValue = (value: unknown) => {
  if (typeof value !== "string") {
    return ""
  }
  return value.trim()
}

export const normalizeReviewGateScope = (value: {
  instanceUrl?: unknown
  projectId?: unknown
}): ReviewGateScope | null => {
  const instanceUrl = normalizeScopeValue(value.instanceUrl).replace(/\/+$/, "")
  const projectId = normalizeScopeValue(value.projectId)

  if (!instanceUrl || !projectId) {
    return null
  }

  return {
    instanceUrl,
    projectId,
  }
}

const toSettings = (value: {
  strictness: string
  requireEvidence: boolean
  securityBoost: boolean
} | null): ReviewGateSettings => {
  if (!value) {
    return { ...REVIEW_GATE_DEFAULTS }
  }

  return normalizeReviewGateSettings(value)
}

export const resolveReviewGatePreferences = async ({

  userId,
  scope,
}: {
  userId: string
  scope: ReviewGateScope | null
}): Promise<ResolvedReviewGatePreferences> => {
  const globalRows = await db
    .select({
      strictness: aiReviewGateGlobalSettings.strictness,
      requireEvidence: aiReviewGateGlobalSettings.requireEvidence,
      securityBoost: aiReviewGateGlobalSettings.securityBoost,
    })
    .from(aiReviewGateGlobalSettings)
    .where(eq(aiReviewGateGlobalSettings.userId, userId))
    .limit(1)

  const globalSettings = toSettings(globalRows[0] ?? null)

  let projectOverride: ReviewGateSettings | null = null
  if (scope) {
    const projectRows = await db
      .select({
        strictness: aiReviewGateProjectOverrides.strictness,
        requireEvidence: aiReviewGateProjectOverrides.requireEvidence,
        securityBoost: aiReviewGateProjectOverrides.securityBoost,
      })
      .from(aiReviewGateProjectOverrides)
      .where(
        and(
          eq(aiReviewGateProjectOverrides.userId, userId),
          eq(aiReviewGateProjectOverrides.instanceUrl, scope.instanceUrl),
          eq(aiReviewGateProjectOverrides.projectId, scope.projectId),
        ),
      )
      .limit(1)

    projectOverride = projectRows[0] ? toSettings(projectRows[0]) : null
  }

  const effectiveSettings = projectOverride ?? globalSettings
  const scopeSource = projectOverride
    ? "project"
    : globalRows[0]
      ? "global"
      : "global_default"

  return {
    globalSettings,
    projectOverride,
    effectiveSettings: {
      ...effectiveSettings,
      scopeSource,
    },
  }
}

