#[derive(Default)]
struct InFlightIndexOps {
  next_id: u64,
  tokens: HashMap<u64, CancelToken>,
}

fn in_flight_index_ops() -> &'static Mutex<InFlightIndexOps> {
  static IN_FLIGHT: OnceLock<Mutex<InFlightIndexOps>> = OnceLock::new();
  IN_FLIGHT.get_or_init(|| Mutex::new(InFlightIndexOps::default()))
}

fn register_in_flight_cancel(token: CancelToken) -> u64 {
  match in_flight_index_ops().lock() {
    Ok(mut guard) => {
      guard.next_id = guard.next_id.saturating_add(1);
      let id = guard.next_id;
      guard.tokens.insert(id, token);
      id
    }
    Err(poisoned) => {
      let mut guard = poisoned.into_inner();
      guard.next_id = guard.next_id.saturating_add(1);
      let id = guard.next_id;
      guard.tokens.insert(id, token);
      id
    }
  }
}

fn unregister_in_flight_cancel(id: u64) {
  match in_flight_index_ops().lock() {
    Ok(mut guard) => {
      guard.tokens.remove(&id);
    }
    Err(poisoned) => {
      let mut guard = poisoned.into_inner();
      guard.tokens.remove(&id);
    }
  }
}

struct InFlightCancelGuard {
  id: u64,
}

impl InFlightCancelGuard {
  fn new(id: u64) -> Self {
    Self { id }
  }
}

impl Drop for InFlightCancelGuard {
  fn drop(&mut self) {
    unregister_in_flight_cancel(self.id);
  }
}

#[napi(js_name = "cancelIndexOperations")]
#[allow(dead_code)]

pub fn cancel_index_operations() -> u32 {
  match in_flight_index_ops().lock() {
    Ok(guard) => {
      for token in guard.tokens.values() {
        token.cancel();
      }
      guard.tokens.len() as u32
    }
    Err(poisoned) => {
      let guard = poisoned.into_inner();
      for token in guard.tokens.values() {
        token.cancel();
      }
      guard.tokens.len() as u32
    }
  }
}

fn lock_callback_error<'a>(mutex: &'a Mutex<Option<String>>) -> MutexGuard<'a, Option<String>> {
  match mutex.lock() {
    Ok(guard) => guard,
    Err(poisoned) => {
      let mut guard = poisoned.into_inner();
      if guard.is_none() {
        *guard = Some("internal error: callback error lock poisoned".to_string());
      }
      guard
    }
  }
}

type JsonTsfn = ThreadsafeFunction<
  serde_json::Value,
  Unknown<'static>,
  (serde_json::Value,),
  Status,
  false,
  false,
  1,
>;

type JsCallback<'env> = Function<'env, Unknown<'static>, Unknown<'static>>;

type ParsedIndexOptions = (IndexOptions, NapiIndexSink, Arc<Mutex<Option<String>>>);

struct NapiIndexSink {
  on_parse_batch: Option<JsonTsfn>,
  on_graph_batch: Option<JsonTsfn>,
  on_vector_batch: Option<JsonTsfn>,
  on_scip_batch: Option<JsonTsfn>,
  on_event: Option<JsonTsfn>,
  callback_error: Arc<Mutex<Option<String>>>,
}

impl NapiIndexSink {
  fn capture_error(&self, error: Error) {
    let mut slot = lock_callback_error(&self.callback_error);
    if slot.is_none() {
      *slot = Some(error.to_string());
    }
  }

  fn call_tsfn(&self, tsfn: &JsonTsfn, payload: serde_json::Value) {
    let status = tsfn.call(payload, ThreadsafeFunctionCallMode::Blocking);
    if status != Status::Ok {
      self.capture_error(Error::from_reason(format!("callback failed: {status}")));
    }
  }
}

impl crate::core::parse::engine::ParseSink for NapiIndexSink {
  fn on_parse_batch_ref(&mut self, batch: &[crate::core::parse::types::CodeChunk]) {
    if let Some(tsfn) = &self.on_parse_batch {
      match serde_json::to_value(batch) {
        Ok(value) => self.call_tsfn(tsfn, value),
        Err(err) => self.capture_error(Error::from_reason(err.to_string())),
      }
    }
  }
}

impl crate::core::graph::engine::GraphSink for NapiIndexSink {
  fn on_graph_batch(&mut self, batch: crate::core::graph::types::GraphBatch) {
    if let Some(tsfn) = &self.on_graph_batch {
      match serde_json::to_value(batch) {
        Ok(value) => self.call_tsfn(tsfn, value),
        Err(err) => self.capture_error(Error::from_reason(err.to_string())),
      }
    }
  }
}

impl crate::core::vector::engine::VectorSink for NapiIndexSink {
  fn on_vector_batch(&mut self, batch: crate::core::vector::types::VectorBatch) {
    if let Some(tsfn) = &self.on_vector_batch {
      match serde_json::to_value(batch) {
        Ok(value) => self.call_tsfn(tsfn, value),
        Err(err) => self.capture_error(Error::from_reason(err.to_string())),
