impl crate::core::scip::engine::ScipSink for NapiIndexSink {
  fn on_scip_batch(&mut self, batch: crate::core::graph::types::GraphBatch) {
    if let Some(tsfn) = &self.on_scip_batch {
      match serde_json::to_value(batch) {
        Ok(value) => self.call_tsfn(tsfn, value),
        Err(err) => self.capture_error(Error::from_reason(err.to_string())),
      }
    }
  }
}

impl IndexSink for NapiIndexSink {
  fn on_event(&mut self, event: IndexEvent) {
    if let Some(tsfn) = &self.on_event {
      self.call_tsfn(tsfn, event.to_json());
    }
  }
}

#[napi]
pub fn index(options: Object<'_>) -> Result<Unknown<'_>> {

  let env_raw = options.value().env;
  let (index_options, mut sink, callback_error) = parse_index_options(options)?;
  let cancel = CancelToken::new();
  let operation_id = register_in_flight_cancel(cancel.clone());

  let fut = async move {
    let _guard = InFlightCancelGuard::new(operation_id);
    let stats = napi::tokio::task::spawn_blocking(move || {
      let engine = IndexEngine::new(index_options);
      let result = engine.run(&mut sink, &cancel);
      let mut guard = lock_callback_error(&callback_error);
      let callback_failure = guard.take();
      match (result, callback_failure) {
        (_, Some(message)) => Err(Error::from_reason(message)),
        (Err(err), None) => Err(Error::from_reason(err.to_string())),
        (Ok(stats), None) => Ok(stats),
      }
    })
    .await
    .map_err(|err| Error::from_reason(format!("index task failed: {err}")))??;

    Ok::<IndexStats, Error>(stats)
  };

  let promise = napi::bindgen_prelude::execute_tokio_future(env_raw, fut, |env, stats| {
    let env = Env::from_raw(env);
    let value = serde_json::to_value(stats).map_err(|err| Error::from_reason(err.to_string()))?;
    let js = env.to_js_value(&value)?;
    Ok(js.raw())
  })?;

  // SAFETY: `execute_tokio_future(env_raw, ..)` returned successfully, so `promise` is a valid
  // `napi_value` for the same `env_raw` (specifically: a JS Promise created by N-API). Wrapping it
  // as `Unknown` is sound as long as the env/value pair is valid, which N-API guarantees here.
  Ok(unsafe { Unknown::from_raw_unchecked(env_raw, promise) })
}

