#[napi(js_name = "registerChunkLanguage")]
#[allow(dead_code)]
pub fn register_chunk_language(options: Object<'_>) -> Result<()> {
  let id = required_string(&options, "id")?;
  let extensions = options
    .get::<Vec<String>>("extensions")?
    .ok_or_else(|| Error::from_reason("missing required field: extensions".to_string()))?;

  let grammar_obj = options
    .get::<Object<'_>>("grammar")?
    .ok_or_else(|| Error::from_reason("missing required field: grammar".to_string()))?;
  let grammar_kind = grammar_obj
    .get::<String>("kind")?
    .unwrap_or_else(|| "builtin".to_string());

  let grammar = match grammar_kind.as_str() {
    "builtin" => {
      let builtin = required_string(&grammar_obj, "builtin")?;
      let language = parse_language_name(&builtin).ok_or_else(|| {
        Error::from_reason(format!("unsupported built-in grammar language: {builtin}"))
      })?;
      CustomGrammarSource::Builtin(language)
    }
    "dylib" => {
      let path = required_string(&grammar_obj, "dylibPath")?;
      let symbol = required_string(&grammar_obj, "symbol")?;
      CustomGrammarSource::Dylib {
        path: PathBuf::from(path),
        symbol,
      }
    }
    _ => {
      return Err(Error::from_reason(format!(
        "unsupported grammar kind: {grammar_kind}"
      )));
    }
  };

  let queries = parse_custom_queries(&options)?;

  let chunk_kinds = options
    .get::<Vec<String>>("chunkKinds")?
    .unwrap_or_default()
    .into_iter()
    .map(|name| {
      ChunkKind::from_name(name.as_str())
        .ok_or_else(|| Error::from_reason(format!("unsupported chunk kind: {name}")))
    })
    .collect::<Result<Vec<_>>>()?;

  let registration = RegisterLanguageOptions {
    id,
    extensions,
    grammar,
    queries,
    chunk_kinds,
  };
  register_language(registration).map_err(Error::from_reason)?;
  Ok(())
}

#[napi(js_name = "indexToKiteDb")]
#[allow(dead_code)]
pub fn index_to_kitedb<'a>(options: Object<'a>, store: Object<'a>) -> Result<Unknown<'a>> {
  let env_raw = options.value().env;
  let index_options = parse_index_options_core(&options)?;

if index_options.phases.vector && index_options.vector_provider.is_none() {
  return Err(Error::from_reason(
    "vector phase requires vector.provider config".to_string(),
  ));
}

let store_path = required_string(&store, "path")?;
let store_path = resolve_store_path(&index_options.project_root, PathBuf::from(store_path))?;
let clear = store.get::<bool>("clear")?.unwrap_or(false);
let cancel = CancelToken::new();
let operation_id = register_in_flight_cancel(cancel.clone());

let fut = async move {
  let _guard = InFlightCancelGuard::new(operation_id);
  let stats = napi::tokio::task::spawn_blocking(move || {
    let engine = IndexEngine::new(index_options);
    let mut sink = KiteDbIndexSink::new(store_path, clear);
    match engine.run(&mut sink, &cancel) {
      Err(err) => {
        let _ = sink.abort();
        Err(Error::from_reason(err.to_string()))
      }
      Ok(stats) => {
        sink
          .finish()
          .map_err(|err| Error::from_reason(err.to_string()))?;
        Ok(stats)
      }
    }
  })
  .await
  .map_err(|err| Error::from_reason(format!("index task failed: {err}")))??;

  Ok::<IndexStats, Error>(stats)
};

let promise = napi::bindgen_prelude::execute_tokio_future(env_raw, fut, |env, stats| {
