fn parse_index_options(options: Object<'_>) -> Result<ParsedIndexOptions> {
  let mut index_options = parse_index_options_core(&options)?;

  let callback_error = Arc::new(Mutex::new(None));
  let hooks = options.get::<Object<'_>>("hooks")?;

  if let Some(hooks) = hooks.as_ref() {
    if let Some(value) = hooks.get::<u32>("parseBatch")? {
      index_options.parse_batch = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("graphBatch")? {
      index_options.graph_batch = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("vectorBatch")? {
      index_options.vector.batch_size = value as usize;
    }
    if let Some(value) = hooks.get::<u32>("scipBatch")? {
      index_options.scip_batch = value as usize;
    }
  }

  let sink = NapiIndexSink {
    on_parse_batch: create_tsfn(hook_fn(hooks.as_ref(), "onParseBatch")?)?,
    on_graph_batch: create_tsfn(hook_fn(hooks.as_ref(), "onGraphBatch")?)?,
    on_vector_batch: create_tsfn(hook_fn(hooks.as_ref(), "onVectorBatch")?)?,
    on_scip_batch: create_tsfn(hook_fn(hooks.as_ref(), "onScipBatch")?)?,
    on_event: create_tsfn(hook_fn(hooks.as_ref(), "onEvent")?)?,
    callback_error: Arc::clone(&callback_error),
  };

  Ok((index_options, sink, callback_error))
}

pub(super) fn parse_index_options_core(options: &Object<'_>) -> Result<IndexOptions> {
  let project_root = required_string(options, "projectRoot")?;
  let project_root = PathBuf::from(project_root);
  let mut index_options = IndexOptions::new(project_root.clone());

if let Some(inputs) = options.get::<Object<'_>>("inputs")? {
  index_options.inputs = ParseInputs {
    paths: inputs
      .get::<Vec<String>>("paths")?
      .unwrap_or_default()
      .into_iter()
      .map(|value| resolve_project_path(&project_root, PathBuf::from(value)))
      .collect(),
    include: inputs.get::<Vec<String>>("include")?.unwrap_or_default(),
    exclude: inputs.get::<Vec<String>>("exclude")?.unwrap_or_default(),
    respect_gitignore: inputs.get::<bool>("respectGitignore")?.unwrap_or(true),
  };
}

if let Some(phases) = options.get::<Object<'_>>("phases")? {
  let mut current = index_options.phases;
  if let Some(value) = phases.get::<bool>("parse")? {
    current.parse = value;
  }
  if let Some(value) = phases.get::<bool>("graph")? {
    current.graph = value;
  }
  if let Some(value) = phases.get::<bool>("vector")? {
    current.vector = value;
  }
  if let Some(value) = phases.get::<bool>("scip")? {
    current.scip = value;
  }
  if let Some(value) = phases.get::<bool>("indexPack")? {
    current.index_pack = value;
  }
  index_options.phases = current;
}

if let Some(output) = options.get::<Object<'_>>("output")? {
  let mut out = IndexOutputOptions::default();
  if let Some(value) = output.get::<String>("dataDir")? {
    out.data_dir = Some(resolve_project_path(&project_root, PathBuf::from(value)));
  }
  if let Some(value) = output.get::<String>("indexPackDir")? {
    out.index_pack_dir = Some(resolve_project_path(&project_root, PathBuf::from(value)));
  }
  if let Some(value) = output.get::<String>("schemaVersion")? {
    out.schema_version = value;
  }
  if let Some(value) = output.get::<String>("indexRunId")? {
    out.index_run_id = value;
  }
  if let Some(value) = output.get::<String>("projectRootRel")? {
    out.project_root_rel = Some(value);
  }
  if let Some(value) = output.get::<bool>("incremental")? {
    out.incremental = value;
  }
  index_options.output = out;
}

if let Some(cache) = options.get::<Object<'_>>("cache")? {
  if let Some(value) = cache.get::<bool>("enabled")? {
    index_options.cache.enabled = value;
  }
  if let Some(value) = cache.get::<bool>("force")? {
    index_options.cache.force = value;
  }
  if let Some(value) = cache.get::<String>("path")? {
    index_options.cache.path = Some(resolve_project_path(&project_root, PathBuf::from(value)));
  }
}

if let Some(vector) = options.get::<Object<'_>>("vector")? {
  if let Some(batch_size) = vector.get::<u32>("batchSize")? {
    index_options.vector.batch_size = batch_size as usize;
  }
  if let Some(concurrency) = vector.get::<u32>("concurrency")? {
    index_options.vector.concurrency = concurrency as usize;
  }
  if let Some(provider) = vector.get::<Object<'_>>("provider")? {
    if let Some(kind) = provider.get::<String>("kind")? {
      if kind != "http" {
        return Err(Error::from_reason(format!(
          "unsupported vector provider kind: {kind}"
        )));
      }
    }
    let base_url = required_string(&provider, "baseUrl")?;
    let model = required_string(&provider, "model")?;
    let api_key = provider.get::<String>("apiKey")?;
    let mut config = HttpEmbeddingConfig::new(base_url, api_key, model);
    if let Some(dimension) = provider.get::<u32>("dimension")? {
      config.dimension = Some(dimension as usize);
    }
    if let Some(timeout) = provider.get::<u32>("timeoutMs")? {
      config.timeout = Some(Duration::from_millis(timeout as u64));
    }
    let provider =
      HttpEmbeddingsProvider::new(config).map_err(|err| Error::from_reason(err.to_string()))?;
    index_options.vector_provider = Some(Arc::new(provider));
  }
}

if index_options.phases.vector {
  // Keep chunk payloads in KiteDB so search can include content without extra file IO.
  index_options.vector.include_chunk = true;
}

  if let Some(scip) = options.get::<Object<'_>>("scip")? {
    let mut scip_settings = ScipIndexSettings::default();
    if let Some(value) = scip.get::<String>("dataDir")? {
      scip_settings.data_dir = Some(resolve_project_path(&project_root, PathBuf::from(value)));
    }
    if let Some(config) = scip.get::<Object<'_>>("indexerConfig")? {
      scip_settings.indexer_config = parse_scip_indexer_config(&project_root, config)?;
    }
    index_options.scip_index = scip_settings;
  }

  if index_options.phases.vector && index_options.vector_provider.is_none() {
    return Err(Error::from_reason(
      "vector phase requires vector.provider config".to_string(),
    ));
  }

  Ok(index_options)
}

fn required_string(obj: &Object<'_>, field: &str) -> Result<String> {
  obj
    .get::<String>(field)?
    .ok_or_else(|| Error::from_reason(format!("missing required field: {field}")))
}

fn resolve_chunk_content(options: &Object<'_>, file_path: &str) -> Result<String> {
  let read_root = std::env::current_dir()
    .map_err(|err| Error::from_reason(format!("failed to resolve current directory: {err}")))?;
  let inline = options.get::<String>("content")?;
  let content_path = options.get::<String>("contentPath")?;
  if inline.is_some() && content_path.is_some() {
    return Err(Error::from_reason(
      "chunkFile accepts either content or contentPath, not both".to_string(),
    ));
  }
  if let Some(content) = inline {
    return Ok(content);
  }
  if let Some(path) = content_path {
    let path = resolve_path_within_root(&read_root, PathBuf::from(path), "contentPath")?;
    return read_text_file(path);
  }

  let candidate = resolve_path_within_root(&read_root, PathBuf::from(file_path), "filePath")?;
  if candidate.is_file() {
    return read_text_file(candidate);
  }

  Err(Error::from_reason(
    "chunkFile requires content or contentPath (or a readable filePath on disk)".to_string(),
  ))
}

fn parse_custom_queries(options: &Object<'_>) -> Result<CustomQuerySet> {
  let mut queries = CustomQuerySet::default();
  let read_root = std::env::current_dir()
    .map_err(|err| Error::from_reason(format!("failed to resolve current directory: {err}")))?;

if let Some(dir) = options.get::<String>("queriesDir")? {
  let dir = resolve_path_within_root(&read_root, PathBuf::from(dir), "queriesDir")?;
  for field in QUERY_FIELD_NAMES {
    let path = dir.join(format!("{field}.scm"));
    if path.is_file() {
      set_query_field(&mut queries, field, Some(read_text_file(path)?));
    }
  }
}

if let Some(query_paths) = options.get::<Object<'_>>("queryPaths")? {
  for field in QUERY_FIELD_NAMES {
    if let Some(path) = query_paths.get::<String>(field)? {
      let path = resolve_path_within_root(&read_root, PathBuf::from(path), "queryPaths")?;
      set_query_field(&mut queries, field, Some(read_text_file(path)?));
    }
  }
}

  if let Some(inline) = options.get::<Object<'_>>("queries")? {
    for field in QUERY_FIELD_NAMES {
      let path_key = format!("{field}Path");
      if let Some(path) = inline.get::<String>(&path_key)? {
        let path = resolve_path_within_root(&read_root, PathBuf::from(path), &path_key)?;
        set_query_field(&mut queries, field, Some(read_text_file(path)?));
      }
    }
    if let Some(value) = inline.get::<String>("functions")? {
      queries.functions = Some(value);
    }
    if let Some(value) = inline.get::<String>("classes")? {
      queries.classes = Some(value);
    }
    if let Some(value) = inline.get::<String>("types")? {
      queries.types = Some(value);
    }
    if let Some(value) = inline.get::<String>("variables")? {
      queries.variables = Some(value);
    }
    if let Some(value) = inline.get::<String>("imports")? {
      queries.imports = Some(value);
    }
    if let Some(value) = inline.get::<String>("exports")? {
      queries.exports = Some(value);
    }
    if let Some(value) = inline.get::<String>("comments")? {
      queries.comments = Some(value);
    }
  }

  Ok(queries)
}

fn set_query_field(queries: &mut CustomQuerySet, field: &str, value: Option<String>) {
  match field {
    "functions" => queries.functions = value,
    "classes" => queries.classes = value,
    "types" => queries.types = value,
    "variables" => queries.variables = value,
    "imports" => queries.imports = value,
    "exports" => queries.exports = value,
    "comments" => queries.comments = value,
    _ => {}
  }
}

fn resolve_path_within_root(root_dir: &Path, candidate: PathBuf, label: &str) -> Result<PathBuf> {
  if candidate
    .components()
    .any(|component| matches!(component, Component::ParentDir))
  {
    return Err(Error::from_reason(format!(
      "{label} escapes current working directory"
    )));
  }
  let root = root_dir
    .canonicalize()
    .unwrap_or_else(|_| root_dir.to_path_buf());
  let joined = if candidate.is_absolute() {
    candidate
  } else {
    root.join(candidate)
  };
  let resolved = joined.canonicalize().unwrap_or(joined.clone());
  if resolved.strip_prefix(&root).is_err() {
    return Err(Error::from_reason(format!(
      "{label} escapes current working directory"
    )));
  }
  Ok(resolved)
}

fn read_text_file(path: PathBuf) -> Result<String> {
  std::fs::read_to_string(&path)
    .map_err(|err| Error::from_reason(format!("failed to read {}: {err}", path.display())))
}

