import { describe, expect, mock, test } from "bun:test"

import {
  getCachedUserIntegrations,
  invalidateUserIntegrations,
} from "@/lib/gitlab/user-integrations-cache"

type IntegrationRow = {
  id: string
  projectId: string
}

describe("user integrations cache", () => {
  test("reuses cached integrations for repeated reads", async () => {
    invalidateUserIntegrations()
    const load = mock(async () => [{ id: "int-1", projectId: "p-1" } as IntegrationRow])

    const first = await getCachedUserIntegrations("user-1", { load })
    const second = await getCachedUserIntegrations("user-1", { load })

    expect(first).toEqual([{ id: "int-1", projectId: "p-1" }])
    expect(second).toEqual(first)
    expect(load).toHaveBeenCalledTimes(1)
  })

  test("invalidates a single user cache entry", async () => {
    invalidateUserIntegrations()
    const load = mock(async () => [{ id: "int-2", projectId: "p-2" } as IntegrationRow])

    await getCachedUserIntegrations("user-2", { load })
    expect(load).toHaveBeenCalledTimes(1)

    const invalidated = invalidateUserIntegrations("user-2")
    expect(invalidated).toBe(1)

    await getCachedUserIntegrations("user-2", { load })
    expect(load).toHaveBeenCalledTimes(2)
  })

  test("returns empty array for blank user ids", async () => {
    invalidateUserIntegrations()
    const load = mock(async () => [{ id: "int-3", projectId: "p-3" } as IntegrationRow])

    const value = await getCachedUserIntegrations("   ", { load })

    expect(value).toEqual([])
    expect(load).toHaveBeenCalledTimes(0)
  })
})

import { realpath } from "node:fs/promises"
import path from "node:path"

export const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return null
  }
  return value as Record<string, unknown>
}

export const toBoolean = (value: unknown, fallback: boolean): boolean =>
  typeof value === "boolean" ? value : fallback

export const clampPositiveInt = (value: unknown, fallback: number): number => {
  if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) {
    return fallback
  }
  return Math.floor(value)
}

export const resolveProjectRoot = async (projectRoot: string): Promise<string> => {
  const absoluteRoot = path.resolve(projectRoot)
  try {
    return await realpath(absoluteRoot)
  } catch {
    return absoluteRoot
  }
}

export const withTimeout = async <T>(promise: Promise<T>, timeoutMs: number, message: string): Promise<T> => {
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) {
    return promise
  }

  let timer: NodeJS.Timeout | null = null
  const timeoutPromise = new Promise<never>((_, reject) => {
    timer = setTimeout(() => {
      reject(new Error(message))
    }, timeoutMs)
  })

  try {
    return await Promise.race([promise, timeoutPromise])
  } finally {
    if (timer) {
      clearTimeout(timer)
    }
  }
}

