}

#[derive(Debug)]
pub enum ScipError {
  Io(std::io::Error),
  Provider(String),
  Cancelled,
}

impl std::fmt::Display for ScipError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      ScipError::Io(err) => write!(f, "scip io error: {err}"),
      ScipError::Provider(msg) => write!(f, "{msg}"),
      ScipError::Cancelled => write!(f, "cancelled"),
    }
  }
}

impl std::error::Error for ScipError {}

impl From<std::io::Error> for ScipError {
  fn from(err: std::io::Error) -> Self {
    ScipError::Io(err)
  }
}

