  cancel: &CancelToken,
  sink: &mut dyn ScipSink,
  index_pack: Option<&mut IndexPackWriter>,
) -> Result<ScipStats, ScipError> {
  cancel.check().map_err(|_| ScipError::Cancelled)?;
  let artifacts = provider.index(index_options)?;
  let batch = build_semantic_graph_batch(&artifacts, &options.project_root, cancel)?;
  emit_batches(batch, options.batch_size, sink, index_pack, cancel)
}

fn emit_batches(
  batch: GraphBatch,
  batch_size: usize,
  sink: &mut dyn ScipSink,
  mut index_pack: Option<&mut IndexPackWriter>,
  cancel: &CancelToken,
) -> Result<ScipStats, ScipError> {
  let mut stats = ScipStats::default();
  let GraphBatch {
    layer,
    mut nodes,
    mut edges,
  } = batch;

  let node_batches = chunk_vec(&mut nodes, batch_size);
  for node_batch in node_batches {
    cancel.check().map_err(|_| ScipError::Cancelled)?;
    write_nodes(&node_batch, index_pack.as_deref_mut())?;
    stats.nodes_emitted += node_batch.len() as u64;
    sink.on_scip_batch(GraphBatch {
      layer,
      nodes: node_batch,
      edges: Vec::new(),
    });
  }

  let edge_batches = chunk_vec(&mut edges, batch_size);
  for edge_batch in edge_batches {
    cancel.check().map_err(|_| ScipError::Cancelled)?;
    write_edges(&edge_batch, index_pack.as_deref_mut())?;
    stats.edges_emitted += edge_batch.len() as u64;
    sink.on_scip_batch(GraphBatch {
      layer,
      nodes: Vec::new(),
      edges: edge_batch,
    });
  }

  Ok(stats)
}

fn chunk_vec<T>(items: &mut Vec<T>, batch_size: usize) -> Vec<Vec<T>> {
  let mut batches = Vec::new();
  let size = if batch_size == 0 {
    items.len().max(1)
  } else {
    batch_size
  };
  while !items.is_empty() {
    let take = items.len().min(size);
    let batch: Vec<T> = items.drain(0..take).collect();
    batches.push(batch);
  }
  if batches.is_empty() {
    batches.push(Vec::new());
  }
  batches
}

fn write_nodes(
  nodes: &[GraphNodeRecord],
  writer: Option<&mut IndexPackWriter>,
) -> Result<(), ScipError> {
  let Some(writer) = writer else {
    return Ok(());
  };
  for node in nodes {
    writer.write_node(node)?;
  }
  Ok(())
}

fn write_edges(
  edges: &[GraphEdgeRecord],
  writer: Option<&mut IndexPackWriter>,
) -> Result<(), ScipError> {
  let Some(writer) = writer else {
    return Ok(());
  };
  for edge in edges {
    writer.write_edge(edge)?;
  }
  Ok(())
}

pub fn build_semantic_graph_batch(
  artifacts: &ScipArtifacts,
  project_root: &Path,
  cancel: &CancelToken,
) -> Result<GraphBatch, ScipError> {
  cancel.check().map_err(|_| ScipError::Cancelled)?;
  let mut nodes = Vec::with_capacity(artifacts.nodes.len());
  for node in &artifacts.nodes {
    cancel.check().map_err(|_| ScipError::Cancelled)?;
    nodes.push(scip_node_to_graph_node(node, project_root));
  }

  let mut edges = Vec::with_capacity(artifacts.edges.len());
  for edge in &artifacts.edges {
    cancel.check().map_err(|_| ScipError::Cancelled)?;
    edges.push(scip_edge_to_graph_edge(edge, project_root));
  }

  Ok(GraphBatch {
    layer: GraphLayer::Semantic,
    nodes,
    edges,
  })
}

fn scip_node_to_graph_node(node: &ScipNodeInsert, project_root: &Path) -> GraphNodeRecord {
  let metadata = node.metadata.clone();
  let file_path = metadata
    .as_ref()
    .and_then(|value| value.get("filePath"))
    .and_then(|value| value.as_str())
    .map(|value| normalize_maybe_path(value, project_root));

  let language = metadata
    .as_ref()
    .and_then(|value| value.get("language"))
    .and_then(|value| value.as_str())
    .map(|value| value.to_string());

  let range = node.start_line.map(|start| Range {
    start: Position {
      row: start.saturating_sub(1),
      column: 0,
    },
    end: Position {
      row: node.end_line.unwrap_or(start).saturating_sub(1),
      column: 0,
    },
  });

  GraphNodeRecord {
    id: node.id.clone(),
    kind: node.node_type.clone(),
    name: node.name.clone(),
    file_path,
    range,
    language,
    sources: vec![GraphSource::Scip],
    metadata: metadata.clone(),
    metadata_by_source: Some(HashMap::from([(
      "scip".to_string(),
      metadata.unwrap_or_else(|| Value::Object(serde_json::Map::new())),
    )])),
  }
}

fn scip_edge_to_graph_edge(edge: &ScipEdgeInsert, project_root: &Path) -> GraphEdgeRecord {
  let metadata = normalize_edge_metadata(edge.metadata.clone(), project_root);
  GraphEdgeRecord {
    source_id: edge.source_id.clone(),
    target_id: edge.target_id.clone(),
    edge_type: edge.edge_type.clone(),
    sources: vec![GraphSource::Scip],
    metadata: metadata.clone(),
    metadata_by_source: Some(HashMap::from([(
      "scip".to_string(),
      metadata.unwrap_or_else(|| Value::Object(serde_json::Map::new())),
    )])),
  }
}

fn normalize_edge_metadata(metadata: Option<Value>, project_root: &Path) -> Option<Value> {
  let Some(Value::Object(mut map)) = metadata else {
    return metadata;
  };
  if let Some(Value::String(target_file)) = map.get("targetFile").cloned() {
    map.insert(
      "targetFile".to_string(),
      Value::String(normalize_maybe_path(&target_file, project_root)),
    );
  }
  if let Some(Value::String(resolved_path)) = map.get("resolvedPath").cloned() {
    map.insert(
      "resolvedPath".to_string(),
      Value::String(normalize_maybe_path(&resolved_path, project_root)),
    );
  }
  Some(Value::Object(map))
}

fn normalize_maybe_path(value: &str, project_root: &Path) -> String {
  let resolved = Path::new(value);
  let root = project_root;
  let resolved = if resolved.is_absolute() {
    resolved.to_path_buf()
  } else {
    root.join(resolved)
  };
  if let Ok(rel) = resolved.strip_prefix(root) {
    return rel.to_string_lossy().replace('\\', "/");
  }
  value.to_string()
}

