import { NextResponse } from "next/server"
import { z } from "zod"

import { traceGraph, CodeTraceError } from "@/lib/argus-search/trace-callers"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"

const tracePayloadSchema = z
  .object({
    mode: z.enum(["callers", "impact"]).optional(),
    symbol: z.string().trim().min(1).max(300).optional(),
    nodeId: z.string().trim().min(1).max(500).optional(),
    limit: z.number().int().positive().max(200).optional(),
    depth: z.number().int().positive().max(64).optional(),
  })
  .superRefine((value, ctx) => {
    if (!value.symbol && !value.nodeId) {
      ctx.addIssue({
        code: z.ZodIssueCode.custom,
        message: "Either symbol or nodeId is required.",
      })
    }
  })

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/trace-callers",
    event: "api.code.trace_callers",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => ({})),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }
      const parsed = tracePayloadSchema.safeParse(payload)

if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid trace payload." }, { status: 400 }),
  }
}

const { mode = "callers", symbol, nodeId, limit, depth } = parsed.data

try {
  const results = await traceGraph({
    mode,
    symbol,
    nodeId,
    limit,
    depth: mode === "impact" ? depth : undefined,
  })

  logger.set({
    mode,
    symbol: symbol ?? null,
    nodeId: nodeId ?? null,
    depth: mode === "impact" ? depth ?? 3 : null,
    callersCount: results.length,
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({
      data: {
        mode,
        symbol: symbol ?? null,
        nodeId: nodeId ?? null,
        depth: mode === "impact" ? depth ?? 3 : null,
        count: results.length,
        results,
      },
    }),
  }
} catch (error) {

        if (error instanceof CodeTraceError) {
          const status = error.code === "binary_missing" ? 503 : 502
          logger.set({
            traceErrorCode: error.code,
            traceErrorDetails: error.details,
          })

          return {
            status,
            outcome: "trace_failed",
            response: NextResponse.json(
              {
                error:
                  error.code === "binary_missing"
                    ? "Code intelligence SDK is unavailable."
                    : "Failed to trace code graph.",
              },
              { status },
            ),
          }
        }

        logger.set({
          traceErrorCode: "unknown",
        })

        return {
          status: 500,
          outcome: "trace_failed",
          response: NextResponse.json({ error: "Failed to trace code graph." }, { status: 500 }),
        }
      }
    },
  })
}

pub fn language_for(language_id: LanguageId) -> Language {
  match language_id {
    LanguageId::JavaScript => tree_sitter_javascript::LANGUAGE.into(),
    LanguageId::TypeScript => tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into(),
    LanguageId::Tsx => tree_sitter_typescript::LANGUAGE_TSX.into(),
    LanguageId::Python => tree_sitter_python::LANGUAGE.into(),
    LanguageId::Rust => tree_sitter_rust::LANGUAGE.into(),
    LanguageId::C => tree_sitter_c::LANGUAGE.into(),
    LanguageId::Cpp => tree_sitter_cpp::LANGUAGE.into(),
    LanguageId::Java => tree_sitter_java::LANGUAGE.into(),
    LanguageId::CSharp => tree_sitter_c_sharp::LANGUAGE.into(),
    LanguageId::Ada => tree_sitter_ada::LANGUAGE.into(),
  }
}

pub fn create_parser(language_id: LanguageId) -> Option<Parser> {
  let mut parser = Parser::new();
  parser.set_language(&language_for(language_id)).ok()?;
  Some(parser)
}

pub fn is_language_available(_language_id: LanguageId) -> bool {
  true
}

pub fn parse_language_name(value: &str) -> Option<LanguageId> {
  let normalized = value.trim().to_lowercase();
  match normalized.as_str() {
    "javascript" | "js" | "jsx" => Some(LanguageId::JavaScript),
    "typescript" | "ts" => Some(LanguageId::TypeScript),
    "tsx" => Some(LanguageId::Tsx),
    "python" | "py" => Some(LanguageId::Python),
    "rust" | "rs" => Some(LanguageId::Rust),
    "c" => Some(LanguageId::C),
    "cpp" | "c++" | "cxx" | "cc" => Some(LanguageId::Cpp),
    "java" => Some(LanguageId::Java),
    "csharp" | "c#" | "c-sharp" | "cs" => Some(LanguageId::CSharp),
    "ada" => Some(LanguageId::Ada),
    _ => None,
  }
}

pub fn normalize_extension(value: &str) -> String {
  value.trim().trim_start_matches('.').to_lowercase()
}

pub fn detect_language_from_path(path: &str) -> Option<LanguageId> {
  let extension = Path::new(path).extension()?.to_string_lossy();
  let extension = normalize_extension(extension.as_ref());
  match extension.as_str() {
    "js" | "mjs" | "cjs" | "jsx" => Some(LanguageId::JavaScript),
    "ts" | "mts" | "cts" => Some(LanguageId::TypeScript),
    "tsx" => Some(LanguageId::Tsx),
    "py" => Some(LanguageId::Python),
    "rs" => Some(LanguageId::Rust),
    "c" | "h" => Some(LanguageId::C),
    "cpp" | "cc" | "cxx" | "c++" | "hpp" | "hh" | "hxx" | "h++" => Some(LanguageId::Cpp),
    "java" => Some(LanguageId::Java),
    "cs" | "csx" => Some(LanguageId::CSharp),
    "adb" | "ads" | "ada" => Some(LanguageId::Ada),
    _ => None,
  }
}

