import { relations } from "drizzle-orm";
import { pgTable, text, timestamp, boolean, index } from "drizzle-orm/pg-core";

export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").notNull(),
  updatedAt: timestamp("updated_at")
    .$onUpdate(() => new Date())
    .notNull(),
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => [index("session_userId_idx").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

export const userRelations = relations(user, ({ many }) => ({
  sessions: many(session),
  accounts: many(account),
}));

export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, {
    fields: [session.userId],
    references: [user.id],
  }),
}));

export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, {
    fields: [account.userId],
    references: [user.id],
  }),
}));

"use client"

import type { ReactNode } from "react"
import { useCallback, useEffect, useRef, useSyncExternalStore } from "react"
import { usePathname, useRouter, useSearchParams } from "next/navigation"

import { AppShell } from "@/components/app-shell"
import { QueryProvider } from "@/components/query-provider"
import { TooltipProvider } from "@/components/ui/tooltip"
import { trackAnalyticsEvent } from "@/lib/analytics/client"
import { authClient } from "@/lib/auth-client"
import { consumeRouteNavigationSample } from "@/lib/navigation/perf-navigation"
import { isOnboardingPath, isSettingsPath, isUnauthenticatedRouteAllowed } from "./layout.utils"

type AppLayoutClientProps = {
  children: ReactNode
  isAuthenticated: boolean
}

const emptySubscribe = () => () => {}
const getClientSnapshot = () => true
const getServerSnapshot = () => false

const ANALYTICS_SESSION_ID_KEY = "argus.analytics.session_id"

const getOrCreateAnalyticsSessionId = () => {
  if (typeof window === "undefined") {
    return null
  }

  const existing = window.sessionStorage.getItem(ANALYTICS_SESSION_ID_KEY)
  if (existing && existing.trim().length > 0) {
    return existing
  }

  const generated =
    typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
      ? crypto.randomUUID()
      : `${Date.now()}-${Math.random().toString(16).slice(2)}`

  window.sessionStorage.setItem(ANALYTICS_SESSION_ID_KEY, generated)
  return generated
}

export function AppLayoutClient({
  children,
  isAuthenticated,
}: Readonly<AppLayoutClientProps>) {

const { data: clientSession, isPending: clientSessionPending } = authClient.useSession()
const hasHydrated = useSyncExternalStore(emptySubscribe, getClientSnapshot, getServerSnapshot)
const router = useRouter()
const pathname = usePathname()
const searchParams = useSearchParams()
const effectiveAuthenticated = hasHydrated
  ? (clientSessionPending
    ? isAuthenticated
    : Boolean(clientSession?.user?.id))
  : isAuthenticated
const onboardingRoute = hasHydrated && isOnboardingPath(pathname)
const settingsRoute = hasHydrated && isSettingsPath(pathname)
const allowUnauthenticatedRoute = isUnauthenticatedRouteAllowed(pathname)
const shellOnlyRoute = onboardingRoute || (effectiveAuthenticated && settingsRoute)
const sessionIdRef = useRef<string | null>(null)
const activeFeatureRef = useRef<string | null>(null)
const featureEnteredAtRef = useRef<number | null>(null)

const flushFeatureDuration = useCallback(() => {
  const feature = activeFeatureRef.current
  const startedAt = featureEnteredAtRef.current
  if (!feature || startedAt === null) {
    return
  }

  const durationMs = Math.max(0, Date.now() - startedAt)
  trackAnalyticsEvent({
    event: "session_duration",
    feature,
    durationMs,
    sessionId: sessionIdRef.current ?? undefined,
  })
}, [])

useEffect(() => {
  if (effectiveAuthenticated || pathname === "/" || isOnboardingPath(pathname)) {
    return
  }

  const search = searchParams.toString()
  const nextPath = `${pathname}${search ? `?${search}` : ""}`
  router.replace(`/?next=${encodeURIComponent(nextPath)}`)
}, [effectiveAuthenticated, pathname, router, searchParams])

useEffect(() => {
  if (!effectiveAuthenticated) {
    return
  }
  if (!sessionIdRef.current) {
    sessionIdRef.current = getOrCreateAnalyticsSessionId()
  }
}, [effectiveAuthenticated])

useEffect(() => {
  if (!effectiveAuthenticated) {
    return
  }

  if (!sessionIdRef.current) {
    sessionIdRef.current = getOrCreateAnalyticsSessionId()
  }

  flushFeatureDuration()

  activeFeatureRef.current = pathname
  featureEnteredAtRef.current = Date.now()

  trackAnalyticsEvent({
    event: "feature_opened",
    feature: pathname,
    sessionId: sessionIdRef.current ?? undefined,
  })

  const navigationSample = consumeRouteNavigationSample(pathname)
  if (navigationSample) {
    trackAnalyticsEvent({
      event: "command_used",
      command: "route_navigation",
      feature: pathname,
      sessionId: sessionIdRef.current ?? undefined,
      metadata: {
        route: navigationSample.route,
        isWarm: navigationSample.prefetchHit,
        prefetchHit: navigationSample.prefetchHit,
        navDurationMs: navigationSample.navDurationMs,
        source: navigationSample.source,
      },
    })
  }
}, [effectiveAuthenticated, flushFeatureDuration, pathname])

useEffect(() => {
  if (!effectiveAuthenticated || typeof window === "undefined") {
    return
  }

  const handleBeforeUnload = () => {
    flushFeatureDuration()
  }

  window.addEventListener("beforeunload", handleBeforeUnload)
  return () => {
    window.removeEventListener("beforeunload", handleBeforeUnload)
    flushFeatureDuration()
  }
}, [effectiveAuthenticated, flushFeatureDuration])

if (!effectiveAuthenticated && !allowUnauthenticatedRoute) {
  return null
}

  if (shellOnlyRoute) {
    return (
      <QueryProvider>
        <TooltipProvider>
          <div className="group/sidebar-wrapper has-data-[variant=inset]:bg-sidebar flex min-h-svh w-full">
            <main className="bg-background relative flex w-full flex-1 flex-col max-h-svh overflow-hidden md:[max-height:calc(100svh-1rem)] md:m-2 md:rounded-xl md:shadow-sm">
              {onboardingRoute ? <div className="h-12 shrink-0" /> : null}
              <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
                <div className="@container/main flex min-h-0 flex-1 flex-col gap-2 overflow-hidden">
                  <div className="flex min-h-0 flex-1 flex-col gap-4 overflow-auto px-4 py-4 md:gap-6 md:py-6 lg:px-6">
                    {children}
                  </div>
                </div>
              </div>
            </main>
          </div>
        </TooltipProvider>
      </QueryProvider>
    )
  }

  if (!effectiveAuthenticated) {
    return <QueryProvider>{children}</QueryProvider>
  }

  return (
    <QueryProvider>
      <AppShell>{children}</AppShell>
    </QueryProvider>
  )
}

