import { normalizeGitLabInstanceUrl } from "@/lib/gitlab/instance"

type MergeRequestBridgeIntegrationLike = {
  instanceUrl: string
  projectPath: string
  status?: string
}

const normalizeProjectPath = (value: string) =>
  value
    .trim()
    .replace(/^\/+|\/+$/g, "")
    .replace(/\/+/g, "/")
    .toLowerCase()

const normalizeInstanceUrl = (value: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    return ""
  }

  try {
    return normalizeGitLabInstanceUrl(trimmed).toLowerCase()
  } catch {
    const withProtocol = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`
    try {
      const parsed = new URL(withProtocol)
      parsed.hash = ""
      parsed.search = ""
      const pathname = parsed.pathname.replace(/\/+$/, "")
      return pathname ? `${parsed.origin}${pathname}`.toLowerCase() : parsed.origin.toLowerCase()
    } catch {
      return trimmed.replace(/\/+$/, "").toLowerCase()
    }
  }
}

export const resolveMergeRequestBridgeIntegration = <T extends MergeRequestBridgeIntegrationLike>({
  integrations,
  projectPath,
  instanceUrl,
}: {
  integrations: readonly T[]
  projectPath: string
  instanceUrl?: string
}) => {
  const normalizedProjectPath = normalizeProjectPath(projectPath)
  if (!normalizedProjectPath) {
    return undefined
  }

  const projectMatches = integrations.filter(
    (integration) => normalizeProjectPath(integration.projectPath) === normalizedProjectPath,
  )

  if (projectMatches.length === 0) {
    return undefined
  }

  const requestedInstance = instanceUrl?.trim()
  if (requestedInstance) {
    const normalizedRequestedInstance = normalizeInstanceUrl(requestedInstance)
    if (!normalizedRequestedInstance) {
      return undefined
    }

    return projectMatches.find(
      (integration) => normalizeInstanceUrl(integration.instanceUrl) === normalizedRequestedInstance,
    )
  }

  if (projectMatches.length === 1) {
    return projectMatches[0]
  }

  const activeMatches = projectMatches.filter((integration) => integration.status === "active")
  if (activeMatches.length === 1) {
    return activeMatches[0]
  }

  return undefined
}

