    process.env.INDEXER_EMBEDDING_API_KEY = 'indexer-key'
    process.env.OPENAI_API_KEY = 'openai-key'
    process.env.AI_API_TOKEN = 'ai-api-token'

    expect(__testables.resolveApiKey()).toBe('indexer-key')
  })

  test('falls back to OPENAI_API_KEY, then AI_API_TOKEN', () => {
    delete process.env.INDEXER_EMBEDDING_API_KEY
    process.env.OPENAI_API_KEY = 'openai-key'
    process.env.AI_API_TOKEN = 'ai-api-token'

    expect(__testables.resolveApiKey()).toBe('openai-key')

    delete process.env.OPENAI_API_KEY
    expect(__testables.resolveApiKey()).toBe('ai-api-token')
  })
})

export async function PUT(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/preferences/global",
    event: "api.review.preferences.global.put",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => null) as Promise<unknown>,
      ])

      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const parsed = parseReviewGateSettings(payload)
      if (!parsed.settings) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: parsed.error ?? "Invalid payload." }, { status: 400 }),
        }
      }

      await upsertReviewGateGlobalSettings({
        userId,
        settings: parsed.settings,
      })

      const resolved = await resolveReviewGatePreferences({
        userId,
        scope: null,
      })

      logger.set({
        scopeSource: resolved.effectiveSettings.scopeSource,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            global: resolved.globalSettings,
            effective: resolved.effectiveSettings,
          },
        }),
      }
    },
  })
}

