import { indexStream } from '@argus/argus-search/stream'

for await (const item of indexStream(
  {
    projectRoot: '/repo',
    inputs: { paths: ['src'], include: ['*.ts', '*.tsx'], exclude: ['node_modules', 'dist', '.git'] },
    phases: { parse: true, graph: true, vector: true, scip: false, indexPack: false },
    vector: {
      provider: { kind: 'http', baseUrl: 'http://127.0.0.1:8080', model: 'text-embedding-3-small', dimension: 1536 },
    },
  },
  { highWaterMark: 16 },
)) {
  if (item.type === 'vector:batch') {
    for (const record of item.batch) {
      // record.chunk is present in the stream (includes content by default)
      await writeVector(record)
    }
  }
  if (item.type === 'pipeline:complete') break
}
