### Agent integration pattern (RAG)

The indexing pipeline is intended to feed an _agent-facing retrieval tool_:

1. Run `indexStream()` with `phases.vector=true` to emit `vector:batch` records (chunk + embedding).
2. Write those records into your vector store (pgvector/Qdrant/etc), keyed by `chunkId` + `filePath`.
3. Expose a tool like `code_search(query, topK)` that returns the top-matching chunks + metadata.
4. Let your agent call `code_search` before answering/editing code.

import { and, eq, inArray } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexBranchStates,
  indexRunFileChanges,
  indexRuns,
  indexVectors,
} from '@/lib/db/schema'
import type { ArtifactStore, GitLabSource, IngestJob, VectorStore } from '@/lib/indexing/contracts'
import {
  DeltaSnapshotFallbackError,
  runDeltaIngest,
} from '@/lib/indexing/delta'
import {
  finalizeIndexRun,
  markIndexRunFailed,
} from '@/lib/indexing/finalize'
import { buildRunGraphArtifacts } from '@/lib/indexing/graph-build'
import { prepareRepoWorkspace, type RepoWorkspace, type RepoWorkspaceMetrics } from '@/lib/indexing/repo-workspace'
import { runSnapshotIngest } from '@/lib/indexing/snapshot'
import { createArtifactStore } from '@/lib/indexing/stores/artifact-store'
import { createPostgresVectorStore } from '@/lib/indexing/stores/vector-store.pg'
import { createGitLabSource } from '@/lib/indexing/sources/gitlab-source'
import type { IngestResult, IngestRunMetrics } from '@/lib/indexing/types'

type IngestProcessorDeps = {
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
}

export type IngestStepEvent = {
  stage: 'ingest' | 'graph' | 'finalize' | 'gc'
  step: string
  message: string
  path?: string
  stats?: Record<string, number> | null
  details?: Record<string, unknown> | null
}

const asRecord = (value: unknown): Record<string, unknown> | null => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return null
  }

  return value as Record<string, unknown>
}

const defaultDeps = (): IngestProcessorDeps => ({
  source: createGitLabSource(),
  vectorStore: createPostgresVectorStore(),
  artifactStore: createArtifactStore(),
})

const getErrorDetails = (error: unknown): Record<string, unknown> | null => {
  if (!(error instanceof Error)) {
    return null
  }

  return asRecord((error as Error & { details?: unknown }).details)
}

const asNumber = (value: unknown) =>
  typeof value === 'number' && Number.isFinite(value) ? value : null

const statValue = (stats: Record<string, number> | null, key: string): number => {
  const value = asNumber(stats?.[key])
  return value === null ? 0 : value
}

const resolveIngestMetrics = (
  stats: Record<string, number> | null,
): IngestRunMetrics | null => {
  if (!stats) {
    return null
  }

  const filesProcessed = (() => {
    const explicit = statValue(stats, 'filesProcessed')
    if (explicit > 0) {
      return explicit
    }

    const filesScanned = statValue(stats, 'filesScanned')
    const filesFetched = statValue(stats, 'filesFetched')
    return Math.max(filesScanned, filesFetched)
  })()

  const embeddingCostUsd = asNumber(stats.embeddingCostUsd)

  return {
    durationMs: null,
    filesProcessed,
    failures: statValue(stats, 'embeddingFailures'),
    embeddingApiCalls: statValue(stats, 'embeddingApiCalls'),
    pendingJobs: null,
    processingJobs: null,
    embeddingPromptTokens: statValue(stats, 'embeddingPromptTokens'),
    embeddingTotalTokens: statValue(stats, 'embeddingTotalTokens'),
    embeddingCostUsd:
      embeddingCostUsd !== null && embeddingCostUsd >= 0 ? Number(embeddingCostUsd.toFixed(8)) : null,
  }
}

const resolveGraphRequired = (): boolean => {
  const value = process.env.INDEXER_GRAPH_REQUIRED?.trim().toLowerCase()
  if (!value) {
    return true
  }

  if (value === '0' || value === 'false' || value === 'no' || value === 'off') {
    return false
  }

  return true
}

const isEnvTruthy = (value: string | undefined): boolean => {
  if (!value) {
    return false
  }

  const normalized = value.trim().toLowerCase()
  return normalized === '1' || normalized === 'true' || normalized === 'yes' || normalized === 'on'
}

const resolveSingleArchiveEnabled = (integrationId: string): boolean => {
  if (!isEnvTruthy(process.env.INDEXER_SINGLE_ARCHIVE_ENABLED)) {
    return false
  }

  const allowlist = process.env.INDEXER_SINGLE_ARCHIVE_ALLOWLIST
    ?.split(',')
    .map((entry) => entry.trim())
    .filter(Boolean)

  if (!allowlist || allowlist.length === 0) {
    return true
  }

  return allowlist.includes(integrationId)
}

const resolveGraphRequiredForRun = (useSharedWorkspace: boolean): boolean => {
  if (!useSharedWorkspace) {
    return resolveGraphRequired()
  }

  const value = process.env.INDEXER_GRAPH_REQUIRED?.trim().toLowerCase()
  if (value === '1' || value === 'true' || value === 'yes' || value === 'on') {
    return true
  }

  const mode = process.env.INDEXER_GRAPH_FAIL_MODE?.trim().toLowerCase()
  return mode === 'hard'
}

const CANCELLATION_ERROR_CODE = 'RUN_CANCELLED_BY_USER'
const CANCELLATION_ERROR_MESSAGE = 'Indexing run cancelled by user request.'
const CANCELLATION_POLL_INTERVAL_MS = 1_000

class IngestRunCancelledError extends Error {
  readonly runId: string

  constructor(runId: string) {
    super(CANCELLATION_ERROR_MESSAGE)
    this.name = 'IngestRunCancelledError'
    this.runId = runId
  }
}

const toErrorPayload = (error: unknown) => {
  const details = getErrorDetails(error)
  if (error instanceof Error) {
    return {
      code: 'INGEST_FAILED',
      message: error.message.slice(0, 500),
      stack: error.stack?.slice(0, 1000) ?? null,
      details,
    }
  }

  return {
    code: 'INGEST_FAILED',
    message: 'Unexpected ingest failure.',
    stack: null,
    details,
  }
}

const cleanupStaleVectorsForRun = async (args: {
  runId: string
  branchStateId: string
  vectorStore: VectorStore
}) => {
  const stagedChanges = await db
    .select({
      path: indexRunFileChanges.path,
      changeType: indexRunFileChanges.changeType,
      fileId: indexRunFileChanges.fileId,
    })
    .from(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, args.runId))

  for (const change of stagedChanges) {
    await args.vectorStore.deleteStaleByPath({
      branchStateId: args.branchStateId,
      path: change.path,
      keepFileId: change.changeType === 'upsert' ? change.fileId : null,
    })
  }
}

const cleanupCancelledRunArtifacts = async (runId: string) => {
  await Promise.all([
    db.delete(indexRunFileChanges).where(eq(indexRunFileChanges.runId, runId)),
    db.delete(indexVectors).where(eq(indexVectors.runId, runId)),
  ])
}

const toCancelledResult = (args: {
  runId: string
  ingestMode: 'snapshot' | 'delta' | null
  modeFallback: 'snapshot' | null
  modeFallbackReason: string | null
  indexingMetrics: IngestRunMetrics | null
}) => ({
  runId: args.runId,
  status: 'cancelled' as const,
  ingestMode: args.ingestMode,
  modeFallback: args.modeFallback,
  modeFallbackReason: args.modeFallbackReason,
  finalizeStatus: null,
  gcStatus: 'not_applicable' as const,
  errorCode: CANCELLATION_ERROR_CODE,
  errorMessage: CANCELLATION_ERROR_MESSAGE,
  errorDetails: null,
  indexingMetrics: args.indexingMetrics,
})

export const processIngestJob = async (
  job: IngestJob & { onStep?: (event: IngestStepEvent) => void },
  deps: IngestProcessorDeps = defaultDeps(),
): Promise<IngestResult> => {
  const emitStep = (event: IngestStepEvent) => {
    if (!job.onStep) {
      return
    }

    try {
      job.onStep(event)
    } catch {
      // Progress logging should never block ingest processing.
    }
  }

  const [run] = await db
    .select({
      id: indexRuns.id,
      status: indexRuns.status,
      mode: indexRuns.mode,
      branchStateId: indexRuns.branchStateId,
      baseSha: indexRuns.baseSha,
      headSha: indexRuns.headSha,
      artifactsPrefix: indexRuns.artifactsPrefix,
      configHash: indexBranchStates.configHash,
      integrationId: indexBranchStates.integrationId,
    })
    .from(indexRuns)
    .innerJoin(indexBranchStates, eq(indexRuns.branchStateId, indexBranchStates.id))
    .where(eq(indexRuns.id, job.runId))
    .limit(1)

const checkCancellation = async (force = false) => {
  if (isCancelled) {
    return true
  }

  const now = Date.now()
  if (!force && now - lastCancellationCheckAt < CANCELLATION_POLL_INTERVAL_MS) {
    return false
  }

  lastCancellationCheckAt = now
  const [statusRow] = await db
    .select({ status: indexRuns.status })
    .from(indexRuns)
    .where(eq(indexRuns.id, run.id))
    .limit(1)
  isCancelled = statusRow?.status === 'cancelled'
  return isCancelled
}

const assertNotCancelled = async (force = false) => {
  if (await checkCancellation(force)) {
    throw new IngestRunCancelledError(run.id)
  }
}

await assertNotCancelled()

const [indexingStarted] = await db
  .update(indexRuns)
  .set({
    status: 'indexing',
    updatedAt: new Date(),
  })
  .where(
    and(
      eq(indexRuns.id, run.id),
      inArray(indexRuns.status, ['planned', 'ingesting']),
    ),
  )
  .returning({
    id: indexRuns.id,
  })

if (!indexingStarted) {
  if (await checkCancellation(true)) {
    return toCancelledResult({
      runId: run.id,
      ingestMode: run.mode,
      modeFallback: null,
      modeFallbackReason: null,
      indexingMetrics: null,
    })
  }

  return {
    runId: run.id,
    status: 'skipped',
    ingestMode: run.mode,
    modeFallback: null,
    modeFallbackReason: null,
    finalizeStatus: 'invalid_state',
    gcStatus: 'not_applicable',
    errorCode: null,
    errorMessage: null,
    errorDetails: null,
    indexingMetrics: null,
  }
}

emitStep({
  stage: 'ingest',
  step: 'run_indexing_started',
  message: `Run entered indexing (${run.mode}).`,
  details: {
    runMode: run.mode,
  },
})

let modeFallback: 'snapshot' | null = null
let modeFallbackReason: string | null = null
let indexingMetrics: IngestRunMetrics | null = null
const useSharedWorkspace = resolveSingleArchiveEnabled(run.integrationId)

try {
  let ingestStats: Record<string, number>

  await assertNotCancelled()

if (useSharedWorkspace) {
  sharedWorkspace = await prepareRepoWorkspace({
    source: deps.source,
    integrationId: run.integrationId,
    sha: run.headSha,
  })
  repoMaterialization = sharedWorkspace.metrics
  emitStep({
    stage: 'ingest',
    step: 'repo_workspace_ready',
    message: 'Repository workspace prepared.',
    details: {
      downloadMs: repoMaterialization.downloadMs,
      extractMs: repoMaterialization.extractMs,
      archiveBytes: repoMaterialization.archiveBytes,
    },
  })
}

const runContext = {
  runId: run.id,
  branchStateId: run.branchStateId,
  integrationId: run.integrationId,
  configHash: run.configHash,
  baseSha: run.baseSha,
  headSha: run.headSha,
  artifactsPrefix: run.artifactsPrefix,
}

if (run.mode === 'delta') {
  emitStep({
    stage: 'ingest',
    step: 'delta_started',
    message: 'Delta ingest started.',
  })

try {
  const delta = await runDeltaIngest({
    run: runContext,
    source: deps.source,
    vectorStore: deps.vectorStore,
    artifactStore: deps.artifactStore,
    workspace: sharedWorkspace ?? undefined,
    shouldAbort: () => assertNotCancelled(true),
    onProgress: (event) => {
      emitStep({
        stage: 'ingest',
        step: event.step,
        message: event.message,
        path: event.path,
        stats: event.stats,
        details: event.details ?? null,
      })
    },
  })
  ingestStats = delta.stats
} catch (error) {

  if (!(error instanceof DeltaSnapshotFallbackError)) {
    throw error
  }

  emitStep({
    stage: 'ingest',
    step: 'delta_fallback',
    message: `Delta fallback to snapshot (${error.reason}).`,
    details: {
      reason: error.reason,
    },
  })
  const snapshot = await runSnapshotIngest({
    run: runContext,
    source: deps.source,
    vectorStore: deps.vectorStore,
    artifactStore: deps.artifactStore,
    workspace: sharedWorkspace ?? undefined,
    shouldAbort: () => assertNotCancelled(true),
    onProgress: (event) => {
      emitStep({
        stage: 'ingest',
        step: event.step,
        message: event.message,
        path: event.path,
        stats: event.stats,
        details: event.details ?? null,
      })
    },
  })

  ingestStats = snapshot.stats
  modeFallback = 'snapshot'
  modeFallbackReason = error.reason
}

} else {
  emitStep({
    stage: 'ingest',
    step: 'snapshot_started',
    message: 'Snapshot ingest started.',
  })
  const snapshot = await runSnapshotIngest({
    run: runContext,
    source: deps.source,
    vectorStore: deps.vectorStore,
    artifactStore: deps.artifactStore,
    workspace: sharedWorkspace ?? undefined,
    shouldAbort: () => assertNotCancelled(true),
    onProgress: (event) => {
      emitStep({
        stage: 'ingest',
        step: event.step,
        message: event.message,
        path: event.path,
        stats: event.stats,
        details: event.details ?? null,
      })
    },
  })

  ingestStats = snapshot.stats
}
emitStep({
  stage: 'ingest',
  step: 'ingest_stats_ready',
  message: 'Ingest stats computed.',
  stats: ingestStats,
})

const graphRequired = resolveGraphRequiredForRun(useSharedWorkspace)
let graphSummary: Awaited<ReturnType<typeof buildRunGraphArtifacts>> | null = null
let graphError: string | null = null
emitStep({
  stage: 'graph',
  step: 'graph_build_started',
  message: graphRequired
    ? 'Graph artifact build started.'
    : 'Graph artifact build started (optional).',
  details: {
    required: graphRequired,
  },
})

try {
  graphSummary = await buildRunGraphArtifacts({
    source: deps.source,
    integrationId: run.integrationId,
    headSha: run.headSha,
    artifactsPrefix: run.artifactsPrefix,
    workspace: sharedWorkspace ?? undefined,
  })
  emitStep({
    stage: 'graph',
    step: 'graph_build_succeeded',
    message: 'Graph artifacts built.',
    details: {
      backend: graphSummary.backend,
      durationMs: graphSummary.durationMs,
    },
  })
} catch (error) {
  graphError = error instanceof Error ? error.message : 'Failed to build graph artifacts.'
  emitStep({
    stage: 'graph',
    step: 'graph_build_failed',
    message: graphError,
    details: {
      required: graphRequired,
    },
  })
  if (graphRequired) {
    throw error
  }
}

await assertNotCancelled()

} catch (error) {
  if (error instanceof IngestRunCancelledError) {
    await cleanupCancelledRunArtifacts(run.id)
    emitStep({
      stage: 'ingest',
      step: 'ingest_cancelled',
      message: CANCELLATION_ERROR_MESSAGE,
    })
    return toCancelledResult({
      runId: run.id,
      ingestMode: run.mode,
      modeFallback,
      modeFallbackReason,
      indexingMetrics,
    })
  }

  const errorPayload = toErrorPayload(error)
  emitStep({
    stage: 'ingest',
    step: 'ingest_failed',
    message: errorPayload.message,
    details: asRecord(errorPayload.details),
  })
  await markIndexRunFailed(run.id, errorPayload)

  return {
    runId: run.id,
    status: 'failed',
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
    finalizeStatus: null,
    gcStatus: 'not_applicable',
    errorCode: 'INGEST_FAILED',
    errorMessage: errorPayload.message,
    errorDetails: asRecord(errorPayload.details),
    indexingMetrics,
  }
}

if (await checkCancellation(true)) {
  await cleanupCancelledRunArtifacts(run.id)
  emitStep({
    stage: 'finalize',
    step: 'run_cancelled_before_finalize',
    message: CANCELLATION_ERROR_MESSAGE,
  })
  return toCancelledResult({
    runId: run.id,
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
    indexingMetrics,
  })
}

const finalized = await finalizeIndexRun(run.id)

emitStep({
  stage: 'finalize',
  step: 'run_finalized',
  message: `Finalize result: ${finalized.status}.`,
  details: {
    finalizeStatus: finalized.status,
  },
})
if (finalized.status === 'not_found' || finalized.status === 'invalid_state') {
  if (finalized.status === 'invalid_state' && (await checkCancellation(true))) {
    await cleanupCancelledRunArtifacts(run.id)
    return toCancelledResult({
      runId: run.id,
      ingestMode: run.mode,
      modeFallback,
      modeFallbackReason,
      indexingMetrics,
    })
  }

  return {
    runId: run.id,
    status: 'skipped',
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
    finalizeStatus: finalized.status,
    gcStatus: 'not_applicable',
    errorCode: finalized.status === 'not_found' ? 'FINALIZE_NOT_FOUND' : 'FINALIZE_INVALID_STATE',
    errorMessage: null,
    errorDetails: null,
    indexingMetrics,
  }
}

let gcStatus: IngestResult['gcStatus'] = 'not_applicable'
let errorCode: string | null = null
let errorMessage: string | null = null

  if (finalized.status === 'ready') {
    gcStatus = 'succeeded'
    emitStep({
      stage: 'gc',
      step: 'vector_gc_started',
      message: 'Vector cleanup started.',
    })
    try {
      await cleanupStaleVectorsForRun({
        runId: run.id,
        branchStateId: run.branchStateId,
        vectorStore: deps.vectorStore,
      })
      emitStep({
        stage: 'gc',
        step: 'vector_gc_succeeded',
        message: 'Vector cleanup succeeded.',
      })
    } catch (error) {
      gcStatus = 'failed'
      errorCode = 'VECTOR_GC_FAILED'
      errorMessage = error instanceof Error ? error.message.slice(0, 500) : 'Vector cleanup failed.'
      emitStep({
        stage: 'gc',
        step: 'vector_gc_failed',
        message: errorMessage,
      })
      await db
        .update(indexRuns)
        .set({
          error: {
            code: 'VECTOR_GC_FAILED',
            message: errorMessage,
          },
          updatedAt: new Date(),
        })
        .where(eq(indexRuns.id, run.id))
    }
  } else {
    gcStatus = 'skipped'
  }

  return {
    runId: run.id,
    status: finalized.status,
    ingestMode: run.mode,
    modeFallback,
    modeFallbackReason,
    finalizeStatus: finalized.status,
    gcStatus,
    errorCode,
    errorMessage,
    errorDetails: null,
    indexingMetrics,
  }
  } finally {
    if (sharedWorkspace) {
      await sharedWorkspace.cleanup().catch(() => {})
    }
  }
}

type PersistedGraphStore = {
  indexRunId: string
  generatedAt: string
  nodesById: Map<string, PersistedGraphNode>
  nodesByNormalizedFilePath: Map<string, PersistedGraphNode[]>
  nodeIds: string[]
  edges: PersistedGraphEdge[]
  outgoing: Map<string, PersistedGraphEdge[]>
  incoming: Map<string, PersistedGraphEdge[]>
  edgeTypes: string[]
}

let graphStoreCache: PersistedGraphStore | null = null

const resolveIndexPackDir = () => resolveCodeIntelIndexPackDir()
const resolveNodesPath = () => path.join(resolveIndexPackDir(), "graph.nodes.jsonl")
const resolveEdgesPath = () => path.join(resolveIndexPackDir(), "graph.edges.jsonl")
const normalizeGraphFilePath = (value: string) =>
  value
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")

const parseJsonLine = (line: string): unknown => {
  try {
    return JSON.parse(line)
  } catch {
    return null
  }
}

const readJsonl = async <T>(
  filePath: string,
  parse: (value: unknown) => T | null,
): Promise<T[]> => {
  const records: T[] = []

  const stream = createReadStream(filePath, { encoding: "utf8" })
  const rl = createInterface({ input: stream, crlfDelay: Infinity })

  try {
    for await (const line of rl) {
      const trimmed = line.trim()
      if (!trimmed) {
        continue
      }
      const parsed = parse(parseJsonLine(trimmed))
      if (parsed) {
        records.push(parsed)
      }
    }
  } catch (error) {
    throw new CodeGraphError("invalid_output", "Failed to parse persisted graph JSONL artifact.", {
      filePath,
      message: error instanceof Error ? error.message : "Unknown parsing error.",
    })
  } finally {
    rl.close()
    stream.destroy()
  }

  return records
}

const normalizeNode = (value: unknown): PersistedGraphNode | null => {
  const parsed = graphNodeRecordSchema.safeParse(value)
  if (!parsed.success) {
    return null
  }

  return {
    id: parsed.data.id,
    kind: parsed.data.kind,
    name: parsed.data.name ?? null,
    filePath: parsed.data.filePath ?? null,
    language: parsed.data.language ?? null,
    range: parsed.data.range ?? null,
  }
}

const normalizeEdge = (value: unknown): PersistedGraphEdge | null => {
  const parsed = graphEdgeRecordSchema.safeParse(value)
  if (!parsed.success) {
    return null
  }

  return {
    sourceId: parsed.data.sourceId,
    targetId: parsed.data.targetId,
    type: parsed.data.type,
  }
}

const sampleArray = <T>(items: T[], limit: number): T[] => {
  if (limit <= 0) {
    return []
  }
  if (items.length <= limit) {
    return [...items]
  }

  const out: T[] = []
  const step = items.length / limit
  for (let index = 0; index < limit; index += 1) {
    const sourceIndex = Math.floor(index * step)
    out.push(items[sourceIndex] as T)
  }
  return out
}

const resolveNode = (store: PersistedGraphStore, id: string): PersistedGraphNode =>
  store.nodesById.get(id) ?? {
    id,
    kind: "external",
    name: id,
    filePath: null,
    language: null,
    range: null,
  }

const normalizeEdgeTypeFilter = (edgeTypes: string[] | undefined, available: string[]) => {
  if (!edgeTypes?.length) {
    return null
  }
  const allowed = new Set(available)
  const normalized = edgeTypes
    .map((value) => value.trim())
    .filter((value) => value.length > 0 && allowed.has(value))

  return normalized.length > 0 ? new Set(normalized) : null
}

const filterEdgesByType = (
  edges: PersistedGraphEdge[],
  edgeTypeFilter: Set<string> | null,
): PersistedGraphEdge[] => {
  if (!edgeTypeFilter) {
    return edges
  }
  return edges.filter((edge) => edgeTypeFilter.has(edge.type))
}

const getPersistedGraphStore = async (): Promise<PersistedGraphStore> => {
  const summary = await getCodeGraphSummary()
  if (!summary) {
    throw new CodeGraphError("missing_index_pack", "Code graph index-pack not found. Refresh it first.", null)
  }

  if (graphStoreCache?.indexRunId === summary.indexRunId) {
    return graphStoreCache
  }

  const [nodes, edges] = await Promise.all([
    readJsonl(resolveNodesPath(), normalizeNode),
    readJsonl(resolveEdgesPath(), normalizeEdge),
  ])

  const nodesById = new Map<string, PersistedGraphNode>()
  const nodesByNormalizedFilePath = new Map<string, PersistedGraphNode[]>()
  for (const node of nodes) {
    nodesById.set(node.id, node)
    if (node.filePath) {
      const normalizedFilePath = normalizeGraphFilePath(node.filePath)
      const current = nodesByNormalizedFilePath.get(normalizedFilePath) ?? []
      current.push(node)
      nodesByNormalizedFilePath.set(normalizedFilePath, current)
    }
  }

  const outgoing = new Map<string, PersistedGraphEdge[]>()
  const incoming = new Map<string, PersistedGraphEdge[]>()
  const edgeTypeSet = new Set<string>()
  for (const edge of edges) {
    edgeTypeSet.add(edge.type)

    const out = outgoing.get(edge.sourceId) ?? []
    out.push(edge)
    outgoing.set(edge.sourceId, out)

    const inb = incoming.get(edge.targetId) ?? []
    inb.push(edge)
    incoming.set(edge.targetId, inb)
  }

  const store: PersistedGraphStore = {
    indexRunId: summary.indexRunId,
    generatedAt: summary.generatedAt,
    nodesById,
    nodesByNormalizedFilePath,
    nodeIds: [...nodesById.keys()],
    edges,
    outgoing,
    incoming,
    edgeTypes: [...edgeTypeSet].sort((a, b) => a.localeCompare(b)),
  }
  graphStoreCache = store

  return store
}

export type GraphNeighborhoodDirection = "incoming" | "outgoing" | "both"
export type GraphImpactPreset = "callers" | "callees" | "dependencies" | "dependents" | "impact"

export type PersistedGraphQueryResult = {
  indexRunId: string
  generatedAt: string
  totalNodes: number
  totalEdges: number
  availableEdgeTypes: string[]
  appliedEdgeTypes: string[]
  nodes: PersistedGraphNode[]
  edges: PersistedGraphEdge[]
}

export const getPersistedGraphEdgeTypes = async () => {
  const store = await getPersistedGraphStore()
  return {
    indexRunId: store.indexRunId,
    generatedAt: store.generatedAt,
    edgeTypes: store.edgeTypes,
  }
}

export type PersistedGraphFindingNodeMatch = {
  nodeId: string
  scope: "symbol" | "file"
  sourceFile: string
  sourceLine: number
}

type PersistedGraphTraversalDirection = "incoming" | "outgoing" | "both"

const includesLine = (node: PersistedGraphNode, lineNumber: number) => {
  if (!node.range) {
    return false
  }
  const safeLine = Math.max(1, Math.floor(lineNumber))
  const zeroBasedLine = safeLine - 1
  return zeroBasedLine >= node.range.start.row && zeroBasedLine <= node.range.end.row
}

const nodeSpanRows = (node: PersistedGraphNode) => {
  if (!node.range) {
    return Number.POSITIVE_INFINITY
  }
  return Math.max(0, node.range.end.row - node.range.start.row)
}

const nodeKindRank = (kind: string) => {
  switch (kind.toLowerCase()) {
    case "function":
    case "method":
      return 0
    case "class":
    case "interface":
    case "type":
      return 1
    case "variable":
    case "constant":
      return 2
    case "file":
      return 9
    default:
      return 4
  }
}

const pickBestNode = (nodes: PersistedGraphNode[]) => {
  if (nodes.length === 0) {
    return null
  }
  return [...nodes].sort((left, right) => {
    const spanDelta = nodeSpanRows(left) - nodeSpanRows(right)
    if (spanDelta !== 0) {
      return spanDelta
    }

    const rankDelta = nodeKindRank(left.kind) - nodeKindRank(right.kind)
    if (rankDelta !== 0) {
      return rankDelta
    }

    const leftName = left.name ?? ""
    const rightName = right.name ?? ""
    return leftName.localeCompare(rightName)
  })[0] ?? null
}

const collectReachableNodeIds = ({
  store,
  startNodeId,
  direction,
  edgeTypes,
  depth,
  maxNodes,
}: {
  store: PersistedGraphStore
  startNodeId: string
  direction: PersistedGraphTraversalDirection
  edgeTypes: Set<string>
  depth: number
  maxNodes: number
}) => {

  const queue: Array<{ id: string; depth: number }> = [{ id: startNodeId, depth: 0 }]
  const visited = new Set<string>([startNodeId])
  const reached = new Set<string>()

  while (queue.length > 0 && reached.size < maxNodes) {
    const current = queue.shift()
    if (!current) {
      break
    }
    if (current.depth >= depth) {
      continue
    }

    if (direction !== "incoming") {
      const outgoing = store.outgoing.get(current.id) ?? []
      for (const edge of outgoing) {
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        const nextId = edge.targetId
        if (nextId !== startNodeId) {
          reached.add(nextId)
        }
        if (!visited.has(nextId) && visited.size < maxNodes) {
          visited.add(nextId)
          queue.push({ id: nextId, depth: current.depth + 1 })
        }
      }
    }

    if (direction !== "outgoing") {
      const incoming = store.incoming.get(current.id) ?? []
      for (const edge of incoming) {
        if (!edgeTypes.has(edge.type)) {
          continue
        }
        const nextId = edge.sourceId
        if (nextId !== startNodeId) {
          reached.add(nextId)
        }
        if (!visited.has(nextId) && visited.size < maxNodes) {
          visited.add(nextId)
          queue.push({ id: nextId, depth: current.depth + 1 })
        }
      }
    }
  }

  return reached
}

export const findPersistedGraphNodeForFinding = async (options: {
  filePath: string
  line: number
  title?: string
}): Promise<PersistedGraphFindingNodeMatch | null> => {
  const normalizedFilePath = normalizeGraphFilePath(options.filePath)
  if (!normalizedFilePath) {
    return null
  }

  const store = await getPersistedGraphStore()
  const nodesInFile = store.nodesByNormalizedFilePath.get(normalizedFilePath) ?? []
  if (nodesInFile.length === 0) {
    return null
  }

  const symbolNodes = nodesInFile.filter((node) => node.kind !== "file" && includesLine(node, options.line))
  const normalizedTitle = (options.title ?? "").trim().toLowerCase()
  const symbolNameMatched = normalizedTitle
    ? symbolNodes.filter((node) => {
      const name = (node.name ?? "").trim().toLowerCase()
      return name.length > 0 && normalizedTitle.includes(name)
    })
    : []

  const symbolSourceNode = pickBestNode(symbolNameMatched) ?? pickBestNode(symbolNodes)
  if (symbolSourceNode) {
    return {
      nodeId: symbolSourceNode.id,
      scope: "symbol",
      sourceFile: symbolSourceNode.filePath ?? normalizedFilePath,
      sourceLine: options.line,
    }
  }

  const fileNode = nodesInFile.find((node) => node.kind === "file") ?? nodesInFile[0]
  if (!fileNode) {
    return null
  }

  return {
    nodeId: fileNode.id,
    scope: "file",
    sourceFile: fileNode.filePath ?? normalizedFilePath,
    sourceLine: options.line,
  }
}

export type PersistedGraphImpactSummary = {
  callersCount: number
  calleesCount: number
  dependentsCount: number
  dependenciesCount: number
  affectedFilesCount: number
  affectedSymbolsCount: number
  topImpactedFiles: Array<{ filePath: string; count: number }>
}

export const summarizePersistedGraphImpactForNode = async (options: {
  nodeId: string
  callDepth?: number
  importDepth?: number
  impactDepth?: number
  maxNodes?: number
}): Promise<PersistedGraphImpactSummary> => {
  const store = await getPersistedGraphStore()
  const nodeId = options.nodeId.trim()
  if (!nodeId) {
    throw new CodeGraphError("command_failed", "Impact summary requires a non-empty nodeId.", null)
  }

  const callDepth = Math.min(6, Math.max(1, options.callDepth ?? 2))
  const importDepth = Math.min(6, Math.max(1, options.importDepth ?? 2))
  const impactDepth = Math.min(6, Math.max(1, options.impactDepth ?? 2))
  const maxNodes = Math.min(20_000, Math.max(50, options.maxNodes ?? 4_000))

  const callers = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "incoming",
    edgeTypes: new Set(["CALLS"]),
    depth: callDepth,
    maxNodes,
  })
  const callees = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "outgoing",
    edgeTypes: new Set(["CALLS"]),
    depth: callDepth,
    maxNodes,
  })
  const dependents = collectReachableNodeIds({
    store,
    startNodeId: nodeId,
    direction: "incoming",
    edgeTypes: new Set(["IMPORTS"]),
    depth: importDepth,
    maxNodes,
  })

const dependencies = collectReachableNodeIds({
  store,
  startNodeId: nodeId,
  direction: "outgoing",
  edgeTypes: new Set(["IMPORTS"]),
  depth: importDepth,
  maxNodes,
})
const impacted = collectReachableNodeIds({
  store,
  startNodeId: nodeId,
  direction: "both",
  edgeTypes: new Set(["CALLS", "IMPORTS", "REFERENCES"]),
  depth: impactDepth,
  maxNodes,
})

const fileCounts = new Map<string, number>()
let affectedSymbolsCount = 0
for (const impactedNodeId of impacted) {
  const node = resolveNode(store, impactedNodeId)
  if (node.kind !== "file") {
    affectedSymbolsCount += 1
  }
  if (!node.filePath) {
    continue
  }
  const normalizedFilePath = normalizeGraphFilePath(node.filePath)
  fileCounts.set(normalizedFilePath, (fileCounts.get(normalizedFilePath) ?? 0) + 1)
}

const topImpactedFiles = [...fileCounts.entries()]
  .sort((left, right) => {
    if (right[1] !== left[1]) {
      return right[1] - left[1]
    }
    return left[0].localeCompare(right[0])
  })
  .slice(0, 5)
  .map(([filePath, count]) => ({ filePath, count }))

return {
  callersCount: callers.size,
  calleesCount: callees.size,
  dependentsCount: dependents.size,
  dependenciesCount: dependencies.size,
  affectedFilesCount: fileCounts.size,
  affectedSymbolsCount,
  topImpactedFiles,
}

}

export const samplePersistedGraphForVisualization = async (options: {
  maxNodes?: number
  maxEdges?: number
  edgeTypes?: string[]
} = {}): Promise<PersistedGraphQueryResult> => {
  const store = await getPersistedGraphStore()

  const maxNodes = Math.min(2_000, Math.max(10, options.maxNodes ?? 220))
  const maxEdges = Math.min(10_000, Math.max(10, options.maxEdges ?? 420))

  const edgeTypeFilter = normalizeEdgeTypeFilter(options.edgeTypes, store.edgeTypes)
  const filteredEdges = filterEdgesByType(store.edges, edgeTypeFilter)
  const sampledEdges = sampleArray(filteredEdges, maxEdges)

  const selectedNodeIds = new Set<string>()
  const finalEdges: PersistedGraphEdge[] = []
  for (const edge of sampledEdges) {
    const hasSource = selectedNodeIds.has(edge.sourceId)
    const hasTarget = selectedNodeIds.has(edge.targetId)
    const nodesToAdd = (hasSource ? 0 : 1) + (hasTarget ? 0 : 1)

    if (selectedNodeIds.size + nodesToAdd > maxNodes) {
      continue
    }

    selectedNodeIds.add(edge.sourceId)
    selectedNodeIds.add(edge.targetId)
    finalEdges.push(edge)

    if (finalEdges.length >= maxEdges || selectedNodeIds.size >= maxNodes) {
      break
    }
  }

  const finalNodes = [...selectedNodeIds].map((id) => resolveNode(store, id))

  return {
    indexRunId: store.indexRunId,
    generatedAt: store.generatedAt,
    totalNodes: store.nodeIds.length,
    totalEdges: store.edges.length,
    availableEdgeTypes: store.edgeTypes,
    appliedEdgeTypes: edgeTypeFilter ? [...edgeTypeFilter] : [],
    nodes: finalNodes,
    edges: finalEdges,
  }
}

export const queryPersistedGraphNeighborhood = async (options: {
  nodeId: string
  depth?: number
  direction?: GraphNeighborhoodDirection
  edgeTypes?: string[]
  maxNodes?: number
  maxEdges?: number
}): Promise<PersistedGraphQueryResult> => {
  const store = await getPersistedGraphStore()

  const nodeId = options.nodeId.trim()
  if (!nodeId) {
    throw new CodeGraphError("command_failed", "Neighborhood query requires a non-empty nodeId.", null)
  }

  const depth = Math.min(6, Math.max(1, options.depth ?? 2))
  const direction: GraphNeighborhoodDirection = options.direction ?? "both"
  const maxNodes = Math.min(2_000, Math.max(10, options.maxNodes ?? 400))
  const maxEdges = Math.min(10_000, Math.max(10, options.maxEdges ?? 900))
  const edgeTypeFilter = normalizeEdgeTypeFilter(options.edgeTypes, store.edgeTypes)

  const queue: Array<{ id: string; depth: number }> = [{ id: nodeId, depth: 0 }]
  const visited = new Set<string>([nodeId])
  const edgesByKey = new Map<string, PersistedGraphEdge>()

while (queue.length > 0 && visited.size < maxNodes && edgesByKey.size < maxEdges) {
  const current = queue.shift()
  if (!current) {
    break
  }
  if (current.depth >= depth) {
    continue
  }

  const outgoing = direction === "incoming" ? [] : store.outgoing.get(current.id) ?? []
  const incoming = direction === "outgoing" ? [] : store.incoming.get(current.id) ?? []
  const candidates = [...outgoing, ...incoming]

  for (const edge of candidates) {
    if (edgeTypeFilter && !edgeTypeFilter.has(edge.type)) {
      continue
    }
    const key = `${edge.sourceId}->${edge.targetId}:${edge.type}`
    if (!edgesByKey.has(key)) {
      edgesByKey.set(key, edge)
    }
    if (edgesByKey.size >= maxEdges) {
      break
    }

    const nextId = edge.sourceId === current.id ? edge.targetId : edge.sourceId
    if (!visited.has(nextId) && visited.size < maxNodes) {
      visited.add(nextId)
      queue.push({ id: nextId, depth: current.depth + 1 })
    }
  }
}

return {
  indexRunId: store.indexRunId,
  generatedAt: store.generatedAt,
  totalNodes: store.nodeIds.length,
  totalEdges: store.edges.length,
  availableEdgeTypes: store.edgeTypes,
  appliedEdgeTypes: edgeTypeFilter ? [...edgeTypeFilter] : [],
  nodes: [...visited].map((id) => resolveNode(store, id)),
  edges: [...edgesByKey.values()],
}

}

export const queryPersistedGraphImpactPreset = async (options: {
  nodeId: string
  preset: GraphImpactPreset
  depth?: number
  maxNodes?: number
  maxEdges?: number
}): Promise<PersistedGraphQueryResult> => {
  const presetToQuery: Record<
    GraphImpactPreset,
    { direction: GraphNeighborhoodDirection; edgeTypes: string[] }
  > = {
    callers: { direction: "incoming", edgeTypes: ["CALLS"] },
    callees: { direction: "outgoing", edgeTypes: ["CALLS"] },
    dependencies: { direction: "outgoing", edgeTypes: ["IMPORTS"] },
    dependents: { direction: "incoming", edgeTypes: ["IMPORTS"] },
    impact: { direction: "both", edgeTypes: ["CALLS", "IMPORTS", "REFERENCES"] },
  }

  const mapping = presetToQuery[options.preset]
  return queryPersistedGraphNeighborhood({
    nodeId: options.nodeId,
    depth: options.depth,
    direction: mapping.direction,
    edgeTypes: mapping.edgeTypes,
    maxNodes: options.maxNodes,
    maxEdges: options.maxEdges,
  })
}

