          workerHeartbeatAgeMs,
          workerHeartbeatStaleAfterMs: WORKER_HEARTBEAT_STALE_AFTER_MS,
        },
        issues,
      }

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json(responsePayload),
      }
    },
  })
}

