  const createArgusSearch = (mod.createArgusSearch ?? mod.default?.createArgusSearch) as unknown
  if (typeof createArgusSearch !== 'function') {
    throw new Error('createArgusSearch not found')
  }
  return { createArgusSearch: createArgusSearch as (options: Record<string, unknown>) => any }
}

