			(value as { message?: unknown }).message ?? "",
		).trim();
		if (message.length > 0) {
			return message;
		}
	}
	if (value && typeof value === "object" && "error" in value) {
		return String((value as { error?: string }).error);
	}
	return "Unable to complete AI review.";
};

export const normalizePatchPath = (value: string) =>
