const readProviderErrorMessage = async (response: Response) => {
  const bodyText = await response.text().catch(() => "")
  const trimmed = bodyText.trim()
  if (!trimmed) {
    return ""
  }

  try {
    const parsed = JSON.parse(trimmed) as unknown
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    const root = parsed as Record<string, unknown>
    if (typeof root.error === "string" && root.error.trim().length > 0) {
      return root.error.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }

    if (root.error && typeof root.error === "object" && !Array.isArray(root.error)) {
      const nested = root.error as Record<string, unknown>
      if (typeof nested.message === "string" && nested.message.trim().length > 0) {
        return nested.message.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
      }
    }

    if (typeof root.message === "string" && root.message.trim().length > 0) {
      return root.message.trim().slice(0, MAX_PROVIDER_ERROR_LENGTH)
    }
  } catch {
    return trimmed.slice(0, MAX_PROVIDER_ERROR_LENGTH)
  }

  return ""
}

const buildNetworkErrorMessage = (error: unknown) => {
  if (error instanceof Error && error.name === "AbortError") {
    return `AI request timed out after ${Math.round(CHAT_TIMEOUT_MS / 1000)} seconds.`
  }

  if (error instanceof Error && error.message.trim().length > 0) {
    return `AI request failed before response: ${error.message}`
  }

  return "AI request failed before response."
}

const extractMessageText = (content: unknown): string => {
  if (typeof content === "string") {
    return content.trim()
  }

  if (!Array.isArray(content)) {
    return ""
  }

  const parts = content
    .map((part) => {
      if (!part || typeof part !== "object" || Array.isArray(part)) {
        return ""
      }
      const candidate = part as Record<string, unknown>
      if (typeof candidate.text === "string") {
        return candidate.text
      }
      if (candidate.type === "text" && typeof candidate.content === "string") {
        return candidate.content
      }
      return ""
    })
    .filter((part) => part.trim().length > 0)

  return parts.join("\n").trim()
}

const toPromptMessages = (args: {
  question: string
  history: ChatMessage[]
  pathname: string
}) => {
  const systemPrompt = [
    "You are Argus command palette assistant.",
    "Primary job: quickly answer where to find features in the Argus app and how to perform common actions.",
    "Answer in 2-5 concise bullets. Mention exact route paths when possible.",
    "If unsure, say you are unsure and suggest the closest likely route.",
    "Do not invent features that are not in this route guide.",
    "",
    `Current route: ${args.pathname || "(unknown)"}`,
    "Known routes and features:",
    APP_GUIDE,
  ].join("\n")

  return [
    {
      role: "system",
      content: systemPrompt,
    },
    ...args.history,
    {
      role: "user",
      content: args.question,
    },
  ]
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/command-palette/chat",
    event: "api.command_palette.chat",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => null) as Promise<unknown>,
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const parsed = chatPayloadSchema.safeParse(payload)

if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json(
      { error: "question is required." },
      { status: 400 },
    ),
  }
}

let serverApiUrl: string
try {
  serverApiUrl = resolveApiUrl(getEnvApiUrl())
} catch {
  return {
    status: 500,
    outcome: "missing_config",
    response: NextResponse.json(
      { error: "Server AI provider URL is invalid." },
      { status: 500 },
    ),
  }
}

let clientApiUrl = ""
if (parsed.data.apiUrl) {
  try {
    clientApiUrl = resolveApiUrl(parsed.data.apiUrl)
  } catch (error) {
    return {
      status: 400,
      outcome: "invalid_request",
      response: NextResponse.json(
        { error: error instanceof Error ? error.message : "API URL is invalid." },
        { status: 400 },
      ),
    }
  }
}
const apiUrl = clientApiUrl || serverApiUrl
const hasCustomApiUrl = clientApiUrl.length > 0 && clientApiUrl !== serverApiUrl

const model = parsed.data.model?.trim() || getEnvModel()
const clientToken = parsed.data.token?.trim() ?? ""
const token = clientToken || (hasCustomApiUrl ? "" : getEnvToken())

if (!token) {
  return {
    status: 400,
    outcome: hasCustomApiUrl ? "invalid_request" : "missing_config",
    response: NextResponse.json(
      {
        error: hasCustomApiUrl
          ? "Custom API URL requires an explicit token."
          : "AI token missing. Set API token in settings or server env.",
      },
      { status: 400 },
    ),
  }
}

const history: ChatMessage[] = (parsed.data.history ?? [])
  .map((entry) => ({
    role: entry.role,
    content: entry.content.trim(),
  }))
  .filter((entry) => entry.content.length > 0)

const controller = new AbortController()
const timeout = setTimeout(() => {
  controller.abort()
}, CHAT_TIMEOUT_MS)
const startedAt = Date.now()
const provider = resolveLlmProviderLabel(apiUrl)

try {
  const response = await fetch(getChatCompletionsUrl(apiUrl), {
    method: "POST",
    headers: {
      "content-type": "application/json",
      authorization: `Bearer ${token}`,
    },
    body: JSON.stringify({
      model,
      temperature: 0.2,
      max_tokens: 420,
      messages: toPromptMessages({
        question: parsed.data.question,
        history,
        pathname: parsed.data.pathname ?? "",
      }),
    }),
    signal: controller.signal,
  })

if (!response.ok) {
  const providerError = await readProviderErrorMessage(response)
  const suffix = providerError ? ` ${providerError}` : ""
  logger.set({
    model,
    providerStatus: response.status,
    labels: {
      provider,
      model,
    },
  })
  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      {
        error: `AI provider request failed (${response.status}).${suffix}`,
        providerStatus: response.status,
      },
      { status: 502 },
    ),
  }
}

const latencyMs = Math.max(1, Date.now() - startedAt)
const providerPayload = (await response.json().catch(() => null)) as ProviderChatResponse | null
const answer = extractMessageText(providerPayload?.choices?.[0]?.message?.content)
if (!answer) {
  logger.set({
    model,
    responseError: "empty_message",
    labels: {
      provider,
      model,
    },
  })
  return {
    status: 502,
    outcome: "upstream_error",
    response: NextResponse.json(
      {
        error: "AI response did not include a message.",
      },
      { status: 502 },
    ),
  }
}

const usage = extractUsageFromOpenAiCompatiblePayload(providerPayload)

        logger.set({
          model,
          latencyMs,
          labels: {
            provider,
            model,
          },
          llmMetrics: buildLlmMetrics({
            provider,
            model,
            promptTokens: usage.promptTokens,
            completionTokens: usage.completionTokens,
            totalTokens: usage.totalTokens,
            latencyMs,
            requestCount: 1,
          }),
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ answer }),
        }
      } catch (error) {
        const message = buildNetworkErrorMessage(error)
        logger.set({
          model,
          networkError: message,
          labels: {
            provider,
            model,
          },
        })
        return {
          status: 502,
          outcome: "upstream_error",
          response: NextResponse.json(
            { error: message },
            { status: 502 },
          ),
        }
      } finally {
        clearTimeout(timeout)
      }
    },
  })
}

