import { extractLogEventName, toSafeJsonObject } from "@argus/shared-observability"

describe("shared observability event utils", () => {
  test("extractLogEventName prefers explicit event name", () => {
    expect(extractLogEventName({ event: "indexer.batch.done", tag: "warn", path: "/x" })).toBe(
      "indexer.batch.done",
    )
  })

  test("extractLogEventName falls back to tag/path", () => {
    expect(extractLogEventName({ tag: "warn" })).toBe("log.warn")
