fn find_up_config(explicit: Option<PathBuf>) -> Option<PathBuf> {
  if let Some(path) = explicit {
    return Some(path);
  }

  let mut dir = std::env::current_dir().ok()?;
  loop {
    for name in DEFAULT_CONFIG_FILES {
      let candidate = dir.join(name);
      if candidate.exists() {
        return Some(candidate);
      }
    }

    let parent = dir.parent().map(|p| p.to_path_buf());
    match parent {
      Some(p) if p != dir => dir = p,
      _ => break,
    }
  }

  None
}

fn load_config(path: &Path) -> anyhow::Result<JsonConfig> {
  let raw = fs::read_to_string(path)
    .with_context(|| format!("failed to read config: {}", path.to_string_lossy()))?;
  let cfg = serde_json::from_str::<JsonConfig>(&raw)
    .with_context(|| format!("invalid JSON config: {}", path.to_string_lossy()))?;
  Ok(cfg)
}

fn query_embedding_cache_path(store_path: &Path) -> PathBuf {
  let file_name = store_path
    .file_name()
    .map(|name| format!("{}.query-cache.json", name.to_string_lossy()))
    .unwrap_or_else(|| "index.kite.query-cache.json".to_string());
  store_path
    .parent()
    .map(|parent| parent.join(&file_name))
    .unwrap_or_else(|| PathBuf::from(file_name))
}

fn load_query_embedding_cache(path: &Path) -> QueryEmbeddingCache {
  match fs::read_to_string(path) {
    Ok(raw) => serde_json::from_str::<QueryEmbeddingCache>(&raw).unwrap_or_default(),
    Err(_) => QueryEmbeddingCache::default(),
  }
}

fn save_query_embedding_cache(path: &Path, cache: &QueryEmbeddingCache) -> anyhow::Result<()> {
  if let Some(parent) = path.parent() {
    fs::create_dir_all(parent)?;
  }
  let payload = serde_json::to_string_pretty(cache)?;
  fs::write(path, format!("{payload}\n"))?;
  Ok(())
}

