fn project_root_from_config(config_path: Option<&Path>, cfg: &JsonConfig) -> Option<PathBuf> {
  let root = cfg.project_root.as_ref()?;
  let parsed = PathBuf::from(root);
  if parsed.is_absolute() {
    return Some(parsed);
  }
  let base = config_path
    .and_then(|p| p.parent())
    .unwrap_or_else(|| Path::new("."));
  Some(base.join(parsed))
}

fn resolve_project_root(
  config_path: Option<&Path>,
  cfg: &JsonConfig,
  override_root: Option<PathBuf>,
) -> PathBuf {
  if let Some(root) = override_root {
    return root;
  }
  if let Some(root) = project_root_from_config(config_path, cfg) {
    return root;
  }
  std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
}

fn resolve_store_path(project_root: &Path, override_store: Option<PathBuf>) -> PathBuf {
  if let Some(path) = override_store {
    if path.is_absolute() {
      return path;
    }
    return project_root.join(path);
  }
  project_root.join(".argus-search/index.kite")
}

fn split_list(value: Option<&str>) -> Vec<String> {
  value
    .unwrap_or("")
    .split(',')
    .map(|entry| entry.trim().to_string())
    .filter(|entry| !entry.is_empty())
    .collect()
}

fn normalize_phase_name(value: &str) -> Option<&'static str> {
  let lowered = value.to_ascii_lowercase();
  match lowered.as_str() {
    "parse" => Some("parse"),
    "graph" => Some("graph"),
    "vector" => Some("vector"),
    "scip" => Some("scip"),
    "indexpack" | "index-pack" | "index_pack" => Some("indexPack"),
    _ => None,
  }
}

fn parse_phase_overrides(value: Option<&str>) -> anyhow::Result<Option<IndexPhases>> {
  let phases = split_list(value);
  if phases.is_empty() {
    return Ok(None);
  }

  let mut enabled = HashSet::new();
  let mut unknown = Vec::new();
  for phase in phases {
    match normalize_phase_name(&phase) {
      Some(name) => {
        enabled.insert(name);
      }
      None => unknown.push(phase),
    }
  }

  if !unknown.is_empty() {
    anyhow::bail!(
      "unknown phase(s): {} (allowed: parse, graph, vector, scip, indexPack)",
      unknown.join(", ")
    );
  }

  Ok(Some(IndexPhases {
    parse: enabled.contains("parse"),
    graph: enabled.contains("graph"),
    vector: enabled.contains("vector"),
    scip: enabled.contains("scip"),
    index_pack: enabled.contains("indexPack"),
  }))
}

fn signature_mtime_len(path: &Path) -> Option<(u128, u64)> {
  let meta = fs::metadata(path).ok()?;
  let mtime = meta
    .modified()
    .ok()?
    .duration_since(std::time::UNIX_EPOCH)
    .ok()?;
  Some((mtime.as_millis(), meta.len()))
}

fn safe_resolve_within_root(root_dir: &Path, unsafe_path: &Path) -> anyhow::Result<PathBuf> {
  let root = root_dir
    .canonicalize()
    .with_context(|| format!("failed to canonicalize project root {}", root_dir.display()))?;
  let resolved = if unsafe_path.is_absolute() {
    unsafe_path.to_path_buf()
  } else {
    root.join(unsafe_path)
  }
  .canonicalize()
  .with_context(|| format!("failed to canonicalize path {}", unsafe_path.display()))?;

  resolved
    .strip_prefix(&root)
    .context("path escapes project root")?;
  Ok(resolved)
}

fn normalize_relative_path(project_root: &Path, file_path: &str) -> anyhow::Result<String> {
  let file_path = file_path.replace('\\', "/");
  let p = Path::new(&file_path);
  if p.is_absolute() {
    let abs = safe_resolve_within_root(project_root, p)?;
    let rel = abs.strip_prefix(project_root).unwrap_or(abs.as_path());
    return Ok(rel.to_string_lossy().replace('\\', "/"));
  }

  if p
    .components()
    .any(|c| matches!(c, std::path::Component::ParentDir))
  {
    anyhow::bail!("path escapes project root");
  }

  Ok(p.to_string_lossy().replace('\\', "/"))
}

fn build_index_options(
  project_root: &Path,
  config_path: Option<&Path>,
  config: &JsonConfig,
  store_path: &Path,
  no_vector: bool,
  phase_overrides: Option<&str>,
) -> anyhow::Result<(IndexOptions, Option<std::sync::Arc<dyn EmbeddingsProvider>>)> {
  let mut options = IndexOptions::new(project_root.to_path_buf());

if let Some(inputs) = &config.inputs {
  options.inputs = ParseInputs {
    paths: inputs
      .paths
      .clone()
      .unwrap_or_default()
      .into_iter()
      .map(|p| {
        let path = PathBuf::from(p);
        if path.is_relative() {
          project_root.join(path)
        } else {
          path
        }
      })
      .collect(),
    include: inputs.include.clone().unwrap_or_default(),
    exclude: inputs.exclude.clone().unwrap_or_default(),
    respect_gitignore: inputs.respect_gitignore.unwrap_or(true),
  };
}

let phases = config.phases.unwrap_or_default();
// For `ci`, default to parse+graph+vector, without index-pack.
let mut out = IndexPhases {
  parse: phases.parse.unwrap_or(true),
  graph: phases.graph.unwrap_or(true),
  vector: phases.vector.unwrap_or(true),
  scip: phases.scip.unwrap_or(false),
  index_pack: phases.index_pack.unwrap_or(false),
};
if let Some(override_phases) = parse_phase_overrides(phase_overrides)? {
  out = override_phases;
}
if no_vector {
  out.vector = false;
}
options.phases = out;

// Cache/output tuning (optional, ignored by other consumers).
if let Some(cache) = &config.cache {
  if let Some(enabled) = cache.enabled {
    options.cache.enabled = enabled;
  }
  if let Some(force) = cache.force {
    options.cache.force = force;
  }
  if let Some(path) = &cache.path {
    options.cache.path = Some(resolve_config_relative_path(
      project_root,
      config_path,
      path,
    ));
  }
}

if let Some(output) = &config.output {
  if let Some(incremental) = output.incremental {
    options.output.incremental = incremental;
  }
  if let Some(dir) = &output.data_dir {
    options.output.data_dir = Some(resolve_config_relative_path(project_root, config_path, dir));
  }
}

// Default data dir based on store location (nice when store is customized).
if options.output.data_dir.is_none() {
  if let Some(parent) = store_path.parent() {
    options.output.data_dir = Some(parent.to_path_buf());
  }
}

if !options.phases.vector {
  return Ok((options, None));
}

let vector = config
  .vector
  .as_ref()
  .ok_or_else(|| anyhow::anyhow!("vector config is required for semantic search"))?;
let provider = vector
  .provider
  .as_ref()
  .ok_or_else(|| anyhow::anyhow!("vector.provider is required for semantic search"))?;

if let Some(kind) = &provider.kind {
  if kind != "http" {
    anyhow::bail!("unsupported vector provider kind: {kind}");
  }
}

let api_key = provider
  .api_key
  .clone()
  .filter(|value| !value.trim().is_empty())
  .or_else(|| std::env::var("OPENAI_API_KEY").ok());

let mut http =
  HttpEmbeddingConfig::new(provider.base_url.clone(), api_key, provider.model.clone());
http.dimension = provider.dimension;
if let Some(timeout) = provider.timeout_ms {
  http.timeout = Some(Duration::from_millis(timeout));
}
let http_provider = HttpEmbeddingsProvider::new(http)?;

if let Some(batch_size) = vector.batch_size {
  options.vector.batch_size = batch_size;
}

  if let Some(concurrency) = vector.concurrency {
    options.vector.concurrency = concurrency;
  }

  // Store chunk JSON to allow future UX improvements without file IO.
  options.vector.include_chunk = true;

  let embeddings_provider: std::sync::Arc<dyn EmbeddingsProvider> =
    std::sync::Arc::new(http_provider);
  options.vector_provider = Some(std::sync::Arc::clone(&embeddings_provider));
  Ok((options, Some(embeddings_provider)))
}

fn resolve_config_relative_path(
  project_root: &Path,
  _config_path: Option<&Path>,
  value: &str,
) -> PathBuf {
  let p = PathBuf::from(value);
  if p.is_absolute() {
    return p;
  }
  // Resolve relative paths against projectRoot, matching other bindings.
  project_root.join(p)
}

#[derive(Debug, Clone, Copy)]
enum CheckStatus {
  Ok,
  Warn,
  Error,
}

#[derive(Debug)]
struct CheckResult {
  name: &'static str,
  status: CheckStatus,
  message: String,
}

impl CheckResult {
  fn ok(name: &'static str, message: impl Into<String>) -> Self {
    Self {
      name,
      status: CheckStatus::Ok,
      message: message.into(),
    }
  }

  fn warn(name: &'static str, message: impl Into<String>) -> Self {
    Self {
      name,
      status: CheckStatus::Warn,
      message: message.into(),
    }
  }

  fn error(name: &'static str, message: impl Into<String>) -> Self {
    Self {
      name,
      status: CheckStatus::Error,
      message: message.into(),
    }
  }
}

fn now_millis() -> i128 {
  std::time::SystemTime::now()
    .duration_since(std::time::UNIX_EPOCH)
    .map(|d| d.as_millis() as i128)
    .unwrap_or(0)
}

fn emit_watch_event(json: bool, event: &str, store_path: &Path, message: &str) {
  if json {
    let payload = serde_json::json!({
      "event": event,
      "storePath": store_path.to_string_lossy(),
      "message": message,
      "timestampMs": now_millis(),
    });
    println!("{payload}");
  } else {
    let ansi = Ansi::new(std::io::stderr().is_terminal());
    let now = time::OffsetDateTime::now_local().unwrap_or_else(|_| time::OffsetDateTime::now_utc());
    let time_str = format!("{:02}:{:02}:{:02}", now.hour(), now.minute(), now.second());
    let timestamp = ansi.dim(&format!("[{time_str}]"));

    let (icon, colored_msg) = match event {
      "index_start" => {
        let icon = if ansi.enabled { "▶" } else { "[START]" };
        (ansi.cyan(icon), message.to_string())
      }
      "index_complete" => (ansi.check(), ansi.green(message)),
      "error" => (ansi.cross(), ansi.red(message)),
      "stopping" => {
        let icon = if ansi.enabled { "◼" } else { "[STOP]" };
        (ansi.yellow(icon), ansi.yellow(message))
      }
      _ => (ansi.info(), message.to_string()),
    };
    eprintln!("{timestamp} {icon} {colored_msg}");
  }
}

fn inject_search_vector_overrides(
  search: &SearchArgs,
  config: &mut JsonConfig,
) -> Option<JsonHttpVectorProvider> {
  if config
    .vector
    .as_ref()
    .and_then(|v| v.provider.as_ref())
    .is_some()
  {
    return None;
  }

  let env_key = std::env::var("OPENAI_API_KEY").ok();
  let api_key = search
    .vector_api_key
    .clone()
    .filter(|v| !v.trim().is_empty())
    .or(env_key);

  if search.vector_base_url.is_none()
    && search.vector_model.is_none()
    && api_key.is_none()
    && search.vector_dimension.is_none()
    && search.vector_timeout_ms.is_none()
  {
    return None;
  }

  Some(JsonHttpVectorProvider {
    kind: Some("http".to_string()),
    base_url: search
      .vector_base_url
      .clone()
      .unwrap_or_else(|| "https://api.openai.com/v1".to_string()),
    model: search
      .vector_model
      .clone()
      .unwrap_or_else(|| "text-embedding-3-small".to_string()),
    api_key,
    dimension: search.vector_dimension,
    timeout_ms: search.vector_timeout_ms,
  })
}

fn ensure_vector_config(config: &mut JsonConfig, provider: JsonHttpVectorProvider) {
  if config.vector.is_none() {
    config.vector = Some(JsonVector {
      provider: Some(provider),
      batch_size: None,
      concurrency: None,
    });
    return;
  }
  if let Some(vector) = config.vector.as_mut() {
    if vector.provider.is_none() {
      vector.provider = Some(provider);
    }
  }
}

fn index_to_kitedb(
  options: IndexOptions,
  store_path: &Path,
  checkpoint_on_finish: bool,
  checkpoint_threshold: f64,
) -> anyhow::Result<()> {
  let mut sink = KiteDbIndexSink::new_with_checkpoint_policy(
    store_path.to_path_buf(),
    false,
    checkpoint_on_finish,
    checkpoint_threshold,
  );
  let engine = IndexEngine::new(options);
  let cancel = CancelToken::new();
  if let Err(err) = engine.run(&mut sink, &cancel) {
    let _ = sink.abort();
    return Err(err.into());
  }
  sink.finish().map_err(|e| anyhow::anyhow!(e.to_string()))?;
  Ok(())
}

fn read_range_json(range_json: &Option<String>) -> Option<Range> {
  let raw = range_json.as_ref()?;
  serde_json::from_str::<Range>(raw).ok()
}

fn range_span(range: &Range) -> (u32, u32) {
  let start = range.start.row;
  let end = range.end.row;
  (start, end.saturating_sub(start))
}

fn best_candidate(candidates: &[KiteGraphNeighbor]) -> Option<&KiteGraphNeighbor> {
  candidates.iter().min_by(|a, b| {
    // Prefer non-file nodes with a file_path.
    let a_file = a.kind.as_deref() == Some("file");
    let b_file = b.kind.as_deref() == Some("file");
    a_file
      .cmp(&b_file)
      .then_with(|| a.file_path.is_none().cmp(&b.file_path.is_none()))
      .then_with(|| {
        let a_span = read_range_json(&a.range_json)
          .map(|r| range_span(&r).1)
          .unwrap_or(u32::MAX);
        let b_span = read_range_json(&b.range_json)
          .map(|r| range_span(&r).1)
          .unwrap_or(u32::MAX);
        a_span.cmp(&b_span)
      })
      .then_with(|| a.id.cmp(&b.id))
  })
}

