      self.hits,
      self.impact_nodes,
      self.embed_ms,
      self.open_store_ms,
      self.vector_search_ms,
      self.content_ms,
      self.impact_ms,
      self.output_ms,
      total_ms
    );
  }
}

/// ANSI color/style codes for terminal output
#[derive(Debug, Clone, Copy)]
struct Ansi {
  enabled: bool,
}

impl Ansi {
  fn new(enabled: bool) -> Self {
    Self { enabled }
  }

  fn wrap(self, code: &str, text: &str) -> String {
    if self.enabled {
      format!("\x1b[{code}m{text}\x1b[0m")
    } else {
      text.to_string()
    }
  }

// Styles
fn bold(self, text: &str) -> String {
  self.wrap("1", text)
}

fn dim(self, text: &str) -> String {
  self.wrap("2", text)
}

#[allow(dead_code)]
fn underline(self, text: &str) -> String {
  self.wrap("4", text)
}

// Colors
fn red(self, text: &str) -> String {
  self.wrap("31", text)
}

fn green(self, text: &str) -> String {
  self.wrap("32", text)
}

fn yellow(self, text: &str) -> String {
  self.wrap("33", text)
}

fn blue(self, text: &str) -> String {
  self.wrap("34", text)
}

fn magenta(self, text: &str) -> String {
  self.wrap("35", text)
}

fn cyan(self, text: &str) -> String {
  self.wrap("36", text)
}

// Combined styles
fn bold_underline(self, text: &str) -> String {
  if self.enabled {
    format!("\x1b[1;4m{text}\x1b[0m")
  } else {
    text.to_string()
  }
}

fn bold_cyan(self, text: &str) -> String {
  if self.enabled {
    format!("\x1b[1;36m{text}\x1b[0m")
  } else {
    text.to_string()
  }
}

fn bold_green(self, text: &str) -> String {
  if self.enabled {
    format!("\x1b[1;32m{text}\x1b[0m")
  } else {
    text.to_string()
  }
}

fn bold_red(self, text: &str) -> String {
  if self.enabled {
    format!("\x1b[1;31m{text}\x1b[0m")
  } else {
    text.to_string()
  }
}

fn bold_yellow(self, text: &str) -> String {
  if self.enabled {
    format!("\x1b[1;33m{text}\x1b[0m")
  } else {
    text.to_string()
  }
}

// Status symbols

  fn check(self) -> String {
    if self.enabled {
      self.green("✓")
    } else {
      "[OK]".to_string()
    }
  }

  fn cross(self) -> String {
    if self.enabled {
      self.red("✗")
    } else {
      "[FAIL]".to_string()
    }
  }

  fn warning_symbol(self) -> String {
    if self.enabled {
      self.yellow("⚠")
    } else {
      "[WARN]".to_string()
    }
  }

  fn info(self) -> String {
    if self.enabled {
      self.cyan("ℹ")
    } else {
      "[INFO]".to_string()
    }
  }
}

