fn run_doctor(
  args: DoctorArgs,
  config: Option<PathBuf>,
  project_root_override: Option<PathBuf>,
  store: Option<PathBuf>,
) -> anyhow::Result<()> {
  let config_path = find_up_config(config);
  let mut checks = Vec::new();
  let mut fixes = Vec::new();
  let mut cfg = JsonConfig::default();
  let mut config_loaded = false;

if let Some(path) = config_path.as_deref() {
  match load_config(path) {
    Ok(loaded) => {
      cfg = loaded;
      config_loaded = true;
      checks.push(CheckResult::ok(
        "config",
        format!("loaded {}", path.to_string_lossy()),
      ));
    }
    Err(err) => {
      checks.push(CheckResult::error("config", format!("{err}")));
    }
  }
} else {
  checks.push(CheckResult::warn("config", "not found (run: ci init)"));
}

let project_root = resolve_project_root(config_path.as_deref(), &cfg, project_root_override);
let store_path = resolve_store_path(&project_root, store);

if args.fix {
  if project_root.exists() && project_root.is_dir() {
    let ci_dir = project_root.join(".argus-search");
    if !ci_dir.exists() {
      if let Err(err) = fs::create_dir_all(&ci_dir) {
        checks.push(CheckResult::warn(
          "fix",
          format!("failed to create {}: {err}", ci_dir.to_string_lossy()),
        ));
      } else {
        fixes.push(format!("created {}", ci_dir.to_string_lossy()));
      }
    }

    if let Err(err) = ensure_gitignore(&project_root) {
      checks.push(CheckResult::warn(
        "fix",
        format!("failed to update .gitignore: {err}"),
      ));
    } else {
      fixes.push("ensured .gitignore includes .argus-search/".to_string());
    }
  }

  if let Some(parent) = store_path.parent() {
    if !parent.exists() {
      if let Err(err) = fs::create_dir_all(parent) {
        checks.push(CheckResult::warn(
          "fix",
          format!(
            "failed to create store dir {}: {err}",
            parent.to_string_lossy()
          ),
        ));
      } else {
        fixes.push(format!("created store dir {}", parent.to_string_lossy()));
      }
    }
  }
}

if project_root.exists() {
  if project_root.is_dir() {
    checks.push(CheckResult::ok(
      "projectRoot",
      project_root.to_string_lossy(),
    ));
  } else {
    checks.push(CheckResult::error(
      "projectRoot",
      format!("not a directory: {}", project_root.to_string_lossy()),
    ));
  }
} else {
  checks.push(CheckResult::error(
    "projectRoot",
    format!("not found: {}", project_root.to_string_lossy()),
  ));
}

match store_path.parent() {
  Some(parent) => {
    if parent.exists() {
      if !parent.is_dir() {
        checks.push(CheckResult::error(
          "storePath",
          format!(
            "store parent is not a directory: {}",
            parent.to_string_lossy()
          ),
        ));
      } else if store_path.exists() {
        checks.push(CheckResult::ok(
          "storePath",
          format!("found {}", store_path.to_string_lossy()),
        ));
      } else {
        checks.push(CheckResult::warn(
          "storePath",
          format!(
            "not found (run: ci watch --once) at {}",
            store_path.to_string_lossy()
          ),
        ));
      }
    } else {
      checks.push(CheckResult::warn(
        "storePath",
        format!(
          "parent does not exist (will be created on watch): {}",
          parent.to_string_lossy()
        ),
      ));
    }
  }
  None => {
    checks.push(CheckResult::error(
      "storePath",
      format!("invalid store path: {}", store_path.to_string_lossy()),
    ));
  }
}

if config_loaded {

if let Some(inputs) = &cfg.inputs {
  if let Some(paths) = &inputs.paths {
    let mut missing = Vec::new();
    for raw in paths {
      let p = PathBuf::from(raw);
      let resolved = if p.is_relative() {
        project_root.join(p)
      } else {
        p
      };
      if !resolved.exists() {
        missing.push(raw.clone());
      }
    }
    if missing.is_empty() {
      checks.push(CheckResult::ok("inputs", "all input paths exist"));
    } else {
      checks.push(CheckResult::warn(
        "inputs",
        format!("missing paths: {}", missing.join(", ")),
      ));
    }
  } else {
    checks.push(CheckResult::warn(
      "inputs",
      "inputs.paths not set (defaults apply)",
    ));
  }
} else {
  checks.push(CheckResult::warn(
    "inputs",
    "inputs not set (defaults apply)",
  ));
}

let phases = cfg.phases.unwrap_or_default();
let vector_enabled = phases.vector.unwrap_or(true);
if vector_enabled {
  match cfg.vector.as_ref() {
    Some(vector) => match vector.provider.as_ref() {
      Some(provider) => {
        if let Some(kind) = &provider.kind {
          if kind != "http" {
            checks.push(CheckResult::error(
              "vector",
              format!("unsupported provider kind: {kind}"),
            ));
          }
        }

if provider.base_url.trim().is_empty() {
  checks.push(CheckResult::error("vector", "provider.baseUrl is empty"));
}
if provider.model.trim().is_empty() {
  checks.push(CheckResult::error("vector", "provider.model is empty"));
}

let api_key = provider
  .api_key
  .clone()
  .filter(|value| !value.trim().is_empty())
  .or_else(|| std::env::var("OPENAI_API_KEY").ok());
if api_key.is_none() {
  checks.push(CheckResult::warn(
    "vector",
    "no API key found (set OPENAI_API_KEY if provider requires auth)",
  ));
}

          if args.network {
            let mut http = HttpEmbeddingConfig::new(
              provider.base_url.clone(),
              api_key,
              provider.model.clone(),
            );
            http.dimension = provider.dimension;
            if let Some(timeout) = provider.timeout_ms {
              http.timeout = Some(Duration::from_millis(timeout));
            }
            match HttpEmbeddingsProvider::new(http) {
              Ok(http_provider) => match http_provider.embed_texts(&["ping"]) {
                Ok(_) => checks.push(CheckResult::ok(
                  "vector.network",
                  "embeddings request succeeded",
                )),
                Err(err) => checks.push(CheckResult::error("vector.network", format!("{err}"))),
              },
              Err(err) => checks.push(CheckResult::error("vector.network", format!("{err}"))),
            }
          }
        }
        None => checks.push(CheckResult::error(
          "vector",
          "vector.provider is required for semantic search",
        )),
      },
      None => checks.push(CheckResult::error(
        "vector",
        "vector config is required for semantic search",
      )),
    }
  } else {
    checks.push(CheckResult::ok("vector", "disabled (phases.vector=false)"));
  }
}

let has_error = checks
  .iter()
  .any(|c| matches!(c.status, CheckStatus::Error));

if args.json {

  let payload = serde_json::json!({
    "ok": !has_error,
    "fixes": fixes,
    "checks": checks.iter().map(|check| {
      let status = match check.status {
        CheckStatus::Ok => "ok",
        CheckStatus::Warn => "warn",
        CheckStatus::Error => "error",
      };
      serde_json::json!({
        "name": check.name,
        "status": status,
        "message": check.message,
      })
    }).collect::<Vec<_>>(),
  });
  println!("{}", serde_json::to_string_pretty(&payload)?);
} else {
  let ansi = Ansi::new(std::io::stdout().is_terminal());

  // Header
  println!();
  println!("  {}", ansi.bold_cyan("ci doctor"));
  println!("  {}", ansi.dim("Diagnosing configuration and environment"));
  println!();

  // Fixes section
  if args.fix {
    if fixes.is_empty() {
      println!("{} {}", ansi.check(), ansi.green("No fixes needed"));
    } else {
      println!("{}", ansi.bold_underline("FIXES APPLIED"));
      for fix in &fixes {
        println!("  {} {}", ansi.check(), ansi.green(fix));
      }
    }
    println!();
  }

  // Checks section
  println!("{}", ansi.bold_underline("CHECKS"));

    for check in &checks {
      let (icon, status_colored) = match check.status {
        CheckStatus::Ok => (ansi.check(), ansi.green("OK   ")),
        CheckStatus::Warn => (ansi.warning_symbol(), ansi.yellow("WARN ")),
        CheckStatus::Error => (ansi.cross(), ansi.red("ERROR")),
      };
      let name = ansi.bold(&format!("{:14}", check.name));
      let msg = ansi.dim(&check.message);
      println!("{icon} {status_colored} {name} {msg}");
    }
    println!();

    // Summary
    let ok_count = checks
      .iter()
      .filter(|c| matches!(c.status, CheckStatus::Ok))
      .count();
    let warn_count = checks
      .iter()
      .filter(|c| matches!(c.status, CheckStatus::Warn))
      .count();
    let error_count = checks
      .iter()
      .filter(|c| matches!(c.status, CheckStatus::Error))
      .count();

    if has_error {
      print!("{}", ansi.bold_red(&format!("✗ {error_count} error(s)")));
    } else if warn_count > 0 {
      print!(
        "{}",
        ansi.bold_yellow(&format!("⚠ {warn_count} warning(s)"))
      );
    } else {
      print!("{}", ansi.bold_green("✓ All checks passed"));
    }
    println!(
      " {}",
      ansi.dim(&format!(
        "({ok_count} ok, {warn_count} warn, {error_count} error)"
      ))
    );
    println!();
  }

  if has_error {
    std::process::exit(1);
  }
  Ok(())
}

fn main() -> anyhow::Result<()> {
  let Args {
    help,
    config,
    project_root: project_root_override,
    store,
    command,
  } = Args::parse();

  let ansi = Ansi::new(std::io::stdout().is_terminal());

// Handle help flag at the top level
// Handle missing command - show main help
if command.is_none() {
  print_main_help(ansi);
  return Ok(());
}

let command = command.unwrap();

// Handle help flag at top level (no subcommand context)
if help {
  // Determine which command's help to show based on the parsed command
  match &command {
    Command::Init(_) => print_command_help("init", ansi),
    Command::Watch(_) => print_command_help("watch", ansi),
    Command::Search(_) => print_command_help("search", ansi),
    Command::Trace(_) => print_command_help("trace", ansi),
    Command::Doctor(_) => print_command_help("doctor", ansi),
    Command::Completions(_) => print_command_help("completions", ansi),
    Command::Man => print_command_help("man", ansi),
    Command::Help { command: target } => {
      if let Some(cmd) = target {
        print_command_help(cmd, ansi);
      } else {
        print_main_help(ansi);
      }
    }
  }
  return Ok(());
}

let command = match command {
  Command::Help { command: target } => {
    if let Some(cmd) = target {
      print_command_help(&cmd, ansi);
    } else {
      print_main_help(ansi);
    }
    return Ok(());
  }
  Command::Init(init) => {
    let project_root = project_root_override
      .unwrap_or(std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")));
    let out_path = init
      .out
      .unwrap_or_else(|| project_root.join("argus-search.json"));

if out_path.exists() && !init.force {
  anyhow::bail!(
    "config already exists at {}; pass --force to overwrite",
    out_path.to_string_lossy()
  );
}

let paths = if let Some(v) = init.paths.as_deref() {
  split_list(Some(v))
} else {
  vec![".".to_string()]
};

let include = if let Some(v) = init.include.as_deref() {
  split_list(Some(v))
} else {
  vec![
    "*.ts".to_string(),
    "*.tsx".to_string(),
    "*.js".to_string(),
    "*.jsx".to_string(),
    "*.py".to_string(),
    "*.cpp".to_string(),
    "*.cc".to_string(),
    "*.c".to_string(),
    "*.hpp".to_string(),
    "*.h".to_string(),
    "*.ada".to_string(),
  ]
};

let exclude = if let Some(v) = init.exclude.as_deref() {
  split_list(Some(v))
} else {
  vec![
    "node_modules".to_string(),
    "dist".to_string(),
    "build".to_string(),
    "target".to_string(),
    ".git".to_string(),
    ".venv".to_string(),
    "__pycache__".to_string(),
    ".argus-search".to_string(),
  ]
};

let vector_base_url = init
  .vector_base_url
  .as_deref()
  .unwrap_or("https://api.openai.com/v1");
let vector_model = init
  .vector_model
  .as_deref()
  .unwrap_or("text-embedding-3-small");

let payload = default_init_config(
  (paths, include, exclude),
  vector_base_url,
  vector_model,
  init.incremental,
);

if let Some(parent) = out_path.parent() {
  fs::create_dir_all(parent)?;
}
fs::write(&out_path, serde_json::to_vec_pretty(&payload)?)?;
fs::create_dir_all(project_root.join(".argus-search"))?;
let _ = ensure_gitignore(&project_root);

let ansi = Ansi::new(std::io::stdout().is_terminal());
println!();
println!(
  "{} {}",
  ansi.check(),
  ansi.bold("Configuration initialized!")
);
println!();
println!(
  "{:16} {}",
  ansi.dim("Config file"),
  ansi.cyan(&out_path.to_string_lossy())
);
println!(
  "{:16} {}",
  ansi.dim("Project root"),
  ansi.blue(&project_root.to_string_lossy())
);
println!(
  "{:16} {}",
  ansi.dim("Vector model"),
  ansi.magenta(vector_model)
);
println!(
  "{:16} {}",
  ansi.dim("Incremental"),
  if init.incremental {
    ansi.green("enabled")
  } else {
    ansi.yellow("disabled")
  }
);
println!();
println!("{}", ansi.bold_underline("Next Steps"));
println!(
  "  {} Set {} environment variable for embeddings",
  ansi.dim("1."),
  ansi.yellow("OPENAI_API_KEY")
);
println!(
  "  {} Run {} to index your code",
  ansi.dim("2."),
  ansi.bold_cyan("ci watch --once")
);

    println!(
      "  {} Use {} to search",
      ansi.dim("3."),
      ansi.bold_cyan("ci search \"your query\"")
    );
    println!();
    return Ok(());
  }
  Command::Completions(completions) => {
    let mut cmd = Args::command();
    generate(completions.shell, &mut cmd, "ci", &mut std::io::stdout());
    return Ok(());
  }
  Command::Man => {
    let man = Man::new(Args::command());
    man.render(&mut std::io::stdout())?;
    return Ok(());
  }
  Command::Doctor(doctor) => {
    return run_doctor(
      doctor,
      config.clone(),
      project_root_override.clone(),
      store.clone(),
    );
  }
  other => other,
};

let config_path = find_up_config(config);
let mut cfg = if let Some(path) = config_path.as_deref() {
  load_config(path)?
} else {
  JsonConfig::default()
};
let project_root = resolve_project_root(config_path.as_deref(), &cfg, project_root_override);
let store_path = resolve_store_path(&project_root, store);

match command {
  Command::Watch(watch) => {
    if config_path.is_none() {
      anyhow::bail!("watch requires a config file (run: ci init)");
    }

    // Ensure store directory exists.
    if let Some(parent) = store_path.parent() {
      fs::create_dir_all(parent)?;
    }

    let (options, _provider) = build_index_options(
      &project_root,
      config_path.as_deref(),
      &cfg,
      &store_path,
      watch.no_vector,
      watch.phases.as_deref(),
    )?;

let mut checkpoint_on_finish = cfg
  .output
  .as_ref()
  .and_then(|out| out.checkpoint_on_finish)
  .unwrap_or(true);
if watch.no_checkpoint_warmup {
  checkpoint_on_finish = false;
}

let mut checkpoint_threshold = cfg
  .output
  .as_ref()
  .and_then(|out| out.checkpoint_threshold)
  .unwrap_or(0.0);
if let Some(override_threshold) = watch.checkpoint_threshold {
  checkpoint_threshold = override_threshold;
}
if !checkpoint_threshold.is_finite() {
  anyhow::bail!("checkpoint threshold must be finite");
}
checkpoint_threshold = checkpoint_threshold.clamp(0.0, 1.0);

let mut last_seen: HashMap<PathBuf, (u128, u64)> = HashMap::new();
let mut last_index = None::<Instant>;

let cancel = CancelToken::new();
loop {
  let files = match argus_search::core::parse::engine::discover_files(
    &project_root,
    &options.inputs,
    &cancel,
  ) {
    Ok(found) => found,
    Err(err) => {
      emit_watch_event(
        watch.json,
        "error",
        &store_path,
        &format!("Failed to discover files: {err}"),
      );
      sleep(Duration::from_millis(watch.poll_ms));
      continue;
    }
  };

  let mut changed = false;
  let mut current: HashMap<PathBuf, (u128, u64)> = HashMap::new();

    for file in files {
      if let Some(sig) = signature_mtime_len(&file) {
        if last_seen.get(&file).copied() != Some(sig) {
          changed = true;
        }
        current.insert(file, sig);
      }
    }
    if !last_seen.is_empty() {
      for key in last_seen.keys() {
        if !current.contains_key(key) {
          changed = true;
          break;
        }
      }
    } else {
      // First loop: always index.
      changed = true;
    }
    last_seen = current;

    if changed {
      if let Some(t) = last_index {
        if t.elapsed() < Duration::from_millis(watch.debounce_ms) {
          sleep(Duration::from_millis(watch.poll_ms));
          continue;
        }
      }
      emit_watch_event(
        watch.json,
        "index_start",
        &store_path,
        &format!("Indexing into {} ...", store_path.to_string_lossy()),
      );
      index_to_kitedb(
        options.clone(),
        &store_path,
        checkpoint_on_finish,
        checkpoint_threshold,
      )?;
      last_index = Some(Instant::now());
      emit_watch_event(watch.json, "index_complete", &store_path, "Index complete.");
      if watch.once {
        break;
      }
    }

    sleep(Duration::from_millis(watch.poll_ms));
  }

  Ok(())
}
Command::Search(search) => {
  let query = search.query.as_deref().unwrap_or("").trim();

if query.is_empty() {
  anyhow::bail!("query cannot be empty\n\nRun `ci help search` for usage");
}

if !store_path.exists() {
  anyhow::bail!(
    "index not found at {}; run: ci watch --once",
    store_path.to_string_lossy()
  );
}
if let Some(provider) = inject_search_vector_overrides(&search, &mut cfg) {
  ensure_vector_config(&mut cfg, provider);
}
if cfg.phases.as_ref().and_then(|p| p.vector) == Some(false) {
  anyhow::bail!("phases.vector is false; enable it to use search");
}
if cfg.vector.is_none() {
  anyhow::bail!(
    "vector provider missing; run: ci init (or pass --vector-base-url/--vector-model and set OPENAI_API_KEY)"
  );
}
let (_options, provider) = build_index_options(
  &project_root,
  config_path.as_deref(),
  &cfg,
  &store_path,
  false,
  None,
)
.with_context(|| {
  "vector.provider is required for semantic search (run: ci init or set --vector-base-url/--vector-model)"
})?;
let provider =
  provider.ok_or_else(|| anyhow::anyhow!("vector provider is required for search"))?;

let mut profile = SearchProfile::default();

let cache_path = query_embedding_cache_path(&store_path);
let mut embedding_cache = load_query_embedding_cache(&cache_path);
let cache_key = cfg
  .vector
  .as_ref()
  .and_then(|vector| vector.provider.as_ref())
  .map(|provider_cfg| query_embedding_cache_key(provider_cfg, query));

let t_embed = Instant::now();
let embedding = if let Some(key) = cache_key.as_deref() {
  if let Some(cached) = embedding_cache.entries.get(key) {
    cached.clone()
  } else {
    let embeddings = provider.embed_texts(&[query])?;
    let embedding = embeddings
      .into_iter()
      .next()
      .ok_or_else(|| anyhow::anyhow!("vector provider returned no embeddings"))?;
    embedding_cache
      .entries
      .insert(key.to_string(), embedding.clone());
    if let Err(err) = save_query_embedding_cache(&cache_path, &embedding_cache) {
      eprintln!(
        "warning: failed to persist query embedding cache at {}: {}",
        cache_path.to_string_lossy(),
        err
      );
    }
    embedding
  }
} else {
  let embeddings = provider.embed_texts(&[query])?;
  embeddings
    .into_iter()
    .next()
    .ok_or_else(|| anyhow::anyhow!("vector provider returned no embeddings"))?
};
profile.embed_ms = t_embed.elapsed().as_millis();

let t_open_store = Instant::now();
let store = KiteCodeStore::open_readonly(store_path.to_path_buf())?;
profile.open_store_ms = t_open_store.elapsed().as_millis();

let t_vector_search = Instant::now();
let mut hits = store.search_by_embedding(&embedding, search.top_k)?;
profile.vector_search_ms = t_vector_search.elapsed().as_millis();
profile.hits = hits.len();

if search.include_content {
  let t_content = Instant::now();
  hydrate_search_hits_content(
    &project_root,
    &store,
    &mut hits,
    search.context,
    search.content_max_chars,
  );
  profile.content_ms = t_content.elapsed().as_millis();
}

let mut impact_by_chunk_id = HashMap::<String, Vec<ImpactHit>>::new();
if search.impact {
  let t_impact = Instant::now();
  for hit in &hits {
    let impact =
      collect_transitive_call_impact(&store, &hit.chunk_id, search.impact_depth, 200)?;
    profile.impact_nodes = profile.impact_nodes.saturating_add(impact.len());
    impact_by_chunk_id.insert(hit.chunk_id.clone(), impact);
  }
  profile.impact_ms = t_impact.elapsed().as_millis();
}

let t_output = Instant::now();
let ansi = Ansi::new(search.color.enabled());

  if search.json {
    if search.impact {
      let payload = hits
        .into_iter()
        .map(|hit| SearchHitWithImpact {
          impact: impact_by_chunk_id.remove(&hit.chunk_id).unwrap_or_default(),
          hit,
        })
        .collect::<Vec<_>>();
      println!("{}", serde_json::to_string_pretty(&payload)?);
    } else {
      println!("{}", serde_json::to_string_pretty(&hits)?);
    }
  } else {
    print_search_hits(&project_root, &hits, search.context, ansi)?;
    if search.impact && !hits.is_empty() {
      print_search_impact(
        &hits,
        &impact_by_chunk_id,
        search.impact_depth.clamp(1, IMPACT_MAX_DEPTH),
        ansi,
      );
    }
  }
  profile.output_ms = t_output.elapsed().as_millis();

  if search.profile {
    profile.print(search.top_k, search.include_content, search.impact);
  }

  Ok(())
}
Command::Trace(trace) => {
  let trace_cmd = match trace.command {
    Some(cmd) => cmd,
    None => {
      print_command_help("trace", ansi);
      return Ok(());
    }
  };
  match trace_cmd {
    TraceCommand::Callers(callers) => {
      if !store_path.exists() {
        anyhow::bail!(
          "index not found at {}; run: ci watch --once",
          store_path.to_string_lossy()
        );
      }
      let store = KiteCodeStore::open_readonly(store_path.to_path_buf())?;

  let node_id =
    resolve_trace_node_id(&store, callers.node_id.as_deref(), callers.name.as_deref())?;

  let neighbors = store.graph_neighbors(&node_id, "CALLS", "in", callers.limit)?;
  if callers.json {
    println!("{}", serde_json::to_string_pretty(&neighbors)?);
  } else {
    let ansi = Ansi::new(std::io::stdout().is_terminal());

    if neighbors.is_empty() {
      println!("{}", ansi.yellow("No callers found"));
      return Ok(());
    }

    println!();
    println!(
      "{} {}",
      ansi.bold_underline("CALLERS"),
      ansi.dim(&format!("({} found)", neighbors.len()))
    );
    println!();

    for (idx, n) in neighbors.iter().enumerate() {
      let num = ansi.dim(&format!("{:3}", idx + 1));
      let id = ansi.cyan(&n.id);
      let name = n
        .name
        .as_deref()
        .map(|nm| format!("  {}", ansi.yellow(nm)))
        .unwrap_or_default();
      let file = n
        .file_path
        .as_deref()
        .map(|f| format!("  {}", ansi.blue(f)))
        .unwrap_or_default();
      println!("{num}  {id}{name}{file}");
    }
    println!();
  }
  Ok(())
}
TraceCommand::Impact(impact) => {

if !store_path.exists() {
  anyhow::bail!(
    "index not found at {}; run: ci watch --once",
    store_path.to_string_lossy()
  );
}
let store = KiteCodeStore::open_readonly(store_path.to_path_buf())?;
let node_id =
  resolve_trace_node_id(&store, impact.node_id.as_deref(), impact.name.as_deref())?;
let max_depth = impact.depth.clamp(1, IMPACT_MAX_DEPTH);
let impact_hits =
  collect_transitive_call_impact(&store, &node_id, max_depth, impact.limit)?;

if impact.json {
  println!("{}", serde_json::to_string_pretty(&impact_hits)?);
  return Ok(());
}

let ansi = Ansi::new(std::io::stdout().is_terminal());
if impact_hits.is_empty() {
  println!("{}", ansi.yellow("No impact callers found"));
  return Ok(());
}

println!();
println!(
  "{} {}",
  ansi.bold_underline("IMPACT"),
  ansi.dim(&format!(
    "(transitive callers, max depth {}, {} found)",
    max_depth,
    impact_hits.len()
  ))
);
println!();

          for item in impact_hits {
            let depth = ansi.yellow(&format!("d{}", item.depth));
            let id = ansi.magenta(&item.node.id);
            let name = item
              .node
              .name
              .as_deref()
              .map(|n| format!("  {}", ansi.green(n)))
              .unwrap_or_default();
            let file = item
              .node
              .file_path
              .as_deref()
              .map(|f| format!("  {}", ansi.blue(f)))
              .unwrap_or_default();
            println!("  {depth}  {id}{name}{file}");
          }
          println!();
          Ok(())
        }
      }
    }
    Command::Init(_) => unreachable!("handled above"),
    Command::Doctor(_) | Command::Completions(_) | Command::Man | Command::Help { .. } => {
      unreachable!("handled above")
    }
  }
}

