use std::collections::HashMap;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone)]
pub struct ModuleResolverOptions {
  pub project_root: PathBuf,
  pub base_dir: Option<PathBuf>,
  pub extensions: Vec<String>,
  pub alias: HashMap<String, String>,
}

impl ModuleResolverOptions {
  pub fn default_for(project_root: impl Into<PathBuf>) -> Self {
    Self {
      project_root: project_root.into(),
      base_dir: None,
      extensions: default_extensions(),
      alias: HashMap::new(),
    }
  }
}

pub fn resolve_module_specifier(
  specifier: &str,
  options: &ModuleResolverOptions,
) -> Option<PathBuf> {
  if is_external_module(specifier) {
    return None;
  }

  let alias_resolved = resolve_alias(specifier, &options.alias);
  let candidates = create_candidate_paths(&alias_resolved, options);

  for candidate in candidates {
    if let Some(resolved) = resolve_with_extensions(&candidate, &options.extensions) {
      return Some(resolved);
    }
  }

  None
}

fn is_external_module(specifier: &str) -> bool {
  !specifier.starts_with('.') && !specifier.starts_with('/')
}

fn resolve_alias(specifier: &str, alias: &HashMap<String, String>) -> String {
  for (key, value) in alias {
    if specifier == key || specifier.starts_with(&format!("{key}/")) {
      return specifier.replacen(key, value, 1);
    }
  }
  specifier.to_string()
}

fn create_candidate_paths(specifier: &str, options: &ModuleResolverOptions) -> Vec<PathBuf> {
  if specifier.starts_with('/') {
    let trimmed = specifier.trim_start_matches('/');
    return vec![options.project_root.join(trimmed)];
  }

  if specifier.starts_with('.') {
    let base_dir = options
      .base_dir
      .clone()
      .unwrap_or_else(|| options.project_root.clone());
    let resolved_base = if base_dir.is_absolute() {
      base_dir
    } else {
      options.project_root.join(base_dir)
    };
    return vec![resolved_base.join(specifier)];
  }

  vec![options.project_root.join(specifier)]
}

fn resolve_with_extensions(base: &Path, extensions: &[String]) -> Option<PathBuf> {
  let mut candidates = Vec::with_capacity(extensions.len() + 1);
  candidates.push(base.to_path_buf());
  for extension in extensions {
    candidates.push(base.with_extension(extension.trim_start_matches('.')));
  }

  candidates.into_iter().find(|candidate| candidate.is_file())
}

fn default_extensions() -> Vec<String> {
  vec![
    ".ts".to_string(),
    ".tsx".to_string(),
    ".js".to_string(),
    ".jsx".to_string(),
    ".mjs".to_string(),
    ".cjs".to_string(),
  ]
}

#[cfg(test)]

mod tests {
  use super::*;

  #[test]
  fn resolves_relative_module() {
    let temp = tempfile::tempdir().expect("tempdir");
    let file_path = temp.path().join("src/module.ts");
    std::fs::create_dir_all(file_path.parent().expect("parent dir")).expect("mkdir");
    std::fs::write(&file_path, "export const x = 1;").expect("write");

    let options = ModuleResolverOptions {
      project_root: temp.path().to_path_buf(),
      base_dir: Some(temp.path().join("src")),
      extensions: default_extensions(),
      alias: HashMap::new(),
    };

    let resolution = resolve_module_specifier("./module", &options);
    assert!(resolution.is_some());
  }
}

