type FindingSide = "additions" | "deletions"

type FindingLineReference = {
  file: string
  line: number
  side: FindingSide
  evidence?: string
}

type IndexedPatchLine = {
  line: number
  normalizedContent: string
}

type PatchFileLineIndex = {
  additions: IndexedPatchLine[]
  additionsSet: Set<number>
  deletions: IndexedPatchLine[]
  deletionsSet: Set<number>
}

const DIFF_FILE_RE = /^diff --git a\/(.+?) b\/(.+)$/
const HUNK_HEADER_RE = /^@@\s*-(\d+)(?:,\d+)?\s+\+(\d+)(?:,\d+)?\s*@@/

const normalizePatchPath = (value: string) =>
  value
    .trim()
    .replace(/^(\.\/)+/, "")
    .replace(/^[ab]\//, "")

const normalizeForMatch = (value: string) =>
  value
    .trim()
    .replace(/^evidence:\s*/i, "")
    .replace(/^[`'"]+|[`'"]+$/g, "")
    .replace(/\s+/g, " ")
    .toLowerCase()

const addPathAlias = (
  fileLookup: Map<string, PatchFileLineIndex>,
  path: string,
  index: PatchFileLineIndex,
) => {
  const normalizedPath = normalizePatchPath(path)
  if (!normalizedPath) {
    return
  }
  fileLookup.set(normalizedPath, index)
}

const getOrCreatePatchFileIndex = (
  fileLookup: Map<string, PatchFileLineIndex>,
  paths: string[],
) => {
  for (const path of paths) {
    const normalizedPath = normalizePatchPath(path)
    if (!normalizedPath) {
      continue
    }
    const existing = fileLookup.get(normalizedPath)
    if (existing) {
      for (const alias of paths) {
        addPathAlias(fileLookup, alias, existing)
      }
      return existing
    }
  }

  const created: PatchFileLineIndex = {
    additions: [],
    additionsSet: new Set<number>(),
    deletions: [],
    deletionsSet: new Set<number>(),
  }
  for (const path of paths) {
    addPathAlias(fileLookup, path, created)
  }
  return created
}

const buildPatchLineIndex = (patch: string) => {
  const fileLookup = new Map<string, PatchFileLineIndex>()
  const lines = patch.split(/\r?\n/)

  let currentFile: PatchFileLineIndex | null = null
  let oldLineNumber: number | null = null
  let newLineNumber: number | null = null

  for (const rawLine of lines) {
    const diffMatch = rawLine.match(DIFF_FILE_RE)
    if (diffMatch) {
      currentFile = getOrCreatePatchFileIndex(fileLookup, [diffMatch[1], diffMatch[2]])
      oldLineNumber = null
      newLineNumber = null
      continue
    }

    if (!currentFile) {
      continue
    }

    if (rawLine.startsWith("--- ") || rawLine.startsWith("+++ ")) {
      const rawPath = rawLine.slice(4).trim().split("\t")[0] ?? ""
      if (rawPath !== "/dev/null") {
        addPathAlias(fileLookup, rawPath, currentFile)
      }
      continue
    }

    const hunkHeaderMatch = rawLine.match(HUNK_HEADER_RE)
    if (hunkHeaderMatch) {
      oldLineNumber = Number.parseInt(hunkHeaderMatch[1], 10)
      newLineNumber = Number.parseInt(hunkHeaderMatch[2], 10)
      continue
    }

    if (oldLineNumber === null || newLineNumber === null) {
      continue
    }

    if (rawLine.startsWith("\\ No newline at end of file")) {
      continue
    }

    if (rawLine.startsWith("+") && !rawLine.startsWith("+++")) {
      const normalizedContent = normalizeForMatch(rawLine.slice(1))
      currentFile.additions.push({
        line: newLineNumber,
        normalizedContent,
      })
      currentFile.additionsSet.add(newLineNumber)
      newLineNumber += 1
      continue
    }

    if (rawLine.startsWith("-") && !rawLine.startsWith("---")) {
      const normalizedContent = normalizeForMatch(rawLine.slice(1))
      currentFile.deletions.push({
        line: oldLineNumber,
        normalizedContent,
      })
      currentFile.deletionsSet.add(oldLineNumber)
      oldLineNumber += 1
      continue
    }

    oldLineNumber += 1
    newLineNumber += 1
  }

  return fileLookup
}

const buildEvidenceNeedles = (evidence: string) => {
  const normalizedEvidence = evidence.trim()
  if (!normalizedEvidence) {
    return []
  }

  const lines = normalizedEvidence
    .split(/\r?\n/)
    .map((line) => normalizeForMatch(line))
    .filter((line) => line.length >= 8 && line !== "```")

  const unique = Array.from(new Set(lines))
  return unique.sort((a, b) => b.length - a.length).slice(0, 4)
}

const findEvidenceBackedLine = (
  findingLine: number,
  indexedLines: IndexedPatchLine[],
  evidence: string | undefined,
) => {
  const needles = buildEvidenceNeedles(evidence ?? "")
  if (needles.length === 0) {
    return null
  }

  let bestMatch: { line: number; strength: number; distance: number } | null = null

  for (const needle of needles) {
    for (const patchLine of indexedLines) {
      const source = patchLine.normalizedContent
      let strength = 0
      if (source === needle) {
        strength = 3
      } else if (source.includes(needle)) {
        strength = 2
      } else if (source.length >= 8 && needle.includes(source)) {
        strength = 1
      }
      if (strength === 0) {
        continue
      }

      const distance = Math.abs(patchLine.line - findingLine)
      if (
        !bestMatch ||
        strength > bestMatch.strength ||
        (strength === bestMatch.strength && distance < bestMatch.distance)
      ) {
        bestMatch = {
          line: patchLine.line,
          strength,
          distance,
        }
      }
    }
  }

  return bestMatch?.line ?? null
}

const findNearestLine = (line: number, candidates: IndexedPatchLine[]) => {
  if (candidates.length === 0) {
    return null
  }

  let nearest = candidates[0].line
  let nearestDistance = Math.abs(nearest - line)
  for (let index = 1; index < candidates.length; index += 1) {
    const candidateLine = candidates[index].line
    const distance = Math.abs(candidateLine - line)
    if (distance < nearestDistance) {
      nearest = candidateLine
      nearestDistance = distance
    }
  }
  return nearest
}

export const reconcileFindingLinesWithPatch = <T extends FindingLineReference>({
  patch,
  findings,
}: {
  patch: string
  findings: T[]
}): T[] => {
  if (!patch.trim() || findings.length === 0) {
    return findings
  }

  const fileLookup = buildPatchLineIndex(patch)
  if (fileLookup.size === 0) {
    return findings
  }

  return findings.map((finding) => {
    const fileIndex = fileLookup.get(normalizePatchPath(finding.file))
    if (!fileIndex) {
      return finding
    }

    const isDeletion = finding.side === "deletions"
    const indexedLines = isDeletion ? fileIndex.deletions : fileIndex.additions
    const indexedSet = isDeletion ? fileIndex.deletionsSet : fileIndex.additionsSet
    if (indexedLines.length === 0) {
      return finding
    }

    const evidenceLine = findEvidenceBackedLine(
      finding.line,
      indexedLines,
      finding.evidence,
    )
    if (evidenceLine !== null && evidenceLine !== finding.line) {
      return {
        ...finding,
        line: evidenceLine,
      }
    }

    if (indexedSet.has(finding.line)) {
      return finding
    }

    const nearestLine = findNearestLine(finding.line, indexedLines)
    if (nearestLine === null || nearestLine === finding.line) {
      return finding
    }

    return {
      ...finding,
      line: nearestLine,
    }
  })
}

