const ACTIVE_TOOL_STORAGE_KEY = "argus-active-tool"
const REPO_DIALOG_CACHE_TTL_MS = 45_000

type ReviewProjectsCacheEntry = {
  expiresAt: number
  projects: ReviewProject[]
}

type DiscoverableProjectsCacheEntry = {
  expiresAt: number
  seedKey: string
  projects: DiscoverableProject[]
  failureCount: number
  instanceCount: number
}

let reviewProjectsCacheEntry: ReviewProjectsCacheEntry | null = null
let discoverableProjectsCacheEntry: DiscoverableProjectsCacheEntry | null = null

const getFreshReviewProjectsCache = () => {
  if (!reviewProjectsCacheEntry) {
    return null
  }

  if (reviewProjectsCacheEntry.expiresAt <= Date.now()) {
    reviewProjectsCacheEntry = null
    return null
  }

  return reviewProjectsCacheEntry.projects
}

const setReviewProjectsCache = (projects: ReviewProject[]) => {
  reviewProjectsCacheEntry = {
    expiresAt: Date.now() + REPO_DIALOG_CACHE_TTL_MS,
    projects,
  }
}

const getFreshDiscoverableProjectsCache = (seedKey: string) => {
  if (!discoverableProjectsCacheEntry) {
    return null
  }

  if (discoverableProjectsCacheEntry.expiresAt <= Date.now()) {
    discoverableProjectsCacheEntry = null
    return null
  }

  if (discoverableProjectsCacheEntry.seedKey !== seedKey) {
    return null
  }

  return discoverableProjectsCacheEntry
}

const setDiscoverableProjectsCache = (
  seedKey: string,
  projects: DiscoverableProject[],
  failureCount: number,
  instanceCount: number,
) => {
  discoverableProjectsCacheEntry = {
    expiresAt: Date.now() + REPO_DIALOG_CACHE_TTL_MS,
    seedKey,
    projects,
    failureCount,
    instanceCount,
  }
}

const clearRepoDialogCaches = () => {
  reviewProjectsCacheEntry = null
  discoverableProjectsCacheEntry = null
}

