  seeds
    .map((seed) => `${seed.instanceUrl.trim().toLowerCase()}::${seed.integrationId.trim()}`)
    .sort()
    .join("|")

const TOOLS: SidebarTool[] = [
  {
    id: "review-agent",
    title: "Review Agent",
    icon: IconDashboard,
  },
  {
    id: "sldc-flow",
    title: "SLDC Flow",
    icon: IconBrain,
  },
  {
    id: "analytics",
    title: "Analytics",
    icon: IconChartBar,
  },
  {
    id: "observability",
    title: "Observability",
    icon: IconActivityHeartbeat,
  },
]

const inferToolFromPathname = (pathname: string): ToolId | null => {
  if (pathname.startsWith("/observability")) {
    return "observability"
  }

  if (pathname.startsWith("/sldc-flow")) {
    return "sldc-flow"
  }

  if (pathname.startsWith("/analytics")) {
    return "analytics"
  }

  if (
    pathname.startsWith("/repos") ||
    pathname.startsWith("/indexing") ||
    pathname.startsWith("/code-graph") ||
    pathname.startsWith("/integrations")
  ) {
    return "review-agent"
  }

  return null
}

const isToolId = (value: string | null): value is ToolId =>
  value === "review-agent" ||
  value === "sldc-flow" ||
  value === "analytics" ||
  value === "observability"

const asDateValue = (value: string | null | undefined) => {
  if (!value) {
    return 0
  }

  const parsed = new Date(value)
  return Number.isNaN(parsed.getTime()) ? 0 : parsed.getTime()
}

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null

const buildProjectScopeKey = (instanceUrl: string, projectId: string) =>
  `${instanceUrl.trim().toLowerCase()}::${projectId.trim()}`

const getApiErrorMessage = (payload: unknown, fallback: string) => {
  if (isRecord(payload) && typeof payload.error === "string") {
    return payload.error
  }

  return fallback
}

const getDiscoverProjectsResult = (failureCount: number, instanceCount: number) => {
  if (failureCount === instanceCount) {
    return {
      state: "error" as const,
      status: "Could not load repositories from connected GitLab instances.",
    }
  }

  return {
    state: "ready" as const,
    status:
      failureCount > 0
        ? "Loaded repositories from available instances. Some instances failed."
        : "",
  }
}

export function AppSidebar({ ...props }: React.ComponentProps<typeof Sidebar>) {
