}, [activeTool])

React.useEffect(() => {
  if (activeTool !== "review-agent") {
    return
  }

  const controller = new AbortController()
  let didCancel = false

  const loadProjects = async () => {
    const shouldForceRefresh = forceProjectsRefreshNonceRef.current === projectsReloadNonce
    if (!shouldForceRefresh) {
      const cachedProjects = getFreshReviewProjectsCache()
      if (cachedProjects) {
        setReviewProjects(cachedProjects)
        setProjectsState("ready")
        return
      }
    }

    setProjectsState("loading")

try {
  const response = await fetch("/api/gitlab/integrations", {
    method: "GET",
    headers: {
      "content-type": "application/json",
    },
    signal: controller.signal,
  })

  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    throw new Error(
      payload &&
        typeof payload === "object" &&
        "error" in payload &&
        typeof (payload as { error?: unknown }).error === "string"
        ? (payload as { error: string }).error
        : "Failed to load review projects.",
    )
  }

  const projects =
    payload &&
      typeof payload === "object" &&
      "data" in payload &&
      Array.isArray((payload as { data?: unknown }).data)
      ? (payload as { data: ReviewProject[] }).data
      : []

  if (didCancel) {
    return
  }

  const nextProjects = [...projects].sort(
    (left, right) => asDateValue(right.updatedAt) - asDateValue(left.updatedAt),
  )

  if (shouldForceRefresh && forceProjectsRefreshNonceRef.current === projectsReloadNonce) {
    forceProjectsRefreshNonceRef.current = null
  }

  setReviewProjects(nextProjects)
  setReviewProjectsCache(nextProjects)
  setProjectsState("ready")
} catch (error) {

      if (shouldForceRefresh && forceProjectsRefreshNonceRef.current === projectsReloadNonce) {
        forceProjectsRefreshNonceRef.current = null
      }

      if (didCancel || (error instanceof DOMException && error.name === "AbortError")) {
        return
      }

      setProjectsState("error")
    }
  }

  void loadProjects()

  return () => {
    didCancel = true
    controller.abort()
  }
}, [activeTool, projectsReloadNonce])

React.useEffect(() => {
  if (!isRepoDialogOpen || activeTool !== "review-agent") {
    return
  }

  void loadDiscoverableProjects()
}, [activeTool, isRepoDialogOpen, loadDiscoverableProjects])

