import { describe, expect, mock, test } from "bun:test"

import type { TokenTestFeedback } from "@/components/onboarding/onboarding-types"

const loadModule = async () => {
  mock.module("react", () => ({
    useCallback: <T,>(fn: T) => fn,
    useEffect: () => {},
  }))

  return import(
    `@/components/onboarding/hooks/use-onboarding-token-autotest.ts?cacheBust=${Math.random()
      .toString(36)
      .slice(2)}`,
  )
}

const createOptions = () => {
  const signature = "https://gitlab.com::hash-1"
  const tokenTestResultCacheRef = {
    current: new Map<string, { checkedAt: number; feedback: TokenTestFeedback }>(),
  }
  const options = {
    isHydrated: true,
    routeStep: "tokens" as const,
    canLoadProjects: true,
    actionBusy: false,
    resolvedGitLabInstance: "https://gitlab.com",
    tokenCacheHash: "hash-1",
    fetchProjects: mock(async () => []),
    applyLoadedProjects: mock(() => undefined),
    tokenTestResultCacheRef,
    tokenTestSignatureRef: { current: null as string | null },
    tokenTestRunRef: { current: 0 },
    tokenAutoTestTimeoutRef: { current: null as number | null },
    setTokenTestBusy: mock(() => undefined),
    setProjectsError: mock(() => undefined),
    setMergeRequestsError: mock(() => undefined),
    setTokenTestFeedback: mock(() => undefined),
    getErrorMessage: () => "error",
  }

  return { options, signature }
}

describe("use-onboarding-token-autotest", () => {

test("triggerTokenAutotestNow skips network retest for the same active signature", async () => {
  const mod = await loadModule()
  const { options, signature } = createOptions()
  options.tokenTestSignatureRef.current = signature

  const model = mod.useOnboardingTokenAutotest(options)
  model.triggerTokenAutotestNow()

  expect(options.fetchProjects).not.toHaveBeenCalled()
  expect(options.setTokenTestBusy).not.toHaveBeenCalled()
})

test("triggerTokenAutotestNow reuses fresh cache without clearing validated feedback", async () => {
  const mod = await loadModule()
  const { options, signature } = createOptions()
  const feedback: TokenTestFeedback = { kind: "success", message: "Token is valid." }
  options.tokenTestResultCacheRef.current.set(signature, {
    checkedAt: Date.now(),
    feedback,
  })

  const model = mod.useOnboardingTokenAutotest(options)
  model.triggerTokenAutotestNow()

  expect(options.tokenTestSignatureRef.current).toBe(signature)
  expect(options.setTokenTestFeedback).toHaveBeenCalledWith(feedback)
  expect(options.fetchProjects).not.toHaveBeenCalled()
  expect(options.setTokenTestBusy).not.toHaveBeenCalled()
})

  test("triggerTokenAutotestNow validates by loading projects and only reports success after load", async () => {
    const mod = await loadModule()
    const { options } = createOptions()
    const projects = [{ id: "1", name: "Project 1", path: "group/project-1", webUrl: "" }]
    options.fetchProjects = mock(async () => projects)

    const model = mod.useOnboardingTokenAutotest(options)
    model.triggerTokenAutotestNow()
    await Promise.resolve()
    await Promise.resolve()

    expect(options.fetchProjects).toHaveBeenCalledTimes(1)
    expect(options.applyLoadedProjects).toHaveBeenCalledWith(projects)
    expect(options.setTokenTestFeedback).not.toHaveBeenCalledWith({
      kind: "success",
      message: "Token is valid.",
    })
    expect(options.setTokenTestFeedback).toHaveBeenLastCalledWith({
      kind: "success",
      message: "Token is valid. Found 1 project.",
    })
  })
})

from fastapi import APIRouter

from py_core.health import build_health_payload

router = APIRouter()


@router.get("/health")
def get_health() -> dict[str, str]:
    return build_health_payload(service="api-health")

  const runId = ++tokenTestRunRef.current
  setTokenTestBusy(true)
  setProjectsError("")
  setMergeRequestsError("")
  setTokenTestFeedback(null)

  try {
    const data = await fetchProjects()
    if (tokenTestSignatureRef.current !== signature || runId !== tokenTestRunRef.current) {
      return
    }

    applyLoadedProjects(data)
    const countLabel = data.length === 1 ? "1 project" : `${data.length} projects`
    const countFeedback: TokenTestFeedback = {
      kind: "success",
      message: `Token is valid. Found ${countLabel}.`,
    }
    tokenTestResultCacheRef.current.set(signature, {
      checkedAt: Date.now(),
      feedback: countFeedback,
    })
    persistTokenTestCache(tokenTestResultCacheRef.current)
    setTokenTestFeedback(countFeedback)
  } catch (error) {
    if (tokenTestSignatureRef.current !== signature || runId !== tokenTestRunRef.current) {
      return
    }
    const feedback: TokenTestFeedback = {
      kind: "error",
      message: getErrorMessage(error),
    }
    tokenTestResultCacheRef.current.set(signature, { checkedAt: Date.now(), feedback })
    persistTokenTestCache(tokenTestResultCacheRef.current)
    setTokenTestFeedback(feedback)
  } finally {
    if (runId === tokenTestRunRef.current) {
      setTokenTestBusy(false)
    }
  }
}, [

  if (!isHydrated || routeStep !== "tokens" || !canLoadProjects || actionBusy) {
    tokenTestRunRef.current += 1
    setTokenTestBusy(false)
    if (!canLoadProjects) {
      tokenTestSignatureRef.current = null
    }
    if (tokenAutoTestTimeoutRef.current !== null) {
      window.clearTimeout(tokenAutoTestTimeoutRef.current)
      tokenAutoTestTimeoutRef.current = null
    }
    return
  }

  const signature = buildSignature()
  const cached = tokenTestResultCacheRef.current.get(signature)
  const now = Date.now()

  if (cached && now - cached.checkedAt < TOKEN_TEST_CACHE_TTL_MS) {
    setTokenTestFeedback(cached.feedback)
    tokenTestSignatureRef.current = signature
    return
  }
  if (cached) {
    tokenTestResultCacheRef.current.delete(signature)
