use std::fs::{create_dir_all, File};
use std::io::{BufWriter, Write};
use std::path::{Path, PathBuf};

use serde::Serialize;
use time::format_description::well_known::Rfc3339;
use time::OffsetDateTime;

use super::records::{IndexPackManifest, IndexPackStats};

const CHUNKS_FILE: &str = "chunks.jsonl";
const GRAPH_NODES_FILE: &str = "graph.nodes.jsonl";
const GRAPH_EDGES_FILE: &str = "graph.edges.jsonl";
const VECTORS_FILE: &str = "vectors.jsonl";
const MANIFEST_FILE: &str = "manifest.json";

#[derive(Debug, Clone)]
pub struct IndexPackWriterOptions {
  pub out_dir: PathBuf,
  pub schema_version: String,
  pub index_run_id: String,
  pub project_root: PathBuf,
  pub project_root_rel: Option<String>,
}

impl IndexPackWriterOptions {
  pub fn new(
    out_dir: impl Into<PathBuf>,
    schema_version: impl Into<String>,
    index_run_id: impl Into<String>,
    project_root: impl Into<PathBuf>,
  ) -> Self {
    Self {
      out_dir: out_dir.into(),
      schema_version: schema_version.into(),
      index_run_id: index_run_id.into(),
      project_root: project_root.into(),
      project_root_rel: None,
    }
  }
}

#[derive(Debug)]
pub struct IndexPackWriter {
  options: IndexPackWriterOptions,
  chunks_writer: BufWriter<File>,
  nodes_writer: BufWriter<File>,
  edges_writer: BufWriter<File>,
  vectors_writer: BufWriter<File>,
  stats: IndexPackStats,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct RecordEnvelope<'a, T: Serialize> {
  schema_version: &'a str,
  index_run_id: &'a str,
  #[serde(flatten)]
  record: &'a T,
}

impl IndexPackWriter {

pub fn new(options: IndexPackWriterOptions) -> std::io::Result<Self> {
  create_dir_all(&options.out_dir)?;

  let chunks_writer = BufWriter::new(open_file(&options.out_dir, CHUNKS_FILE)?);
  let nodes_writer = BufWriter::new(open_file(&options.out_dir, GRAPH_NODES_FILE)?);
  let edges_writer = BufWriter::new(open_file(&options.out_dir, GRAPH_EDGES_FILE)?);
  let vectors_writer = BufWriter::new(open_file(&options.out_dir, VECTORS_FILE)?);

  Ok(Self {
    options,
    chunks_writer,
    nodes_writer,
    edges_writer,
    vectors_writer,
    stats: IndexPackStats::default(),
  })
}

pub fn write_chunk<T: Serialize>(&mut self, record: &T) -> std::io::Result<()> {
  let envelope = RecordEnvelope {
    schema_version: &self.options.schema_version,
    index_run_id: &self.options.index_run_id,
    record,
  };
  write_json_line(&mut self.chunks_writer, &envelope)?;
  self.bump_chunks();
  Ok(())
}

pub fn write_node<T: Serialize>(&mut self, record: &T) -> std::io::Result<()> {
  let envelope = RecordEnvelope {
    schema_version: &self.options.schema_version,
    index_run_id: &self.options.index_run_id,
    record,
  };
  write_json_line(&mut self.nodes_writer, &envelope)?;
  self.bump_nodes();
  Ok(())
}

pub fn write_edge<T: Serialize>(&mut self, record: &T) -> std::io::Result<()> {
  let envelope = RecordEnvelope {
    schema_version: &self.options.schema_version,
    index_run_id: &self.options.index_run_id,
    record,
  };
  write_json_line(&mut self.edges_writer, &envelope)?;
  self.bump_edges();
  Ok(())
}

pub fn write_vector<T: Serialize>(&mut self, record: &T) -> std::io::Result<()> {
  let envelope = RecordEnvelope {
    schema_version: &self.options.schema_version,
    index_run_id: &self.options.index_run_id,
    record,
  };
  write_json_line(&mut self.vectors_writer, &envelope)?;
  self.bump_vectors();
  Ok(())
}

pub fn set_files_parsed(&mut self, count: u64) {
  self.stats.files_parsed = Some(count);
}

  pub fn finalize(&mut self) -> std::io::Result<IndexPackManifest> {
    self.chunks_writer.flush()?;
    self.nodes_writer.flush()?;
    self.edges_writer.flush()?;
    self.vectors_writer.flush()?;

    let manifest = IndexPackManifest {
      schema_version: self.options.schema_version.clone(),
      index_run_id: self.options.index_run_id.clone(),
      project_root: self.path_to_string(&self.options.project_root),
      project_root_rel: self
        .options
        .project_root_rel
        .clone()
        .unwrap_or_else(|| ".".to_string()),
      generated_at: now_rfc3339(),
      stats: Some(self.stats.clone()),
    };

    let manifest_path = self.options.out_dir.join(MANIFEST_FILE);
    let manifest_file = File::create(manifest_path)?;
    serde_json::to_writer_pretty(manifest_file, &manifest)?;

    Ok(manifest)
  }

  fn bump_chunks(&mut self) {
    let next = self.stats.chunks_emitted.unwrap_or(0) + 1;
    self.stats.chunks_emitted = Some(next);
  }

  fn bump_nodes(&mut self) {
    let next = self.stats.nodes_emitted.unwrap_or(0) + 1;
    self.stats.nodes_emitted = Some(next);
  }

  fn bump_edges(&mut self) {
    let next = self.stats.edges_emitted.unwrap_or(0) + 1;
    self.stats.edges_emitted = Some(next);
  }

  fn bump_vectors(&mut self) {
    let next = self.stats.vectors_emitted.unwrap_or(0) + 1;
    self.stats.vectors_emitted = Some(next);
  }

  fn path_to_string(&self, path: &Path) -> String {
    path.to_string_lossy().to_string()
  }
}

fn open_file(out_dir: &Path, name: &str) -> std::io::Result<File> {
  File::create(out_dir.join(name))
}

fn write_json_line<T: Serialize>(writer: &mut BufWriter<File>, record: &T) -> std::io::Result<()> {
  serde_json::to_writer(&mut *writer, record)?;
  writer.write_all(b"\n")?;
  Ok(())
}

fn now_rfc3339() -> String {
  OffsetDateTime::now_utc()
    .format(&Rfc3339)
    .unwrap_or_else(|_| "1970-01-01T00:00:00Z".to_string())
}

#[cfg(test)]
mod tests {
  use super::*;

  #[test]
  fn writes_manifest_with_stats() -> Result<(), Box<dyn std::error::Error>> {
    let temp = tempfile::tempdir()?;
    let options = IndexPackWriterOptions::new(temp.path(), "1.0.0", "run-1", temp.path());
    let mut writer = IndexPackWriter::new(options)?;

    writer.write_chunk(&serde_json::json!({ "id": "chunk-1" }))?;
    writer.write_node(&serde_json::json!({ "id": "node-1" }))?;
    writer.write_edge(&serde_json::json!({ "sourceId": "node-1", "targetId": "node-2" }))?;
    writer.write_vector(&serde_json::json!({ "chunkId": "chunk-1" }))?;
    writer.set_files_parsed(2);

    let manifest = writer.finalize()?;

    assert_eq!(manifest.schema_version, "1.0.0");
    assert_eq!(manifest.index_run_id, "run-1");
    let stats = manifest.stats.expect("stats");
    assert_eq!(stats.files_parsed, Some(2));
    assert_eq!(stats.chunks_emitted, Some(1));
    assert_eq!(stats.nodes_emitted, Some(1));
    assert_eq!(stats.edges_emitted, Some(1));
    assert_eq!(stats.vectors_emitted, Some(1));

    Ok(())
  }
}

