export type SiteHeaderBreadcrumb = {
  label: string
  href: string | null
}

const SEGMENT_LABELS: Record<string, string> = {
  "code-graph": "Code Graph",
  integrations: "Integrations",
  indexing: "Indexing",
  "indexing-health": "Indexing Health",
  logs: "Log Explorer",
  mrs: "Merge Requests",
  model: "Model",
  observability: "Observability",
  onboarding: "Onboarding",
  "onboarding-ttfr": "Onboarding TTFR",
  projects: "Projects",
  repos: "Repositories",
  "sldc-flow": "SLDC Flow",
  settings: "Settings",
  tokens: "Tokens",
  description: "Description",
}

const decodeSegment = (segment: string) => {
  try {
    return decodeURIComponent(segment)
  } catch {
    return segment
  }
}

const toTitleCase = (value: string) =>
  value
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => (
      word.length <= 2
        ? word.toUpperCase()
        : `${word[0]?.toUpperCase() ?? ""}${word.slice(1)}`
    ))
    .join(" ")

const humanize = (value: string) => {
  const normalized = value
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()

  return normalized ? toTitleCase(normalized) : value
}

const formatRepoRouteId = (value: string) => {
  const parts = value.split("--")
  if (parts.length < 3) {
    return humanize(value)
  }

  const projectToken = parts[1]?.trim()
  if (!projectToken) {
    return humanize(value)
  }

  return humanize(projectToken)
}

const segmentLabel = (segments: string[], index: number) => {
  const current = decodeSegment(segments[index] ?? "")
  const previous = decodeSegment(segments[index - 1] ?? "")

  if (previous === "repos") {
    return formatRepoRouteId(current)
  }

  if (previous === "mrs") {
    return `!${current}`
  }

  return SEGMENT_LABELS[current] ?? humanize(current)
}

export const buildSiteHeaderBreadcrumbs = (pathname: string): SiteHeaderBreadcrumb[] => {
  const rawSegments = pathname.split("/").filter(Boolean)
  const segments = rawSegments.filter((segment, index) => {
    const current = decodeSegment(segment)
    const twoBack = decodeSegment(rawSegments[index - 2] ?? "")

    if (current === "description" && twoBack === "mrs") {
      return false
    }

    return true
  })

  if (segments.length === 0) {
    return [{ label: "Home", href: null }]
  }

  return segments.map((_, index) => {
    const isLast = index === segments.length - 1
    const href = isLast ? null : `/${segments.slice(0, index + 1).join("/")}`

    return {
      label: segmentLabel(segments, index),
      href,
    }
  })
}

export const resolveSiteHeaderTitle = (
  explicitTitle: string | null,
) => (explicitTitle?.trim() ? explicitTitle : null)

fn main() {
  napi_build::setup();

  // `pyo3` with `extension-module` intentionally doesn't link to libpython.
  // That's correct for the extension module itself, but it breaks `cargo test`
  // when `python-tests` are enabled because the unit-test binary needs Python
  // symbols resolved at link/runtime.
  //
  // For a nicer dev experience on macOS, link against the interpreter's
  // `libpythonX.Y.dylib` and add an `rpath` so the test binary can run.
  #[cfg(target_os = "macos")]
  if std::env::var_os("CARGO_FEATURE_PYTHON_TESTS").is_some() {
    println!("cargo:rerun-if-env-changed=PYTHON_SYS_EXECUTABLE");
    println!("cargo:rerun-if-env-changed=PYO3_PYTHON");

    let python = std::env::var("PYTHON_SYS_EXECUTABLE")
      .or_else(|_| std::env::var("PYO3_PYTHON"))
      .unwrap_or_else(|_| "python3".to_string());

    let output = std::process::Command::new(&python)
      .args([
        "-c",
        "import sysconfig; \
         print(sysconfig.get_config_var('LIBDIR') or ''); \
         print(sysconfig.get_config_var('LDLIBRARY') or '')",
      ])
      .output();

    let Ok(output) = output else {
      println!("cargo:warning=python-tests enabled but failed to run python to discover libpython");
      return;
    };
    if !output.status.success() {
      println!(
        "cargo:warning=python-tests enabled but python discovery failed (exit {})",
        output.status
      );
      return;
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut lines = stdout.lines();

    let Some(libdir) = lines.next() else {
      println!("cargo:warning=python-tests enabled but LIBDIR was not discovered");
      return;
    };
    let Some(ldlibrary) = lines.next() else {
      println!("cargo:warning=python-tests enabled but LDLIBRARY was not discovered");
      return;
    };

    let libdir = libdir.trim();
    let ldlibrary = ldlibrary.trim();
    if libdir.is_empty() || ldlibrary.is_empty() {
      println!("cargo:warning=python-tests enabled but libpython path could not be determined");
      return;
    }

    let libname = ldlibrary
      .strip_prefix("lib")
      .and_then(|name| name.strip_suffix(".dylib"))
      .unwrap_or(ldlibrary);

    println!("cargo:rustc-link-search=native={libdir}");
    println!("cargo:rustc-link-lib=dylib={libname}");
    println!("cargo:rustc-link-arg=-Wl,-rpath,{libdir}");
  }
}

