import Link from "next/link"
import { notFound, redirect } from "next/navigation"

import { MergeRequestDescriptionStreamPage } from "@/components/merge-request-diff/merge-request-description-stream-page"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  buildRepoMergeRequestDescriptionPath,
  buildRepoMergeRequestPath,
  buildRepoPath,
  buildRepoRouteId,
  findIntegrationByRepoRouteId,
} from "@/lib/gitlab/repo-route"
import { getCachedUserIntegrations } from "@/lib/gitlab/user-integrations-cache"
import { getSession } from "@/lib/session"

type MergeRequestDescriptionPageProps = {
  params: Promise<{
    integrationId: string
    mergeRequestIid: string
  }>
}

const integrationStatusLabel: Record<"active" | "degraded" | "disabled", string> = {
  active: "Active",
  degraded: "Degraded",
  disabled: "Disabled",
}

const integrationStatusVariant: Record<"active" | "degraded" | "disabled", "default" | "secondary" | "outline"> = {
  active: "default",
  degraded: "secondary",
  disabled: "outline",
}

export default async function MergeRequestDescriptionPage({
  params,
}: MergeRequestDescriptionPageProps) {
  const [session, { integrationId: repoRouteId, mergeRequestIid }] = await Promise.all([
    getSession(),
    params,
  ])

  if (!session?.user?.id) {
    redirect("/")
  }

  const integrations = await getCachedUserIntegrations(session.user.id)
  const integration = findIntegrationByRepoRouteId(integrations, repoRouteId)
  if (!integration) {
    notFound()
  }

  const canonicalRepoRouteId = buildRepoRouteId(integration)
  if (repoRouteId !== canonicalRepoRouteId) {
    redirect(buildRepoMergeRequestDescriptionPath(integration, mergeRequestIid))
  }

  return (
    <div className="space-y-4">
      <section className="space-y-2">
        <div className="flex flex-wrap items-center justify-between gap-2">
          <div className="space-y-1">
            <div className="flex flex-wrap items-center gap-2">
              <h1 className="text-2xl font-semibold">MR Description</h1>
              <Badge variant={integrationStatusVariant[integration.status]}>
                {integrationStatusLabel[integration.status]}
              </Badge>
            </div>
            <p className="text-sm text-muted-foreground">
              {integration.projectPath} · MR !{mergeRequestIid}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <Button asChild size="sm" variant="outline">
              <Link href={buildRepoMergeRequestPath(integration, mergeRequestIid)}>Back to review</Link>
            </Button>
            <Button asChild size="sm" variant="outline">
              <Link href={buildRepoPath(integration)}>Repo workspace</Link>
            </Button>
          </div>
        </div>
      </section>

      <MergeRequestDescriptionStreamPage
        instanceUrl={integration.instanceUrl}
        token=""
        integrationId={integration.id}
        projectId={integration.projectId}
        mergeRequestIid={mergeRequestIid}
      />
    </div>
  )
}

import { NextResponse } from "next/server"
import { z } from "zod"

import { db } from "@/lib/db"
import { analyticsUserActivityEvents } from "@/lib/db/schema"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const payloadSchema = z
  .object({
    event: z.enum(["command_used", "feature_opened", "session_duration"]),
    feature: z.string().trim().min(1).max(160).optional(),
    command: z.string().trim().min(1).max(160).optional(),
    sessionId: z.string().trim().min(1).max(120).optional(),
    durationMs: z.coerce.number().int().nonnegative().max(1000 * 60 * 60 * 24).optional(),
    metadata: z.record(z.string(), z.unknown()).optional(),
  })
  .strict()

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/analytics/track",
    event: "api.analytics.track",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const parsed = payloadSchema.safeParse(await request.json().catch(() => null))
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid analytics event payload." }, { status: 400 }),
        }
      }

      if (parsed.data.event === "command_used" && !parsed.data.command) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "command is required for command_used." }, { status: 400 }),
        }
      }
      if (parsed.data.event === "feature_opened" && !parsed.data.feature) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "feature is required for feature_opened." }, { status: 400 }),
        }
      }
      if (parsed.data.event === "session_duration" && parsed.data.durationMs === undefined) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "durationMs is required for session_duration." }, { status: 400 }),
        }
      }

      await db.insert(analyticsUserActivityEvents).values({
        userId,
        event: parsed.data.event,
        feature: parsed.data.feature,
        command: parsed.data.command,
        sessionId: parsed.data.sessionId,
        durationMs: parsed.data.durationMs,
        metadata: parsed.data.metadata,
      })

      logger.set({
        analyticsEvent: parsed.data.event,
        feature: parsed.data.feature ?? null,
        command: parsed.data.command ?? null,
        hasDuration: parsed.data.durationMs !== undefined,
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ ok: true }),
      }
    },
  })
}

import { useCallback, useState } from "react"

import {
  INITIAL_FILE_BATCH_SIZE,
  type DiffStyle,
  type DiffThemeMode,
} from "../merge-request-diff-viewer.utils"

export function useMergeRequestDiffUiState() {
  const [diffThemeMode, setDiffThemeMode] = useState<DiffThemeMode>("system")
  const [collapsedFileKeys, setCollapsedFileKeys] = useState<Set<string>>(new Set())

  const [filenameFilter, setFilenameFilter] = useState("")
  const [diffStyle, setDiffStyle] = useState<DiffStyle>("split")
  const [wrapLines, setWrapLines] = useState(false)
  const [showLineNumbers, setShowLineNumbers] = useState(true)
  const [visibleResetToken, setVisibleResetToken] = useState(0)
  const [visibleWindow, setVisibleWindow] = useState<{
    key: string
    count: number
  }>({
    key: "",
    count: INITIAL_FILE_BATCH_SIZE,
  })

  const resetVisibleFileCount = useCallback(() => {
    setVisibleResetToken((current) => current + 1)
  }, [])

  const cycleDiffThemeMode = useCallback(() => {
    setDiffThemeMode((current) => {
      if (current === "system") {
        return "light"
      }
      if (current === "light") {
        return "dark"
      }
      return "system"
    })
  }, [])

  return {
    diffThemeMode,
    setDiffThemeMode,
    collapsedFileKeys,
    setCollapsedFileKeys,
    filenameFilter,
    setFilenameFilter,
    diffStyle,
    setDiffStyle,
    wrapLines,
    setWrapLines,
    showLineNumbers,
    setShowLineNumbers,
    visibleResetToken,
    visibleWindow,
    setVisibleWindow,
    resetVisibleFileCount,
    cycleDiffThemeMode,
  }
}

