const withEnv = async <T>(
  overrides: Partial<NodeJS.ProcessEnv>,
  fn: () => Promise<T>,
): Promise<T> => {
  const previous = new Map<string, string | undefined>()

  for (const [key, value] of Object.entries(overrides)) {
    previous.set(key, process.env[key])
    if (value === undefined) {
      delete process.env[key]
    } else {
      process.env[key] = value
    }
  }

  try {
    return await fn()
  } finally {
    for (const [key, value] of previous.entries()) {
      if (value === undefined) {
        delete process.env[key]
      } else {
        process.env[key] = value
      }
    }
  }
}

const createSnapshotArchive = async (files: Record<string, string>) => {
  const root = await mkdtemp(path.join(os.tmpdir(), 'argus-indexer-e2e-archive-'))
  const repoDir = path.join(root, 'repo')
  await mkdir(repoDir, { recursive: true })

  for (const [relativePath, content] of Object.entries(files)) {
    const absolutePath = path.join(repoDir, relativePath)
    await mkdir(path.dirname(absolutePath), { recursive: true })
    await writeFile(absolutePath, content, 'utf8')
  }

  const archivePath = path.join(root, 'repo.tar.gz')
  await execFileAsync('tar', ['-czf', archivePath, '-C', root, 'repo'])
  return {
    root,
    archivePath,
  }
}

