  if (typeof value === "bigint") {
    return Number(value)
  }
  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number.parseInt(value, 10)
    return Number.isFinite(parsed) ? parsed : 0
  }
  return 0
}

const asDate = (value: unknown): Date | null => {
  if (!value) {
