import { existsSync } from "node:fs"
import path from "node:path"

const ARGUS_SEARCH_CONFIG = "argus-search.json"

export const resolveCodeIntelRootFrom = (startDir: string): string => {
  let cursor = path.resolve(startDir)

  while (true) {
    const candidate = path.join(cursor, ARGUS_SEARCH_CONFIG)
    if (existsSync(candidate)) {
      return cursor
    }

    const parent = path.dirname(cursor)
    if (parent === cursor) {
      throw new Error(`Could not locate ${ARGUS_SEARCH_CONFIG} from ${startDir}`)
    }
    cursor = parent
  }
}

export const resolveCodeIntelRoot = () => resolveCodeIntelRootFrom(process.cwd())

export const resolveCodeIntelConfigPath = () =>
  path.join(resolveCodeIntelRoot(), ARGUS_SEARCH_CONFIG)

export const resolveCodeIntelIndexPackDir = () =>
  path.join(resolveCodeIntelRoot(), ".argus-search", "index-pack")

