  test("persists onboarding state patches without dropping existing keys", () => {
    const originalWindow = (globalThis as { window?: unknown }).window
    const storage = new Map<string, string>()
    const mockWindow = {
      sessionStorage: {
        getItem: (key: string) => storage.get(key) ?? null,
        setItem: (key: string, value: string) => {
          storage.set(key, value)
        },
        removeItem: (key: string) => {
          storage.delete(key)
        },
        clear: () => {
          storage.clear()
        },
      },
    }

    Object.defineProperty(globalThis, "window", {
      configurable: true,
      value: mockWindow,
    })

    try {
      mockWindow.sessionStorage.setItem(
        ONBOARDING_STORAGE_KEY,
        JSON.stringify({
          token: "existing-token",
          selectedProjectId: "",
        }),
      )

      persistOnboardingStatePatch({
        selectedProjectId: "project-9",
        selectedMergeRequestId: "",
      })

      expect(readPersistedState()).toMatchObject({
        token: "existing-token",
        selectedProjectId: "project-9",
        selectedMergeRequestId: "",
      })
    } finally {
      if (originalWindow === undefined) {
        Reflect.deleteProperty(globalThis, "window")
      } else {
        Object.defineProperty(globalThis, "window", {
          configurable: true,
          value: originalWindow,
        })
      }
    }
  })
})

export const processReconcileJob = async (job: ReconcileJob) => {
  const source = createGitLabSource()
  const branches = await db
    .select({
      branch: indexBranchStates.branch,
      configHash: indexBranchStates.configHash,
      lastReadySha: indexBranchStates.lastReadySha,
    })
    .from(indexBranchStates)
    .where(eq(indexBranchStates.integrationId, job.integrationId))
    .limit(resolveBranchLimit())

  let checked = 0
  let enqueued = 0
  const branchChecks: Array<{
    branch: string
    configHash: string
    lastReadySha: string | null
    headSha: string
    enqueued: boolean
  }> = []

  for (const branchState of branches) {
    const headSha = await source.resolveHeadSha({
      integrationId: job.integrationId,
      branch: branchState.branch,
    })

    checked += 1
    const isStale = branchState.lastReadySha !== headSha

    if (isStale) {
      await enqueuePlanJob({
        integrationId: job.integrationId,
        branch: branchState.branch,
        configHash: branchState.configHash,
        hintedHeadSha: headSha,
      })
      enqueued += 1
    }

    branchChecks.push({
      branch: branchState.branch,
      configHash: branchState.configHash,
      lastReadySha: branchState.lastReadySha,
      headSha,
      enqueued: isStale,
    })
  }

  return {
    checked,
    enqueued,
    branchChecks,
  }
}

