fn index_to_kitedb(
  index_options: IndexOptions,
  store_path: &Path,
  clear: bool,
) -> anyhow::Result<()> {
  let mut sink = KiteDbIndexSink::new(store_path.to_path_buf(), clear);
  let engine = IndexEngine::new(index_options);
  let cancel = CancelToken::new();
  if let Err(err) = engine.run(&mut sink, &cancel) {
    let _ = sink.abort();
    return Err(err.into());
  }
  sink.finish().map_err(|e| anyhow::anyhow!(e.to_string()))?;
  Ok(())
}

fn search_kitedb(
  provider: &dyn EmbeddingsProvider,
  store_path: &Path,
  query: &str,
  top_k: usize,
) -> anyhow::Result<Vec<KiteSearchHit>> {
  let query = query.trim();
  if query.is_empty() {
    anyhow::bail!("query cannot be empty");
  }
  let embeddings = provider.embed_texts(&[query])?;
  let embedding = embeddings
    .into_iter()
    .next()
    .ok_or_else(|| anyhow::anyhow!("vector provider returned no embeddings"))?;
  let store = KiteCodeStore::open_readonly(store_path.to_path_buf())?;
  Ok(store.search_by_embedding(&embedding, top_k)?)
}

fn truncate_chars(value: String, max_chars: usize) -> String {
  if max_chars == 0 {
    return String::new();
  }
  value.chars().take(max_chars).collect::<String>()
}

fn graph_neighbors_kitedb(
  store_path: &Path,
  node_id: &str,
  edge_type: &str,
  direction: &str,
  limit: usize,
) -> anyhow::Result<Vec<KiteGraphNeighbor>> {
  let store = KiteCodeStore::open_readonly(store_path.to_path_buf())?;
  Ok(store.graph_neighbors(node_id, edge_type, direction, limit)?)
}

fn locate_kitedb(
  store_path: &Path,
  file_path: &str,
  line_1_based: u32,
  column_1_based: u32,
  options: KiteLocateOptions,
) -> anyhow::Result<Vec<KiteLocateHit>> {
  let store = KiteCodeStore::open_readonly(store_path.to_path_buf())?;
  let position = Position {
    row: line_1_based.saturating_sub(1),
    column: column_1_based.saturating_sub(1),
  };
  Ok(store.locate_by_position(file_path, position, options)?)
}

fn impact_callers_kitedb(
  store_path: &Path,
  node_id: &str,
  max_depth: usize,
  limit: usize,
) -> anyhow::Result<Vec<ImpactHit>> {
  let store = KiteCodeStore::open_readonly(store_path.to_path_buf())?;

  let max_depth = max_depth.clamp(1, 10);
  let limit = limit.clamp(1, 500);

  let mut visited = HashSet::<String>::new();
  visited.insert(node_id.to_string());

  let mut q = VecDeque::<(String, usize)>::new();
  q.push_back((node_id.to_string(), 0));

  let mut out = Vec::<ImpactHit>::new();
  while let Some((current, depth)) = q.pop_front() {
    if depth >= max_depth {
      continue;
    }
    let neighbors = store.graph_neighbors(&current, "CALLS", "in", 200)?;
    for neighbor in neighbors {
      if !visited.insert(neighbor.id.clone()) {
        continue;
      }
      let next_depth = depth + 1;
      out.push(ImpactHit {
        depth: next_depth,
        node: neighbor.clone(),
      });
      if out.len() >= limit {
        return Ok(out);
      }
      q.push_back((neighbor.id, next_depth));
    }
  }
  Ok(out)
}

fn open_file_with_range(
  project_root: &Path,
  file_path: &Path,
  start_line: usize,
  end_line: usize,
  max_chars: usize,
) -> anyhow::Result<String> {
  let abs = safe_resolve_within_root(project_root, file_path)?;
  let content = fs::read_to_string(&abs)?;
  let lines: Vec<&str> = content.split('\n').collect();
  let slice = lines
    .get(start_line.saturating_sub(1)..end_line.min(lines.len()))
    .unwrap_or(&[]);
  let mut text = slice.join("\n");
  if text.chars().count() > max_chars {
    text = truncate_chars(text, max_chars);
  }
  Ok(format!(
    "file: {}\nlines: {}-{}\n\n{}",
    abs.strip_prefix(project_root).unwrap_or(&abs).display(),
    start_line,
    end_line,
    text
  ))
}

fn store_exists_and_valid(store_path: &Path) -> bool {
  if !store_path.exists() {
    return false;
  }
  KiteCodeStore::open_readonly(store_path.to_path_buf()).is_ok()
}

