fn resolve_root_path(root: Option<String>) -> PyResult<PathBuf> {
  match root {
    Some(root) => {
      if root.trim().is_empty() {
        Err(PyValueError::new_err("root cannot be empty"))
      } else {
        Ok(PathBuf::from(root))
      }
    }
    None => std::env::current_dir()
      .map_err(|err| PyValueError::new_err(format!("failed to resolve current directory: {err}"))),
  }
}

