impl PyPipelineStats {
  fn from_json(duration_ms: u64, stats: &serde_json::Value) -> Self {
    let parse = stats.get("parse");
    let parsed = parse
      .and_then(|value| value.get("filesParsed"))
      .and_then(serde_json::Value::as_u64)
      .unwrap_or(0);
    let skipped = parse
      .and_then(|value| value.get("filesSkipped"))
      .and_then(serde_json::Value::as_u64)
      .unwrap_or(0);

    Self {
      duration: duration_ms as f64 / 1000.0,
      duration_ms,
      file_count: parsed + skipped,
    }
  }
}

