fn validate_cli_vector_args(args: &PythonCliArgs) -> PyResult<()> {
  if args.vector_dimension == 0 {
    return Err(PyValueError::new_err(
      "vector_dimension must be greater than 0",
    ));
  }
  if args.vector_timeout_s == 0 {
    return Err(PyValueError::new_err(
      "vector_timeout_s must be greater than 0",
    ));
  }
  if args.vector_batch_size == 0 {
    return Err(PyValueError::new_err(
      "vector_batch_size must be greater than 0",
    ));
  }
  if args.vector_concurrency == 0 {
    return Err(PyValueError::new_err(
      "vector_concurrency must be greater than 0",
    ));
  }
  if args.vector_base_url.trim().is_empty() {
    return Err(PyValueError::new_err("vector_base_url cannot be empty"));
  }
  if args.vector_model.trim().is_empty() {
    return Err(PyValueError::new_err("vector_model cannot be empty"));
  }
  Ok(())
}

fn build_cli_indexer(
  args: &PythonCliArgs,
  use_vectors: bool,
) -> PyResult<(Indexer, KiteDB, PathBuf)> {
  let mut project_root = resolve_root_path(Some(args.project_root.clone()))?;
  if project_root.is_relative() {
    project_root = std::env::current_dir()
      .map_err(|err| PyValueError::new_err(format!("failed to resolve current directory: {err}")))?
      .join(project_root);
  }
  let mut indexer = Indexer {
    root: project_root.clone(),
    paths: normalize_paths(args.paths.clone()),
    include: args.include.clone(),
    exclude: args.exclude.clone(),
    respect_gitignore: !args.no_gitignore,
    vector_config: None,
    vector_batch_size: None,
    vector_concurrency: None,
  };

  if use_vectors {
    validate_cli_vector_args(args)?;
    indexer.vector_config = Some(VectorConfig {
      base_url: args.vector_base_url.clone(),
      model: args.vector_model.clone(),
      api_key: with_default_openai_key(args.vector_api_key.clone()),
      dimension: Some(args.vector_dimension as usize),
      timeout_ms: Some((args.vector_timeout_s as u64) * 1000),
    });
    indexer.vector_batch_size = Some(args.vector_batch_size as usize);
    indexer.vector_concurrency = Some(args.vector_concurrency as usize);
  }

  let store = KiteDB::new(
    args.store.clone(),
    Some(project_root.to_string_lossy().to_string()),
  )?;
  Ok((indexer, store, project_root))
}

fn print_json_payload(value: &serde_json::Value) -> PyResult<()> {
  let rendered = serde_json::to_string_pretty(value)
    .map_err(|err| PyValueError::new_err(format!("failed to serialize output: {err}")))?;
  println!("{rendered}");
  Ok(())
}

fn run_python_cli(args: PythonCliArgs) -> PyResult<i32> {
  match args.command {
    PythonCliCommand::Index {
      vector,
      clear,
      no_graph,
      scip,
      index_pack,
      json,
    } => {
      let (indexer, store, project_root) = build_cli_indexer(&args, vector)?;
      let run = indexer.persist(
        Some(&store),
        clear,
        !no_graph,
        Some(vector),
        scip,
        index_pack,
      )?;

      if json {
        let payload = serde_json::json!({
          "project_root": project_root.to_string_lossy(),
          "store_path": run.store_path,
          "duration_s": run.duration,
          "duration_ms": run.duration_ms,
          "file_count": run.file_count,
          "vector_count": run.vector_count,
          "graph_nodes": run.graph_nodes,
          "graph_edges": run.graph_edges,
        });
        print_json_payload(&payload)?;
      } else {
        println!("Indexed {} files in {:.2}s", run.file_count, run.duration);
        println!(
          "Store: {}",
          run
            .store_path
            .unwrap_or_else(|| store.path.to_string_lossy().to_string())
        );
        println!(
          "Vectors: {}  Graph nodes: {}  Graph edges: {}",
          run.vector_count, run.graph_nodes, run.graph_edges
        );
      }
      Ok(0)
    }

    PythonCliCommand::Search {
      ref query,
      top_k,
      json,
    } => {
      let (indexer, store, project_root) = build_cli_indexer(&args, true)?;
      let hits = indexer.search(query.clone(), Some(&store), top_k)?;

      if json {
        let hit_values = hits
          .iter()
          .map(|hit| {
            serde_json::json!({
              "score": hit.score,
              "chunk_id": hit.chunk_id,
              "file_path": hit.file_path,
              "range_json": hit.range_json,
            })
          })
          .collect::<Vec<_>>();
        let payload = serde_json::json!({
          "project_root": project_root.to_string_lossy(),
          "store_path": store.path.to_string_lossy(),
          "query": query,
          "top_k": top_k,
          "hits": hit_values,
        });
        print_json_payload(&payload)?;
      } else if hits.is_empty() {
        println!("No results.");
      } else {
        for (idx, hit) in hits.iter().enumerate() {
          println!(
            "{}. {:.4}  {}  {}",
            idx + 1,
            hit.score,
            hit.chunk_id,
            hit.file_path.as_deref().unwrap_or("<unknown>")
          );
        }
      }
      Ok(0)
    }
  }
}

#[pyfunction(signature = (argv=None))]

fn cli_main(argv: Option<Vec<String>>) -> PyResult<i32> {
  let mut args = vec!["argus-search".to_string()];
  if let Some(values) = argv {
    args.extend(values);
  } else {
    let sys_argv = Python::with_gil(|py| -> PyResult<Vec<String>> {
      let sys = py.import_bound("sys")?;
      let argv = sys.getattr("argv")?.extract::<Vec<String>>()?;
      Ok(argv.into_iter().skip(1).collect())
    })?;
    args.extend(sys_argv);
  }

  let parsed = match PythonCliArgs::try_parse_from(args) {
    Ok(parsed) => parsed,
    Err(err) => {
      let exit_code = match err.kind() {
        ErrorKind::DisplayHelp | ErrorKind::DisplayVersion => 0,
        _ => 2,
      };
      err.print().map_err(|print_err| {
        PyValueError::new_err(format!("failed to print CLI output: {print_err}"))
      })?;
      return Ok(exit_code);
    }
  };

  match run_python_cli(parsed) {
    Ok(code) => Ok(code),
    Err(err) => {
      eprintln!("error: {err}");
      Ok(1)
    }
  }
}

fn register_events_submodule(py: Python<'_>, module: &Bound<'_, PyModule>) -> PyResult<()> {
  let events = PyModule::new_bound(py, "events")?;
  events.add_class::<PyVectorRecord>()?;
  events.add_class::<PyVectorBatchEvent>()?;
  events.add_class::<PyPipelineStats>()?;
  events.add_class::<PyPipelineCompleteEvent>()?;

  module.add_submodule(&events)?;
  module.setattr("events", &events)?;

  let sys = py.import_bound("sys")?;
  let modules = sys.getattr("modules")?.downcast_into::<PyDict>()?;
  modules.set_item("argus_search.events", &events)?;
  Ok(())
}

#[pyfunction(signature = (file_path, content=None, language=None, content_path=None))]
fn chunk_file(
  file_path: &str,
  content: Option<&str>,
  language: Option<&str>,
  content_path: Option<&str>,
) -> PyResult<PyObject> {
  let content = resolve_chunk_content(file_path, content, content_path)?;
  let chunks = TreeSitterChunker::chunk_file_with_language(file_path, &content, language);
  let value = serde_json::to_value(chunks).map_err(|err| PyValueError::new_err(err.to_string()))?;
