fn get_optional_dict<'py>(
  dict: &'py Bound<'py, PyDict>,
  key: &str,
) -> PyResult<Option<Bound<'py, PyDict>>> {
  match PyDictMethods::get_item(dict, key)? {
    Some(value) => value
      .downcast_into::<PyDict>()
      .map(Some)
      .map_err(Into::into),
    None => Ok(None),
  }
}

fn get_optional_string(dict: &Bound<'_, PyDict>, key: &str) -> PyResult<Option<String>> {
  match dict.get_item(key)? {
    Some(value) => value.extract::<String>().map(Some),
    None => Ok(None),
  }
}

fn get_required_string(dict: &Bound<'_, PyDict>, key: &str) -> PyResult<String> {
  get_optional_string(dict, key)?
    .ok_or_else(|| PyValueError::new_err(format!("missing required field: {key}")))
}

fn resolve_project_path(project_root: &Path, candidate: PathBuf) -> PathBuf {
  if candidate.is_relative() {
    project_root.join(candidate)
  } else {
    candidate
  }
}

fn resolve_store_path(project_root: &Path, candidate: PathBuf) -> PyResult<PathBuf> {
  if candidate
    .components()
    .any(|component| matches!(component, Component::ParentDir))
  {
    return Err(PyValueError::new_err("store path escapes project root"));
  }
  let root = project_root
    .canonicalize()
    .unwrap_or_else(|_| project_root.to_path_buf());
  let resolved = resolve_project_path(project_root, candidate);
  let normalized = resolved.canonicalize().unwrap_or(resolved.clone());
  if normalized.strip_prefix(&root).is_err() {
    return Err(PyValueError::new_err("store path escapes project root"));
  }
  Ok(resolved)
}

fn get_string_list(dict: &Bound<'_, PyDict>, key: &str) -> PyResult<Vec<String>> {
  match dict.get_item(key)? {
    Some(value) => value.extract::<Vec<String>>(),
    None => Ok(Vec::new()),
  }
}

fn stream_event_to_py(
  py: Python<'_>,
  value: &serde_json::Value,
  typed_events: bool,
) -> PyResult<PyObject> {

  if !typed_events {
    return json_to_py(py, value);
  }

  let Some(event_type) = value.get("type").and_then(serde_json::Value::as_str) else {
    return json_to_py(py, value);
  };

  match event_type {
    "vector:batch" => {
      let batch = value
        .get("batch")
        .cloned()
        .unwrap_or_else(|| serde_json::Value::Array(Vec::new()));
      let records: Vec<CoreVectorRecord> =
        serde_json::from_value(batch).map_err(|err| PyValueError::new_err(err.to_string()))?;

      let mut out = Vec::with_capacity(records.len());
      for record in records {
        out.push(Py::new(py, PyVectorRecord::from_core(record)?)?);
      }

      let event = Py::new(py, PyVectorBatchEvent { records: out })?;
      Ok(event.to_object(py))
    }
    "pipeline:complete" => {
      let duration_ms = value
        .get("durationMs")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or(0);
      let stats_json = value
        .get("stats")
        .cloned()
        .unwrap_or(serde_json::Value::Null);
      let stats = Py::new(py, PyPipelineStats::from_json(duration_ms, &stats_json))?;

      let errors = value
        .get("errors")
        .and_then(serde_json::Value::as_array)
        .map(|items| {
          items
            .iter()
            .filter_map(serde_json::Value::as_str)
            .map(ToString::to_string)
            .collect()
        })
        .unwrap_or_else(Vec::new);

      let event = Py::new(py, PyPipelineCompleteEvent { stats, errors })?;
      Ok(event.to_object(py))
    }
    _ => json_to_py(py, value),
  }
}

fn json_to_py(py: Python<'_>, value: &serde_json::Value) -> PyResult<PyObject> {
  match value {
    serde_json::Value::Null => Ok(py.None()),
    serde_json::Value::Bool(val) => Ok(val.to_object(py)),
    serde_json::Value::Number(val) => {
      if let Some(int_val) = val.as_i64() {
        Ok(int_val.to_object(py))
      } else if let Some(int_val) = val.as_u64() {
        Ok(int_val.to_object(py))
      } else {
        Ok(val.as_f64().unwrap_or(0.0).to_object(py))
      }
    }
    serde_json::Value::String(val) => Ok(val.to_object(py)),
    serde_json::Value::Array(items) => {
      let list = PyList::empty_bound(py);
      for item in items {
        list.append(json_to_py(py, item)?)?;
      }
      Ok(list.to_object(py))
    }
    serde_json::Value::Object(map) => {
      let dict = PyDict::new_bound(py);
      for (key, val) in map {
        dict.set_item(key, json_to_py(py, val)?)?;
      }
      Ok(dict.to_object(py))
    }
  }
}

