import { createFsArtifactStore } from '@/lib/indexing/stores/artifact-store.fs'
import { createS3ArtifactStore } from '@/lib/indexing/stores/artifact-store.s3'

export type ArtifactCleanupDetails = {
  bytes: number
  objects: number
}

export interface ArtifactCleanupStore {
  describePrefix(args: {
    artifactsPrefix: string
  }): Promise<ArtifactCleanupDetails>

  deletePrefix(args: {
    artifactsPrefix: string
  }): Promise<ArtifactCleanupDetails>
}

const resolveBackend = () => process.env.INDEXER_ARTIFACTS_BACKEND?.trim().toLowerCase() || 'fs'

export const createArtifactCleanupStore = (): ArtifactCleanupStore => {
  const backend = resolveBackend()
  if (backend === 's3') {
    return createS3ArtifactStore()
  }

  return createFsArtifactStore()
}

import { describe, expect, test } from "bun:test"

import { resolveKeepRules, resolveSamplingRates } from "@argus/shared-observability"

describe("shared observability sampling", () => {
  test("resolveSamplingRates reads env with production debug fallback", () => {
    expect(
      resolveSamplingRates({
        environment: "production",
        env: {
          APP_LOG_SAMPLE_INFO: "85",
          APP_LOG_SAMPLE_WARN: "70",
          APP_LOG_SAMPLE_DEBUG: "not-a-number",
          APP_LOG_SAMPLE_ERROR: "150",
        },
      }),
    ).toEqual({
      info: 85,
      warn: 70,
      debug: 0,
      error: 100,
    })
  })

  test("resolveSamplingRates allows overrides", () => {
    expect(
      resolveSamplingRates({
        environment: "development",
        env: {
          APP_LOG_SAMPLE_INFO: "1",
          APP_LOG_SAMPLE_WARN: "2",
          APP_LOG_SAMPLE_DEBUG: "3",
          APP_LOG_SAMPLE_ERROR: "4",
        },
        overrides: {
          info: 9,
          debug: 5,
        },
      }),
    ).toEqual({
      info: 9,
      warn: 2,
      debug: 5,
      error: 4,
    })
  })

  test("resolveKeepRules returns default keep rules plus optional path", () => {
    expect(
      resolveKeepRules({
        env: {
          APP_LOG_KEEP_MIN_STATUS: "401",
          APP_LOG_KEEP_MIN_DURATION_MS: "1200",
          APP_LOG_KEEP_PATH_PREFIX: "/api/internal",
        },
      }),
    ).toEqual([{ status: 401 }, { duration: 1200 }, { path: "/api/internal/**" }])
  })

  test("resolveKeepRules falls back when values are missing or invalid", () => {
    expect(
      resolveKeepRules({
        env: {
          APP_LOG_KEEP_MIN_STATUS: "invalid",
          APP_LOG_KEEP_MIN_DURATION_MS: "",
          APP_LOG_KEEP_PATH_PREFIX: "   ",
        },
      }),
    ).toEqual([{ status: 400 }, { duration: 1000 }])
  })
})

import { NextResponse } from "next/server"
import { z } from "zod"

import { secureCompare } from "@/lib/gitlab/crypto"
import { gitlabEnv } from "@/lib/gitlab/env"
import { runGitLabJobRunner } from "@/lib/gitlab/jobs"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const runPayloadSchema = z.object({
  batchSize: z.number().int().positive().max(200).optional(),
})

const isAuthorizedRunnerRequest = (request: Request) => {
  const headerValue = request.headers.get("x-internal-runner-key")
  if (!headerValue) {
    return false
  }
  return secureCompare(headerValue, gitlabEnv.internalRunnerKey)
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/internal/gitlab-jobs/run",
    event: "api.gitlab.jobs.run",
    handler: async ({ logger }) => {
      if (!isAuthorizedRunnerRequest(request)) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const payload = await request.json().catch(() => ({}))
      const parsed = runPayloadSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid runner payload." }, { status: 400 }),
        }
      }

      const summary = await runGitLabJobRunner(parsed.data.batchSize)
      logger.set({
        summary,
      })
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: summary }),
      }
    },
  })
}

