import http from 'node:http'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import fs from 'node:fs'

import test from 'ava'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')
const fixtureRoot = path.join(__dirname, '..', 'fixtures', 'sample-repo')

function hasNativeBinding(): boolean {
  if (process.env.NAPI_RS_NATIVE_LIBRARY_PATH) {
    return true
  }
  try {
    return fs.readdirSync(packageRoot).some((entry) => entry.endsWith('.node'))
  } catch {
    return false
  }
}

const testWithBinding = hasNativeBinding() ? test : test.skip

function startEmbeddingServer(dimension: number) {
  const server = http.createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/embeddings') {
      res.statusCode = 404
      res.end('not found')
      return
    }

    const body = await new Promise<string>((resolve, reject) => {
      let raw = ''
      req.on('data', (chunk) => (raw += String(chunk)))
      req.on('end', () => resolve(raw))
      req.on('error', reject)
    })

    let inputCount = 1
    try {
      const parsed = JSON.parse(body) as { input?: unknown }
      inputCount = Array.isArray(parsed?.input) ? parsed.input.length : 1
    } catch {
      inputCount = 1
    }

    const embedding = Array.from({ length: dimension }, (_, idx) => (idx + 1) / 10)
    const data = Array.from({ length: inputCount }, () => ({ embedding }))

    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ data }))
  })

  return new Promise<{ url: string; close: () => Promise<void> }>((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const address = server.address()
      const port = typeof address === 'object' && address ? address.port : 0
      resolve({
        url: `http://127.0.0.1:${port}`,
        close: () => new Promise<void>((done) => server.close(() => done())),
      })
    })
  })
}

async function loadMcp() {
  const mod = (await import('../mcp.js')) as unknown as {
    createMcpServer?: unknown
    default?: { createMcpServer?: unknown }
  }
  const createMcpServer = (mod.createMcpServer ?? mod.default?.createMcpServer) as unknown
  if (typeof createMcpServer !== 'function') {
    throw new Error('createMcpServer not found')
  }
  return { createMcpServer: createMcpServer as (options: Record<string, unknown>) => any }
}

function parseSseJson(text: string) {
  const line = text
    .split('\n')
    .map((l) => l.trimEnd())
    .find((l) => l.startsWith('data: '))
  if (!line) throw new Error('no data line found')
  return JSON.parse(line.slice('data: '.length))
}

testWithBinding('MCP server tools/list and tools/call', async (t) => {
  const { url: embedUrl, close: closeEmbed } = await startEmbeddingServer(3)
  const { createMcpServer } = await loadMcp()

  const server = createMcpServer({
    host: '127.0.0.1',
    port: 0,
    projectRoot: fixtureRoot,
    inputs: { paths: [fixtureRoot], include: ['*.ts'], exclude: ['node_modules', 'dist', '.git'] },
    vectorProvider: { kind: 'http', baseUrl: embedUrl, model: 'test-model', dimension: 3 },
    indexOnStart: false,
  })

  const started = await server.start()
  try {
    const listRes = await fetch(started.url, {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream' },
      body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/list', params: {} }),
    })
    t.true(listRes.ok)
    const listText = await listRes.text()

    const listJson = parseSseJson(listText)
    t.true(Array.isArray(listJson?.result?.tools))

    const callRes = await fetch(started.url, {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0',
        id: 2,
        method: 'tools/call',
        params: { name: 'code_search', arguments: { query: 'answer', topK: 2 } },
      }),
    })
    t.true(callRes.ok)
    const callText = await callRes.text()
    const callJson = parseSseJson(callText)
    const payload = callJson?.result?.content?.[0]?.text ?? '[]'
    const matches = JSON.parse(String(payload))
    t.true(Array.isArray(matches))
    t.true(matches.length > 0)

    const openRes = await fetch(started.url, {
      method: 'POST',
      headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream' },
      body: JSON.stringify({
        jsonrpc: '2.0',
        id: 3,
        method: 'tools/call',
        params: { name: 'code_open', arguments: { filePath: 'src/index.ts', startLine: 1, endLine: 5 } },
      }),
    })
    t.true(openRes.ok)
    const openText = await openRes.text()
    const openJson = parseSseJson(openText)
    t.true(String(openJson?.result?.content?.[0]?.text ?? '').includes('src/index.ts'))
  } finally {
    await started.close()
    await closeEmbed()
  }
})

