import { refreshCodeGraphSummary } from "../src/lib/argus-search/graph-index-pack"

const run = async () => {
  const summary = await refreshCodeGraphSummary()
  process.stdout.write(`${JSON.stringify(summary, null, 2)}\n`)
}

run().catch((error) => {
  process.stderr.write(`${error instanceof Error ? error.message : "Failed to refresh code graph."}\n`)
  process.exitCode = 1
})

