"use client"

import { QueryClient, QueryClientProvider } from "@tanstack/react-query"
import { useState, type ReactNode } from "react"

const createQueryClient = () =>
  new QueryClient({
    defaultOptions: {
      queries: {
        staleTime: 10 * 60_000,
        gcTime: 45 * 60_000,
        retry: 1,
        refetchOnMount: false,
        refetchOnWindowFocus: false,
        refetchOnReconnect: false,
      },
    },
  })

export const QueryProvider = ({ children }: { children: ReactNode }) => {
  const [queryClient] = useState(createQueryClient)
  return <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
}

const fs = require('node:fs')
const path = require('node:path')

const ANSI = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  underline: '\x1b[4m',
  yellow: '\x1b[33m',
  green: '\x1b[32m',
  cyan: '\x1b[36m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  brightBlack: '\x1b[90m',
}

const NO_COLOR = {
  reset: '',
  bold: '',
  dim: '',
  underline: '',
  yellow: '',
  green: '',
  cyan: '',
  blue: '',
  magenta: '',
  brightBlack: '',
}

function resolveColorMode(mode, { isTTY = Boolean(process.stdout?.isTTY), env = process.env } = {}) {
  const value = String(mode ?? 'auto')
    .trim()
    .toLowerCase()
  if (value === 'always') return true
  if (value === 'never') return false
  if (value !== 'auto') throw new Error(`invalid color mode: ${mode}`)
  if (env.NO_COLOR != null && String(env.NO_COLOR) !== '') return false
  return isTTY
}

function safeResolveWithinRoot(rootDir, unsafePath) {
  const root = path.resolve(String(rootDir))
  const resolved = path.resolve(root, String(unsafePath))
  const rel = path.relative(root, resolved)
  if (rel === '..' || rel.startsWith(`..${path.sep}`) || path.isAbsolute(rel)) {
    throw new Error('path escapes project root')
  }
  return resolved
}

function normalizeRelativePath(projectRoot, filePath) {
  const normalized = String(filePath ?? '').replace(/\\/g, '/')
  if (path.isAbsolute(normalized)) {
    const abs = safeResolveWithinRoot(projectRoot, normalized)
    return path.relative(projectRoot, abs).replace(/\\/g, '/')
  }
  if (normalized.split('/').includes('..')) throw new Error('path escapes project root')
  return normalized
}

function readRangeJson(rangeJson) {
  if (!rangeJson) return null
  try {
    return JSON.parse(rangeJson)
  } catch {
    return null
  }
}

function openSnippet(projectRoot, relPath, range, context, colors = null) {
  const c = colors || NO_COLOR
  const rel = normalizeRelativePath(projectRoot, relPath)
  const abs = safeResolveWithinRoot(projectRoot, path.join(projectRoot, rel))
  const content = fs.readFileSync(abs, 'utf8')
  const lines = content.split('\n')
  const start = Number(range?.start?.row ?? 0)
  const end = Number(range?.end?.row ?? start)
  const ctx = Math.max(0, Number(context) || 0)
  const from = Math.max(0, start - ctx)
  const to = Math.min(lines.length, end + ctx + 1)
  if (from >= to) return ''
  const out = []
  for (let idx = from; idx < to; idx += 1) {
    const lineNo = String(idx + 1).padStart(5, ' ')
    const isHighlight = idx >= start && idx <= end
    const lineNumStyled = isHighlight
      ? `${c.yellow}${c.bold}${lineNo}${c.reset}`
      : `${c.brightBlack}${lineNo}${c.reset}`
    const separator = isHighlight ? `${c.yellow}│${c.reset}` : `${c.brightBlack}│${c.reset}`
    out.push(`${lineNumStyled} ${separator} ${lines[idx]}`)
  }
  return out.join('\n')
}

function formatSearchHits(hits, options = {}) {
  if (!Array.isArray(hits)) throw new Error('formatSearchHits: hits must be an array')

  const { projectRoot, context = 2, color = 'auto', includeContentFallback = false } = options

  const c = resolveColorMode(color) ? ANSI : NO_COLOR
  const out = []

  // Header

if (hits.length > 0) {
  out.push(`\n${c.bold}${c.underline}SEARCH RESULTS${c.reset} ${c.dim}(${hits.length} matches)${c.reset}\n`)
} else {
  out.push(`\n${c.yellow}No matches found${c.reset}\n`)
  return out.join('\n')
}

for (const [idx, hit] of hits.entries()) {
  const filePath = hit?.filePath ?? '<unknown>'
  const score = Number(hit?.score)
  const scoreText = Number.isFinite(score) ? score.toFixed(4) : '0.0000'
  const chunkId = String(hit?.chunkId ?? '')

  let suffix = ''
  const range = readRangeJson(hit?.rangeJson ?? null)
  if (range) {
    const startLine = (Number(range?.start?.row ?? 0) || 0) + 1
    const endLine = (Number(range?.end?.row ?? 0) || 0) + 1
    suffix = `:${startLine}-${endLine}`
  }

  // Result header with score badge
  const num = `${c.yellow}${c.bold}${String(idx + 1).padStart(2, '0')}${c.reset}`
  const scoreBadge = `${c.green}${scoreText}${c.reset}`
  const chunkIdStyled = `${c.cyan}${chunkId}${c.reset}`
  const filePathStyled = `${c.blue}${c.underline}${filePath}${suffix}${c.reset}`

  out.push(`${num}  ${scoreBadge}  ${chunkIdStyled}`)
  out.push(`    ${c.dim}└─${c.reset} ${filePathStyled}`)

  let snippet = ''
  if (projectRoot && hit?.filePath && range) {
    try {
      const snippetColors = resolveColorMode(color) ? c : null
      snippet = openSnippet(projectRoot, hit.filePath, range, context, snippetColors)
    } catch {
      snippet = ''
    }
  }
  if (snippet) {
    out.push(`${c.dim}${'─'.repeat(60)}${c.reset}`)
    out.push(snippet)
    out.push('')
  } else if (includeContentFallback && hit?.content) {
    out.push(`${c.dim}${'─'.repeat(60)}${c.reset}`)
    out.push(String(hit.content))
    out.push('')
  }
}

return out.join('\n')

}

module.exports = {
  formatSearchHits,
  resolveColorMode,
}

