import http from 'node:http'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import fs from 'node:fs'

import test from 'ava'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..')
const fixtureRoot = path.join(__dirname, '..', 'fixtures', 'sample-repo')

function hasNativeBinding(): boolean {
  if (process.env.NAPI_RS_NATIVE_LIBRARY_PATH) {
    return true
  }
  try {
    return fs.readdirSync(packageRoot).some((entry) => entry.endsWith('.node'))
  } catch {
    return false
  }
}

const testWithBinding = hasNativeBinding() ? test : test.skip

function startEmbeddingServer(dimension: number) {
  const server = http.createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/embeddings') {
      res.statusCode = 404
      res.end('not found')
      return
    }

    const body = await new Promise<string>((resolve, reject) => {
      let raw = ''
      req.on('data', (chunk) => (raw += String(chunk)))
      req.on('end', () => resolve(raw))
      req.on('error', reject)
    })

    let inputCount = 1
    try {
      const parsed = JSON.parse(body) as { input?: unknown }
      inputCount = Array.isArray(parsed?.input) ? parsed.input.length : 1
    } catch {
      inputCount = 1
    }

    const embedding = Array.from({ length: dimension }, (_, idx) => (idx + 1) / 10)
    const data = Array.from({ length: inputCount }, () => ({ embedding }))

    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ data }))
  })

  return new Promise<{ url: string; close: () => Promise<void> }>((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const address = server.address()
      const port = typeof address === 'object' && address ? address.port : 0
      resolve({
        url: `http://127.0.0.1:${port}`,
        close: () => new Promise<void>((done) => server.close(() => done())),
      })
    })
  })
}

async function loadIndexStream() {
  const mod = (await import('../stream.js')) as unknown as {
    indexStream?: unknown
    default?: { indexStream?: unknown }
  }
  const indexStream = (mod.indexStream ?? mod.default?.indexStream) as unknown
  if (typeof indexStream !== 'function') {
    throw new Error('indexStream not found')
  }
  return indexStream as (options: Record<string, unknown>, stream?: Record<string, unknown>) => AsyncIterable<unknown> & {
    cancel(): void
  }
}

testWithBinding('vector stream emits chunks', async (t) => {
  const { url, close } = await startEmbeddingServer(3)
  try {
    const indexStream = await loadIndexStream()
    const stream = indexStream(
      {
        projectRoot: fixtureRoot,
        inputs: { paths: [fixtureRoot], include: ['*.ts'] },
        phases: { parse: true, graph: false, vector: true, scip: false, indexPack: false },
        vector: { provider: { kind: 'http', baseUrl: url, model: 'test-model', dimension: 3 } },
      },
      {
        highWaterMark: 16,
        emit: { vectorBatches: true, phaseEvents: true, parseBatches: false },
      },
    )

    for await (const item of stream) {
      const asAny = item as any
      if (asAny?.type === 'vector:batch') {
        const batch = asAny.batch as any[]
        t.true(Array.isArray(batch) && batch.length > 0)
        const record = batch[0]
        t.truthy(record?.chunk)
        t.truthy(record?.chunk?.content)
        t.is(record?.chunk?.id, record?.chunkId)
        stream.cancel()
        break
      }
    }
  } finally {
    await close()
  }
})

testWithBinding('stream ends naturally', async (t) => {
  const { url, close } = await startEmbeddingServer(3)
  try {
    const indexStream = await loadIndexStream()
    const stream = indexStream({
      projectRoot: fixtureRoot,
      inputs: { paths: [fixtureRoot], include: ['*.ts'] },
      phases: { parse: true, graph: false, vector: true, scip: false, indexPack: false },
      vector: { provider: { kind: 'http', baseUrl: url, model: 'test-model', dimension: 3 } },
      hooks: { vectorBatch: 1 },
    })

    let sawComplete = false
    for await (const item of stream) {
      const asAny = item as any
      if (asAny?.type === 'pipeline:complete') {
        sawComplete = true
      }
    }

    t.true(sawComplete)
  } finally {
    await close()
  }
})

testWithBinding('backpressure sanity', async (t) => {
  const { url, close } = await startEmbeddingServer(3)
  try {
    const indexStream = await loadIndexStream()
    const stream = indexStream(
      {
        projectRoot: fixtureRoot,
        inputs: { paths: [fixtureRoot], include: ['*.ts'] },
        phases: { parse: true, graph: false, vector: true, scip: false, indexPack: false },
        vector: { provider: { kind: 'http', baseUrl: url, model: 'test-model', dimension: 3 } },
        hooks: { parseBatch: 1, vectorBatch: 1 },
      },
      { highWaterMark: 1, emit: { parseBatches: true, vectorBatches: true, phaseEvents: true } },
    )

    let items = 0
    for await (const _item of stream) {
      items += 1
      await new Promise((r) => setTimeout(r, 10))
    }

    t.true(items > 0)
  } finally {
    await close()
  }
})

