  ]

const REGISTRY_TOOLS: RegistryTool[] = [
  {
    name: "Diagram + Documentation",
    status: "ready",
    category: "docs",
    description: "Creates architecture diagrams and updates markdown/spec documentation.",
  },
  {
    name: "Test Generation",
