  { label: "Workflow Drafts", value: "4", detail: "Saved in Builder" },
  { label: "Auto-Connected Paths", value: "11", detail: "Generated from tool order" },
  { label: "Ready Tool Blocks", value: "4", detail: "Available for orchestration" },
]

const pickFirst = (value: string | string[] | undefined) =>
  Array.isArray(value) ? value[0] : value

const resolveTab = (value: string | undefined): SldcFlowTab => {
  if (value === "tool-registry" || value === "runs") {
    return value
  }

  return "builder"
}

const categoryLabel = (category: RegistryTool["category"]) => {
  if (category === "docs") {
    return "Docs"
  }
  if (category === "testing") {
    return "Testing"
  }
  if (category === "review") {
    return "Review"
  }
  return "Security"
}

