  const activeTab = resolveTab(pickFirst(params.tab))

  return (
    <div className="space-y-4 pt-6">
      <section className="space-y-1">
        <h1 className="text-2xl font-semibold">SLDC Flow</h1>
        <p className="text-sm text-muted-foreground">
          Workflow workspace for chaining diagram/docs, test generation, code review, and security remediation.
