      </section>

      <section className="grid gap-3 md:grid-cols-3">
        {TABS.map((tab) => {
          const isActive = tab.id === activeTab

          return (
            <Link key={tab.id} href={tab.href} className="block">
              <Card className={isActive ? "border-primary/70 bg-primary/5" : "transition-colors hover:border-primary/50"}>
                <CardHeader className="space-y-2">
                  <div className="flex items-center justify-between gap-2">
                    <CardTitle className="text-base">{tab.title}</CardTitle>
                    {isActive ? <Badge>Current</Badge> : null}
                  </div>
                  <CardDescription>{tab.description}</CardDescription>
                </CardHeader>
              </Card>
            </Link>
          )
        })}
      </section>

      {activeTab === "builder" ? <WorkflowBuilderPanelClient /> : null}
      {activeTab === "tool-registry" ? renderToolRegistryTab() : null}
      {activeTab === "runs" ? renderRunsTab() : null}
    </div>
  )
}

