}) => Promise<ApiLogResult>;

const MAX_BUFFER_SIZE = 5_000;
const DEFAULT_BATCH_SIZE = 100;
const DEFAULT_FLUSH_INTERVAL_MS = 2_000;

const state = {
  initialized: false,
  batchSize: DEFAULT_BATCH_SIZE,
  flushIntervalMs: DEFAULT_FLUSH_INTERVAL_MS,
