  },
});

const pushDrainEvent = (ctx: DrainContext) => {
  drainBuffer.push(ctx.event);
};

export const initAppLogger = (options: InitAppLoggerOptions = {}) => {
  if (state.initialized) {
    return;
  }

  const service = options.service ?? process.env.SERVICE_NAME?.trim() ?? "argus-app";
  const environment = options.environment ?? process.env.NODE_ENV ?? "development";

  state.batchSize = parsePositiveInt(process.env.APP_LOG_DB_BATCH_SIZE, DEFAULT_BATCH_SIZE);
  state.flushIntervalMs = parsePositiveInt(
    process.env.APP_LOG_DB_FLUSH_INTERVAL_MS,
    DEFAULT_FLUSH_INTERVAL_MS,
  );
  state.dbDrainEnabled = parseBooleanWithFallback(process.env.APP_LOG_DB_ENABLED, true);
  drainBuffer.configure({
    batchSize: state.batchSize,
    flushIntervalMs: state.flushIntervalMs,
    enabled: state.dbDrainEnabled,
  });

  initLogger({
    env: {
      service,
      environment,
      version: options.version ?? process.env.npm_package_version,
    },
    pretty: options.pretty,
    sampling: {
      rates: resolveSamplingRates({
        environment,
        overrides: options.samplingRates,
      }),
      keep: resolveKeepRules(),
    },
    drain: state.dbDrainEnabled ? pushDrainEvent : undefined,
  });
  state.initialized = true;

  if (options.initEvent) {
    log.info({
      event: options.initEvent,
      logger: {
        dbDrainEnabled: state.dbDrainEnabled,
        batchSize: state.batchSize,
        flushIntervalMs: state.flushIntervalMs,
      },
      ...(options.initContext ?? {}),
    });
  }
};

export const flushAppLogger = async () => {
  await drainBuffer.flush();
};

export { createCorrelationId };

export const createScopedLogger = (options: ScopedLoggerOptions = {}) => {
  if (!state.initialized) {
    initAppLogger({
      pretty: parseBooleanWithFallback(
        process.env.APP_LOG_PRETTY,
        process.env.NODE_ENV !== "production",
      ),
    });
  }

  return createEvlogRequestLogger({
    method: options.method,
    path: options.path,
    requestId: options.requestId,
  });
};

export const startApiRequestLog = (args: {
  request: Request;
  path: string;
  event: string;
  requestId?: string;
  context?: Record<string, unknown>;
}) => {
  const requestId = args.requestId ?? args.request.headers.get("x-request-id") ?? createCorrelationId();
  const logger = createScopedLogger({
    method: args.request.method,
    path: args.path,
    requestId,
  });
  logger.set({
    event: args.event,
    requestId,
    ...(args.context ?? {}),
  });
  return { logger, requestId };
};

export const runWithApiRequestLog = async (args: {
  request: Request;
  path: string;
  event: string;
  context?: Record<string, unknown>;
  handler: ApiLogHandler;
}) => {
  const startedAt = Date.now();
  const { logger, requestId } = startApiRequestLog({
    request: args.request,
    path: args.path,
    event: args.event,
    context: args.context,
  });

  let status = 500;
  try {
    const result = await args.handler({ logger, requestId });
    status = result.status;
    logger.set({
      outcome: result.outcome ?? (status >= 400 ? "error" : "success"),
      ...(result.context ?? {}),
    });
    return result.response;
  } catch (error) {
    logScopedError(logger, error, {
      code: "API_ROUTE_FAILED",
      why: "Route handler threw before response serialization.",
      fix: "Check request payload parsing, auth checks, and dependency calls.",
    });
    logger.set({
      outcome: "error",
    });
    throw error;
  } finally {
    const durationMs = Date.now() - startedAt;
    logger.set({
      apiMetrics: buildApiRequestMetrics({
        durationMs,
        status,
        method: args.request.method,
        path: args.path,
        service: process.env.SERVICE_NAME?.trim() ?? "argus-app",
        event: args.event,
      }),
    });
    logger.emit({
      status,
      durationMs,
    });
  }
};

export const addLogContext = <T extends object>(
  logger: RequestLogger<T>,
  context: FieldContext<T>,
) => {
  logger.set(context);
};

export const emitScopedLog = <T extends object>(
  logger: RequestLogger<T>,
  context?: FieldContext<T>,
) => {
  logger.emit(context);
};

export const logScopedError = <T extends object>(
  logger: RequestLogger<T>,
  error: unknown,
  metadata: ErrorMetadata = {},
) => {
  const normalizedError = normalizeUnknownError(error);
  const context = toScopedErrorContext(metadata);
  logger.error(normalizedError, context as unknown as FieldContext<T>);
};

