export const parsePositiveInt = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }

  return parsed
}

export const parseBoolean = (value: string | undefined): boolean | undefined => {
  if (!value) {
    return undefined
  }

  const normalized = value.trim().toLowerCase()
  if (normalized === "1" || normalized === "true" || normalized === "yes") {
    return true
  }
  if (normalized === "0" || normalized === "false" || normalized === "no") {
    return false
  }

  return undefined
}

export type IndexerWorkerConfig = {
  service: string
  environment: string
  version: string | undefined
  pretty: boolean | undefined
  batchSize: number
  pollIntervalMs: number
  continuous: boolean
}

const resolveDefaultEnv = (): Record<string, string | undefined> => {
  const processEnv = (
    globalThis as { process?: { env?: Record<string, string | undefined> } }
  ).process?.env
  return processEnv ?? {}
}

export const resolveIndexerWorkerConfig = (
  env: Record<string, string | undefined> = resolveDefaultEnv(),
): IndexerWorkerConfig => ({
  service: env.INDEXER_SERVICE_NAME?.trim() || "argus-indexer-worker",
  environment: env.INDEXER_ENVIRONMENT?.trim() || env.NODE_ENV || "development",
  version: env.INDEXER_SERVICE_VERSION?.trim() || env.npm_package_version,
  pretty: parseBoolean(env.INDEXER_LOG_PRETTY),
  batchSize: parsePositiveInt(env.INDEXER_BATCH_SIZE, 25),
  pollIntervalMs: parsePositiveInt(env.INDEXER_POLL_MS, 30_000),
  continuous: env.INDEXER_CONTINUOUS === "1",
})

type LogDrainScheduler = {
  clear: (handle: unknown) => void
  set: (callback: () => void, delayMs: number) => unknown
}

type LogDrainBufferOptions<TEvent> = {
  maxBufferSize: number
  batchSize: number
  flushIntervalMs: number
  enabled: boolean
  writeBatch: (batch: TEvent[]) => Promise<void>
  onWriteError?: (error: unknown) => void
  scheduler?: LogDrainScheduler
}

type LogDrainBufferState = {
  queueSize: number
  dropCount: number
  enabled: boolean
  batchSize: number
  flushIntervalMs: number
}

type LogDrainBufferConfig = Partial<Pick<LogDrainBufferState, "enabled" | "batchSize" | "flushIntervalMs">>

export type LogDrainBuffer<TEvent> = {
  push: (event: TEvent) => void
  flush: () => Promise<void>
  configure: (config: LogDrainBufferConfig) => void
  getState: () => LogDrainBufferState
}

const normalizePositiveInt = (value: number, fallback: number) => {
  if (!Number.isFinite(value) || value <= 0) {
    return fallback
  }

  return Math.floor(value)
}

export const createLogDrainBuffer = <TEvent>(
  options: LogDrainBufferOptions<TEvent>,
): LogDrainBuffer<TEvent> => {
  const scheduler: LogDrainScheduler = options.scheduler ?? {
    clear: (handle) => clearTimeout(handle as ReturnType<typeof setTimeout>),
    set: (callback, delayMs) => setTimeout(callback, delayMs),
  }

  const maxBufferSize = normalizePositiveInt(options.maxBufferSize, 1)
  let batchSize = normalizePositiveInt(options.batchSize, 1)
  let flushIntervalMs = normalizePositiveInt(options.flushIntervalMs, 1)
  let enabled = options.enabled
  let dropCount = 0
  const queue: TEvent[] = []

let flushTimer: unknown | null = null
let flushing: Promise<void> | null = null

const scheduleFlush = () => {
  if (!enabled || flushTimer) {
    return
  }

  flushTimer = scheduler.set(() => {
    flushTimer = null
    void flush()
  }, flushIntervalMs)
}

const flush = async () => {
  if (flushTimer) {
    scheduler.clear(flushTimer)
    flushTimer = null
  }

  if (!enabled) {
    return Promise.resolve()
  }

  if (flushing) {
    return flushing
  }

  flushing = (async () => {
    while (queue.length > 0) {
      const batch = queue.splice(0, batchSize)
      if (batch.length === 0) {
        continue
      }

      try {
        await options.writeBatch(batch)
      } catch (error) {
        options.onWriteError?.(error)
      }
    }
  })().finally(() => {
    flushing = null
    if (queue.length > 0) {
      scheduleFlush()
    }
  })

  return flushing
}

const push = (event: TEvent) => {
  if (!enabled) {
    return
  }

  if (queue.length >= maxBufferSize) {
    queue.shift()
    dropCount += 1
  }

  queue.push(event)

  if (queue.length >= batchSize) {
    void flush()
    return
  }

  scheduleFlush()
}

  const configure = (config: LogDrainBufferConfig) => {
    if (typeof config.enabled === "boolean") {
      enabled = config.enabled
      if (!enabled && flushTimer) {
        scheduler.clear(flushTimer)
        flushTimer = null
      }
    }

    if (typeof config.batchSize === "number") {
      batchSize = normalizePositiveInt(config.batchSize, batchSize)
    }

    if (typeof config.flushIntervalMs === "number") {
      flushIntervalMs = normalizePositiveInt(config.flushIntervalMs, flushIntervalMs)
    }
  }

  const getState = (): LogDrainBufferState => ({
    queueSize: queue.length,
    dropCount,
    enabled,
    batchSize,
    flushIntervalMs,
  })

  return {
    push,
    flush,
    configure,
    getState,
  }
}

