import { DIFF_THEME } from "./merge-request-diff-viewer.utils"

type HeadingBlock = {
  type: "heading"
  level: 1 | 2 | 3 | 4 | 5 | 6
  text: string
}

type ParagraphBlock = {
  type: "paragraph"
  text: string
}

type ListItem = {
  text: string
  checked: boolean | null
}

type ListBlock = {
  type: "list"
  ordered: boolean
  items: ListItem[]
}

type BlockquoteBlock = {
  type: "blockquote"
  text: string
}

type CodeBlock = {
  type: "code"
  language: string
  text: string
}

type RuleBlock = {
  type: "rule"
}

type TableBlock = {
  type: "table"
  headers: string[]
  rows: string[][]
}

type MarkdownBlock =
  | HeadingBlock
  | ParagraphBlock
  | ListBlock
  | BlockquoteBlock
  | CodeBlock
  | TableBlock
  | RuleBlock

const isBlockquote = (line: string) => /^>\s?/.test(line)
const isUnorderedList = (line: string) => /^\s*[-*+]\s+/.test(line)
const isOrderedList = (line: string) => /^\s*\d+\.\s+/.test(line)
const isTableRow = (line: string) => /\|/.test(line.trim())

const stripHtmlTags = (value: string) => value.replace(/<[^>]+>/g, "")

const normalizeHtmlMarkdown = (value: string) => {
  let next = value.replace(/\r\n?/g, "\n")
  next = next.replace(/<!--[\s\S]*?-->/g, "\n")
  next = next.replace(/<br\s*\/?>/gi, "\n")
  next = next.replace(/<details[^>]*>/gi, "\n")
  next = next.replace(/<\/details>/gi, "\n")
  next = next.replace(/<summary>([\s\S]*?)<\/summary>/gi, (_, inner: string) => {
    const headingText = stripHtmlTags(inner).trim()
    return headingText ? `\n### ${headingText}\n` : "\n"
  })
  next = next.replace(/<h([1-6])[^>]*>([\s\S]*?)<\/h\1>/gi, (_, level: string, inner: string) => {
    const headingText = stripHtmlTags(inner).trim()
    if (!headingText) {
      return "\n"
    }
    return `\n${"#".repeat(Number(level))} ${headingText}\n`
  })
  next = next.replace(/<code>([\s\S]*?)<\/code>/gi, (_, inner: string) => `\`${inner.trim()}\``)
  next = next.replace(/<\/?(?:p|div|section|article|span)[^>]*>/gi, "\n")
  next = next.replace(/^\s*<\/?[^>]+>\s*$/gm, "")
  next = next.replace(/\n{3,}/g, "\n\n")
  return next.trim()
}

const splitTableCells = (line: string) =>
  line
    .trim()
    .replace(/^\|/, "")
    .replace(/\|$/, "")
    .split("|")
    .map((cell) => cell.trim())

const isTableSeparator = (line: string) => {
  const cells = splitTableCells(line)
  if (cells.length === 0) {
    return false
  }
  return cells.every((cell) => /^:?-{3,}:?$/.test(cell))
}

const isBlockStart = (line: string) => {
  if (!line.trim()) return false
  return (
    isHeading(line) ||
    isRule(line) ||
    isCodeFence(line) ||
    isBlockquote(line) ||
    isUnorderedList(line) ||
    isOrderedList(line) ||
    isTableRow(line)
  )
}

const parseBlocks = (markdown: string): MarkdownBlock[] => {
  const lines = normalizeHtmlMarkdown(markdown).split("\n")
  const blocks: MarkdownBlock[] = []

  let index = 0
  while (index < lines.length) {
    const line = lines[index] ?? ""
    const trimmedLine = line.trim()

    if (!trimmedLine) {
      index += 1
      continue
    }

    if (isCodeFence(trimmedLine)) {
      const language = trimmedLine.replace(/^```/, "").trim()
      const codeLines: string[] = []
      index += 1
      while (index < lines.length && !isCodeFence((lines[index] ?? "").trim())) {
        codeLines.push(lines[index] ?? "")
        index += 1
      }
      if (index < lines.length) {
        index += 1
      }
      blocks.push({
        type: "code",
        language,
        text: codeLines.join("\n").trimEnd(),
      })
      continue
    }

    const headingMatch = trimmedLine.match(/^(#{1,6})\s+(.*)$/)
    if (headingMatch) {
      blocks.push({
        type: "heading",
        level: headingMatch[1].length as HeadingBlock["level"],
        text: headingMatch[2].trim(),
      })
      index += 1
      continue
    }

if (isRule(trimmedLine)) {
  blocks.push({ type: "rule" })
  index += 1
  continue
}

if (
  isTableRow(line) &&
  index + 1 < lines.length &&
  isTableRow(lines[index + 1] ?? "") &&
  isTableSeparator(lines[index + 1] ?? "")
) {
  const headers = splitTableCells(line)
  const rows: string[][] = []
  index += 2
  while (index < lines.length && isTableRow(lines[index] ?? "")) {
    const row = splitTableCells(lines[index] ?? "")
    if (row.some((cell) => cell.length > 0)) {
      rows.push(row)
    }
    index += 1
  }
  blocks.push({
    type: "table",
    headers,
    rows,
  })
  continue
}

if (isBlockquote(line)) {
  const quoteLines: string[] = []
  while (index < lines.length && isBlockquote(lines[index] ?? "")) {
    quoteLines.push((lines[index] ?? "").replace(/^>\s?/, ""))
    index += 1
  }
  blocks.push({
    type: "blockquote",
    text: quoteLines.join("\n").trim(),
  })
  continue
}

    if (isUnorderedList(line) || isOrderedList(line)) {
      const ordered = isOrderedList(line)
      const items: ListItem[] = []
      while (index < lines.length) {
        const nextLine = lines[index] ?? ""
        if (ordered ? !isOrderedList(nextLine) : !isUnorderedList(nextLine)) {
          break
        }
        const content = nextLine.replace(ordered ? /^\s*\d+\.\s+/ : /^\s*[-*+]\s+/, "")
        const checkboxMatch = content.match(/^\[( |x|X)\]\s+(.*)$/)
        if (checkboxMatch) {
          items.push({
            text: checkboxMatch[2].trim(),
            checked: checkboxMatch[1].toLowerCase() === "x",
          })
        } else {
          items.push({
            text: content.trim(),
            checked: null,
          })
        }
        index += 1
      }
      blocks.push({
        type: "list",
        ordered,
        items,
      })
      continue
    }

    const paragraphLines: string[] = []
    while (index < lines.length) {
      const nextLine = lines[index] ?? ""
      if (!nextLine.trim()) {
        break
      }
      if (isBlockStart(nextLine)) {
        break
      }
      paragraphLines.push(nextLine.trim())
      index += 1
    }

    if (paragraphLines.length > 0) {
      blocks.push({
        type: "paragraph",
        text: paragraphLines.join(" "),
      })
      continue
    }

    blocks.push({
      type: "paragraph",
      text: trimmedLine,
    })
    index += 1
  }

  return blocks
}

const taskKey = (blockIndex: number, itemIndex: number) => `${blockIndex}:${itemIndex}`

const buildInitialTaskState = (blocks: MarkdownBlock[]) => {
  const initial: Record<string, boolean> = {}
  blocks.forEach((block, blockIndex) => {
    if (block.type !== "list") {
      return
    }
    block.items.forEach((item, itemIndex) => {
      if (item.checked === null) {
        return
      }
      initial[taskKey(blockIndex, itemIndex)] = item.checked
    })
  })
  return initial
}

const looksLikeDiff = (text: string) =>
  /^diff --git\b/m.test(text) || /^@@\s+-\d+/m.test(text) || /^(\+\+\+|---)\s+/.test(text.trim())

const resolveCodeLanguage = (language: string, text: string): SupportedLanguages => {
  const normalized = language
    .trim()
    .toLowerCase()
    .split(/\s+/)[0]

  if (normalized && CODE_LANGUAGE_ALIASES[normalized]) {
    return CODE_LANGUAGE_ALIASES[normalized]
  }

  if (looksLikeDiff(text)) {
    return "diff"
  }

  return "text"
}

const resolveCodeLabel = (language: string, resolvedLanguage: SupportedLanguages) => {
  const normalized = language.trim().split(/\s+/)[0]
  if (normalized) {
    return normalized
  }
  return resolvedLanguage
}

const createSnippetFile = ({
  language,
  text,
  blockIndex,
}: {
  language: SupportedLanguages
  text: string
  blockIndex: number
}): FileContents => {
  const extension = CODE_EXTENSION_BY_LANGUAGE[language] ?? "txt"
  return {
    name: `snippet-${blockIndex + 1}.${extension}`,
    contents: text,
    lang: language,
    cacheKey: `snippet:${blockIndex}:${language}:${text.length}`,
  }
}

const parseFileChangeSummary = (text: string) => {
  const trimmed = text.trim()

  const fencedPathMatch = trimmed.match(/^`([^`]+)`\s*(?:[:-]\s+(.+))?$/)
  if (fencedPathMatch) {
    return {
      filePath: fencedPathMatch[1].trim(),
      summary: (fencedPathMatch[2] ?? "").trim(),
    }
  }

  const plainPathMatch = trimmed.match(
    /^([A-Za-z0-9@._~/-]+(?:\.[A-Za-z0-9._-]+)?)\s*(?:[:-]\s+(.+))?$/,
  )

  if (!plainPathMatch) {
    return null
  }

  const filePath = plainPathMatch[1].trim()
  const summary = (plainPathMatch[2] ?? "").trim()
  const pathLikelyValid =
    filePath.includes("/") ||
    filePath.includes(".") ||
    filePath === "Dockerfile" ||
    filePath === "Makefile"

  if (!pathLikelyValid || filePath.includes(" ")) {
    return null
  }

  return {
    filePath,
    summary,
  }
}

const renderInlineMarkdown = (text: string): ReactNode[] => {
  const nodes: ReactNode[] = []
  const pattern = /\[([^\]]+)\]\(([^)]+)\)|`([^`]+)`|\*\*([^*]+)\*\*/g
  let lastIndex = 0
  let match = pattern.exec(text)

  while (match) {
    if (match.index > lastIndex) {
      nodes.push(text.slice(lastIndex, match.index))
    }

    if (match[1] && match[2]) {
      nodes.push(
        <a
          key={`link-${match.index}`}
          href={match[2]}
          target="_blank"
          rel="noreferrer"
          className="font-medium text-primary underline decoration-primary/60 underline-offset-4"
        >
          {match[1]}
        </a>,
      )
    } else if (match[3]) {
      nodes.push(
        <code
          key={`code-${match.index}`}
          className="rounded bg-muted px-1.5 py-0.5 font-mono text-[0.85em]"
        >
          {match[3]}
        </code>,
      )
    } else if (match[4]) {
      nodes.push(
        <strong key={`strong-${match.index}`} className="font-semibold">
          {match[4]}
        </strong>,
      )
    }

    lastIndex = pattern.lastIndex
    match = pattern.exec(text)
  }

  if (lastIndex < text.length) {
    nodes.push(text.slice(lastIndex))
  }

  if (nodes.length === 0) {
    nodes.push(text)
  }

  return nodes
}

