function MermaidBlock({ chart }: MermaidBlockProps) {
  const [svg, setSvg] = useState("")
  const [error, setError] = useState("")
  const renderId = useMemo(() => `mermaid-${Math.random().toString(36).slice(2)}`, [])

  useEffect(() => {
    let cancelled = false
    setSvg("")
    setError("")

    void (async () => {
      try {
        const mermaidModule = await import("mermaid")
        const mermaid = mermaidModule.default
        mermaid.initialize({
          startOnLoad: false,
          securityLevel: "strict",
          theme: "neutral",
        })
        const rendered = await mermaid.render(renderId, chart)
        if (cancelled) {
          return
        }
        setSvg(rendered.svg)
      } catch (nextError) {
        if (cancelled) {
          return
        }
        const message =
          nextError instanceof Error
            ? nextError.message
            : "Unable to render Mermaid diagram."
        setError(message)
      }
    })()

    return () => {
      cancelled = true
    }
  }, [chart, renderId])

  if (error) {
    return (
      <div className="space-y-2 p-3">
        <p className="text-xs text-destructive">Mermaid render failed: {error}</p>
        <pre className="overflow-x-auto rounded border border-border/70 bg-muted/40 p-3 font-mono text-xs text-foreground">
          {chart}
        </pre>
      </div>
    )
  }

  if (!svg) {
    return (
      <div className="p-3 text-xs text-muted-foreground">
        Rendering Mermaid diagram...
      </div>
    )
  }

  return (
    <div
      className="overflow-x-auto p-3 [&>svg]:mx-auto [&>svg]:max-w-full"
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  )
}

