"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"

import { cn } from "@/lib/utils"

type NavItem = {
  href: string
  label: string
}

const NAV_ITEMS: NavItem[] = [
  {
    href: "/observability",
    label: "Overview",
  },
  {
    href: "/observability/logs",
    label: "Log Explorer",
  },
  {
    href: "/observability/indexing-health",
    label: "Indexing Health",
  },
  {
    href: "/observability/onboarding-ttfr",
    label: "Onboarding TTFR",
  },
  {
    href: "/observability/model",
    label: "Model",
  },
]

const isItemActive = (pathname: string, href: string) => {
  if (href === "/observability") {
    return pathname === href
  }
  return pathname === href || pathname.startsWith(`${href}/`)
}

export function ObservabilitySectionNav() {
  const pathname = usePathname()

  return (
    <nav aria-label="Observability sections" className="overflow-x-auto pb-1">
      <div className="flex min-w-max items-center gap-2">
        {NAV_ITEMS.map((item) => {
          const active = isItemActive(pathname, item.href)
          return (
            <Link
              key={item.href}
              href={item.href}
              className={cn(
                "rounded-md border px-3 py-1.5 text-sm transition-colors",
                active
                  ? "border-primary bg-primary text-primary-foreground"
                  : "bg-background hover:bg-accent hover:text-accent-foreground",
              )}
            >
              {item.label}
            </Link>
          )
        })}
      </div>
    </nav>
  )
}

const path = require('node:path')
const { createRequire } = require('node:module')

function parseArgs(argv) {
  const out = {}
  for (let idx = 0; idx < argv.length; idx += 1) {
    const key = argv[idx]
    const value = argv[idx + 1]
    if (key && key.startsWith('--')) {
      out[key.slice(2)] = value
      idx += 1
    }
  }
  return out
}

async function main() {
  const args = parseArgs(process.argv.slice(2))
  const projectRoot = args['project-root']
  const storePath = args['store-path']

  if (!projectRoot) throw new Error('--project-root is required')
  if (!storePath) throw new Error('--store-path is required')

  const packageRoot = path.resolve(__dirname, '..', '..')
  const mcpStdioPath = path.join(packageRoot, 'mcp-stdio.js')

  const requireFrom = createRequire(mcpStdioPath)
  const indexResolved = requireFrom.resolve('./index.js')

  let indexCalls = 0
  requireFrom.cache[indexResolved] = {
    id: indexResolved,
    filename: indexResolved,
    loaded: true,
    exports: {
      async indexToKiteDb(_options, store) {
        indexCalls += 1
        process.stderr.write(`INDEX clear=${Boolean(store && store.clear)} calls=${indexCalls}\n`)
        await new Promise((r) => setTimeout(r, 50))
      },
      async searchKiteDb(args) {
        process.stderr.write(`SEARCH topK=${args && args.topK}\n`)
        return [{ score: 0.9, chunkId: 'c1', filePath: 'hello.txt', chunk: { id: 'c1', content: 'hello' } }]
      },
    },
  }

  const { createStdioMcpServer } = requireFrom('./mcp-stdio.js')

  const server = createStdioMcpServer({
    projectRoot,
    storePath,
    quiet: true,
    indexOnStart: false,
    vectorProvider: { kind: 'http', baseUrl: 'http://example.invalid', model: 'test-model', dimension: 3 },
    indexOptions: { inputs: { paths: [projectRoot], include: ['*.txt'] } },
  })

  await server.start()
}

main().catch((err) => {
  process.stderr.write(String(err && err.stack ? err.stack : err) + '\n')
  process.exitCode = 1
})

