type RepoRouteIntegrationLike = {
  id: string
  instanceUrl: string
  projectPath: string
  projectId: string
}

const slugify = (value: string, fallback: string) => {
  const normalized = value
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")

  return normalized.length > 0 ? normalized : fallback
}

const compactToken = (value: string) =>
  value.toLowerCase().replace(/[^a-z0-9]+/g, "")

const getInstanceHost = (instanceUrl: string) => {
  const trimmed = instanceUrl.trim()
  if (!trimmed) {
    return "instance"
  }

  try {
    return new URL(trimmed).host
  } catch {
    return trimmed
  }
}

export const buildRepoRouteId = ({
  id,
  instanceUrl,
  projectPath,
  projectId,
}: RepoRouteIntegrationLike) => {
  const hostSlug = slugify(getInstanceHost(instanceUrl), "instance")
  const pathSlug = slugify(projectPath, "repo")
  const projectToken = compactToken(projectId) || compactToken(id) || "repo"

  return `${hostSlug}--${pathSlug}--p${projectToken}`
}

export const buildRepoPath = (integration: RepoRouteIntegrationLike) =>
  `/repos/${encodeURIComponent(buildRepoRouteId(integration))}`

export const buildRepoMergeRequestPath = (
  integration: RepoRouteIntegrationLike,
  mergeRequestIid: string,
) => `${buildRepoPath(integration)}/mrs/${encodeURIComponent(mergeRequestIid)}`

export const buildRepoMergeRequestDescriptionPath = (
  integration: RepoRouteIntegrationLike,
  mergeRequestIid: string,
) => `${buildRepoMergeRequestPath(integration, mergeRequestIid)}/description`

export const findIntegrationByRepoRouteId = <T extends RepoRouteIntegrationLike>(
  integrations: readonly T[],
  routeId: string,
) => {
  const normalizedRouteId = routeId.trim()
  if (!normalizedRouteId) {
    return undefined
  }

  return integrations.find((integration) => (
    integration.id === normalizedRouteId ||
    buildRepoRouteId(integration) === normalizedRouteId
  ))
}

import { NextResponse } from "next/server"
import { z } from "zod"

import { getUserIntegration, resyncGitLabIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const resyncSchema = z.object({
  token: z.string().optional(),
})

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/resync`,
    event: "api.gitlab.integrations.resync",
    context: { integrationId },
    handler: async ({ logger }) => {

      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const [integration, payload] = await Promise.all([
        getUserIntegration(integrationId, userId),
        request.json().catch(() => ({})),
      ])

      if (!integration) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      const parsed = resyncSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid resync payload." }, { status: 400 }),
        }
      }

      try {
        const result = await resyncGitLabIntegration({
          integration,
          token: parsed.data.token,
        })
        logger.set({
          hasWarning: Boolean(result.warning),
        })
        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: result.integration, warning: result.warning }),
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Failed to resync integration."
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: message }, { status: 400 }),
        }
      }
    },
  })
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type CollapsibleContextValue = {
  open: boolean
  setOpen: (open: boolean) => void
}

const CollapsibleContext = React.createContext<CollapsibleContextValue | null>(null)

const useCollapsibleContext = () => {
  const context = React.useContext(CollapsibleContext)
  if (!context) {
    throw new Error("Collapsible components must be used within a Collapsible.")
  }
  return context
}

type CollapsibleProps = {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  disabled?: boolean
  asChild?: boolean
  className?: string
  children: React.ReactNode
}

export const Collapsible = ({
  open,
  defaultOpen = false,
  onOpenChange,
  disabled = false,
  className,
  children,
}: CollapsibleProps) => {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen)
  const controlled = typeof open === "boolean"
  const isOpen = controlled ? open : internalOpen

  React.useEffect(() => {
    if (!controlled) {
      return
    }
    setInternalOpen(open)
  }, [controlled, open])

  const setOpen = React.useCallback(
    (nextOpen: boolean) => {
      if (disabled) {
        return
      }

      if (!controlled) {
        setInternalOpen(nextOpen)
      }
      onOpenChange?.(nextOpen)
    },
    [disabled, controlled, onOpenChange],
  )

  return (
    <CollapsibleContext.Provider value={{ open: isOpen, setOpen }}>
      <div
        className={cn(
          "group/collapsible",
          "data-[state=open]:animate-in data-[state=closed]:animate-out",
          className,
        )}
        data-state={isOpen ? "open" : "closed"}
      >
        {children}
      </div>
    </CollapsibleContext.Provider>
  )
}

type CollapsibleTriggerProps = React.HTMLAttributes<HTMLElement> & {
  asChild?: boolean
}

export const CollapsibleTrigger = ({
  className,
  children,
  asChild,
  onClick,
  ...props
}: CollapsibleTriggerProps) => {
  const { open, setOpen } = useCollapsibleContext()

  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    onClick?.(event)
    if (event.defaultPrevented) {
      return
    }
    setOpen(!open)
  }

  if (!asChild || !React.isValidElement(children)) {
    return (
      <button
        type="button"
        aria-expanded={open}
        onClick={handleClick}
        className={className}
        {...props}
      >
        {children}
      </button>
    )
  }

  const child = React.Children.only(children) as React.ReactElement<
    React.HTMLAttributes<HTMLElement> & { "data-state"?: string }
  >
  const childProps = child.props

  return React.cloneElement(child, {
    ...props,
    ...childProps,
    onClick: (event: React.MouseEvent<HTMLElement>) => {
      childProps.onClick?.(event)
      if (event.defaultPrevented) {
        return
      }
      handleClick(event)
    },
    "aria-expanded": childProps["aria-expanded"] ?? open,
    "data-state": open ? "open" : "closed",
    className: cn(childProps.className, className),
  })
}

type CollapsibleContentProps = React.HTMLAttributes<HTMLDivElement>

export const CollapsibleContent = ({ className, children, ...props }: CollapsibleContentProps) => {
  const { open } = useCollapsibleContext()

  return (
    <div
      className={cn(
        "data-[state=open]:animate-in data-[state=closed]:animate-out",
        "overflow-hidden",
        className,
      )}
      data-state={open ? "open" : "closed"}
      hidden={!open}
      {...props}
    >
      {children}
    </div>
  )
}

