const DEFAULT_TOP_K = 5

function clampTopK(topK) {
  const value = Number(topK)
  if (!Number.isFinite(value)) return DEFAULT_TOP_K
  return Math.max(1, Math.min(50, Math.floor(value)))
}

function isObject(value) {
  return value !== null && typeof value === 'object'
}

function readFirst(obj, keys) {
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      return obj[key]
    }
  }
  return undefined
}

function toOptionalString(value) {
  if (value == null) return null
  const text = String(value).trim()
  return text.length > 0 ? text : null
}

function toOptionalRangeJson(value, index) {
  if (value == null) return null
  if (typeof value === 'string') {
    const text = value.trim()
    return text.length > 0 ? text : null
  }
  if (isObject(value)) {
    try {
      return JSON.stringify(value)
    } catch (error) {
      throw new Error(`invalid search hit at index ${index}: rangeJson is not serializable (${error})`)
    }
  }
  throw new Error(`invalid search hit at index ${index}: rangeJson must be a string/object/null`)
}

function toOptionalContent(value, index) {
  if (value == null) return null
  if (typeof value === 'string') return value
  throw new Error(`invalid search hit at index ${index}: content must be a string/null`)
}

function normalizeSearchHit(hit, index) {
  if (!isObject(hit)) {
    throw new Error(`invalid search hit at index ${index}: expected object`)
  }

  const score = Number(hit.score)
  if (!Number.isFinite(score)) {
    throw new Error(`invalid search hit at index ${index}: score must be a finite number`)
  }

  const chunkId = toOptionalString(readFirst(hit, ['chunkId', 'chunk_id']))
  if (!chunkId) {
    throw new Error(`invalid search hit at index ${index}: chunkId is required`)
  }

  const filePath = toOptionalString(readFirst(hit, ['filePath', 'file_path']))
  const rangeJson = toOptionalRangeJson(readFirst(hit, ['rangeJson', 'range_json']), index)
  const content = toOptionalContent(readFirst(hit, ['content']), index)

  return { score, chunkId, filePath, rangeJson, content }
}

function normalizeSearchHits(hits, source = 'search') {
  if (!Array.isArray(hits)) {
    throw new Error(`${source} returned invalid payload: expected an array`)
  }
  return hits.map((hit, index) => normalizeSearchHit(hit, index))
}

module.exports = {
  clampTopK,
  normalizeSearchHits,
}

