import { eq, inArray, sql } from "drizzle-orm"
import { NextResponse } from "next/server"

import { db } from "@/lib/db"
import { appLogEvents, indexBranchStates, indexJobs, indexRuns } from "@/lib/db/schema"
import { getUserIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const STREAM_POLL_INTERVAL_MS = 2_000
const STREAM_KEEPALIVE_INTERVAL_MS = 15_000

const INDEXER_WORKER_EVENTS = [
  "indexer.worker.started",
  "indexer.worker.batch_cycle",
  "indexer.batch.processing",
] as const

const toIso = (value: unknown) => {
  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value.toISOString()
  }
  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = new Date(value)
    return Number.isNaN(parsed.getTime()) ? null : parsed.toISOString()
  }
  return null
}

const loadStreamCursor = async (integrationId: string) => {
  const [[runsRow], [branchesRow], [jobsRow], [workerRow]] = await Promise.all([
    db
      .select({
        value: sql<Date | null>`max(${indexRuns.updatedAt})`,
      })
      .from(indexRuns)
      .innerJoin(indexBranchStates, eq(indexRuns.branchStateId, indexBranchStates.id))
      .where(eq(indexBranchStates.integrationId, integrationId)),
    db
      .select({
        value: sql<Date | null>`max(${indexBranchStates.updatedAt})`,
      })
      .from(indexBranchStates)
      .where(eq(indexBranchStates.integrationId, integrationId)),
    db
      .select({
        value: sql<Date | null>`max(${indexJobs.updatedAt})`,
      })
      .from(indexJobs)
      .where(eq(indexJobs.integrationId, integrationId)),
    db
      .select({
        value: sql<Date | null>`max(${appLogEvents.timestamp})`,
      })
      .from(appLogEvents)
      .where(inArray(appLogEvents.event, [...INDEXER_WORKER_EVENTS])),
  ])

  const runsUpdatedAt = toIso(runsRow?.value)
  const branchesUpdatedAt = toIso(branchesRow?.value)
  const jobsUpdatedAt = toIso(jobsRow?.value)
  const workerHeartbeatAt = toIso(workerRow?.value)

  return {
    cursor: `${runsUpdatedAt ?? "-"}|${branchesUpdatedAt ?? "-"}|${jobsUpdatedAt ?? "-"}|${workerHeartbeatAt ?? "-"}`,
    runsUpdatedAt,
    branchesUpdatedAt,
    jobsUpdatedAt,
    workerHeartbeatAt,
  }
}

export async function GET(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({

request,
path: `/api/gitlab/integrations/${integrationId}/index/stream`,
event: "api.gitlab.integrations.index.stream",
context: { integrationId },
handler: async () => {
  const userId = await getSessionUserId()
  if (!userId) {
    return {
      status: 401,
      outcome: "unauthorized",
      response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
    }
  }

  const integration = await getUserIntegration(integrationId, userId)
  if (!integration) {
    return {
      status: 404,
      outcome: "not_found",
      response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
    }
  }

  const encoder = new TextEncoder()
  let closed = false

  let pollTimer: ReturnType<typeof setInterval> | null = null
  let keepAliveTimer: ReturnType<typeof setInterval> | null = null
  let inFlight = false
  let latestCursor = ""

  const close = (controller: ReadableStreamDefaultController<Uint8Array>) => {
    if (closed) {
      return
    }
    closed = true
    if (pollTimer) {
      clearInterval(pollTimer)
      pollTimer = null
    }
    if (keepAliveTimer) {
      clearInterval(keepAliveTimer)
      keepAliveTimer = null
    }
    try {
      controller.close()
    } catch {
      // no-op
    }
  }

const sendEvent = (
  controller: ReadableStreamDefaultController<Uint8Array>,
  event: string,
  data: Record<string, unknown>,
) => {
  if (closed) {
    return
  }
  controller.enqueue(
    encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`),
  )
}

const stream = new ReadableStream<Uint8Array>({

  start(controller) {
    const checkForChanges = async (force = false) => {
      if (closed || inFlight) {
        return
      }
      inFlight = true
      try {
        const snapshot = await loadStreamCursor(integration.id)
        if (force || snapshot.cursor !== latestCursor) {
          latestCursor = snapshot.cursor
          sendEvent(controller, force ? "ready" : "update", {
            ...snapshot,
            at: new Date().toISOString(),
          })
        }
      } catch {
        sendEvent(controller, "error", {
          code: "STREAM_CHECK_FAILED",
          at: new Date().toISOString(),
        })
      } finally {
        inFlight = false
      }
    }

    request.signal.addEventListener("abort", () => {
      close(controller)
    })

    void checkForChanges(true)
    pollTimer = setInterval(() => {
      void checkForChanges(false)
    }, STREAM_POLL_INTERVAL_MS)
    keepAliveTimer = setInterval(() => {
      if (closed) {
        return
      }
      controller.enqueue(encoder.encode(": ping\n\n"))
    }, STREAM_KEEPALIVE_INTERVAL_MS)
  },
  cancel() {
    closed = true
    if (pollTimer) {
      clearInterval(pollTimer)
      pollTimer = null
    }
    if (keepAliveTimer) {
      clearInterval(keepAliveTimer)
      keepAliveTimer = null
    }
  },
})

      return {
        status: 200,
        outcome: "success",
        response: new Response(stream, {
          headers: {
            "content-type": "text/event-stream; charset=utf-8",
            "cache-control":
              "private, max-age=0, must-revalidate, no-transform",
            connection: "keep-alive",
            "x-accel-buffering": "no",
          },
        }),
      }
    },
  })
}

import { isIP } from "node:net"

const allowPrivateHosts = process.env.JIRA_ALLOW_PRIVATE_HOSTS === "1"

const isPrivateIpv4 = (hostname: string) => {
  const parts = hostname.split(".").map((part) => Number.parseInt(part, 10))
  if (parts.length !== 4 || parts.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) {
    return true
  }

  const [first, second] = parts
  if (
    first === 10 ||
    first === 127 ||
    first === 0 ||
    (first === 169 && second === 254) ||
    (first === 172 && second >= 16 && second <= 31) ||
    (first === 192 && second === 168) ||
    (first === 100 && second >= 64 && second <= 127) ||
    (first === 198 && (second === 18 || second === 19)) ||
    first >= 224
  ) {
    return true
  }

  return false
}

const isPrivateIpv6 = (hostname: string) => {
  const normalized = hostname.toLowerCase()
  if (normalized === "::" || normalized === "::1") {
    return true
  }

  if (
    normalized.startsWith("fc") ||
    normalized.startsWith("fd") ||
    normalized.startsWith("fe8") ||
    normalized.startsWith("fe9") ||
    normalized.startsWith("fea") ||
    normalized.startsWith("feb") ||
    normalized.startsWith("2001:db8:")
  ) {
    return true
  }

  if (normalized.startsWith("::ffff:")) {
    return isPrivateIpv4(normalized.slice("::ffff:".length))
  }

  return false
}

const isPrivateHostname = (hostname: string) =>
  hostname === "localhost" ||
  hostname.endsWith(".localhost") ||
  hostname.endsWith(".local")

const isPrivateTarget = (hostname: string) => {
  const normalized = hostname.trim().toLowerCase()
  if (!normalized) {
    return true
  }

  const ipKind = isIP(normalized)
  if (ipKind === 4) {
    return isPrivateIpv4(normalized)
  }
  if (ipKind === 6) {
    return isPrivateIpv6(normalized)
  }

  return isPrivateHostname(normalized)
}

export const normalizeJiraInstanceUrl = (input: string) => {
  const trimmed = input.trim().replace(/\/+$/, "")
  if (!trimmed) {
    throw new Error("Jira instance URL is required.")
  }

  const withProtocol = /^https?:\/\//i.test(trimmed) ? trimmed : `https://${trimmed}`

  let parsed: URL
  try {
    parsed = new URL(withProtocol)
  } catch {
    throw new Error("Jira instance URL is invalid.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("Jira instance URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("Jira instance URL must not include credentials.")
  }
  if (!allowPrivateHosts && isPrivateTarget(parsed.hostname)) {
    throw new Error(
      "Jira instance URL must use a public host. Set JIRA_ALLOW_PRIVATE_HOSTS=1 to allow private hosts.",
    )
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  return pathname ? `${parsed.origin}${pathname}` : parsed.origin
}

