const HOME_CACHE_TTL_MS = 20_000
const HOME_CACHE_MAX_ENTRIES = 128

type HomeCacheEntry<T> = {
  expiresAt: number
  value: Promise<T>
}

const homeOnboardingStatusCache = new Map<string, HomeCacheEntry<boolean>>()

const trimHomeCache = <T,>(cache: Map<string, HomeCacheEntry<T>>) => {
  const now = Date.now()
  for (const [key, value] of cache.entries()) {
    if (value.expiresAt <= now) {
      cache.delete(key)
    }
  }

  while (cache.size > HOME_CACHE_MAX_ENTRIES) {
    const oldestKey = cache.keys().next().value
    if (!oldestKey) {
      break
    }
    cache.delete(oldestKey)
  }
}

const getCachedHomeValue = <T,>(
  cache: Map<string, HomeCacheEntry<T>>,
  key: string,
  load: () => Promise<T>,
) => {
  const now = Date.now()
  const cached = cache.get(key)
  if (cached && cached.expiresAt > now) {
    return cached.value
  }
  if (cached) {
    cache.delete(key)
  }

  const value = load()
  cache.set(key, {
    expiresAt: now + HOME_CACHE_TTL_MS,
    value,
  })
  trimHomeCache(cache)

  value.catch(() => {
    const current = cache.get(key)
    if (current?.value === value) {
      cache.delete(key)
    }
  })

  return value
}

export default async function HomePage() {
  const { session, isAlphaDenied } = await getSessionAccess()

  if (!session?.user?.id) {
    return (
      <div className="flex min-h-dvh items-center justify-center px-4">
        {isAlphaDenied ? (
          <AlphaAccessDenied message={ALPHA_ACCESS_DENIED_MESSAGE} />
        ) : (
          <RootAuth />
        )}
      </div>
    )
  }

  const [completed, integrations] = await Promise.all([
    getCachedHomeValue(homeOnboardingStatusCache, session.user.id, () =>
      isOnboardingCompleted(session.user.id),
    ),
    getCachedUserIntegrations(session.user.id),
  ])
  if (!completed) {
    redirect("/onboarding/tokens")
  }

  const recentIntegrations = [...integrations].sort(
    (left, right) => right.updatedAt.getTime() - left.updatedAt.getTime(),
  )

  return (
    <div className="space-y-4">

      {recentIntegrations.length === 0 ? (
        <div className="rounded-md border border-dashed p-4 text-sm text-muted-foreground">
          No repos connected yet.
        </div>
      ) : (
        <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {recentIntegrations.map((integration) => (
            <Link
              key={integration.id}
              href={buildRepoPath(integration)}
              className="group block rounded-xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <Card className="border-border/60 transition-colors group-hover:bg-accent/25">
                <CardHeader className="space-y-2">
                  <div className="flex items-center justify-between gap-3">
                    <CardTitle className="line-clamp-1">{integration.projectName}</CardTitle>
                    <Badge
                      variant={
                        integration.status === "active"
                          ? "default"
                          : integration.status === "degraded"
                            ? "secondary"
                            : "outline"
                      }
                    >
                      {integration.status}
                    </Badge>
                  </div>
                  <CardDescription className="line-clamp-1">{integration.projectPath}</CardDescription>
                </CardHeader>
              </Card>
            </Link>
          ))}
        </section>
      )}
    </div>
  )
}

