import { useEffect, useRef } from "react"
import { toast } from "sonner"

const COPY_ERROR_SUCCESS_MESSAGE = "Error details copied."
const COPY_ERROR_FAILURE_MESSAGE = "Could not copy error details."

export const copyErrorToClipboard = async (message: string) => {
  if (
    typeof navigator === "undefined" ||
    !navigator.clipboard ||
    typeof navigator.clipboard.writeText !== "function"
  ) {
    throw new Error("Clipboard API is unavailable.")
  }

  await navigator.clipboard.writeText(message)
}

export const useCopyableErrorToast = (
  message: string,
  options?: {
    title?: string
    action?: {
      label: string
      onClick: (message: string) => void | Promise<void>
    }
  },
) => {
  const lastToastSignature = useRef("")

  useEffect(() => {
    const trimmedMessage = message.trim()
    if (!trimmedMessage) {
      return
    }

    const title = options?.title?.trim() || "Request failed"
    const signature = `${title}::${trimmedMessage}`
    if (signature === lastToastSignature.current) {
      return
    }
    lastToastSignature.current = signature

    toast.error(title, {
      description: trimmedMessage,
      duration: 10_000,
      action: options?.action
        ? {
            label: options.action.label,
            onClick: () => {
              void options.action?.onClick(trimmedMessage)
            },
          }
        : {
            label: "Copy",
            onClick: () => {
              void copyErrorToClipboard(trimmedMessage)
                .then(() => {
                  toast.success(COPY_ERROR_SUCCESS_MESSAGE)
                })
                .catch(() => {
                  toast.error(COPY_ERROR_FAILURE_MESSAGE)
                })
            },
          },
    })
  }, [message, options?.action, options?.title])
}

import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import { createRequire } from 'node:module'

import test from 'ava'

const require = createRequire(import.meta.url)
const { formatSearchHits, resolveColorMode } = require('../sdk.js') as {
  formatSearchHits: (hits: any[], options?: Record<string, unknown>) => string
  resolveColorMode: (mode?: string, options?: Record<string, unknown>) => boolean
}

test('search formatter: color mode respects auto/always/never', (t) => {
  t.false(resolveColorMode('never', { isTTY: true, env: {} }))
  t.true(resolveColorMode('always', { isTTY: false, env: { NO_COLOR: '1' } }))
  t.true(resolveColorMode('auto', { isTTY: true, env: {} }))
  t.false(resolveColorMode('auto', { isTTY: true, env: { NO_COLOR: '1' } }))
})

test('search formatter: renders plain output and content fallback', (t) => {
  const out = formatSearchHits(
    [{ score: 0.42, chunkId: 'chunk-1', filePath: 'src/a.ts', content: 'function a() {}' }],
    { color: 'never', includeContentFallback: true },
  )
  t.true(out.includes('0.4200'))
  t.true(out.includes('chunk-1'))
  t.true(out.includes('function a() {}'))
  t.false(out.includes('\x1b['))
})

test('search formatter: reads snippets from projectRoot + rangeJson', (t) => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'code-intel-format-'))
  t.teardown(() => fs.rmSync(root, { recursive: true, force: true }))
  fs.mkdirSync(path.join(root, 'src'), { recursive: true })
  fs.writeFileSync(path.join(root, 'src', 'a.ts'), 'line1\nline2\nline3\n', 'utf8')

  const out = formatSearchHits(
    [
      {
        score: 1,
        chunkId: 'chunk-2',
        filePath: 'src/a.ts',
        rangeJson: JSON.stringify({ start: { row: 1, column: 0 }, end: { row: 1, column: 5 } }),
      },
    ],
    { projectRoot: root, context: 0, color: 'never' },
  )
  t.true(out.includes('src/a.ts:2-2'))
  // Line format uses Unicode vertical bar: "2 │ line2"
  t.true(out.includes('2') && out.includes('line2'))
})

