fn ci_search_reuses_query_embedding_cache() -> Result<(), Box<dyn std::error::Error>> {
  let (base_url, requests, _handle) = spawn_embeddings_server_with_counter();
  let tmp = TempDir::new()?;
  write_file(
    &tmp.path().join("src/a.ts"),
    r#"export function Login() { return 1 }
export function main() { return Login() }
"#,
  );

  let init = ci_cmd()
    .args([
      "--project-root",
      tmp.path().to_str().unwrap(),
      "init",
      "--vector-base-url",
      &base_url,
      "--vector-model",
      "test-model",
    ])
    .output()?;

  assert!(
    init.status.success(),
    "init failed: {}",
    String::from_utf8_lossy(&init.stderr)
  );

  let config = tmp.path().join("argus-search.json");
  let watch = ci_cmd()
    .args([
      "--config",
      config.to_str().unwrap(),
      "watch",
      "--once",
      "--phases",
      "parse,vector",
    ])
    .output()?;
  assert!(
    watch.status.success(),
    "watch failed: {}",
    String::from_utf8_lossy(&watch.stderr)
  );

  let before = requests.load(Ordering::SeqCst);
  let search1 = ci_cmd()
    .args([
      "--config",
      config.to_str().unwrap(),
      "search",
      "Login",
      "--top-k",
      "3",
      "--json",
    ])
    .output()?;
  assert!(
    search1.status.success(),
    "first search failed: {}",
    String::from_utf8_lossy(&search1.stderr)
  );

  let after_first = requests.load(Ordering::SeqCst);
  assert!(
    after_first > before,
    "expected first search to request embeddings: before={before} after={after_first}"
  );

  let search2 = ci_cmd()
    .args([
      "--config",
      config.to_str().unwrap(),
      "search",
      "Login",
      "--top-k",
      "3",
      "--json",
    ])
    .output()?;
  assert!(
    search2.status.success(),
    "second search failed: {}",
    String::from_utf8_lossy(&search2.stderr)
  );

  let after_second = requests.load(Ordering::SeqCst);
  assert_eq!(
    after_second, after_first,
    "expected second identical search to hit cache without extra embeddings request"
  );
  Ok(())
}

