import { NextResponse } from "next/server"

import {
  normalizeReviewGateScope,
  resolveReviewGatePreferences,
} from "@/lib/review/preferences"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/preferences",
    event: "api.review.preferences.get",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const params = new URL(request.url).searchParams
      const scope = normalizeReviewGateScope({
        instanceUrl: params.get("instanceUrl"),
        projectId: params.get("projectId"),
      })

      const resolved = await resolveReviewGatePreferences({
        userId,
        scope,
      })

      logger.set({
        scopeSource: resolved.effectiveSettings.scopeSource,
        hasProjectScope: Boolean(scope),
        hasProjectOverride: Boolean(resolved.projectOverride),
      })

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            global: resolved.globalSettings,
            projectOverride: resolved.projectOverride,
            effective: resolved.effectiveSettings,
          },
        }),
      }
    },
  })
}

"use client"

import { useState } from "react"
import { IconAlertCircle, IconLogout2 } from "@tabler/icons-react"

import { authClient } from "@/lib/auth-client"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"

type AlphaAccessDeniedProps = {
  message: string
}

const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value && typeof value === "object" && "message" in value) {
    return String((value as { message?: string }).message)
  }
  return "Could not sign out. Try again."
}

export function AlphaAccessDenied({ message }: AlphaAccessDeniedProps) {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")

  const handleSignOut = async () => {
    setBusy(true)
    setError("")

    const { error: signOutError } = await authClient.signOut()
    if (signOutError) {
      setBusy(false)
      setError(getErrorMessage(signOutError))
      return
    }

    window.location.replace("/")
  }

  return (
    <Card className="w-full max-w-md">
      <CardHeader className="space-y-2">
        <CardTitle className="flex items-center gap-2">
          <IconAlertCircle className="size-5 text-amber-600" />
          Alpha access required
        </CardTitle>
        <CardDescription>{message}</CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        <Button type="button" variant="outline" onClick={handleSignOut} disabled={busy}>
          <IconLogout2 className="size-4" />
          {busy ? "Signing out..." : "Sign out"}
        </Button>
        {error ? <p className="text-xs text-destructive">{error}</p> : null}
      </CardContent>
    </Card>
  )
}

