  let first = TombstoneResult {
    symbols_to_remove: ["scip:a".to_string()].into_iter().collect(),
    edges_to_remove: ["edge:a->b:CALLS".to_string()].into_iter().collect(),
    overflow_edge_ids: vec!["overflow-1".to_string()],
  };
  let second = TombstoneResult {
    symbols_to_remove: ["scip:b".to_string()].into_iter().collect(),
    edges_to_remove: ["edge:b->c:CALLS".to_string()].into_iter().collect(),
    overflow_edge_ids: vec!["overflow-1".to_string(), "overflow-2".to_string()],
  };

  let merged = merge_tombstones(&[first, second]);
  assert_eq!(merged.symbols_to_remove.len(), 2);
  assert_eq!(merged.edges_to_remove.len(), 2);
  assert_eq!(merged.overflow_edge_ids.len(), 2);
}

