const toErrorMessage = (error: unknown) => {
  if (error instanceof Error) {
    return truncateError(error.message)
  }
  return "Unexpected GitLab integration error."
}

const toErrorMessageChain = (error: unknown): string => {
  if (error instanceof Error) {
    const cause = (error as Error & { cause?: unknown }).cause
    if (cause) {
      return `${error.message}\n${toErrorMessageChain(cause)}`
    }
    return error.message
  }
  if (typeof error === "string") {
    return error
  }
  return ""
}

const isMissingAiReviewColumnError = (error: unknown) => {
  const message = toErrorMessageChain(error).toLowerCase()
  return (
    message.includes("ai_review_auto_post_enabled") &&
    (message.includes("does not exist") || message.includes("undefined column"))
  )
}

const withGitLabSchemaHint = async <T>(work: () => Promise<T>): Promise<T> => {
  try {
    return await work()
  } catch (error) {
    if (isMissingAiReviewColumnError(error)) {
      throw new Error(
        'Database schema is out of date for GitLab integrations. Run "bun run --cwd apps/web db:migrate" with DATABASE_URL set.',
        { cause: error },
      )
    }
    throw error
  }
}

const assertNonEmpty = (value: string, fieldName: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    throw new Error(`${fieldName} is required.`)
  }
  return trimmed
}

const buildWebhookUrl = (integrationId: string) =>
  `${gitlabEnv.appPublicUrl}${GITLAB_WEBHOOK_PATH_PREFIX}/${integrationId}`

export const enqueueGitLabJob = async ({
  integrationId,
  jobType,
  deliveryId,
  normalizedPayload,
}: {
  integrationId: string
  jobType: GitLabJobType
  deliveryId?: string
  normalizedPayload?: Record<string, unknown>
}) => {
  await db.insert(gitlabJobs).values({
    integrationId,
    deliveryId,
    jobType,
    status: "pending",
    attempts: 0,
    nextAttemptAt: new Date(),
    normalizedPayload,
    updatedAt: new Date(),
  })
}

export const decryptIntegrationToken = (integration: GitLabIntegration) => {
  if (!integration.tokenCiphertext || !integration.tokenIv || !integration.tokenAuthTag) {
    throw new Error("No encrypted GitLab token is available for this integration.")
  }

  return decryptGitLabToken({
    ciphertext: integration.tokenCiphertext,
    iv: integration.tokenIv,
    authTag: integration.tokenAuthTag,
  })
}

const updateIntegrationToken = async (integrationId: string, token: string) => {
  const encrypted = encryptGitLabToken(token)
  await db
    .update(gitlabIntegrations)
    .set({
      tokenCiphertext: encrypted.ciphertext,
      tokenIv: encrypted.iv,
      tokenAuthTag: encrypted.authTag,
      updatedAt: new Date(),
    })
    .where(eq(gitlabIntegrations.id, integrationId))
}

export const syncIntegrationWebhook = async ({
  integration,
  token,
}: {
  integration: GitLabIntegration
  token: string
}): Promise<SyncResult> => {
  const webhookSecret = generateWebhookSecret()
  const webhookSecretHash = hashWebhookSecret(webhookSecret)

  try {
    const { hookId } = await upsertProjectWebhook({
      instanceUrl: integration.instanceUrl,
      token,
      projectId: integration.projectId,
      callbackUrl: buildWebhookUrl(integration.id),
      secret: webhookSecret,
    })

    await db
      .update(gitlabIntegrations)
      .set({
        hookId,
        webhookUrl: buildWebhookUrl(integration.id),
        webhookSecretHash,
        status: "active",
        lastHookSyncAt: new Date(),
        lastError: null,
        updatedAt: new Date(),
      })
      .where(eq(gitlabIntegrations.id, integration.id))

    return { ok: true }
  } catch (error) {
    const message = describeWebhookSyncError(error) ?? toErrorMessage(error)
    await db
      .update(gitlabIntegrations)
      .set({
        status: "degraded",
        lastError: message,
        updatedAt: new Date(),
      })
      .where(eq(gitlabIntegrations.id, integration.id))

    return {
      ok: false,
      error: message,
    }
  }
}

export const connectGitLabIntegration = async ({
  userId,
  instanceUrl,
  token,
  projectId,
  projectPath,
  projectName,
}: {
  userId: string
  instanceUrl: string
  token: string
  projectId: string
  projectPath: string
  projectName: string
}) => {
  const normalizedInstanceUrl = normalizeGitLabInstanceUrl(instanceUrl)

const normalizedProjectId = assertNonEmpty(projectId, "projectId")
const normalizedProjectPath = assertNonEmpty(projectPath, "projectPath")
const normalizedProjectName = assertNonEmpty(projectName, "projectName")
const normalizedToken = assertNonEmpty(token, "token")

const existing = await db.query.gitlabIntegrations.findFirst({
  where: and(
    eq(gitlabIntegrations.instanceUrl, normalizedInstanceUrl),
    eq(gitlabIntegrations.projectId, normalizedProjectId),
  ),
})

if (existing) {
  await linkMembership(existing.id, userId)
  await enqueueGitLabJob({
    integrationId: existing.id,
    jobType: "hook_sync",
    normalizedPayload: {
      reason: "connect_existing",
    },
  })

  return {
    created: false,
    integration: integrationToSummary(existing),
    warning:
      existing.status === "active"
        ? undefined
        : "Integration linked. Hook verification queued in background.",
  }
}

const integrationId = randomUUID()
const encryptedToken = encryptGitLabToken(normalizedToken)
const bootstrapSecret = generateWebhookSecret()

const insertedRows = await db
  .insert(gitlabIntegrations)
  .values({
    id: integrationId,
    instanceUrl: normalizedInstanceUrl,
    projectId: normalizedProjectId,
    projectPath: normalizedProjectPath,
    projectName: normalizedProjectName,
    webhookUrl: buildWebhookUrl(integrationId),
    webhookSecretHash: hashWebhookSecret(bootstrapSecret),
    tokenCiphertext: encryptedToken.ciphertext,
    tokenIv: encryptedToken.iv,
    tokenAuthTag: encryptedToken.authTag,
    status: "degraded",
    lastError: "Pending initial webhook sync.",
  })
  .onConflictDoNothing()
  .returning()

const inserted = insertedRows[0]
if (!inserted) {
  const winner = await db.query.gitlabIntegrations.findFirst({
    where: and(
      eq(gitlabIntegrations.instanceUrl, normalizedInstanceUrl),
      eq(gitlabIntegrations.projectId, normalizedProjectId),
    ),
  })

  if (!winner) {
    throw new Error("Failed to resolve shared GitLab integration.")
  }

  await linkMembership(winner.id, userId)
  await enqueueGitLabJob({
    integrationId: winner.id,
    jobType: "hook_sync",
    normalizedPayload: {
      reason: "connect_race_winner",
    },
  })

  return {
    created: false,
    integration: integrationToSummary(winner),
    warning: "Integration linked. Hook verification queued in background.",
  }
}

await linkMembership(inserted.id, userId)

const syncResult = await syncIntegrationWebhook({
  integration: inserted,
  token: normalizedToken,
})

  const updatedIntegration = await getIntegrationById(inserted.id)
  if (!updatedIntegration) {
    throw new Error("Integration created but not found after sync.")
  }

  return {
    created: true,
    integration: integrationToSummary(updatedIntegration),
    warning: syncResult.ok ? undefined : syncResult.error,
  }
}

export const getUserIntegration = async (integrationId: string, userId: string) => {
  const rows = await withGitLabSchemaHint(() =>
    db
      .select({ integration: gitlabIntegrations })
      .from(gitlabIntegrationMemberships)
      .innerJoin(
        gitlabIntegrations,
        eq(gitlabIntegrationMemberships.integrationId, gitlabIntegrations.id),
      )
      .where(
        and(
          eq(gitlabIntegrationMemberships.integrationId, integrationId),
          eqGitLabMembershipUserId(userId),
        ),
      )
      .limit(1),
  )

  return rows[0]?.integration
}

export const resyncGitLabIntegration = async ({
  integration,
  token,
}: {
  integration: GitLabIntegration
  token?: string
}) => {
  const normalizedToken = token?.trim()

  let tokenToUse: string
  if (normalizedToken) {
    await updateIntegrationToken(integration.id, normalizedToken)
    tokenToUse = normalizedToken
  } else {
    tokenToUse = decryptIntegrationToken(integration)
  }

  const current = (await getIntegrationById(integration.id)) ?? integration
  const syncResult = await syncIntegrationWebhook({
    integration: current,
    token: tokenToUse,
  })

  const updated = await getIntegrationById(integration.id)
  if (!updated) {
    throw new Error("Integration no longer exists.")
  }

  return {
    integration: integrationToSummary(updated),
    warning: syncResult.ok ? undefined : syncResult.error,
  }
}

export const updateGitLabIntegrationAiReviewSettings = async ({
  integrationId,
  autoPostEnabled,
}: {
  integrationId: string
  autoPostEnabled: boolean
}) => {
  await db
    .update(gitlabIntegrations)
    .set({
      aiReviewAutoPostEnabled: autoPostEnabled,
      updatedAt: new Date(),
    })
    .where(eq(gitlabIntegrations.id, integrationId))

  const updated = await getIntegrationById(integrationId)
  if (!updated) {
    throw new Error("Integration not found.")
  }
  return integrationToSummary(updated)
}

export const disconnectGitLabIntegration = async ({
  integration,
  userId,
}: {
  integration: GitLabIntegration
  userId: string
}) => {
  await db
    .delete(gitlabIntegrationMemberships)
    .where(
      and(
        eq(gitlabIntegrationMemberships.integrationId, integration.id),
        eqGitLabMembershipUserId(userId),
      ),
    )

  const countResult = await db
    .select({ value: count() })
    .from(gitlabIntegrationMemberships)
    .where(eq(gitlabIntegrationMemberships.integrationId, integration.id))

  const memberCount = Number(countResult[0]?.value ?? 0)
  if (memberCount > 0) {
    return {
      scope: "personal" as const,
      warning: undefined,
    }
  }

  let warning: string | undefined
  try {
    if (integration.tokenCiphertext && integration.tokenIv && integration.tokenAuthTag) {
      const token = decryptIntegrationToken(integration)
      await deleteProjectWebhook({
        instanceUrl: integration.instanceUrl,
        token,
        projectId: integration.projectId,
        callbackUrl: integration.webhookUrl,
        hookId: integration.hookId,
      })
    }
  } catch (error) {
    warning = `Hook cleanup warning: ${toErrorMessage(error)}`
  }

  await db
    .update(gitlabIntegrations)
    .set({
      hookId: null,
      webhookSecretHash: null,
      tokenCiphertext: null,
      tokenIv: null,
      tokenAuthTag: null,
      status: "disabled",
      lastError: warning ?? null,
      updatedAt: new Date(),
    })
    .where(eq(gitlabIntegrations.id, integration.id))

  return {
    scope: "global" as const,
    warning,
  }
}

export const ingestWebhookDelivery = async ({
  integrationId,
  eventUuid,
  eventName,
  eventType,
  ref,
  payload,
  jobType,
  normalizedPayload,
}: {
  integrationId: string
  eventUuid: string
  eventName: string
  eventType: "push" | "merge_request" | "ignored"
  ref: string | null
  payload: Record<string, unknown>
  jobType?: "push" | "merge_request"
  normalizedPayload?: Record<string, unknown>
}) => {
  return db.transaction(async (tx) => {
    await tx
      .update(gitlabIntegrations)
      .set({
        lastWebhookReceivedAt: new Date(),
        updatedAt: new Date(),
      })
      .where(eq(gitlabIntegrations.id, integrationId))

    const insertedDeliveries = await tx
      .insert(gitlabWebhookDeliveries)
      .values({
        integrationId,
        eventUuid,
        eventName,
        eventType,
        ref,
        payload,
      })
      .onConflictDoNothing()
      .returning({ id: gitlabWebhookDeliveries.id })

    const deliveryId = insertedDeliveries[0]?.id
    if (!deliveryId) {
      return {
        deduped: true,
        enqueued: false,
      }
    }

    if (jobType) {
      await tx.insert(gitlabJobs).values({
        integrationId,
        deliveryId,
        jobType,
        status: "pending",
        attempts: 0,
        nextAttemptAt: new Date(),
        normalizedPayload,
        updatedAt: new Date(),
      })
    }

    return {
      deduped: false,
      enqueued: Boolean(jobType),
    }
  })
}

