import { NextResponse } from "next/server"

import {
  getCodeGraphSummary,
  refreshCodeGraphSummary,
  CodeGraphError,
} from "@/lib/argus-search/graph-index-pack"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export const runtime = "nodejs"
const CODE_GRAPH_GET_CACHE_CONTROL =
  "private, max-age=60, stale-while-revalidate=300"
const CODE_GRAPH_POST_CACHE_CONTROL = "private, no-store"

const mapGraphErrorStatus = (code: CodeGraphError["code"]) => {
  if (code === "binary_missing") {
    return 503
  }

  if (code === "missing_index_pack") {
    return 404
  }

  return 502
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/code/graph",
    event: "api.code.graph.get",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      try {
        const summary = await getCodeGraphSummary()
        if (!summary) {
          return {
            status: 404,
            outcome: "not_found",
            response: NextResponse.json(
              { error: "Code graph index-pack not found. Refresh to build it." },
              { status: 404 },
            ),
          }
        }

        logger.set({
          indexRunId: summary.indexRunId,
          nodesEmitted: summary.stats.nodesEmitted,
          edgesEmitted: summary.stats.edgesEmitted,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json(
            { data: summary },
            {
              headers: {
                "cache-control": CODE_GRAPH_GET_CACHE_CONTROL,
              },
            },
          ),
        }
      } catch (error) {
        if (error instanceof CodeGraphError) {
          logger.set({
            graphErrorCode: error.code,
            graphErrorDetails: error.details,
          })

          return {
            status: mapGraphErrorStatus(error.code),
            outcome: "graph_failed",
            response: NextResponse.json({ error: error.message }, { status: mapGraphErrorStatus(error.code) }),
          }
        }

        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to read code graph summary." }, { status: 500 }),
        }
      }
    },
  })
}

export async function POST(request: Request) {

    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      try {
        const summary = await refreshCodeGraphSummary()

        logger.set({
          indexRunId: summary.indexRunId,
          nodesEmitted: summary.stats.nodesEmitted,
          edgesEmitted: summary.stats.edgesEmitted,
        })

        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json(
            { data: summary },
            {
              headers: {
                "cache-control": CODE_GRAPH_POST_CACHE_CONTROL,
              },
            },
          ),
        }
      } catch (error) {
        if (error instanceof CodeGraphError) {
          logger.set({
            graphErrorCode: error.code,
            graphErrorDetails: error.details,
          })

          return {
            status: mapGraphErrorStatus(error.code),
            outcome: "graph_failed",
            response: NextResponse.json({ error: error.message }, { status: mapGraphErrorStatus(error.code) }),
          }
        }

        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to refresh code graph summary." }, { status: 500 }),
        }
      }
    },
  })
}

