import { readFile } from 'node:fs/promises'

import { buildVectorChunks } from '@/lib/indexing/chunker'
import type {
  ArtifactStore,
  GitLabSource,
  VectorChunkRecord,
  VectorStore,
} from '@/lib/indexing/contracts'
import { embedVectorChunks } from '@/lib/indexing/embedder'
import { DEFAULT_MAX_FILE_SIZE_BYTES, classifySkipReason } from '@/lib/indexing/ignore'
import { prepareRepoWorkspace, type RepoWorkspace } from '@/lib/indexing/repo-workspace'
import {
  clearStagedChanges,
  loadExistingStates,
  stageDelete,
  stageUpsert,
} from '@/lib/indexing/staging'
import { sha256Hex } from '@/lib/utils/hash'

type SnapshotRunContext = {
  runId: string
  branchStateId: string
  integrationId: string
  configHash: string
  headSha: string
  artifactsPrefix: string
}

type SnapshotResult = {
  stats: Record<string, number>
}

type SnapshotProgressEvent = {
  stage: 'ingest'
  step: string
  message: string
  path?: string
  stats: Record<string, number>
  details?: Record<string, unknown>
}

const resolveMaxFileSizeBytes = () => {
  const raw = process.env.INDEXER_MAX_FILE_SIZE_BYTES
  if (!raw) {
    return DEFAULT_MAX_FILE_SIZE_BYTES
  }

  const parsed = Number.parseInt(raw, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return DEFAULT_MAX_FILE_SIZE_BYTES
  }

  return parsed
}

const toErrorMessage = (error: unknown) =>
  error instanceof Error ? error.message : 'Unexpected embedding failure.'

const wrapEmbeddingError = (args: {
  path: string
  chunks: Array<Omit<VectorChunkRecord, 'embedding'>>
  error: unknown
}) => {
  const maxChunk = args.chunks.reduce<{ chunkIndex: number; size: number } | null>(
    (largest, chunk) => {
      const size = chunk.content.length
      if (!largest || size > largest.size) {
        return {
          chunkIndex: chunk.chunkIndex,
          size,
        }
      }

      return largest
    },
    null,
  )

  const wrapped = new Error(
    `Embedding failed for ${args.path} (chunks=${args.chunks.length}, maxChunkChars=${maxChunk?.size ?? 0}): ${toErrorMessage(args.error)}`,
  )
  ;(wrapped as Error & { details?: Record<string, unknown> }).details = {
    stage: 'embedding',
    path: args.path,
    chunkCount: args.chunks.length,
    maxChunkChars: maxChunk?.size ?? 0,
    maxChunkIndex: maxChunk?.chunkIndex ?? null,
  }

  return wrapped
}

export const runSnapshotIngest = async (args: {
  run: SnapshotRunContext
  source: GitLabSource
  vectorStore: VectorStore
  artifactStore: ArtifactStore
  shouldAbort?: () => Promise<void>
  onProgress?: (event: SnapshotProgressEvent) => void
  workspace?: RepoWorkspace
}): Promise<SnapshotResult> => {
  const maxFileSizeBytes = resolveMaxFileSizeBytes()

  const stats = {
    filesScanned: 0,
    filesProcessed: 0,
    filesUnchanged: 0,
    filesIndexed: 0,
    filesSkipped: 0,
    filesDeleted: 0,
    chunksUpserted: 0,
    embeddingApiCalls: 0,
    embeddingFailures: 0,
    embeddingPromptTokens: 0,
    embeddingTotalTokens: 0,
    embeddingCostUsd: 0,
  }

const manifestLines: string[] = []
const changedFileLines: string[] = []

const existingByPath = await loadExistingStates(args.run.branchStateId)
const seenPaths = new Set<string>()

await clearStagedChanges(args.run.runId)
await args.shouldAbort?.()
let ownedWorkspace: RepoWorkspace | null = null
const workspace =
  args.workspace ??
  (await prepareRepoWorkspace({
    source: args.source,
    integrationId: args.run.integrationId,
    sha: args.run.headSha,
  }))
if (!args.workspace) {
  ownedWorkspace = workspace
}

const emitProgress = (event: Omit<SnapshotProgressEvent, 'stage' | 'stats'>) => {
  if (!args.onProgress) {
    return
  }

  args.onProgress({
    stage: 'ingest',
    ...event,
    stats: { ...stats },
  })
}

try {
  await args.shouldAbort?.()
  const relativeFiles = await workspace.listFiles()
  emitProgress({
    step: 'snapshot_scan_started',
    message: `Snapshot scan started (${relativeFiles.length} file(s)).`,
    details: {
      filesTotal: relativeFiles.length,
    },
  })

  for (const relativePath of relativeFiles) {
    await args.shouldAbort?.()
    if (!relativePath) {
      continue
    }

    stats.filesScanned += 1
    stats.filesProcessed += 1

    const content = await workspace.readFile(relativePath)
    const skipReason = classifySkipReason({
      relativePath,
      content,
      maxFileSizeBytes,
    })

if (skipReason) {
  stats.filesSkipped += 1
  emitProgress({
    step: 'file_skipped',
    message: `Skipped ${relativePath} (${skipReason}).`,
    path: relativePath,
    details: {
      skipReason,
    },
  })
  manifestLines.push(
    JSON.stringify({ path: relativePath, status: 'skipped', skipReason }),
  )

  if (existingByPath.has(relativePath)) {
    await stageDelete({
      runId: args.run.runId,
      path: relativePath,
      skipReason,
    })
    stats.filesDeleted += 1
  }

  seenPaths.add(relativePath)
  continue
}

const fileId = sha256Hex(content)
const existing = existingByPath.get(relativePath)
if (existing?.fileId === fileId) {
  stats.filesUnchanged += 1
  emitProgress({
    step: 'file_unchanged',
    message: `Unchanged ${relativePath}; reuse existing vectors.`,
    path: relativePath,
  })
  manifestLines.push(JSON.stringify({ path: relativePath, status: 'unchanged' }))
  seenPaths.add(relativePath)
  continue
}

const chunks = await buildVectorChunks({
  path: relativePath,
  content: content.toString('utf8'),
  configHash: args.run.configHash,
})

if (chunks.length === 0) {
  stats.filesSkipped += 1
  emitProgress({
    step: 'file_skipped',
    message: `Skipped ${relativePath} (no chunks).`,
    path: relativePath,
    details: {
      skipReason: 'no_chunks',
    },
  })
  manifestLines.push(
    JSON.stringify({ path: relativePath, status: 'skipped', skipReason: 'no_chunks' }),
  )

  if (existing) {
    await stageDelete({
      runId: args.run.runId,
      path: relativePath,
      skipReason: 'no_chunks',
    })
    stats.filesDeleted += 1
  }

  seenPaths.add(relativePath)
  continue
}

let embeddedChunks: VectorChunkRecord[]
try {
  embeddedChunks = await embedVectorChunks(chunks, {
    onTelemetry: (telemetry) => {
      stats.embeddingApiCalls += telemetry.requestCount
      stats.embeddingFailures += telemetry.failureCount
      stats.embeddingPromptTokens += telemetry.promptTokens
      stats.embeddingTotalTokens += telemetry.totalTokens
      stats.embeddingCostUsd += telemetry.costUsd ?? 0
    },
  })
} catch (error) {
  throw wrapEmbeddingError({
    path: relativePath,
    chunks,
    error,
  })
}
await args.vectorStore.upsertChunks({
  branchStateId: args.run.branchStateId,
  runId: args.run.runId,
  path: relativePath,
  fileId,
  chunks: embeddedChunks,
})

  await stageUpsert({
    runId: args.run.runId,
    path: relativePath,
    fileId,
    sizeBytes: content.length,
  })

  stats.filesIndexed += 1
  stats.chunksUpserted += embeddedChunks.length
  emitProgress({
    step: 'file_indexed',
    message: `Indexed ${relativePath} (${embeddedChunks.length} chunk(s)).`,
    path: relativePath,
    details: {
      chunks: embeddedChunks.length,
      changeType: existing ? 'modified' : 'added',
    },
  })
  manifestLines.push(
    JSON.stringify({
      path: relativePath,
      status: existing ? 'changed' : 'new',
      chunks: embeddedChunks.length,
    }),
  )
  changedFileLines.push(
    JSON.stringify({
      path: relativePath,
      changeType: existing ? 'modified' : 'added',
      fileId,
    }),
  )
  seenPaths.add(relativePath)
}

for (const [existingPath] of existingByPath) {
  await args.shouldAbort?.()
  if (seenPaths.has(existingPath)) {
    continue
  }

  await stageDelete({
    runId: args.run.runId,
    path: existingPath,
    skipReason: 'deleted',
  })

  stats.filesDeleted += 1
  emitProgress({
    step: 'file_deleted',
    message: `Deleted ${existingPath} from index state.`,
    path: existingPath,
  })
  changedFileLines.push(
    JSON.stringify({
      path: existingPath,
      changeType: 'deleted',
    }),
  )
}

await args.shouldAbort?.()

    await args.artifactStore.writeManifest({
      artifactsPrefix: args.run.artifactsPrefix,
      lines: manifestLines,
    })

    await args.artifactStore.writeChangedFiles({
      artifactsPrefix: args.run.artifactsPrefix,
      lines: changedFileLines,
    })

    await args.artifactStore.writeRunJson({
      artifactsPrefix: args.run.artifactsPrefix,
      run: {
        runId: args.run.runId,
        mode: 'snapshot',
        headSha: args.run.headSha,
        stats,
      },
    })
    emitProgress({
      step: 'snapshot_artifacts_written',
      message: 'Snapshot artifacts written.',
      details: {
        manifestLines: manifestLines.length,
        changedFiles: changedFileLines.length,
      },
    })

    return {
      stats,
    }
  } finally {
    if (ownedWorkspace) {
      await ownedWorkspace.cleanup()
    }
  }
}

import { describe, expect, test } from "bun:test"

import { buildAlphaAccessConfig, isAlphaAccessEmailAllowedForConfig } from "@/lib/alpha-access"

describe("alpha access gating", () => {
  test("allows all users when the gate is disabled", () => {
    const config = buildAlphaAccessConfig({
      enabled: "0",
      allowedEmails: "",
    })

    expect(isAlphaAccessEmailAllowedForConfig(config, null)).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "user@example.com")).toBe(true)
  })

  test("enforces exact email matches when the gate is enabled", () => {
    const config = buildAlphaAccessConfig({
      enabled: "1",
      allowedEmails: "alpha@example.com",
    })

    expect(isAlphaAccessEmailAllowedForConfig(config, "alpha@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "ALPHA@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "beta@example.com")).toBe(false)
  })

  test("supports domain allowlist entries", () => {
    const config = buildAlphaAccessConfig({
      enabled: "true",
      allowedEmails: "@example.com",
    })

    expect(isAlphaAccessEmailAllowedForConfig(config, "dev@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "dev@other.com")).toBe(false)
  })

  test("parses mixed separators for allowlist tokens", () => {
    const config = buildAlphaAccessConfig({
      enabled: "yes",
      allowedEmails: "one@example.com, two@example.com\n@company.com",
    })

    expect(isAlphaAccessEmailAllowedForConfig(config, "one@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "two@example.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "three@company.com")).toBe(true)
    expect(isAlphaAccessEmailAllowedForConfig(config, "three@elsewhere.com")).toBe(false)
  })
})

