test("downloads once, extracts once, and cleanup is idempotent", async () => {
  const archive = await createArchive({
    "src/a.ts": "export const a = 1\n",
    "README.md": "# Test\n",
  })

  try {
    const mod = await import(`@/lib/indexing/repo-workspace.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
    const downloadArchive = mock(async () => ({ archivePath: archive.archivePath }))

    const workspace = await mod.prepareRepoWorkspace({
      source: { downloadArchive } as never,
      integrationId: "integration-1",
      sha: "head-sha-1",
    })

    expect(downloadArchive).toHaveBeenCalledTimes(1)
    expect(workspace.archivePath).toBe(archive.archivePath)
    expect(workspace.rootDir.length).toBeGreaterThan(0)

    const files = await workspace.listFiles()
    expect(files).toContain("README.md")
    expect(files).toContain("src/a.ts")

    const file = await workspace.readFile("src/a.ts")
    expect(file.toString("utf8")).toContain("export const a = 1")

    await workspace.cleanup()
    await workspace.cleanup()

    await expect(access(archive.archiveRoot)).rejects.toBeDefined()
  } finally {
    await rm(archive.root, { recursive: true, force: true }).catch(() => {})
  }
})

  test("rejects traversal outside repository root", async () => {
    const archive = await createArchive({
      "src/a.ts": "export const a = 1\n",
    })

    try {
      const mod = await import(`@/lib/indexing/repo-workspace.ts?cacheBust=${Math.random().toString(36).slice(2)}`)
      const workspace = await mod.prepareRepoWorkspace({
        source: { downloadArchive: async () => ({ archivePath: archive.archivePath }) } as never,
        integrationId: "integration-1",
        sha: "head-sha-1",
      })

      try {
        await expect(workspace.readFile("../outside.txt")).rejects.toThrow(
          "Workspace path escapes repository root.",
        )
      } finally {
        await workspace.cleanup()
      }
    } finally {
      await rm(archive.root, { recursive: true, force: true }).catch(() => {})
    }
  })
})

import { NextResponse } from 'next/server'
import { z } from 'zod'

import { secureCompare } from '@/lib/gitlab/crypto'
import { gitlabEnv } from '@/lib/gitlab/env'
import { cleanupIndexArtifacts } from '@/lib/indexing/artifact-retention'
import { runWithApiRequestLog } from '@/lib/utils/logger'

const cleanupPayloadSchema = z.object({
  readyKeepPerBranch: z.number().int().positive().max(100).optional(),
  failedRetentionDays: z.number().int().positive().max(3650).optional(),
  supersededRetentionDays: z.number().int().positive().max(3650).optional(),
  maxTotalBytes: z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER).optional(),
  runScanLimit: z.number().int().positive().max(20_000).optional(),
  deleteLimit: z.number().int().positive().max(2_000).optional(),
})

const isAuthorizedRunnerRequest = (request: Request) => {
  const headerValue = request.headers.get('x-internal-runner-key')
  if (!headerValue) {
    return false
  }

  return secureCompare(headerValue, gitlabEnv.internalRunnerKey)
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: '/api/internal/indexing/cleanup',
    event: 'api.indexing.cleanup',
    handler: async ({ logger }) => {
      if (!isAuthorizedRunnerRequest(request)) {
        return {
          status: 401,
          outcome: 'unauthorized',
          response: NextResponse.json({ error: 'Unauthorized' }, { status: 401 }),
        }
      }

      const payload = await request.json().catch(() => ({}))
      const parsed = cleanupPayloadSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: 'invalid_request',
          response: NextResponse.json({ error: 'Invalid cleanup payload.' }, { status: 400 }),
        }
      }

      const summary = await cleanupIndexArtifacts(parsed.data)
      logger.set({
        summary,
      })

      return {
        status: 200,
        outcome: 'success',
        response: NextResponse.json({ data: summary }),
      }
    },
  })
}

