#![allow(dead_code)]

use std::collections::VecDeque;
use std::sync::{Arc, Condvar, Mutex};

use serde_json::Value;

use crate::core::cancel::CancelToken;

#[derive(Debug)]
pub enum StreamError {
  Cancelled,
  Closed,
  Fatal(String),
}

impl std::fmt::Display for StreamError {
  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    match self {
      StreamError::Cancelled => write!(f, "cancelled"),
      StreamError::Closed => write!(f, "closed"),
      StreamError::Fatal(message) => write!(f, "{message}"),
    }
  }
}

impl std::error::Error for StreamError {}

#[derive(Clone)]
pub struct StreamQueue {
  inner: Arc<StreamQueueInner>,
}

struct StreamQueueInner {
  state: Mutex<StreamState>,
  cv: Condvar,
  high_water_mark: usize,
  cancel: CancelToken,
}

struct StreamState {
  queue: VecDeque<Value>,
  closed: bool,
  error: Option<String>,
}

impl StreamQueue {
  pub fn new(high_water_mark: usize) -> Self {
    let high_water_mark = high_water_mark.max(1);
    Self {
      inner: Arc::new(StreamQueueInner {
        state: Mutex::new(StreamState {
          queue: VecDeque::new(),
          closed: false,
          error: None,
        }),
        cv: Condvar::new(),
        high_water_mark,
        cancel: CancelToken::new(),
      }),
    }
  }

  pub fn cancel_token(&self) -> CancelToken {
    self.inner.cancel.clone()
  }

pub fn cancel(&self) {
  self.inner.cancel.cancel();
  let mut guard = self
    .inner
    .state
    .lock()
    .unwrap_or_else(|poisoned| poisoned.into_inner());
  guard.closed = true;
  if guard.error.is_none() {
    guard.error = Some("cancelled".to_string());
  }
  self.inner.cv.notify_all();
}

pub fn close(&self, error: Option<String>) {
  let mut guard = self
    .inner
    .state
    .lock()
    .unwrap_or_else(|poisoned| poisoned.into_inner());
  guard.closed = true;
  if guard.error.is_none() {
    guard.error = error;
  }
  self.inner.cv.notify_all();
}

pub fn push_blocking(&self, value: Value) -> Result<(), StreamError> {
  if self.inner.cancel.is_cancelled() {
    return Err(StreamError::Cancelled);
  }

  let mut guard = self
    .inner
    .state
    .lock()
    .unwrap_or_else(|poisoned| poisoned.into_inner());

  while !guard.closed
    && !self.inner.cancel.is_cancelled()
    && guard.queue.len() >= self.inner.high_water_mark
  {
    guard = self
      .inner
      .cv
      .wait(guard)
      .unwrap_or_else(|poisoned| poisoned.into_inner());
  }

  if self.inner.cancel.is_cancelled() {
    return Err(StreamError::Cancelled);
  }
  if guard.closed {
    return Err(StreamError::Closed);
  }

  guard.queue.push_back(value);
  self.inner.cv.notify_all();
  Ok(())
}

  pub fn next_blocking(&self) -> Result<Option<Value>, StreamError> {
    let mut guard = self
      .inner
      .state
      .lock()
      .unwrap_or_else(|poisoned| poisoned.into_inner());

    loop {
      if let Some(item) = guard.queue.pop_front() {
        self.inner.cv.notify_all();
        return Ok(Some(item));
      }

      if guard.closed {
        if let Some(message) = guard.error.take() {
          if message == "cancelled" || self.inner.cancel.is_cancelled() {
            return Err(StreamError::Cancelled);
          }
          return Err(StreamError::Fatal(message));
        }
        return Ok(None);
      }

      if self.inner.cancel.is_cancelled() {
        guard.closed = true;
        guard.error = guard.error.take().or(Some("cancelled".to_string()));
        self.inner.cv.notify_all();
        continue;
      }

      guard = self
        .inner
        .cv
        .wait(guard)
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    }
  }
}

