      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => ({})),
      ])
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }
      const parsed = payloadSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid graph query payload." }, { status: 400 }),
        }
      }

try {
  if (parsed.data.kind === "edge-types") {
    const result = await getPersistedGraphEdgeTypes()
    return {
      status: 200,
      outcome: "success",
      response: NextResponse.json({ data: result }),
    }
  }

  if (parsed.data.kind === "neighborhood") {
    const result = await queryPersistedGraphNeighborhood({
      nodeId: parsed.data.nodeId,
      depth: parsed.data.depth,
      direction: parsed.data.direction,
      edgeTypes: parsed.data.edgeTypes,
      maxNodes: parsed.data.maxNodes,
      maxEdges: parsed.data.maxEdges,
    })
    logger.set({
      queryKind: "neighborhood",
      nodeCount: result.nodes.length,
      edgeCount: result.edges.length,
    })
    return {
      status: 200,
      outcome: "success",
      response: NextResponse.json({ data: result }),
    }
  }

  const result = await queryPersistedGraphImpactPreset({
    nodeId: parsed.data.nodeId,
    preset: parsed.data.preset,
    depth: parsed.data.depth,
    maxNodes: parsed.data.maxNodes,
    maxEdges: parsed.data.maxEdges,
  })
  logger.set({
    queryKind: "preset",
    preset: parsed.data.preset,
    nodeCount: result.nodes.length,
    edgeCount: result.edges.length,
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ data: result }),
  }
} catch (error) {

        if (error instanceof CodeGraphError) {
          logger.set({
            graphErrorCode: error.code,
            graphErrorDetails: error.details,
          })
          return {
            status: mapGraphErrorStatus(error.code),
            outcome: "graph_failed",
            response: NextResponse.json({ error: error.message }, { status: mapGraphErrorStatus(error.code) }),
          }
        }

        logger.set({ graphErrorCode: "unknown" })
        return {
          status: 500,
          outcome: "graph_failed",
          response: NextResponse.json({ error: "Failed to run graph query." }, { status: 500 }),
        }
      }
    },
  })
}

