describe("gitlab index run cancel route", () => {
  test("returns 202 and cancels an active run", async () => {
    const { POST, db, loggerContext } = await loadRouteModule({
      run: {
        id: "run-1",
        status: "indexing",
      },
    })

    const response = await POST(
      new Request(
        "http://localhost/api/gitlab/integrations/integration-1/index/runs/run-1/cancel",
        {
          method: "POST",
        },
      ),
      {
        params: Promise.resolve({ integrationId: "integration-1", runId: "run-1" }),
      },
    )

    const body = await response.json()

    expect(response.status).toBe(202)
    expect(body).toEqual({
      data: {
        runId: "run-1",
        status: "cancelled",
        cancelled: true,
        alreadyCancelled: false,
      },
    })
    expect(db.update).toHaveBeenCalledTimes(1)
    expect(loggerContext).toMatchObject({
      previousStatus: "indexing",
      runStatus: "cancelled",
      alreadyCancelled: false,
    })
  })

test("returns 200 when run is already cancelled", async () => {
  const { POST, db, loggerContext } = await loadRouteModule({
    run: {
      id: "run-1",
      status: "cancelled",
    },
  })

  const response = await POST(
    new Request(
      "http://localhost/api/gitlab/integrations/integration-1/index/runs/run-1/cancel",
      {
        method: "POST",
      },
    ),
    {
      params: Promise.resolve({ integrationId: "integration-1", runId: "run-1" }),
    },
  )

  const body = await response.json()

  expect(response.status).toBe(200)
  expect(body).toEqual({
    data: {
      runId: "run-1",
      status: "cancelled",
      cancelled: true,
      alreadyCancelled: true,
    },
  })
  expect(db.update).toHaveBeenCalledTimes(0)
  expect(loggerContext).toMatchObject({
    runStatus: "cancelled",
    alreadyCancelled: true,
  })
})

  test("returns 409 for terminal non-cancellable run", async () => {
    const { POST, db, loggerContext } = await loadRouteModule({
      run: {
        id: "run-1",
        status: "ready",
      },
    })

    const response = await POST(
      new Request(
        "http://localhost/api/gitlab/integrations/integration-1/index/runs/run-1/cancel",
        {
          method: "POST",
        },
      ),
      {
        params: Promise.resolve({ integrationId: "integration-1", runId: "run-1" }),
      },
    )

    const body = await response.json()

    expect(response.status).toBe(409)
    expect(body).toEqual({
      error: "Run is not cancellable from status 'ready'.",
    })
    expect(db.update).toHaveBeenCalledTimes(0)
    expect(loggerContext).toMatchObject({
      runStatus: "ready",
      alreadyCancelled: false,
      cancellable: false,
    })
  })

  test("returns 404 when run is missing", async () => {
    const { POST, db } = await loadRouteModule({ run: null })

    const response = await POST(
      new Request(
        "http://localhost/api/gitlab/integrations/integration-1/index/runs/run-1/cancel",
        {
          method: "POST",
        },
      ),
      {
        params: Promise.resolve({ integrationId: "integration-1", runId: "run-1" }),
      },
    )

    const body = await response.json()

    expect(response.status).toBe(404)
    expect(body).toEqual({ error: "Index run not found." })
    expect(db.update).toHaveBeenCalledTimes(0)
  })
})

