import type { ArtifactStore } from '@/lib/indexing/contracts'
import { createFsArtifactStore } from '@/lib/indexing/stores/artifact-store.fs'
import { createS3ArtifactStore } from '@/lib/indexing/stores/artifact-store.s3'

const resolveBackend = () => process.env.INDEXER_ARTIFACTS_BACKEND?.trim().toLowerCase() || 'fs'

export const createArtifactStore = (): ArtifactStore => {
  const backend = resolveBackend()
  if (backend === 's3') {
    return createS3ArtifactStore()
  }

  return createFsArtifactStore()
}

def main() -> None:
    package_root = pathlib.Path(__file__).resolve().parents[2]
    fixture_root = package_root / "fixtures" / "sample-repo"

    base_url, stop = start_server()
    try:
        indexer = Indexer(
            root=str(fixture_root),
            paths=["."],
            include=["*.ts"],
        )
        indexer.use_vectors(model="test-model", base_url=base_url, dimension=3, batch_size=1)

        for event in indexer.stream(high_water_mark=16):
            match event:
                case VectorBatch(records):
                    record = records[0]
                    chunk = record.chunk or {}
                    print(
                        {
                            "chunkId": record.chunk_id,
                            "hasChunk": bool(chunk),
                            "contentPreview": str(chunk.get("content", ""))[:40],
                        }
                    )
                    break
                case PipelineComplete(stats):
                    print({"ok": True, "files": stats.file_count, "durationSec": stats.duration})
    finally:
        stop()


if __name__ == "__main__":
    main()

import { eq } from 'drizzle-orm'

import { db } from '@/lib/db'
import {
  indexFileStates,
  indexRunFileChanges,
} from '@/lib/db/schema'

export type ExistingFileState = {
  path: string
  fileId: string
}

export const clearStagedChanges = async (runId: string): Promise<void> => {
  await db
    .delete(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, runId))
}

export const stageUpsert = async (args: {
  runId: string
  path: string
  fileId: string
  sizeBytes: number
}) => {
  const now = new Date()
  await db
    .insert(indexRunFileChanges)
    .values({
      runId: args.runId,
      path: args.path,
      changeType: 'upsert',
      fileId: args.fileId,
      sizeBytes: args.sizeBytes,
      skipReason: null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexRunFileChanges.runId, indexRunFileChanges.path],
      set: {
        changeType: 'upsert',
        fileId: args.fileId,
        sizeBytes: args.sizeBytes,
        skipReason: null,
        updatedAt: now,
      },
    })
}

export const stageDelete = async (args: {
  runId: string
  path: string
  skipReason?: string | null
}) => {
  const now = new Date()
  await db
    .insert(indexRunFileChanges)
    .values({
      runId: args.runId,
      path: args.path,
      changeType: 'delete',
      fileId: null,
      sizeBytes: null,
      skipReason: args.skipReason ?? null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexRunFileChanges.runId, indexRunFileChanges.path],
      set: {
        changeType: 'delete',
        fileId: null,
        sizeBytes: null,
        skipReason: args.skipReason ?? null,
        updatedAt: now,
      },
    })
}

export const loadExistingStates = async (branchStateId: string): Promise<Map<string, ExistingFileState>> => {
  const rows = await db
    .select({
      path: indexFileStates.path,
      fileId: indexFileStates.fileId,
    })
    .from(indexFileStates)
    .where(eq(indexFileStates.branchStateId, branchStateId))

  return new Map(rows.map((row) => [row.path, row]))
}

import { describe, expect, test } from "bun:test"

import {
  isOnboardingPath,
  isSettingsPath,
  isUnauthenticatedRouteAllowed,
} from "./layout.utils"

describe("app layout onboarding path detection", () => {
  test("matches onboarding routes only", () => {
    expect(isOnboardingPath("/onboarding")).toBe(true)
    expect(isOnboardingPath("/onboarding/tokens")).toBe(true)
    expect(isOnboardingPath("/onboarding/projects")).toBe(true)
    expect(isOnboardingPath("/onboarding/mrs")).toBe(true)

    expect(isOnboardingPath("/settings")).toBe(false)
    expect(isOnboardingPath("/repos/1")).toBe(false)
    expect(isOnboardingPath("/onboardingish")).toBe(false)
  })
})

describe("app layout settings path detection", () => {
  test("matches settings routes only", () => {
    expect(isSettingsPath("/settings")).toBe(true)
    expect(isSettingsPath("/settings/connections")).toBe(true)

    expect(isSettingsPath("/onboarding")).toBe(false)
    expect(isSettingsPath("/repos/1")).toBe(false)
    expect(isSettingsPath("/settings-ish")).toBe(false)
  })
})

describe("app layout unauthenticated route allowlist", () => {
  test("allows root and onboarding, blocks other app routes", () => {
    expect(isUnauthenticatedRouteAllowed("/")).toBe(true)
    expect(isUnauthenticatedRouteAllowed("/onboarding")).toBe(true)
    expect(isUnauthenticatedRouteAllowed("/onboarding/tokens")).toBe(true)

    expect(isUnauthenticatedRouteAllowed("/repos/1")).toBe(false)
    expect(isUnauthenticatedRouteAllowed("/settings")).toBe(false)
    expect(isUnauthenticatedRouteAllowed("/onboardingish")).toBe(false)
  })
})

