function parsePositiveInt(name: string, value: string | undefined, fallback: number): number {
  if (!value) return fallback
  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(`${name} must be a positive integer`)
  }
  return parsed
}

function parseOptionalPositiveInt(name: string, value: string | undefined): number | undefined {
  if (!value) return undefined
  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error(`${name} must be a positive integer`)
  }
  return parsed
}

function parseNonNegativeInt(name: string, value: string | undefined, fallback: number): number {
  if (!value) return fallback
  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed < 0) {
    throw new Error(`${name} must be a non-negative integer`)
  }
  return parsed
}

function resolveProjectPath(projectRoot: string, target: string): string {
  if (path.isAbsolute(target)) return target
  return path.join(projectRoot, target)
}

function avg(values: number[]): number {
  if (values.length === 0) return 0
  return values.reduce((sum, current) => sum + current, 0) / values.length
}

function min(values: number[]): number {
  if (values.length === 0) return 0
  return Math.min(...values)
}

function max(values: number[]): number {
  if (values.length === 0) return 0
  return Math.max(...values)
}

function percentile(values: number[], p: number): number {
  if (values.length === 0) return 0
  const sorted = [...values].sort((a, b) => a - b)
  const index = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1))
  return sorted[index]
}

function startEmbeddingServer(dimension: number): Promise<EmbeddingServer> {
  const server = http.createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/embeddings') {
      res.statusCode = 404
      res.end(JSON.stringify({ error: 'not found' }))
      return
    }

    const body = await new Promise<string>((resolve, reject) => {
      let raw = ''
      req.on('data', (chunk) => {
        raw += String(chunk)
      })
      req.on('end', () => resolve(raw))
      req.on('error', reject)
    })

    let inputCount = 1
    try {
      const parsed = JSON.parse(body) as { input?: unknown }
      inputCount = Array.isArray(parsed?.input) ? parsed.input.length : 1
    } catch {
      inputCount = 1
    }

    const base = Array.from({ length: dimension }, (_, idx) => (idx + 1) / (dimension + 1))
    const data = Array.from({ length: inputCount }, (_value, i) => ({
      embedding: base.map((entry) => Number((entry + i * 0.0001).toFixed(6))),
    }))

    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ data }))
  })

  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const address = server.address()
      const port = typeof address === 'object' && address ? address.port : 0
      resolve({
        baseUrl: `http://127.0.0.1:${port}`,
        close: () =>
          new Promise<void>((done) => {
            server.close(() => done())
          }),
      })
    })
  })
}

const args = parseArgs({
  options: {
    'project-root': { type: 'string' },
    store: { type: 'string' },
    results: { type: 'string' },
    query: { type: 'string' },
    'trace-symbol': { type: 'string' },
    iterations: { type: 'string' },
    warmup: { type: 'string' },
    'top-k': { type: 'string' },
    'embedding-provider': { type: 'string' },
    'vector-base-url': { type: 'string' },
    'vector-model': { type: 'string' },
    'vector-api-key': { type: 'string' },
    dimension: { type: 'string' },
    'mock-dimension': { type: 'string' },
    'no-vector': { type: 'boolean' },
    'no-clear-between': { type: 'boolean' },
  },
}).values

const projectRoot = path.resolve(args['project-root'] ?? packageRoot)
const storePath = resolveProjectPath(projectRoot, args.store ?? '.argus-search/dogfood/index.kite')
const resultsPath = resolveProjectPath(projectRoot, args.results ?? '.argus-search/benchmarks/dogfood-latest.json')

const iterations = parsePositiveInt('iterations', args.iterations, 3)
const warmup = parseNonNegativeInt('warmup', args.warmup, 1)
const topK = parsePositiveInt('top-k', args['top-k'], 5)
const configuredDimension = parseOptionalPositiveInt('dimension', args.dimension)
const mockDimension = parsePositiveInt('mock-dimension', args['mock-dimension'], 3)

const vectorEnabled = !args['no-vector']
const clearBetween = !args['no-clear-between']
const searchQuery = args.query ?? 'indexing pipeline'
const traceCandidates = args['trace-symbol'] ? [args['trace-symbol']] : ['run', 'add', 'main']

const embeddingProviderInput = (args['embedding-provider'] ?? 'openai').toLowerCase()
if (!['openai', 'mock', 'auto'].includes(embeddingProviderInput)) {
  throw new Error('embedding-provider must be one of: openai, mock, auto')
}

const vectorBaseUrl = args['vector-base-url'] ?? 'https://api.openai.com/v1'
const vectorModel = args['vector-model'] ?? 'text-embedding-3-small'
const vectorApiKey = (args['vector-api-key'] ?? process.env.OPENAI_API_KEY)?.trim()

const selectedEmbeddingProvider =
  !vectorEnabled
    ? 'none'
    : embeddingProviderInput === 'auto'
      ? vectorApiKey
        ? 'openai'
        : 'mock'
      : embeddingProviderInput

console.log(`Dogfood benchmark project root: ${projectRoot}`)
console.log(`KiteDB store: ${storePath}`)
console.log(`Iterations: ${iterations} (+${warmup} warmup), vector: ${vectorEnabled ? 'on' : 'off'}`)
if (vectorEnabled) {
  console.log(`Embedding provider mode: ${selectedEmbeddingProvider}`)
}

let embeddingServer: EmbeddingServer | null = null
if (selectedEmbeddingProvider === 'openai' && !vectorApiKey) {
  throw new Error(
    'OPENAI_API_KEY is required for embedding-provider=openai. Set OPENAI_API_KEY, pass --vector-api-key, or use --embedding-provider mock',
  )
}
if (selectedEmbeddingProvider === 'mock') {
  embeddingServer = await startEmbeddingServer(mockDimension)
  console.log(`Embedding provider endpoint: ${embeddingServer.baseUrl}`)
}

const vectorProvider =
  selectedEmbeddingProvider === 'openai'
    ? {
        kind: 'http',
        baseUrl: vectorBaseUrl,
        model: vectorModel,
        apiKey: vectorApiKey,
        ...(configuredDimension ? { dimension: configuredDimension } : {}),
      }
    : selectedEmbeddingProvider === 'mock'
      ? {
          kind: 'http',
          baseUrl: embeddingServer.baseUrl,
          model: 'dogfood-local-model',
          dimension: mockDimension,
        }
      : undefined

if (vectorProvider && selectedEmbeddingProvider === 'openai') {
  console.log(`Embedding provider endpoint: ${vectorProvider.baseUrl}`)
  console.log(`Embedding model: ${vectorProvider.model}`)
}

const indexOptions = {
  projectRoot,
  inputs: {
    paths: ['src', 'tests', 'examples', 'fixtures'],
    include: DEFAULT_INCLUDE,
    exclude: DEFAULT_EXCLUDE,
  },
  phases: {
    parse: true,
    graph: true,
    vector: vectorEnabled,
    scip: false,
    indexPack: false,
  },
  ...(vectorProvider ? { vector: { provider: vectorProvider } } : {}),
}

const runs: RunSummary[] = []

try {
  for (let pass = 0; pass < warmup + iterations; pass += 1) {
    const isWarmup = pass < warmup
    const clear = pass === 0 || clearBetween
    const started = performance.now()
    await indexToKiteDb(indexOptions, { path: storePath, clear })
    const durationMs = Number((performance.now() - started).toFixed(2))
    runs.push({ durationMs, clear })

    const label = isWarmup ? `warmup ${pass + 1}` : `run ${pass - warmup + 1}`
    console.log(`${label.padEnd(12)} ${durationMs.toFixed(2)} ms (clear=${clear})`)
  }

  let searchHitCount = 0
  if (vectorProvider) {
    const hits = await searchKiteDb({
      projectRoot,
      store: { path: storePath },
      query: searchQuery,
      topK,
      vectorProvider,
    })
    if (!Array.isArray(hits)) {
      throw new Error('searchKiteDb returned a non-array value')
    }
    searchHitCount = hits.length
    if (searchHitCount === 0) {
      throw new Error('searchKiteDb returned zero hits')
    }
  }

