  let traceCallers = 0
  let traceValidated = false
  let lastTraceError: unknown = null
  for (const candidate of traceCandidates) {
    try {
      const callers = await traceCallersKiteDb({
        projectRoot,
        store: { path: storePath },
        name: candidate,
        limit: 50,
      })
      if (!Array.isArray(callers)) {
