  const message = lastTraceError instanceof Error ? lastTraceError.message : String(lastTraceError ?? '')
  throw new Error(
    `traceCallersKiteDb failed for symbols: ${traceCandidates.join(', ')}${message ? ` (${message})` : ''}`,
  )
}

const warmupRuns = runs.slice(0, warmup)
const measured = runs.slice(warmup).map((run) => run.durationMs)
const storeSizeBytes = fs.existsSync(storePath) ? fs.statSync(storePath).size : 0

  console.log(`  trace: ${result.validation.traceSymbol} (${result.validation.traceCallers} callers)`)
  if (vectorProvider) {
    console.log(`  search hits: ${result.validation.searchHitCount}`)
  }
  console.log(`  store size: ${result.validation.storeSizeBytes} bytes`)
  console.log(`  report: ${resultsPath}`)
} finally {
  if (embeddingServer) {
    await embeddingServer.close()
  }
}

