import type { CodeChunk } from '@/lib/indexing/types'
import { createRequire } from 'node:module'

type ArgusSearchChunk = {
  id?: string
  content?: string
  kind?: string
  language?: string
  metadata?: unknown
}

type ChunkFileFn = (args: { filePath: string; content: string }) => ArgusSearchChunk[]

const requireFromModule = createRequire(import.meta.url)
let cachedChunkFile: ChunkFileFn | null | undefined

const fallbackChunkFile: ChunkFileFn = ({ filePath, content }) => [
  {
    id: `${filePath}#0`,
    content,
    kind: 'fallback',
    language: undefined,
    metadata: { fallback: true },
  },
]

const resolveChunkFile = (): ChunkFileFn => {
  if (cachedChunkFile !== undefined) {
    return cachedChunkFile ?? fallbackChunkFile
  }

  try {
    const moduleName = ['@argus', 'argus-search'].join('/')
    const argusSearch = requireFromModule(moduleName) as { chunkFile?: ChunkFileFn }
    cachedChunkFile = typeof argusSearch.chunkFile === 'function' ? argusSearch.chunkFile : null
  } catch {
    cachedChunkFile = null
  }

  return cachedChunkFile ?? fallbackChunkFile
}

export const chunkWithArgusSearch = async (
  path: string,
  content: string,
): Promise<CodeChunk[]> => {
  const chunkFile = resolveChunkFile()
  const chunks = chunkFile({ filePath: path, content })

  return chunks.map((chunk, chunkIndex) => ({
    chunkId: chunk.id || `${path}#${chunkIndex}`,
    chunkIndex,
    content: chunk.content ?? '',
    metadata: {
      kind: chunk.kind,
      language: chunk.language,
      ...(chunk.metadata && typeof chunk.metadata === 'object'
        ? { argusSearch: chunk.metadata as Record<string, unknown> }
        : {}),
    },
  }))
}

function unsupported() {
  throw new Error(
    '@argus/argus-search/agent: not available in browser environments. ' +
      'Run indexing and retrieval in Node.js/Python, or expose it via a service (MCP/HTTP).',
  )
}

