/* ── React Flow overrides ── */

/* Reset ALL node wrappers — custom nodes own their chrome */
.react-flow__node {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
  color: inherit !important;
}

/* Kill default selection outline — custom nodes handle their own */
.react-flow__node.selected,
.react-flow__node.selected:focus,
.react-flow__node.selected:focus-visible,
.react-flow__node:focus,
.react-flow__node:focus-visible,
.react-flow__node.selectable.selected,
.react-flow__node.selectable:focus,
.react-flow__node.selectable:focus-visible {
  box-shadow: none !important;
  outline: none !important;
}

/* Make handles always visible (not just when connecting) */
.react-flow__handle {
  pointer-events: all !important;
  cursor: crosshair;
  opacity: 1 !important;
}

/* Edge hover glow */
.react-flow__edge-path {
  stroke: rgba(216, 191, 123, 0.95) !important;
  stroke-width: 2.5 !important;
  opacity: 1 !important;
  fill: none;
  transition: stroke 0.2s ease;
}

.react-flow__edge:hover .react-flow__edge-path {
  stroke: rgba(236, 212, 148, 1) !important;
  filter: drop-shadow(0 0 4px rgba(236, 212, 148, 0.75));
}

/* Connection line while dragging */
.react-flow__connection-path {
  stroke: var(--primary) !important;
  stroke-width: 2;
  stroke-dasharray: 6 3;
}

import { NextResponse } from "next/server"
import { z } from "zod"

import { secureCompare } from "@/lib/gitlab/crypto"
import { gitlabEnv } from "@/lib/gitlab/env"
import { cleanupOldWebhookDeliveries } from "@/lib/gitlab/jobs"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const cleanupPayloadSchema = z.object({
  retentionDays: z.number().int().positive().max(365).optional(),
})

const isAuthorizedRunnerRequest = (request: Request) => {
  const headerValue = request.headers.get("x-internal-runner-key")
  if (!headerValue) {
    return false
  }
  return secureCompare(headerValue, gitlabEnv.internalRunnerKey)
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/internal/gitlab-jobs/cleanup",
    event: "api.gitlab.jobs.cleanup",
    handler: async ({ logger }) => {
      if (!isAuthorizedRunnerRequest(request)) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const payload = await request.json().catch(() => ({}))
      const parsed = cleanupPayloadSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid cleanup payload." }, { status: 400 }),
        }
      }

      const summary = await cleanupOldWebhookDeliveries(parsed.data.retentionDays)
      logger.set({
        summary,
      })
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: summary }),
      }
    },
  })
}

