use std::path::{Path, PathBuf};
use std::process::Command;

use super::binary_provider::ScipBinaryProvider;
use super::engine::{ScipArtifacts, ScipError, ScipIndexOptions, ScipProvider};
use super::indexers::default_indexer_commands_with_config;

const ALLOWED_COMMANDS: [&str; 7] = [
