#[derive(Debug, Clone)]
pub struct ScipIndexerCommand {
  pub language: String,
  pub command: String,
  pub args: Vec<String>,
  pub output_path: Option<PathBuf>,
  pub working_dir: Option<PathBuf>,
  pub env: HashMap<String, String>,
}

impl ScipIndexerCommand {
  pub fn new(language: impl Into<String>, command: impl Into<String>) -> Self {
    Self {
      language: language.into(),
      command: command.into(),
      args: Vec::new(),
      output_path: None,
      working_dir: None,
      env: HashMap::new(),
    }
  }
}

#[derive(Debug, Clone)]
pub struct ScipCliProvider {
  pub indexers: Vec<ScipIndexerCommand>,
}

impl ScipCliProvider {
  pub fn new(indexers: Vec<ScipIndexerCommand>) -> Self {
    Self { indexers }
  }

  pub fn from_default_indexers(options: &ScipIndexOptions) -> Self {
    let commands = default_indexer_commands_with_config(
      &options.project_root,
      &options.files,
      &options.indexer_config,
    );
    Self::new(commands)
  }
}

impl ScipProvider for ScipCliProvider {
  fn index(&self, options: &ScipIndexOptions) -> Result<ScipArtifacts, ScipError> {
    let mut output_paths = Vec::new();
    let data_dir = resolve_data_dir(options.project_root.as_path(), options.data_dir.as_deref());

    for indexer in &self.indexers {
      let output_path = resolve_output_path(indexer, &data_dir);
      run_indexer(indexer, options, &data_dir, &output_path)?;
      output_paths.push(output_path);
    }

    let provider = ScipBinaryProvider::new(output_paths);
    provider.index(options)
  }
}

fn resolve_data_dir(project_root: &Path, data_dir: Option<&Path>) -> PathBuf {
  data_dir
    .map(|value| value.to_path_buf())
    .unwrap_or_else(|| project_root.join(".argus-search"))
}

fn resolve_output_path(indexer: &ScipIndexerCommand, data_dir: &Path) -> PathBuf {
  indexer.output_path.clone().unwrap_or_else(|| {
    data_dir
      .join("scip")
      .join(&indexer.language)
      .join("index.scip")
  })
}

fn run_indexer(
  indexer: &ScipIndexerCommand,
  options: &ScipIndexOptions,
  data_dir: &Path,
  output_path: &Path,
) -> Result<(), ScipError> {
  validate_safe_indexer_command(&indexer.command)?;

  if let Some(parent) = output_path.parent() {
    std::fs::create_dir_all(parent)?;
  }

  let args = expand_args(&indexer.args, options, data_dir, output_path);
  let mut cmd = Command::new(&indexer.command);
  cmd.args(args);
  cmd.current_dir(
    indexer
      .working_dir
      .as_deref()
      .unwrap_or(options.project_root.as_path()),
  );
  for (key, value) in &indexer.env {
    cmd.env(key, value);
  }

  let status = cmd
    .status()
    .map_err(|err| ScipError::Provider(format!("failed to spawn {}: {err}", indexer.command)))?;

  if !status.success() {
    return Err(ScipError::Provider(format!(
      "scip indexer {} exited with status {}",
      indexer.command, status
    )));
  }

  if !output_path.exists() {
    return Err(ScipError::Provider(format!(
      "scip indexer {} did not produce {}",
      indexer.command,
      output_path.display()
    )));
  }

  Ok(())
}

fn env_flag_enabled(name: &str) -> bool {
  matches!(
    std::env::var(name),
    Ok(value) if matches!(value.as_str(), "1" | "true" | "TRUE" | "yes" | "YES")
  )
}

fn command_basename(command: &str) -> Option<&str> {
  Path::new(command)
    .file_name()
    .and_then(|value| value.to_str())
}

fn has_path_components(command: &str) -> bool {
  let path = Path::new(command);
  path.is_absolute() || path.components().count() > 1
}

fn resolve_from_path(command: &str) -> bool {
  let Some(path_value) = std::env::var_os("PATH") else {
    return false;
  };
  for dir in std::env::split_paths(&path_value) {
    let candidate = dir.join(command);
    if candidate.is_file() {
      return true;
    }
    #[cfg(windows)]
    {
      for ext in [".exe", ".cmd", ".bat"] {
        if dir.join(format!("{command}{ext}")).is_file() {
          return true;
        }
      }
    }
  }
  false
}

fn validate_safe_indexer_command(command: &str) -> Result<(), ScipError> {
  if env_flag_enabled(ALLOW_UNSAFE_SCIP_COMMANDS_ENV) {
    return Ok(());
  }
  if has_path_components(command) {
    return Err(ScipError::Provider(format!(
      "refusing path-based scip command {command}; use an allowlisted binary name from PATH (set {ALLOW_UNSAFE_SCIP_COMMANDS_ENV}=1 only for trusted local execution)"
    )));
  }
  let Some(command_name) = command_basename(command) else {
    return Err(ScipError::Provider(format!(
      "invalid scip command name: {command}"
    )));
  };
  if !ALLOWED_COMMANDS.contains(&command_name) {
    return Err(ScipError::Provider(format!(
      "refusing untrusted scip command {} (allowed: {}; set {ALLOW_UNSAFE_SCIP_COMMANDS_ENV}=1 only if you trust this command)",
      command_name,
      ALLOWED_COMMANDS.join(", ")
    )));
  }
  if !resolve_from_path(command_name) {
    return Err(ScipError::Provider(format!(
      "scip command {command_name} is allowlisted but was not found on PATH"
    )));
  }
  Ok(())
}

fn expand_args(
  args: &[String],
  options: &ScipIndexOptions,
  data_dir: &Path,
  output_path: &Path,
) -> Vec<String> {
  let mut expanded = Vec::new();
  let project_root = options.project_root.to_string_lossy();
  let data_dir = data_dir.to_string_lossy();
  let output_path = output_path.to_string_lossy();

  for arg in args {
    if arg == "{files}" {
      if options.files.is_empty() {
        continue;
      }
      expanded.extend(options.files.iter().cloned());
      continue;
    }
    let mut value = arg.clone();
    value = value.replace("{project_root}", project_root.as_ref());
    value = value.replace("{data_dir}", data_dir.as_ref());
    value = value.replace("{output}", output_path.as_ref());
    if value.contains("{files}") {
      value = value.replace("{files}", &options.files.join(","));
    }
    expanded.push(value);
  }

  expanded
}

