  fn safe_command_rejects_path_components() {
    assert!(validate_safe_indexer_command("./npx").is_err());
    assert!(validate_safe_indexer_command("/tmp/npx").is_err());
  }

  #[test]
  fn safe_command_rejects_non_allowlisted_command() {
    assert!(validate_safe_indexer_command("sh").is_err());
  }
}

