import http from 'node:http'
import path from 'node:path'
import process from 'node:process'
import readline from 'node:readline/promises'
import { fileURLToPath } from 'node:url'

import { indexStream } from '../../stream.js'

type ToolExecuteParams = { query: string; topK?: number }
type ChunkMatch = { score: number; filePath: string; chunkId: string; chunk: any }

function parseArgs(argv: string[]) {
  const out = new Map<string, string | true>()
  for (let idx = 0; idx < argv.length; idx += 1) {
    const arg = argv[idx]
    if (!arg.startsWith('--')) continue
    const key = arg.slice(2)
    const next = argv[idx + 1]
    if (!next || next.startsWith('--')) {
      out.set(key, true)
      continue
    }
    out.set(key, next)
    idx += 1
  }
  return out
}

function splitList(value: unknown) {
  if (!value) return []
  return String(value)
    .split(',')
    .map((entry) => entry.trim())
    .filter(Boolean)
}

function fnv1a32(input: string) {
  let hash = 0x811c9dc5
  for (let idx = 0; idx < input.length; idx += 1) {
    hash ^= input.charCodeAt(idx)
    hash = Math.imul(hash, 0x01000193)
  }
  return hash >>> 0
}

function l2Normalize(vector: Float32Array) {
  let sumSq = 0
  for (let idx = 0; idx < vector.length; idx += 1) sumSq += vector[idx] * vector[idx]
  const norm = Math.sqrt(sumSq) || 1
  for (let idx = 0; idx < vector.length; idx += 1) vector[idx] /= norm
  return vector
}

function embedText(text: string, dimension: number) {
  const vector = new Float32Array(dimension)
  const tokens = String(text)
    .toLowerCase()
    .split(/[^a-z0-9_]+/g)
    .filter((t) => t.length >= 2)

  for (const token of tokens) {
    const hash = fnv1a32(token)
    const slot = hash % dimension
    const sign = hash & 1 ? 1 : -1
    vector[slot] += sign
  }

  return l2Normalize(vector)
}

function dot(a: Float32Array, b: Float32Array) {
  const len = Math.min(a.length, b.length)
  let sum = 0
  for (let idx = 0; idx < len; idx += 1) sum += a[idx] * b[idx]
  return sum
}

function startEmbeddingServer({ dimension }: { dimension: number }) {
  const server = http.createServer(async (req, res) => {
    if (req.method !== 'POST' || req.url !== '/embeddings') {
      res.statusCode = 404
      res.end('not found')
      return
    }

    const body = await new Promise<string>((resolve, reject) => {
      let raw = ''
      req.on('data', (chunk) => (raw += String(chunk)))
      req.on('end', () => resolve(raw))
      req.on('error', reject)
    })

    let inputs = ['']
    try {
      const parsed = JSON.parse(body)
      if (Array.isArray(parsed?.input)) inputs = parsed.input.map((v: unknown) => String(v))
      else if (typeof parsed?.input === 'string') inputs = [parsed.input]
    } catch {
      inputs = ['']
    }

    const data = inputs.map((value) => ({ embedding: Array.from(embedText(value, dimension)) }))
    res.statusCode = 200
    res.setHeader('content-type', 'application/json')
    res.end(JSON.stringify({ data }))
  })

  return new Promise<{ url: string; close: () => Promise<void> }>((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      const address = server.address()
      const port = typeof address === 'object' && address ? address.port : 0
      resolve({
        url: `http://127.0.0.1:${port}`,
        close: () => new Promise((done) => server.close(() => done())),
      })
    })
  })
}

function createCodeSearchTool({ records, dimension }: { records: any[]; dimension: number }) {
  return {
    name: 'code_search',
    description: 'Semantic-ish search over indexed code chunks (demo uses hashed embeddings).',
    parameters: {
      type: 'object',
      additionalProperties: false,
      properties: {
        query: { type: 'string', description: 'Natural-language query' },
        topK: { type: 'integer', minimum: 1, maximum: 50, default: 5 },
      },
      required: ['query'],
    },
    async execute({ query, topK = 5 }: ToolExecuteParams): Promise<ChunkMatch[]> {
      const queryEmbedding = embedText(query, dimension)
      const scored = records
        .map((record) => ({
          score: dot(queryEmbedding, record.embedding),
          record,
        }))
        .sort((a, b) => b.score - a.score)
        .slice(0, topK)

      return scored.map(({ score, record }) => ({
        score,
        filePath: record.filePath,
        chunkId: record.chunkId,
        chunk: record.chunk,
      }))
    },
  }
}

const usage = `
Usage:
  bun examples/node/agent-rag.ts [--project-root /repo] [--paths src,lib] [--include "*.ts,*.tsx"] [--exclude node_modules,dist,.git]
  bun examples/node/agent-rag.ts --query "What does IndexStreamHandle.cancel do?" --once

Options:
  --project-root   Repo root (defaults to fixtures/sample-repo)
  --paths          Comma-separated input paths (default: <project-root>)
  --include        Comma-separated include globs (default: "*.ts")
  --exclude        Comma-separated exclude entries (default: "node_modules,dist,.git")
  --k              Top K results (default: 5)
  --dim            Embedding dimension for the demo provider (default: 256)
  --query          Single query (otherwise interactive)
  --once           Exit after answering --query
  --help           Show help
`

const args = parseArgs(process.argv.slice(2))
if (args.get('help')) {
  process.stdout.write(usage)
  process.exit(0)
}

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const packageRoot = path.join(__dirname, '..', '..')
const fixtureRoot = path.join(packageRoot, 'fixtures', 'sample-repo')

const projectRoot = String(args.get('project-root') ?? fixtureRoot)
const include = splitList(args.get('include') ?? '*.ts')
const exclude = splitList(args.get('exclude') ?? 'node_modules,dist,.git')
const paths = splitList(args.get('paths'))
const topK = Number(args.get('k') ?? 5) || 5
const dimension = Number(args.get('dim') ?? 256) || 256

const { url, close } = await startEmbeddingServer({ dimension })

const records: any[] = []

try {
  for await (const item of indexStream(
    {
      projectRoot,
      inputs: { paths: paths.length ? paths : [projectRoot], include, exclude },
      phases: { parse: true, graph: false, vector: true, scip: false, indexPack: false },
      vector: { provider: { kind: 'http', baseUrl: url, model: 'hash-v1', dimension } },
      hooks: { vectorBatch: 64 },
    },
    { highWaterMark: 16, emit: { vectorBatches: true, phaseEvents: true } },
  )) {
    if (item?.type === 'vector:batch') {
      for (const record of item.batch ?? []) {
        if (!record?.chunk) continue
        records.push({
          chunkId: String(record.chunkId),
          filePath: String(record.filePath),
          embedding: Float32Array.from(record.embedding ?? []),
          chunk: record.chunk,
        })
      }
    }
    if (item?.type === 'pipeline:complete') break
  }
} finally {
  await close()
}

const tool = createCodeSearchTool({ records, dimension })
process.stdout.write(
  `Indexed ${records.length} chunk embeddings from ${projectRoot}.\n` +
    `Tool contract: { name: "${tool.name}", parameters: ${JSON.stringify(tool.parameters)} }\n\n`,
)

async function printResults(query: string) {
  const results = await tool.execute({ query, topK })
  process.stdout.write(`query: ${query}\n\n`)
  for (const [idx, match] of results.entries()) {
    const preview = String(match.chunk?.content ?? '').slice(0, 240).trimEnd()
    process.stdout.write(
      `${idx + 1}. score=${match.score.toFixed(3)}  ${match.filePath}\n` +
        `${preview}${preview.length >= 240 ? '…' : ''}\n\n`,
    )
  }
}

const singleQuery = args.get('query')
if (singleQuery) {
  await printResults(String(singleQuery))
  if (args.get('once')) process.exit(0)
}

const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
try {
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const query = await rl.question('ask> ')
    if (!query.trim()) break
    await printResults(query)
  }
} finally {
  rl.close()
}

