import type { ArtifactStore } from '@/lib/indexing/contracts'

type S3Object = {
  Key?: string
  Size?: number
}

type ListObjectsPage = {
  Contents?: S3Object[]
  IsTruncated?: boolean
  NextContinuationToken?: string
}

type S3Module = {
  S3Client: new (config: Record<string, unknown>) => {
    send: (command: unknown) => Promise<unknown>
  }
  PutObjectCommand: new (input: Record<string, unknown>) => unknown
  ListObjectsV2Command: new (input: Record<string, unknown>) => unknown
  DeleteObjectsCommand: new (input: Record<string, unknown>) => unknown
}

const parseBoolean = (value: string | undefined) => value?.trim().toLowerCase() === 'true'

const trimSlashes = (value: string) => value.replace(/^\/+|\/+$/g, '')

const joinKey = (...parts: Array<string | null | undefined>) =>
  parts
    .map((part) => (part ? trimSlashes(part) : ''))
    .filter(Boolean)
    .join('/')

const ensureTrailingNewline = (value: string) => (value.endsWith('\n') ? value : `${value}\n`)

const resolveS3Bucket = () => {
  const bucket = process.env.INDEXER_S3_BUCKET?.trim() || process.env.AWS_S3_BUCKET?.trim()
  if (!bucket) {
    throw new Error('Missing INDEXER_S3_BUCKET (or AWS_S3_BUCKET) for S3 artifact store.')
  }
  return bucket
}

let s3ModulePromise: Promise<S3Module> | null = null

const loadS3Module = async (): Promise<S3Module> => {
  if (!s3ModulePromise) {
    s3ModulePromise = import('@aws-sdk/client-s3') as unknown as Promise<S3Module>
  }
  return s3ModulePromise
}

const resolveS3Client = async () => {
  const { S3Client } = await loadS3Module()
  return new S3Client({
    region: process.env.INDEXER_S3_REGION?.trim() || process.env.AWS_REGION?.trim() || 'us-east-1',
    endpoint: process.env.INDEXER_S3_ENDPOINT?.trim() || undefined,
    forcePathStyle: parseBoolean(process.env.INDEXER_S3_FORCE_PATH_STYLE),
    credentials:
      process.env.INDEXER_S3_ACCESS_KEY_ID?.trim() && process.env.INDEXER_S3_SECRET_ACCESS_KEY?.trim()
        ? {
            accessKeyId: process.env.INDEXER_S3_ACCESS_KEY_ID.trim(),
            secretAccessKey: process.env.INDEXER_S3_SECRET_ACCESS_KEY.trim(),
            sessionToken: process.env.INDEXER_S3_SESSION_TOKEN?.trim() || undefined,
          }
        : undefined,
  })
}

export class S3ArtifactStore implements ArtifactStore {
  private readonly clientPromise = resolveS3Client()
  private readonly bucket = resolveS3Bucket()
  private readonly keyPrefix = trimSlashes(process.env.INDEXER_S3_KEY_PREFIX?.trim() || '')

  private async putObject(args: {
    artifactsPrefix: string
    filename: string
    body: string
    contentType: string
  }) {
    const [client, { PutObjectCommand }] = await Promise.all([
      this.clientPromise,
      loadS3Module(),
    ])
    const key = joinKey(this.keyPrefix, args.artifactsPrefix, args.filename)
    await client.send(
      new PutObjectCommand({
        Bucket: this.bucket,
        Key: key,
        Body: args.body,
        ContentType: args.contentType,
      }),
    )
  }

async writeRunJson(args: { artifactsPrefix: string; run: unknown }): Promise<void> {
  await this.putObject({
    artifactsPrefix: args.artifactsPrefix,
    filename: 'run.json',
    body: ensureTrailingNewline(JSON.stringify(args.run, null, 2)),
    contentType: 'application/json',
  })
}

async writeManifest(args: { artifactsPrefix: string; lines: string[] }): Promise<void> {
  await this.putObject({
    artifactsPrefix: args.artifactsPrefix,
    filename: 'manifest.jsonl',
    body: args.lines.length > 0 ? `${args.lines.join('\n')}\n` : '',
    contentType: 'application/x-ndjson',
  })
}

async writeChangedFiles(args: { artifactsPrefix: string; lines: string[] }): Promise<void> {
  await this.putObject({
    artifactsPrefix: args.artifactsPrefix,
    filename: 'changed_files.jsonl',
    body: args.lines.length > 0 ? `${args.lines.join('\n')}\n` : '',
    contentType: 'application/x-ndjson',
  })
}

async describePrefix(args: {
  artifactsPrefix: string
}): Promise<{ bytes: number; objects: number }> {
  const [client, { ListObjectsV2Command }] = await Promise.all([
    this.clientPromise,
    loadS3Module(),
  ])
  const keyPrefix = joinKey(this.keyPrefix, args.artifactsPrefix)
  const prefix = keyPrefix ? `${keyPrefix}/` : ''
  let continuationToken: string | undefined
  let bytes = 0
  let objects = 0

  do {
    const page = (await client.send(
      new ListObjectsV2Command({
        Bucket: this.bucket,
        Prefix: prefix,
        ContinuationToken: continuationToken,
      }),
    )) as ListObjectsPage

    for (const object of page.Contents ?? []) {
      bytes += object.Size ?? 0
      if (object.Key) {
        objects += 1
      }
    }

    continuationToken = page.IsTruncated ? page.NextContinuationToken : undefined
  } while (continuationToken)

  return { bytes, objects }
}

  async deletePrefix(args: {
    artifactsPrefix: string
  }): Promise<{ bytes: number; objects: number }> {
    const [client, { DeleteObjectsCommand, ListObjectsV2Command }] = await Promise.all([
      this.clientPromise,
      loadS3Module(),
    ])
    const keyPrefix = joinKey(this.keyPrefix, args.artifactsPrefix)
    const prefix = keyPrefix ? `${keyPrefix}/` : ''
    let continuationToken: string | undefined
    let bytes = 0
    let objects = 0

    do {
      const page = (await client.send(
        new ListObjectsV2Command({
          Bucket: this.bucket,
          Prefix: prefix,
          ContinuationToken: continuationToken,
        }),
      )) as ListObjectsPage

      const keys = (page.Contents ?? []).flatMap((object) =>
        object.Key ? [{ Key: object.Key }] : [],
      )

      for (const object of page.Contents ?? []) {
        bytes += object.Size ?? 0
        if (object.Key) {
          objects += 1
        }
      }

      if (keys.length > 0) {
        await client.send(
          new DeleteObjectsCommand({
            Bucket: this.bucket,
            Delete: {
              Objects: keys,
              Quiet: true,
            },
          }),
        )
      }

      continuationToken = page.IsTruncated ? page.NextContinuationToken : undefined
    } while (continuationToken)

    return { bytes, objects }
  }
}

export const createS3ArtifactStore = () => new S3ArtifactStore()

