type AnalyticsSnapshot = {
  connectedProjects: number
  collaborators: number
  reviewsAllTime: number
  reviews30d: number
  reviewsPrevious30d: number
  findings30d: number
  findingsPrevious30d: number
  activeReviewers30d: number
  activeReviewersPrevious30d: number
  avgFindingsPerReview30d: number
  avgFindingsPerReviewPrevious30d: number
  projectsConnected30d: number
  projectsConnectedPrevious30d: number
  reviewTrend: ReviewTrendPoint[]
  topProjects: TopProjectPoint[]
  integrationStatus: Array<{ status: IntegrationStatus; count: number }>
}

type CardTrend = "up" | "down" | "flat"
type AnalyticsView = "overview" | "code-health" | "usage"
type AnalyticsPageProps = {
  searchParams: Promise<{
    tab?: string | string[]
  }>
}

const WINDOW_DAYS = 30
const TREND_DAYS = 90
const DAY_MS = 24 * 60 * 60 * 1000
const numberFormatter = new Intl.NumberFormat("en-US")

const pickFirst = (value: string | string[] | undefined) =>
  Array.isArray(value) ? value[0] : value

const resolveAnalyticsView = (value: string | undefined): AnalyticsView => {
  if (value === "code-health" || value === "usage") {
    return value
  }
  return "overview"
}

const toNumber = (value: unknown): number => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }
  if (typeof value === "bigint") {
    return Number(value)
  }
  if (typeof value === "string" && value.trim()) {
    const parsed = Number(value)
    return Number.isFinite(parsed) ? parsed : 0
  }
  return 0
}

const toUtcDateKey = (value: Date) => value.toISOString().slice(0, 10)

const normalizeProjectLabel = (value: string) => {
  const normalized = value.trim()
  if (normalized.length <= 36) {
    return normalized
  }
  return `${normalized.slice(0, 33)}...`
}

const formatMetric = (value: number, mode: "integer" | "decimal" = "integer") =>
  mode === "decimal" ? value.toFixed(1) : numberFormatter.format(Math.round(value))

const formatOptionalMetric = (value: number | null, decimals = 1) => {
  if (value === null) {
    return "n/a"
  }
  return value.toFixed(decimals)
}

const formatDeltaMetric = (value: number | null, decimals = 1, unit = "") => {
  if (value === null) {
    return "n/a"
  }
  const rounded = Number(value.toFixed(decimals))
  const signed = rounded > 0 ? `+${rounded.toFixed(decimals)}` : rounded.toFixed(decimals)
  return `${signed}${unit}`
}

const formatDuration = (value: number | null) => {
  if (value === null) {
    return "n/a"
  }
  if (value < 1000) {
    return `${value}ms`
  }
  return `${(value / 1000).toFixed(1)}s`
}

const normalizeFeatureLabel = (value: string) => {
  const normalized = value.trim() || "/"
  if (normalized.length <= 40) {
    return normalized
  }
  return `${normalized.slice(0, 37)}...`
}

const buildPercentDelta = (
  current: number,
  previous: number,
): { badge: string; trend: CardTrend; headline: string } => {
  if (current === 0 && previous === 0) {
    return {
      badge: "0%",
      trend: "flat",
      headline: "No change this period",
    }
  }

  if (previous === 0) {
    return {
      badge: "+100%",
      trend: "up",
      headline: "New activity this period",
    }
  }

  const delta = ((current - previous) / previous) * 100
  const rounded = Math.round(delta * 10) / 10
  if (rounded === 0) {
    return {
      badge: "0%",
      trend: "flat",
      headline: "Flat vs previous 30 days",
    }
  }

  return {
    badge: `${rounded > 0 ? "+" : ""}${rounded.toFixed(1)}%`,
    trend: rounded > 0 ? "up" : "down",
    headline: rounded > 0 ? "Trending up vs previous period" : "Down vs previous period",
  }
}

const buildReviewTrendSeries = (
  rows: Array<{ date: string; reviews: unknown; findings: unknown }>,
) => {
  const pointsByDate = new Map(
    rows.map((row) => [
      row.date,
      {
        reviews: toNumber(row.reviews),
        findings: toNumber(row.findings),
      },
    ]),
  )

  const now = new Date()
  const series: ReviewTrendPoint[] = []

  for (let offset = TREND_DAYS - 1; offset >= 0; offset -= 1) {
    const cursor = new Date(now)
    cursor.setUTCDate(now.getUTCDate() - offset)
    const date = toUtcDateKey(cursor)
    const values = pointsByDate.get(date)

    series.push({
      date,
      reviews: values?.reviews ?? 0,
      findings: values?.findings ?? 0,
    })
  }

  return series
}

const buildEmptySnapshot = (): AnalyticsSnapshot => ({
  connectedProjects: 0,
  collaborators: 0,
  reviewsAllTime: 0,
  reviews30d: 0,
  reviewsPrevious30d: 0,
  findings30d: 0,
  findingsPrevious30d: 0,
  activeReviewers30d: 0,
  activeReviewersPrevious30d: 0,
  avgFindingsPerReview30d: 0,
  avgFindingsPerReviewPrevious30d: 0,
  projectsConnected30d: 0,
  projectsConnectedPrevious30d: 0,
  reviewTrend: buildReviewTrendSeries([]),
  topProjects: [],
  integrationStatus: [
    { status: "active", count: 0 },
    { status: "degraded", count: 0 },
    { status: "disabled", count: 0 },
  ],
})

const integrationStatusVariant = (status: IntegrationStatus): "default" | "secondary" | "outline" => {
  if (status === "active") {
    return "default"
  }
  if (status === "degraded") {
    return "secondary"
  }
  return "outline"
}

const buildAnalyticsSnapshot = async (
  userId: string,
  integrationsInput?: AnalyticsIntegrationScope,
): Promise<AnalyticsSnapshot> => {
  const integrations = integrationsInput ?? (await loadAnalyticsIntegrationScope(userId))
  const integrationIds = integrations.map((integration) => integration.id)
  const now = new Date()
  const currentWindowStart = new Date(now.getTime() - WINDOW_DAYS * DAY_MS)
  const previousWindowStart = new Date(now.getTime() - WINDOW_DAYS * 2 * DAY_MS)
  const trendWindowStart = new Date(now.getTime() - TREND_DAYS * DAY_MS)

const integrationStatus: AnalyticsSnapshot["integrationStatus"] = [
  {
    status: "active",
    count: integrations.filter((integration) => integration.status === "active").length,
  },
  {
    status: "degraded",
    count: integrations.filter((integration) => integration.status === "degraded").length,
  },
  {
    status: "disabled",
    count: integrations.filter((integration) => integration.status === "disabled").length,
  },
]

const projectsConnected30d = integrations.filter(
  (integration) => integration.createdAt >= currentWindowStart,
).length
const projectsConnectedPrevious30d = integrations.filter(
  (integration) =>
    integration.createdAt >= previousWindowStart &&
    integration.createdAt < currentWindowStart,
).length

if (integrations.length === 0) {
  return {
    ...buildEmptySnapshot(),
    projectsConnected30d,
    projectsConnectedPrevious30d,
    integrationStatus,
  }
}

const scopeConditions = integrations.map((integration) =>
  and(
    eq(aiReviewRuns.instanceUrl, integration.instanceUrl),
    eq(aiReviewRuns.projectId, integration.projectId),
  ),
)
const scopeWhere = scopeConditions.length === 1 ? scopeConditions[0] : or(...scopeConditions)

const [
  [collaboratorCountRow],
  [allTimeReviewCountRow],
  [windowMetricsRow],
  reviewTrendRows,
  topProjectRows,
] = await Promise.all([

  db
    .select({
      date: sql<string>`to_char(date_trunc('day', ${aiReviewRuns.createdAt} at time zone 'utc'), 'YYYY-MM-DD')`,
      reviews: count(),
      findings: sql<number>`coalesce(sum(${aiReviewRuns.findingsCount}), 0)`,
    })
    .from(aiReviewRuns)
    .where(and(scopeWhere, gte(aiReviewRuns.createdAt, trendWindowStart)))
    .groupBy(sql`date_trunc('day', ${aiReviewRuns.createdAt} at time zone 'utc')`)
    .orderBy(sql`date_trunc('day', ${aiReviewRuns.createdAt} at time zone 'utc')`),
  db
    .select({
      instanceUrl: aiReviewRuns.instanceUrl,
      projectId: aiReviewRuns.projectId,
      reviews: count(),
    })
    .from(aiReviewRuns)
    .where(scopeWhere)
    .groupBy(aiReviewRuns.instanceUrl, aiReviewRuns.projectId)
    .orderBy(sql`count(*) desc`)
    .limit(8),
])

const projectNameByScope = new Map(
  integrations.map((integration) => [
    `${integration.instanceUrl}::${integration.projectId}`,
    integration.projectName,
  ]),
)

const topProjects: TopProjectPoint[] = topProjectRows.map((row) => {
  const projectName =
    projectNameByScope.get(`${row.instanceUrl}::${row.projectId}`) ?? row.projectId

  return {
    project: normalizeProjectLabel(projectName),
    reviews: toNumber(row.reviews),
  }
})

  return {
    connectedProjects: integrations.length,
    collaborators: toNumber(collaboratorCountRow?.value),
    reviewsAllTime: toNumber(allTimeReviewCountRow?.value),
    reviews30d: toNumber(windowMetricsRow?.reviewsCurrent),
    reviewsPrevious30d: toNumber(windowMetricsRow?.reviewsPrevious),
    findings30d: toNumber(windowMetricsRow?.findingsCurrent),
    findingsPrevious30d: toNumber(windowMetricsRow?.findingsPrevious),
    activeReviewers30d: toNumber(windowMetricsRow?.activeReviewersCurrent),
    activeReviewersPrevious30d: toNumber(windowMetricsRow?.activeReviewersPrevious),
    avgFindingsPerReview30d: toNumber(windowMetricsRow?.avgFindingsCurrent),
    avgFindingsPerReviewPrevious30d: toNumber(windowMetricsRow?.avgFindingsPrevious),
    projectsConnected30d,
    projectsConnectedPrevious30d,
    reviewTrend: buildReviewTrendSeries(reviewTrendRows),
    topProjects,
    integrationStatus,
  }
}

export default async function AnalyticsPage({
  searchParams,
}: AnalyticsPageProps) {
  const session = await getSession()

  if (!session?.user?.id) {
