class JiraRouteError extends Error {
  status: number

  constructor(message: string, status = 400) {
    super(message)
    this.status = status
  }
}

const optionalCredentialsSchema = z.object({
  baseUrl: z.string().optional(),
  email: z.string().optional(),
  token: z.string().optional(),
})

const actionSchema = z.discriminatedUnion("action", [
  z.object({
    action: z.literal("validate"),
    ...optionalCredentialsSchema.shape,
  }),
  z.object({
    action: z.literal("test-connection"),
    ...optionalCredentialsSchema.shape,
  }),
  z.object({
    action: z.literal("boards"),
    ...optionalCredentialsSchema.shape,
  }),
  z.object({
    action: z.literal("sprints"),
    ...optionalCredentialsSchema.shape,
    boardId: z.number().int().positive(),
  }),
  z.object({
    action: z.literal("issues"),
    ...optionalCredentialsSchema.shape,
    sprintId: z.number().int().positive(),
  }),
])

type JiraRequestCredentials = {
  baseUrl: string
  email: string
  token: string
}

const resolveRequestCredentials = async (
  userId: string,
  partial: {
    baseUrl?: string
    email?: string
    token?: string
  },
): Promise<JiraRequestCredentials> => {
  const baseUrlFromRequest = partial.baseUrl?.trim()
  const emailFromRequest = partial.email?.trim()
  const tokenFromRequest = partial.token?.trim()

  let stored = null
  if (!baseUrlFromRequest || !emailFromRequest || !tokenFromRequest) {
    stored = await getStoredJiraCredentials(userId)
  }

  const baseUrl = baseUrlFromRequest || stored?.baseUrl || ""
  const email = emailFromRequest || stored?.email || ""
  const token = tokenFromRequest || stored?.token || ""

  if (!baseUrl || !email || !token) {
    throw new JiraRouteError(
      "Jira credentials are required. Enter base URL, email, and API token, then run Save & Validate.",
      400,
    )
  }

  return { baseUrl, email, token }
}

export async function GET(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/jira",
    event: "api.jira.get",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const summary = await getStoredJiraCredentialSummary(userId)
      logger.set({
        hasCredentials: Boolean(summary),
      })
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({ data: summary }),
      }
    },
  })
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/jira",
    event: "api.jira.post",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => null),
      ])

      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const parsed = actionSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid Jira request payload." }, { status: 400 }),
        }
      }

      try {
        logger.set({
          action: parsed.data.action,
        })
        if (parsed.data.action === "validate") {
          const credentials = await resolveRequestCredentials(userId, parsed.data)
          const result = await validateJiraCredentials(credentials)

          if (result.isValid) {
            await upsertJiraCredentials(userId, credentials)
          }

          return {
            status: 200,
            outcome: "success",
            response: NextResponse.json({ data: result }),
          }
        }

        const credentials = await resolveRequestCredentials(userId, parsed.data)

        if (parsed.data.action === "test-connection") {
          const result = await testJiraConnection(credentials)
          return {
            status: 200,
            outcome: "success",
            response: NextResponse.json({ data: result }),
          }
        }

        if (parsed.data.action === "boards") {
          const boards = await listJiraBoards(credentials)
          return {
            status: 200,
            outcome: "success",
            response: NextResponse.json({ data: boards }),
          }
        }

        if (parsed.data.action === "sprints") {
          const sprints = await listJiraSprints({
            ...credentials,
            boardId: parsed.data.boardId,
          })
          return {
            status: 200,
            outcome: "success",
            response: NextResponse.json({ data: sprints }),
          }
        }

        const issues = await listJiraIssuesForSprint({
          ...credentials,
          sprintId: parsed.data.sprintId,
        })
        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: issues }),
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Jira request failed."
        const status = error instanceof JiraRouteError ? error.status : getJiraErrorStatus(error)
        return {
          status,
          outcome: "error",
          response: NextResponse.json({ error: message }, { status }),
        }
      }
    },
  })
}

